window.QURAN_TAFSIRS["tabari"] = {"1":{"1":"القول في تأويل ﴿بسم الله الرحمن الرحيم﴾\n\nالقول في تأويل قوله: ﴿بِسْمِ﴾ .\n\nقال أبو جعفر: إن الله تعالى ذكره وتقدَّست أسماؤه أدّب نبيه محمدًا ﷺ بتعليمه تقديمَ ذكر أسمائه الحسنى أمام جميع أفعاله، وتقدَّم إليه في وَصفه بها قبل جميع مُهمَّاته  ، وجعل ما أدّبه به من ذلك وعلَّمه إياه، منه لجميع خلقه سُنَّةً يستَنُّون بها  ، وسبيلا يتَّبعونه عليها، فبه افتتاح أوائل منطقهم  ، وصدور رسائلهم وكتبهم وحاجاتهم، حتى أغنت دلالة ما ظهر من قول القائل: \"بسم الله\"، على من بطن من مراده الذي هو محذوف.\n\nوذلك أن الباء من \"بسم الله\" مقتضية فعلا يكون لها جالبًا، ولا فعلَ معها ظاهرٌ، فأغنت سامعَ القائل \"بسم الله\" معرفتُه بمراد قائله، عن إظهار قائل ذلك مُرادَه قولا إذْ كان كل ناطق به عند افتتاحه أمرًا، قد أحضرَ منطقُه به -إمّا معه، وإمّا قبله بلا فصْلٍ- ما قد أغنى سامِعَه عن دلالةٍ شاهدةٍ على الذي من أجله افتتح قِيلَه به  . فصار استغناءُ سامع ذلك منه عن إظهار ما حذف منه، نظيرَ استغنائه - إذا سمع قائلا قيل له: ما أكلت اليوم؟ فقال: \"طعامًا\" - عن أن يكرّر المسئُولُ مع قوله \"طعامًا\"، أكلت، لما قد ظهر لديه من الدلالة على أن ذلك معناه  ، بتقدُّم مسألة السائل إياه عما أكل. فمعقول إذًا أنّ قول القائل إذا قال: \"بسم الله الرحمن الرحيم\" ثم افتتح تاليًا سورةً، أن إتباعه \"بسم الله الرحمن الرحيم\" تلاوةَ السورة، يُنبئ عن معنى قوله: \"بسم الله الرحمن الرحيم\" ومفهومٌ به أنه مريد بذلك: أقرأ بسم الله الرحمن الرحيم. وكذلك قوله: \"بسم الله\" عند نهوضه للقيام أو عند قعوده وسائر أفعاله، ينبئ عن معنى مراده بقوله \"بسم الله\"، وأنه أراد بقِيلِه \"بسم الله\"، أقوم باسم الله، وأقعد باسم الله. وكذلك سائر الأفعال.\n\nوهذا الذي قلنا في تأويل ذلك، هو معنى قول ابن عباس الذي:-\n\n١٣٨ - حدثنا به أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشرُ بن عُمَارة، قال: حدثنا أبو رَوْق، عن الضحّاك، عن عبد الله بن عباس، قال: إنَّ أول ما نزل به جبريلُ على محمد، قال: \"يا محمد، قُل: أستعيذ بالسميع العليم من الشيطان الرجيم\" ثم قال: \"قل بسم الله الرحمن الرحيم\". قال: قال له جبريل: قل بسم الله يا محمد، يقول: اقرأ بذكر الله ربك، وقم واقعد بذكر الله.\n\nقال أبو جعفر: فإن قال لنا قائل: فإن كان تأويلُ قوله \"بسم الله\" ما وصفتَ، والجالبُ الباءَ في \"بسم الله\" ما ذكرتَ، فكيف قيل \"بسم الله\"، بمعنى أقرأ باسم الله\"، أو أقوم أو أقعد باسم الله؟ وقد علمتَ أن كلَّ قارئٍ كتابَ الله، فبعَوْن الله وتوفيقه قراءتُه، وأن كل قائم أو قاعد أو فاعلٍ فعلا فبالله قيامُه وقعودُه وفعلُه. وهَلا - إذْ كان ذلك كذلك - قيل \"بسم الله الرحمن الرحيم\" ولم يَقُل \"بسم الله\"؟ فإن قول القائل: أقوم وأقعد بالله الرحمن الرحيم، أو أقرأ بالله - أوضحُ معنى لسامعه من قوله \"بسم الله\"، إذ كان قوله أقوم \"أقوم أو أقعد باسم الله\"، يوهم سامعَه أن قيامه وقعوده بمعنى غيرِ الله.\n\nقيل له، وبالله التوفيق: إن المقصودَ إليه من معنى ذلك غيرُ ما توهَّمته في نفسك. وإنما معنى قوله \"بسم الله\": أبدأ بتسمية الله وذكره قبل كل شيء، أو أقرأ بتسميتي اللهَ، أو أقوم وأقعد بتسميتي اللهَ وذكرِه - لا أنه يعني بقِيلِه \"بسم الله\": أقوم بالله، أو أقرأ بالله، فيكونَ قولُ القائل: أقرأ بالله، أو أقوم أو أقعد بالله - أولى بوجه الصواب في ذلك من قوله \"بسم الله\".\n\nفإن قال: فإن كان الأمر في ذلك على ما وصفتَ، فكيف قيل: \"بسم الله\" وقد علمتَ أنّ الاسم اسمٌ، وأن التسمية مصدرٌ من قولك سَمَّيت؟\n\nقيل: إن العربَ قد تخرج المصادرَ مبهمةً على أسماء مختلفة، كقولهم: أكرمتُ فلانًا كرامةً، وإنما بناءُ مصدر \"أفعلتُ\" - إذا أخرج على فعله - \"الإفعالُ\". وكقولهم: أهنت فلانًا هَوانًا، وكلّمته كلامًا. وبناء مصدر: \"فعَّلت\" التفعيل. ومن ذلك قول الشاعر:\n\nأَكُفْرًا بعد رَدِّ المَوْتِ عَنِّي ... وبعد عَطَائِكَ المِئَةَ الرِّتَاعَا\n\nيريد: إعطائك. ومنه قول الآخر:\n\nوَإن كانَ هذا البُخْلُ منْك سَجيةً ... لقد كُنْتُ في طَولِي رَجَاءكَ أَشْعَبَا\n\nيريد: في إطالتي رجاءك. ومنه قول الآخر:\n\nأَظُلَيْمُ إن مُصَابَكم رَجُلا ... أَهْدَى السّلامَ تحيَّةً ظُلْمُ\n\nيريد: إصابتكم. والشواهد في هذا المعنى تكثُرُ، وفيما ذكرنا كفاية، لمن وُفِّق لفهمه.\n\nفإذْ كان الأمر - على ما وصفنا، من إخراج العرب مصادرَ الأفعال على غير بناء أفعالها - كثيرًا، وكان تصديرها إياها على مخارج الأسماء موجودًا فاشيًا  ، فبيِّنٌ بذلك صوابُ ما قلنا من التأويل في قول القائل \"بسم الله\"، أن معناه في ذلك عند ابتدائه في فعل أو قول: أبدأ بتسمية الله، قبل فعلي، أو قبل قولي.\n\nوكذلك معنى قول القائل عند ابتدائه بتلاوة القرآن: \"بسم الله الرحمن الرحيم\"، إنما معناه: أقرأ مبتدئًا بتسمية الله، أو أبتدئ قراءتي بتسمية الله. فجُعِل \"الاسمُ\" مكان التسمية، كما جُعل الكلامُ مكان التكليم، والعطاءُ مكان الإعطاء.\n\nوبمثل الذي قلنا من التأويل في ذلك، رُوِي الخبر عن عبد الله بن عباس.\n\n١٣٩ - حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمَارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس، قال: أوّل ما نزل جبريل على محمد ﷺ قال: \"يا محمد، قل: أستعيذ بالسميع العليم من الشيطان الرجيم\"، ثم قال: \"قل: بسم الله الرحمن الرحيم\".\n\nقال ابن عباس: \"بسم الله\"، يقول له جبريلُ: يا محمد، اقرأ بذكر الله ربِّك، وقم واقعد بذكر الله.\n\nوهذا التأويل من ابن عباس ينبئ عن صحة ما قلنا - من أنه يراد بقول القائل مفتتحًا قراءته: \"بسم الله الرحمن الرحيم\": أقرأ بتسمية الله وذكره، وأفتتح القراءة بتسمية الله، بأسمائه الحسنى وصفاته العُلَى - ويوضح فسادَ قول من زعم أن معنى ذلك من قائله: بالله الرحمن الرحيم أوّلِ كلِّ شيء  ، مع أن العباد إنما أُمِروا أن يبتدئوا عند فواتح أمورِهم بتسمية الله، لا بالخبر عن عظمته وصفاته، كالذي أمِروا به من التسمية على الذبائح والصَّيد، وعند المَطعم والمَشرب، وسائر أفعالهم. وكذلك الذي أمِروا به من تسميته عند افتتاح تلاوة تنزيل الله، وصدور رسائلهم وكتبهم.\n\nولا خلاف بين الجميع من علماء الأمة، أن قائلا لو قال عند تذكيته بعض بهائم الأنعام  \"بالله\"، ولم يقل \"بسم الله\"، أنه مخالف - بتركه قِيلَ: \"بسم الله\" ما سُنَّ له عند التذكية من القول. وقد عُلم بذلك أنه لم يُرِدْ بقوله \"بسم الله\" \"بالله\"، كما قال الزاعم أن اسمَ الله في قول الله: \"بسم الله الرحمن الرحيم\" هو الله. لأن ذلك لو كان كما زعم، لوجب أن يكون القائل عند تذكيته ذبيحتَه \"بالله\"، قائلا ما سُنَّ له من القول على الذبيحة. وفي إجماع الجميع على أنّ قائلَ ذلك تارك ما سُنَّ له من القول على ذبيحته - إذْ لم يقل \"بسم الله\" - دليلٌ واضح على فساد ما ادَّعى من التأويل في قول القائل: \"بسم الله\"، أنه مراد به \"بالله\"، وأن اسم الله هو الله.\n\nوليس هذا الموضع من مواضع الإكثار في الإبانة عن الاسم: أهُوَ المسمى، أمْ غيرُه، أم هو صفة له؟ فنطيل الكتاب به، وإنما هذا موضع من مواضع الإبانة عن الاسم المضاف إلى الله: أهو اسمٌ، أم مصدر بمعنى التسمية  ؟ فإن قال قائل: فما أنت قائلٌ في بيت لبيد بن ربيعة:\n\nإلَى الحَوْلِ، ثم اسْمُ السَّلام عليكُمَا، ... ومن يَبْكِ حَوْلا كاملا فَقَد اعتَذَرْ\n\nفقد تأوله مُقدَّم في العلم بلغة العرب، أنه معني به: ثم السلام عليكما، وأن اسمَ السلام هو السلام؟\n\nقيل له: لو جاز ذلك وصح تأويله فيه على ما تأوّل، لجاز أن يقال: رأيتُ اسم زيد، وأكلتُ اسمَ الطعام، وشربتُ اسمَ الشراب؛ وفي إجماع جميع العرب على إحالة ذلك ما ينبئ عن فساد تأويل من تأول قول لبيد: \"ثمّ اسم السلام عليكما\"، أنه أراد: ثم السلام عليكما، وادِّعائه أن إدخال الاسم في ذلك وإضافتَه إلى السلام إنما جاز، إذْ كان اسم المسمَّى هو المسمَّى بعينه.\n\nويُسأل القائلون قولَ من حكينا قولَه هذا، فيقال لهم: أتستجيزون في العربية أن يقال: \"أكلتُ اسمَ العسل\"، يعني بذلك: أكلت العسل، كما جاز عندكم: اسم السلام عليك، وأنتم تريدون: السلامُ عليك؟\n\nفإن قالوا: نعم! خرجوا من لسان العرب، وأجازوا في لغتها ما تخطِّئه جميع العرب في لغتها. وإن قالوا: لا سئلوا الفرقَ بينهما: فلن يقولوا في أحدهما قولا إلا أُلزموا في الآخر مثله.\n\nفإن قال لنا قائل: فما معنى قول لبيد هذا عندك؟\n\nقيل له: يحتمل ذلك وجهين، كلاهما غير الذي قاله من حكينا قوله.\n\nأحدُهما: أن \"السلام\" اسمٌ من أسماء الله، فجائز أن يكون لبيد عنَى بقوله: \"ثم اسم السلام عليكما\"، ثم الزما اسمَ الله وذكرَه بعد ذلك، وَدَعَا ذكري والبكاءَ عليّ؛ على وجه الإغراء. فرفعَ الاسم، إذْ أخّر الحرفَ الذي يأتي بمعنى الإغراء.  وقد تفعَلُ العرب ذلك، إذا أخّرت الإغراء وقدمت المُغْرَى به، وإن كانت قد تنصبُ به وهو مؤخَّر. ومن ذلك قول الشاعر:\n\nيَا أَيُّها المائحُ دَلوِي دُونَكا! ... إني رأيتُ النَّاس يَحْمدُونَكا!\n\nفأغرَى ب \"دونك\"، وهي مؤخرة، وإنما معناه: دونَك دلوي. فذلك قول لبيد:\n\nإلى الحوْلِ، ثمَّ اسمُ السَّلامُ عَلَيْكُمَا *\n\nيعني: عليكما اسمَ السلام، أي: الزما ذكر الله ودعا ذكري والوجدَ بي، لأن من بكى حَوْلا على امرئ ميّت فقد اعتذر. فهذا أحد وجهيه.\n\nوالوجه الآخر منهما: ثم تسميتي اللهَ عليكما، كما يقول القائل للشيء يراه فيعجبه: \"اسم الله عليك\" يعوِّذه بذلك من السوء، فكأنه قال: ثم اسمُ الله عليكما من السوء، وكأنّ الوجه الأول أشبه المعنيين بقول لبيد.\n\nويقال لمن وجه بيت لبيد هذا إلى أنّ معناه: ثم السلام عليكما، أترَى ما قلنا - من هذين الوجهين - جائزًا، أو أحدهما، أو غيرَ ما قلتَ فيه؟\n\nفإن قال: لا! أبان مقدارَه من العلم بتصاريف وُجوه كلام العرب، وأغنى خصمه عن مناظرته.\n\nوإن قال: بَلَى!\n\nقيل له: فما برهانك على صحة ما ادَّعيت من التأويل أنه الصوابُ، دون الذي ذكرتَ أنه محتملُه - من الوجه الذي يلزمنا تسلميه لك؟ ولا سبيل إلى ذلك.\n\nوأما الخبر الذي:-\n\n١٤٠ - حدثنا به إسماعيل بن الفضل، قال: حدثنا إبراهيم بن العلاء بن الضحاك [وهو يلقب بزبريق] قال: حدثنا إسماعيل بن عياش، عن إسماعيل بن يحيى، عن ابن أبي مُليكة، عمن حدثه، عن ابن مسعود - ومِسْعَرِ بن كِدَام، عن عطية، عن أبي سعيد - قال: قال رسول الله ﷺ: \"إن عيسى ابن مريم أسلمته أمُّه إلى الكتَّاب ليعلِّمه، فقال له المعلم: اكتب \"بسم\" فقال له عيسى: وما \"بسم\"؟ فقال له المعلم: ما أدري! فقال عيسى: الباء بهاءُ الله، والسين: سناؤه، والميم: مملكته.  فأخشى أنْ يكون غلطًا من المحدِّث، وأن يكون أراد [ب س م] ، على سبيل ما يعلَّم المبتدئ من الصبيان في الكتّاب حروف أبي جاد، فغلط بذلك، فوصَله، فقال: \"بسم\"، لأنه لا معنى لهذا التأويل إذا تُلي \"بسم الله الرحمن الرحيم\"، على ما يتلوه القارئ في كتاب الله، لاستحالة معناه على المفهوم به عند جميع العرب وأهل لسانها، إذا حُمِل تأويله على ذلك.\n\nالقول في تأويل قوله جل ثناؤه: ﴿اللَّهِ﴾ .\n\nقال أبو جعفر: وأما تأويل قول الله تعالى ذكره \"الله\"، فإنه على معنى ما رُوي لنا عن عبد الله بن عباس-: هو الذي يَألَهه كل شيء، ويعبده كل خلْقٍ.\n\n١٤١ - وذلك أنّ أبا كريب حدثنا، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمَارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس، قال: \"الله\" ذو الألوهية والمَعْبودية على خلقه أجمعين.\n\nفإن قال لنا قائل: فهل لذلك في \"فعل ويفعل\" أصل كان منه بناءُ هذا الاسم؟\n\nقيل: أمّا سماعًا من العرب فلا ولكن استدلالا.\n\nفإن قال: وما دلّ على أن الألوهية هي العبادة، وأنّ الإله هو المعبود، وأنّ له أصلا في \"فعل ويفعل\".\n\nقيل: لا تمانع بين العرب في الحكم لقول القائل  - يصف رجلا بعبادة، وبطلب مما عند الله جل ذكره: \"تألَّه فلان\" - بالصحة ولا خلاف. ومن ذلك قول رؤبة بن العجاج:\n\nللهِ دَرُّ الغانِيات المُدَّهِ  سَبَّحْنَ واسْتَرْجَعْنَ مِن تَأَلُّهِي\n\nيعني: من تعبدي وطلبي اللهَ بعملي.\n\nولا شك أنّ \"التألُّه\"، التفعُّل من: \"ألَه يأله\"، وأن معنى \"أله\" - إذا نُطق به:- عَبَدَ اللهَ. وقد جاء منه مصدر يدل على أن العرب قد نطقت منه ب \"فعل يفعل\" يغير زيادة.\n\n١٤٢ - وذلك ما حدثنا به سفيان بن وكيع، قال حدثنا أبي، عن نافع بن عُمر، عن عَمرو بن دينار، عن ابن عباس: أنه قرأ ﴿وَيَذَرَكَ وإلاهَتَكَ﴾ [سورة الأعراف: ١٢٧] قال: عبادتَك، ويقال: إنه كان يُعبَد ولا يَعبُد.\n\n١٤٣ - حدثنا سفيان، قال: حدثنا ابن عُيينة، عن عمرو بن دينار، عن محمد بن عمرو بن الحسن، عن ابن عباس: ﴿وَيَذَرَكَ وَإلاهَتَك﴾ ، قال: إنما كان فرعونُ يُعبَد ولا يَعبُد\n\nوكذلك كان عبدُ الله يقرؤها ومجاهد.\n\n١٤٤ - حدثنا القاسم قال: حدثنا الحسين بن داود، قال: أخبرني حجاج، عن ابن جريج، عن مجاهد: قوله \"ويذرَكَ وإلاهتك\" قال: وعبادتَك  ولا شك أن الإلاهة - على ما فسره ابن عباس ومجاهد - مصدرٌ من قول القائل: ألَه اللهَ فلانٌ إلاهةً، كما يقال: عَبَد الله فلانٌ عبادةً، وعَبَرَ الرؤيا عبارةً. فقد بين قول ابن عباس ومجاهد هذا: أنّ \"أله\" عَبد، وأن \"الإلاهة\" مصدرُه.\n\nفإن قال: فإن كان جائزًا أن يقال لمن عبد الله: ألهه - على تأويل قول ابن عباس ومجاهد - فكيف الواجبُ في ذلك أن يقال، إذا أراد المخبر الخبرَ عن استيجاب الله ذلك على عَبْده؟ قيل: أما الروايةُ فلا رواية فيه عندنا، ولكن الواجب - على قياس ما جاء به الخبرُ عن رسول الله ﷺ الذي:-\n\n١٤٥ - حدثنا به إسماعيل بن الفضل، حدثنا إبراهيم بن العلاء، قال: حدثنا إسماعيل بن عياش، عن إسماعيل بن يحيى، عن ابن أبي مُليكة، عمن حدثه عن ابن مسعود - ومِسْعَر بن كِدَام، عن عطية العَوْفي، عن أبي سعيد - قال: قال رسول الله ﷺ: إنّ عيسى أسلمَتْه أمه إلى الكتّاب ليعلّمه فقال له المعلم اكتب \"الله\" فقال له عيسى: \"أتدري ما الله؟ الله إلهُ الآلهة  \".\n\n- أن يقال  ، الله جل جلاله ألَهَ العبدَ، والعبدُ ألَهَه. وأنْ يكون قولُ القائل \"الله\" - من كلام العرب أصله \"الإله\".\n\nفإن قال: وكيف يجوز أن يكون ذلك كذلك، مع اختلاف لفظيهما؟\n\nقيل: كما جاز أن يكون قوله: ﴿لكِنَّ هُوَ اللهُ رَبِّي﴾ [سورة الكهف: ٣٨] أصله: لكن أنا، هو الله ربي، كما قال الشاعر:\n\nوَتَرْمِينَنِي بالطَّرْف، أَيْ أَنتَ مُذْنبٌ ... وتَقْلينَني، لكِنَّ إياكِ لا أَقْلِي\n\nيريد: لكن أنا إياك لا أقلي، فحذَف الهمزة من \"أنا\" فالتقت نون \"أنا\" \"ونون \"لكنْ\" وهي ساكنة، فأدغمت في نون \"أنا\" فصارتا نونًا مشددة. فكذلك \"الله\" أصله \"الإله\"، أسقطت الهمزةُ التي هي فاء الاسم، فالتقت اللام التي هي عين الاسم، واللام الزائدة التي دخلت مع الألف الزائدة وهي ساكنة، فأدغمت في الأخرى التي هي عين الاسم، فصارتا في اللفظ لامًا واحدة مشددة، كما وصفنا من قول الله ﴿لكنَّ هوَ الله رَبي﴾ .\n\nالقول في تأويل قوله جل ثناؤه: ﴿الرَّحْمَنِ الرَّحِيمِ﴾ .\n\nقال أبو جعفر: وأما \"الرحمن\"، فهو فَعلان، من رَحم، و \"الرحيم\" فعيل منه. والعرب كثيرًا ما تبني الأسماء من \"فَعِل يفْعَل\" على \"فعلان\"، كقولهم من غَضِب: غَضبان، ومن سَكر: سكران، ومن عَطش: عطشان. فكذلك قولهم \"رَحمن\" من رَحِمَ، لأن \"فعِلَ\" منه: رَحم يرْحم. وقيل \"رحيم\"، وإن كانت عَين \"فعِل\" منها مكسورة، لأنه مدح. ومن شأن العرب أن يحملوا أبنية الأسماء - إذا كان فيها مدح أو ذم - على \"فعيل\"، وإن كانت عين \"فعل\" منها مكسورةً أو مفتوحةً، كما قالوا من \"علم\" عالم وعليم، ومن \"قدَر\" قادر وقدير. وليس ذلك منها بناء على أفعالها، لأن البناء من \"فَعِل يفْعَل\" و \"فعَل يفعِل\" فاعلٌ. فلو كان \"الرحمن والرحيم\" خارجين عن بناء أفعالهما لكانت صورتهما \"الراحم\".\n\nفإن قال قائل: فإذا كان الرحمن والرحيم اسمين مشتقين من الرحمة، فما وجهُ تكرير ذلك، وأحدهما مؤدٍّ عن معنى الآخر؟\n\nقيل له: ليس الأمر في ذلك على ما ظننتَ، بل لكل كلمة منهما معنى لا تؤدي الأخرى منهما عنها.\n\nفإن قال: وما المعنى الذي انفردت به كل واحدة منهما، فصارت إحداهما غير مؤدية المعنى عن الأخرى؟\n\nقيل: أما من جهة العربية، فلا تَمانُع  بين أهل المعرفة بلغات العرب، أنّ قول القائل: \"الرحمن\" - عن أبنية الأسماء من \"فَعِل يفعَل\" - أشدُّ عدولا من قوله \"الرّحيم\". ولا خلاف مع ذلك بينهم، أنّ كل اسم كان له أصل في \"فَعِلَ يفعَل\" - ثم كان عن أصله من \"فَعِل يفعَلُ\" أشد عدولا - أنّ الموصوف به مفضَّل على الموصوف بالاسم المبني على أصله من \"فَعِل يفعَل\"، إذا كانت التسمية به مدحًا أو ذمًّا. فهذا ما في قول القائل \"الرحمن\"، من زيادة المعنى على قوله \"الرحيم\" في اللغة.\n\nوأما من جهة الأثر والخبر، ففيه بين أهل التأويل اختلاف:-\n\n١٤٦ - فحدثني السري بن يحيى التميمي، قال: حدثنا عثمان بن زفر، قال: سمعت العَرْزَمي يقول: \"الرحمن الرحيم\"، قال: الرحمن بجميع الخلق، الرّحيم، قال: بالمؤمنين.\n\n١٤٧ - حدثنا إسماعيل بن الفضل، قال: حدثنا إبراهيم بن العلاء، قال: حدثنا إسماعيل بن عياش، عن إسماعيل بن يحيى، عن ابن أبي مُليكة، عمن حدثه، عن ابن مسعود - ومسعر بن كدام، عن عطية العَوفي، عن أبي سعيد - يعني الخدريّ - قال: قال رسول الله ﷺ: \"إنّ عيسى ابن مريم قال: الرحمن رَحمنُ الآخرة والدنيا، والرحيم رحيمُ الآخرة\".\n\nفهذان الخبران قد أنبآ عن فرق ما بين تسمية الله جل ثناؤه باسمه الذي هو \"رحمن\"، وتسميته باسمه الذي هو \"رحيم\"، واختلاف معنى الكلمتين - وإن اختلفا في معنى ذلك الفرق، فدلّ أحدهما على أنّ ذلك في الدنيا، ودلّ الآخر على أنه في الآخرة.\n\nفإن قال: فأي هذين التأويلين أولى عندك بالصحة؟ قيل: لجميعهما عندنا في الصحة مخرج، فلا وجه لقول قائل: أيُّهما أولى بالصحة؟ وذلك أنّ المعنى الذي في تسمية الله بالرحمن، دون الذي في تسميته بالرحيم: هو أنه بالتسمية بالرحمن موصوف بعموم الرحمة جميعَ خلقه، وأنه بالتسمية بالرحيم موصوف بخصوص الرحمة بعضَ خلقه، إما في كل الأحوال، وإما في بعض الأحوال. فلا شك - إذا كان ذلك كذلك - أنّ ذلك الخصوص الذي في وصفه بالرحيم لا يستحيل عن معناه، في الدنيا كان ذلك أو في الآخرة، أو فيهما جميعًا.\n\nفإذا كان صحيحًا ما قلنا من ذلك - وكان الله جل ثناؤه قد خصّ عباده المؤمنين في عاجل الدنيا بما لطف بهم من توفيقه إياهم لطاعته، والإيمان به وبرسله، واتباع أمره واجتناب معاصيه، مما خُذِل عنه من أشرك به، وكفر وخالف ما أمره به، وركب معاصيَه؛ وكان مع ذلك قد جعلَ، جَلَّ ثناؤه، ما أعد في آجل الآخرة في جناته من النعيم المقيم والفوز المبين، لمن آمن به، وصدّق رسله، وعمل بطاعته، خالصًا، دون من أشرك وكفر به -  كان بيِّنًا إن الله قد خص المؤمنين من رحمته في الدنيا والآخرة، مع ما قد عمَّهم به والكفارَ في الدنيا من الإفضال والإحسان إلى جميعهم، في البَسْط في الرزق، وتسخير السحاب بالغَيْثِ، وإخراج النبات من الأرض، وصحة الأجسام والعقول، وسائر النعم التي لا تُحصى، التي يشترك فيها المؤمنون والكافرون.\n\nفربُّنا جل ثناؤه رحمنُ جميع خلقه في الدنيا والآخرة، ورحيمُ المؤمنين خاصةً في الدنيا والآخرة. فأما الذي عمّ جميعَهم به في الدنيا من رحمته فكان رَحمانًا لهم به، فما ذكرنا مع نظائره التي لا سبيل إلى إحصائها لأحد من خلقه، كما قال جل ثناؤه: ﴿وَإِنْ تَعُدُّوا نِعْمَةَ الله لا تُحْصُوهَا﴾ [سورة إبراهيم: ٣٤، وسورة النحل: ١٨] .\n\nوأما في الآخرة، فالذي عمّ جميعهم به فيها من رحمته، فكان لهم رحمانًا، تسويته بين جميعهم جل ذكرُه في عَدله وقضائه، فلا يظلم أحدًا منهم مِثْقال ذَرّة، وإن تَكُ حسنةً يُضاعفها ويُؤتِ من لَدُنْهُ أجرًا عظيما، وتُوفَّى كُلُّ نَفْسٍ ما كَسَبَتْ. فذلك معنى عمومه في الآخرة جميعَهم برحمته، الذي كان به رحمانًا في الآخرة.\n\nوأما ما خص به المؤمنين في عاجل الدنيا من رحمته، الذي كان به رحيما لهم فيها، كما قال جل ذكره: ﴿وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا﴾ [سورة الأحزاب: ٤٣] فما وصفنا من اللطف لهم في دينهم، فخصّهم به، دونَ من خذَله من أهل الكفر به.\n\nوأمَّا ما خصّهم به في الآخرة، فكان به رحيما لهم دون الكافرين، فما وصفنا آنفًا مما أعدَّ لهم دون غيرهم من النعيم، والكرامة التي تقصرُ عنها الأمانيّ.\n\nوأما القول الآخر في تأويله فهو ما:-\n\n١٤٨ - حدثنا به أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس، قال: الرحمن، الفعلان من الرحمة، وهو من كلام العرب. قال: الرّحمن الرحيم: الرقيقُ الرفيقُ بمن أحبَّ أن يرحمه، والبعيد الشديد على من أحب أن يعنُف عليه.  وكذلك أسماؤه كلها.\n\nوهذا التأويل من ابن عباس، يدل على أن الذي به ربُّنا رحمن، هو الذي به رحيم، وإن كان لقوله \"الرحمن\" من المعنى، ما ليس لقوله \"الرحيم\". لأنه جعل معنى \"الرحمن\" بمعنى الرقيق على من رقَّ عليه، ومعنى \"الرحيم\" بمعنى الرفيق بمن رفق به.\n\nوالقول الذي رويناه في تأويل ذلك عن النبي ﷺ وذكرناه عن العرْزَمي  ، أشبه بتأويله من هذا القول الذي رويناه عن ابن عباس. وإن كان هذا القول موافقًا معناه معنى ذلك، في أن للرحمن من المعنى ما ليس للرحيم، وأن للرحيم تأويلا غيرَ تأويل الرحمن.\n\nوالقول الثالث في تأويل ذلك ما:-\n\n١٤٩ - حدثني به عمران بن بَكَّار الكلاعي، قال: حدثنا يحيى بن صالح، قال: حدثنا أبو الأزهر نصر بن عمرو اللَّخمي من أهلِ فلَسْطين، قال: سمعت عطاء الخراساني يقول: كان الرحمن، فلما اختزلَ الرحمن من اسمه كان الرحمنَ الرحيمَ.\n\nوالذي أراد، إن شاء الله، عطاءٌ بقوله هذا: أن الرحمن كان من أسماء الله التي لا يتسمَّى بها أحد من خَلْقِه، فلما تسمَّى به الكذابُ مسيلمة - وهو اختزاله إياه، يعني اقتطاعه من أسمائه لنفسه - أخبر الله جلّ ثناؤه أن اسمه \"الرحمنُ الرحيمُ\" ليفصِل بذلك لعباده اسمَهُ من اسم من قد تسمَّى بأسمائه، إذ كان لا يسمَّى أحد \"الرحمن الرحيم\"، فيجمع له هذان الاسمان، غيره جلّ ذكره. وإنما يتسمَّى بعضُ خَلْقه إما رحيما، أو يتسمَّى رَحمن. فأما \"رحمن رحيم\"، فلم يجتمعا قطّ لأحد سواهُ، ولا يجمعان لأحد غيره. فكأنّ معنى قول عطاء هذا: أن الله جل ثناؤه إنما فَصَل بتكرير الرحيم على الرحمن، بين اسمه واسم غيره من خلقِه، اختلف معناهما أو اتفقا.\n\nوالذي قال عطاءٌ من ذلك غيرُ فاسد المعنى، بل جائز أن يكون جلّ ثناؤه خصّ نفسه بالتسمية بهما معًا مجتمعين، إبانةً لها من خلقه، ليعرف عبادُه بذكرهما مجموعينِ أنه المقصود بذكرهما دون مَنْ سواه من خلقه، مع مَا في تأويل كل واحد منهما من المعنى الذي ليس في الآخر منهما.\n\nوقد زعم بعضُ أهل الغَباء أنّ العرب كانت لا تعرف \"الرحمن\"، ولم يكن ذلك في لغتها  ولذلك قال المشركون للنبي ﷺ: ﴿وَمَا الرَّحْمَنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا﴾ [سورة الفرقان: ٦٠] ، إنكارًا منهم لهذا الاسم، كأنه كان محالا عنده أن ينكر أهل الشرك ما كانوا عالمين بصحته، أوْ: لا وكأنه لم يتْلُ من كتاب الله قول الله ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ﴾ - يعني محمدًا - ﴿كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾ [سورة البقرة: ١٤٦] وهم مع ذلك به مكذِّبون، ولنبوته جاحدون! فيَعلمَ بذلك أنهم قد كانوا يدافعون حقيقةَ ما قد ثبت عندهم صحتُه، واستحكمتْ لديهم معرفتُه. وقد أنشد لبعض الجاهلية الجهلاء:\n\nأَلا ضربَتْ تلكَ الفتاةُ هَجِينَهَا ... أَلا قَضَبَ الرحْمَنُ رَبِّي يَمِينَهَا\n\nوقال سلامة بن جَندلٍ السَّعْدي:\n\nعَجِلْتُمْ عَلَيْنَا عَجْلَتَيْنَا عَلَيْكُمُ ... وَمَا يَشَإ الرحْمَنُ يَعْقِدْ وَيُطْلِقِ\n\nوقد زعم أيضًا بعضُ من ضعُفت معرفتُه بتأويل أهل التأويل، وقلَّت روايته لأقوال السلف من أهل التفسير، أنّ \"الرحمن\" مجازه: ذو الرحمة، و \"الرحيم\" مجازه: الرّاحم  ، ثم قال: قد يقدِّرون اللفظين من لفظٍ والمعنى واحد، وذلك لاتساع الكلام عندهم. قال: وقد فعلوا مثل ذلك فقالوا: ندمان ونَديم، ثم استشهد ببيتِ بُرْج بن مُسْهِر الطائي:\n\nوَنَدْمَانٍ يزيدُ الكأسَ طِيبًا، ... سَقَيْتُ وَقَدْ تَغَوَّرَتِ النُّجُومُ\n\nواستشهد بأبياتٍ نظائره في النَّديم والنَّدمان، ففرق بين معنى الرحمن والرحيم في التأويل لقوله: الرحمن ذو الرحمة، والرحيم الراحم، وإن كان قد ترك بيان تأويل معنيَيْهما على صحته. ثم مثّل ذلك باللَّفظين يأتيان بمعنى واحد، فعاد إلى ما قد جعله بمعنيين، فجعله مثال ما هو بمعنى واحد مع اختلاف الألفاظ.\n\nولا شك أن ذا الرحمة هو الذي ثَبت أن له الرحمة، وصحَّ أنها له صفة؛ وأن الراحم هو الموصوف بأنه سيرحم، أو قد رحم فانقضى ذلك منه، أو هو فيه.\n\nولا دلالة له فيه حينئذ أن الرحمة له صفة، كالدلالة على أنها له صفة، إذا وُصِف بأنه ذو الرحمة. فأين معنى \"الرحمن الرحيم\" على تأويله، من معنى الكلمتين يأتيان مقدَّرتين من لفظ واحد باختلاف الألفاظ واتفاق المعاني؟ ولكن القول إذا كان غير أصل معتمد عليه، كان واضحًا عوارُه.\n\nوإن قال لنا قائل: ولم قدّم اسمَ الله الذي هو \"الله\"، على اسمه الذي هو \"الرحمن\"، واسمه الذي هو \"الرحمن\"، على اسمه الذي هو \"الرحيم\"؟\n\nقيل: لأن من شأن العرب، إذا أرادوا الخبر عن مُخبَر عنه، أن يقدِّموا اسمه، ثم يتبعوه صفاتِه ونعوتَه. وهذا هو الواجب في الحُكم: أن يكون الاسم مقدَّمًا قبل نعته وصِفَته، ليعلم السامع الخبرَ، عمَّن الخبرُ. فإذا كان ذلك كذلك - وكانَ لله جلَّ ذكره أسماءٌ قد حرَّم على خلقه أن يتسمَّوا بها، خَصَّ بها نفسه دونهم، وذلك مثلُ \"الله\" و \"الرحمن\" و \"الخالق\"؛ وأسماءٌ أباحَ لهم أن يُسمِّيَ بعضهم بعضًا بها، وذلك: كالرحيم والسميع والبصير والكريم، وما أشبه ذلك من الأسماء - كان الواجب أن تقدَّم أسماؤه التي هي له خاصة دون جميع خلقه، ليعرف السامعُ ذلك مَنْ تَوجَّه إليه الحمد والتمجيدُ، ثم يُتبع ذلك بأسمائه التي قد تسمى بها غيره، بعد علم المخاطب أو السامع من توجَّه إليه ما يتلو ذلك من المعاني. فبدأ الله جل ذكره باسمه الذي هو \"الله\"، لأن الألوهية ليست لغيره جلّ ثناؤه من وجهٍ من الوجوه، لا من جهة التسمِّي به، ولا من جهة المعنى. وذلك أنا قد بينَّا أن معنى \"الله\" تعالى ذكره المعبود  ، ولا معبودَ غيرُه جل جلاله، وأن التسمِّي به قد حرّمه الله جل ثناؤه، وإن قصد المتسمِّي به ما يقصدُ المتسمِّي بسعيد وهو شقي، وبحسَنٍ وهو قبيح.\n\nأوَلا تَرى أنّ الله جلّ جلاله قال في غير آية من كتابه: ﴿أَإِلَهٌ مَعَ اللهِ﴾ فاستكبر ذلك من المقرِّ به، وقال تعالى في خُصوصه نَفسَه بالله وبالرحمن: ﴿قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ أَيًّا مَا تَدْعُوا فَلَهُ الأَسْمَاءُ الْحُسْنَى﴾ [سورة الإسراء: ١١٠] . ثم ثنَّى باسمه، الذي هو الرحمن، إذ كان قد مَنع أيضًا خلقه التسمي به، وإن كان من خلْقه من قد يستحق تسميته ببعض معانيه. وذلك أنه قد يجوز وصْف كثير ممّن هو دون الله من خلقه، ببعض صفات الرحمة. وغير جائز أن يستحق بعضَ الألوهية أحد دونه. فلذلك جاء الرحمن ثانيًا لاسمه الذي هو \"الله\".\n\nوأما اسمه الذي هو\"الرحيم\" فقد ذكرنا أنه مما هو جائز وصْف غيره به. والرحمة من صفاته جل ذكره، فكان - إذ كان الأمرُ على ما وصفنا - واقعًا مواقع نعوت الأسماء اللواتي هنّ توابعُها، بعد تقدم الأسماء عليها. فهذا وجه تقديم اسم الله الذي هو \"الله\"، على اسمه الذي هو \"الرحمن\"، واسمه الذي هو \"الرحمن\" على اسمه الذي هو \"الرحيم\".\n\nوقد كان الحسنُ البصريّ يقول في \"الرحمن\" مثل ما قلنا، أنه من أسماء الله التي مَنَعَ التسميَ بها العبادَ.\n\n١٥٠ - حدثنا محمد بن بشار، قال: حدثنا حماد بن مسعدة، عن عوف، عن الحسن، قال: \"الرحمن\" اسمٌ ممنوع.\n\nمع أن في إجماع الأمة من منع التسمِّي به جميعَ الناس، ما يُغني عن الاستشهاد على صحة ما قلنا في ذلك بقول الحسن وغيره.","2":"القول في تأويل فاتحة الكتاب\n\n﴿الْحَمْدُ لِلَّهِ﴾ :\n\nقال أبو جعفر: ومعنى ﴿الْحَمْدُ لِلَّهِ﴾ : الشكر خالصًا لله جل ثناؤه دون سائر ما يُعبد من دونه، ودون كلِّ ما برَأَ من خلقه  ، بما أنعم على عباده من النِّعم التي لا يُحصيها العدد، ولا يحيط بعددها غيره أحدٌ، في تصحيح الآلات لطاعته، وتمكين جوارح أجسام المكلَّفين لأداء فرائضه، مع ما بسط لهم في دنياهم من الرزق، وَغذَاهم به من نعيم العيش، من غير استحقاق منهم لذلك عليه، ومع ما نبَّههم عليه ودعاهم إليه، من الأسباب المؤدِّية إلى دوام الخلود في دار المُقام في النعيم المقيم. فلربِّنا الحمدُ على ذلك كله أولا وآخرًا.\n\nوبما ذكرنا من تأويل قول ربنا جلّ ذكره وتقدَّست أسماؤه: ﴿الْحَمْدُ لِلَّهِ﴾ ، جاء الخبرُ عن ابن عباس وغيره:-\n\n١٥١ - حدثنا محمد بن العلاء، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن ابن عباس، قال: قال جبريل لمحمد صلى الله عليهما: قل يا محمد \"الحمد لله \" قال ابن عباس: \"الحمد لله\": هو الشكر لله، والاستخذاء لله، والإقرار بنعمته وهدايته وابتدائه، وغير ذلك.\n\n١٥٢ - وحدثني سعيد بن عمرو السَّكُوني، قال: حدثنا بقية بن الوليد، قال: حدثني عيسى بن إبراهيم، عن موسى بن أبي حَبيب، عن الحكم بن عُمَير - وكانت له صحبة - قال: قال النبيُّ ﷺ: إذا قلت \"الحمد لله ربِّ العالمين\"، فقد شكرت الله، فزادك.  قال: وقد قيل: إنّ قول القائل \"الحمد لله\"، ثناء على الله بأسمائه وصفاته الحُسنى، وقوله: \"الشكر لله\"، ثناء عليه بنعمه وأياديه.\n\nوقد رُوي عن كعب الأحبار أنه قال: \"الحمد لله\"، ثناءٌ على الله. ولم يبيّن في الرواية عنه، من أي معنيي الثناء اللذين ذكرنا ذلك.\n\n١٥٣ - حدثنا يونس بن عبد الأعلى الصَّدَفي، قال: أنبأنا ابن وهب، قال: حدثني عمر بن محمد، عن سهيل بن أبي صالح، عن أبيه، قال: أخبرني السلولي، عن كعب، قال: من قال \"الحمد لله\"، فذلك ثناء على الله.\n\n١٥٤ - حدثني علي بن الحسن الخرّاز، قال: حدثنا مسلم بن عبد الرحمن الجَرْمي، قال: حدثنا محمد بن مصعب القُرْقُساني، عن مُبارك بن فَضالة، عن الحسن، عن الأسود بن سريع: أن النبي ﷺ قال: ليس شيءٌ أحبَّ إليه الحمد، من الله تعالى، ولذلك أثنى على نَفسه فقال: \"الحمد لله\"  .\n\nقال أبو جعفر: ولا تَمانُع بين أهل المعرفة بلغات العرب من الحُكْم  ، لقول القائل: \"الحمد لله شكرًا\" - بالصحة. فقد تبيّن - إذْ كان ذلك عند جميعهم صحيحًا - أنّ الحمد لله قد يُنطق به في موضع الشكر، وأن الشكر قد يوضع موضعَ الحمد. لأن ذلك لو لم يكن كذلك، لما جاز أن يُقال \"الحمد لله شكرًا\"، فيُخْرِج من قول القائل \"الحمد لله\" مُصَدَّرَ: \"أشكُرُ\"، لأن الشكر لو لم يكن بمعنى الحمد، كان خطأ أن يُصَدَّرَ من الحمد غيرُ معناه وغير لفظه.\n\nفإن قال لنا قائل: وما وجه إدخال الألف واللام في الحمد؟ وهلا قيل: حمدًا لله رب العالمين؟\n\nقيل: إن لدخول الألف واللام في الحمد، معنى لا يؤديه قول القائل \"حَمْدًا\"، بإسقاط الألف واللام. وذلك أن دخولهما في الحمد مُنْبِئٌ عن أن معناه  : جميعُ المحامد والشكرُ الكامل لله. ولو أسقطتا منه لما دَلّ إلا على أنّ حَمْدَ قائلِ ذلك لله، دون المحامد كلها. إذْ كان معنى قول القائل: \"حمدًا لله\" أو \"حمدٌ لله\": أحمد الله حمدًا، وليس التأويل في قول القائل: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، تاليًا سورةَ أم القرآن: أحمدُ الله، بل التأويلُ في ذلك ما وصفنا قبلُ، من أنّ جميع المحامد لله بألوهيّته وإنعامه على خلقه بما أنعم به عليهم من النعم التي لا كِفاء لها في الدين والدنيا، والعاجل والآجل.\n\nولذلك من المعنى، تتابعتْ قراءة القرّاء وعلماء الأمة على رَفع الحمد من ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ دون نصبها، الذي يؤدي إلى الدلالة على أن معنى تاليه كذلك: أحمد الله حمدًا. ولو قرأ قارئ ذلك بالنصب، لكان عندي مُحيلا معناه، ومستحقًّا العقوبةَ على قراءته إياه كذلك، إذا تعمَّد قراءتَه كذلك، وهو عالم بخطئه وفساد تأويله.\n\nفإن قال لنا قائل: وما معنى قوله \"الحمد لله\"؟ أحَمِد الله نفسه جلّ ثناؤه فأثنى عليها، ثم علَّمنَاه لنقول ذلك كما قال ووصَف به نفسه؟ فإن كان ذلك كذلك، فما وجه قوله تعالى ذكره إذًا ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ وهو عزّ ذكرُه معبودٌ لا عابدٌ؟ أم ذلك من قِيلِ جبريلَ أو محمدٍ رَسول الله ﷺ؟ فقد بَطل أن يكون ذلك لله كلامًا.\n\nقيل: بل ذلك كله كلام الله جل ثناؤه، ولكنه جلّ ذكره حَمِد نفسه وأثنى عليها بما هو له أهلٌ، ثم علَّم ذلك عباده، وفرض عليهم تلاوته، اختبارًا منه لهم وابتلاءً، فقال لهم قولوا: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، وقولوا: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ . فقوله ﴿إِيَّاكَ نَعْبُدُ﴾ مما علمهم جلّ ذكره أن يقولوه ويَدينُوا له بمعناه، وذلك موصول بقوله: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، وكأنه قال: قولوا هذا وهذا.\n\nفإن قال: وأين قوله: \"قولوا\"، فيكونَ تأويلُ ذلك ما ادَّعَيْتَ؟\n\nقيل: قد دللنا فيما مضى أن العرب من شأنها - إذا عرفتْ مكان الكلمة، ولم تَشكَّك أنّ سامعها يعرف، بما أظهرت من منطقها، ما حذفت -  حذفُ ما كفى منه الظاهرُ من منطقها، ولا سيما إن كانت تلك الكلمة التي حُذفت، قولا أو تأويلَ قولٍ، كما قال الشاعر:\n\nوأَعْلَمُ أَنَّنِي سَأَكُونُ رَمْسًا ... إذَا سَارَ النَّوَاعِجُ لا يَسِيرُ\n\nفَقَالَ السّائلون لِمَنْ حَفَرْتُمْ؟ ... فَقَالَ المُخْبِرُون لَهُمْ: وزيرُ\n\nقال أبو جعفر: يريد بذلك، فقال المخبرون لهم: الميِّتُ وزيرٌ، فأسقَط الميت، إذ كان قد أتى من الكلام بما دلّ على ذلك. وكذلك قول الآخر:\n\nوَرأَيتِ زَوْجَكِ في الوغَى ... مُتَقَلِّدًا سَيْفًا وَرُمْحَا\n\nوقد علم أنّ الرمح لا يُتَقَلَّد، وإنما أراد: وحاملا رمحًا، ولكن لما كان معلومًا معناه، اكتفى بما قد ظَهر من كلامه، عن إظهار ما حذف منه. وقد يقولون للمسافر إذا ودَّعوه: \"مُصاحَبًا مُعافًى\"، يحذفون \"سر، واخرج\"، إذ كان معلومًا معناه، وإن أسقط ذكره.\n\nفكذلك ما حُذف من قول الله تعالى ذكره: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، لمَّا عُلم بقوله جل وعزّ: ﴿إيّاكَ نَعبُد﴾ ما أراد بقوله: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، من معنى أمره عبادَه، أغنتْ دلالةُ ما ظُهِر عليه من القول عن إبداء ما حُذف.\n\nوقد روينا الخبرَ الذي قدمنا ذكره مبتَدأ في تأويل قول الله:  ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، عن ابن عباس، وأنه كان يقول: إن جبريل قال لمحمد: قل يا محمد: \"الحمد لله رب العالمين\"، وبيّنا أن جبريل إنما علّم محمدًا ما أُمِر بتعليمه إياه  . وهذا الخبر يُنبئ عن صحة ما قلنا في تأويل ذلك.\n\n* *\n\nالقول في تأويل قوله: ﴿رَبِّ﴾ .\n\nقال أبو جعفر: قد مضى البيان عن تأويل اسم الله الذي هو \"الله\"، في \"بسم الله\"، فلا حاجة بنا إلى تكراره في هذا الموضع.\n\nوأما تأويل قوله ﴿رَبِّ﴾ ، فإن الرّب في كلام العرب منصرفٌ على معان: فالسيد المطاع فيها يدعَى ربًّا، ومن ذلك قول لَبِيد بن ربيعة:\n\nوأَهْلكْنَ يومًا ربَّ كِنْدَة وابنَه ... ورَبَّ مَعدٍّ، بين خَبْتٍ وعَرْعَرِ\n\nيعني بربِّ كندة: سيِّد كندة. ومنه قول نابغة بني ذُبيان:\n\nتَخُبُّ إلى النُّعْمَانِ حَتَّى تَنالَهُ ... فِدًى لكَ من رَبٍّ طَرِيفِي وَتَالِدِي\n\nوالرجل المصلح للشيء يُدعى ربًّا، ومنه قول الفرزدق بن غالب:\n\nكانُوا كَسَالِئَةٍ حَمْقَاءَ إذْ حَقَنتْ ... سِلاءَها فِي أدِيم غَيْرِ مَرْبُوبِ\n\nيعني بذلك: في أديم غير مُصلَحٍ. ومن ذلك قيل: إن فلانًا يَرُبُّ صنيعته عند فلان؛ إذا كان يحاول إصلاحها وإدامتها، ومن ذلك قول علقمة بن عَبَدة:\n\nفكُنْتَ امرَأً أَفْضَتْ إليك رِبَابَتي ... وَقَبْلَكَ رَبَّتْني، فَضِعْتُ رُبُوبُ\n\nيعنى بقوله: \"أفضتْ إليك\" أي وصلتْ إليك رِبَابتي، فصرتَ أنت الذي ترُبُّ أمري فتصلحه، لمّا خرجتُ من ربابة غيرك من الملوك الذين كانوا قبلك عليّ  ، فضيَّعوا أمري وتركوا تفقُّده - وهم الرُّبوب: واحدهم ربٌّ. والمالك للشيء يدعى رَبَّه. وقد يتصرف أيضًا معنى \"الربّ\" في وجوه غير ذلك، غير أنها تعود إلى بعض هذه الوجوه الثلاثة.\n\nفربّنا جلّ ثناؤه: السيد الذي لا شِبْه لهُ، ولا مثل في سُؤدده، والمصلح أمر خلقه بما أسبغ عليهم من نعمه، والمالك الذي له الخلق والأمر.\n\nوبنحو الذي قلنا في تأويل قوله جلّ ثناؤه ﴿رَبِّ الْعَالَمِينَ﴾ ، جاءت الرواية عن ابن عباس:-\n\n١٥٥ - حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحّاك، عن ابن عباس، قال: قال جبريل لمحمد: \"يا محمد قل: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ \"، قال ابن عباس: يقول: قل الحمد لله الذي له الخلق كله - السمواتُ كلهن ومن فيهنّ، والأَرَضُون كلُّهنّ ومن فيهنّ وما بينهن، مما يُعلم ومما لا يُعلم. يقول: اعلم يا محمد أن ربَّك هذا لا يشبهه شيء.\n\n* *\n\nالقول في تأويل قوله: ﴿الْعَالَمِينَ﴾ .\n\nقاله أبو جعفر: والعالَمون جمع عالَم، والعالَم: جمعٌ لا واحدَ له من لفظه، كالأنام والرهط والجيش، ونحو ذلك من الأسماء التي هي موضوعات على جِمَاعٍ لا واحد له من لفظه.\n\nوالعالم اسم لأصناف الأمم، وكل صنف منها عالَمٌ، وأهل كل قَرْن من كل صنف منها عالم ذلك القرن وذلك الزمان. فالإنس عالَم، وكل أهل زمان منهم عالمُ ذلك الزمان. والجنُّ عالم، وكذلك سائر أجناس الخلق، كلّ جنس منها عالمُ زمانه. ولذلك جُمع فقيل: عالمون، وواحده جمعٌ، لكون عالم كلّ زمان من ذلك عالم ذلك الزمان. ومن ذلك قول العجاج:\n\nفَخِنْدِفٌ هامَةُ هَذَا العَالَمِ *\n\nفجعلهم عالمَ زمانه. وهذا القول الذي قلناه، قولُ ابن عباس وسعيد بن جبير، وهو معنى قول عامّة المفسرين.\n\n١٥٦ - حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن ابن عباس: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، الحمد لله الذي له الخلق كله: السموات والأرضون ومَن فيهنّ، وما بينهن، مما يُعلم ولا يعلم.\n\n١٥٧ - وحدثني محمد بن سنان القَزَّاز، قال حدثنا أبو عاصم، عن شبيب، عن عكرمة، عن ابن عباس: ﴿رب العالمين﴾ : الجن والإنس.\n\n١٥٨ - حدثني علي بن الحسن، قال: حدثنا مسلم بن عبد الرحمن، قال: حدثنا محمد بن مصعب، عن قيس بن الربيع، عن عطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس، في قول الله جل وعزّ ﴿رَبِّ الْعَالَمِينَ﴾ ، قال: ربِّ الجن والإنس.\n\n١٥٩ - حدثنا أحمد بن إسحاق بن عيسى الأهوازي، قال: حدثنا أبو أحمد الزبيري، قال: حدثنا قيس، عن عطاء بن السائب، عن سعيد بن جبير: قوله: ﴿رَبِّ الْعَالَمِينَ﴾ ، قال: الجنّ والإنس.\n\n١٦٠ - حدثني أحمد بن عبد الرحيم البرْقي، قال: حدثني ابن أبي مريم، عن ابن لَهِيعة، عن عطاء بن دينار، عن سعيد بن جبير، قوله: ﴿رَبِّ الْعَالَمِينَ﴾ قال: ابن آدم، والجن والإنس، كل أمة منهم عالمٌ على حِدَته.\n\n١٦١ - حدثني محمد بن حُميد، قال: حدثنا مهران، عن سفيان، عن مجاهد: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ، قال: الإنس والجن.\n\n١٦٢ - حدثنا أحمد بن إسحاق الأهوازي، قال: حدثنا أبو أحمد الزبيري، عن سفيان، عن رجل، عن مجاهد بمثله.\n\n١٦٣ - حدثنا بشر بن معاذ العَقَدي، قال: حدثنا يزيد بن زُرَيْع، عن سعيد، عن قتادة: ﴿رَبِّ الْعَالَمِينَ﴾ قال: كلّ صنف عالم.\n\n١٦٤ - حدثني أحمد بن حازم الغِفَاري، قال: حدثنا عُبيد الله بن موسى، عن أبي جعفر، عن ربيع بن أنس، عن أبي العالية، في قوله: ﴿رَبِّ الْعَالَمِينَ﴾ ، قال: الإنس عالَمٌ، والجنّ عالم، وما سوى ذلك ثمانية عشر ألف عالم، أو أربعةَ عشر ألف عالم - هو يشكّ - من الملائكة على الأرض، وللأرض أربع زوايا، في كل زاوية ثلاثة آلافِ عالم وخمسمائة عالَمٍ، خلقهم لعبادته.\n\n١٦٥ - حدثنا القاسم بن الحسن، قال: حدثنا الحسين بن داود، قال: حدثنا حجاج، عن ابن جُريج، في قوله: ﴿رَبِّ الَعَالَمِينَ﴾ قال: الجن والإنس.","3":"القول في تأويل قوله: ﴿الرَّحْمَنِ الرَّحِيمِ﴾ .\n\nقال أبو جعفر: قد مضى البيانُ عن تأويل قوله ﴿الرحمن الرحيم﴾ ، في تأويل ﴿بسم الله الرحمن الرحيم﴾ ، فأغنى ذلك عن إعادته في هذا الموضع.\n\nولم نَحْتَجْ إلى الإبانة عن وجه تكرير ذلك في هذا الموضع، إذْ كنا لا نرى أن \"بسم الله الرحمن الرحيم\" من فاتحة الكتاب - آيةٌ، فيكونَ علينا لسائلٍ مسألةٌ بأن يقول: ما وجه تكرير ذلك في هذا الموضع، وقد مضى وصفُ الله عزّ وجلّ به نفسه في قوله \" بسم الله الرحمن الرحيم \"، مع قرب مكان إحدى الآيتين من الأخرى، ومجاورتها صَاحِبتها؟ بل ذلك لنا حُجة على خطأ دعوى من ادَّعى أن \"بسم الله الرحمن الرحيم\" من فاتحة الكتاب آية. إذ لو كان ذلك كذلك، لكان ذلك إعادةَ آية بمعنى واحد ولفظ واحدٍ مرتين من غير فَصْل يَفصِل بينهما. وغيرُ موجودٍ في شيء من كتاب الله آيتان مُتجاورتان مكرّرتان بلفظ واحد ومعنى واحد، لا فصلَ بينهما من كلام يُخالف معناه معناهما. وإنما يُؤتى بتكرير آية بكمالها في السورة الواحدة، مع فُصولٍ تفصِل بين ذلك، وكلامٍ يُعترضُ به معنى الآيات المكررات أو غير ألفاظها، ولا فاصِلَ بين قول الله تبارك وتعالى اسمه \" الرحمن الرحيم \" من \" بسم الله الرحمن الرحيم \"، وقولِ الله: \" الرحمن الرحيم \"، من \" الحمدُ لله ربّ العالمين \".\n\nفإن قال: فإن \" الحمدُ لِله رَبِّ العالَمين \" فاصل من ذلك.\n\nقيل: قد أنكر ذلك جماعة من أهل التأويل، وقالوا: إن ذلك من المؤخَّر الذي معناه التقديم، وإنما هو: الحمد لله الرحمن الرحيم رَبّ العالمين مَلِك يوم الدين. واستشهدوا على صحة ما ادعوا من ذلك بقوله: \"مَلِك يوم الدين\"، فقالوا: إن قوله \"ملِكِ يوم الدين\" تعليم من الله عبدَه أنْ يصفَه بالمُلْك في قراءة من قرأ ملِك، وبالمِلْك في قراءة من قرأ \" مالك \". قالوا: فالذي هو أولى أن يكونَ مجاورَ وصفه بالمُلْك أو المِلْك، ما كان نظيرَ ذلك من الوصف؛ وذلك هو قوله: \"ربّ العالمين\"، الذي هو خبر عن مِلْكه جميع أجناس الخلق؛ وأن يكون مجاورَ وصفه بالعظمة والألُوهة ما كان له نظيرًا في المعنى من الثناء عليه، وذلك قوله: ﴿الرحمن الرحيم﴾ .\n\nفزعموا أنّ ذلك لهم دليلٌ على أن قوله \" الرحمن الرحيم \" بمعنى التقديم قبل \" رب العالمين \"، وإن كان في الظاهر مؤخرًا. وقالوا: نظائرُ ذلك - من التقديم الذي هو بمعنى التأخير، والمؤخَّر الذي هو بمعنى التقديم - في كلام العرب أفشى، وفي منطقها أكثر، من أن يُحصى. من ذلك قول جرير بن عطية:\n\nطَافَ الخَيَالُ - وأَيْنَ مِنْكَ؟ - لِمَامَا ... فَارْجِعْ لزَوْرِكَ بالسَّلام سَلاما\n\nبمعنى طاف الخيال لمامًا، وأين هو منك؟ وكما قال جل ثناؤه في كتابه: ﴿الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا قَيِّمًا﴾ [سورة الكهف: ١] بمعنى  : الحمدُ لله الذي أنزل على عبده الكتاب قيِّمًا ولم يجعل له عوجًا، وما أشبه ذلك. ففي ذلك دليل شاهدٌ على صحة قول من أنكر أن تكون - ﴿بسم الله الرحمن الرحيم﴾ من فاتحة الكتاب - آيةً","4":"القول في تأويل قوله: ﴿مَالِكِ يَوْمِ الدِّينِ﴾ .\n\nقال أبو جعفر: القرَّاء مختلفون في تلاوة ﴿ملك يَوْمِ الدِّينِ﴾ . فبعضهم يتلوه \" مَلِكِ يَوْمِ الدِّينِ \"، وبعضهم يتلوه ﴿مَلِكِ يَوْمِ الدِّينِ﴾ وبعضهم يتلوه ﴿مالِكَ يَوْمِ الدِّينِ﴾ بنصب الكاف. وقد استقصينا حكاية الرواية عمن رُوي عنه في ذلك قراءةٌ في \" كتاب القراآت \"، وأخبرنا بالذي نختار من القراءة فيه، والعلة الموجبة صحّة ما اخترنا من القراءة فيه، فكرهنا إعادة ذلك في هذا الموضع، إذ كان الذي قَصَدْنا له، في كتابنا هذا، البيانَ عن وجوه تأويل آي القرآن، دون وجوه قراءتها.\n\nولا خلاف بين جميع أهل المعرفة بلغات العرب، أن المَلِك من \"المُلْك\" مشتق، وأن المالك من \"المِلْك\" مأخوذٌ. فتأويل قراءةِ من قرأ ذلك: ﴿مَلِكِ يَوْمِ الدِّينِ﴾ ، أن لله المُلْك يوم الدين خالصًا دون جميع خلقه، الذين كانوا قبل ذلك في الدنيا ملوكًا جبابرة ينازعونه الملك، ويدافعونه الانفرادَ بالكبرياء والعظمة والسلطان والجبرية  . فأيقنوا بلقاء الله يوم الدين أنهم الصَّغَرة الأذِلّة  ، وأنّ له - من دُونهم، ودون غيرهم - المُلك والكبرياء، والعزة والبهاء، كما قال جلّ ذكره وتقدست أسماؤه في تنزيله: ﴿يَوْمَ هُمْ بَارِزُونَ لا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾ [سورة غافر: ١٦] . فأخبر تعالى ذكره أنه المنفرد يومئذ بالمُلك دون ملوك الدنيا، الذين صارُوا يوم الدّين منْ مُلكهم إلى ذِلّة وصَغار، ومن دُنياهم في المعاد إلى خسار.\n\nوأما تأويلُ قراءة من قرأ: ﴿مالك يوم الدين﴾ ، فما:-\n\n١٦٦ - حدثنا به أبو كُريب، قال: حدثنا عثمان بن سعيد، عن بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس: ﴿مَالِكِ يَوْمِ الدِّينِ﴾ ، يقول: لا يملك أحدٌ في ذلك اليوم معهُ حكمًا كمِلْكِهم في الدنيا. ثم قال: ﴿لا يَتَكَلَّمُونَ إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا﴾ [سورة النبأ: ٣٨] وقال: ﴿وَخَشَعَتِ الأَصْوَاتُ لِلرَّحْمَنِ﴾ [سورة طه: ١٠٨] . وقال: ﴿وَلا يَشْفَعُونَ إِلا لِمَنِ ارْتَضَى﴾  [سورة الأنبياء: ٢٨] .\n\nقال أبو جعفر: وأولى التأويلين بالآية، وأصحُّ القراءتين في التلاوة عندي، التأويلُ الأول، وهي قراءةُ من قرأ \"مَلِكِ\" بمعنى \"المُلك\". لأن في الإقرار له بالانفراد بالمُلك، إيجابًا لانفراده بالمِلْك، وفضيلة زيادة المِلك على المالك  ، إذْ كان معلومًا أن لا مَلِك إلا وهو مالكٌ، وقد يكون المالكُ لا ملكًا.\n\nوبعدُ، فإن الله جلّ ذكره، قد أخبر عبادَه في الآية التي قبل قوله ﴿ملِكِ يوم الدين﴾ أنه مالكُ جميع العالمين وسيَّدهم، ومُصلحُهم، والناظرُ لهم، والرحيم بهم في الدنيا والآخرة، بقوله: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَنِ الرَّحِيمِ﴾ .\n\nوإذْ كان جلّ ذكره قد أنبأهم عن مِلْكه إيَّاهم كذلك بقوله: ﴿ربِّ العالمين﴾ ، فأولى الصّفات من صفاته جل ذكره أن يَتْبَع ذلك ما لم يحْوِه قوله ﴿ربِّ العالمين الرَّحمن الرحيم﴾ ، مع قرب ما بين الآيتين من المواصَلة والمجاورة، إذْ كانت حكمتُه الحكمةَ التي لا تشبهها حِكمةٌ، وكان في إعادة وصفه جلّ ذكره بأنه ﴿مالِكِ يوم الدين﴾ ، إعادةُ ما قد مضى من وصفه به في قوله ﴿ربِّ العالمين﴾ ، مع تقارب الآيتين وتجاوز الصفتين. وكان في إعادة ذلك تكرارُ ألفاظ مختلفة بمعان متفقة، لا تفيد سامع ما كُرِّر منه فائدةً به إليها حاجة. والذي لم يحْوِه من صفاته جلّ ذكره ما قبل قوله: ﴿مالك يوم الدين﴾ ، المعنى الذي في قوله: ﴿مَلِك يوم الدين﴾ ، وهو وصْفه بأنه الملِك.\n\nفبيِّن إذًا أن أولى القراءتين بالصواب، وأحقّ التأويلين بالكتاب، قراءة من قرأه ﴿مَلِكِ يَوْمِ الدِّينِ﴾ ، بمعنى إخلاص المُلك له يوم الدين، دون قراءة من قرأ ﴿مالك يوم الدين﴾ الذي بمعنى أنه يملك الحكمَ بينهم وفصلَ القضاء، متفرِّدًا به دون سائر خلقه.\n\nفإن ظنّ ظانّ أن قوله ﴿رَبّ العَالمين﴾ نبأ عن ملكه إياهم في الدنيا دون الآخرة، يوجبُ وصْلَ ذلك بالنبأ عن نفسه أنه: مَنْ مَلَكهم في الآخرة على نحو مِلْكه إياهم في الدنيا بقوله ﴿مالك يوم الدين﴾ - فَقد أغفلَ وظنَّ خطأ  .\n\nوذلك أنه لو جاز لِظانّ أنْ يظنّ أن قوله ﴿ربّ العالمين﴾ محصورٌ معناه على الخبر عن ربوبِيَّة عالم الدنيا دُونَ عالم الآخرة، مع عدم الدلالة على أن مَعنى ذلك كذلك في ظاهر التنزيل، أو في خبرٍ عن الرسول ﷺ به منقولٍ، أو بحجّة موجودة في المعقول - لجاز لآخر أن يظنّ أن ذلك محصور على عالم الزمان الذي فيه نزل قوله ﴿رب العالمين﴾ ، دون سائر ما يحدث بعدَه في الأزمنة الحادثة من العالمين. إذْ كان صحيحًا بما قد قدّمنا من البيان، أنّ عالمَ كل زمان غير عالم الزمان الذي بعده.\n\nفإن غَبِيَ - عن علم صحة ذلك بما قد قدمنا - ذو غباء، فإنّ في قول الله جل ثناؤه: ﴿وَلَقَدْ آتَيْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ وَرَزَقْنَاهُمْ مِنَ الطَّيِّبَاتِ وَفَضَّلْنَاهُمْ عَلَى الْعَالَمِينَ﴾ [سورة الجاثية: ١٦] دلالةً واضحةً على أنّ عالم كلّ زمان، غيرُ عالم الزمان الذي كان قَبله، وعالم الزمان الذي بعدَه، إذْ كان الله جلّ ثناؤه قد فضّل أمّة نبينا محمد ﷺ على سائر الأمم الخالية، وأخبرهم بذلك في قوله: ﴿كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ﴾ الآية [سورة آل عمران: ١١٠] . فمعلومٌ بذلك أن بَني إسرائيل في عصر نبينا لم يكونوا -مع تكذيبهم به ﷺ- أفضلَ العالمين، بل كانَ أفضلَ العالمين في ذلك العصر وبعدَه إلى قيام الساعة، المؤمنون به المتَّبِعون منهاجهُ، دون من سِواهم من الأمم المكذِّبة الضالة عن منهاجه.\n\nوإذْ كان بيِّنًا فساد تأويل متأوِّلٍ لو تأوّل قوله ﴿ربّ العالمين﴾ أنه معنيٌّ به أن الله ربُّ عَالمي زَمن نبيّنا محمد ﷺ، دون عالمي سائر الأزمنة غيره - كان واضحًا فساد قول من زعم أنّ تأويلَهُ: ربُّ عالَمِ الدنيا دُون عالَمِ الآخرة، وأنّ \"مالك يوم الدين\" استحقَّ الوصلَ به ليُعلَم أنه في الآخرة من مِلْكِهم ورُبُوبيتهم بمثل الذي كان عليه في الدنيا.\n\nويُسْأل زاعم ذلك، الفرقَ بينه وبين متحكم مثله - في تأويل قوله ﴿رب العالمين﴾ ، تحكَّم فقال: إنه إنما عنى بذلك أنه ربّ عالمي زمان محمّد ﷺ، دون عالمي غيره من الأزمان الماضية قبله، والحادثة بعده، كالذي زعم قائل هذا القول: أنه عَنى به عالمي الدنيا دُون عالمي الآخرة - من أصل أو دلالة  . فلن يقول في أحدهما شيئًا إلا ألزم في الآخر مثله.\n\nوأما الزاعم أن تأويل قوله ﴿مالك يوم الدين﴾ أنه الذي يملكُ إقامة يَوم الدين، فإن الذي ألزمْنا قَائلَ هذا القول الذي قبله - له لازمٌ. إذْ كانت إقامةُ القيامة، إنما هي إعادة الخلق الذين قد بادوا لهيئاتهم التي كانوا عليها قبل الهلاك، في الدار التي أعَدّ الله لهم فيها ما أعدّ. وُهمُ العالَمون الذين قد أخبر جلّ ذكره عنهم أنه ربُّهم في قوله ﴿ربّ العالمين﴾ .\n\nوأما تأويل ذلك في قراءة من قرأ ﴿مَالِكَ يَوْمِ الدِّينِ﴾ ، فإنه أراد: يا مالك يوم الدين، فنصَبه بنيّة النداء والدعاء، كما قال جلّ ثناؤه: ﴿يُوسُفُ أَعْرِضْ عَنْ هَذَا﴾ [سورة يوسف: ٢٩] بتأويل: يا يوسف أعرضْ عن هذا، وكما قال الشاعر من بني أسد، وهو شعر -فيما يقال- جاهلي:\n\nإنْ كُنْتَ أَزْنَنْتَني بِهَا كَذِبًا ... جَزْءُ، فلاقَيْتَ مِثْلَهَا عَجِلا\n\nيريد: يا جزءُ، وكما قال الآخر:\n\nكَذَبْتُمْ وبيتِ الله لا تَنْكِحُونَهَا، ... بَني شَاب قَرْنَاها تَصُرُّ وتَحْلبُ\n\nيريد: يا بني شابَ قرْناها. وإنما أوْرطه في قراءة ذلك - بنصب الكاف من \"مالك\"، على المعنى الذي وصفتُ - حيرتهُ في توجيه قَوله: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ وِجْهَته، مع جر ﴿مالك يوم الدين﴾ وخفضِه. فظنّ أنّه لا يصحّ معنى ذلك بعد جرِّه ﴿مالك يوم الدين﴾ ، فنصب: \"مالكَ يوم الدين\" ليكون ﴿إياك نعبد﴾ له خطابًا. كأنه أراد: يا مالك يوم الدين، إياك نعبد وإياك نَستعين. ولو كان عَلم تأويل أول السورة، وأن \"الحمدُ لله رَبّ العالمين\" أمرٌ من الله عبدَه بقيلِ ذلك - كما ذكرنا قبلُ من الخبر عن ابن عباس: أن جبريلَ قال للنبي ﷺ عن الله تعالى ذكره: قل يا محمد، ﴿الحمدُ لله رب العالمين الرحمن الرحيم مَالكِ يوم الدين﴾ ، وقل أيضًا يا محمد: ﴿إياك نَعبد وإياك نَستعين﴾  - وكان عَقَل  عن العرب أنَّ من شأنها إذا حكَت أو أمرت بحكاية خبرٍ يتلو القولَ، أن تخاطب ثم تخبر عن غائب، وتخبرَ عن الغائب ثم تعودَ إلى الخطاب، لما في الحكاية بالقول من معنى الغائب والمخاطب، كقولهم للرجل: قد قلتُ لأخيك: لو قمتَ لقمتُ، وقد قلتُ لأخيك: لو قام لقمتُ  - لسَهُل عليه مخرجُ ما استصعب عليه وجْهتُه من جر \"مالك يوم الدين\".\n\nومن نظير \"مالك يوم الدين\" مجرورًا، ثم عَوْده إلى الخطاب بـ \"إياك نعبد \"، لما ذكرنا قبل - البيتُ السائرُ من شعر أبي كبير الهُذَلي:\n\nيَا لَهْفَ نَفْسي كان جِدَّةُ خَالِدٍ ... وَبَيَاضُ وَجْهِكَ للتُّرابِ الأَعْفَرِ\n\nفرجعَ إلى الخطاب بقوله: \" وبياضُ وَجْهك \"، بعد ما قد مضى الخبرُ عن خالد على معنى الخبر عن الغائب.\n\nومنه قول لبيد بن ربيعة:\n\nبَاتَتْ تَشَكَّى إليّ النَّفْسُ مُجْهِشَةً ... وقد حَمَلْتُكِ سَبْعًا بَعْدَ سَبْعِينَا\n\nفرجع إلى مخاطبة نفسه، وقد تقدم الخبر عنها على وجه الخبر عن الغائب.\n\nومنه قول الله، وهو أصدق قيلٍ وأثبتُ حجةٍ: ﴿حَتَّى إِذَا كُنْتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِمْ بِرِيحٍ طَيِّبَةٍ﴾ [سورة يونس: ٢٢] ، فخاطب ثم رجع إلى الخبر عن الغائب، ولم يقل: وَجرَين بكم. والشواهدُ من الشعر وكلام العرب في ذلك أكثر من أن تُحصى، وفيما ذكرنا كفاية لمن وُفِّق لفهمه.\n\nفقراءة: \" مالكَ يوم الدين \" محظورة غير جائزة، لإجماع جميع الحجة من القرّاء وعلماء الأمة على رَفض القراءة بها.\n\n* *\n\nالقول في تأويل قوله جل ثناؤه: ﴿يَوْمِ الدِّينِ﴾ .\n\nقال أبو جعفر: والدين في هذا الموضع، بتأويل الحساب والمجازاة بالأعمال، كما قال كعب بن جُعَيْل:\n\nإِذَا مَا رَمَوْنَا رَمَيْنَاهُم ... ودِنَّاهُمُ مِثْلَ ما يُقْرِضُونَا\n\nوكما قال الآخر:\n\nوَاعْلَمْ وأَيْقِنْ أنَّ مُلْككَ زائلٌ ... واعلمْ بأَنَّكَ مَا تدِينُ تُدَانُ\n\nيعني: ما تَجْزِي تُجازى.\n\nومن ذلك قول الله جل ثناؤه ﴿كَلا بَلْ تُكَذِّبُونَ بِالدِّينِ﴾ - يعني: بالجزاء - ﴿وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ﴾ [سورة الانفطار: ٩، ١٠] يُحصون ما تعملون من الأعمال، وقوله تعالى ﴿فَلَوْلا إِنْ كُنْتُمْ غَيْرَ مَدِينِينَ﴾ [سورة الواقعة: ٨٦] ، يعني غير مجزيِّين بأعمالكم ولا مُحاسَبين.\n\nوللدين معانٍ في كلام العرب، غير معنى الحساب والجزاء، سنذكرها في أماكنها إن شاء الله.\n\nوبما قُلنا في تأويل قوله ﴿يوم الدين﴾ جاءت الآثار عن السلف من المفسِّرين، مع تصحيح الشواهد تأويلَهم الذي تأوّلوه في ذلك.\n\n١٦٧ - حدثنا أبو كريب محمد بن العلاء، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمارة، قال: حدثنا أبو رَوق، عن الضحاك، عن عبد الله بن عباس: ﴿يَوْمِ الدِّينِ﴾ ، قال: يوم حساب الخلائق، وهو يوم القيامة، يدينهم بأعمالهم، إن خيرًا فخيرًا، وإن شرًّا فشرًّا، إلا من عَفا عنه، فالأمرُ أمرُه. ثم قال: ﴿أَلا لَهُ الْخَلْقُ وَالأَمْرُ﴾ [سورة الأعراف: ٥٤] .\n\n١٦٨ - وحدثني موسى بن هارون الهَمْدَاني، قال: حدثنا عمرو بن حماد القَنَّاد، قال: حدثنا أسباط بن نصر الهمداني، عن إسماعيل بن عبد الرحمن السُّدِّي، عن أبي مالك، وعن أبي صالح، عن ابن عباس - وعن مرة الهمداني عن ابن مسعود - وعن ناس من أصحاب النبي ﷺ: ﴿مَلِكِ يَوْمِ الدِّينِ﴾ ، هو يوم الحساب. [[الخبر ١٦٨ - هذا الإسناد من أكثر الأسانيد دورانًا في تفسير الطبري، إن لم يكن أكثرها، فلا يكاد يخلو تفسير آية من رواية بهذا الإسناد. وقد عرض الطبري نفسه في (ص ١٢١ بولاق، سطر: ٢٨ وما بعده) ، فقال، وقد ذكر الخبر عن ابن مسعود وابن عباس بهذا الإسناد: \"فإن كان ذلك صحيحًا، ولست أعلمه صحيحًا، إذ كان بإسناده مرتابًا. . . . \". ولم يبين علة ارتيابه في إسناده، وهو مع ارتيابه قد أكثر من الرواية به. ولكنه لم يجعلها حجة قط.\n\nبيد أني أراه إسنادا يحتاج إلى بحث دقيق. ولأئمة الحديث كلام فيه وفي بعض رجاله. وقد تتبعت ما قالوا وما يدعو إليه بحثه، ما استطعت، وبدا لي فيه رأي، أرجو أن يكون صوابًا، إن شاء الله. وما توفيقي إلا بالله:\n\nأما شيخ الطبري، وهو \"موسى بن هارون الهمداني\": فما وجدت له ترجمة، ولا ذكرًا في شيء مما بين يدي من المراجع، إلا ما يرويه عنه الطبري أيضًا في تاريخه، وهو أكثر من خمسين موضعًا في الجزئين الأول والثاني منه. وما بنا حاجة إلى ترجمته من جهة الجرح والتعديل، فإن هذا التفسير الذي يرويه عن عمرو بن حماد، معروف عند أهل العلم بالحديث. وما هو إلا رواية كتاب، لا رواية حديث بعينه.\n\n\"وعمرو بن حماد\": هو عمرو بن حماد بن طلحة القناد، وقد ينسب إلى جده، فيقال عمرو بن طلحة، وهو ثقة، روى عنه مسلم في صحيحه، وترجمه ابن سعد في الطبقات ٦: ٢٨٥، وقال: \"وكان ثقة إن شاء الله\" مات سنة ٢٢٢. وترجمه ابن أبي حاتم في الجرح والتعديل ٣ / ١ / ٢٢٨، وروى عن أبيه ويحيى بن معين أنهما قالا فيه: \"صدوق\".\n\nأسباط بن نصر الهمداني: مختلف فيه، وضعفه أحمد، وذكره ابن حبان في الثقات: ٤١٠، ةترجمه البخاري في الكبير ١ / ٢ / ٥٣ فلم يذكر فيه جرحًا، وترجمه ابن أبي حاتم في الجرح والتعديل ١ / ١ / ٣٣٢، وروى عن يحيى بن معين قال: \"أسباط بن نصر ثقة\". وقد رجحنا توثيقه في شرح المسند، في الحديث ١٢٨٦.\n\nإسماعيل بن عبد الرحمن بن أبي كريمة السدي: هو السدي الكبير، قرشي بالولاء، مولى زينب بنت قيس بن مخرمة، من بني عبد مناف، كما نص على ذلك البخاري في تاريخيه: الصغير: ١٤١ - ١٤٢، والكبير ١ / ١ / ٣٦١، وهو تابعي، سمع أنسًا، كما نص على ذلك البخاري أيضًا، وروى عن غيره من الصحابة، وعن كثير من التابعين. وهو ثقة. أخرج له مسلم في صحيحه، وثقه أحمد بن حنبل، فيما روى ابن أبي حاتم في الجرح والتعديل ١ / ١ / ١٨٤، وروى أيضًا عن أحمد، قال: \"قال لي يحيى بن معين يومًا عند عبد الرحمن بن مهدي: السدي ضعيف، فغضب عبد الرحمن، وكره ما قال\": وفي الميزان والتهذيب \"أن الشعبي قيل له: إن السدي قد أعطي حظًا من علم القرآن، فقال: قد أعطي حظًا من جهل بالقرآن! \". وعندي أن هذه الكلمة من الشعبي قد تكون أساسا لقول كل من تكلم في السدي بغير حق. ولذلك لم يعبأ البخاري بهذا القول من الشعبي، ولم يروه، بل روى في الكبير عن مسدد عن يحيى قال: \" سمعت ابن أبي خالد يقول: السدي أعلم بالقرآن من الشعبي\". وروى في تاريخيه عن ابن المديني عن يحيى، وهو القطان، قال: \"ما رأيت أحدًا يذكر السدي إلا بخير، وما تركه أحد\". وفي التهذيب: \"قال العجلي: ثقة عالم بالتفسير راوية له\". وقد رجحنا توثيقه في شرح المسند ٨٠٧. وتوفي السدي سنة ١٢٧.\n\nو\"السدي\": بضم السين وتشديد الدال المهملتين، نسبة إلى \"السدة\"، وهي الباب، لأنه كان يجلس إلى سدة الجامع بالكوفة، ويبيع بها المقانع.\n\nأبو مالك: هو الغفاري، واسمه غزوان. وهو تابعي كوفي ثقة. ترجمه البخاري في الكبير ٤ / ١ / ١٠٨، وابن سعد في الطبقات ٦: ٢٠٦، وابن أبي حاتم في الجرح والتعديل ٣ / ٢ / ٥٥، وروى توثيقه يحيى بن معين.\n\nأبو صالح: هو مولى أم هانئ بنت أبي طالب، واسمه باذام، ويقال باذان. وهو تابعي ثقة، رجحنا توثيقه في شرح المسند ٢٠٣٠، وترجمه البخاري في الكبير ١ / ٢ / ١٤٤، وروى عن محمد بن بشار، قال: \"ترك ابن مهدي حديث أبي صالح\". وكذلك روى ابن أبي حاتم في ترجمته في الجرح والتعديل ١ / ١ / ٤٣١ - ٤٣٢ عن أحمد بن حنبل عن ابن مهدي. ولكنه أيضًا عن يحيى بن سعيد القطان، قال: \" لم أرَ أحدًا من أصحابنا ترك أبا صالح مولى أم هانئ، وما سمعت أحدًا من الناس يقول فيه شيئًا، ولم يتركه شعبة ولا زائدة ولا عبد الله بن عثمان\". وروى أيضًا عن يحيى بن معين، قال: \" أبو صالح مولى أم هانئ ليس به بأس، فإذا روى عنه الكلبي فليس بشيء، وإذا روى عنه غير الكلبي فليس به بأس، لأن الكلبي يحدث به مرة من رأيه، ومرة عن أبي صالح، ومرة عن أبي صالح عن ابن عباس\". يعني بهذا أن الطعن فيما يروي عنه هو في رواية الكلبي، كما هو ظاهر.\n\nهذا عن القسم الأول من هذا الإسناد. فإنه في حقيقته إسنادان أو ثلاثة. أولهما هذا المتصل بابن عباس.\n\nوالقسم الثاني، أو الإسناد الثاني: \"وعن مرة الهمداني عن ابن مسعود\". والذي يروي عن مرة الهمداني: هو السدي نفسه.\n\nومرة: هو ابن شراحيل الهمداني الكوفي، وهو تابعي ثقة، من كبار التابعين، ليس فيه خلاف بينهم.\n\nوالقسم الثالث، أو الإسناد الثالث: \"وعن ناس من أصحاب النبي ﷺ\".\n\nوهذا أيضًا من رواية السدي نفسه عن ناس من الصحابة.\n\nفالسدي يروي هذه التفاسير لآيات من القرآن: عن اثنين من التابعين عن ابن عباس، وعن تابعي واحد عن ابن مسعود، ومن رواية نفسه عن ناس من الصحابة.\n\nوللعلماء الأئمة الأقدمين كلام في هذا التفسير، بهذه الأسانيد، قد يوهم أنه من تأليف من دون السدي من الرواة عنه، إلا أني استيقنت بعدُ، أنه كتاب ألفه السدي.\n\nفمن ذلك قول ابن سعد في ترجمة \"عمرو بن حماد القناد\" ٦: ٢٨٥: \"صاحب تفسير أسباط بن نصر عن السدي\". وقال في ترجمة \"أسباط بن نصر\" ٦: ٢٦١: \"وكان راوية السدي، روى عنه التفسير\". وقال قبل ذلك في ترجمة \"السدي\" ٦: ٢٢٥: \"إسماعيل بن عبد الرحمن السدي، صاحب التفسير\". وقال قبل ذلك أيضًا، في ترجمة \"أبي مالك الغفاري\" ٦: ٢٠٦: \"أبو مالك الغفاري صاحب التفسير، وكان قليل الحديث\".\n\nولكن الذي يرجح أنه كتاب ألفه السدي، جمع فيه التفسير، بهذه الطرق الثلاث، قول أحمد بن حنبل في التهذيب ١: ٣١٤، في ترجمة السدي: \"إنه ليحسن الحديث، إلا أن هذا التفسير الذي يجئ به، قد جعل له إسنادًا، واستكلفه\". وقول الحافظ في التهذيب أيضًا ١: ٣١٥: \"قد أخرج الطبري وابن أبي حاتم وغيرهما، في تفاسيرهم، تفسير السدي، مفرقًا في السور، من طريق أسباط بن نصر عنه\".\n\nوقول السيوطي في الإتقان ٢: ٢٢٤ فيما نقل عن الخليل في الإرشاد: \"وتفسير إسماعيل السدي، يورده بأسانيد إلى ابن مسعود وابن عباس. وروى عن السدي الأئمة، مثل الثوري وشعبة. ولكن التفسير الذي جمعه، رواه أسباط بن نصر. وأسباط لم يتفقوا عليه. غير أن أمثل التفاسير تفسير السدي\". ثم قال السيوطي: \"وتفسير السدي، [الذي] أشار إليه، يورد منه ابن جرير كثيرًا، من طريق السدي عن أبي مالك وعن أبي صالح عن ابن عباس، وعن مرة عن ابن مسعود، و [عن] ناس من الصحابة. هكذا. ولم يورد منه ابن أبي حاتم شيئًا، لأنه التزم أن يخرج أصح ما ورد. والحاكم يخرج منه في مستدركه أشياء، ويصححه، لكن من طريق مرة عن ابن مسعود وناس، فقط، دون الطريق الأول، وقد قال ابن كثير: إن هذا الإسناد يروي به السدي أشياء فيها غرابة\".\n\nوأول ما نشير إليه في هذه الأقوال: التناقض بين قولي الحافظ ابن حجر والسيوطي، في أن ابن أبي حاتم أخرج تفسير السدي مفرقًا في تفسيره، كما صنع الطبري، في نقل الحافظ، وأنه أعرض عنه، في نقل السيوطي. ولست أستطيع الجزم في ذلك بشيء، إذ لم أرَ تفسير ابن أبي حاتم. ولكني أميل إلى ترجيح نقل ابن حجر، بأنه أكثر تثبتًا ودقة في النقل من السيوطي.\n\nثم قد صدق السيوطي فيما نقل عن الحاكم. فإنه يروي بعض هذا التفسير في المستدرك، بإسناده، إلى أحمد بن نصر: \"حدثنا عمرو بن طلحة القناد حدثنا أسباط بن نصر، عن إسماعيل بن عبد الرحمن السدي، عن مرة الهمداني، عن عبد الله بن مسعود، وعن أناس من أصحاب النبي ﷺ\". ثم يصححه على شرط مسلم، ويوافقه الذهبي في تلخيصه. من ذلك في المستدرك ٢: ٢٥٨، ٢٦٠، ٢٧٣، ٣٢١.\n\nوالحاكم في ذلك على صواب، فإن مسلمًا أخرج لجميع رجال هذا الإسناد. من عمرو بن حماد بن طلحة القناد إلى مرة الهمداني. ولم يخرج لأبي صالح باذام ولا لأبي مالك الغفاري، في القسم الأول من الإسناد الذي روى به السدي تفاسيره.\n\nأما كلمة الإمام أحمد بن حنبل في السدي \"إلا أن هذا التفسير الذي يجيء به، قد جعل له إسنادًا واستكلفه\" فإنه لا يريد ما قد يفهم من ظاهرها: أنه اصطنع إسنادا لا أصل له؛ إذ لو كان ذلك، لكان -عنده- كذابًا وضاعًا للرواية. ولكنه يريد -فيما أرى، والله أعلم- أنه جمع هذه التفاسير، من روايته عن هؤلاء الناس: عن أبي مالك وأبي صالح عن ابن عباس، وعن مرة عن ابن مسعود، وعن ناس من الصحابة، ثم ساقها كلها مفصلة، على الآيات التي ورد فيها شيء من التفسير، عن هذا أو ذاك أو أولئك، وجعل لها كلها هذا الإسناد، وتكلف أن يسوقها به مساقًا واحدًا.\n\nأعني: أنه جمع مفرق هذه التفاسير في كتاب واحد، جعل له في أوله هذه الأسانيد. يريد بها أن ما رواه من التفاسير في هذا الكتاب، لا يخرج عن هذه الأسانيد. ولا أكاد أعقل أنه يروي كل حرف من هذه التفاسير عنهم جميعا. فهو كتاب مؤلف في التفسير، مرجع فيه إلى الرواية عن هؤلاء، في الجملة، لا في التفصيل.\n\nإنما الذي أوقع الناس في هذه الشبهة، تفريق هذه التفاسير في مواضعها، مثل صنيع الطبري بين أيدينا، ومثل صنيع ابن أبي حاتم، فيما نقل الحافظ ابن حجر، ومثل صنيع الحاكم في المستدرك. فأنا أكاد أجزم أن هذا التفريق خطأ منهم، لأنه يوهم القارئ أن كل حرف من هذه التفاسير مروي بهذه الأسانيد كلها، لأنهم يسوقونها كاملة عند كل إسناد، والحاكم يختار منها إسنادًا واحدًا يذكره عند كل تفسير منها يريد روايته. وقد يكون ما رواه الحاكم -مثلا- بالإسناد إلى ابن مسعود، ليس مما روى السدي عن ابن مسعود نصًا. بل لعله مما رواه من تفسير ابن عباس، او مما رواه ناس من الصحابة، روى عن كل واحد منهم شيئًا، فأسند الجملة، ولم يسند التفاصيل.\n\nولم يكن السدي ببدع في ذلك، ولا يكون هذا جرحًا فيه ولا قدحًا. إنما يريد إسناد هذه التفاسير إلى الصحابة، بعضها عن ابن عباس، وبعضها عن ابن مسعود، وبعضها عن غيرهما منهم. وقد صنع غيره من حفاظ الحديث وأئمته نحوًا مما صنع، فما كان ذلك بمطعن فيهم، بل تقبلها الحفاظ بعدهم، وأخرجوها في دواوينهم. ويحض]]\n\n١٦٩ - حدثنا الحسن بن يحيى، قال: أخبرنا عبد الرزاق، قال: أخبرنا مَعمر، عن قتادة في قوله: ﴿مَالِكِ يَوْمِ الدِّينِ﴾ قال: يوم يَدينُ الله العبادَ بأعمالهم.\n\n١٧٠ - وحدثنا القاسم بن الحسن، قال: حدثنا الحسين بن داود، قال: حدثني حجاج، عن ابن جريج، ﴿مالك يوم الدين﴾ قال: يوم يُدان الناس بالحساب.","5":"القول في تأويل قوله جل ثناؤه: ﴿إِيَّاكَ نَعْبُدُ﴾ .\n\nقال أبو جعفر: وتأويل قوله ﴿إيَّاكَ نعبُدُ﴾ : لك اللهم نَخشعُ ونَذِلُّ ونستكينُ، إقرارًا لك يا رَبنا بالرُّبوبية لا لغيرك.\n\n١٧١ - كما حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمَارة، قال: حدثنا أبو رَوق، عن الضحاك، عن عبد الله بن عباس، قال: قال جبريلُ لمحمد ﷺ: قل يا محمد: ﴿إِيَّاكَ نَعْبُدُ﴾ ، إياكَ نُوحِّد ونخاف ونرجو يا ربَّنا لا غيرك  .\n\nوذلك من قول ابن عباس بمعنى ما قلنا. وإنما اخترنا البيان عن تأويله بأنه بمعنى نَخشع ونذلّ ونستكينُ، دون البيان عنه بأنه بمعنى نرجو ونَخاف- وإن كان الرّجاء والخوف لا يكونان إلا مع ذلة- لأنّ العبودية، عندَ جميع العرب أصلُها الذلّة، وأنها تسمي الطريقَ المذلَّلَ الذي قد وَطِئته الأقدام، وذلّلته السابلة: معبَّدًا. ومن ذلك قولَ طَرَفَة بن العَبْد:\n\nتُبَارِي عِتَاقًا نَاجياتٍ وأَتْبَعت ... وَظِيفًا وظيفًا فوق مَوْرٍ مُعَبَّدِ\n\nيعني بالموْر: الطريق. وبالمعبَّد: المذلَّل الموطوء  . ومن ذلك قيل للبعير المذلّل بالركوب في الحوائج: معبَّد. ومنه سمي العبْدُ عبدًا لذلّته لمولاه. والشواهد على ذلك -من أشعار العرب وكلامها- أكثرُ من أن تُحصى، وفيما ذكرناه كفاية لمن وُفّق لفهمه إن شاء الله تعالى.\n\n* *\n\nالقول في تأويل قوله: ﴿وَإِيَّاكَ نَسْتَعِينُ﴾ .\n\nقال أبو جعفر: ومعنى قوله: ﴿وَإِيَّاكَ نَسْتَعِينُ﴾ : وإياك رَبنا نستعين على عبادتنا إيّاك وطاعتنا لك وفي أمورنا كلها -لا أحدًا سواك، إذْ كان من يكفُر بك يَستعين في أمورِه معبودَه الذي يعبُدُه من الأوثان دونَك، ونحن بك نستعين في جميع أمورنا مخلصين لك العبادة.\n\n١٧٢ - كالذي حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثني بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس: ﴿وَإِيَّاكَ نَسْتَعِينُ﴾ ، قال: إياك نستَعِينُ على طاعتك وعلى أمورنا كلها  .\n\nفإن قال قائل: وما معنى أمر الله عبادَه بأن يسألوه المعونةَ على طاعته؟ أوَ جائزٌ، وقد أمرهم بطاعته، أن لا يعينهم عليها؟ أم هل يقول قائل لربه: إياك نستعين على طاعتك، إلا وهو على قوله ذلك مُعانٌ، وذلك هو الطاعة. فما وجهُ مسألة العبد ربَّه ما قد أعطاه إياه؟\n\nقيل: إن تأويلَ ذلك على غير الوجه الذي ذهبتَ إليه، وإنما الداعي ربَّه من المؤمنين أن يعينه على طاعته إياه، داعٍ أن يعينه فيما بقي من عُمره على ما كلّفه من طاعته، دون ما قد تَقضَّى ومَضى من أعماله الصالحة فيما خلا من عمره. وجازت مسألةُ العبد ربَّه ذلك، لأن إعطاء الله عبدَه ذلك -مع تمكينه جوارحَه لأداء ما كلَّفه من طاعته، وافترض عليه من فرائضه، فضلٌ منه جل ثناؤه تفضّل به عليه، ولُطْف منه لَطَف له فيه. وليس في تَركه التفضُّلَ على بعض عبيده بالتوفيق -مع اشتغال عبده بمعصيته، وانصرافه عن مَحبته، ولا في بَسطه فضلَه على بعضهم، مع إجهاد العبد نفسه في مَحبته، ومسارعته إلى طاعته -فسادٌ في تدبير، ولا جَور في حكم، فيجوز أن يجهلَ جاهل موضع حُكم الله في أمرِه عبدَه بمسألته عَونَه على طاعته  .\n\nوفي أمر الله جل ثناؤه عبادَه أن يقولوا: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ ، بمعنى مسألتهم إياه المعونةَ على العبادة، أدلُّ الدليل على فساد قول القائلين بالتَّفويض من أهل القدر  ، الذين أحالوا أن يأمُرَ الله أحدًا من عبيده بأمرٍ، أو يكلّفه فرضَ عمل، إلا بعدَ إعطائه المعونة على فعلِه وعلى تركِه. ولو كانَ الذي قالوا من ذلك كما قالوا، لبطلت الرَّغبة إلى الله في المعونة على طاعته. إذ كان -على قولهم، مع وجود الأمر والنهي والتكليف- حقًّا واجبًا على الله للعبد إعطاؤه المعونة عليه، سأله عبدُه أو تركَ مسألة ذلك. بل تَرك إعطائه ذلك عندهم منه جَورٌ. ولو كان الأمر في ذلك على ما قالوا، لكان القائل: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ ، إنما يسأل رَبَّه أن لا يجور.\n\nوفي إجماع أهل الإسلام جميعًا -على تصويب قول القائل: \"اللهم إنا نستعينك\"، وتخطئَتِهم قول القائل: \"اللهم لا تَجُرْ علينا\"- دليل واضحٌ على خطأ ما قال الذين وصفتُ قولهم. إذْ كان تأويلُ قول القائل عندهم: \"اللهم إنّا نستعينك- اللهم لا تترك مَعونتنا التي تركُكَها جَوْرٌ منك.\n\nفإن قال قائل: وكيف قيل: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ ، فقُدِّم الخبرُ عن العِبادة، وأخِّرتْ مسألةُ المعونة عليها بعدَها؟ وإنما تكون العِبادة بالمعونة، فمسألةُ المعونة كانت أحقَّّ بالتقديم قبلَ المُعَان عليه من العمل والعبادةُ بها.\n\nقيل: لمَّا كان معلومًا أن العبادة لا سبيلَ للعبد إليها إلا بمعونة من الله جلّ ثناؤه، وكان محالا أن يكون العبْد عابدًا إلا وهو على العبادة مُعان، وأن يكون مُعانًا عليها إلا وهو لها فاعل- كان سواءً تقديمُ ما قُدمّ منهما على صاحبه. كما سواءٌ قولك للرجل إذا قضى حاجَتَك فأحسن إليك في قضائها: \"قضيتَ حاجتي فأحسنتَ إليّ \"، فقدّمت ذكر قضائه حاجتَك، أو قلتَ: أحسنتَ إليّ فقضيتَ حاجتي\"، فقدَّمتَ ذكر الإحسان على ذكر قضاء الحاجة. لأنه لا يكون قاضيًا حاجتَك إلا وهو إليك محسن، ولا محسنًا إليك إلا وهو لحاجتك قاضٍ. فكذلك سواءٌ قول القائل: اللهم إنّا إياك نعبُدُ فأعِنَّا على عبادتك، وقوله: اللهم أعنَّا على عبادتك فإنّا إياك نعبُدُ.\n\nقال أبو جعفر: وقد ظنّ بعض أهل الغفلة أنّ ذلك من المقدّم الذي معناه التأخيرُ، كما قال امرؤ القيس:\n\nولَوْ أَنّ مَا أسْعَى لأَدْنَى مَعِيشةٍ ... كَفاني، ولم أطلُبْ، قليلٌ من المالِ\n\nيريد بذلك: كفاني قليلٌ من المال ولم أطلب كثيرًا. وذلك -من معنى التقديم والتأخير، ومن مشابهة بيت امرئ القيس- بمعْزِل. من أجل أنّه قد يكفيه القليلُ من المال ويطلُب الكثيرَ، فليس وُجودُ ما يكفيه منه بموجبٍ له تركَ طلب الكثير، فيكونَ نظيرَ العبادة التي بوجُودها وجود المعونة عليها، وبوجود المعونة عليها وُجُودها، فيكونَ ذكرُ أحدِهما دالا على الآخر، فيعتدلَ في صحة الكلام تقديمُ ما قُدِّم منهما قبلَ صاحبه، أن يكونَ موضوعًا في درجته ومرتَّبًا في مرتَبتِه.\n\nفإن قال: فما وجْه تكراره: \"إياك\" مع قوله: \"نستعين\"، وقد تقدَّم ذلك قَبْل \"نعبد\"؟ وهلا قيل: \"إياك نعبُدُ ونستعين\"، إذ كان المخبَرُ عنه أنه المعبودُ، هو المخبر عنه أنه المستعانُ؟\n\nقيل له: إن الكاف التي مع \" إيَّا \"، هي الكاف التي كانت تصل بالفعل -أعني بقوله: \"نعبد\" -لو كانت مؤخرةً بعدَ الفعل. وهي كنايةُ اسم المخاطبِ المنصوب بالفعل، فكُثِّرت بـ \"إيّا \" متقدِّمةً، إذْ كان الأسماء إذا انفردتْ بأنفسِها لا تكون في كلام العرب على حرف واحد.\n\nفلمّا كانت الكاف من \" إياكَ \" هي كنايةَ اسم المخاطَب التي كانت تكون كافًا وحدها متصلةً بالفعل إذا كانتْ بعد الفعل، ثم كان حظُّها أن تعادَ مع كلّ فعل اتصلتْ به، فيقال: \"اللهم إنا نعبدكَ ونستعينكَ ونحمدكَ ونشكرك\"، وكان ذلك أفصحَ في كلام العرب من أن يقال: \"اللهم إنا نعبدك ونستعين ونحمد\"- كان كذلك، إذا قدِّمت كنايةُ اسم المخاطب قبل الفعل موصولةً بـ \"إيّا \"، كان الأفصح إعادَتها مع كل فعل. كما كان الفصيحُ من الكلام إعادَتها مع كل فعل، إذا كانت بعد الفعل متصلةً به، وإن كان تركُ إعادتها جائزًا.\n\nوقد ظنّ بعضُ من لم يُنعم النظرَ  أنّ إعادة \" إياك \" مع \" نستعين \"، بعد تقدّمها في قوله: \"إياك نستعين\"، بمعنى قول عدي بن زيد العِبَاديّ:\n\nوجَاعِل الشَّمس مِصْرًا لا خَفَاءَ بِه ... بَيْن النَّهارِ وَبيْنَ اللَّيل قد فَصَلا\n\nوكقول أعشى هَمْدان:\n\nبَيْنَ الأشَجِّ وبَيْنَ قَيْسٍ باذخٌ ... بَخْ بَخْ لوَالِدِهِ وللمَولُودِ\n\nوذلك من قائله جهل، من أجل أن حظ \"إيّاك\" أن تكون مكررة مع كل فعل، لما وصفنا آنفًا من العلة، وليس ذلك حُكم \" بين \" لأنها لا تكون -إذ اقتضت اثنين- إلا تكريرًا إذا أعيدت، إذْ كانت لا تنفَرد بالواحد. وأنها لو أفْرِدت بأحد الاسمين، في حال اقتضائها اثنين، كان الكلام كالمستحيل. وذلك أنّ قائلا لو قال: \"الشمس قد فَصَلت بين النهار\"، لكان من الكلام خَلْفًا  لنُقصان الكلام عما به الحاجة إليه، من تمامه الذي يقتضيه \" بين \".\n\nولو قال قائل: \" اللهمّ إياك نعبد \"، لكان ذلك كلامًا تامًّا. فكان معلومًا بذلك أنّ حاجةَ كلِّ كلمةٍ -كانت نظيرةَ \" إياك نعبد \" - إلى \" إياك \" كحاجة \" نُعْبد \" إليها  وأنّ الصواب أن تكونَ معها \" إياك \"، إذْ كانت كل كلمة منها جملةَ خبرِ مبتدأ، وبيّنًا حُكم مخالفة ذلك حُكم \" بين \" فيما وَفّق بينهما الذي وصفنا قوله.","6":"القول في تأويل قوله: ﴿اهْدِنَا﴾ .\n\nقال أبو جعفر: ومعنى قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ ، في هذا الموضع عندنا: وَفِّقْنا للثبات عليه، كما رُوي ذلك عن ابن عباس:-\n\n١٧٣ - حدثنا أبو كُريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن عبد الله بن عباس، قال: قال جبريل لمحمد صلى الله عليه: \" قل، يا محمد، اهدنا الصراط المستقيمَ \". يقول: ألهمنا الطريق الهادي  .\n\nوإلهامه إياه ذلك، هو توفيقه له، كالذي قلنا في تأويله. ومعناه نظيرُ معنى قوله: \" إياك نستعين \"، في أنه مَسألةُ العبد ربَّه التوفيقَ للثبات على العمل بطاعته، وإصابة الحق والصواب فيما أمَره به ونهاه عنه، فيما يَستَقبِلُ من عُمُره، دون ما قد مضى من أعماله، وتقضَّى فيما سَلف من عُمُره. كما في قوله: \"إياك نستعين\"، مسألةٌ منه ربَّه المعونةَ على أداء ما قد كلَّفه من طاعته، فيما بقي من عُمُره.\n\nفكانَ معنى الكلام: اللهمّ إياك نعبدُ وحدَك لا شريك لك، مخلصين لك العبادةَ دونَ ما سِواك من الآلهة والأوثان، فأعِنَّا على عبادتك، ووفِّقنا لما وفَّقت له مَن أنعمتَ عليه من أنبيائك وأهل طاعتك، من السبيل والمنهاج.\n\nفإن قال قائل: وأنَّى وَجدتَ الهدايةَ في كلام العرب بمعنى التَّوفيق؟\n\nقيل له: ذلك في كلامها أكثرُ وأظهر من أن يُحصى عددُ ما جاء عنهم في ذلك من الشواهد. فمن ذلك قول الشاعر:\n\nلا تَحْرِمَنِّي هَدَاكَ الله مَسْألتِي ... وَلا أكُونَنْ كمن أوْدَى به السَّفَرُ\n\nيعنى به: وفَّقك الله لقضاء حاجتي. ومنه قول الآخر:\n\nولا تُعْجِلَنِّي هدَاَك المليكُ ... فإنّ لكلِّ مَقامٍ مَقَالا\n\nفمعلوم أنه إنما أراد: وفقك الله لإصابة الحق في أمري.\n\nومنه قول الله جل ثناؤه: ﴿وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ﴾ في غير آيه من تنزيله. وقد عُلم بذلك، أنه لم يَعْنِ أنه لا يُبيِّنُ للظالمين الواجبَ عليهم من فرائضه. وكيف يجوزُ أن يكونَ ذلك معناه، وقد عمَّ بالبيان جميع المكلَّفين من خلقه؟ ولكنه عَنى جلّ وعزّ أنه لا يُوفِّقهم، ولا يشرَحُ للحق والإيمان صدورَهم.\n\nوقد زعم بعضهم أن تأويل قوله: ﴿اهدِنا﴾ : زدْنا هدايةٍ.\n\nوليس يخلُو هذا القولُ من أحد أمرين: إما أن يكون ظنَّ قائلُه أنّ النبي ﷺ أُمِر بمسألة الزيادة في البيان، أو الزيادةَ في المعونة والتوفيق.\n\nفإن كان ظن أنه أُمِر بمسألة رَبِّه الزيادة في البيان، فذلك ما لا وجه له؛ لأن الله جلّ ثناؤه لا يكلِّف عبدًا فرضًا من فرائضه، إلا بعد تبيينه له وإقامةِ الحجة عليه به. ولو كان مَعنى ذلك معنى مسألتِه البيانَ، لكانَ قد أمِر أن يدعو ربَّه أن يبين له ما فَرض عليه، وذلك من الدعاء خَلفٌ  ، لأنه لا يفرض فرضًا إلا مبيَّنًا لمن فرضَه عليه. أو يكون أمِر أن يدعوَ ربَّه أن يفرض عليه الفرائضَ التي لم يفرضْها.\n\nوفي فساد وَجه مسألة العبد ربَّه ذلك، ما يوضِّح عن أن معنى: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ ، غير معنى: بيِّن لنا فرائضَك وحدودَك.\n\nأو يكون ظنّ أنه أمِر بمسألة ربه الزيادةَ في المعونة والتوفيق. فإن كان ذلك كذلك، فلن تخلوَ مسألتُه تلك الزيادةَ من أن تكون مسألةً للزيادة في المعونة على ما قد مضى من عمله، أو على ما يحدُث.\n\nوفي ارتفاع حاجةِ العبد إلى المعونة على ما قد تقضَّى من عمله  ، ما يُعلِمُ أنّ معنى مسألة تلك الزيادة إنما هو مسألتُه الزيادةَ لما يحدث من عمله. وإذْ كانَ ذلك كذلك، صارَ الأمر إلى ما وصفنا وقلنا في ذلك: من أنه مسألة العبد ربَّه التوفيقَ لأداء ما كُلِّف من فرائضه، فيما يَستقبل من عُمُره.\n\nوفي صحة ذلك، فسادُ قول أهل القدَر الزاعمين أنّ كل مأمور بأمرٍ أو مكلَّف فرضًا، فقد أعطي من المعونة عليه، ما قد ارتفعت معه في ذلك الفرض حاجتُه إلى ربِّه  . لأنه لو كان الأمرُ على ما قالوا في ذلك، لبطَلَ معنى قول الله جل ثناؤه: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ . وفي صحة معنى ذلك، على ما بيَّنا، فسادُ قولهم.\n\nوقد زعم بعضُهم أنّ معنى قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ : أسْلِكنا طريق الجنة في المعاد، أيْ قدِّمنا له وامض بنا إليه، كما قال جلّ ثناؤه: ﴿فَاهْدُوهُمْ إِلَى صِرَاطِ الْجَحِيمِ﴾ [سورة الصافات: ٢٣] ، أي أدخلوهم النار، كما تُهْدَى المرأة إلى زوجها، يُعني بذلك أنها تُدخَل إليه، وكما تُهدَى الهديَّة إلى الرجل، وكما تَهدِي الساقَ القدمُ، نظير قَول طَرفة بن العبد:\n\nلَعبتْ بَعْدِي السُّيُولُ بهِ ... وجَرَى في رَوْنَقٍ رِهمُهْ\n\nلِلفَتَى عَقْلٌ يَعِيشُ بِهِ ... حَيْثُ تَهْدِي سَاقَه قَدَمُهْ\n\nأي تَرِدُ به الموارد.\n\nوفي قول الله جل ثناؤه ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ ما ينبئ عن خطأ هذا التأويل، مع شهادة الحجة من المفسِّرين على تخطئته. وذلك أنّ جميع المفسرين من الصحابة والتابعين مجمِعُون على أنّ معنى \" الصراط \" في هذا الموضع، غيرُ المعنى الذي تأوله قائل هذا القول، وأن قوله: \" إياك نستعينُ\" مسألةُ العبدِ ربَّه المعونةَ على عبادته. فكذلك قوله \" اهْدِنا \" إنما هو مسألةُ الثباتِ على الهدى فيما بقي من عُمُره.\n\nوالعربُ تقول: هديتُ فلانًا الطريقَ، وهَديتُه للطريق، وهديتُه إلى الطريق، إذا أرشدتَه إليه وسدَّدته له. وبكل ذلك جاء القرآن، قال الله جلّ ثناؤه: ﴿وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا﴾ [سورة الأعراف: ٤٣] ، وقال في موضع آخر: ﴿اجْتَبَاهُ وَهَدَاهُ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾ [سورة النحل: ١٢١] ، وقال: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ .\n\nوكل ذلك فاش في منطقها، موجودٌ في كلامها، من ذلك قول الشاعر:\n\nأَسْتَغْفِرُ اللهَ ذَنْبًا لَسْتُ مُحْصِيَهُ، ... رَبَّ العِباد، إليهِ الوَجْهُ والعَمَلُ\n\nيريد: أستغفر الله لذنْب، كما قال جل ثناؤه: ﴿وَاسْتَغْفِرْ لِذَنْبِكَ﴾ [سورة غافر: ٥٥] .\n\nومنه قول نابغة بني ذُبْيان:\n\nفَيَصِيدُنَا العَيْرَ المُدِلَّ بِحُضْرِهِ ... قَبْلَ الوَنَى وَالأَشْعَبَ النَبَّاحَا\n\nيريد: فيصيدُ لنا. وذلك كثير في أشعارهم وكلامهم، وفيما ذكرنا منه كفاية.\n\n* *\n\nالقول في تأويل قوله: ﴿الصِّرَاطَ الْمُسْتَقِيمَ﴾ .\n\nقال أبو جعفر: أجمعت الأمة من أهل التأويل جميعًا على أن \"الصراط المستقيم\"، هو الطريق الواضح الذي لا اعوجاج فيه. وكذلك ذلك في لغة جميع العرب، فمن ذلك قول جرير بن عطية الخَطَفي:\n\nأميرُ المؤمنين عَلَى صِرَاطٍ ... إذا اعوَجَّ المَوَارِدُ مُسْتَقيمِ\n\nيريد على طريق الحق. ومنه قول الهُذلي أبي ذُؤَيْب:\n\nصَبَحْنَا أَرْضَهُمْ بالخَيْلِ حَتّى ... تركْنَاها أَدَقَّ مِنَ الصِّرَاطِ\n\nومنه قول الراجز:\n\nفَصُدَّ عَنْ نَهْجِ الصِّراطِ القَاصدِ  *\n\nوالشواهد على ذلك أكثرُ من أن تُحصى، وفيما ذكرنا غنًى عما تركنا.\n\nثم تستعيرُ العرب \"الصراط\" فتستعمله في كل قولٍ وعمل وُصِف باستقامة أو اعوجاج، فتصفُ المستقيمَ باستقامته، والمعوجَّ باعوجاجه.\n\nوالذي هو أولى بتأويل هذه الآية عندي، أعني: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ ، أن يكونا معنيًّا به: وَفّقنا للثبات على ما ارتضيتَه ووَفّقتَ له مَنْ أنعمتَ عليه من عبادِك، من قولٍ وعملٍ، وذلك هو الصِّراط المستقيم. لأن من وُفّق لما وفق له من أنعم الله عليه من النبيِّين والصديقين والشهداء، فقد وُفّق للإسلام، وتصديقِ الرسلِ، والتمسكِ بالكتاب، والعملِ بما أمر الله به، والانزجار عمّا زَجره عنه، واتّباع منهج النبيّ ﷺ، ومنهاج أبي بكر وعمر وعثمان وعلي. وكلِّ عبدٍ لله صالحٍ، وكل ذلك من الصراط المستقيم.\n\nوقد اختلفتْ تراجمةُ القرآن في المعنيِّ بالصراط المستقيم  . يشمل معاني جميعهم في ذلك، ما اخترنا من التأويل فيه.\n\nومما قالته في ذلك، ما رُوي عن علي بن أبي طالب، عن النبي ﷺ، أنه قال، وذكر القرآن، فقال: هو الصراط المستقيم.\n\n١٧٤ - حدثنا بذلك موسى بن عبد الرحمن المسروقي، قال: حدثنا حسين الجُعْفي، عن حمزة الزيات، عن أبي المختار الطائي، عن ابن أخي الحارث، عن الحارث، عن عليّ، عن النبي ﷺ  .\n\n١٧٥ - وحُدِّثْتُ عن إسماعيل بن أبي كريمة، قال: حدثنا محمد بن سَلمة، عن أبي سِنان، عن عمرو بن مُرّة، عن أبي البَخْتريّ، عن الحارث، عن عليّ، عن النبي ﷺ، مثله  .\n\n١٧٦ - وحدثنا أحمد بن إسحاق الأهوازي، قال: حدثنا أبو أحمد الزُّبيري، قال: حدثنا حمزة الزيات، عن أبي المختار الطائي، عن أبن أخي الحارث الأعور، عن الحارث، عن عليّ، قال: \" الصِّراطُ المستقيم: كتاب الله تعالى ذكره  \".\n\n١٧٧ - حدثنا أحمد بن إسحاق الأهوازي، قال: حدثنا أبو أحمد الزبيري، قال: حدثنا سفيان -ح- وحدثنا محمد بن حُميد الرازي، قال. حدثنا مِهْران، عن سفيان، عن منصور عن أبي وائل، قال: قال عبد الله: \" الصِّراطُ المستقيم\" كتابُ الله  \".\n\n١٧٨ - حدثني محمود بن خِدَاشِ الطالَقاني، قال: حدثنا حُميد بن عبد الرحمن الرُّؤاسِي، قال: حدثنا علي والحسن ابنا صالح، جميعًا، عن عبد الله بن محمد بن عَقِيل، عن جابر بن عبد الله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ قال: الإسلام، قال: هو أوسع مما بين السماء والأرض  .\n\n١٧٩ - حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمَارة، قال: حدثنا أبو رَوق، عن الضحّاك، عن عبد الله بن عباس، قال: قال جبريل لمحمد: قل يا محمد: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ يقول: ألهمنا الطريقَ الهادي، وهو دين الله الذي لا عوج له  .\n\n١٨٠ - حدثنا موسى بن سهل الرازي، قال: حدثنا يحيى بن عوف، عن الفُرَات بن السائب، عن ميمون بن مِهْران، عن ابن عباس، في قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ قال: ذلك الإسلام  .\n\n١٨١ - حدثني محمود بن خِدَاش، قال: حدثنا محمد بن ربيعة الكِلابي، عن إسماعيل الأزرق، عن أبي عُمر البزّار، عن ابن الحنفية، في قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ قال: هو دين الله الذي لا يقبل من العِباد غيرَه  .\n\n١٨٢ - حدثني موسى بن هارون الهمداني، قال: حدّثنا عَمرو بن طلحة القنَّاد، قال: حدثنا أسباط، عن السدِّي -في خبر ذكره- عن أبي مالك، وعن أبي صالح، عن ابن عباس -وعن مُرّة الهمداني، عن ابن مسعود -وعن ناس من أصحاب النبي ﷺ: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ قال: هو الإسلام\n\n١٨٣ - حدثنا القاسم بن الحسن، قال: حدثنا الحسين بن داود، قال: حدثني حجاج، عن ابن جُريج، قال: قال ابن عباس في قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ قال: الطريق  .\n\n١٨٤ - حدثنا عبد الله بن كثير أبو صديف الآمُلي، قال: حدثنا هاشم بن القاسم، قال: حدثنا حمزة بن المغيرة، عن عاصم، عن أبي العالية، في قوله: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ ، قال: هو رسول الله ﷺ، وصاحباه من بعدِه أبو بكر وعمر. قال: فذكرتُ ذلك للحسن، فقال: صدَق أبو العالية ونصح\n\n١٨٥- حدثني يونس بن عبد الأعلى، قال: حدثنا ابن وهب، قال: قال عبد الرحمن بن زيد بن أسلم: \" اهدنا الصراط المستقي\"، قال: الإسلام  .\n\n١٨٦- حدثنا المثنى، قال: حدثنا أبو صالح، قال: حدثني معاوية بن صالح، أنّ عبد الرحمن بن جُبير، حدّثه عن أبيه، عن نَوَّاس بن سمعان الأنصاري، عن رسول الله ﷺ قال: ضرب الله مثلا صراطًا مستقيمًا \". والصِّراط: الإسلامُ.\n\n١٨٧ - حدثنا المثنى، قال: حدثنا آدم العسقلاني، قال: حدثنا الليث، عن معاوية بن صالح، عن عبد الرحمن بن جبير بن نُفير، عن أبيه، عن نَوَّاس بن سمعان الأنصاري، عن النبي ﷺ، بمثله  .\n\nقال أبو جعفر: وإنما وصفه الله بالاستقامة، لأنه صواب لا خطأ فيه. وقد زعم بعض أهل الغباء، أنه سمّاه مستقيمًا، لاستقامته بأهله إلى الجنة. وذلك تأويلٌ لتأويل جميع أهل التفسير خلافٌ، وكفى بإجماع جميعهم على خلافه دليلا على خطئه.","7":"القول في تأويل قوله: ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾ .\n\nوقوله ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾ ، إبانةٌ عن الصراط المستقيم، أيُّ الصراط هو؟ إذْ كان كلّ طريق من طرُق الحق صراطًا مستقيمًا. فقيل لمحمد ﷺ: قُلْ يا محمد: اهدنا يا ربنا الصراط المستقيم، صراط الذين أنعمت عليهم، بطاعتك وعبادتك، من مَلائكتك وأنبيائك والصديقين والشهداء والصالحين.\n\nوذلك نظير ما قال ربنا جلّ ثناؤه في تنزيله: (وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَهُمْ وَأَشَدَّ تَثْبِيتًا وَإِذًا لآتَيْنَاهُمْ مِنْ لَدُنَّا أَجْرًا عَظِيمًا وَلَهَدَيْنَاهُمْ صِرَاطًا مُسْتَقِيمًا وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ) [سورة النساء: ٦٦-٦٩] .\n\nقال أبو جعفر: فالذي أمِر محمدٌ ﷺ وأمّتُه أن يسألوا ربَّهم من الهداية للطريق المستقيم، هي الهداية للطريق الذي وَصف الله جلّ ثناؤه صفتَه. وذلك الطريق، هو طريق الذي وَصفهم الله بما وصفهم به في تنزيله، ووعد من سَلكه فاستقام فيه طائعًا لله ولرسوله ﷺ، أن يورده مواردهم، والله لا يخلف الميعاد.\n\nوبنحو ما قلنا في ذلك رُوِي الخبر عن ابن عباس وغيره.\n\n١٨٨ - حدثنا محمد بن العلاء، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمَارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن ابن عباس: \"صراطَ الذين أنعمت عليهم\" يقول: طَريقَ من أنعمتَ عليهم بطاعتك وعبادتك من الملائكة والنبيين والصديقين والشهداء والصالحين، الذين أطاعوك وعبَدُوك  .\n\n١٨٩ - حدثني أحمد بن حازم الغفاري، قال: أخبرنا عبيد الله بن موسى، عن أبي جعفر عن ربيع: \"صراط الذين أنعمتَ عليهم\"، قال: النبيّون  .\n\n١٩٠ - حدثني القاسم، قال: حدثنا الحسين، قال: حدثني حجاج عن ابن جريج، قال: قال ابن عباس: \"أنعمت عليهم \" قال: المؤمنين  .\n\n١٩١- حدثنا القاسم، قال: حدثنا الحسين، قال: قال وكيع: \"أنعمت عليهم\"، المسلمين  .\n\n١٩٢- حدثني يونس بن عبد الأعلى، قال: أخبرنا ابن وهب، قال: قال عبد الرحمن بن زيد في قول الله \" صراط الذين أنعمت عليهم \"، قال: النبيّ ﷺ ومن معه  .\n\nقال أبو جعفر: وفي هذه الآية دليلٌ واضح على أنّ طاعة الله جَلّ ثناؤه لا ينالها المُطيعون إلا بإنعام الله بها عليهم، وتوفيقه إياهم لها. أوَ لا يسمعونه يقول: \"صراط الذين أنعمت عليهم\"، فأضاف كلّ ما كان منهم من اهتداء وطاعة وعبادة إلى أنه إنعام منه عليهم؟\n\nفإن قال قائل: وأين تمام هذا الخبر؟ وقد علمتَ أنّ قول القائل لآخر: \"أنعمت عليك\"، مقتضٍ الخبرَ عمَّا أنعمَ به عليه، فأين ذلك الخبرُ في قوله: \"صراط الذين أنعمت عليهم\"؟ وما تلك النعمة التي أنعمها عليهم؟\n\nقيل له: قد قدّمنا البيان -فيما مضى من كتابنا هذا- عن إجراء العرب في منطقها ببعضٍ من بعض، إذا كان البعضُ الظاهر دالا على البعض الباطن وكافيًا منه. فقوله: \"صراط الذين أنعمتَ عليهم\" من ذلك. لأن أمرَ الله جل ثناؤه عبادَه بمسألته المعونةَ، وطلبهم منه الهدايةَ للصراط المستقيم، لما كان متقدّمًا قولَه: \"صراطَ الذين أنعمت عليهم\"، الذي هو إبانةٌ عن الصراط المستقيم وإبدالٌ منه -كان معلومًا أن النعمة التي أنعم الله بها على من أمَرنا بمسألته الهدايةَ لطريقهم، هو المنهاجُ القويمُ والصراطُ المستقيم، الذي قد قدّمنا البيان عن تأويله آنفًا، فكان ظاهرُ ما ظهر من ذلك - مع قرب تجاور الكلمتين- مغنيًا عن تكراره.\n\nكما قال نابغة بني ذبيان:\n\nكأَنَّك مِنْ جِمالِ بَنِي أُقَيْشٍ ... يُقَعْقَعُ خَلْفَ رِجْلَيْهِ بشَنِّ\n\nيريد: كأنك من جمال بني أقيش، جملٌ يُقعقع خلف رجليه بشنّ، فاكتفى بما ظهر من ذكر \"الجمال\" الدال على المحذوف، من إظهار ما حذف. وكما قال الفرزدق بن غالب:\n\nتَرَى أَرْباقَهُمْ مُتَقَلِّدِيها ... إِذا صَدِئَ الحديدُ عَلَى الكُمَاةِ\n\nيريد: متقلديها هم، فحذف \"هم \"، إذ كان الظاهرُ من قوله أرباقَهُم، دالا عليها.\n\nوالشواهد على ذلك من شعر العرب وكلامها أكثر من أن تحصى. فكذلك ذلك في قوله: \"صراط الذين أنعمت عليهم\".\n\n* *\n\nالقول في تأويل قوله: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ﴾ .\n\nقال أبو جعفر: والقرَأةُ مجمعةٌ على قراءة \" غير \" بجر الراء منها  . والخفضُ يأتيها من وجهين:\n\nأحدهما: أن يكون \"غير\" صفة لِ\"الذين\" ونعتًا لهم فتخفضها. إذ كان \" الذين \" خفضًا، وهي لهم نعتٌ وصفةٌ. وإنما جاز أن يكون \" غير \" نعتًا لِـ \" الذين \"، و \" الذين \" معرفة و\"غير\" نكرة، لأن \" الذين \" بصلتها ليست بالمعرفة المؤقتة كالأسماء التي هي أماراتٌ بين الناس، مثل: زيد وعمرو، وما أشبه ذلك  ؛ وإنما هي كالنكرات المجهولات، مثل: الرجل والبعير، وما أشبه ذلك. فلما كان \" الذين \" كذلك صفتُها، وكانت \"غير\" مضافةً إلى مجهول من الأسماء، نظيرَ \" الذين \"، في أنه معرفة غير موقتة، كما \" الذين \" معرفة غير مؤقتة - جاز من أجل ذلك أن يكون \"غير المغضوب عليهم\" نعتًا لِ \"الذين أنعمت عليهم\" كما يقال: \" لا أجلس إلا إلى العالم غير الجاهل\"، يراد: لا أجلس إلا إلى مَن يعلم، لا إلى مَن يجهل.\n\nولو كان \"الذين أنعمت عليهم\" مَعرفة موقتة. كان غير جائز أن يكون \"غير المغضوب عليهم\" لها نعتًا. وذلك أنه خطأ في كلام العرب - إذا وصفت معرفة مؤقَّتة بنكرة- أن تُلْزِم نَعتها النكرةَ إعرابَ المعرفة المنعوت بها، إلا على نية تكرير ما أعربَ المنعوتَ بها. خطأ في كلامهم أن يقال: \"مررت بعبد الله غير العالم\"، فتخفض \" غير \"، إلا على نية تكرير الباء التي أعرَبتْ عبد الله. فكان معنى ذلك لو قيل كذلك: مَرَرتُ بعبد الله، مررت بغيرِ العالم. فهذا أحد وجهي الخفض في: \"غير المغضوب عليهم\".\n\nوالوجهُ الآخر من وجهي الخفض فيها: أن يكون \" الذين \" بمعنى المعرفة المؤقتة. وإذا وُجِّه إلى ذلك، كانت \"غير\" مخفوضةً بنية تكرير \"الصراط\" الذي خُفِض \"الذين\" عليها، فكأنك قلت: صراطَ الذين أنعمت عليهم، صراطَ غير المغضوب عليهم.\n\nوهذان التأويلان في \"غير المغضوب عليهم\"، وإن اختلفا باختلاف مُعرِبَيْهما، فإنهما يتقارب معناهما. من أجل أنَّ من أنعم الله عليه فهداه لدينه الحق، فقد سلم من غضب رَبه ونجا من الضلال في دينه.\n\nفسواءٌ - إذ كان سَبب قوله: \"اهدنا الصراط المستقيم صراط الذين أنعمت عليهم\" غيرَ جائزٍ أن يرتاب، مع سماعه ذلك من تاليه، في أن الذين أنْعم الله عليهم بالهداية للصِّراط غيرُ غاضب ربُّهم عليهم، مع النعمة التي قد عظمت مِنَّته بها عليهم في دينهم؛ ولا أن يكونوا ضُلالا وقد هداهم الحقَّ ربُّهم. إذْ كان مستحيلا في فِطَرِهم اجتماعُ الرضَى من الله جلّ ثناؤه عن شخص والغضب عليه في حال واحدة، واجتماعُ الهدى والضلال له في وقت واحد - أوُصِف  القوم؛ معَ وَصْف الله إياهم بما وصفهم به من توفيقه إياهم وهدايته لهم، وإنعامه عَليهم بما أنعم الله به عليهم في دينهم، بأنهم غيرُ مغضوب عليهم ولا هم ضَالُّون؛ أم لم يوصفوا بذلك. لأن الصِّفة الظاهرة التي وُصفوا بها، قد أنبأت عنهم أنهم كذلك، وإن لم يصرِّح وصفَهُم به.\n\nهذا، إذا وجَّهنا \" غير \" إلى أنها مخفوضة على نية تكرير \"الصراطِ\" الخافضِ \"الذين\"، ولم نجعل \"غير المغضوب عليهم ولا الضالين\" من صفة \"الذين أنعمت عليهم\"، بل إذا حملناهم غيرَهم. وإن كان الفريقان لا شك مُنْعَمًا عليهما في أدْيانهم.\n\nفأمّا إذا وجهنا \"غير المغضوب عليهم ولا الضالين\" إلى أنها من نَعت، \"الذين أنعمت عليهم\". فلا حاجة بسامعه إلى الاستدلال، إذْ كان الصريحُ من معناه قد أغنى عن الدليل.\n\nوقد يجوز نصب \" غير \" في \"غير المغضوب عليهم\"، وإن كنتُ للقراءة بها كارهًا لشذوذها عن قراءة القُرّاء. وإنَّ ما شذ من القراءات عما جاءت به الأمة نقلا ظاهرًا مستفيضًا، فرأيٌ للحق مخالف. وعن سبيل الله وسبيل رسوله ﷺ وسبيل المسلمين مُتجانفٌ. وإن كان له - لو كانت جائزًا القراءةُ به  - في الصواب مخرجٌ.\n\nوتأويل وجه صوابه إذا نصبتَ: أن يوجَّه إلى أن يكون صفةً للهاء والميم اللتين في \" عليهم \" العائدة على \" الذين \". لأنها وإن كانت مخفوضة بِ \" على \"، فهي في محل نصب يقوله: \" أنعمت \". فكأن تأويل الكلام -إذا نصبت \" غير \" التي مع \" المغضوب عليهم\"-: صراطَ الذين هَدَيتهم إنعامًا منك عليهم، غيرَ مغَضوبٍ عليهم، أي لا مغضوبًا عليهم ولا ضالين. فيكون النصب في ذلك حينئذ، كالنصب في \" غير \" في قولك: مررت بعبد الله غيرَ الكريم ولا الرشيدِ، فتقطع \"غيرَ الكريم\" من \"عبد الله\"، إذْ كان \"عبدُ الله\" معرفة مؤقتة، و\"غير الكريم\" نكرة مجهولة.\n\nوقد كان بعضُ نحويِّي البصريين يزعم أنّ قراءة مَنْ نصب \" غير \" في \"غير المغضوب عليهم\"، على وَجه استثناءِ \"غير المغضوب عليهم\" من معاني صفة \"الذين أنعمت عليهم\"، كأنه كان يرى أنّ معنى الذين قرأوا ذلك نصبًا: اهدنا الصراط المستقيم، صراطَ الذين أنعمتَ عليهم، إلا المغضوبَ عَليهم -الذين لم تُنعم عليهم في أديانهم ولم تَهْدهم للحق- فلا تجعلنا منهم. كما قال نابغة بني ذبيان:\n\nوَقَفْتُ فِيهَا أُصَيْلالا أُسَائِلُها ... عَيَّت جَوابًا، ومَا بالرَّبْعِ مِنْ أَحَدِ  إلا أَوَارِيَّ لأيًا مَا أُبَيِّنُهُا ... والنُّؤْيُ كالحَوْضِ بالمَظْلُومَةِ الجَلَدِ\n\nوالأواريُّ معلومٌ أنها ليست من عِدَاد \"أحد\" في شيء. فكذلك عنده، استثنى \"غير المغضوب عليهم\" من \"الذين أنعمت عليهم\"، وإن لم يكونوا من معانيهم في الدين في شيء.\n\nوأما نحِويُّو الكوفيين، فأنكروا هذا التأويل واستخفُّوه  ، وزعموا أن ذلك لو كان كما قاله الزاعم من أهل البصرة، لكان خطأ أن يقال: \"ولا الضالين\".\n\nلأن \" لا \" نفي وجحد، ولا يعطف بجحد إلا على جحد. وقالوا: لم نجد في شيء من كلام العرب استثناءً يُعطف عليه بجحد، وإنما وجدناهم يعطفون على الاستثناء بالاستثناء، وبالجحد على الجحد، فيقولون في الاستثناء: قام القومُ إلا أخاك وإلا أباك.\n\nوفي الجحد: ما قام أخوك ولا أبوك. وأما: قام القومُ إلا أباك ولا أخاك. فلم نجده في كلام العرب. قالوا: فلما كان ذلك معدومًا في كلام العرب، وكان القرآن بأفصح لسان العرب نزولُه، علمنا -إذ كان قولُه\"ولا الضالين\" معطوفًا على قوله\"غير المغضوب عليهم\" -أن \" غير \" بمعنى الجحد لا بمعنى الاستثناء، وأن تأويل من وجَّهها إلى الاستثناء خطأ.\n\nفهذه أوجه تأويل \"غير المغضوب عليهم\"، باختلاف أوجه إعراب ذلك.\n\nوإنما اعترضْنا بما اعترضنا في ذلك من بَيان وُجوه إعرابه- وإن كان قصدُنا في هذا الكتاب الكشفَ عن تأويل آي القرآن- لما في اختلاف وجوه إعراب ذلك من اختلاف وجوه تأويله. فاضطرّتنا الحاجة إلى كشف وجوه إعرابه، لتنكشف لطالب تأويله وُجوه تأويله، على قدر اختلاف المختلفة في تأويله وقراءته.\n\nوالصَّوابُ من القول في تأويله وقراءته عندنا، القول الأول، وهو قراءةُ ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ﴾ بخفض الراء من \" غير \". بتأويل أنها صفة لِ \"الذين أنعمت عليهم\" ونعتٌ لهم -لما قد قدمنا من البيان- إن شئتَ، وإن شئت فبتأويلِ تكرار \" صراط \". كلُّ ذلك صوابٌ حَسنٌ.\n\nفإن قال لنا قائل: فمنْ هؤلاء المغضوبُ عليهم، الذين أمرنا الله جل ثناؤه بمسألته أن لا يجعلنا منهم؟\n\nقيل: هم الذين وصفهم الله جَلّ ثناؤه في تنزيله فقال: ﴿قُلْ هَلْ أُنَبِّئُكُمْ بِشَرٍّ مِنْ ذَلِكَ مَثُوبَةً عِنْدَ اللَّهِ مَنْ لَعَنَهُ اللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ الْقِرَدَةَ وَالْخَنَازِيرَ وَعَبَدَ الطَّاغُوتَ أُولَئِكَ شَرٌّ مَكَانًا وَأَضَلُّ عَنْ سَوَاءِ السَّبِيلِ﴾ [سورة المائدة: ٦٠] . فأعلمنا جلّ ذكره ثَمَّة  ، ما أحَلَّ بهم من عقوبته بمعصيتهم إياه. ثم علمنا، منّهً منه علينا، وجه السبيل إلى النجاة من أن يَحِلَّ بنا مثل الذي حَلّ بهم من المَثُلات، ورأفة منه بنا  .\n\nفإن قيل: وما الدليلُ على أنهم أولاء الذين وصفَهم الله وذكر نبأهم في تنزيله على ما وصفت؟ قيل:\n\n١٩٣ - حدثني أحمد بن الوليد الرملي، قال: حدثنا عبد الله بن جعفر الرقي، قال: حدثنا سفيان بن عيينة، عن إسماعيل بن أبي خالد، عن الشعبي، عن عديّ بن حاتم، قال: قال لي رسول الله ﷺ: المغضوبُ عليهم، اليهود  .\n\n١٩٤- حدثنا محمد بن المثنى، قال: حدثنا محمد بن جعفر، قال: حدثنا شعبة، عن سماك بن حرب، قال: سمعت عباد بن حُبيش يحدث، عن عدي بن حاتم، قال: قال لي رسول الله ﷺ: إنّ المغضوبَ عليهم اليهود  .\n\n١٩٥- حدثني علي بن الحسن، قال: حدثنا مسلم بن عبد الرحمن، قال: حدثنا محمد بن مصعب، عن حماد بن سلمة، عن سماك بن حرب، عن مُرِّي بن قَطَريّ، عن عدي بن حاتم، قال: سألت النبي ﷺ عن قول الله جلّ وعزّ \"غير المغضوب عليهم\" قال: هم اليهود  .\n\n١٩٦ - حدثنا حُميد بن مَسْعَدة السّامي، قال: حدثنا بشر بن المفضَّل، قال: حدثنا الجُرَيْري، عن عبد الله بن شَقِيق: أنّ رُجلا أتى رسول الله ﷺ وهو محاصرٌ واديَ القُرَى، فقال: مَنْ هؤلاء الذين تحاصرُ يا رسول الله؟ قال: هؤلاء المغضوب عليهم، اليهود  .\n\n١٩٧- حدثني يعقوب بن إبراهيم، قال: حدثنا ابن عُلَّية، عن سعيد الجُرَيْري، عن عروة، عن عبد الله بن شَقيق: أن رجلا أتى رسول الله ﷺ، فذكر نحوه.\n\n١٩٨- حدثنا الحسن بن يحيى، قال: أنبأنا عبد الرزّاق، قال: أخبرنا معمر، عن بُدَيْل العقيلي، قال: أخبرني عبد الله بن شَقيق: أنه أخبره من سمع النبي ﷺ -وهو بوادي القُرَى، وهو عَلى فَرسه، وسأله رجل من بني القَين فقال: يا رسول الله، من هؤلاء؟ - قال: المغضوبُ عليهم. وأشار إلى اليهود  .\n\n١٩٩- حدثنا القاسم بن الحسن، قال: حدثنا الحسين، قال: حدثنا خالد الواسطي، عن خالد الحَذَّاء، عن عبد الله بن شقيق، أنّ رجلا سأل النبي ﷺ، فذكر نحوه\n\n٢٠٠ - حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، قال: حدثنا بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن ابن عباس: \"غير المغضوب عليهم\"، يعني اليهودَ الذين غَضب الله عليهم  .\n\n٢٠١- حدثني موسى بن هارون الهمداني، قال: حدثنا عمرو بن طلحة، قال: حدثنا أسباط بن نصر، عن السدّيّ في خبر ذكره، عن أبي مالك، وعن أبي صالح عن ابن عباس -وعن مرة الهمداني عن ابن مسعود- وعن ناس من أصحاب النبي ﷺ: \"غير المغضوب عليهم\"، هم اليهود  .\n\n٢٠٢- حدثنا ابن حميد الرازي، قال: حدثنا مهران، عن سفيان، عن مجاهد، قال: \"غير المغضوب عليهم\"، قال: هم اليهود.\n\n٢٠٣- حدثنا أحمد بن حازم الغفاري، قال: حدثنا عبد الله، عن أبي جعفر، عن ربيع: \"غير المغضوب عليهم\"، قال: اليهود.\n\n٢٠٤- حدثنا القاسم، قال: حدثنا الحسين، قال: حدثني حجاج، عن ابن جريج، قال: قال ابن عباس: \"غير المغضوب عليهم\" قال: اليهود.\n\n٢٠٥- حدثني يونس بن عبد الأعلى، قال: أخبرنا ابن وهب، قال: قال ابن زيد: \"غير المغضوب عليهم\"، اليهود.\n\n٢٠٦- حدثني يونس، قال: أخبرنا ابن وهب، قال: حدثني ابن زيد، عن أبيه، قال: \"المغضوب عليهم\"، اليهود  .\n\nقال أبو جعفر: واختُلِف في صفة الغضب من الله جلّ ذكره:\n\nفقال بعضهم: غضبُ الله على من غضب عليه من خلقه، إحلالُ عقوبته بمن غَضبَ عليه، إمّا في دنياه، وإمّا في آخرته، كما وصف به نفسه جلّ ذكره في كتابه فقال: ﴿فَلَمَّا آسَفُونَا انْتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ﴾ [سورة الزخرف: ٥٥] .\n\nوكما قال: (قُلْ هَلْ أُنَبِّئُكُمْ بِشَرٍّ مِنْ ذَلِكَ مَثُوبَةً عِنْدَ اللَّهِ مَنْ لَعَنَهُ اللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ الْقِرَدَةَ وَالْخَنَازِيرَ) [سورة المائدة: ٦٠] .\n\nوقال بعضهم: غضب الله على من غضب عليه من عباده، ذم منه لهم ولأفعالهم، وشتم لهم منه بالقول.\n\nوقال بعضهم: الغضب منه معنى مفهوم، كالذي يعرف من معاني الغضب، غير أنه -وإن كان كذلك من جهة الإثبات  - فمخالف معناه منه معنى ما يكون من غضب الآدميين الذين يزعجهم ويحركهم ويشق عليهم ويؤذيهم.\n\nلأن الله جل ثناؤه لا تحل ذاته الآفات، ولكنه له صفة، كما العلم له صفة، والقدرة له صفة، على ما يعقل من جهة الإثبات، وإن خالفت معاني ذلك معاني علوم العباد، التي هي معارف القلوب، وقواهم التي توجد مع وجود الأفعال وتعدم مع عدمها  .\n\n* *\n\nالقول في تأويل قوله جل ثناؤه: ﴿وَلا الضَّالِّينَ﴾ .\n\nقال أبو جعفر: كان بعض أهل البصرة يزعم أن \" لا \" مع \" الضالين \" أدخلت تتميما للكلام، والمعنى إلغاؤها، يستشهد على قيله ذلك ببيت العجاج: فِي بِئْرِ لاحُورٍ سَرَى وَمَا شَعَرْ\n\nويتأوله بمعنى: في بئر حور سرى، أي في بئر هلكة، وأن \" لا \" بمعنى الإلغاء والصلة. ويعتل أيضا لذلك بقول أبي النجم:\n\nفَمَا أَلُومُ الْبِيضَ أَنْ لا تَسْخَرَا ... لَمَّا رَأَيْنَ الشَّمْطَ الْقَفَنْدَرَا\n\nوهو يريد: فما ألوم البيض أن تسخر وبقول الأحوص:\n\nوَيَلْحَيْنَنِي فِي اللَّهْوِ أَنْ لا أُحِبَّه ... وَللَّهْوُ دَاعٍ دَائِبٌ غَيْرُ غَافِلِ\n\nيريد: وَيلحينني في اللهو أن أحبه، وبقوله تعالى: ﴿مَا مَنَعَكَ أَلا تَسْجُدَ﴾ [سورة الأعراف: ١٢] ، يريد أن تسجد. وحُكي عن قائل هذه المقالة أنه كان يتأول \" غير \" التي \" مع \"المغضوب عليهم \"، أنها بمعنى \" سوى  . فكأنّ معنى الكلام كانَ عنده: اهدنا الصراط المستقيمَ، صراط الذين أنعمتَ عليهم، الذين همُ سوى المغضوب والضالين.\n\nوكان بعضُ نحويي الكوفة يستنكر ذلك من قوله  ، ويزعمُ أن \" غير \" التي \" مع المغضوب عليهم \"، لو كانت بمعنى سوى، لكان خطأ أن يعطف عليها بـ \" لا \"، إذْ كانت \" لا \" لا يعطف بها إلا على جحد قد تقدمها. كما كان خطأ قول القائل: \"عندي سِوَى أخيك ولا أبيك\"، لأن سِوَى ليست من حروف النفي والجحود. ويقول: لما كان ذلك خطأ في كلام العرب، وكان القرآن بأفصحِ اللغات من لغات العرب، كان معلومًا أن الذي زَعمه القائل: أن \"غير\" مع \"المغضوب عليهم\" بمعنى: سوى المغضوب عليهم، خطأ. إذ كان قد كرّ عليه الكلامَ بـ \" لا \". وكان يزعم أن \" غير \" هنالك إنما هي بمعنى الجحد. إذْ كان صحيحًا في كلام العرب، وفاشيًا ظاهرًا في منطقها توجيه \" غير \" إلى معنى النفي ومستعملا فيهم: \"أخوك غير مُحسِن ولا مُجْمِل\"، يراد بذلك أخوك لا محسن، ولا مجمل، ويَستنكرُ أن تأتي \" لا \" بمعنى الحذف في الكلام مُبتدأً، ولمَّا يتقدمها جحد. ويقول: لو جاز مجيئها بمعنى الحذف مُبتدأ، قبل دلالة تدلّ ذلك من جحد سابق، لصحَّ قول قائل قال: \"أردْتُ أن لا أكرم أخاك\"، بمعنى: أردت أن أكرم أخاك. وكان يقول: ففي شهادة أهل المعرفة بلسان العرب على تخطئة قائل ذلك، دلالةٌ واضحة على أنَّ \" لا \" تأتي مبتدأة بمعنى الحذف، ولَمَّا يتقدَّمها جحد. وكان يتأوّل في \" لا \" التي في بيت العجاج، الذي ذكرنا أن البصْريّ استشهد به، بقوله: إنها جَحْدٌ صحيح، وأنّ معنى البيت: سَرَى في بئر لا تُحيرُ عليه خيرًا، ولا يتبيَّن له فيها أثرُ عملٍ، وهو لا يشعُر بذلك ولا يدري به  . من قولهم: \"طحنت الطَّاحنة فما أحارت شيئًا\"، أي لم يتبيَّن لها أثرُ عملٍ. ويقول في سائر الأبيات الأخر، أعني مثل بَيت أبي النجم:\n\nفما ألُوم البيضَ أن لا تسخَرَا\n\nإنما جاز أن تكون \" لا \" بمعنى الحذف، لأن الجحد قد تقدمها في أول الكلام، فكان الكلام الآخر مُواصِلا للأول، كما قال الشاعر:\n\nمَا كَانَ يَرْضَى رَسُولُ اللهِ فِعْلَهُمُ ... وَالطَّيِّبَانِ أَبُو بَكْرٍ وَلا عُمَرُ\n\nفجازَ ذلك، إذْ كان قد تقدَّم الجحدُ في أوّل الكلام.\n\nقال أبو جعفر: وهذا القولُ الآخر أولى بالصواب من الأول، إذ كان غيرَ موجودٍ في كلام العرب ابتداءُ الكلام من غير جحد تقدَّمه بـ \" لا \" التي معناها الحذف، ولا جائزٍ العطفُ بها على \" سوى \"، ولا على حرف الاستثناء. وإنما لِـ \" غير \" في كلام العرب معان ثلاثة: أحدها الاستثناء، والآخر الجحد، والثالث سوى. فإذا ثبت خطأ \" لا \" أن يكون بمعنى الإلغاء مُبتدأ  ، وفسدَ أن يكون عطفًا على \" غير \" التي مع \" المغضوب عليهم \"، لو كانت بمعنى \" إلا \" التي هي استثناء، ولم يَجز أيضًا أن يكون عطفًا عليها لو كانت بمعنى \" سوى \"، وكانت \" لا \" موجودة عطفًا بالواو التي هي عاطفة لها على ما قَبلها -صحَّ  وثبت أن لا وجهَ لـ \" غير \"، التي مع \" المغضوب عليهم \"، يجوز توجيهها إليه على صحَّة إلا بمعنى الجحد والنفي، وأن لا وَجه لقوله: \" ولا الضالين \"، إلا العطف على \" غير المغضوب عليهم \".\n\nفتأويلُ الكلام إذًا - إذْ كان صحيحًا ما قلنا بالذي عليه استشهدنا- اهدنا الصراط المستقيم، صراط الذين أنعمت عليهم، لا المغضوب عليهم ولا الضالين.\n\nفإن قال لنا قائل: ومَن هؤلاء الضَّالُّون الذين أمرنا اللهُ بالاستعاذة بالله أن يَسْلُكَ بنا سبيلهم، أو نَضِلَّ ضلالهم؟\n\nقيل: هم الذين وصَفهم الله في تنزيله فقال: (قُلْ يَا أَهْلَ الْكِتَابِ لا تَغْلُوا فِي دِينِكُمْ غَيْرَ الْحَقِّ وَلا تَتَّبِعُوا أَهْوَاءَ قَوْمٍ قَدْ ضَلُّوا مِنْ قَبْلُ وَأَضَلُّوا كَثِيرًا وَضَلُّوا عَنْ سَوَاءِ السَّبِيلِ) [سورة المائدة: ٧٧] .\n\nفإن قال: وما برهانك على أنهم أولاء؟\n\nقيل:\n\n٢٠٧- حدثنا أحمد بن الوليد الرملي، قال: حدثنا عبد الله بن جعفر، قال: حدثنا سفيان بن عيينة، عن إسماعيل بن أبي خالد، عن الشَّعبي، عن عدي بن أبي حاتم، قال: قال رسول الله ﷺ: \"ولا الضالين\" قال: النصارى  .\n\n٢٠٨- حدثنا محمد بن المثنى، أنبأنا محمد بن جعفر، أنبأنا شعبة، عن سِمَاك، قال: سمعت عبّاد بن حُبيش يحدث، عن عدي بن حاتم، قال: قالَ لي رسول الله ﷺ: \"إن الضَّالين: النَّصارى \".\n\n٢٠٩ - حدثني علي بن الحسن، قال: حدثنا مسلم بن عبد الرحمن، قال: حدثنا محمد بن مُصْعَب، عن حماد بن سلمة، عن سماك بن حرب، عن مُرّيّ بن قَطَريّ، عن عدي بن حاتم، قال: سألت النبي ﷺ عن قول الله: \"ولا الضالين\"، قال: النصارى هم الضالون.\n\n٢١٠- حدثنا حُميد بن مَسعدة السَّامي، قال: حدثنا بشر بن المفضَّل، قال: حدثنا الجريري، عن عبد الله بن شقيق: أن رجلا أتى رسول الله ﷺ وهو محاصرٌ واديَ القُرَى قال: قلت: من هؤلاء؟ قال: هؤلاء الضّالون: النصارى.\n\n٢١١ - حدثنا يعقوب بن إبراهيم، قال: حدثنا ابنُ عُلَيَّة، عن سعيد الجُرَيري، عن عروة، يعني ابن عبد الله بن قيس، عن عبد الله بن شقيق، عن رسول الله ﷺ بنحوه  .\n\n٢١٢ - حدثنا الحسن بن يحيى، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن بُدَيْل العُقَيلي، قال: أخبرني عبد الله بن شقيق، أنه أخبره من سَمع النبي ﷺ وهو بوادي القرى وهو على فرسه وسأله رجل من بني القَين، فقال: يا رسولَ الله، من هؤلاء؟ - قال: هؤلاء الضَّالون \"، يعني النصارى.\n\n٢١٣ - حدثنا القاسم قال: حدثنا الحسين، قال: حدثنا خالد الواسطي، عن خالد الحذاء، عن عبد الله بن شقيق، أن رجلا سأل النبي ﷺ، وهو محاصرٌ وادي القُرى وهو على فرس: من هؤلاء؟ قال: الضالّون. يعني النصارى.\n\n٢١٤- حدثنا محمد بن حميد، قال: حدثنا مهران، عن سفيان، عن مجاهد: \"ولا الضالين\" قال: النصارى.\n\n٢١٥- حدثنا أبو كريب، قال: حدثنا عثمان بن سعيد، عن بشر بن عُمارة، قال: حدثنا أبو رَوْق، عن الضحاك، عن ابن عباس: \"ولا الضالين\" قال: وَغير طريقِ النَّصارى الذين أضلَّهم الله بِفرْيَتهمْ عليه. قال: يقول: فألهِمنا دينك الحق، وهو لا إله إلا الله وحدَه لا شريك له، حتى لا تغضَبَ علينا كما غضبتَ على اليهود، ولا تضلَّنا كما أضللتَ النصارى فتعذّبنا بما تعذِّبهم به. يقول امنعْنا من ذلك برفْقِك ورَحمتك وقدرتك.\n\n٢١٦- حدثنا القاسم، قال: حدثنا الحسين، قال: حدثني حجاج، عن ابن جريج، قال: قال ابن عباس: الضالين النصارى.\n\n٢١٧- حدثني موسى بن هارون الهمداني، قال: حدثنا عمرو بن حماد، قال: حدثنا أسباط بن نصر، عن إسماعيل السدّيّ في خبر ذكره عن أبي مالك، وعن أبي صالح، عن ابن عباس - وعن مرة الهمداني، عن ابن مسعود- وعن ناس من أصحاب النبي ﷺ: \"ولا الضالين\"، هم النصارى.\n\n٢١٨- حدثني أحمد بن حازم الغِفاري، قال: أخبرنا عُبيد الله بن موسى، عن أبي جعفر، عن ربيع: \"ولا الضالين\"، النصارى.\n\n٢١٩- حدثني يونس بن عبد الأعلى، قال أخبرنا ابن وهب، قال: قال عبد الرحمن بن زيد: \"ولا الضالين\"، النصارى.\n\n٢٢٠- حدثنا يونس قال: أخبرنا ابن وهب، قال: حدثنا عبد الرحمن بن زيد، عن أبيه. قال: الضالين، النصارى.\n\n* *\n\nقال أبو جعفر: فكلّ حائدٍ عن قَصْد السبيل، وسالكٍ غيرَ المنهج القويم، فضَالٌّ عند العرب، لإضلاله وَجهَ الطريق. فلذلك سمى الله جل ذكره النصارَى ضُلالا لخطئهم في الحقِّ مَنهجَ السبيل، وأخذهم من الدِّين في غير الطريق المستقيم.\n\nفإن قال قائل: أوَ ليس ذلك أيضًا من صفة اليهود؟\n\nقيل: بلى!\n\nفإن قال: كيف خَصّ النصارَى بهذه الصفة، وَخصّ اليهودَ بما وصفَهم به من أنهم مغضوب عليهم؟\n\nقيل: كلا الفريقين ضُلال مغضوبٌ عليهم، غيرَ أن الله جلّ ثناؤه وَسم كل فريق منهم من صِفَته لعباده بما يعرفونه به، إذا ذكرهُ لهم أو أخبرهم عنه. ولم يسمِّ واحدًا من الفريقين إلا بما هو له صفةٌ على حقيقته، وإن كان له من صفاتِ الذمّ زياداتٌ عليه.\n\nفيظنُّ بعض أهل الغباء من القدريّة أن في وصف الله جلّ ثناؤه النصارى بالضّلال، بقوله: \"ولا الضالين\"، وإضافته الضَّلال إليهم دون إضافة إضلالهم إلى نفسه، وتركه وصفهم بأنهم المضلَّلون، كالذي وَصف به اليهود أنهم المغضوبُ عليهم -دلالةً على صحة ما قاله إخوانُه من جهلة القدرية، جهلا منه بسَعَة كلام العرب وتصاريف وُجوهه.\n\nولو كان الأمر على ما ظَنّه الغبي الذي وصفنا شأنه، لوجب أن يكونَ شأنُ كلِّ موصوفٍ بصفةٍ أو مضافٍ إليه فعلٌ، لا يجوزُ أن يكون فيه سببٌ لغيره، وأنْ يكون كلُّ ما كان فيه من ذلك لغيره سببٌ، فالحقُّ فيه أن يكون مضافًا إلى مُسبِّبه، ولو وَجب ذلك، لوجبَ أن يكون خطأ قولُ القائل: \" تحركت الشجرةُ \"، إذْ حرَّكتها الرياح؛ و \" اضطربت الأرض \"، إذْ حرَّكتها الزلزلة، وما أشبهَ ذلك من الكلام الذي يطولُ بإحصائه الكتاب.\n\nوفي قول الله جلّ ثناؤه: ﴿حَتَّى إِذَا كُنْتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِمْ﴾ [سورة يونس: ٢٢]-بإضافته الجريَ إلى الفلك، وإن كان جريها بإجراء غيرِها إيَّاها- ما دلّ على خطأ التأويل الذي تأوله من وصفنا قوله في قوله: \"ولا الضالين\"، وادّعائه أنّ في نسبة الله جلّ ثناؤه الضلالةَ إلى من نَسبها إليه من النصارى، تصحيحًا لما ادَّعى المنكرون: أن يكون لله جلّ ثناؤه في أفعال خلقه سببٌ من أجله وُجدت أفعالهم، مع إبانة الله عزّ ذكره نصًّا في آيٍ كثيرة من تنزيله، أنه المضلُّ الهادي، فمن ذلك قوله جل ثناؤه: ﴿أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلَهَهُ هَوَاهُ وَأَضَلَّهُ اللَّهُ عَلَى عِلْمٍ وَخَتَمَ عَلَى سَمْعِهِ وَقَلْبِهِ وَجَعَلَ عَلَى بَصَرِهِ غِشَاوَةً فَمَنْ يَهْدِيهِ مِنْ بَعْدِ اللَّهِ أَفَلا تَذَكَّرُونَ﴾ [سورة الجاثية: ٢٣] . فأنبأ جلّ ذكره أنه المضلّ الهادي دون غيره.\n\nولكنّ القرآن نزلَ بلسان العرب، على ما قدَّمنا البيان عنه في أول الكتاب، ومن شأن العرب إضافة الفعل إلى من وُجد منه -وإن كان مسبِّبُه غيرَ الذي وُجِد منه- أحيانًا، وأحيانًا إلى مسبِّبه، وإن كان الذي وجد منه الفعل غيرُه. فكيف بالفعل الذي يكتسبه العبد كسبًا، ويُوجِده الله جلّ ثناؤه عَيْنًا مُنْشَأةً؟ بل ذلك أحرى أن يُضاف إلى مكتسبِه؛ كسبًا له، بالقوة منه عليه، والاختيار منه له -وَإلى الله جلّ ثناؤه، بإيجاد عينِه وإنشائها تدبيرًا. ﴿مسألة يَسأل عنها أهل الإلحاد الطَّاعنون في القرآن﴾\n\nإن سألَنا منهم سائل فقال: إنك قد قدَّمتَ في أول كتابك هذا في وصْف البيان: بأنّ أعلاه درجة وأشرفَه مرتبة، أبلغُه في الإبانة عن حاجة المُبين به عن نفسه، وأبينُه عن مُراد قائله، وأقربُه من فهم سامعه. وقلتَ، مع ذلك: إنّ أوْلى البيان بأن يكون كذلك، كلامُ الله جل ثناؤه، لِفَضْله على سائر الكلام وبارتفاع دَرَجته على أعلى درجات البيان  ، فما الوجه -إذ كان الأمر على ما وصفت- في إطالة الكلام بمثل سورة أم القرآن بسبع آيات؟ وقد حوت معاني جميعها منها آيتان، وذلك قوله: ﴿مالك يوم الدين إياك نعبد وإياك نستعين﴾ ، إذْ كان لا شك أنّ من عَرف: مَلك يوم الدين، فقد عَرَفه بأسمائه الحسنى وصفاته المُثْلى. وأنّ من كان لله مطيعًا، فلا شك أنه لسبيل من أنعم الله عليه في دينه مُتَّبع، وعن سبيل من غَضِب عليه وضَلَّ مُنْعَدِل. فما في زيادة الآيات الخمس الباقية، من الحكمة التي لم تَحْوِها الآيتان اللتان ذكرنا؟\n\nقيل له: إنّ الله تعالى ذكرُه جَمع لنبينا محمد ﷺ ولأمته -بما أنزل إليه من كتابه- معانيَ لم يجمعْهُنّ بكتاب أنزله إلى نبيّ قبله، ولا لأمَّة من الأمم قبلهم. وذلك أنّ كُلّ كتاب أنزله جلّ ذكرُه على نبيّ من أنبيائه قبله، فإنما أنزل ببعض المعاني التي يحوي جميعَها كتابُه الذي أنزله إلى نبينا محمد ﷺ. كالتَّوراة التي هي مواعظ وتفصيل، والزَّبُور الذي هو تحميد وتمجيد، والإنجيل الذي هو مواعظ وتذكير -لا مُعجزةَ في واحد منها تشهد لمن أنزل إليه بالتصديق. والكتابُ الذي أنزل على نبيِّنا محمد ﷺ، يحوي معاني ذلك كله، ويزيد عليه كثيرًا من المعاني التي سائرُ الكتب غيرِه منها خالٍ.\n\nوقد قدَّمنا ذكرها فيما مضى من هذا الكتاب  .\n\nومن أشرفِ تلك المعاني التي فَضَل بها كتابُنا سائرَ الكتب قبله، نظْمُه العجيبُ ورصْفُه الغريب  وتأليفُه البديع؛ الذي عجزتْ عن نظم مثْلِ أصغرِ سورة منه الخطباء، وكلَّت عن وَصْف شكل بعضه البلغاء، وتحيَّرت في تأليفه الشُّعراء، وتبلَّدت -قصورًا عن أن تأتيَ بمثله- لديه أفهامُ الفُهماء، فلم يجدوا له إلا التسليمَ والإقرار بأنه من عند الواحد القهار. مع ما يحوي، مَع ذلك، من المعاني التي هي ترغيب وترهيب، وأمرٌ وزجرٌ، وقَصَص وجَدَل ومَثَل، وما أشبهَ ذلك من المعاني التي لم تجتمع في كتاب أنزل إلى الأرض من السماء.\n\nفمهما يكن فيه من إطالة، على نحو مَا في أمِّ القرآن  ، فلِما وصفتُ قبلُ من أن الله جل ذكره أرادَ أن يجمعَ - برَصْفه العجيب ونظْمِه الغريب، المنعدِلِ عن أوزان الأشعار، وسجْع الكُهَّان وخطب الخطباء ورَسائل البلغاء، العاجز عن رَصْف مثله جميع الأنام، وعن نظم نظيره كل العباد - الدلالةَ  على نبوة نبينا محمد ﷺ؛ وبما فيه من تحميد وتمجيد وثناء عليه، تنبيهَ  العباد على عَظمته وسلطانه وقدرته وعِظم مَملكته، ليذكرُوه بآلائه، ويحمدوه على نعمائه، فيستحقوا به منه المزيدَ، ويستوجبوا عليه الثوابَ الجزيل؛ وبما فيه من نَعْتِ من أنعم عليه بمعرفته، وتفضَّل عليه بتوفيقه لطاعته، تعريفَ  عباده أن كل ما بهم من نعمة، في دينهم ودنياهم، فمنه، ليصرفوا رَغبتهم إليه، ويبتغوا حاجاتهم من عنده دُون ما سواهُ من الآلهة والأنداد، وبما فيه من ذكره ما أحلّ بمن عَصَاه منْ مَثُلاته، وأنزل بمن خالف أمره من عقوباته -ترهيبَ  عباده عن ركوب معاصيه، والتعرُّضِ لما لا قِبَل لهم به من سَخَطه، فيسلكَ بهم في النكال والنَّقِمات سبيلَ من ركب ذلك من الهُلاك.\n\nفذلك وَجْه إطالة البيان في سورة أم القرآن، وفيما كان نظيرًا لها من سائر سور الفرقان. وذلك هو الحكمة البالغة والحجة الكاملة.\n\n* *\n\n٢٢١- حدثنا أبو كريب، قال: حدثنا المحاربي، عن محمد بن إسحاق، قال: حدثني العلاء بن عبد الرحمن بن يعقوب، عن أبي السائب مولى زُهْرة، عن أبي هريرة، قال: قال رسول الله ﷺ: إذا قال العبد: \"الحمد لله ربّ العالمين\"، قال الله: \"حمدني عبدي\". وإذا قال: \"الرحمن الرحيم\"، قال: \"أثنى عليّ عبدي\". وإذا قال: \"مالكِ يوم الدين\"، قال: \"مجَّدني عبدي. فهذا لي\". وإذا قَال: \"إيّاك نَعبُد وإيّاكَ نستعين\" إلى أن يختم السورة، قال: \"فذاكَ لهُ  .\n\n٢٢٢ - حدثنا أبو كريب، قال: حدثنا عبدة، عن ابن إسحاق، عن العلاء بن عبد الرحمن، عن أبي السائب، عن أبي هريرة، قال: إذا قال العبد: \"الحمد لله\"، فذكر نحوه، ولم يرفعه  .\n\n٢٢٣ - حدثنا أبو كريب، قال: حدثنا أبو أسامة، قال: حدثنا الوليد بن كثير، قال: حدثني العلاء بن عبد الرحمن مولى الحُرَقَة، عن أبي السائب، عن أبي هريرة عن رسول الله ﷺ، مثله  .\n\n٢٢٤- حدثني صالح بن مسمار المروزي، قال: حدثنا زيد بن الحُبَاب، قال: حدثنا عَنْبسة بن سعيد، عن مُطَرِّف بن طَرِيف، عن سعد بن إسحاق بن كعب بن عُجْرة، عن جابر بن عبد الله الأنصاري، قال: قال رسول الله ﷺ: قال الله عز وجلّ: \"قَسَمت الصلاة بيني وبين عبدي نِصْفين، وله ما سَأل\". فإذا قال العبد: \"الحمدُ لله ربّ العالمين\" قال الله: \"حمدَني عَبدي\"، وإذا قال: \"الرحمن الرحيم\"، قال: \"أثنى عليّ عَبدي\"، وإذا قال: \"مالكِ يَومِ الدين\" قال: \"مجَّدني عَبدي\" قال: \"هذا لي، وما بقي\"  . \"آخرُ تفسيرِ سُورَةِ فَاتِحةُ الكتابِ\"."},"78":{"1":"القول في تأويل قوله تعالى: ﴿عَمَّ يَتَسَاءَلُونَ (١) عَنِ النَّبَإِ الْعَظِيمِ (٢) الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ (٣) كَلا سَيَعْلَمُونَ (٤) ثُمَّ كَلا سَيَعْلَمُونَ (٥) ﴾\n\n.\n\nيقول تعالى ذكره: عن أي شيء يتساءل هؤلاء المشركون بالله ورسوله من قريش يا محمد، وقيل ذلك له ﷺ، وذلك أن قريشا جعلت فيما ذُكر عنها تختصم وتتجادل في الذي دعاهم إليه رسول الله ﷺ من الإقرار بنبوّته، والتصديق بما جاء به من عند الله، والإيمان بالبعث، فقال الله لنبيه: فيم يتساءل هؤلاء القوم ويختصمون، و\"في\" و\"عن\" في هذا الموضع بمعنى واحد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع بن الجراح، عن مِسعر، عن محمد بن جحادة، عن الحسن، قال: لما بُعِث النبيّ ﷺ جعلوا يتساءلون بينهم، فأنزل الله: ﴿عَمَّ يَتَسَاءَلُونَ عَنِ النَّبَإِ الْعَظِيمِ﴾ يعني: الخبر العظيم.\n\nقال أبو جعفر، ثم أخبر الله نبيه ﷺ عن الذي يتساءلونه، فقال: يتساءلون عن النبأ العظيم: يعني: عن الخبر العظيم.\n\nواختلف أهل التأويل في المعنيّ بالنبأ العظيم، فقال بعضهم: أريد به القرآن.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿عَنِ النَّبَإِ الْعَظِيمِ﴾ قال: القرآن.\n\nوقال آخرون: عني به البعث.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، في قوله: ﴿عَنِ النَّبَإِ الْعَظِيمِ﴾ وهو البعث بعد الموت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سعيد، عن قتادة ﴿عَنِ النَّبَإِ الْعَظِيمِ﴾ قال: النبأ العظيم: البعث بعد الموت.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿عَمَّ يَتَسَاءَلُونَ عَنِ النَّبَإِ الْعَظِيمِ الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ قال: يوم القيامة؛ قال: قالوا هذا اليوم الذي تزعمون أنا نحيا فيه وآباؤنا، قال: فهم فيه مختلفون، لا يؤمنون به، فقال الله: بل هو نبأ عظيم أنتم عنه معرضون: يوم القيامة لا يؤمنون به.\n\nوكان بعض أهل العربية يقول: معنى ذلك: عمّ يتحدّث به قريش في القرآن، ثم أجاب فصارت عمّ كأنها في معنى: لأيّ شيء يتساءلون عن القرآن، ثم أخبر فقال: ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ بين مصدق ومكذِّب، فذلك إخلافهم، وقوله: ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ يقول تعالى ذكره: الذي صاروا هم فيه مختلفون فريقين: فريق به مصدّق، وفريق به مكذّب. يقول تعالى ذكره: فتساؤلهم بينهم في النبأ الذي هذه صفته.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة: عن النبإ ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ البعث بعد الموت، فصار الناس فيه فريقين: مصدّق ومكذّب، فأما الموت فقد أقرّوا به لمعاينتهم إياه، واختلفوا في البعث بعد الموت.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ صار الناس فيه رجلين: مصدّق، ومكذّب، فأما الموت فإنهم أقروا به كلهم لمعاينتهم إياه، واختلفوا في البعث بعد الموت.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ قال: مصدّق ومكذّب.\n\n* *\n\nوقوله: ﴿كَلا﴾\n\nيقول تعالى ذكره: ما الأمر كما يزعم هؤلاء المشركون الذين ينكرون بعث الله إياهم أحياء بعد مماتهم، وتوعدهم جل ثناؤه على هذا القول منهم، فقال: ﴿سَيَعْلَمُونَ﴾ يقول: سيعلم هؤلاء الكفار المنُكرون وعيد الله أعداءه، ما الله فاعل بهم يوم القيامة، ثم أكد الوعيد بتكرير آخر، فقال: ما الأمر كما يزعمون من أن الله غير محييهم بعد مماتهم، ولا معاقبهم على كفرهم به، سيعلمون أن القول غير ما قالوا إذا لقوا الله، وأفضوا إلى ما قدّموا من سيئ أعمالهم.\n\nوذُكر عن الضحاك بن مزاحم في ذلك ما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي سنان، عن ثابت، عن الضحاك ﴿كَلا سَيَعْلَمُونَ﴾ الكفار ﴿ثُمَّ كَلا سَيَعْلَمُونَ﴾ المؤمنون، وكذلك كان يقرأها.","2":1,"3":1,"4":1,"5":1,"6":"القول في تأويل قوله تعالى: ﴿أَلَمْ نَجْعَلِ الأرْضَ مِهَادًا (٦) وَالْجِبَالَ أَوْتَادًا (٧) وَخَلَقْنَاكُمْ أَزْوَاجًا (٨) وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا (٩) وَجَعَلْنَا اللَّيْلَ لِبَاسًا (١٠) وَجَعَلْنَا النَّهَارَ مَعَاشًا (١١) ﴾\n\n.\n\nيقول تعالى ذكره معدّدا على هؤلاء المشركين نِعَمه وأياديه عندهم، وإحسانه إليهم، وكفرانهم ما أنعم به عليهم، ومتوعدهم بما أعدّ لهم عند ورودهم عليه من صنوف عقابه، وأليم عذابه، فقال لهم: ﴿أَلَمْ نَجْعَلِ الأرْضَ﴾ لكم ﴿مِهادًا﴾ تمتدونها وتفترشونها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة ﴿أَلَمْ نَجْعَلِ الأرْضَ مِهَادًا﴾ :أي بساطا ﴿وَالْجِبَالَ أَوْتَادًا﴾ يقول: والجبال للأرض أوتادا أن تميد بكم ﴿وَخَلَقْنَاكُمْ أَزْوَاجًا﴾ ذُكرانا وإناثا، وطوالا وقصارا، أو ذوي دمامة وجمال، مثل قوله: ﴿الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ﴾ يعني به: صيرناهم ﴿وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا﴾ يقول: وجعلنا نومكم لكم راحة ودَعة، تهدءون به وتسكنون، كأنكم أموات لا تشعرون، وأنتم أحياء لم تفارقكم الأرواح، والسبت والسبات: هو السكون، ولذلك سمي السبت سبتا، لأنه يوم راحة ودعة ﴿وَجَعَلْنَا اللَّيْلَ لِبَاسًا﴾ يقول تعالى ذكره: وجعلنا الليل لكم غشاء يتغشاكم سواده، وتغطيكم ظلمته، كما يغطي الثوب لابسه لتسكنوا فيه عن التصرّف لما كنتم تتصرّفون له نهارا؛ ومنه قول الشاعر:\n\nفلمَّا لَبِسْن اللَّيْلَ أوْ حِينَ نَصَّبَتْ ... له مِنْ خَذا آذانِها وَهْوَ دَالِحُ\n\nيعني بقوله\" لبسن الليل\": أدخلن في سواده فاستترن به.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن قتادة ﴿وَجَعَلْنَا اللَّيْلَ لِبَاسًا﴾ قال: سكنا.\n\n* *\n\nوقوله: ﴿وَجَعَلْنَا النَّهَارَ مَعَاشًا﴾\n\nيقول: وجعلنا النهار لكم ضياء لتنتشروا فيه لمعاشكم، وتتصرّفوا فيه لمصالح دنياكم، وابتغاء فضل الله فيه، وجعل جلّ ثناؤه النهار إذ كان سببا لتصرّف عباده لطلب المعاش فيه معاشا، كما في قول الشاعر:\n\nوأخُو الهمومِ إذا الهُمُومُ تَحَضرَتْ ... جُنْحَ الظَّلامِ وِسادُهُ لا يَرْقُدُ\n\nفجعل الوساد هو الذي لا يرقد، والمعنى لصاحب الوساد.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿النَّهَارَ مَعَاشًا﴾ قال: يبتغون فيه من فضل الله.","7":6,"8":6,"9":6,"10":6,"11":6,"12":"القول في تأويل قوله تعالى: ﴿وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا (١٢) وَجَعَلْنَا سِرَاجًا وَهَّاجًا (١٣) وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ مَاءً ثَجَّاجًا (١٤) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿وَبَنَيْنَا فَوْقَكُمْ﴾ : وسقفنا فوقكم، فجعل السقف بناء، إذ كانت العرب تسمي سقوف البيوت - وهي سماؤها - بناءً وكانت السماء للأرض سقفا، فخاطبهم بلسانهم إذ كان التنزيل بِلسانهم، وقال ﴿سَبْعًا شِدَادًا﴾ إذ كانت وثاقا محكمة الخلق، لا صدوع فيهنّ ولا فطور، ولا يبليهنّ مرّ الليالي والأيام.\n\n* *\n\nوقوله: ﴿وَجَعَلْنَا سِرَاجًا وَهَّاجًا﴾\n\nيقول تعالى ذكره: وجعلنا سراجا، يعني بالسراج: الشمس وقوله: ﴿وَهَّاجًا﴾ يعني: وقادا مضيئا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَجَعَلْنَا سِرَاجًا وَهَّاجًا﴾ يقول: مضيئا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَجَعَلْنَا سِرَاجًا وَهَّاجًا﴾ يقول: سراجا منيرا.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿سِرَاجًا وَهَّاجًا﴾ قال: يتلألأ.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿سِرَاجًا وَهَّاجًا﴾ قال: الوهاح: المنير.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿سِرَاجًا وَهَّاجًا﴾ قال: يتلألأ ضوءه.\n\n* *\n\nوقوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾\n\nاختلف أهل التأويل في المعنيِّ بالمعصرات، فقال بعضهم: عُنِي بها الرياح التي تعصر في هبوبها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ فالمعصرات: الريح.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن يزيد، عن عكرِمة، أنه كان يقرأ ﴿وأنزلْنا بالمُعْصِرَاتِ﴾ يعني: الرياح.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿مِنَ الْمُعْصِرَاتِ﴾ قال: الريح.\n\n⁕ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: هي في بعض القراءات ﴿وَأنزلْنا بالمُعْصِرَات﴾ : الرياح.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ قال: المعصرات: الرياح، وقرأ قول الله: (الَّذِي يُرْسِلُ الرِّيَاحَ فَتُثِيرُ سَحَابًا ... ) إلى آخر الآية.\n\nوقال آخرون: بل هي السحاب التي تتحلب بالمطر ولمَّا تمطر، كالمرأة المعصر التي قد دنا أوان حيضها ولم تحض.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿مِنَ الْمُعْصِرَاتِ﴾ قال: المعصرات: السحاب.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ يقول: من السحاب.\n\n⁕ قال: ثنا مهران، عن أبي جعفر، عن الربيع: ﴿الْمُعْصِرَاتِ﴾ السحاب.\n\nوقال آخرون: بل هي السماء.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سمعت الحسن يقول: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ قال: من السماء.\n\n⁕ حدثنا بشر. قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ قال: من السموات.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قوله: ﴿وَأَنزلْنَا مِنَ الْمُعْصِرَاتِ﴾ قال: من السماء.\n\nوأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أنه أنزل من المعصرات - وهي التي قد تحلبت بالماء من السحاب - ماء.\n\nوإنما قلنا ذلك أولى بالصواب؛ لأن القول في ذلك على أحد الأقوال الثلاثة التي ذكرت، والرياح لا ماء فيها فينزل منها، وإنما ينزل بها، وكان يصحّ أن تكون الرياح لو كانت القراءة ﴿وَأنزلنا بالمُعْصِرَاتِ﴾ فلما كانت القراءة ﴿مِنَ الْمُعْصِرَاتِ﴾ علم أن المعنيّ بذلك ما وصفت.\n\nفإن ظنّ ظانّ أن الباء قد تعقب في مثل هذا الموضع من قيل ذلك، وإن كان كذلك، فالأغلب من معنى \"من\" غير ذلك، والتأويل على الأغلب من معنى الكلام. فإن قال: فإن السماء قد يجوز أن تكون مرادا بها. قيل: إن ذلك وإن كان كذلك، فإن الأغلب من نزول الغيث من السحاب دون غيره.\n\nوأما قوله: ﴿مَاءً ثَجَّاجًا﴾ يقول: ماء منصبا يتبع بعضه بعضا كثجّ دماء البدن، وذلك سفكها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿مَاءً ثَجَّاجًا﴾ قال: منصبا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿مَاءً ثَجَّاجًا﴾ ماء من السماء منصبا.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿مَاءً ثَجَّاجًا﴾ قال: منصبًّا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة: ﴿مَاءً ثَجَّاجًا﴾ قال: الثجاج: المنصبّ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع ﴿مَاءً ثَجَّاجًا﴾ قال: منصبا.\n\n⁕ قال: ثنا مهران، عن سفيان ﴿مَاءً ثَجَّاجًا﴾ قال: متتابعا.\n\nوقال بعضهم: عُنِي بالثجَّاج: الكثير.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب ﴿مَاءً ثَجَّاجًا﴾ قال: كثيرا، ولا يُعرف في كلام العرب من صفة الكثرة الثجّ، وإنما الثجّ: الصب المتتابع. ومنه قول النبيّ ﷺ: \" أفْضَلُ الحَجِّ الْعَجُّ والثجّ\" يعني بالثج: صبّ دماء الهدايا والبُدن بذبحها، يقال منه: ثججت دمه، فأنا أثجُّه ثجا، وقد ثجَّ الدم، فهو يثجّ ثجوجا.","13":12,"14":12,"15":"القول في تأويل قوله تعالى: ﴿لِنُخْرِجَ بِهِ حَبًّا وَنَبَاتًا (١٥) وَجَنَّاتٍ أَلْفَافًا (١٦) إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا (١٧) يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا (١٨) وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا (١٩) وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا (٢٠) ﴾ .\n\nيقول تعالى ذكره: لنخرج بالماء الذي ننزله من المعصرات إلى الأرض حبا، والحب كل ما تضمنه كمام الزرع التي تحصد، وهي جمع حبة، كما الشعير جمع شعيرة، وكما التمر جمع تمرة: وأما النبات فهو الكلأ الذي يُرْعى، من الحشيش والزروع.\n\n* *\n\nوقوله: ﴿وَجَنَّاتٍ أَلْفَافًا﴾\n\nيقول: ولنخرج بذلك الغيث جنات، وهي البساتين، وقال: ﴿وَجَنَّاتٍ﴾ والمعنى: وثمر جنات، فترك ذكر الثمر استغناء بدلالة الكلام عليه من ذكره.\n\n* *\n\nوقوله: ﴿أَلْفَافًا﴾\n\nيعني: ملتفة مجتمعة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: مجتمعة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَجَنَّاتٍ أَلْفَافًا﴾ يقول: وجنات التفّ بعضها ببعض.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: ملتفة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: التفّ بعضها إلى بعض.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: التفّ بعضها إلى بعض.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: ملتفة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَجَنَّاتٍ أَلْفَافًا﴾ قال: هي الملتفة، بعضها فوق بعض.\n\nواختلف أهل العربية في واحد الألفاف، فكان بعض نحويي البصرة يقول: واحدها: لَفٌّ. وقال بعض نحويِّي الكوفة: واحدها: لف ولفيف، قال: وإن شئت كان الإلفاف جمعا واحده جمع أيضا، فتقول: جنة لفَّاء، وجنات لفّ، ثم يجمع اللَّفَّ ألفافا.\n\nوقال آخر منهم: لم نسمع شجرة لفة، ولكن واحدها لفاء، وجمعها لفّ، وجمع لفّ: ألفاف، فهو جمع الجمع.\n\nوالصواب من القول في ذلك أن الألفاف جمع لفّ أو لفيف، وذلك أن أهل التأويل مجمعون على أن معناه: ملتفة، واللفاء، هي الغليظة، وليس الالتفاف من الغلظ في شيء، إلا أن يوجه إلى أنه غلظ الالتفاف، فيكون ذلك حينئذ وجها.\n\n* *\n\nوقوله: ﴿إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا﴾\n\nيقول تعالى ذكره: إن يوم يفصل الله فيه بين خلقه، فيأخذ فيه من بعضهم لبعض، كان ميقاتًا لما أنفذ الله لهؤلاء المكذّبين بالبعث، ولضربائهم من الخلق.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا﴾ وهو يوم عظَّمه الله، يفصِل الله فيه بين الأوّلين والآخرين بأعمالهم.\n\n* *\n\nوقوله: ﴿يَوْمَ يُنْفَخُ فِي الصُّورِ﴾\n\nتَرْجَم بيوم ينفخ عن يوم الفصل، فكأنه قيل: يوم الفصل كان أجلا لما وعدنا هؤلاء القوم، يوم ينفخ في الصور، وقد بيَّنت معنى الصور فيما مضى قبل، وذكرت اختلاف أهل التأويل فيه، فأغنى ذلك عن إعادته في هذا الموضع، وهو قَرْن يُنْفَخ فيه عندنا.\n\nكما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سليمان التيميّ، عن أسلم، عن بشر بن شغاف، عن عبد الله بن عمرو، عن النبيّ ﷺ، قال: \"الصور: قرن\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَوْمَ يُنْفَخُ فِي الصُّورِ﴾ والصُّور: الخَلق.\n\n* *\n\nوقوله: ﴿فَتَأْتُونَ أَفْوَاجًا﴾\n\nيقول: فيجيئون زمرا زمرا، وجماعة جماعة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن. قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿أَفْوَاجًا﴾ قال: زُمرًا زُمرًا.\n\nوإنما قيل: ﴿فَتَأْتُونَ أَفْوَاجًا﴾ لأن كلّ أمة أرسل الله إليها رسولا تأتي مع الذي أرسل إليها كما قال: ﴿يَوْمَ نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ﴾\n\nوقوله: ﴿وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا﴾\n\nيقول تعالى ذكره: وشققت السماء فصدّعت، فكانت طُرقا، وكانت من قبل شدادا لا فطور فيها ولا صدوع. وقيل: معنى ذلك: وفُتحت السماء فكانت قِطعا كقطع الخشب المشقَّقة لأبواب الدور والمساكن، قالوا: ومعنى الكلام: وفُتحت السماء فكانت قِطعا كالأبواب، فلما أسقطت الكاف صارت الأبواب الخبر، كما يقال في الكلام: كان عبد الله أسدا، يعني: كالأسد.\n\n* *\n\nوقوله: ﴿وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا﴾\n\nيقول: ونُسفت الجبال فاجتثت من أصولها، فصيرت هباء منبثا، لعين الناظر، كالسراب الذي يظنّ من يراه من بُعد ماء، وهو في الحقيقة هباء.","16":15,"17":15,"18":15,"19":15,"20":15,"21":"القول في تأويل قوله تعالى: ﴿إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا (٢١) لِلطَّاغِينَ مَآبًا (٢٢) لابِثِينَ فِيهَا أَحْقَابًا (٢٣) لا يَذُوقُونَ فِيهَا بَرْدًا وَلا شَرَابًا (٢٤) إِلا حَمِيمًا وَغَسَّاقًا (٢٥) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: إن جهنم كانت ذات رَصْد لأهلها الذين كانوا يكذّبون في الدنيا بها وبالمعاد إلى الله في الآخرة، ولغيرهم من المصدّقين بها. ومعنى الكلام: إن جهنم كانت ذات ارتقاب ترقب من يجتازها وترصُدهم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا زكريا بن يحيى بن أبي زائدة، قال: ثنا مسلم بن إبراهيم، عن عبد الله بن بكر بن عبد الله المازني، قال: كان الحسن إذا تلا هذه الآية: ﴿إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا﴾ قال: ألا إنّ على الباب الرّصَد، فمن جاء بجواز جاز، ومن لم يجئ بجواز احتبس.\n\n⁕ حدثني يعقوب، قال: ثنا إسماعيل بن عُلَية، عن أبي رجاء، عن الحسن، في قوله: ﴿إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا﴾ قال: لا يدخل الجنة أحد حي يجتاز النار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا﴾ يُعْلِمُنا أنه لا سبيل إلى الجنة حتى يَقطَع النار.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا﴾ قال: عليها ثلاث قناطر.\n\n* *\n\nوقوله: ﴿لِلطَّاغِينَ مَآبًا﴾\n\nيقول تعالى ذكره: إن جهنم للذين طَغَوا في الدنيا، فتجاوزوا حدود الله استكبارا على ربهم كانت منزلا ومرجعا يرجعون إليه، ومصيرا يصيرون إليه يسكنونه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد. قال: ثنا سعيد، عن قتادة ﴿لِلطَّاغِينَ مَآبًا﴾ أي منزلا ومأوى.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران عن سفيان ﴿مآبًا﴾ يقول: مرجعا ومنزلا.\n\n* *\n\nوقوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾\n\nيقول تعالى ذكره: إن هؤلاء الطاغين في الدنيا لابثون في جهنم، فماكثون فيها أحقابا.\n\nواختلفت القرّاء في قراءة قوله: ﴿لابِثِينَ﴾ فقرأ ذلك عامة قرّاء المدينة والبصرة وبعض قرّاء الكوفة ﴿لابِثِينَ﴾ بالألف. وقرأ ذلك عامة قرّاء الكوفة \" لَبِثِينَ \" بغير ألف، وأفصح القراءتين وأصحهما مخرجا في العربية قراءة من قرأ ذلك بالألف، وذلك أن العرب لا تكاد توقع الصفة إذا جاءت على فَعِل فتعملها في شيء، وتنصبه بها، لا يكادون أن يقولوا: هذا رجل بَخِل بماله، ولا عَسِر علينا، ولا هو خَصِم لنا؛ لأن فعل لا يأتي صفة إلا مدحا أو ذما، فلا يعمل المدح والذمّ في غيره، وإذا أرادوا إعمال ذلك في الاسم أو غيره جعلوه فاعلا فقالوا: هو باخل بماله، وهو طامع فيما عندنا، فلذلك قلت: إن ﴿لابِثِينَ﴾ أصح مخرجا في العربية وأفصح، ولم أُحِلّ قراءة من قرأ ﴿لَبِثِينَ﴾ وإن كان غيرها أفصح، لأن العرب ربما أعملت المدح في الأسماء، وقد يُنشد بيت لبيد:\n\nأوْ مِسْحَلٌ عَمِلٌ عِضَادَةَ سَمْحَجٍ ... بِسَرَاتِهَا نَدَبٌ لَهُ وكُلُومُ\n\nفأعمل عَمِلٌ في عِضادة، ولو كانت عاملا كانت أفصح، ويُنشد أيضا:\n\n... ... ... ... ... ... ... ... ... وبالفأس ضَرَّابٌ رُءُوسَ الكَرَانِفِ\n\nومنه قول عباس بن مرداس:\n\nأكَرَّ وأحْمَى لِلْحَقِيقَةِ مِنْهُمُ ... وأضْرَبَ مِنَّا بالسُّيُوفِ الْقَوَانِسا\n\nوأما الأحقاب فجمع حُقْب، والحِقَب: جمع حِقْبة، كما قال الشاعر:\n\nعِشْنا كَنَدْمَانَيْ جَذِيمَةَ حِقْبَةً ... مِنَ الدَّهْرِ حتى قيلَ لَن نَتَصَدَّعا\n\nفهذه جمعها حِقَب، ومن الأحقاب التي جمعها حقب  قول الله: ﴿أَوْ أَمْضِيَ حُقُبًا﴾ فهذا واحد الأحقاب.\n\nوقد اختلف أهل التأويل في مبلغ مدة الحُقْب، فقال بعضهم: مدة ثلاث مئة سنة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عمران بن موسى القزاز، قال: ثنا عبد الوارث بن سعيد، قال: ثنا إسحاق بن سُويد، عن بشير بن كعب، في قوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ قال: بلغني أن الحُقب ثلاث مئة سنة، كلّ سنة ثلاث مئة وستون يوما، كل يوم ألف سنة.\n\nوقال آخرون: بل مدة الحُقْب الواحد: ثمانون سنة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: ثني عمار الدُّهْنيّ، عن سالم بن أبي الجعد، قال: قال عليّ بن أبي طالب رضي الله عنه لهلال الهَجرِيّ: ما تجدون الحُقْب في كتاب الله المنزل؟ قال: نجد ثمانين سنة كل سنة اثنا عشر شهرا، كل شهر ثلاثون يوما، كل يوم ألف سنة.\n\n⁕ حدثنا تميم بن المنتصر، قال: أخبرنا إسحاق، عن شريك، عن عاصم بن أبي النَّجود، عن أبي صالح، عن أبي هريرة: أنه قال: الحُقب: ثمانون سنة، والسنة: ستون وثلاث مئة يوم، واليوم: ألف سنة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبى سنان، عن ابن عباس، قال: الحُقْب: ثمانون سنة.\n\n⁕ حدثنا أبو كُريب، قال: ثنا جابر بن نوح، قال: ثنا الأعمش، عن سعيد، بن جُبير، في قوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ قال: الحقب: ثمانون سنة، السنة: ثلاث مئة وستون يوما، اليوم: سنة أو ألف سنة \"الطبري يشكّ\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال الله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ وهو ما لا انقطاع له، كلما مضى حُقْب جاء حُقْب بعده. وذُكر لنا أن الحُقْب ثمانون سنة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿أحْقابًا﴾ قال: بلغنا أن الحقب ثمانون سنة من سني الآخرة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع بن أنس ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ لا يعلم عدّة هذه الأحقاب إلا الله، ولكن الحُقْب الواحد: ثمانون سنة، والسنة: ثلاث مئة وستون يوما، كل يوم من ذلك ألف سنة.\n\nوقال آخرون: الحُقْب الواحد: سبعون ألف سنة.\n\nذكر من قال ذلك:\n\n⁕ حدثني ابن عبد الرحيم البرقي، قال: ثني عمرو بن أبي سلمة، عن زهير، عن سالم، قال: سمعت الحسن يُسْأل عن قول الله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ قال: أما الأحقاب فليس لها عدّة إلا الخلود في النار؛ ولكن ذكروا أن الحُقْب الواحد سبعون ألف سنة، كلّ يوم من تلك الأيام السبعين ألفا كألف سنة مما تَعُدّون.\n\n⁕ حدثنا عمرو بن عبد الحميد الآمُلِيّ، قال: ثنا أبو أُسامة، عن هشام، عن الحسن في قوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ قال: أما الأحقاب، فلا يَدرِي أحد ما هي، وأما الحُقْب الواحد: فسبعون ألف سنة، كلّ يوم كألف سنة.\n\nورُوي عن خالد بن معدان في هذه الآية أنها في أهل القِبلة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عليّ، قال: ثنا أبو صالح، قال: ثني معاوية بن صالح، عن عامر بن جَشْبٍ، عن خالد بن معدان في قوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ ، وقوله: ﴿إِلا مَا شَاءَ رَبُّكَ﴾ إنهما في أهل التوحيد من أهل القبلة.\n\nفإن قال قائل: فما أنت قائل في هذا الحديث؟ قيل: الذي قاله قتادة عن الربيع بن أنس في ذلك أصحّ. فإن قال: فما للكفار عند الله عذاب إلا أحقابا، قيل: إن الربيع وقتادة قد قالا إن هذه الأحقاب لا انقضاء لها ولا انقطاع لها. وقد يحتمل أن يكون معنى ذلك: لابثين فيها أحقابا في هذا النوع من العذاب هو أنهم: ﴿لا يَذُوقُونَ فِيهَا بَرْدًا وَلا شَرَابًا إِلا حَمِيمًا وَغَسَّاقًا﴾ فإذا انقضت تلك الأحقاب، صار لهم من العذاب أنواع غير ذلك، كما قال جلّ ثناؤه في كتابه: ﴿وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ الْمِهَادُ هَذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ وَآخَرُ مِنْ شَكْلِهِ أَزْوَاجٌ﴾ وهذا القول عندي أشبه بمعنى الآية.\n\nوقد رُوي عن مقاتل بن حيان في ذلك ما:-\n\n⁕ حدثني محمد بن عبد الرحيم البرقي، قال: ثنا عمرو بن أبي سَلَمة، قال: سألت أبا معاذ الخراساني، عن قول الله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ فأخبرنا عن مقاتل بن حَيان، قال: منسوخة، نسختها ﴿فَلَنْ نزيدَكُمْ إِلا عَذَابًا﴾ ولا معنى لهذا القول؛ لأن قوله: ﴿لابِثِينَ فِيهَا أَحْقَابًا﴾ خبر والأخبار لا يكون فيها نسخ، وإنما النسخ يكون في الأمر والنهي.\n\n* *\n\nوقوله: ﴿لا يَذُوقُونَ فِيهَا بَرْدًا وَلا شَرَابًا﴾\n\nيقول: لا يطعمون فيها بردا يبرد حرّ السعير عنهم، إلا الغساق، ولا شرابا يرويهم من شدّة العطش الذي بهم، إلا الحميم. وقد زعم بعض أهل العلم بكلام العرب أن البرد في هذا الموضع النوم، وأن معنى الكلام: لا يذوقون فيها نوما ولا شرابا، واستشهد لقيله ذلك بقول الكنديّ:\n\nبَرَدَتْ مَرَاشِفُها عَليَّ فَصَدَّني ... عَنْها وَعَنْ قُبُلاتِها البَرْدُ\n\nيعني بالبرد: النُّعاس، والنوم إن كان يُبرِد غليلَ العطش، فقيل له من أجل ذلك البرد فليس هو باسمه المعروف، وتأويل كتاب الله على الأغلب من معروف كلام العرب، دون غيره.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع ﴿لا يَذُوقُونَ فِيهَا بَرْدًا وَلا شَرَابًا إِلا حَمِيمًا وَغَسَّاقًا﴾ فاستثنى من الشراب الحميم، ومن البَرْد: الغَسَّاق.\n\n* *\n\nوقوله: ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾\n\nيقول تعالى ذكره: لا يذوقون فيها بردا ولا شرابا إلا حميمًا قد أغلي حتى انتهى حرّه، فهو كالمُهْل يَشْوِي الوجوه، ولا بردًا إلا غَسَّاقًا.\n\nاختلف أهل التأويل في معنى الغَسَّاق، فقال بعضهم: هو ما سال من صديد أهل جهنم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، ومحمد بن المثنى، قالا ثنا ابن إدريس، عن أبيه، عن عطية بن سعد، في قوله: ﴿حَمِيمًا وَغَسَّاقًا﴾ قال: هو الذي يَسيل من جلودهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر، عن أبيه، قال: ثنا أبو عمرو، قال: زَعم عكرِمة أنه حدثهم في قوله: ﴿وَغَسَّاقًا﴾ قال: ما يخرج من أبصارهم من القيح والدم.\n\n⁕ حدثنا ابن بشار وابن المثنى، قالا ثنا عبد الرحمن قال: ثنا سفيان، عن منصور عن إبراهيم وأبي رَزِين ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ قالا غُسالة أهل النار: لفظ ابن بشار؛ وأما ابن المثنى فقال في حديثه: ما يسيل من صديدهم.\n\n⁕ وحدثنا ابن بشار مرّة أخرى عن عبد الرحمن، فقال كما قال ابن المثنى.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن أبي رزين ﴿وَغَسَّاقًا﴾ قال: ما يَسِيل من صديدهم.\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن منصور وأبي رزين، عن إبراهيم مثله.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿غَسَّاقًا﴾ كنا نحدَّث أن الغَسَّاق: ما يسيل من بين جلده ولحمه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا الضحاك بن مخلد، عن سفيان، أنه قال: بلغني أنه ما يسيل من دموعهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن إبراهيم ﴿وَغَسَّاقًا﴾ قال: ما يسيل من صديدهم من البرد، قاله سفيان، وقال غيره: الدموع.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ قال: الحميم: دموع أعينهم في النار، يجتمع في خنادق النار فَيُسْقَونه والغساق: الصديد الذي يخرج من جلودهم، ما تصهرهم النار في حياض يجتمع فيها فيسقونه.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن إبراهيم ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ قال: الغساق: ما يقطر من جلودهم، وما يسيل من نتنهم.\n\nوقال آخرون: الغساق: الزمهرير.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ يقول: الزمهرير.\n\n⁕ حدثنا أبو كُريب وأبو السائب وابن المثنى، قالوا: ثنا ابن إدريس، قال: سمعت ليثا، عن مجاهد، في قوله: ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ قال: الذي لا يستطيعون أن يذوقوه من برده.\n\n⁕ قال: ثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ليث، عن مجاهد ﴿إِلا حَمِيمًا وَغَسَّاقًا﴾ قال: الذي لا يستطيعونه من برده.\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن ليث، عن مجاهد، الغساق: الذي لا يستطاع من برده.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر عن الربيع، قال: الغساق، الزمهرير.\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن أبي جعفر، عن الربيع عن أبي العالية، قال: الغساق: الزمهرير.\n\nوقال آخرون: هو المنتن، وهو بالطَّخارية.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن المسيب بن شريك، عن صالح بن حيان، عن عبد الله بن بُرَيدة، قال: الغساق: بالطَّخارية: هو المُنْتِن.\n\nوالغساق عندي: هو الفعال، من قولهم: غَسَقَت عين فلان: إذا سالت دموعها، وغَسَق الجرح: إذا سال صديده، ومنه قول الله ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ يعني بالغاسق: الليل إذا لَبِسَ الأشياء وغطاها، وإنما أريد بذلك هجومه على الأشياء، هجوم السيل السائل. فإذا كان الغسَّاق هو ما وصفت من الشيء السائل، فالواجب أن يقال: الذي وعد الله هؤلاء القوم، وأخبر أنهم يذوقونه في الآخرة من الشراب هو السائل من الزمهرير في جهنم، الجامع مع شدّة برده النتن.\n\nكما:-\n\n⁕ حدثنا ابن المثنى، قال: ثنا يعمر بن بشر، قال: ثنا ابن المبارك، قال: ثنا رشدين بن سعد، قال: ثنا عمرو بن الحارث، عن أبي السمح، عن أبي الهيثم، عن أبي سعيد الخدريّ، عن النبيّ ﷺ، قال: \"لَوْ أنَّ دَلْوًا مِنْ غَسَّاقٍ يُهْرَاقُ إلى الدُّنْيا لأنْتَن أهْلَ الدُّنْيا\".\n\n⁕ حُدثت عن محمد بن حرب، قال: ثنا ابن لَهِيعة، عن أبي قبيل، عن أبي مالك، عن عبد الله بن عمرو أنه قال: \"أتدرون أيّ شيء الغسَّاق؟ \" قالوا: الله أعلم، قال: \"هو القيح الغليظ، لو أن قطرة منه تهراق بالمغرب لأنتن أهل المشرق، ولو تهراق بالمشرق، لأنتن أهل المغرب\".\n\nفإن قال قائل: فإنك قد قلت: إن الغَساق: هو الزمهرير، والزمهرير، هو غاية البرد، فكيف يكون الزمهرير سائلا؟ قيل: إن البرد الذي لا يُستطاع ولا يُطاق يكون في صفة السائل من أجساد القوم من القيح والصديد.","22":21,"23":21,"24":21,"25":21,"26":"القول في تأويل قوله تعالى: ﴿جَزَاءً وِفَاقًا (٢٦) إِنَّهُمْ كَانُوا لا يَرْجُونَ حِسَابًا (٢٧) وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا (٢٨) وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا (٢٩) فَذُوقُوا فَلَنْ نزيدَكُمْ إِلا عَذَابًا (٣٠) ﴾\n\n.\n\nيقول تعالى ذكره: هذا العقاب الذي عُوقِب به هؤلاء الكفار في الآخرة فعلَه بهم ربهم جزاء، يعني: ثوابا لهم على أفعالهم وأقوالهم الرديئة التي كانوا يعملونها في الدنيا، وهو مصدر من قول القائل: وافق هذا العقاب هذا العلم وِفاقا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ عن ابن عباس، قوله: ﴿جَزَاءً وِفَاقًا﴾ يقول: وافَق أعمالهم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿جَزَاءً وِفَاقًا﴾ وافق الجزاء أعمال القوم أعمال السوء.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع ﴿جَزَاءً وِفَاقًا﴾ قال: بحسب أعمالهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: ثنا حكام، عن أبي جعفر، عن الربيع، في قوله: ﴿جَزَاءً وِفَاقًا﴾ قال: ثواب وافَق أعمالهم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿جَزَاءً وِفَاقًا﴾ قال: عملوا شرّا فجزوا شرّا، وعملوا حسنا فجزوا حسنا، ثم قرأ قول الله: ﴿ثُمَّ كَانَ عَاقِبَةَ الَّذِينَ أَسَاءُوا السُّوءَى﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿جَزَاءً وِفَاقًا﴾ قال: جزاء وافق أعمال القوم.\n\n⁕ حدثنا محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿جَزَاءً وِفَاقًا﴾ قال: وافق الجزاء العمل.\n\n* *\n\nوقوله: ﴿إِنَّهُمْ كَانُوا لا يَرْجُونَ حِسَابًا﴾\n\nيقول تعالى ذكره: إن هؤلاء الكفار كانوا في الدنيا لا يخافون محاسبة الله إياهم في الآخرة على نعمه عليهم، وإحسانه إليهم، وسوء شكرهم له على ذلك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿لا يَرْجُونَ حِسَابًا﴾ قال: لا يبالون فيصدّقون بالغيب.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد عن قتادة، قوله: ﴿إِنَّهُمْ كَانُوا لا يَرْجُونَ حِسَابًا﴾ أي: لا يخافون حسابا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّهُمْ كَانُوا لا يَرْجُونَ حِسَابًا﴾ قال: لا يؤمنون بالبعث ولا بالحساب، وكيف يرجو الحساب من لا يوقن أنه يحيا، ولا يوقن بالبعث، وقرأ قول الله: ﴿بَلْ قَالُوا مِثْلَ مَا قَالَ الأوَّلُونَ قَالُوا أَئِذَا مِتْنَا وَكُنَّا تُرَابًا ... ﴾ إلى قوله: ﴿أساطِيرُ الأوَّلِينَ﴾ . وقرأ ﴿هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ ... ﴾ إلى قوله: ﴿جَدِيدٍ﴾ فقال بعضهم لبعض: ماله ﴿أَفْتَرَى عَلَى اللَّهِ كَذِبًا أَمْ بِهِ جِنَّةٌ﴾ الرجل مجنون حين يخبرنا بهذا.\n\n* *\n\nوقوله: ﴿وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا﴾\n\nيقول تعالى ذكره: وكذّب هؤلاء الكفار بحُججِنا وأدلتنا تكذيبا. وقيل: ﴿كِذَّابًا﴾ ، ولم يقل تكذيبا تصديرا على فعله.\n\nوكان بعض نحويِّي البصرة يقول: قيل ذلك لأن فعل منه على أربعة فأراد أن يجعله مثل باب أفعلت، ومصدر أفعلت إفعالا فقال: كذّابا، فجعله على عدد مصدره، قال: وعلى هذا القياس تقول: قاتل قتالا قال: وهو من كلام العرب. وقال بعض نحويِّي الكوفة: هذه لغة يمانية فصيحة، يقولون: كذّبت به كذّابا، وخَرَّقت القميص خِرَّاقا، وكلٌّ فَعَّلْت فمصدرها فِعَّال بلغتهم مشدّدة. قال: وقال لي أعرابي مرّة على المروة يستفتيني: ألحلق أحبّ إليك أم القِصَّار؟ قال: وأنشدني بعض بنِي كلاب:\n\nلَقَدْ طالَ ما ثَبَّطَتْنِي عَنْ صَحَابَتِي ... وَعَنْ حِوَجٍ قِضَّاؤُها مِنْ شِفائِيَا\n\nوأجمعت القرّاء على تشديد الذال من الكِذّاب في هذا الموضع. وكان الكسائي خاصة يخفِّف الثانية، وذلك في قوله: ﴿لا يَسْمَعُونَ فِيهَا لَغْوًا وَلا كِذَّابًا﴾ ويقول: هو من قولهم: كاذبته كِذّابا ومكاذبة، ويشدّد هذه، ويقول قوله: ﴿كذّبوا﴾ يقيد الكذّاب بالمصدر.\n\n* *\n\nوقوله: ﴿وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا﴾\n\nيقول تعالى ذكره: وكلّ شيء أحصيناه فكتبناه كتابا، كتبنا عدده ومبلغه وقدره، فلا يعزُب عنا علم شيء منه، ونصب كتابا، لأن في قوله: ﴿أحصَيْناهُ﴾ مصدر أثبتناه وكتبناه، كأنه قيل: وكلّ شيء كتبناه كتابا.\n\n* *\n\nوقوله: ﴿فَذُوقُوا فَلَنْ نزيدَكُمْ إِلا عَذَابًا﴾\n\nيقول جلّ ثناؤه: يقال لهؤلاء الكفار في جهنم إذا شربوا الحميم والغَسَّاق: ذوقوا أيها القوم من عذاب الله الذي كنتم به في الدنيا تكذّبون، فلن نزيدكم إلا عذابًا على العذاب الذي أنتم فيه، لا تخفيفا منه، ولا ترفُّها.\n\n⁕ وقد حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، عن سعيد، عن قتادة، عن أبي أيوب الأزدي، عن عبد الله بن عمرو، قال: لم تنزل على أهل النار آية أشد من هذه: ﴿فَذُوقُوا فَلَنْ نزيدَكُمْ إِلا عَذَابًا﴾ قال: فهم في مزيد من العذاب أبدا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَذُوقُوا فَلَنْ نزيدَكُمْ إِلا عَذَابًا﴾ ذُكر لنا أن عبد الله بن عمرو كان يقول: ما نزلت على أهل النار آية أشدّ منها ﴿فَذُوقُوا فَلَنْ نزيدَكُمْ إِلا عَذَابًا﴾ فهم في مزيد من الله أبدا.","27":26,"28":26,"29":26,"30":26,"31":"القول في تأويل قوله تعالى: ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا (٣١) حَدَائِقَ وَأَعْنَابًا (٣٢) وَكَوَاعِبَ أَتْرَابًا (٣٣) وَكَأْسًا دِهَاقًا (٣٤) لا يَسْمَعُونَ فِيهَا لَغْوًا وَلا كِذَّابًا (٣٥) ﴾\n\n.\n\nيقول: إن للمتقين مَنجَى من النار إلى الجنة، ومخلصا منها لهم إليها، وظفرا بما طلبوا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا﴾ قال: فازوا بأن نَجَوا من النار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا﴾ إي والله مفازا من النار إلى الجنة، ومن عذاب الله إلى رحمته.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا﴾ قال: مفازا من النار إلى الجنة.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاومة، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا﴾ يقول: مُنْتَزَها  .\n\n* *\n\nوقوله: ﴿حَدَائِقَ﴾\n\nوالحدائق: ترجمة وبيان عن المفاز، وجاز أن يترجم عنه، لأن المفاز مصدر من قول القائل: فاز فلان بهذا الشيء، إذا طلبه فظفر به، فكأنه قيل: إن للمتقين ظفرا بما طلبوا من حدائق وأعناب، والحدائق: جمع حديقة، وهي البساتين من النخل والأعناب والأشجار المُحَوَّط عليها الحيطان المحدقة بها، لإحداق الحيطان بها تسمى الحديقة حديقة، فإن لم تكن الحيطان بها محدقة، لم يَقُل لها حديقة، وإحداقها بها: اشتمالها عليها.\n\n* *\n\nوقوله: ﴿وأعْنابًا﴾\n\nيعني: وكرومَ أعناب، واستغنى بذكر الأعناب عن ذكر الكروم.\n\n* *\n\nوقوله: ﴿وَكَوَاعِبَ أَتْرَابًا﴾\n\nيقول: ونواهد في سنّ واحدة.\n\nوبنحو الذي قلنا قي ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَكَوَاعِبَ﴾ يقول: ونواهد.\n\n* *\n\nوقوله: ﴿أَتْرَابًا﴾\n\nيقول: مُسْتَوِيَات.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَكَوَاعِبَ أَتْرَابًا﴾ يعني: النساء المستويات.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَكَوَاعِبَ أَتْرَابًا﴾ قال: نواهد أترابا، يقول: لسن واحدة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، ثم وصف ما في الجنة قال: ﴿حَدَائِقَ وَأَعْنَابًا﴾ ﴿وَكَوَاعِبَ أَتْرَابًا﴾ يعني بذلك النساء أترابا لسنٍّ واحدة.\n\n⁕ حدثني عباس بن محمد، قال: ثنا حجاج، عن ابن جُرَيج، قال: الكواعب: النواهد.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَكَوَاعِبَ أَتْرَابًا﴾ قال: الكواعب: التي قد نهدت وكَعَبَ ثديها، وقال: أترابا: مستويات، فلانة تربة فلانة، قال: الأتراب: اللِّدات.\n\n⁕ حدثنا نصر بن عليّ، قال: ثنا يحيى بن سليمان، عن ابن جريج، عن مجاهد ﴿وَكَوَاعِبَ أَتْرَابًا﴾ لِدَّات.\n\n* *\n\nوقوله: ﴿وَكَأْسًا دِهَاقًا﴾\n\nيقول: وكأسا ملأى متتابعة على شاربيها بكثرة وامتلاء، وأصله من الدَّهْق: وهو متابعة الضغط على الإنسان بشدّة وعنف، وكذلك الكأس الدهاق: متابعتها على شاربيها بكثرة وامتلاء.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا مروان، قال: ثنا أبو يزيد يحيى بن ميسرة، عن مسلم بن نَسْطاس، قال: قال ابن عباس لغلامه: اسقني دهاقا، قال: فجاء بها الغلام ملأى، فقال ابن عباس: هذا الدِّهاق.\n\n⁕ حدثني محمد بن عبيد المحاربي، قال: ثنا موسى بن عمير، عن أبي صالح، عن ابن عباس، قوله: ﴿كَأْسًا دِهَاقًا﴾ قال: ملأى.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، أخبرني سليمان بن بلال، عن جعفر بن محمد، عن عمرو بن دينار، قال: سمعت ابن عباس يُسأل عن ﴿كأْسًا دِهاقًا﴾ قال: دراكا، قال يونس: قال ابن وهب: الذي يَتْبع بعضُه بعضا.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثنى معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَكَأْسًا دِهَاقًا﴾ يقول: ممتلئا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا حميد الطويل، عن ثابت البُنَانيّ، عن أبي رافع، عن أبي هريرة، في قوله: ﴿كَأْسًا دِهَاقًا﴾ قال: دمادم  .\n\n⁕ قال ثنا ابن علية، قال: ثنا أبو رجاء، عن الحسن، في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: مَلأى.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا ابن أبي عديّ، عن يونس، عن الحسن ﴿وَكَأْسًا دِهَاقًا﴾ قال: الملأى.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿وَكَأْسًا دِهَاقًا﴾ قال: مَلأى.\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، قال: ثنا شعبة، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن سعيد بن أبي عَرُوبة، عن قتادة، في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: مُتْرَعة مَلأى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَكَأْسًا دِهَاقًا﴾ قال: الدهاق: المَلأى المُتْرَعة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿كأْسًا دِهاقًا﴾ قال: الدهاق: الممتلئة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كأْسًا دِهاقًا﴾ قال: الدِّهاق المملوءة.\n\nوقال آخرون: الدِّهاق: الصافية.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن يحيى الأزديّ وعباس بن محمد، قالا ثنا حجاج، عن ابن جريج، قال: ثنا عمر بن عطاء، عن عكرِمة، في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: صافية.\n\nوقال آخرون: بل هي المتتابعة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: قال سعيد بن جُبير في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ دهاقًا: المتتابعة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: المتتابع.\n\n⁕ حدثنا عمرو بن عبد الحميد، قال: ثنا جرير، عن حصين، عن عكرِمة، عن ابن عباس، في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: الملأى المتتابعة.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، في قوله: ﴿وَكَأْسًا دِهَاقًا﴾ قال: المتتابعة.\n\n* *\n\nوقوله: ﴿لا يَسْمَعُونَ فِيهَا لَغْوًا وَلا كِذَّابًا﴾\n\nيقول تعالى ذكره: لا يسمعون في الجنة لغوا، يعني باطلا من القول، ولا كذّابًا، يقول: ولا مكاذبة، أي لا يكذب بعضهم بعضا، وقرأت القرّاء في الأمصار بتشديد الذال على ما بيَّنت في قوله: ﴿وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا﴾ سوى الكسائيّ فإنه خَفَّفها لما وصفت قبل، والتشديد أحبّ إليّ من التخفيف، وبالتشديد القراءة، ولا أرى قراءة ذلك بالتخفيف لإجماع الحجة من القرّاء على خلافه، ومن التخفيف قول الأعشى:\n\nفَصَدَقْتُها وكَذبْتُها ... والمَرْءُ يَنْفَعُهُ كِذَابُهُ\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿لَغْوًا وَلا كِذَّابًا﴾ قال: باطلا وإثمًا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿لا يَسْمَعُونَ فِيهَا لَغْوًا وَلا كِذَّابًا﴾ قال: وهي كذلك ليس فيها لغوٌ ولا كذَّاب.","32":31,"33":31,"34":31,"35":31,"36":"القول في تأويل قوله تعالى: ﴿جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا (٣٦) رَبِّ السَّمَاوَاتِ وَالأرْضِ وَمَا بَيْنَهُمَا الرَّحْمَنِ لا يَمْلِكُونَ مِنْهُ خِطَابًا (٣٧) يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ صَفًّا لا يَتَكَلَّمُونَ إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا (٣٨) ﴾ .\n\nيعني بقوله جلّ ثناؤه: ﴿جَزَاءً مِنْ رَبِّكَ عَطَاءً﴾ أعطى الله هؤلاء المتقين ما وصف في هذه الآيات ثوابًا من ربك بأعمالهم، على طاعتهم إياه في الدنيا.\n\n* *\n\nوقوله: ﴿عَطاءً﴾\n\nيقول: تفضلا من الله عليهم بذلك الجزاء، وذلك أنه جزاهم بالواحد عشرا في بعض وفي بعض بالواحد سبع مِئَةٍ، فهذه الزيادة وإن كانت جزاء، فعطاء من الله.\n\n* *\n\nوقوله: ﴿حِسابًا﴾\n\nيقول: محاسبة لهم بأعمالهم لله في الدنيا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا﴾ قال: عطاء منه حسابًا لما عملوا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا﴾ : أي عطاء كثيرا، فجزاهم بالعمل اليسير الخير الجسيم، الذي لا انقطاع له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن مَعْمر، عن قتادة، في قوله: ﴿عَطَاءً حِسَابًا﴾ قال: عطاء كثيرا، وقال مجاهد: عطاء من الله حسابًا بأعمالهم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: سمعت ابن زيد يقول في قول الله: ﴿جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا﴾ فقرأ: ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا حَدَائِقَ وَأَعْنَابًا وَكَوَاعِبَ أَتْرَابًا ... ﴾ إلى ﴿عَطَاءً حِسَابًا﴾ قال: فهذه جزاء بأعمالهم عطاء الذي أعطاهم عملوا له واحدة، فجزاهم عشرا، وقرأ قول الله: ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا﴾ ، وقرأ قول الله: ﴿مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ﴾ قال: يزيد من يشاء، كان هذا كله عطاء، ولم يكن أعمالا يحسبه لهم، فجزاهم به حتى كأنهم عملوا له، قال: ولم يعملوا إنما عملوا عشرا، فأعطاهم مئة، وعملوا مئة، فأعطاهم ألفا، هذا كله عطاء، والعمل الأوّل، ثم حَسَب ذلك حتى كأنهم عملوا فجزاهم كما جزاهم بالذي عملوا.\n\n* *\n\nوقوله: ﴿رَبِّ السَّمَاوَاتِ وَالأرْضِ وَمَا بَيْنَهُمَا الرَّحْمَنِ﴾\n\nيقول جلّ ثناؤه: جزاء من ربك ربّ السموات السبع والأرض وما بينهما من الخلق.\n\nواختلف القرّاء في قراءة ذلك، فقرأته عامة قراء المدينة: ﴿رَبُّ السَّمَوَاتِ والأرْضِ وَما بَيْنَهُما الرَّحْمَنُ﴾ بالرفع في كليهما. وقرأ ذلك بعض أهل البصرة وبعض الكوفيين: ﴿رَبِّ﴾ خفضًا: ﴿الرَّحْمَنُ﴾ رفعًا ولكلّ ذلك عندنا وجه صحيح، فبأيّ ذلك قرأ القارئ فمصيب، غير أن الخفض في الربّ، لقربه من قوله: ﴿جَزَاءً مِنْ رَبِّكَ﴾ : أعجب إليّ، وأما ﴿الرَّحْمَنُ﴾ بالرفع فإنه أحسن لبعده من ذلك.\n\n* *\n\nوقوله: ﴿الرَّحْمَنِ لا يَمْلِكُونَ مِنْهُ خِطَابًا﴾\n\nيقول تعالى ذكره: الرحمن لا يقدر أحد من خلقه خطابه يوم القيامة، إلا من أذن له منهم وقال صوابًا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿لا يَمْلِكُونَ مِنْهُ خِطَابًا﴾ قال: كلاما.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿لا يَمْلِكُونَ مِنْهُ خِطَابًا﴾ أي كلاما.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿لا يَمْلِكُونَ مِنْهُ خِطَابًا﴾ قال: لا يملكون أن يخاطبوا الله، والمخاطِب: المخاصم الذي يخاصم صاحبه.\n\n* *\n\nوقوله: ﴿يَوْمَ يَقُومُ الرُّوحُ﴾\n\nاختلف أهل العلم في معنى الروح في هذا الموضع، فقال بعضهم: هو مَلَك من أعظم الملائكة خَلْقًا.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن خلف العَسْقَلانيّ، قال: ثنا روّاد بن الجرّاح، عن أبي حمزة، عن الشعبيّ، عن علقمة، عن ابن مسعود، قال: الرُّوح: ملك في السماء الرابعة، هو أعظم من السموات ومن الجبال ومن الملائكة يسبح الله كلّ يوم اثني عشر ألف تسبيحة، يخلق الله من كلّ تسبيحة مَلَكا من الملائكة، يجيء يوم القيامة صفًّا وحده.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ﴾ قال: هو ملك أعظم الملائكة خَلْقًا.\n\nوقال آخرون: هو جبريل عليه السلام.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي سنان، عن ثابت، عن الضحاك ﴿يَوْمَ يَقُومُ الرُّوحُ﴾ قال: جبريل عليه السلام.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الضحاك ﴿يَوْمَ يَقُومُ الرُّوحُ﴾ قال: الروح: جبريل عليه السلام.\n\n⁕ حدثنا محمد بن خَلَف العَسْقَلانيّ، قال: ثنا روّاد بن الجرّاح، عن أبي حمزة عن الشعبىّ ﴿يَوْمَ يَقُومُ الرُّوحُ﴾ قال: الروح جبريل عليه السلام.\n\nوقال آخرون: خَلْق من خلق الله في صورة بني آدم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عامر، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، قال: ﴿الرُّوحُ﴾ خَلْق على صورة بني آدم يأكلون ويشربون.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن مسلم، عن مجاهد، قال: ﴿الرُّوحُ﴾ : خلق لهم أيد وأرجل، وأراه قال: ورءوس يأكلون الطعام، ليسوا ملائكة.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عامر، قال: ثنا سفيان، عن إسماعيل بن أبي خالد، عن أبي صالح، قال: يشبهون الناس وليسوا بالناس.\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن شعبة، عن سليمان، عن مجاهد، قال: ﴿الرُّوحُ﴾ خلق كخلق آدم.\n\n⁕ حدثني يحيى بن إبراهيم المسعوديّ، قال: ثنا أبي، عن أبيه، عن جدّه، عن الأعمش، في قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ صَفًّا﴾ قال: الروح خلق من خلق الله يضعفون على الملائكة أضعافًا، لهم أيد وأرجل.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا معتمر بن سليمان، عن إسماعيل، عن أبي صالح مولى أم هانئ ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ﴾ قال: الروح: خلق كالناس، وليسوا بالناس.\n\nوقال آخرون: هم بنو آدم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿يَوْمَ يَقُومُ الرُّوحُ﴾ قال: هم بنو آدم، وهو قول الحسن.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، في قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ﴾ قال: الروح بنو آدم. وقال قتادة: هذا مما كان يكتمه ابن عباس.\n\nوقال آخرون: قيل: ذلك أرواح بني آدم.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ صَفًّا لا يَتَكَلَّمُونَ﴾ قال: يعني حين تقوم أرواح الناس مع الملائكة فيما بين النفختين قبل أن تردّ الأرواح إلى الأجساد.\n\nوقال آخرون: هو القرآن.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، كان أبي يقول: الروح: القرآن، وقرأ ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِنْ أَمْرِنَا مَا كُنْتَ تَدْرِي مَا الْكِتَابُ وَلا الإيمَانُ﴾ .\n\nوالصواب من القول أن يقال: إن الله تعالى ذكره أخبر أنّ خَلْقَه لا يملكون منه خطابا، يوم يقوم الرُّوح، والرُّوح خَلْق من خَلْقِه، وجائز أن يكون بعض هذه الأشياء التي ذكرت، والله أعلم أيّ ذلك هو، ولا خبر بشيء من ذلك أنه المعنيّ به دون غيره يجب التسليم له، ولاحجة تدلّ عليه، وغير ضائر الجهل به.\n\nوقيل: إنه يقول: سِمَاطان.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا منصور بن عبد الرحمن، عن الشعبيّ، في قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلائِكَةُ صَفًّا لا يَتَكَلَّمُونَ إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ﴾ قال: هما سِمَاطان  لربّ العالمين يوم القيامة؛ سِماط من الروح، وسِماط من الملائكة.\n\n* *\n\nوقوله: ﴿لا يَتَكَلَّمُونَ إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ﴾\n\nقيل: إنهم يُؤْذَن لهم في الكلام حين يُؤْمَر بأهل النار إلى النار، وبأهل الجنة إلى الجنة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر بن سليمان، عن أبيه، قال: ثنا أبو عمرو - الذي يقصّ في طيئ - عن عكرمة، وقرأ هذه الآية: ﴿إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا﴾ قال: يُمرّ بأناس من أهل النار على ملائكة، فيقولون: أين تذهبون بهؤلاء؟ فيقال: إلى النار، فيقولون: بما كَسَبت أيديهم، وما ظلمهم الله، ويمرّ بأناس من أهل الجنة على ملائكة، فيقال: أين تذهبون بهؤلاء؟ فيقولون: إلى الجنة، فيقولون: برحمة الله دخلتم الجنة، قال: فيُؤْذَن لهم في الكلام، أو نحو ذلك.\n\nوقال آخرون: ﴿إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ﴾ بالتوحيد ﴿وَقَالَ صَوَابًا﴾ في الدنيا، فوحَّد الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا﴾ يقول: إلا من أذن له الربّ بشهادة أن لا إله إلا الله، وهي منتهى الصواب.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَقَالَ صَوَابًا﴾ قال: حقا في الدنيا وعمل به.\n\n⁕ حدثنا عمرو بن علي، قال: ثنا أبو معاوية، قال: ثنا إسماعيل، عن أبي صالح في قوله: ﴿إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا﴾ قال: لا إله إلا الله.\n\nقال أبو حفص: فحدثت به يحيى بن سعيد، فقال: أنا كتبته عن عبد الرحمن بن مهديّ، عن أبي معاوية.\n\n⁕ حدثني سعد بن عبد الله بن عبد الحكم، قال: ثنا حفص بن عمر العَدَنيّ، قال: ثنا الحكم بن أبان، عن عكرِمة في قوله: ﴿إِلا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا﴾ قال: لا إله إلا الله.\n\nوالصواب من القول في ذلك: أن يقال: إن الله تعالى ذكره أخبر عن خلقه أنهم لا يتكلمون يوم يقوم الروح والملائكة صفا، إلا من أذن له منهم في الكلام الرحمن، وقال صوابا، فالواجب أن يقال كما أخبر إذ لم يخبرنا في كتابه، ولا على لسان رسوله، أنه عَنَى بذلك نوعا من أنواع الصواب، والظاهر محتمل جميعه.","37":36,"38":36,"39":"القول في تأويل قوله تعالى: ﴿ذَلِكَ الْيَوْمُ الْحَقُّ فَمَنْ شَاءَ اتَّخَذَ إِلَى رَبِّهِ مَآبًا (٣٩) إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنْتُ تُرَابًا (٤٠) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿ذَلِك الْيَوْمُ﴾ يعني: يوم القيامة، وهو يوم يقوم الروح والملائكة صفا ﴿الْحَقُّ﴾ يقول: إنه حقّ كائن لا شكّ فيه.\n\n* *\n\nوقوله: ﴿فَمَنْ شَاءَ اتَّخَذَ إِلَى رَبِّهِ مَآبًا﴾\n\nيقول: فمن شاء من عباده اتخذ بالتصديق بهذا اليوم الحقّ، والاستعداد له، والعمل بما فيه النجاة له من أهواله ﴿مآبًا﴾ ، يعني: مرجعا، وهو مَفْعَلٌ من قولهم: آب فلان من سفره، كما قال عبيد:\n\nوكُل ذِي غَيْبَةٍ يَئُوب ... وغائِبُ المَوْتِ لا يَئُوبُ\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَمَنْ شَاءَ اتَّخَذَ إِلَى رَبِّهِ مَآبًا﴾ قال: اتخذوا إلى الله مآبًا بطاعته، وما يقرّبهم إليه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِلَى رَبِّهِ مَآبًا﴾ قال: سبيلا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿مآبًا﴾ يقول: مرجعا منزلا.\n\n* *\n\nوقوله: ﴿إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا﴾\n\nيقول: إنا حذّرناكم أيها الناس عذابًا قد دنا منكم وقرُب، وذلك ﴿يَوْمَ يَنْظُرُ الْمَرْءُ﴾ المؤمن ﴿مَا قَدَّمَتْ يَدَاهُ﴾ من خير اكتسبه في الدنيا، أو شرّ سَلَفَهُ، فيرجو ثواب الله على صالح أعماله، ويخاف عقابه على سيئها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن مبارك، عن الحسن ﴿يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ﴾ قال: المرء المؤمن يحذَر الصغيرة، ويخاف الكبيرة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن محمد بن جحَّادة، عن الحسن ﴿يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ﴾ قال: المرء المؤمن.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو أحمد، قال: ثنا سفيان، عن محمد بن جحادة، عن الحسن، في قوله: ﴿يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ﴾ قال: المرء المؤمن.\n\n* *\n\nوقوله: ﴿وَيَقُولُ الْكَافِرُ يَالَيْتَنِي كُنْتُ تُرَابًا﴾\n\nيقول تعالى ذكره: ويقول الكافر يومئذ تمنيا لما يلقى من عذاب الله الذي أعدّه لأصحابه الكافرين به، يا ليتني كنت ترابًا كالبهائم التي جُعِلت ترابًا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن بشار، قال: ثنا محمد بن جعفر وابن أبي عديّ، قالا ثنا عوف، عن أبي المغيرة، عن عبد الله بن عمرو، قال: \" إذا كان يوم القيامة، مُدّ الأديم، وحُشِر الدوابّ والبهائم والوحش، ثم يحصل القصاص بين الدوابّ، يقتصّ للشاة الجمَّاء من الشاة القرناء نطحتها، فإذا فرغ من القصاص بين الدوابّ، قال لها: كوني ترابا، قال: فعند ذلك يقول الكافر: يا ليتني كنت ترابًا \".\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر؛ قال: وحدثني جعفر بن بُرْقَان، عن يزيد بن الأصمّ، عن أبي هريرة، قال: \" إن الله يحشر الخلق كلهم، كل دابة وطائر وإنسان، يقول للبهائم والطير: كونوا ترابًا، فعند ذلك يقول الكافر: يا ليتني كنت ترابا \".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا المحاربي عبد الرحمن بن محمد، عن إسماعيل بن رافع المدني، عن يزيد بن زياد، عن محمد بن كعب القُرظيِّ، عن رجل من الأنصار، عن أبي هريرة، أن رسول الله ﷺ قال: \"يَقْضِي اللهُ بَينَ خَلْقِهِ الجِنِّ والإنْسِ والبَهائم، وإنَّه لَيَقِيدُ يَوْمَئِذٍ الجَمَّاءَ مِنَ القَرْناءِ، حتى إذَا لَمْ يَبْقَ تَبِعَةٌ عِنْدَ وَاحِدَةٍ لأخْرَى، قالَ اللهُ: كُونُوا تُرَابًا، فَعِنْدَ ذلكَ يَقُولُ الكافِرُ: يا لَيْتَنِي كُنْتُ تُرَابًا\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَالَيْتَنِي كُنْتُ تُرَابًا﴾ وهو الهالك المفرط العاجز، وما يمنعه أن يقول ذلك وقد راج عليه عَوْرَاتُ عمله، وقد استَقبل الرحمن وهو عليه غضبان، فتمنى الموت يومئذ، ولم يكن في الدنيا شيء أكرهَ عنده من الموت.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن أبي الزناد عبد الله بن ذكوان، قال: إذا قُضِيَ بين الناس، وأمر بأهل النار إلى النار قيل لمؤمني الجنّ ولسائر الأمم سوى ولد آدم: عُودُوا ترابًا، فإذا نظر الكفار إليهم قد عادوا ترابًا، قال الكافر: يا ليتني يا ليتني كنت ترابًا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، في قوله: ﴿وَيَقُولُ الْكَافِرُ يَالَيْتَنِي كُنْتُ تُرَابًا﴾ قال: إذا قيل للبهائم: كونوا ترابًا، قال الكافر: يا ليتني كنت ترابًا.\n\nآخر تفسير سورة عم يتساءلون.","40":39},"79":{"1":"القول في تأويل قوله تعالى: ﴿وَالنَّازِعَاتِ غَرْقًا (١) وَالنَّاشِطَاتِ نَشْطًا (٢) وَالسَّابِحَاتِ سَبْحًا (٣) فَالسَّابِقَاتِ سَبْقًا (٤) فَالْمُدَبِّرَاتِ أَمْرًا (٥) يَوْمَ تَرْجُفُ الرَّاجِفَةُ (٦) تَتْبَعُهَا الرَّادِفَةُ (٧) قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ (٨) أَبْصَارُهَا خَاشِعَةٌ (٩) ﴾\n\n.\n\nأقسم ربنا جلّ جلاله بالنازعات، واختلف أهل التأويل فيها، وما هي، وما تنزع؟ فقال بعضهم: هم الملائكة التي تنزع نفوس بني آدم، والمنزوع نفوس الآدميين.\n\nذكر من قال ذلك:\n\n⁕ حدثنا إسحاق بن أبي إسرائيل، قال: ثنا النضر بن شُمَيل، قال: أخبرنا شعبة، عن سليمان، قال: سمعت أبا الضحى، عن مسروق، عن عبد الله ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: الملائكة.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن مسلم، عن مسروق أنه كان يقول في النازعات: هي الملائكة.\n\n⁕ حدثنا ابن المثنى، قال: ثنا يوسف بن يعقوب، قال: ثنا شعبة، عن السُّدِّي، عن أبي صالح، عن ابن عباس في النازعات قال: حين تنزع نفسه.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: تنزع الأنفس.\n\n⁕ حدثنا أبو كُريب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: نزعت أرواحهم، ثم غرقت، ثم قذف بها في النار.\n\nوقال آخرون: بل هو الموت ينزع النفوس.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: الموت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عبد الله بن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\nوقال آخرون: هي النجوم تنزع من أفق إلى أفق.\n\n⁕ حدثنا الفضل بن إسحاق، قال: ثنا أبو قُتَيبة، قال: ثنا أبو العوّام، أنه سمع الحسن في ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: النجوم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: النجوم.\n\nوقال آخرون: هي القسيّ تنزع بالسهم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن واصل بن السائب، عن عطاء ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: القسيّ.\n\nوقال آخرون: هي النفس حين تُنزع.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن السدّي ﴿وَالنَّازِعَاتِ غَرْقًا﴾ قال: النفس حين تَغرق في الصدر.\n\nوالصواب من القول في ذلك عندي أن يقال: إن الله تعالى ذكره أقسم بالنازعات غرقا، ولم يخصص نازعة دون نازعة، فكلّ نازعة غرقا، فداخلة في قسمه، ملكا كان أو موتا، أو نجما، أو قوسا، أو غير ذلك. والمعنى: والنازعات إغراقا كما يغرق النازع في القوس.\n\n* *\n\nوقوله: ﴿وَالنَّاشِطَاتِ نَشْطًا﴾\n\nاختلف أهل التأويل أيضا فيهنّ، وما هنّ، وما الذي ينشط، فقال بعضهم: هم الملائكة، تنشِط نفس المؤمن فتقبضُها، كما ينشط العقال من البعير إذا حُلّ عنه.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: الملائكة.\n\nوكان الفرّاء يقول: الذي سمعت من العرب أن يقولوا: أنشطت، وكأنما أنشط من عقال، ورَبْطُها: نشطها، والرابط: الناشط؛ قال: وإذا رَبَطْتَ الحبل في يد البعير فقد نشطته تنشطه، وأنت ناشط، وإذا حللته فقد أنشطته.\n\nوقال آخرون: ﴿النَّاشِطاتِ نَشْطا﴾ هو الموت يَنْشِط نفسَ الإنسان.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: الموت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، قال: ثنا سفيان، عن عبد الله بن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن المثنى، قال: ثنا يوسف بن يعقوب، قال: ثنا شعبة عن السديّ، عن ابن عباس ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: حين تَنشِط نفسه.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن السدي ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: نشطها حين تُنشط من القدمين.\n\nوقال آخرون: هي النجوم تنشط من أفق إلى أفق.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قوله: ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: النجوم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: هنّ النجوم.\n\nوقال آخرون: هي الأوهاق  .\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل بن السائب، عن عطاء ﴿وَالنَّاشِطَاتِ نَشْطًا﴾ قال: الأوهاق.\n\nوالصواب من القول في ذلك عندي أن يقال: إن الله جلّ ثناؤه أقسم بالناشطات نشطا، وهي التي تنشط من موضع إلى موضع، فتذهب إليه، ولم يخصص الله بذلك شيئا دون شيء، بل عم القسم بجميع الناشطات والملائكة تنشط من موضع إلى موضع، وكذلك الموت، وكذلك النجوم والأوهاق وبقر الوحش أيضا تَنْشُط، كما قال الطِّرِمَّاح:\n\nوَهَلْ بِحَلِيفِ الخَيْلِ مِمَّنْ عَهِدْتُه ... بِهِ غَيْرُ أُحْدانَ النَّوَاشِطِ رُوع\n\nيعني بالنواشط: بقر الوحش، لأنها تنشط من بلدة إلى بلدة، كما قال رؤبة بن العجَّاج:\n\nتَنَشَّطَتْهُ كُلُّ مِغْلاةِ الْوَهْق\n\nوالهموم تنشط صاحبها، كما قال هِيمان بن قحافة:\n\nأمْسَتْ هُمُومِي تَنْشِطُ المَناشِطَا ... الشَّامَ بِي طَوْرًا وَطَوْرًا وَاسِطَا\n\nفكل ناشط فداخل فيما أقسم به إلا أن تقوم حجة يجب التسليم لها بأن المعنيّ بالقسم من ذلك بعض دون بعض.\n\n* *\n\nوقوله: ﴿وَالسَّابِحَاتِ سَبْحًا﴾\n\nيقول تعالى ذكره: واللواتي تسبح سبحا.\n\nواختلف أهل التأويل في التي أقسم بها جلّ ثناؤه من السابحات، فقال بعضهم: هي الموت تسبح في نفس ابن آدم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَالسَّابِحَاتِ سَبْحًا﴾ قال: الموت، هكذا وجدته في كتابي  .\n\n⁕ وقد حدثنا به ابن حميد، قال: ثنا مهران، قال: ثنا سفيان، عن عبد الله بن أبي نجيح، عن مجاهد ﴿وَالسَّابِحَاتِ سَبْحًا﴾ قال: الملائكة، وهكذا وجدت هذا أيضا في كتابي، فإن يكن ما ذكرنا عن ابن حميد صحيحا، فإن مجاهدا كان يرى أن نزول الملائكة من السماء سبَّاحة، كما يقال للفرس الجواد: إنه لسابح إذا مرّ يُسرعُ.\n\nوقال آخرون: هي النجوم تَسْبَح في فلكها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالسَّابِحَاتِ سَبْحًا﴾ قال: هِي النجوم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.\n\nوقال آخرون: هي السفن.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل بن السائب، عن عطاء ﴿وَالسَّابِحَاتِ سَبْحًا﴾ قال: السفن.\n\nوالصواب من القول في ذلك عندي أن يقال: إن الله جلّ ثناؤه أقسم بالسابحات سبحا من خلقه، ولم يخصص من ذلك بعضا دون بعض، فذلك  كل سابح، لما وصفنا قبل في النازعات  .\n\n* *\n\nوقوله: ﴿فَالسَّابِقَاتِ سَبْقًا﴾\n\nاختلف أهل التأويل فيها، فقال بعضهم: هي الملائكة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عبد الله بن أبي نجيح، عن مجاهد ﴿فَالسَّابِقَاتِ سَبْقًا﴾ قال: الملائكة.\n\n⁕ وقد حدثنا بهذا الحديث أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿فَالسَّابِقَاتِ سَبْقًا﴾ قال: الموت.\n\nوقال آخرون: بل هي الخيل السابقة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل بن السائب، عن عطاء ﴿فَالسَّابِقَاتِ سَبْقًا﴾ قال: الخيل.\n\nوقال آخرون: بل هي النجوم يسبق بعضها بعضا في السير.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالسَّابِقَاتِ سَبْقًا﴾ قال: هي النجوم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.\n\nوالقول عندنا في هذه مثل القول في سائر الأحرف الماضية.\n\n* *\n\nوقوله: ﴿فَالْمُدَبِّرَاتِ أَمْرًا﴾\n\nيقول: فالملائكة المدبرة ما أمرت به من أمر الله، وكذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالْمُدَبِّرَاتِ أَمْرًا﴾ قال: هي الملائكة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.\n\n* *\n\nوقوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾\n\nيقول تعالى ذكره: يوم ترجف الأرض والجبال للنفخة الأولى ﴿تَتْبَعُهَا الرَّادِفَةُ﴾ تتبعها الأخرى بعدها، هي النفخة الثانية التي ردفت الأولى لبعث يوم القيامة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، قوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ يقول: النفخة الأولى.\n\n* *\n\nوقوله: ﴿تَتْبَعُهَا الرَّادِفَةُ﴾\n\nيقول: النفخة الثانية.\n\n⁕ حدثنا محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ﴾ يقول: تتبع الآخرة الأولى، والراجفة: النفخة الأولى، والرادفة: النفخة الآخرة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ﴾ قال: هما النفختان: أما الأولى فتميت الأحياء، وأما الثانية فتُحيي الموتى، ثم تلا الحسن: ﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الأرْضِ إِلا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ﴾ قال: هما الصيحتان، أما الأولى فتُميت كل شيء بإذن الله، وأما الأخرى فتُحيي كل شيء بإذن الله، إن نبيّ الله ﷺ كان يقول: \" بَيْنَهُما أرْبَعُونَ\" قال أصحابه: والله ما زادنا على ذلك. وذُكر لنا أن نبيّ الله ﷺ كان يقول: \" يُبْعَثُ فِي تِلْك الأرْبَعِينَ مَطَرٌ يُقال لَهُ الْحَياةُ، حتى تَطِيبَ الأرْضُ وتَهْتَزَّ، وتَنْبُتَ أجْسادُ النَّاسِ نَباتَ البَقْل، ثُمَّ تُنْفَخُ الثَّانِيَةُ، فإذَا هُمْ قِيامٌ يَنْظُرُونَ\".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عبد الرحمن بن محمد المحاربي، عن إسماعيل بن رافع المدني، عن يزيد ابن أبي زياد عن رجل، عن محمد بن كعب القرظي، عن رجل من الأنصار، عن أبي هريرة، قال: قال رسول الله ﷺ، وذكر الصور، فقال أبو هريرة: يا رسول الله، وما الصور؟ قال: \" قَرْنٌ\". قال: فكيف هو؟ قال: \" قَرْنٌ عَظِيمٌ يُنْفَخُ فِيهِ ثَلاثُ نَفَخاتٍ: الأولى نَفْخَةُ الفَزَع، والثَّانِيَةُ نَفْخَةُ الصَّعْق، والثَّالِثَةُ نَفْخَةُ القِيام، فَيَفْزَعُ أهْلُ السَّمَوَاتِ والأرْضِ إلا مَنْ شاء الله، ويأمر الله فيدِيمُها، ويطوّلها، ولا يفتر، وهي التي تقول: ما ينظر هؤلاء إلا صيحة واحدة مالها من فَوَاق فيسير الله الجبال، فتكون سَرابًا، وتُرَجّ الأرضُ بأهلها رجًّا، وهي التي يقول: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ \".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عبيد الله بن محمد بن عقيل، عن الطفيل بن أبيّ، عن أبيه، قال: قرأ رسول الله ﷺ: (يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ) فقال: \" جاءت الراجفة تتبعها الرادفة، جاء الموت بما فيه\".\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ : النفخة الأولى ﴿تَتْبَعُهَا الرَّادِفَةُ﴾ : النفخة الأخرى.\n\nوقال آخرون: في ذلك ما:-\n\n⁕ حدثني به محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ قال: ترجف الأرض والجبال، وهي الزلزلة وقوله: ﴿الرَّادِفَةُ﴾ قال: هو قوله: ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ ﴿فَدُكَّتَا دَكَّةً وَاحِدَةً﴾ .\n\nوقال آخرون: ترجف الأرض، والرادفة: الساعة.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ الأرض، وفي قوله: ﴿تَتْبَعُهَا الرَّادِفَةُ﴾ قال: الرادفة: الساعة.\n\nواختلف أهل العربية في موضع جواب قوله: ﴿وَالنَّازِعَاتِ غَرْقًا﴾ فقال بعض نحويِّي البصرة: قوله ﴿وَالنَّازِعَاتِ غَرْقًا﴾ : قسم والله أعلم على ﴿إِنَّ فِي ذَلِكَ لَعِبْرَةً لِمَنْ يَخْشَى﴾ وإن شئت جعلتها على ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ ﴿قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ وهو كما قال الله وشاء أن يكون في كل هذا، وفي كلّ الأمور. وقال بعض نحويي الكُوفة: جواب القسم في النازعات: ما تُرِك لمعرفة السامعين بالمعنى، كأنه لو ظهر كان لَتُبْعَثُنّ ولتحاسبنّ. قال: ويدل على ذلك ﴿أَئِذَا كُنَّا عِظَامًا نَخِرَةً﴾ . ألا ترى أنه كالجواب لقوله: ﴿لَتُبْعَثُنَّ﴾ إذ قال: ﴿أَئِذَا كُنَّا عِظَامًا نَخِرَةً﴾ ، وقال آخر منهم نحو هذا، غير أنه قال: لا يجوز حذف اللام في جواب اليمين، لأنها إذا حذفت لم يُعرف موضعها، وذلك أنها تلي كلّ كلام.\n\nوالصواب من القول في ذلك عندنا، أن جواب القسم في هذا الموضع مما استغني عنه بدلالة الكلام، فترك ذكره.\n\n* *\n\nوقوله: ﴿قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾\n\nيقول تعالى ذكره: قلوب خَلْقٍ من خلقه يومئذ، خائفة من عظيم الهول النازل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ يقول: خائفة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَاجِفَةٌ﴾ : خائفة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في ﴿وَاجِفَةٌ﴾ قال: خائفة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ يقول: خائفة، وجفت مما عاينت يومئذ.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ قال: الواجفة: الخائفة.\n\n* *\n\nوقوله: ﴿أَبْصَارُهَا خَاشِعَةٌ﴾\n\nيقول: أبصار أصحابها ذليلة مما قد علاها من الكآبة والحزن من الخوف والرعب الذي قد نزل بهم من عظيم هول ذلك اليوم.\n\nكما:-\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿أَبْصَارُهَا خَاشِعَةٌ﴾ قال: خاشعة للذلّ الذي قد نزل بها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَبْصَارُهَا خَاشِعَةٌ﴾ يقول: ذليلة.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1,"10":"القول في تأويل قوله تعالى: ﴿يَقُولُونَ أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ (١٠) أَئِذَا كُنَّا عِظَامًا نَخِرَةً (١١) قَالُوا تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ (١٢) فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ (١٣) فَإِذَا هُمْ بِالسَّاهِرَةِ (١٤) ﴾\n\n.\n\nيقول تعالى ذكره: يقول هؤلاء المكذّبون بالبعث من مشركي قريش إذا قيل لهم: إنكم مبعوثون من بعد الموت: أئنا لمردودون إلى حالنا الأولى قبل الممات، فراجعون أحياء كما كنا قبل هلاكنا، وقبل مماتنا، وهو من قولهم: رجع فلان على حافرته: إذا رجع من حيث جاء؛ ومنه قول الشاعر:\n\nأحافِرَةً عَلى صَلَعٍ وشَيْبٍ ... مَعاذَ اللهِ مِنْ سَفَهٍ وطَيْشٍ\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿الْحَافِرَةِ﴾ يقول: الحياة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ يقول: أئنا لنحيا بعد موتنا، ونبعث من مكاننا هذا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة يقول: ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ أئنا لمبعوثون خلقا جديدا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فِي الْحَافِرَةِ﴾ قال: أي مردودون خَلقا جديدا.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي معشر، عن محمد بن قيس أو محمد بن كعب القُرَظيّ ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ قال: في الحياة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ قال: في الحياة.\n\nوقال آخرون: الحافرة: الأرض المحفورة التي حُفرت فيها قبورهم، فجعلوا ذلك نظير قوله: ﴿مِنْ مَاءٍ دَافِقٍ﴾ . يعني مدفوق، وقالوا: الحافرة بمعنى المحفورة، ومعنى الكلام عندهم: أئنا لمردودون في قبورنا أمواتا.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿الْحَافِرَةِ﴾ قال: الأرض: نبعث خلقا جديدا، قال: البعث.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ قال: الأرض، نبعث خلقا جديدا.\n\nوقال آخرون: الحافرة: النار.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: سمعت ابن زيد يقول في قول الله: ﴿أَئِنَّا لَمَرْدُودُونَ فِي الْحَافِرَةِ﴾ قال: الحافرة: النار، وقرأ قول الله ﴿تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ﴾ قال: ما أكثر أسماءها، هي النار، وهي الجحيم، وهي سَقَرُ، وهي جهنم، وهي الهاوية، وهي الحافرة، وهي لَظَى، وهي الحُطَمة.\n\n* *\n\nوقوله: ﴿أَئِذَا كُنَّا عِظَامًا نَخِرَةً﴾\n\nاختلفت القرّاء قي قراءة ذلك، فقرأته عامة قرّاء المدينة والحجاز والبصرة ﴿نَخِرَةً﴾ بمعنى: بالية. وقرأ ذلك عامة قرّاء الكوفة ﴿ناخِرَةً﴾ بألف، بمعنى: أنها مجوّفة تنخَر الرياح في جوفها إذا مرّت بها. وكان بعض أهل العلم بكلام العرب من الكوفيين يقول: الناخرة والنخرة سواء في المعنى، بمنزلة الطامع والطمِع، والباخل والبَخِل؛ وأفصح اللغتين عندنا وأشهرهما عندنا ﴿نَخِرَةً﴾ ، بغير ألف، بمعنى: بالية، غير أن رءوس الآي قبلها وبعدها جاءت بالألف، فأعجب إليّ لذلك أن تُلْحق ناخرة بها ليتفق هو وسائر رءوس الآيات، لولا ذلك كان أعجب القراءتين إليّ حذف الألف منها.\n\nذكر من قال ﴿نَخِرَةً﴾ : بالية:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿أَئِذَا كُنَّا عِظَامًا نَخِرَةً﴾ فالنخرة: الفانية البالية.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿عِظَامًا نَخِرَةً﴾ قال: مرفوتة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَئِذَا كُنَّا عِظَامًا﴾ تكذيبا بالبعث ﴿نَاخِرَةً﴾ بالية. قالوا: ﴿تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ﴾ يقول جلّ ثناؤه عن قيل هؤلاء المكذّبين بالبعث، قالوا: تلك: يعنون تلك الرجعة أحياء بعد الممات، إذًا: يعنون الآن، كرّة: يعنون رجعة، خاسرة: يعنون غابنة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِذًا كَرَّةٌ خَاسِرَةٌ﴾ : أي رجعة خاسرة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ﴾ قال: وأيّ كرّة أخسر منها، أُحيوا ثم صاروا إلى النار، فكانت كرّة سوء.\n\n* *\n\nوقوله: ﴿فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ﴾\n\nيقول تعالى ذكره: فإنما هي صيحة واحدة، ونَفخة تنفخ في الصور، وذلك هو الزجرة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿زَجْرَةٌ وَاحِدَةٌ﴾ قال: صيحة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿زَجْرَةٌ وَاحِدَةٌ﴾ قال: الزجرة: النفخة في الصور.\n\n* *\n\nوقوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾\n\nيقول تعالى ذكره: فإذا هؤلاء المكذبون بالبعث المتعجبون من إحياء الله إياهم من بعد مماتهم، تكذيبا منهم بذلك بالساهرة، يعني بظهر الأرض، والعرب تسمي الفلاة ووجه الأرض ساهرة، وأراهم سموا ذلك بها، لأن فيه نوم الحيوان وسهرها، فوصف بصفة ما فيه؛ ومنه قول أُميَّة بن أبي الصَّلْت:\n\nوفِيها لَحْمُ ساهِرَةٍ وبَحْرٍ ... وَمَا فاهُوا بِهِ لَهُمُ مُقِيمُ\n\nومنه قول أخي نهم يوم ذي قار لفرسه:\n\nأَقْدِمْ \"مِحاجُ\" إنها الأساوِرَه ... وَلا يَهُولَنَّكَ رِجْلٌ نادِرَهْ ... فإنَّمَا قَصْرُكَ تُرْبُ السَّاهِرَهْ ... ثُمَّ تَعُودُ بَعْدَها فِي الْحَافِرَهْ ... مِنْ بَعْدِ ما كُنْتَ عِظاما ناخِرَهْ\n\nواختلف أهل التأويل في معناها، فقال بعضهم مثل الذي قلنا.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا هشيم، قال: أخبرنا حصين، عن عكرِمة، عن ابن عباس، في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: على الأرض، قال: فذكر شعرا قاله أُمية بن أبي الصلت، فقال:\n\nعِنْدَنا صَيْدُ بَحْرٍ وصَيْدُ ساهِرَةٍ\n\n⁕ حدثنا محمد بن عبد الله بن بزيع، قال: ثنا أبو محصن، عن حصين، عن عكرِمة، في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: الساهرة: الأرض، أما سمعت: لهم صيد بحر، وصيد ساهرة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ يعني: الأرض.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: ثنا عُمارة بن أبي حفصة، عن عكرِمة، في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: فإذا هم على وجه الأرض، قال: أو لم تسمعوا ما قال أُمية بن أبي الصلت لهم:\n\nوفِيها لَحْمُ ساهِرَةٍ وبَحْرٍ ... .......\n\n⁕ حدثنا عمارة بن موسى، قال: ثنا عبد الوارث بن سعيد، قال: ثنا عمارة، عن عكرمة، في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: فإذا هم على وجه الأرض، قال أمية:\n\nوفِيها لَحْمُ ساهِرَةٍ وبَحْرٍ ... .......\n\n⁕ حدثنا يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ فإذا هم على وجه الأرض.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿بِالسَّاهِرَةِ﴾ قال: المكان المستوي.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: لما تباعد البعث في أعين القوم قال الله: ﴿فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ يقول: فإذا هم بأعلى الأرض بعد ما كانوا في جوفها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿بِالسَّاهِرَةِ﴾ قال: فإذا هم يخرجون من قبورهم فوق الأرض والأرض، الساهرة، قال: فإذا هم يخرجون.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن خصيف، عن عكرمة وأبي الهيثم، عن سعيد بن جُبير ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: بالأرض.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبي الهيثم، عن سعيد بن جُبير، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حصين، عن عكرمة، مثله.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ : وجه الأرض.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: الساهرة ظهر الأرض فوق ظهرها.\n\nوقال آخرون: الساهرة: اسم مكان من الأرض بعينه معروف.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ بن سهل، قال: ثني الوليد بن مسلم، عن عثمان بن أبي العاتكة، قوله: ﴿فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: بالصُّقْع الذي بين جبل حسان وجبل أريحاء، يمدّه الله كيف يشاء.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: أرض بالشام.\n\nوقال آخرون: هو جبل بعينه معروف.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عليّ بن سهل، قال: ثنا الحسن بن بلال، قال: ثنا حماد، قال: أخبرنا أبو سنان، عن وهب بن منبه، قال في قول الله: ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: الساهرة: جبل إلى جنب بيت المقدس.\n\nوقال آخرون: هي جهنم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن مروان العقيلي، قال: ثني سعيد بن أبي عروبة، عن قتادة ﴿فَإِذَا هُمْ بِالسَّاهِرَةِ﴾ قال: في جهنم.","11":10,"12":10,"13":10,"14":10,"15":"القول في تأويل قوله تعالى: ﴿هَلْ أتَاكَ حَدِيثُ مُوسَى (١٥) ﴾\n\n.","16":"القول في تأويل قوله تعالى: ﴿إِذْ نَادَاهُ رَبُّهُ بِالْوَادِي الْمُقَدَّسِ طُوًى (١٦) اذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى (١٧) فَقُلْ هَلْ لَكَ إِلَى أَنْ تَزَكَّى (١٨) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: هل أتاك يا محمد حديث موسى بن عمران، وهل سمعت خبره حين ناجاه ربه بالواد المقدّس، يعني بالمقدّس: المطهر المبارك. وقد ذكرنا أقوال أهل العلم في ذلك فيما مضى، فأغنى عن إعادته في هذا الموضع، وكذلك بيَّنَّا معنى قوله: ﴿طُوًى﴾ وما قال فيه أهل التأويل، غير أنا نذكر بعض ذلك هاهنا.\n\nوقد اختلف أهل التأويل في قوله: ﴿طُوى﴾ فقال بعضهم: هو اسم الوادي.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿طُوًى﴾ اسم الوادي.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّكَ بِالْوَادِي الْمُقَدَّسِ طُوًى﴾ قال: اسم المقدّس طوى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِذْ نَادَاهُ رَبُّهُ بِالْوَادِي الْمُقَدَّسِ طُوًى﴾ كنا نحدّث أنه قدّس مرّتين، واسم الوادي طُوًى.\n\nوقال آخرون: بل معنى ذلك: طأ الأرض حافيا.\n\nذكر بعض من قال ذلك:\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن سفيان، عن ابن جُرَيج، عن مجاهد ﴿إِنَّكَ بِالْوَادِي الْمُقَدَّسِ طُوًى﴾ قال: طأ الأرض بقدمك.\n\nوقال آخرون: بل معنى ذلك أن الوادي قدّس طوى: أي مرّتين، وقد بيَّنا ذلك كله ووجوهه فيما مضى بما أغنى عن إعادته في هذا الموضع. وقرأ ذلك الحسن بكسر الطاء، وقال: بُثَّتْ فيه البركة والتقديس مرّتين. حدثنا بذلك أحمد بن يوسف، قال: ثنا القاسم، قال: ثنا هشيم، عن عوف، عن الحسن.\n\nواختلفت القراء في قراءة ذلك، فقرأته عامة قرّاء المدينة والبصرة ﴿طُوًى﴾ بالضمّ ولم يجرّوه وقرأ ذلك بعض أهل الشأم والكوفة ﴿طُوًى﴾ بضمّ الطاء والتنوين.\n\n* *\n\nوقوله: ﴿اذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى﴾\n\nيقول تعالى ذكره: نادى موسى ربُّه: أن اذهب إلى فرعون، فحذفت \" أن\" إذ كان النداء قولا فكأنه قيل لموسى قال ربه: اذهب إلى فرعون.\n\n* *\n\nوقوله: ﴿إِنَّهُ طَغَى﴾\n\nيقول: عتا وتجاوز حدّه في العدوان، والتكبر على ربه.\n\n* *\n\nوقوله: ﴿فَقُلْ هَلْ لَكَ إِلَى أَنْ تَزَكَّى﴾\n\nيقول: فقل له: هل لك إلى أن تتطهَّر من دنس الكفر، وتؤمِن بربك؟\n\nكما:-\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿هَلْ لَكَ إِلَى أَنْ تَزَكَّى﴾ قال: إلى أن تُسلم. قال: والتزكي في القرآن كله: الإسلام، وقرأ قول الله: ﴿وَذَلِكَ جَزَاءُ مَنْ تَزَكَّى﴾ قال: من أسلم، وقرأ ﴿وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى﴾ قال: يسلم، وقرأ ﴿وَمَا عَلَيْكَ أَلا يَزَّكَّى﴾ . ألا يسلم.\n\n⁕ حدثني سعيد بن عبد الله بن عبد الحَكَم، قال: ثنا حفص بن عُمَرَ العَدَنِيّ، عن الحكم بن أبان عن عكرمة، قول موسى لفرعون: ﴿هَلْ لَكَ إِلَى أَنْ تَزَكَّى﴾ هل لك إلى أن تقول: لا إله إلا الله.\n\nواختلفت القرّاء في قراءة قوله: ﴿تَزَكَّى﴾ فقرأته عامة قرَّاء المدينة ﴿تَزَّكَّى﴾ بتشديد الزاي، وقرأته عامة قرّاء الكوفة والبصرة ﴿إِلَى أَنْ تَزَكَّى﴾ بتخفيف الزاي. وكان أبو عمرو يقول فيما ذُكر عنه ﴿تَزَّكَّى﴾ بتشديد الزاي، بمعنى: تتصدّق بالزكاة، فتقول: تتزكى، ثم تدغم، وموسى لم يدع فرعون إلى أن يتصدّق وهو كافر، إنما دعاه إلى الإسلام، فقال: تزكى: أي تكون زاكيا مؤمنا، والتخفيف في الزاي هو أفصح القراءتين في العربية.","17":16,"18":16,"19":"القول في تأويل قوله تعالى: ﴿وَأَهْدِيَكَ إِلَى رَبِّكَ فَتَخْشَى (١٩) فَأَرَاهُ الآيَةَ الْكُبْرَى (٢٠) فَكَذَّبَ وَعَصَى (٢١) ثُمَّ أَدْبَرَ يَسْعَى (٢٢) فَحَشَرَ فَنَادَى (٢٣) فَقَالَ أَنَا رَبُّكُمُ الأعْلَى (٢٤) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه موسى: قل لفرعون: هل لك إلى أن أرشدك إلى ما يرضي ربك، وذلك الدين القيم ﴿فَتَخْشَى﴾ يقول: فتخشى عقابه بأداء ما ألزمك من فرائضه، واجتناب ما نهاك عنه من معاصيه.\n\n* *\n\nقوله: ﴿فَأَرَاهُ الآيَةَ الْكُبْرَى﴾\n\nيقول تعالى ذكره: فأرى موسى فرعون الآية الكبرى، يعني الدلالة الكبرى، على أنه لله رسول أرسله إليه، فكانت تلك الآية يد موسى إذ أخرجها بيضاء للناظرين، وعصاه إذ تحوّلت ثعبانا مبينا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني أبو زائدة زكريا بن يحيى بن أبي زائدة، قال: ثنا مسلم بن إبراهيم، عن محمد بن سيف أبي رجاء هكذا هو في كتابي وأظنه عن نوح بن قيس، عن محمد بن سيف، قال: سمعت الحسن يقول في هذه الآية: ﴿فَأَرَاهُ الآيَةَ الْكُبْرَى﴾ قال: يده وعصاه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿فَأَرَاهُ الآيَةَ الْكُبْرَى﴾ قال: عصاه ويده.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَأَرَاهُ الآيَةَ الْكُبْرَى﴾ قال: رأى يد موسى وعصاه، وهما آيتان.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿الآيَةَ الْكُبْرَى﴾ قال: عصاه ويده.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب قال: قال ابن زيد، في قوله: ﴿فَأَرَاهُ الآيَةَ الْكُبْرَى﴾ قال: العصا والحية.\n\n* *\n\nوقوله: ﴿فَكَذَّبَ وَعَصَى﴾\n\nيقول: فكذّب فرعون موسى فيما أتاه من الآيات المعجزة، وعصاه فيما أمره به من طاعته ربه، وخَشيته إياه.\n\n* *\n\nوقوله: ﴿ثُمَّ أَدْبَرَ يَسْعَى﴾\n\nيقول: ثم ولَّى مُعرضا عما دعاه إليه موسى من طاعته ربه، وخشيته وتوحيده. ﴿يَسْعَى﴾ يقول: يعمل في معصية الله، وفيما يُسخطه عليه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ثُمَّ أَدْبَرَ يَسْعَى﴾ قال: يعمل بالفساد.\n\n* *\n\nوقوله: ﴿فَحَشَرَ فَنَادَى﴾\n\nيقول: فجمع قومه وأتباعه، فنادى فيهم ﴿فَقالَ﴾ لهم: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ الذي كلّ ربّ دوني، وكذب الأحمق.\n\nوبمثل الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَحَشَرَ فَنَادَى﴾ قال: صرخ وحشر قومه، فنادى فيهم، فلما اجتمعوا قال: ﴿أَنَا رَبُّكُمُ الأعْلَى فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ .","20":19,"21":19,"22":19,"23":19,"24":19,"25":"القول في تأويل قوله تعالى: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى (٢٥) إِنَّ فِي ذَلِكَ لَعِبْرَةً لِمَنْ يَخْشَى (٢٦) أَأَنْتُمْ أَشَدُّ خَلْقًا أَمِ السَّمَاءُ بَنَاهَا (٢٧) رَفَعَ سَمْكَهَا فَسَوَّاهَا (٢٨) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: ﴿فَأَخَذَهُ اللَّهُ﴾ فعاقبه الله ﴿نَكَالَ الآخِرَةِ وَالأولَى﴾ يقول: عقوبة الآخرة من كلمتيه، وهي قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ ، والأولى قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: سمعت أبا بكر، وسُئل عن هذا فقال: كان بينهما أربعون سنة، بين قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ ، وقوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ قال: هما كلمتاه، ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قيل له: مَن ذكره؟ قال: أبو حصين، فقيل له: عن أبي الضُّحَى، عن ابن عباس؟ قال: نعم.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: أما الأولى فحين قال: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ ، وأما الآخرة فحين قال: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ .\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا محمد بن أبي الوضَّاح، عن عبد الكريم الجَزريّ، عن مجاهد، في قوله: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: هو قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ ، وقوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ وكان بينهما أربعون سنة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا أبو عوانة، عن إسماعيل الأسدي، عن الشعبيّ بمثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن زكريا، عن عامر ﴿نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: هما كلمتاه ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ و ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿نَكَالَ الآخِرَةِ وَالأولَى﴾ فذلك قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ والآخرة في قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: أخبرني من سمع مجاهدا يقول: كان بين قول فرعون: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ وبين قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ أربعون سنة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿نَكَالَ الآخِرَةِ وَالأولَى﴾ أما الأولى فحين قال فرعون: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ ، وأما الآخرة فحين قال: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ فأخذه الله بكلمتيه كلتيهما، فأغرقه في اليم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: اختلفوا فيها فمنهم من قال: نكال الآخرة من كلمتيه، والأولى قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ وقوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ .\n\nوقال آخرون: عذاب الدنيا وعذاب الآخرة، عجَّل الله له الغرق مع ما أعدّ له من العذاب في الآخرة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن خيثمة الجعفي، قال: كان بين كلمتي فرعون أربعون سنة، قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ ، وقوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن ثُوير، عن مجاهد، قال: مكث فرعون في قومه بعد ما قال: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ أربعين سنة.\n\nقال آخرون: بل عُنِيَ بذلك: فأخذه الله نكال الدنيا والآخرة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا هَوْذَة، قال: ثنا عوف، عن الحسن، في قوله: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: الدنيا والآخرة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن الحسن ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: عقوبة الدنيا والآخرة، وهو قول قتادة.\n\nوقال آخرون: الأولى عصيانه ربه وكفره به، والآخرة قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل بن سميع، عن أبي رَزين ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: الأولى تكذيبه وعصيانه، والآخرة قوله: ﴿أَنَا رَبُّكُمُ الأعْلَى﴾ ، ثم قرأ: ﴿فَكَذَّبَ وَعَصَى ثُمَّ أَدْبَرَ يَسْعَى فَحَشَرَ فَنَادَى فَقَالَ أَنَا رَبُّكُمُ الأعْلَى﴾ فهي الكلمة الآخرة.\n\nوقال آخرون: بل عُنِيَ بذلك أنه أخذه بأوّل عمله وآخره.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: أوّل عمله وآخره.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: أول أعماله وآخرها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبي: ﴿فَأَخَذَهُ اللَّهُ نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: نكال الآخرة من المعصية والأولى.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، قوله: ﴿نَكَالَ الآخِرَةِ وَالأولَى﴾ قال: عمله للآخرة والأولى.\n\n* *\n\nوقوله: ﴿إِنَّ فِي ذَلِكَ لَعِبْرَةً لِمَنْ يَخْشَى﴾\n\nيقول تعالى ذكره: إن في العقوبة التي عاقب الله بها فرعون في عاجل الدنيا، وفي أخذه إياه نكال الآخرة والأولى، عظة ومعتبرا لمن يخاف الله ويخشى عقابه، وأخرج نكال الآخرة مصدرا من قوله: ﴿فَأَخَذَهُ اللَّهُ﴾ لأن قوله ﴿فَأَخَذَهُ اللَّهُ﴾ نكل به فجعل ﴿نَكَالَ الآخِرَةِ﴾ مصدرا من معناه لا من لفظه.\n\n* *\n\nوقوله: ﴿أَأَنْتُمْ أَشَدُّ خَلْقًا أَمِ السَّمَاءُ بَنَاهَا﴾\n\nيقول تعالى ذكره للمكذّبين بالبعث من قريش، القائلين: ﴿أَئِذَا كُنَّا عِظَامًا نَخِرَةً قَالُوا تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ﴾ أأنتم أيها الناس أشد خلقا، أم السماء بناها ربكم، فإن من بنى السماء فرفعها سقفا، هَيِّن عليه خلقكم وخلق أمثالكم، وإحياؤكم بعد مماتكم وليس خلقكم بعد مماتكم بأشدّ من خلق السماء. وعني بقوله: ﴿بَناها﴾ : رفعها فجعلها للأرض سقفا.\n\n* *\n\nوقوله: ﴿رَفَعَ سَمْكَهَا فَسَوَّاهَا﴾\n\nيقول تعالى ذكره: فسوّى السماء، فلا شيء أرفع من شيء، ولا شيء أخفض من شيء، ولكن جميعها مستوي الارتفاع والامتداد.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿رَفَعَ سَمْكَهَا فَسَوَّاهَا﴾ يقول: رفع بناءها فسوّاها.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿رَفَعَ سَمْكَهَا فَسَوَّاهَا﴾ قال: رفع بناءها بغير عمد.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿رَفَعَ سَمْكَهَا﴾ يقول: بُنيانها.","26":25,"27":25,"28":25,"29":"القول في تأويل قوله تعالى: ﴿وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا (٢٩) وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا (٣٠) أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا (٣١) وَالْجِبَالَ أَرْسَاهَا (٣٢) ﴾\n\n.\n\n* *\n\nوقوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾\n\nيقول تعالى ذكره: أظلم ليل السماء، فأضاف الليل إلى السماء، لأن الليل غروب الشمس، وغروبها وطلوعها فيها، فأضيف إليها لمَّا كان فيها، كما قيل: نجوم الليل، إذ كان فيه الطلوع والغروب.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾ يقول: أظلم ليلها.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَأَغْطَشَ لَيْلَهَا﴾ يقول: أظلم ليلها.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾ قال: أظلم.\n\n⁕ حدثني بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾ قال: أظلم ليلها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَأَغْطَشَ لَيْلَهَا﴾ قال: أظلم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب. قال: قال ابن زيد، في قوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾ قال: الظُّلمة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَأَغْطَشَ لَيْلَهَا﴾ يقول: أظلم ليلها.\n\n⁕ حدثنا محمد بن سنان القزّاز، قال: ثنا حفص بن عمر، قال: ثنا الحكم عن عكرمة ﴿وَأَغْطَشَ لَيْلَهَا﴾ قال: أظلم ليلها.\n\n* *\n\nوقوله: ﴿وَأَخْرَجَ ضُحَاهَا﴾\n\nيقول: وأخرج ضياءها، يعني: أبرز نهارها فأظهره، ونوّر ضحاها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَأَخْرَجَ ضُحَاهَا﴾ نوّرها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَأَخْرَجَ ضُحَاهَا﴾ يقول: نوّر ضياءها.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَأَخْرَجَ ضُحَاهَا﴾ قال: نهارها.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: (وَأَخْرَجَ ضُحَاهَا) قال: ضوء النهار.\n\n* *\n\nوقوله: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾\n\nاختلف أهل التأويل في معنى قوله ﴿بَعْدَ ذَلكَ﴾ فقال بعضهم: دُحِيت الأرض من بعد خَلق السماء.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله حيث ذكر خلق الأرض قبل السماء، ثم ذكر السماء قبل الأرض، وذلك أن الله خَلق الأرض بأقواتها من غير أن يدحوها قبل السماء، ثم استوى إلى السماء فسوّاهنّ سبع سموات، ثم دحا الأرض بعد ذلك، فذلك قوله: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ .\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا وَالْجِبَالَ أَرْسَاهَا﴾ يعني: أن الله خلق السموات والأرض، فلما فرغ من السموات قبل أن يخلق أقوات الأرض فيها بعد خلق السماء، وأرسى الجبال، يعني بذلك دحْوَها الأقوات، ولم تكن تصلح أقوات الأرض ونباتها إلا بالليل والنهار، فذلك قوله: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ ألم تسمع أنه قال: ﴿أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن حفص، عن عكرمة، عن ابن عباس، قال: وضع البيت على الماء على أربعة أركان قبل أن يخلق الدنيا بألفي عام، ثم دُحيت الأرض من تحت البيت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن بكير بن الأخنس، عن مجاهد عن عبد الله بن عمرو، قال: خلق الله البيت قبل الأرض بألفي سنة، ومنه دُحيت الأرض.\n\nوقال آخرون: بل معنى ذلك: والأرض مع ذلك دحاها، وقالوا: الأرض خُلِقت ودُحِيت قبل السماء، وذلك أن الله قال: ﴿هُوَ الَّذِي خَلَقَ لَكُمْ مَا فِي الأرْضِ جَمِيعًا ثُمَّ اسْتَوَى إِلَى السَّمَاءِ فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ﴾ . قالوا: فأخبر الله أنه سوّى السماوات بعد أن خلق ما في الأرض جميعا، قالوا فإذا كان ذلك كذلك، فلا وجه لقوله: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ إلا ما ذكرنا من أنه مع ذلك دحاها قالوا: وذلك كقول الله عز وجلّ: ﴿عُتُلٍّ بَعْدَ ذَلِكَ زَنِيمٍ﴾ . بمعنى: مع ذلك زنيم، وكما يقال للرجل: أنت أحمق، وأنت بعد هذا لئيم الحسب، بمعنى: مع هذا، وكما قال جلّ ثناؤه: ﴿وَلَقَدْ كَتَبْنَا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ﴾ : أي من قبل الذكر، واستشهد بقول الهُذَليّ:\n\nحَمِدْتُ إلَهِي بَعْدَ عُرْوَةَ إذْ نَجَا ... خِراشٌ وبَعْضُ الشِّر أهْوَنُ مِنْ بَعْضِ\n\nوزعموا أن خراشا نجا قبل عروة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن خَصِيفٍ، عن مجاهد ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ قال: مع ذلك دحاها.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش، عن مجاهد، أنه قال: والأرْضَ عِنْدَ ذَلكَ دَحاها.\n\n⁕ حدثنا عبد الرحمن بن عبد الله بن عبد الحكم، قال: ثنا عليّ بن معبد، قال: ثنا محمد بن سلمة، عن خصيف، عن مجاهد ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ قال: مع ذلك دحاها.\n\n⁕ حدثني محمد بن خلف العسقلاني، قال: ثنا روّاد بن الجرّاح، عن أبي حمزة، عن السدي في قوله: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ قال: مع ذلك دحاها.\n\nوالقول الذي ذكرناه عن ابن عباس من أن الله تعالى خلق الأرض، وقدّر فيها أقواتها، ولم يدحها، ثم استوى إلى السماء، فسوّاهن سبع سموات، ثم دحا الأرض بعد ذلك، فأخرج منها ماءها ومرعاها، وأرسى جبالها، أشبه بما دلّ عليه ظاهر التنزيل، لأنه جلّ ثناؤه قال: ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ والمعروف من معنى \" بَعْدَ \" أنه خلاف معنى \" قَبْل \" وليس في دحوِّ الله الأرض بعد تسويته السماوات السبع، وإغطاشه ليلها، وإخراجه ضحاها، ما يوجب أن تكون الأرض خُلقت بعد خلق السموات لأن الدحوّ إنما هو البسط في كلام العرب، والمدّ يقال منه: دحا يدحو دَحْوا، ودَحيْتُ أدْحي دَحْيا، لغتان؛ ومنه قول أُميَّة بن أبي الصلت:\n\nدَارٌ دَحاها ثُمَّ أعْمَرَنا بِها ... وَأقامَ بالأخْرَى الَّتِي هي أمجدُ\n\nوقول أوس بن حجر في نعت غيث:\n\nيَنْفِي الحصَى عن جديد الأرْضِ مُبْتَرِكٌ ... كأنَّه فاحِصٌ أو لاعِبٌ داحِي\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالأرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴾ : أي بسطها.\n\n⁕ حدثني محمد بن خلف، قال: ثنا رَوّاد، عن أبي حمزة، عن السدي ﴿دَحَاها﴾ قال: بسطها.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان: ﴿دَحَاها﴾ بسطها.\n\nوقال ابن زيد في ذلك ما:-\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿دَحَاها﴾ قال: حرثها شقَّها وقال: ﴿أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا﴾ ، وقرأ: ﴿ثُمَّ شَقَقْنَا الأرْضَ شَقًّا ... ﴾ حتى بلغ ﴿وَفَاكِهَةً وَأَبًّا﴾ ، وقال حين شقَّها أنْبتَ هذا منها، وقرأ ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ .\n\n* *\n\nوقوله: ﴿أَخْرَجَ مِنْهَا مَاءَهَا﴾\n\nيقول: فجَّر فيها الأنهار ﴿وَمَرْعَاهَا﴾ يقول: أنبت نَباتها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَمَرْعَاهَا﴾ ما خلق الله فيها من النبات، ومَاءهَا ما فجر فيها من الأنهار.\n\n* *\n\nوقوله: ﴿وَالْجِبَالَ أَرْسَاهَا﴾\n\nيقول: والجبال أثبتها فيها، وفي الكلام متروك استغني بدلالة الكلام عليه من ذكره، وهو فيها، وذلك أن معنى الكلام: والجبال أرساها فيها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد عن قتادة ﴿وَالْجِبَالَ أَرْسَاهَا﴾ أي: أثبتها لا تَمِيد بأهلها حدثنا ابن حميد، قال: ثنا جرير، عن عطاء، عن أبي عبد الرحمن السلمي، عن علي قال: لما خلق الله الأرض قمصت وقالت: تخلق عليّ آدم وذرّيته يلقون عليّ نتْنهم، ويعملون عليّ بالخطايا، فأرساها الله، فمنها ما ترون، ومنها ما لا ترون، فكان أوَّل قرار الأرض كلحم الجزور إذا نُحِر يحتلج لحمها.","30":29,"31":29,"32":29,"33":"القول في تأويل قوله تعالى: ﴿مَتَاعًا لَكُمْ وَلأنْعَامِكُمْ (٣٣) فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى (٣٤) يَوْمَ يَتَذَكَّرُ الإنْسَانُ مَا سَعَى (٣٥) وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَى (٣٦) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: ﴿مَتَاعًا لَكُمْ وَلأنْعَامِكُمْ﴾ أنه خلق هذه الأشياء، وأخرج من الأرض ماءها ومرعاها منفعة لنا ومتاعا إلى حين.\n\n* *\n\nوقوله: ﴿فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى﴾\n\nيقول تعالى ذكره: فإذا جاءت التي تطم على كلّ هائلة من الأمور، فتغمر ما سواها بعظيم هولها، وقيل: إنها اسم من أسماء يوم القيامة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى﴾ من أسماء يوم القيامة عظمه الله، وحذّره عباده.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا سهل بن عامر، قال: ثنا مالك بن مغول، عن القاسم بن الوليد، في قوله: ﴿فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَى﴾ قال: سيق أهل الجنة إلى الجنة، وأهل النار إلى النار.\n\n* *\n\nوقوله: ﴿يَوْمَ يَتَذَكَّرُ الإنْسَانُ مَا سَعَى﴾\n\nيقول: إذا جاءت الطامة يوم يتذكر الإنسان ما عمل في الدنيا من خير وشر، وذلك سعيه ﴿وَبُرِّزَتِ الْجَحِيمُ﴾ يقول: وأظْهِرت الجحيم، وهي نار الله لمن يراها، يقول: لأبصار الناظرين.","34":33,"35":33,"36":33,"37":"القول في تأويل قوله تعالى: ﴿فَأَمَّا مَنْ طَغَى (٣٧) وَآثَرَ الْحَيَاةَ الدُّنْيَا (٣٨) فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى (٣٩) وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى (٤٠) فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى (٤١) ﴾\n\n.\n\nيقول تعالى ذكره: فأما من عتا على ربه، وعصاه واستكبر عن عبادته.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿طَغَى﴾ قال: عصى.\n\n* *\n\nقوله: ﴿وَآثَرَ الْحَيَاةَ الدُّنْيَا﴾\n\nيقول: وآثر متاع الحياة الدنيا على كرامة الآخرة، وما أعدّ الله فيها لأوليائه، فعمل للدنيا، وسعى لها، وترك العمل للآخرة ﴿فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَى﴾ يقول: فإن نار الله التي اسمها الجحيم، هي منزله ومأواه، ومصيره الذي يصير إليه يوم القيامة.\n\n* *\n\nوقوله: ﴿وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى﴾\n\nيقول: وأما من خاف مسألة الله إياه عند وقوفه يوم القيامة بين يديه، فاتقاه بأداء فرائضه، واجتناب معاصيه، ﴿وَنَهَى النَّفْسَ عَنِ الْهَوَى﴾ يقول: ونهى نفسه عن هواها فيما يكرهه الله، ولا يرضاه منها، فزجرها عن ذلك، وخالف هواها إلى ما أمره به ربه ﴿فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى﴾ يقول: فإن الجنة هي مأواه ومنزله يوم القيامة.\n\nوقد ذكرنا أقوال أهل التأويل في معنى قوله: ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ﴾ فيما مضى بما أغنى عن إعادته في هذا الموضع.\n\n* *\n\nالقول في تأويل قوله تعالى: ﴿يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا (٤٢) فِيمَ أَنْتَ مِنْ ذِكْرَاهَا (٤٣) إِلَى رَبِّكَ مُنْتَهَاهَا (٤٤) إِنَّمَا أَنْتَ مُنْذِرُ مَنْ يَخْشَاهَا (٤٥) كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلا عَشِيَّةً أَوْ ضُحَاهَا (٤٦) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: يسألك يا محمد هؤلاء المكذّبون بالبعث عن الساعة التي تبعث فيها الموتى من قبورهم ﴿أَيَّانَ مُرْسَاهَا﴾ ، متى قيامها وظهورها. وكان الفرّاء يقول: إن قال القائل: إنما الإرساء للسفينة، والجبال الراسية وما أشبههنّ، فكيف وصف الساعة بالإرساء؟ قلت: هي بمنزلة السفينة إذا كانت جارية فرست، ورسوّها: قيامها؛ قال: وليس قيامها كقيام القائم، إنما هي كقولك: قد قام العدل، وقام الحقّ: أي ظهر وثبت.\n\nقال أبو جعفر رحمه الله: يقول الله لنبيه: ﴿فِيمَ أَنْتَ مِنْ ذِكْرَاهَا﴾ يقول: في أيّ شيء أنت من ذكر الساعة والبحث عن شأنها. وذُكر أن رسول الله ﷺ كان يُكثر ذكر الساعة، حتى نزلت هذه الآية.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا سفيان بن عيينة، عن الزهريّ، عن عُروة، عن عائشة، قالت: لم يزل النبيّ ﷺ يسأل عن الساعة، حتى أنزل الله عزّ وجل: ﴿فِيمَ أَنْتَ مِنْ ذِكْرَاهَا إِلَى رَبِّكَ مُنْتَهَاهَا﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسماعيل، عن طارق بن شهاب، قال: كان النبيّ ﷺ لا يزال يذكر شأن الساعة حتى نزلت ﴿يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا ... ﴾ إلى ﴿مَنْ يخْشاهَا﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿فِيمَ أَنْتَ مِنْ ذِكْرَاهَا﴾ قال: الساعة.\n\n* *\n\nوقوله: ﴿إِلَى رَبِّكَ مُنْتَهَاهَا﴾\n\nيقول: إلى ربك منتهى علمها، أي إليه ينتهي علم الساعة، لا يعلم وقت قيامها غيره.\n\n* *\n\nوقوله: ﴿إِنَّمَا أَنْتَ مُنْذِرُ مَنْ يَخْشَاهَا﴾\n\nيقول تعالى ذكره لمحمد: إنما أنت رسول مبعوث بإنذار الساعة من يخاف عقاب الله فيها على إجرامه ولم تكلف علم وقت قيامها، يقول: فدع ما لم تكلف علمَه واعمل بما أمرت به من إنذار من أُمرت بإنذاره.\n\nواختلف القرّاء في قراءة قوله: ﴿مُنْذِرُ مَنْ يَخْشَاهَا﴾ فكان أبو جعفر القارئ وابن محيصن يقرأان ﴿مُنْذِرٌ﴾ بالتنوين، بمعنى: أنه منذر من يخشاها، وقرأ ذلك سائر قرّاء المدينة ومكة والكوفة والبصرة بإضافة ﴿مُنْذِرُ﴾ إلى ﴿من﴾ .\n\nوالصواب من القول في ذلك عندي: أنهم قراءتان معروفتان، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلا عَشِيَّةً أَوْ ضُحَاهَا﴾\n\nيقول جلّ ثناؤه: كأن هؤلاء المكذّبين بالساعة، يوم يرون أن الساعة قد قامت من عظيم هولها، لم يلبثوا في الدنيا إلا عشية يوم، أو ضحى تلك العشية، والعرب تقول: آتيك العشية أو غَدَاتَها، وآتيك الغداةَ أو عشيتها، فيجعلون معنى الغداة بمعنى أوّل النهار، والعشية: آخر النهار فكذلك قوله: ﴿إِلا عَشِيَّةً أَوْ ضُحَاهَا﴾ إنما معناه إلا آخر يوم أو أوّله، وينشد هذا البيت:\n\nنَحْنُ صَبَحْنا عامِرًا فِي دَارِها ... عَشِيَّةَ الهِلالِ أوْ سِرَارِها\n\nيعني: عشية الهلال، أو عشية سرار العشية.\n\n⁕ حدثنا بشر، قال: ثنا يزيد قال: ثنا سعيد عن قتادة، قوله: ﴿كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلا عَشِيَّةً أَوْ ضُحَاهَا﴾ وقت الدنيا في أعين القوم حين عاينوا الآخرة.\n\nآخر تفسير سورة النازعات.","38":37,"39":37,"40":37,"41":37,"42":37,"43":37,"44":37,"45":37,"46":37},"80":{"1":"القول في تأويل قوله تعالى: ﴿عَبَسَ وَتَوَلَّى (١) أَنْ جَاءَهُ الأعْمَى (٢) وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى (٣) أَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرَى (٤) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: ﴿عَبَسَ﴾ قبض وجهه تكرّها، ﴿وَتَوَلى﴾ يقول: وأعرض ﴿أَنْ جَاءَهُ الأعْمَى﴾ يقول: لأن جاءه الأعمى. وقد ذُكر عن بعض القرّاء أنه كان يطوّل الألف ويمدها من ﴿أنْ جاءَهُ﴾ فيقول: ﴿آنْ جاءَهُ﴾ ، وكأنّ معنى الكلام كان عنده: أأن جاءه الأعمى؟ عبس وتولى، كما قرأ من قرأ: ﴿آنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾ بمدّ الألف من \"أن\" وقصرها.\n\nوذُكر أن الأعمى الذي ذكره الله في هذه الآية، هو ابن أمّ مكتوم، عوتب النبيّ ﷺ بسببه.\n\nذكر الأخبار الواردة بذلك\n\n⁕ حدثنا سعيد بن يحيى الأموي، قال: ثنا أبي، عن هشام بن عروة مما عرضه عليه عروة، عن عائشة قالت: أنزلت ﴿عَبَسَ وَتَوَلَّى﴾ في ابن أمّ مكتوم قالت: أتى إلى رسول الله ﷺ فجعل يقول: أرشدني، قالت: وعند رسول الله ﷺ من عظماء المشركين، قالت: فجعل النبيّ ﷺ يُعْرِض عنه، ويُقْبِل على الآخر ويقول: \"أتَرَى بِما أقُولُهُ بأسًا؟ فيقول: لا ففي هذا أُنزلت: ﴿عَبَسَ وَتَوَلَّى﴾ .\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس قوله: ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى﴾ قال: \" بينا رسول الله ﷺ يناجي عُتبة بن ربيعة وأبا جهل بن هشام والعباس بن عبد المطلب، وكان يتصدّى لهم كثيرا، ويَعرض عليهم أن يؤمنوا، فأقبل إليه رجل أعمى يقال له عبد الله بن أمّ مكتوم، يمشي وهو يناجيهم، فجعل عبد الله يستقرئ النبيّ ﷺ آية من القرآن، وقال: يا رسول الله، علمني مما علَّمك الله، فأعرض عنه رسول الله ﷺ، وعبس في وجهه وتوّلى، وكره كلامه، وأقبل على الآخرين؛ فلما قضى رسول الله ﷺ، وأخذ ينقلب إلى أهله، أمسك الله بعض بصره، ثم خَفَق برأسه، ثم أنزل الله: ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى أَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرَى﴾ ، فلما نزل فيه أكرمه رسول الله ﷺ وكلَّمه، وقال له: \"ما حاجَتُك، هَلْ تُرِيدُ مِنْ شَيءٍ؟ \" وإذا ذهب من عنده قال له: \"هَلْ لكَ حاجَةٌ فِي شَيْء؟ \" وذلك لما أنزل الله: ﴿أَمَّا مَنِ اسْتَغْنَى فَأَنْتَ لَهُ تَصَدَّى وَمَا عَلَيْكَ أَلا يَزَّكَّى﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن هشام، عن أبيه، قال: نزلت في ابن أمّ مكتوم ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿أَنْ جَاءَهُ الأعْمَى﴾ قال: رجل من بني فهر، يقال له: ابن أمّ مكتوم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى﴾ عبد الله بن زائدة، وهو ابن أمّ مكتوم، وجاءه يستقرئه، وهو يناجي أُميَّة بن خلف، رجل من عِلْية قريش، فأعرض عنه نبيّ الله ﷺ، فأنزل الله فيه ما تسمعون: ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى﴾ إلى قوله: ﴿فَأَنْتَ عَنْهُ تَلَهَّى﴾ ذُكر لنا أن نبيّ الله ﷺ استخلفه بعد ذلك مرّتين على المدينة في غزوتين غزاهما يصلي بأهلها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن أنس بن مالك، أنه رآه يوم القادسية معه راية سوداء، وعليه درع له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة قال: جاء ابن أمّ مكتوم إلى النبيّ ﷺ وهو يكلم أبيَّ بن خَلَف، فأعرض عنه، فأنزل الله عليه: ﴿عَبَسَ وَتَوَلَّى﴾ فكان النبيّ ﷺ بعد ذلك يُكرمه قال أنس: فرأيته يوم القادسية عليه درع، ومعه راية سوداء.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿عَبَسَ وَتَوَلَّى﴾ تصدّى رسول الله ﷺ لرجل من مشركي قريش كثير المال، ورجا أن يؤمن، وجاء رجل من الأنصار أعمى يقال له: عبد الله بن أمّ مكتوم، فجعل يسأل نبيّ الله ﷺ فكرهه نبيّ الله ﷺ وتولى عنه، وأقبل على الغنيّ، فوعظ الله نبيه، فأكرمه نبيّ الله ﷺ، واستخلفه على المدينة مرّتين في غزوتين غزاهما.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، وسألته عن قول الله عزّ وجلّ: ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى﴾ قال: جاء ابن أمّ مكتوم إلى رسول الله ﷺ وقائده يبصر، وهو لا يبصر، قال: ورسول الله ﷺ يشير إلى قائده يكفّ، وابن أمّ مكتوم يدفعه ولا يُبصر؛ قال: حتى عبس رسول الله ﷺ، فعاتبه الله في ذلك، فقال: ﴿عَبَسَ وَتَوَلَّى أَنْ جَاءَهُ الأعْمَى وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى ... ﴾ إلى قوله: ﴿فَأَنْتَ عَنْهُ تَلَهَّى﴾ قال ابن زيد: كان يقال: لو أن رسول الله ﷺ كَتَمَ من الوحي شيئا، كتم هذا عن نفسه، قال: وكان يتصدّى لهذا الشريف في جاهليته رجاء أن يسلم، وكان عن هذا يتلَّهى.\n\n* *\n\nوقوله: ﴿وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: وما يدريك يا محمد لعلّ هذا الأعمى الذي عَبَست في وجهه يَزَّكَّى: يقول: يتطهَّر من ذنوبه.\n\nوكان ابن زيد يقول في ذلك ما:-\n\n⁕ حدثني يونس قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿لَعَلَّهُ يَزَّكَّى﴾ يسلم.\n\n* *\n\nوقوله: ﴿أَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرَى﴾\n\nيقول: أو يتذكَّر فتنفعه الذكرى: يعني: يعتبر فينفعه الاعتبار والاتعاظ، والقراءة على رفع: ﴿فتَنْفَعهُ﴾ عطفا به على قوله: ﴿يَذَّكَّرُ﴾ ، وقد رُوي عن عاصم النصب فيه والرفع، والنصب على أن تجعله جوابا بالفاء للعلّ، كما قال الشاعر:\n\nعَلَّ صُرُوفَ الدَّهْرِ أوْ دُوْلاتِها ... يُدِلْنَنا اللَّمَّةَ مِنْ لمَّاتِها\n\nفَتَسْتَرِيحُ النَّفْسُ مِنْ زَفْراتها ... وتُنْقَعُ الغُلَّةُ مِن غُلاتِها\n\n\"وتنقع\" يُروى بالرفع والنصب.","2":1,"3":1,"4":1,"5":"القول في تأويل قوله تعالى: ﴿أَمَّا مَنِ اسْتَغْنَى (٥) فَأَنْتَ لَهُ تَصَدَّى (٦) وَمَا عَلَيْكَ أَلا يَزَّكَّى (٧) وَأَمَّا مَنْ جَاءَكَ يَسْعَى (٨) وَهُوَ يَخْشَى (٩) فَأَنْتَ عَنْهُ تَلَهَّى (١٠) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: أما من استغنى بماله فأنت له تتعرّض رجاء أن يُسلِم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿أَمَّا مَنِ اسْتَغْنَى فَأَنْتَ لَهُ تَصَدَّى﴾ قال: نزلت في العباس.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، ثنا الحسن قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿أَمَّا مَنِ اسْتَغْنَى﴾ قال عتبة بن ربيعة، وشيبة بن ربيعة ﴿وَمَا عَلَيْكَ أَلا يَزَّكَّى﴾ يقول: وأي شيء عليك أن لا يتطهَّر من كفره فيُسلم؟ ﴿وَأَمَّا مَنْ جَاءَكَ يَسْعَى وَهُوَ يَخْشَى﴾ يقول: وأما هذا الأعمى الذي جاءك سعيا، وهو يخشى الله ويتقيه ﴿فَأَنْتَ عَنْهُ تَلَهَّى﴾ يقول: فأنت عنه تعرض، وتشاغل عنه بغيره وتغافل.\n\n* *\n\nالقول في تأويل قوله تعالى: ﴿كَلا إِنَّهَا تَذْكِرَةٌ (١١) فَمَنْ شَاءَ ذَكَرَهُ (١٢) فِي صُحُفٍ مُكَرَّمَةٍ (١٣) مَرْفُوعَةٍ مُطَهَّرَةٍ (١٤) بِأَيْدِي سَفَرَةٍ (١٥) كِرَامٍ بَرَرَةٍ (١٦) قُتِلَ الإنْسَانُ مَا أَكْفَرَهُ (١٧) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿كَلا﴾ ما الأمر كما تفعل يا محمد من أن تعبس في وجه من جاءك يسعى وهو يخشى، وتتصدّى لمن استغنى ﴿إنَّها تَذْكِرَة﴾ يقول: إن هذه العظة وهذه السورة تذكرة: يقول: عظة وعبرة ﴿فَمَنْ شَاءَ ذَكَرَهُ﴾ يقول: فمن شاء من عباد الله ذكره، يقول: ذكر تنزيل الله ووحيه والهاء في قوله: \"إنَّها\" للسورة، وفي قوله: \"ذَكَرَهُ\" للتنزيل والوحي. ﴿فِي صُحُفِ﴾ يقول: إنها تذكرة ﴿فِي صُحُفٍ مُكَرَّمَةٍ مَرْفُوعَةٍ مُطَهَّرَةٍ﴾ يعني: في اللوح المحفوظ، وهو المرفوع المطهر عند الله.\n\n* *\n\nوقوله: ﴿بِأَيْدِي سَفَرَةٍ﴾\n\nيقول: الصحف المكرّمة بأيدي سفرة، جمع سافر.\n\nواختلف أهل التأويل فيهم ما هم؟ فقال بعضهم: هم كَتَبة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿بِأَيْدِي سَفَرَةٍ﴾ يقول: كَتَبة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿بِأَيْدِي سَفَرَةٍ﴾ قال: الكَتَبة.\n\nوقال آخرون: هم القرّاء.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَمَنْ شَاءَ ذَكَرَهُ فِي صُحُفٍ مُكَرَّمَةٍ مَرْفُوعَةٍ مُطَهَّرَةٍ بِأَيْدِي سَفَرَةٍ﴾ قال: هم القرّاء.\n\nوقال آخرون: هم الملائكة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿بِأَيْدِي سَفَرَةٍ كِرَامٍ بَرَرَةٍ﴾ يعني: الملائكة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿بِأَيْدِي سَفَرَةٍ كِرَامٍ بَرَرَةٍ﴾ قال: السَّفَرة: الذين يُحْصون الأعمال.\n\nوأولى الأقوال في ذلك بالصواب قول من قال: هم الملائكة الذين يَسْفِرون بين الله ورسله بالوحي.\n\nوسفير القوم: الذي يسعى بينهم بالصلح، يقال: سفرت بين القوم: إذا أصلحت بينهم، ومنه قول الشاعر:\n\nومَا أدَعُ السِّفارَةَ بَين قَوْمي ... ومَا أمْشِي بغِشّ إنْ مَشِيتُ\n\nوإذا وُجِّه التأويل إلى ما قلنا، احتمل الوجه الذي قاله القائلون: هم الكَتَبة، والذي قاله القائلون: هم القرّاء لأن الملائكة هي التي تقرأ الكتب، وتَسْفِر بين الله وبين رسله.\n\n* *\n\nوقوله: ﴿كِرَامٍ بَرَرَةٍ﴾\n\nوالبَررَة: جمع بارّ، كما الكفرة جمع كافر، والسحرة جمع ساحر، غير أن المعروف من كلام العرب إذا نطقوا بواحدة أن يقولوا: رجل بر، وامرأة برّة، وإذا جمعوا ردّوه إلى جمع فاعل، كما قالوا: رجل سري، ثم قالوا في جمعه: قوم سراة وكان القياس في واحده أن يكون ساريا، وقد حُكي سماعا من بعض العرب: قوم خِيَرَة بَرَرَة، وواحد الخيرة: خير، والبَررَة: برّ.\n\n* *\n\nوقوله: ﴿قُتِلَ الإنْسَانُ مَا أَكْفَرَهُ﴾\n\nيقول تعالى ذكره: لعن الإنسان الكافر ما أكفره.\n\nوبنحو الذي قلنا في ذلك قال مجاهد.\n\n⁕ حدثني موسى بن عبد الرحمن المسروقي، قال: ثنا عبد الحميد الحِماني، عن الأعمش، عن مجاهد قال: ما كان في القرآن قُتِلَ الإنسانُ أو فُعل بالإنسان، فإنما عنِي به: الكافر.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿قُتِلَ الإنْسَانُ مَا أَكْفَرَهُ﴾ بلغني أنه: الكافر.\n\nوفي قوله: ﴿أكْفَرَهُ﴾ وجهان: أحدهما: التعجب من كفره مع إحسان الله إليه، وأياديه عنده. والآخر: ما الذي أكفره، أي: أيّ شيء أكفره.","6":5,"7":5,"8":5,"9":5,"10":5,"11":5,"12":5,"13":5,"14":5,"15":5,"16":5,"17":5,"18":"القول في تأويل قوله تعالى: ﴿مِنْ أَيِّ شَيْءٍ خَلَقَهُ (١٨) مِنْ نُطْفَةٍ خَلَقَهُ فَقَدَّرَهُ (١٩) ثُمَّ السَّبِيلَ يَسَّرَهُ (٢٠) ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ (٢١) ثُمَّ إِذَا شَاءَ أَنْشَرَهُ (٢٢) كَلا لَمَّا يَقْضِ مَا أَمَرَهُ (٢٣) ﴾\n\n.\n\nيقول تعالى ذكره: من أي شيء خلق الإنسان الكافر ربه حتي يتكبر ويتعظم عن طاعة ربه، والإقرار بتوحيده. ثم بين جلّ ثناؤه الذي منه خلقه، فقال: ﴿مِنْ نُطْفَةٍ خَلَقَهُ فَقَدَّرَهُ﴾ أحوالا نطفة تارة، ثم عَلَقة أخرى، ثم مُضغة، إلى أن أتت عليه أحواله وهو في رحم أمه. ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ يقول: ثم يسَّره للسبيل، يعني للطريق.\n\nواختلف أهل التأويل في السبيل الذي يسَّره لها، فقال بعضهم: هو خروجه من بطن أمه.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ يعني بذلك: خروجه من بطن أمه يسَّره له.\n\n⁕ حدثني ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل، عن أبي صالح ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: سبيل الرحم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: أخرجه من بطن أمه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: خروجه من بطن أمه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: أخرجه من بطن أمه.\n\nوقال آخرون: بل معنى ذلك: طريق الحق والباطل، بيَّناه له وأعلمناه، وسهلنا له العمل به.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: هو كقوله: ﴿إِنَّا هَدَيْنَاهُ السَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: على نحو ﴿إِنَّا هَدَيْنَاهُ السَّبِيلَ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، قال: سبيل الشقاء والسعادة، وهو كقوله: ﴿إِنَّا هَدَيْنَاهُ السَّبِيلَ﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة قال: قال الحسن، في قوله: ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: سبيل الخير.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿ثُمَّ السَّبِيلَ يَسَّرَهُ﴾ قال: هداه للإسلام الذي يسَّره له، وأعلمه به، والسبيل سبيل الإسلام.\n\nوأولى التأويلين في ذلك عندي بالصواب قول من قال: ثم الطريق، وهو الخروج من بطن أمه يسَّره.\n\nوإنما قلنا ذلك أولى التأويلين بالصواب، لأنه أشبههما بظاهر الآية، وذلك أن الخبر من الله قبلها وبعدها عن صفته خلقه وتدبيره جسمه، وتصريفه إياه في الأحوال، فالأولى أن يكون أوسط ذلك نظير ما قبله وما بعده.\n\n* *\n\nوقوله: ﴿ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ﴾\n\nيقول: ثم قَبَضَ رُوحه، فأماته بعد ذلك. يعني بقوله: ﴿أَقْبَرَهُ﴾ صيره ذا قبر، والقابر: هو الدافن الميت بيده، كما قال الأعشى:\n\nلَوْ أسْنَدَتْ مَيْتا إلى نَحْرِها ... عاشَ وَلمْ يُنْقَلْ إلى قابِرِ\n\nوالمقبر: هو الله، الذي أمر عباده أن يقبروه بعد وفاته، فصيره ذا قبر. والعرب تقول فيما ذُكر لي: بترت ذنَب البعير، والله أبتره، وعضبت قَرنَ الثور، والله أعضبه؛ وطردت عني فلانا، والله أطرده، صيره طريدا.\n\n* *\n\nوقوله: ﴿ثُمَّ إِذَا شَاءَ أَنْشَرَهُ﴾\n\nيقول: ثم إذا شاء الله أنشره بعد مماته وأحياه، يقال: أنشر الله الميت بمعنى: أحياه، ونشر الميت بمعنى حيى هو بنفسه، ومنه قول الأعشى:\n\nحتى يَقُولَ النَّاسُ مِمَّا رأوْا ... يا عَجَبا لِلْمَيِّتِ النَّاشرِ\n\n* *\n\nوقوله: ﴿كَلا لَمَّا يَقْضِ مَا أَمَرَهُ﴾\n\nيقول تعالى ذكره: كلا ليس الأمر كما يقول هذا الإنسان الكافر من أنه قد أدّى حقّ الله عليه، في نفسه وماله، ﴿لَمَّا يَقْضِ مَا أَمَرَهُ﴾ لم يؤدّ ما فرض عليه من الفرائض ربُّه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿لَمَّا يَقْضِ مَا أَمَرَهُ﴾ قال: لا يقضي أحد أبدًا ما افتُرِض عليه. وقال الحارث: كلّ ما افترض عليه.","19":18,"20":18,"21":18,"22":18,"23":18,"24":"القول في تأويل قوله تعالى: ﴿فَلْيَنْظُرِ الإنْسَانُ إِلَى طَعَامِهِ (٢٤) أَنَّا صَبَبْنَا الْمَاءَ صَبًّا (٢٥) ثُمَّ شَقَقْنَا الأرْضَ شَقًّا (٢٦) فَأَنْبَتْنَا فِيهَا حَبًّا (٢٧) وَعِنَبًا وَقَضْبًا (٢٨) وَزَيْتُونًا وَنَخْلا (٢٩) وَحَدَائِقَ غُلْبًا (٣٠) ﴾\n\n.\n\nيقول تعالى ذكره: فلينظر هذا الإنسان الكافر المُنكر توحيد الله إلى طعامه كيف دبَّره.\n\nكما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿فَلْيَنْظُرِ الإنْسَانُ إِلَى طَعَامِهِ﴾ وشرابه، قال: إلى مأكله ومشربه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿فَلْيَنْظُرِ الإنْسَانُ إِلَى طَعَامِهِ﴾ آية لهم.\n\nواختلفت القرّاء في قراءة قوله: ﴿أَنَّا صَبَبْنَا الْمَاءَ صَبًّا﴾ فقرأته عامة قرّاء المدينة والبصرة بكسر الألف من \"أنَّا\"، على وجه الاستئناف، وقرأ ذلك عامة قرّاء الكوفة \"أنَّا\" بفتح الألف، بمعنى: فلينظر الإنسان إلى أنا، فيجعل \"أنَّا\" في موضع خفض على نية تكرير الخافض، وقد يجوز أن يكون رفعا إذا فُتحت، بنية طعامه، ﴿أَنَّا صَبَبْنَا الْمَاءَ صَبًّا﴾ .\n\nوالصواب من القول في ذلك عندي أنهما قراءتان معروفتان: فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿أَنَّا صَبَبْنَا الْمَاءَ صَبًّا﴾\n\nيقول: أنا أنزلنا الغيث من السماء إنزالا وصببناه عليها صبا ﴿ثُمَّ شَقَقْنَا الأرْضَ شَقًّا﴾ يقول: ثم فتقنا الأرض فصدّعناها بالنبات ﴿فَأَنْبَتْنَا فِيهَا حَبًّا﴾ يعني: حبّ الزرع، وهو كلّ ما أخرجته الأرض من الحبوب كالحنطة والشعير، وغير ذلك ﴿وَعِنَبًا﴾ يقول: وكرم عنب ﴿وَقَضْبَا﴾ يعني بالقضب: الرطبة، وأهل مكة يسمون القَتَّ القَضْب.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَقَضْبا﴾ يقول: الفِصفِصة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَقَضْبا﴾ قال: والقضب: الفصافص.\n\nقال أبو جعفر رحمه الله: الفِصفصة: الرَّطبة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وقَضْبا﴾ يعني: الرطبة.\n\n⁕ حدثنا بشر، قال: ثنا عبد الواحد بن زياد، قال: ثنا يونس، عن الحسن، في قوله: ﴿وَقَضْبا﴾ قال: القضب: العَلَف.\n\n* *\n\nوقوله: ﴿وَزَيْتُونًا﴾\n\nوهو الزيتون الذي منه الزيت ﴿وَنَخْلا وَحَدَائِقَ غُلْبًا﴾ وقد بينَّا أن الحديقة البستان المحوّط عليه.\n\n* *\n\nوقوله: ﴿غُلْبا﴾\n\nيعني: غلاظا. ويعني بقوله: ﴿غُلْبا﴾ أشجارا في بساتين غلاظ.\n\nوالغلب: جمع أغلب، وهو الغليظ الرقبة من الرجال؛ ومنه قول الفرزدق:\n\nعَوَى فأثارَ أغْلَبَ ضَيْغَميًّا ... فَوَيْل ابْنِ المَراغَةِ ما اسْتثارَا؟\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في البيان عنه، فقال بعضهم: هو ما التفّ من الشجر واجتمع.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن إدريس، عن عاصم بن كُلَيب، عن أبيه، عن ابن عباس، في قوله: ﴿وَحَدَائِقَ غُلْبًا﴾ قال: الحدائق: ما التفّ واجتمع.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَحَدَائِقَ غُلْبًا﴾ قال: طيبة.\n\nوقال آخرون: الحدائق: نبت الشجر كله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو هشام، قال: ثنا ابن فضيل، قال: ثنا عصام، عن أبيه: الحدائق: نبت الشجر كلها.\n\n⁕ حدثني محمد بن سنان القزّاز، قال: ثنا أبو عاصم، عن شبيب، عن عكرمة، عن ابن عباس: ﴿وَحَدَائِقَ غُلْبًا﴾ قال: الشجر يستظلّ به في الجنة.\n\nوقال آخرون: بل الغُلب: الطوال.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿وَحَدَائِقَ غُلْبًا﴾ يقول: طوالا.\n\nوقال آخرون: هو النخل الكرام.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، في قوله: ﴿وَحَدَائِقَ غُلْبًا﴾ والغلب: النخل الكرام.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَحَدَائِقَ غُلْبًا﴾ قال: النخل الكرام.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَحَدَائِقَ غُلْبًا﴾ عظام النخل العظيمة الجذع، قال: والغلب من الرجال: العظام الرقاب، يقال: هو أغلب الرقبة: عظيمها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن عكرمة ﴿حَدَائِقَ غُلْبًا﴾ قال: عظام الأوساط.","25":24,"26":24,"27":24,"28":24,"29":24,"30":24,"31":"القول في تأويل قوله تعالى: ﴿وَفَاكِهَةً وَأَبًّا (٣١) مَتَاعًا لَكُمْ وَلأنْعَامِكُمْ (٣٢) فَإِذَا جَاءَتِ الصَّاخَّةُ (٣٣) يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ (٣٤) وَأُمِّهِ وَأَبِيهِ (٣٥) وَصَاحِبَتِهِ وَبَنِيهِ (٣٦) لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ (٣٧) وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌ (٣٨) ضَاحِكَةٌ مُسْتَبْشِرَةٌ (٣٩) وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ (٤٠) تَرْهَقُهَا قَتَرَةٌ (٤١) أُولَئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ (٤٢) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿وَفاكِهَةً﴾ ما يأكله الناس من ثمار الأشجار، والأبّ: ما تأكله البهائم من العشب والنبات.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مبارك، عن الحسن ﴿وَفاكِهَةً﴾ قال: ما يأكل ابن آدم.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَفاكِهَةً﴾ قال: ما أكل الناس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَفاكِهَةً﴾ قال: أما الفاكهة فلكم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَفاكِهَةً﴾ قال: الفاكهة لنا.\n\n⁕ حدثنا حميد بن مسعدة، قال: ثنا بشر بن المفضل، قال: ثنا حميد، قال أنس بن مالك: قرأ عمر ﴿عَبَسَ وَتَوَلَّى﴾ حتى أتى على هذه الآية ﴿وَفَاكِهَةً وَأَبًّا﴾ قال: قد علمنا ما الفاكهة، فما الأبّ؟ ثم أحسبه \" شك الطبري \" قال: إن هذا لهو التكلف.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، عن حميد، عن أنس، قال: قرأ عمر بن الخطاب رضى الله عنه ﴿عَبَسَ وَتَوَلَّى﴾ فلما أتى على هذه الآية ﴿وَفَاكِهَةً وَأَبًّا﴾ قال: قد عرفنا الفاكهة. فما الأبّ؟ قال: لعمرك يا بن الخطاب إن هذا لهو التكلف.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن موسى بن أنس، عن أنس، قال: قرأ عمر: ﴿وَفَاكِهَةً وَأَبًّا﴾ ومعه عصا في يده، فقال: ما الأبّ، ثم قال: بحسبنا ما قد علمنا، وألقى العصا من يده.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن خليد بن جعفر، عن أبي إياس معاوية بن قرة، عن أنس، عن عمر رضي الله عنه أنه قال: إن هذا هو التكلف.\n\nقال: وحدثني قتادة، عن أنس، عن عمر بنحو هذا الحديث كله.\n\n⁕ حدثنا أبو كُرَيب وأبو السائب ويعقوب قالوا: ثنا ابن إدريس، قال: سمعت عاصم بن كليب، عن أبيه، عن ابن عباس، قال: عدّ سبعا جعل رزقه في سبعة، وجعله من سبعة، وقال في آخر ذلك: الأبّ: ما أنبتت الأرض مما لا يأكل الناس.\n\n⁕ حدثنا أبو هشام، قال: ثنا ابن فضيل، قال: ثنا عاصم، عن أبيه، عن ابن عباس، قال: الأبّ: نبت الأرض مما تأكله الدوابّ، ولا يأكله الناس.\n\n⁕ حدثنا أبو كُرَيب وأبو السائب، قالا ثنا ابن إدريس، قال: ثنا عبد الملك، عن سعيد بن جبير، قال: عدّ ابن عباس، وقال: الأبّ: ما أنبتت الأرض للأنعام، وهذا لفظ حديث أبي كريب. وقال أبو السائب في حديثه: قال: ما أنبتت الأرض مما يأكل الناس وتأكل الأنعام.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قال: الأبّ: الكلأ والمرعى كله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن أبي رَزين، قال: الأبّ النبات.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن أبي رَزين، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش أو غيره، عن مجاهد، قال: الأبّ: المرعى.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: قال مجاهد: ﴿وأبًّا﴾ المرعى.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مبارك، عن الحسن ﴿وأبًّا﴾ قال: الأبّ: ما تأكل الأنعام.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد قوله ﴿وأبًّا﴾ قال: الأبّ: ما أكلت الأنعام.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة: أما الأبّ: فلأنعامكم نعم من الله متظاهرة.\n\n⁕ حدثنا ابن بشر، قال: ثنا عبد الواحد، قال: ثنا يونس، عن الحسن، في قوله: ﴿وأبًّا﴾ قال: الأبّ: العشب.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، وقتادة، في قوله ﴿وأبًّا﴾ قال: هو ما تأكله الدوابّ.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله ﴿وأبًّا﴾ يعني: المرعى.\n\n⁕ حدثنا يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله ﴿وأبًّا﴾ قال: الأبّ لأنعامنا، قال: والأبّ: ما ترعى. وقرأ: ﴿مَتَاعًا لَكُمْ وَلأنْعَامِكُمْ﴾ .\n\nقال: أخبرنا ابن وهب، قال: أخبرني يونس وعمرو بن الحارث، عن ابن شهاب أن أنس بن مالك حدثه أنه سمع عمر بن الخطاب رضى الله عنه يقول: قال الله: ﴿وَقَضْبًا وَزَيْتُونًا وَنَخْلا وَحَدَائِقَ غُلْبًا وَفَاكِهَةً وَأَبًّا﴾ كلّ هذا قد علمناه، فما الأبّ؟ ثم ضرب بيده، ثم قال: لعمرك إن هذا لهو التكلف، واتبعوا ما يتبين لكم في هذا الكتاب، قال عمر: وما يتبين فعليكم به، وما لا فدعوه.\n\nوقال آخرون: الأبّ: الثمار الرطبة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله ﴿وأبًّا﴾ يقول: الثمار الرطبة.\n\n* *\n\nوقوله: ﴿مَتاعا لَكُمْ﴾\n\nيقول: أنبتنا هذه الأشياء التي يأكلها بنو آدم متاعا لكم أيها الناس، ومنفعة تتمتعون بها، وتنتفعون، والتي يأكلها الأنعام لأنعامكم، وأصل الأنعام الإبل، ثم تستعمل في كلّ راعية.\n\nوبالذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن الحسن، في قوله: ﴿مَتَاعًا لَكُمْ وَلأنْعَامِكُمْ﴾ قال: متاعا لكم الفاكهة، ولأنعامكم العشب.\n\n* *\n\nوقوله: ﴿فَإِذَا جَاءَتِ الصَّاخَّةُ﴾\n\nذُكر أنها اسم من أسماء القيامة، وأحسبها مأخوذة من قولهم: صاخ فلان لصوت فلان: إذا استمع له، إلا أن هذا يقال منه: هو مُصِيخ له، ولعلّ الصوت هو الصاخّ، فإن يكن ذلك كذلك، فينبغي أن يكون قبل ذلك لنفخة الصور.\n\nذكر من قال: هو اسم من أسماء القيامة\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿فَإِذَا جَاءَتِ الصَّاخَّةُ﴾ قال: هذا من أسماء يوم القيامة عظَّمه الله، وحذّره عباده.\n\n* *\n\nوقوله: ﴿يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ﴾\n\nيقول: فإذا جاءت الصاخة في هذا اليوم الذي يفرّ فيه المرء من أخيه. ويعني بقوله: يفرّ من أخيه: يفرّ عن أخيه ﴿وَأُمِّهِ وَأَبِيهِ وَصَاحِبَتِهِ﴾ يعني: زوجته التي كانت زوجته في الدنيا ﴿وَبَنِيهِ﴾ حذرا من مطالبتهم إياه بما بينه وبينهم من التَّبعات والمظالم.\n\nوقال بعضهم: معنى قوله: ﴿يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ﴾ يفرّ عن أخيه لئلا يراه، وما ينزل به، ﴿لكل امرئ﴾ يعني: من الرجل وأخيه وأمه وأبيه، وسائر من ذُكر في هذه الآية ﴿يَوْمَئِذٍ﴾ يعني: يوم القيامة إذا جاءت الصاخَّة يوم القيامة ﴿شَأْنٌ يُغْنِيهِ﴾ يقول: أمر يغنيه، ويُشغِله عن شأن غيره.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ﴾ أفضى إلى كلّ إنسان ما يشغله عن الناس.\n\n⁕ حدثنا أبو عمارة المَرْوَزيّ الحسين بن حُريث، قال: ثنا الفضل بن موسى، عن عائذ بن شريح، عن أنس قال: سألتْ عائشة رسول الله ﷺ قالت: يا رسول الله بأبي أنت وأمي، إني سائلتك عن حديث أخبرني أنت به، قال:\" إن كانَ عِنْدي مِنْهُ عِلْمٌ\" قالت: يا نبيّ الله كيف يُحْشر الرجال؟ قال: \" حفاةً عُرَاةً \"، ثم انتظرت ساعة فقالت: يا نبيّ الله كيف يُحْشر النساء؟ قال: \" كَذلك حُفاةً عُرَاةً \"، قالت: واسوأتاه من يوم القيامة، قال: \" وعَنْ ذلك تَسألِيني؟ إنَّهُ قَدْ نزلَتْ عليّ آيَة لا يَضُرُّكِ كانَ عَلَيْكِ ثيابٌ أمْ لا \"، قالت: أيّ آية هي يا نبيّ الله؟ قال: ﴿لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ﴾ .\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب قال: قال ابن زيد في قول الله: ﴿لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ﴾ قال: شأن قد شغله عن صاحبه.\n\n* *\n\nوقوله: ﴿وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌ﴾\n\nيقول تعالى ذكره: وجوه يومئذ مشرقة مضيئة، وهي وجوه المؤمنين الذين قد رضى الله عنهم، يقال: أسفر وجه فلان: إذا حَسُن، ومنه أسفر الصبح: إذا أضاء، وكلّ مضيء فهو مسفر، وأما سَفَر بغير ألف، فإنما يقال للمرأة إذا ألقت نقابها عن وجهها أو برقعها، يقال: قد سَفَرت المرأة عن وجهها إذا فعلت ذلك فهي سافر؛ ومنه قول تَوْبَة بن الحُمَيِّر:\n\nوكُنْتُ إذا ما زُرْتُ لَيْلَى تَبرْقَعَتْ ... فَقَدْ رَابَنِي مِنْها الغَدَاةَ سُفُورُها\n\nيعني بقوله: \" سفورها \" إلقاءها برقعها عن وجهها.\n\n﴿ضَاحِكَةٌ﴾ يقول: ضاحكة من السرور بما أعطاها الله من النعيم والكرامة ﴿مُسْتَبْشِرَةٌ﴾ لما ترجو من الزيادة.\n\nوبنحو الذي قلنا في معنى قوله: ﴿مُسْفِرَةٌ﴾ قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله ﴿مُسْفِرَةٌ﴾ يقول: مشرقة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وُجُوهٌ يَوْمَئِذٍ مُسْفِرَةٌ ضَاحِكَةٌ مُسْتَبْشِرَةٌ﴾ قال: هؤلاء أهل الجنة.\n\n* *\n\nوقوله: ﴿وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ﴾\n\nيقول تعالى ذكره: ﴿وَوُجُوهٌ﴾ وهي وجوه الكفار يومئذ عليها غبرة. ذُكر أن البهائم التي يصيرها الله ترابا يومئذ بعد القضاء بينها، يحوّل ذلك التراب غَبَرة في وجوه أهل الكفر ﴿تَرْهَقُهَا قَتَرَةٌ﴾ يقول: يغشى تلك الوجوه قَتَرة، وهي الغَبَرة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿تَرْهَقُهَا قَتَرَةٌ﴾ يقول: تغشاها ذلة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿تَرْهَقُهَا قَتَرَةٌ﴾ قال: هذه وجوه أهل النار؛ قال: والقَتَرة من الغَبَرة، قال: وهما واحد، قال: فأما في الدنيا فإن القترة: ما ارتفع، فلحق بالسماء، ورفعته الريح، تسميه العرب القترة، وما كان أسفل في الأرض فهو الغبرة.\n\n* *\n\nوقوله: ﴿أُولَئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ﴾\n\nيقول تعالى ذكره: هؤلاء الذين هذه صفتهم يوم القيامة هم الكفرة بالله، كانوا في الدنيا الفجرة في دينهم، لا يبالون ما أتوا به من معاصي الله، وركبوا من محارمه، فجزاهم الله بسوء أعمالهم ما أخبر به عباده.\n\nآخر تفسير سورة عبس.","32":31,"33":31,"34":31,"35":31,"36":31,"37":31,"38":31,"39":31,"40":31,"41":31,"42":31},"81":{"1":"القول في تأويل قوله تعالى: ﴿إِذَا الشَّمْسُ كُوِّرَتْ (١) وَإِذَا النُّجُومُ انْكَدَرَتْ (٢) وَإِذَا الْجِبَالُ سُيِّرَتْ (٣) وَإِذَا الْعِشَارُ عُطِّلَتْ (٤) ﴾\n\n.\n\nاختلف أهل التأويل في تأويل قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ فقال بعضهم: معنى ذلك: إذا الشمس ذهب ضوءها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسين بن الحريث، قال: ثنا الفضل بن موسى، عن الحسين بن واقد، عن الربيع بن أنس، عن أبي العالية، قال: ثني أبيّ بن كعب، قال: ستّ آيات قبل يوم القيامة: بينا الناس في أسواقهم، إذ ذهب ضوء الشمس، فبينما هم كذلك، إذ تناثرت النجوم، فبينما هم كذلك، إذ وقعت الجبال على وجه الأرض، فتحرّكت واضطربت واحترقت، وفزِعت الجنّ إلى الإنس، والإنس إلى الجنّ، واختلطت الدوابّ والطير والوحش، وماجوا بعضهم في بعض ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ قال: اختلطت ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: أهملها أهلها ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: قالت الجنّ للإنس: نحن نأتيكم بالخبر، قال: فانطلقوا إلى البحار، فإذا هي نار تأجج؛ قال: فبينما هم كذلك إذ تصدّعت الأرض صدعة واحدة إلى الأرض السابعة السفلى، وإلى السماء السابعة العليا، قال: فبينما هم كذلك إذ جاءتهم الريح فأماتتهم.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ يقول: أظلمت.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ يعني: ذهبت.\n\n⁕ حدثني محمد بن عمارة، حدثني عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: اضمحلت وذهبت.\n\n⁕ حدثنا ابن بشار وابن المثنى، قالا ثنا محمد بن جعفر، قال: ثنا شعبة، عن قتادة، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: ذهب ضوءها فلا ضوء لها.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القمي، عن جعفر، عن سعيد، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: غوّرت، وهي بالفارسية، كور تكور.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ أما تكوير الشمس: فذهابها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: كوّرت كورا بالفارسية.\n\nوقال آخرون: معنى ذلك: رمي بها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عثام بن عليّ، قال: ثنا إسماعيل بن أبي خالد، عن أبي صالح، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: نُكِّست.\n\n⁕ حدثني محمد بن عبد الرحمن المسروقي، قال: ثنا محمد بن بشر، قال: ثنا إسماعيل، عن أبي صالح مثله.\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا بدل بن المحبر، قال: ثنا شعبة، قال: سمعت إسماعيل، سمع أبا صالح في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: أُلقيت.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن ربيع بن خثيم ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: رُمِي بها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم، مثله.\n\nوالصواب من القول في ذلك عندنا: أن يقال: ﴿كُوِّرَتْ﴾ كما قال الله جل ثناؤه، والتكوير في كلام العرب: جمع بعض الشيء إلى بعض، وذلك كتكوير العمامة، وهو لفها على الرأس، وكتكوير الكارة، وهي جمع الثياب بعضها إلى بعض، ولفها، وكذلك قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ إنما معناه: جمع بعضها إلى بعض، ثم لفت فَرُمِي بها، وإذا فعل ذلك بها ذهب ضوءها فعلى التأويل الذي تأوّلناه وبيَّناه لكلا القولين اللَّذين ذكرت عن أهل التأويل وجه صحيح، وذلك أنها إذا كُوِّرت ورُمي بها، ذهب ضوءها.\n\n* *\n\nوقوله: ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾\n\nيقول: وإذا النجوم تناثرت من السماء فتساقطت، وأصل الانكدار: الانصباب، كما قال العجاج:\n\nأبْصَرَ خِرْبانَ فَضَاءٍ فانْكَدَرْ\n\nيعني بقوله: انكدر: انصبّ.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ قال: تناثرت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم، مثله.\n\n⁕ حدثني محمد بنُ عمارة، قال: ثنا عبيد الله، قال: أخبرنا إسرائيل، عن ابن أبي نجيح، عن مجاهد ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ قال: تناثرت.\n\n⁕ حدثني محمد بن موسى بن عبد الرحمن المسروقي، قال: ثنا محمد بن بشر، قال: ثنا إسماعيل، عن أبي صالح، في قوله: ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ قال: انتثرت.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ قال: تساقطت وتهافتت.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ قال: رُمِي بها من السماء إلى الأرض.\n\nوقال آخرون: انكدرت: تغيرت.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿وَإِذَا النُّجُومُ انْكَدَرَتْ﴾ يقول: تغيرت.\n\n* *\n\nوقوله: ﴿وَإِذَا الْجِبَالُ سُيِّرَتْ﴾\n\nيقول: وإذا الجبال سيرها الله، فكانت سرابا، وهباء منبثا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد ﴿وَإِذَا الْجِبَالُ سُيِّرَتْ﴾ قال: ذهبت.\n\n* *\n\nقوله: ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾\n\nوالعشار: جمع عشراء، وهي التي قد أتى عليها عشرة أشهر من حملها. يقول تعالى ذكره: وإذا هذه الحوامل التي يَتَنافس أهلها فيها أُهملت فتركت، من شدة الهول النازل بهم فكيف بغيرها؟! .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسين بن الحريث، قال: ثنا الفضل بن موسى، عن الحسين بن واقد، عن الربيع بن أنس، عن أبي العالية، قال: ثني أبيّ بن كعب ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: إذا أهملها أهلها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: خلا منها أهلها لم تُحْلَب ولم تُصرّ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: لم تحلب ولم تصر، وتخلَّى منها أربابها.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد، في قول الله: ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: سُيِّبت: تُرِكت.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: عشار الإبل.\n\n⁕ حدثنا ابن بشار، قال: ثنا هوذة، قال: ثنا عوف، عن الحسن ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: سيبها أهلها فلم تصر، ولم تحلب، ولم يكن في الدنيا مال أعجب إليهم منها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ قال: عشار الإبل سيبت.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ، يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَإِذَا الْعِشَارُ عُطِّلَتْ﴾ يقول: لا راعي لها.","2":1,"3":1,"4":1,"5":"القول في تأويل قوله تعالى: ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ (٥) وَإِذَا الْبِحَارُ سُجِّرَتْ (٦) وَإِذَا النُّفُوسُ زُوِّجَتْ (٧) وَإِذَا الْمَوْءُودَةُ سُئِلَتْ (٨) بِأَيِّ ذَنْبٍ قُتِلَتْ (٩) وَإِذَا الصُّحُفُ نُشِرَتْ (١٠) ﴾\n\n.\n\nاختلف أهل التأويل في معنى قوله: ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ فقال بعضهم: معنى ذلك: ماتت.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ بن مسلم الطوسي، قال: ثنا عباد بن العوّام، قال: أخبرنا حصين، عن عكرمة، عن ابن عباس، في قول الله: ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ قال: حَشْرُ البهائم: موتها، وحشر كل شيء: الموت، غير الجنّ والإنس، فإنهما يوقفان يوم القيامة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن ربيع بن خيثم ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ قال: أتى عليها أمر الله، قال سفيان، قال أبي، فذكرته لعكرِمة، فقال: قال ابن عباس: حشرها: موتها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم، بنحوه.\n\nوقال آخرون: بل معنى ذلك: وإذا الوحوش اختلطت.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسين بن حريث، قال: ثنا الفضل بن موسى، عن الحسين بن واقد، عن الربيع بن أنس عن أبي العالية، قال: ثني أُبيّ بن كعب ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ قال: اختلطت.\n\nوقال آخرون: بل معنى ذلك: جُمعت.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ هذه الخلائق موافية يوم القيامة، فيقضي الله فيها ما يشاء.\n\nوأولى الأقوال في ذلك بالصواب قول من قال: معنى حشرت: جمعت، فأميتت لأن المعروف في كلام العرب من معنى الحشر: الجمع، ومنه قول الله: ﴿وَالطَّيْرَ مَحْشُورَةً﴾ يعني: مجموعة.\n\n* *\n\nوقوله: ﴿فَحَشَرَ فَنَادَى﴾\n\nوإنما يحمل تأويل القرآن على الأغلب الظاهر من تأويله، لا على الأنكر المجهول.\n\n* *\n\nوقوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معنى ذلك: وإذا البحار اشتعلت نارا وحَمِيت.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسين بن حريث، قال: ثنا الفضل بن موسى، قال: ثنا الحسين بن واقد، عن الربيع بن أنس، عن أبي العالية، قال: ثني أبيُّ بن كعب ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: قالت الجنّ للإنس: نحن نأتيكم بالخبر، فانطلقوا إلى البحار، فإذا هي تأجج نارا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن داود، عن سعيد بن المسيب، قال: قال عليّ رضي الله عنه لرجل من اليهود: أين جهنم؟ فقال: البحر، فقال: ما أراه إلا صادقا ﴿وَالْبَحْرِ الْمَسْجُورِ﴾ ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ مخففة.\n\n⁕ حدثني حوثرة بن محمد المنقري، قال: ثنا أبو أُسامة، قال: ثنا مجالد، قال: أخبرني شيخ من بجيلة عن ابن عباس، في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: كوّر الله الشمس والقمر والنجوم في البحر، فيبعث عليها ريحا دبورا، فتنفخه حتى يصير نارا، فذلك قوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ .\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: إنها توقد يوم القيامة، زعموا ذلك التسجير في كلام العرب.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن حفص بن حميد، عن شمر بن عطية، في قوله: ﴿وَالْبَحْرِ الْمَسْجُورِ﴾ قال: بمنزلة التنور المسجور ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ مثله.\n\n⁕ قال: ثنا مِهران، عن سفيان ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: أوقدت.\n\nوقال آخرون: معنى ذلك: فاضت.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن ربيع بن خيثم ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: فاضت.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن ربيع مثله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبي، في قوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: مُلئت، ألا ترى أنه قال: ﴿وَالْبَحْرِ الْمَسْجُورِ﴾ .\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ يقول: فُجِّرت.\n\nوقال آخرون: بل عُنِيَ بذلك أنه ذهب ماؤها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: ذهب ماؤها فلم يبق فيها قطرة.\n\n⁕ حدثنا محمد بن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: غار ماؤها فذهب.\n\n⁕ حدثني الحسين بن محمد الذارع، قال: ثنا المعتمر بن سليمان، عن أبيه، عن الحسين، في هذا الحرف ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: يبست.\n\n⁕ حدثنا الحسين بن محمد، قال: ثنا يزيد بن زريع، قال: ثنا أبو رجاء، عن الحسن، بمثله.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿وَإِذَا الْبِحَارُ سُجِّرَتْ﴾ قال: يبست.\n\nوأولى الأقوال في ذلك بالصواب قول من قال: معنى ذلك: مُلئت حتى فاضت، فانفجرت وسالت كما وصفها الله به في الموضع الآخر، فقال: \" وَإذَا الْبِحَارُ فُجِّرَتْ \" والعرب تقول للنهر أو للرَّكيّ المملوء: ماء مسجور؛ ومنه قول لبيد:\n\nفَتَوَسَّطا عُرْضَ السَّرِيّ وَصَدَّعا ... مَسْجُورَةً مُتَجاوِرًا قُلامُها\n\nويعني بالمسجورة: المملوءة ماء.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء المدينة والكوفة ﴿سُجِّرَتْ﴾ بتشديد الجيم. وقرأ ذلك بعض قرّاء البصرة: بتخفيف الجيم.\n\nوالصواب من القول في ذلك: أنهما قراءتان معروفتان متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾\n\nاختلف أهل التأويل في تأويله، فقال بضعهم: أُلحِقَ كلُّ إنسان بشكله، وقُرِنَ بين الضُّرَباءِ والأمثال.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن سماك، عن النعمان بن بشير، عن عمر رضي الله عنه ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: هما الرجلان يعمَلان العمل الواحد يدخلان به الجنة، ويدخلان به النار.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن سماك بن حرب، عن النعمان بن بشير عن عمر بن الخطاب رضي الله عنه ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: هما الرجلان يعملان العمل فيدخلان به الجنة، وقال: ﴿احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ﴾ ، قال: ضرباءَهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سماك بن حرب، عن النعمان بن بشير، عن عمر بن الخطاب رضي الله عنه ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: هما الرجلان يعملان العمل يدخلان به الجنة أو النار.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن سماك بن حرب أنه سمع النعمان بن بشير يقول: سمعت عمر بن الخطاب وهو يخطب، قال: ﴿وَكُنْتُمْ أَزْوَاجًا ثَلاثَةً فَأَصْحَابُ الْمَيْمَنَةِ مَا أَصْحَابُ الْمَيْمَنَةِ وَأَصْحَابُ الْمَشْأَمَةِ مَا أَصْحَابُ الْمَشْأَمَةِ وَالسَّابِقُونَ السَّابِقُونَ أُولَئِكَ الْمُقَرَّبُونَ﴾ ثم قال: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: أزواج في الجنة، وأزواج في النار.\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن النعمان بن بشير، قال: سُئل عمر بن الخطاب رضي الله عنه، عن قول الله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: يقرن بين الرجل الصالح مع الرجل الصالح في الجنة، وبين الرجل السوء مع الرجل السوء في النار.\n\n⁕ حدثني محمد بن خلف، قال: ثنا محمد بن الصباح الدولابي، عن الوليد، عن سماك، عن النعمان بن بشير، عن النبيّ ﷺ، والنعمان عن عمرو قال: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: الضرباء كلّ رجل مع كل قوم كانوا يعملون عمله، وذلك أن الله يقول: ﴿وَكُنْتُمْ أَزْوَاجًا ثَلاثَةً فَأَصْحَابُ الْمَيْمَنَةِ مَا أَصْحَابُ الْمَيْمَنَةِ وَأَصْحَابُ الْمَشْأَمَةِ مَا أَصْحَابُ الْمَشْأَمَةِ وَالسَّابِقُونَ السَّابِقُونَ﴾ قال: هم الضرباء.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: ذلك حين يكون الناس أزواجا ثلاثة.\n\n⁕ حدثنا محمد بن بشار، قال: ثنا هوذة، قال: ثنا عوف، عن الحسن، في قوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: ألحق كلّ امرئ بشيعته.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: الأمثال من الناس جُمِع بينهم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: لحق كلُّ إنسان بشيعته، اليهود باليهود، والنصارى بالنصارى.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: يحشر المرء مع صاحب عمله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع،: قال: يجيء المرء مع صاحب عمله.\n\nوقال آخرون: بل عني بذلك أن الأرواح ردّت إلى الأجساد فزوّجت بها: أي جعلت لها زوجا.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر، عن أبيه، عن أبي عمرو، عن عكرِمة ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: الأرواح ترجع إلى الأجساد.\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن داود، عن الشعبيّ أنه قال في هذه الآية ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: زوّجت الأجساد فردّت الأرواح في الأجساد.\n\n⁕ حدثني عبيد بن أسباط بن محمد، قال: ثنا أبي، عن أبيه، عن عكرِمة ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: ردّت الأرواح في الأجساد.\n\n⁕ حدثني الحسن بن زريق الطهوي، قال: ثنا أسباط، عن أبيه، عن عكرمة، مثله.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: أخبرنا داود، عن الشعبيّ، في قوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ قال: زوّجت الأرواح الأجساد.\n\nوأولى التأويلين في ذلك بالصحة، الذي تأوّله عمر بن الخطاب رضي الله عنه للعلة التي اعتلّ بها، وذلك قول الله تعالى ذكره: ﴿وَكُنْتُمْ أَزْوَاجًا ثَلاثَةً﴾ ، وقوله: ﴿احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ﴾ وذلك لا شكّ الأمثال والأشكال في الخير والشرّ، وكذلك قوله: ﴿وَإِذَا النُّفُوسُ زُوِّجَتْ﴾ بالقرناء والأمثال في الخير والشرّ.\n\n⁕ وحدثني مطر بن محمد الضبي، قال: ثنا عبد الرحمن بن مهدي، قال: ثنا عبد العزيز بن مسلم القسملي عن الربيع بن أنس، عن أبي العالية في قوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ قال: سيأتي أوّلها والناس ينظرون، وسيأتي آخرها إذا النفوس زوّجت.\n\n* *\n\nوقوله: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ بِأيّ ذَنْبٍ قُتلَتْ﴾\n\nاختلفت القرّاء في قراءة ذلك فقرأه أبو الضحى مسلم بن صبيح ﴿وَإذَا المَوْءُودَةُ سألَتْ بِأيّ ذَنْبٍ قُتلَتْ﴾ بمعنى: سألت الموءودة الوائدين: بأي ذنب قتلوها.\n\nذكر الرواية بذلك:\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن مسلم، في قوله: ﴿وَإذَا المَوْءُودَةُ سألَتْ﴾ قال: طلبت بدمائها.\n\n⁕ حدثنا سوّار بن عبد الله العنبري، قال: ثنا يحيى بن سعيد، عن الأعمش، قال: قال أبو الضحى ﴿وَإذَا المَوْءُودَةُ سألَتْ﴾ قال: سألت قَتَلَتها.\n\nولو قرأ قارئ ممن قرأ ﴿سألَتْ بِأيّ ذَنْبٍ قُتلَتْ﴾ كان له وجه، وكان يكون معنى ذلك من قرأ ﴿بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ غير أنه إذا كان حكاية جاز فيه الوجهان، كما يقال: قال عبد الله: بأيّ ذنْبٍ ضُرب؛ كما قال عنترة:\n\nالشَّاتِمَيْ عِرْضِي ولم أشْتُمْهُما ... والنَّاذِرَيْنِ إذَا لَقِيتُهُما دَمي\n\nوذلك أنهما كانا يقولان: إذا لقينا عنترة لنقتلنَّه، فحكى عنترة قولهما في شعره؛ وكذلك قول الآخر:\n\nرَجُلانِ مِنْ ضَبَّةَ أخْبَرَانا ... أنَّا رأيْنا رَجُلا عُرْيانا\n\nبمعنى: أخبرانا أنهما، ولكنه جرى الكلام على مذهب الحكاية. وقرأ ذلك بعض عامة قرّاء الأمصار: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ بمعنى: سُئلت الموءودة بأيّ ذنب قُتلت، ومعنى قُتلت: قتلت غير أن ذلك ردّ إلى الخبر على وجه الحكاية على نحو القول الماضي قبل، وقد يتوجه معنى ذلك إلى أن يكون: وإذا الموءودة سألت قتلتها ووائديها، بأيّ ذنب قتلوها؟ ثم ردّ ذلك إلى ما لم يسمّ فاعله، فقيل: بأيّ ذنب قتلت.\n\nوأولى القراءتين في ذلك عندنا بالصواب قراءة من قرأ ذلك ﴿سُئِلَتْ﴾ بضم السين ﴿بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ على وجه الخبر، لإجماع الحجة من القراء عليه. والموءودة: المدفونة حية، وكذلك كانت العرب تفعل ببناتها؛ ومنه قول الفرزدق بن غالب:\n\nوِمَّنا الذي أحْيا الوَئِيدَ وَغائِب ... وعَمْروٌ، ومنَّا حامِلونَ ودَافعُ\n\nيقال: وأده فهو يئده وأدا، ووأدة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ﴾ هي في بعض القراءات: ﴿سأَلَتْ بِأيّ ذَنْب قُتلَتْ﴾ لا بذنب، كان أهل الجاهلية يقتل أحدهم ابنته، ويغذو كلبه، فعاب الله ذلك عليهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: جاء قيس بن عاصم التميمي إلى النبيّ ﷺ فقال: إني وأدت ثماني بنات في الجاهلية، قال: \" فأعْتِقْ عَنْ كُلّ وَاحِدَةٍ بَدَنَةً\".\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ قال: كانت العرب من أفعل الناس لذلك.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن ربيع بن خيثم بمثله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ﴾ قال: البنات التي كانت طوائف العرب يقتلونهنّ، وقرأ: (بِأَيِّ ذَنْبٍ قُتِلَتْ) .\n\n* *\n\nوقوله: ﴿وَإِذَا الصُّحُفُ نُشِرَتْ﴾\n\nيقول تعالى ذكره: وإذا صحف أعمال العباد نُشرت لهم بعد أن كانت مطوية على ما فيها مكتوب من الحسنات والسيئات.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿وَإِذَا الصُّحُفُ نُشِرَتْ﴾ صحيفتك يا ابن آدم تملى ما فيها، ثم تُطوى، ثم تُنشر عليك يوم القيامة.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء المدينة ﴿نُشِرتْ﴾ بتخفيف الشين، وكذلك قرأ أيضا بعض الكوفيين، وقرأ ذلك بعض قرّاء مكة وعامة قرّاء الكوفة بتشديد الشين. واعتلّ من اعتل منهم لقراءته ذلك كذلك بقول الله: ﴿أَنْ يُؤْتَى صُحُفًا مُنَشَّرَةً﴾ ولم يقل منشورة، وإنما حسن التشديد فيه لأنه خبر عن جماعة، كما يقال: هذه كباش مُذبَّحَةٌ، ولو أخبر عن الواحد بذلك كانت مخففة، فقيل مذبوحةٌ، فكذلك قوله منشورة.","6":5,"7":5,"8":5,"9":5,"10":5,"11":"القول في تأويل قوله تعالى: ﴿وَإِذَا السَّمَاءُ كُشِطَتْ (١١) وَإِذَا الْجَحِيمُ سُعِّرَتْ (١٢) وَإِذَا الْجَنَّةُ أُزْلِفَتْ (١٣) عَلِمَتْ نَفْسٌ مَا أَحْضَرَتْ (١٤) فَلا أُقْسِمُ بِالْخُنَّسِ (١٥) الْجَوَارِ الْكُنَّسِ (١٦) ﴾\n\n.\n\nيقول تعالى ذكره: وإذا السماء نزعت وجُذبت ثم طُويت.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿كُشِطَتْ﴾ قال: جُذبت. وذُكر أن ذلك في قراءة عبد الله ﴿قشِطَتْ﴾ بالقاف، والقشْط والكَشْط بمعنى واحد وذلك تحويل من العرب الكاف قافا لتقارب مخرجيهما، كما قيل للكافور قافور، ولقُسط كُسْط، وذلك كثير في كلامهم إذا تقارب مخرج الحرفين أبدلوا من كلّ واحد منهما صاحبه، كقولهم للأثافي: أثاثي، وثوب فَرْقَبِيّ وثَرْقَبِيّ.\n\n* *\n\nوقوله: ﴿وَإِذَا الْجَحِيمُ سُعِّرَتْ﴾\n\nيقول تعالى ذكره: وإذا الجحيم أوقد عليها فأُحميت.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِذَا الْجَحِيمُ سُعِّرَتْ﴾ سعرها غضب الله، وخطايا بني آدم.\n\nواختلفت القرّاء في قراءة ذلك فقرأته عامة قرّاء المدينة ﴿سُعِّرَتْ﴾ بتشديد عينها بمعنى أوقد عليها مرة بعد مرّة، وقرأته عامة قرّاء الكوفة بالتخفيف. والقول في ذلك أنهما قراءتان معروفتان فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿وَإِذَا الْجَنَّةُ أُزْلِفَتْ﴾\n\nيقول تعالى ذكره: وإذا الجنة قرّبت وأُدنيت.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبيه، عن أبي يعلى، عن الربيع بن خثيم: ﴿وَإِذَا الْجَحِيمُ سُعِّرَتْ وَإِذَا الْجَنَّةُ أُزْلِفَتْ﴾ قال: إلى هذين ما جرى الحديث: فريق في الجنة، وفريق في السعير.\n\n⁕ حدثني ابن حميد، قال: ثنا مهران، عن سفيان عن أبيه، عن أبي يعلى، عن الربيع ﴿وَإِذَا الْجَحِيمُ سُعِّرَتْ وَإِذَا الْجَنَّةُ أُزْلِفَتْ﴾ قال: إلى هذين ما جرى الحديث: فريق إلى الجنة، وفريق إلى النار. يعنى الربيع بقوله: إلى هذين ما جرى الحديث أن ابتداء الخبر ﴿إِذَا الشَّمْسُ كُوِّرَتْ ... ﴾ إلى قوله: ﴿وَإِذَا الْجَحِيمُ سُعِّرَتْ﴾ إنما عُدِّدت الأمور الكائنة التي نهايتها أحد هذين الأمرين، وذلك المصير إما إلى الجنة، وإما إلى النار.\n\n* *\n\nوقوله: ﴿عَلِمَتْ نَفْسٌ مَا أَحْضَرَتْ﴾\n\nيقول تعالى ذكره: علمت نفس عند ذلك ما أحضرت من خير، فتصير به إلى الجنة، أو شرّ فتصير به إلى النار، يقول: يتبين له عند ذاك ما كان جاهلا به، وما الذي كان فيه صلاحه من غيره.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة (عَلِمَتْ نَفْسٌ مَا أَحْضَرَتْ) من عمل قال: قال عمر بن الخطاب رضي الله عنه: وإلى هذا جرى الحديث.\n\n* *\n\nوقوله: ﴿عَلِمَتْ نَفْسٌ مَا أَحْضَرَتْ﴾\n\nجواب لقوله: ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ وما بعدها، كما يقال: إذا قام عبد الله قعد عمرو.\n\n* *\n\nوقوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾\n\nاختلف أهل التأويل في الخُنَّس الجوار الكنَّسِ فقال بعضهم: هي النجوم الدراريّ الخمسة تخنِس في مجراها فترجع وتكنس، فتستتر في بيوتها كما تكنس الظباء في المغار، والنجوم الخمسة: بَهْرام وزُحَل، وعُطارد، والزُّهَرَة، والمُشْتَرِي.\n\nذكر من قال ذلك:\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن خالد بن عُرعُرة، أن رجلا قام إلى عليّ رضي الله عنه، فقال: ما ﴿الْجَوَارِ الْكُنَّسِ﴾ ؟ قال: هي الكواكب.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن سماك بن حرب، قال: سمعت خالد بن عُرعرة، قال: سمعت عليا عليه السلام، وسُئل عن ﴿لا أُقْسِمُ بالخُنَّسِ الجَوَارِ الكُنَّسِ﴾ قال: هي النجوم تخنس بالنهار، وتكنس بالليل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سماك، عن خالد بن عرعرة، عن عليّ رضي الله عنه، قال: النجوم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي إسحاق، عن رجل من مُراد، عن عليّ أنه قال: هل تدرون ما الخنس؟ هي النجوم تجري بالليل، وتخنس بالنهار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني جرير بن حازم، أنه سمع الحسن يسئل، فقيل: يا أبا سعيد ما الجواري الكُنَّس؟ قال: النجوم.\n\n⁕ حدثنا محمد بن بشار، قال: ثنا هوذة بن خليفة، قال: ثنا عوف، عن بكر بن عبد الله، في قوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: هي النجوم الدراريّ، التي تجري تستقبل المشرق.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن مجاهد، قال: هي النجوم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبي إسحاق، عن رجل من مراد، عن عليّ بن أبي طالب رضي الله عنه ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: يعني النجوم تكنس بالنهار، وتبدو بالليل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة: قوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: هي النجوم تبدو بالليل وتخنس بالنهار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن في قوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: هي النجوم تخنس بالنهار، والجوار الكنس: سيرهنّ إذا غبن.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: الخنس والجواري الكنس: النجوم الخنس، إنها تخنس تتأخر عن مطلعها، هي تتأخر كلّ عام لها في كلّ عام تأخر عن تعجيل ذلك الطلوع تخنس عنه. والكنس: تكنس بالنهار فلا تُرَى. قال: والجواري تجري بعد، فهذا الخنس الجواري الكنس.\n\nوقال آخرون: هي بقر الوحش التي تكنس في كناسها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسن بن عرفة قال: ثنا هشيم بن بشير، عن زكريا بن أبي زائدة، عن أبي إسحاق السَّبيعيّ، عن أبي ميسرة، عن عبد الله بن مسعود أنه قال لأبي ميسرة: ما الجواري الكنس؟ قال: فقال بقر الوحش قال: فقال: وأنا أرى ذلك.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى، عن سفيان، عن أبي إسحاق، عن أبي ميسرة، عن عبد الله، في قوله: ﴿الْجَوَارِ الْكُنَّسِ﴾ : قال: بقر الوحش.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي إسحاق، عن عمرو ابن شرحبيل، قال: قال ابن مسعود: يا عمرو ما الجواري الكنس، أو ما تراها؟ قال عمرو: أراها البقر، قال عبد الله: وأنا أراها البقر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبي إسحاق، عن أبي ميسرة قال: سألت عنها عبد الله، فذكر نحوه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني جرير بن حازم، قال: ثني الحجاج بن المنذر، قال: سألت أبا الشَعثاء جابر بن زيد عن الجواري الكنس، قال: هي البقر إذا كَنَست كوانسها.\n\nقال يونس: قال لي عبد الله بن وهب: هي البقر إذا فرّت من الذئاب، فذلك الذي أراد بقوله: كنست كوانسها.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال جرير، وحدثني الصلت بن راشد، عن مجاهد مثل ذلك.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن إبراهيم، في قوله: ﴿الْجَوَارِ الْكُنَّسِ﴾ قال: هي بقر الوحش.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، قال: سُئل مجاهد ونحن عند إبراهيم، عن قوله: ﴿الْجَوَارِ الْكُنَّسِ﴾ قال: لا أدري، فانتهره إبراهيم وقال: لِمَ لا تدري؟ فقال: إنهم يروُون عن عليّ رضي الله عنه: وكنا نسمع أنها البقر، فقال إبراهيم: هي البقر، الجواري الكنس: حِجَرة بقر الوحش التي تأوي إليها، والخنس الجوارى: البقر.\n\n⁕ حدثنا يعقوب، قال: ثنا هشيم، قال: أخبرنا مغيرة، عن إبراهيم ومجاهد أنهما تذاكرا هذه الآية ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ فقال إبراهيم لمجاهد: قل فيها ما سمعت، قال: فقال مجاهد: كنا نسمع فيها شيئا، وناس يقولون: إنها النجوم، قال: فقال إبراهيم: إنهم يكذبون على عليّ رضي الله عنه، هذا كما رَوَوْا عن علي رضي الله عنه، أنه ضمَّن الأسفل الأعلى، والأعلى الأسفل.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن المغيرة، قال: سُئل مجاهد عن الجواري الكنس قال: لا أدري يزعمون أنها البقر؛ قال: فقال إبراهيم: ما لا تدري هي البقر، قال: يذكرون عن عليّ رضي الله عنه أنها النجوم، قال: يكذبون على عليّ عليه السلام.\n\nوقال آخرون: هي الظباء.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ يعني: الظباء.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث بن إسحاق، عن جعفر، عن سعيد بن جُبير ﴿فَلا أُقْسِمُ بِالْخُنَّسِ﴾ قال: الظباء.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلية، قال: ثنا ابن أبي نجيح، عن مجاهد، في قوله: ﴿فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾ قال: كنا نقول: \" أظنه قال\": الظباء، حتى زعم سعيد بن جُبير أنه سأل ابن عباس عنها، فأعاد عليه قراءتها.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿الْخُنَّسِ الْجَوَارِ الْكُنَّسِ ِ﴾ يعني الظباء.\n\nوأولى الأقوال في ذلك بالصواب: أن يقال: إن الله تعالى ذكره أقسم بأشياء تخنس أحيانا: أي تغيب، وتجري أحيانا وتكنس أخرى، وكنوسها: أن تأوي في مكانسها، والمكانس عند العرب: هي المواضع التي تأوي إليها بقر الوحش والظباء، واحدها: مَكْنِس وكناس، كما قال الأعشى:\n\nفلَمَّا لَحِقْنا الْحَيَّ أتْلَعَ أُنَّسٌ ... كمَا أتْلَعَتْ تَحْتَ المَكانِسِ رَبْرَبُ\n\nفهذه جمع مَكْنِس، وكما قال في الكناس طَرَفة بن العبد:\n\nكأنَّ كِناسَيْ ضَالَةٍ يَكْنُفانِهَا ... وأطْرَ قِسِيٍّ تَحْتَ صُلْبٍ مُؤَيَّدِ\n\nوأما الدلالة على أن الكناس قد يكون للظباء، فقول أوس بن حَجَر:\n\nأَلَمْ تَرَ أنَّ اللهَ أنزلَ مُزْنَةً ... وعُفْرُ الظِّباءِ في الكِناسِ تَقَمَّعُ\n\nفالكناس في كلام العرب ما وصفت، وغير مُنكر أن يستعار ذلك في المواضع التي تكون بها النجوم من السماء، فإذا كان ذلك كذلك، ولم يكن في الآية دلالة على أن المراد بذلك النجوم دون البقر، ولا البقر دون الظباء، فالصواب أن يُعَمّ بذلك كلّ ما كانت صفته الخنوس أحيانا والجري أخرى، والكنوس بآنات على ما وصف جلّ ثناؤه من صفتها.","12":11,"13":11,"14":11,"15":11,"16":11,"17":"القول في تأويل قوله تعالى: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ (١٧) وَالصُّبْحِ إِذَا تَنَفَّسَ (١٨) إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ (١٩) ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ (٢٠) ﴾\n\n.\n\nأقسم ربنا جلّ ثناؤه بالليل إذا عسعس، يقول: وأقسم بالليل إذا عسعس.\n\nواختلف أهل التأويل في قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ فقال بعضهم: عُنِيَ بقوله: ﴿إِذَا عَسْعَسَ﴾ إذا أدبر.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ يقول: إذا أدبر.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ يعني: إذا أدبر.\n\n⁕ حدثنا عبد الحميد بن بيان اليشكري، قال: ثنا محمد بن يزيد، عن إسماعيل بن أبي خالد، عن رجل عن أبي ظَبيان، قال: كنت أتبع عليّ بن أبي طالب رضي الله عنه، وهو خارج نحو المشرق، فاستقبل الفجر، فقرأ هذه الآية: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن إدريس، عن الحسن بن عبيد الله، عن سعد بن عبيدة، عن أبي عبد الرحمن، قال: خرج عليّ عليه السلام مما يلي باب السوق، وقد طلع الصبح أو الفجر، فقرأ: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ أين السائل عن الوتر، نعم ساعة الوتر هذه.\n\nثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ قال: إقباله، ويقال: إدباره.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ : إذا أدبر.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِذَا عَسْعَسَ﴾ قال: إذا أدبر.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿إِذَا عَسْعَسَ﴾ إذا أدبر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مسعر، عن أبي حصين، عن أبي عبد الرحمن، قال: خرج عليّ عليه السلام بعد ما أذّن المؤذّن بالصبح، فقال: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ أين السائل عن الوتر؟ قال: نعم ساعة الوتر هذه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ قال: عسعس تولى، وقال: تنفس الصبح من هاهنا، وأشار إلى المشرق طلاع الفجر.\n\nوقال آخرون: عُني بقوله: ﴿إِذَا عَسْعَسَ﴾ إذا أقبل بظلامه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَاللَّيْلِ إِذَا عَسْعَسَ﴾ قال: إذا غَشِيَ الناسَ.\n\n⁕ حدثنا الحسين بن عليّ الصدائي، قال: ثني أبي، عن الفضيل، عن عطية (وَاللّيْلِ إِذَا عَسْعَسَ) قال: أشار بيده إلى المغرب.\n\nوأولى التأويلين في ذلك بالصواب عندي قول من قال: معنى ذلك: إذا أدبر، وذلك لقوله: ﴿وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ فدلّ بذلك على أن القسم بالليل مدبرًا، وبالنهار مقبلا والعرب تقول: عسعس الليل، وسَعْسَع الليل: إذا أدبر، ولم يبق منه إلا اليسير؛ ومن ذلك قول رُؤْبة بن العجاج:\n\nيا هِنْدُ ما أسْرَعَ ما تَسَعْسَعا ... وَلَوْ رَجا تَبْعَ الصِّبا تَتَبَّعا\n\nفهذه لغة من قال: سعسع؛ وأما لغة من قال: عسعس، فقول علقمة بن قُرْط:\n\nحتى إذَا الصُّبْحُ لَهَا تَنَفَّسا ... وانْجابَ عَنْها لَيْلُها وَعَسْعَسا\n\nيعني أدبر. وقد كان بعض أهل المعرفة بكلام العرب، يزعم أن عسعس: دنا من أوّله وأظلم. وقال الفراء: كان أبو البلاد النحوي ينشد بيتا:\n\nعَسْعَسَ حتى لَوْ يشاءُ إدَّنا ... كانَ لَه مِنْ ضَوْئِهِ مَقْبَسُ\n\nيقول: لو يشاء إذ دنا، ولكنه أدغم الذال في الدال، قال الفراء: فكانوا يرون أن هذا البيت مصنوع.\n\n* *\n\nوقوله: ﴿وَالصُّبْحِ إِذَا تَنَفَّسَ﴾\n\nيقول: وضوء النهار إذا أقبل وتبين.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ قال: إذا نشأ.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ : إذا أضاء وأقبل.\n\n* *\n\nوقوله: ﴿إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ﴾\n\nيقول تعالى ذكره: إن هذا القرآن لتنزيل رسول كريم؛ يعني: جبريل، نزله على محمد بن عبد الله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، أنه كان يقول: ﴿إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ﴾ يعني: جبريل.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، أنه كان يقول: ﴿إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ﴾ قال: هو جبريل.\n\n* *\n\nوقوله: ﴿ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ﴾\n\nيقول تعالى ذكره: ذي قوّة، يعني: جبرائيل على ما كلف من أمر غير عاجز ﴿عِنْدَ ذِي الْعَرْشِ مَكِينٍ﴾ يقول: هو مكين عند ربّ العرش العظيم.","18":17,"19":17,"20":17,"21":"القول في تأويل قوله تعالى: ﴿مُطَاعٍ ثَمَّ أَمِينٍ (٢١) وَمَا صَاحِبُكُمْ بِمَجْنُونٍ (٢٢) وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ (٢٣) وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ (٢٤) وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَجِيمٍ (٢٥) فَأَيْنَ تَذْهَبُونَ (٢٦) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿مُطَاعٍ ثَمَّ﴾ يعني جبريل ﷺ، مطاع في السماء تطيعه الملائكة ﴿أمِينٍ﴾ يقول: أمين عند الله على وحيه ورسالته وغير ذلك مما ائتمنه عليه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني أبو السائب، قال: ثنا عمر بن شبيب المسلي، عن إسماعيل بن أبي خالد. عن أبي صالح: ﴿مُطَاعٍ ثَمَّ أَمِينٍ﴾ قال جبريل عليه السلام، أمين على أن يدخل سبعين سرادقا من نور بغير إذن.\n\n⁕ حدثنا محمد بن منصور الطوسي، قال: ثنا عمر بن شبيب، قال: ثنا إسماعيل بن أبي خالد، قال: لا أعلمه إلا عن أبي صالح، مثله.\n\n⁕ حدثنا سليمان بن عمر بن خالد الأقطع، قال: ثني أبي عمر بن خالد، عن معقل بن عبيد الله الجزري، قال: قال ميمون بن مِهْران في قوله: ﴿مُطَاعٍ ثَمَّ أَمِينٍ﴾ قال: ذاكم جبريل عليه السلام.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ مُطَاعٍ ثَمَّ أَمِينٍ﴾ قال: يعني جبريل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ مُطَاعٍ﴾ مطاع عند الله ﴿ثَمَّ أَمِينٍ﴾ .\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿مُطَاعٍ ثَمَّ أَمِينٍ﴾ يعني: جبريل عليه السلام.\n\n* *\n\nوقوله: ﴿وَمَا صَاحِبُكُمْ بِمَجْنُونٍ﴾\n\nيقول تعالى ذكره: وما صاحبكم أيها الناس محمد بمجنون فيتكلم عن جنة، ويهذي هذيان المجانين ﴿بَلْ جَاءَ بِالْحَقِّ وَصَدَّقَ الْمُرْسَلِينَ﴾ .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا سليمان بن عمرو بن خالد البرقي، قال: ثنا أبي عمرو بن خالد، عن مَعْقل بن عبد الله الجَزَري، قال: قال ميمون بن مهران: ﴿وَمَا صَاحِبُكُمْ بِمَجْنُونٍ﴾ قال: ذاكم محمد ﷺ.\n\n* *\n\nوقوله: ﴿وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ﴾\n\nيقول تعالى ذكره: ولقد رآه أي محمدٌ جبريل ﷺ في صورته بالناحية التي تبين الأشياء، فترى من قبَلها، وذلك من ناحية مطلع الشمس من قِبَل المشرق.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبى نجيح، عن مجاهد قوله: ﴿بِالأفُقِ الْمُبِينِ﴾ الأعلى. قال: بالأفق من نحو \" أجياد\".\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿بِالأفُقِ الْمُبِينِ﴾ قال: كنا نحدَّث أن الأفق حيث تطلع الشمس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ﴾ كنا نحدَّث أنه الأفق الذي يجيء منه النهار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ﴾ قال: رأى جبريل بالأفق المبين.\n\n⁕ حدثني عيسى بن عثمان بن عيسى الرملي، قال: ثنا يحيى بن عيسى، عن الأعمش، عن الوليد بن العيزار، قال: سمعت أبا الأحوص يقول في قول الله: ﴿وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ﴾ قال: رأى جبريل له ستّ مئة جناح في صورته.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن عطاء، عن عامر، قال: ما رأى جبريل النبيّ ﷺ في صورته إلا مرّة واحدة، وكان يأتيه في صورة رجل يقال له: دَحْية، فأتاه يوم رآه في صورته قد سدّ الأفق كله، عليه سندس أخضر معلق الدّر، فذلك قول الله: ﴿وَلَقَدْ رَآهُ بِالأفُقِ الْمُبِينِ﴾ وذُكر أن هذه الآية في \" إذا الشمس كوّرت \") ﴿إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ﴾ في جبريل، إلى قوله: ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ يعني النبيّ ﷺ.\n\n* *\n\nوقوله: ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾\n\nاختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء المدينة والكوفة ﴿بِضَنِينٍ﴾ بالضاد، بمعنى أنه غير بخيل عليهم بتعليمهم ما علَّمه الله، وأنزل إليه من كتابه. وقرأ ذلك بعض المكيين وبعض البصريين وبعض الكوفيين ﴿بِظَنِينٍ﴾ بالظاء، بمعنى أنه غير متهم فيما يخبرهم عن الله من الأنباء.\n\nذكر من قال ذلك بالضاد، وتأوّله على ما وصفنا من التأويل من أهل التأويل: حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن عاصم، عن زِرّ ﴿وَما هوَ عَلَى الْغَيْبِ بِظَنِينٍ﴾ قال: الظَّنين: المتهم. وفي قراءتكم: ﴿بِضَنِينٍ﴾ والضنين: البخيل، والغيب: القرآن.\n\n⁕ حدثنا بشر، قال: ثنا خالد بن عبد الله الواسطي، قال: ثنا مغيرة، عن إبراهيم ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ ببخيل.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ قال: ما يضنّ عليكم بما يعلم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ قال: إن هذا القرآن غيب، فأعطاه الله محمدا، فبذله وعلَّمه ودعا إليه، والله ما ضنّ به رسول الله ﷺ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عاصم، عن زرّ ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ قال: في قراءتنا بمتهم، ومن قرأها ﴿بِضَنِينٍ﴾ يقول: ببخيل.\n\n⁕ حدثنا مهران، عن سفيان ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ قال: ببخيل.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ الغيب: القرآن، لم يضنّ به على أحد من الناس أدّاه وبلَّغه، بعث الله به الروح الأمين جبريل إلى رسول الله ﷺ، فأدّى جبريل ما استودعه الله إلى محمد، وأدّى محمد ما استودعه الله وجبريل إلى العباد، ليس أحد منهم ضَنَّ، ولا كَتَم، ولا تَخَرَّص.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن عطاء، عن عامر ﴿وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ﴾ يعني النبيّ ﷺ.\n\nذكر من قال ذلك بالظاء، وتأوّله على ما ذكرنا من أهل التأويل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا المحاربي، عن جويبر، عن الضحاك، عن ابن عباس، أنه قرأ: ﴿بظَنينٍ﴾ قال: ليس بمتهم.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي المعلَّى، عن سعيد بن جُبير أنه كان يقرأ هذا الحرف ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ فقلت لسعيد بن جُبير: ما الظنين؟ قال: ليس بمتهم.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي المعلى، عن سعيد بن جُبير أنه قرأ: ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ قلت: وما الظنين؟ قال: المتهم.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ يقول: ليس بمتهم على ما جاء به، وليس يظنّ بما أوتي.\n\n⁕ حدثنا بشر، قال: ثنا خالد بن عبد الله الواسطيّ، قال: ثنا المغيرة، عن إبراهيم ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ قال: بمتهم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عاصم، عن زِرّ ﴿وَما هُوَ عَلى الْغَيْبِ بِظَنِينٍ﴾ قال: الغَيب: القرآن. وفي قراءتنا ﴿بِظَنِينٍ﴾ متهم.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿بِظَنِينٍ﴾ قال: ليس على ما أنزل الله بمتهم.\n\nوقد تأوّل ذلك بعض أهل العربية أن معناه: وما هو على الغيب بضعيف، ولكنه محتمِل له مطيق، ووجهه إلى قول العرب للرجل الضعيف: هو ظَنُون.\n\nوأولى القراءتين في ذلك عندي بالصواب: ما عليه خطوط مصاحف المسلمين متفقة، وإن اختلفت قراءتهم به، وذلك ﴿بِضَنِينٍ﴾ بالضاد، لأن ذلك كله كذلك في خطوطها. فإذا كان ذلك كذلك، فأولى التأويلين بالصواب في ذلك: تأويل من تأوّله، وما محمد على ما علَّمه الله من وحيه وتنزيله ببخيل بتعليمكموه أيها الناس، بل هو حريص على أن تؤمنوا به وتتعلَّموه.\n\n* *\n\nوقوله: ﴿وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَجِيمٍ﴾\n\nيقول تعالى ذكره: وما هذا القرآن بقول شيطان ملعون مطرود، ولكنه كلام الله ووحيه.\n\n* *\n\nوقوله: ﴿فَأَيْنَ تَذْهَبُونَ﴾ ؟\n\nيقول تعالى ذكره: فأين تذهبون عن هذا القرآن وتعدلون عنه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَأَيْنَ تَذْهَبُونَ﴾ يقول: فأين تعدلون عن كتابي وطاعتي. وقيل: ﴿فَأَيْنَ تَذْهَبُونَ﴾ ولم يقل: فإلى أين تذهبون، كما يقال: ذهبت الشأم وذهبت السوق. وحُكي عن العرب سماعا: انطلق به الغَوْرَ، على معنى إلغاء الصفة، وقد ينشد لبعض بني عُقَيل:\n\nتَصِيحُ بِنا حَنِيفةُ إذْ رأتْنا ... وأيَّ الأرْضِ تَذْهَبُ للصَّياح\n\nبمعنى: إلى أيّ الأرض تذهب واستجيز إلغاء الصفة في ذلك للاستعمال.","22":21,"23":21,"24":21,"25":21,"26":21,"27":"القول في تأويل قوله تعالى: ﴿إِنْ هُوَ إِلا ذِكْرٌ لِلْعَالَمِينَ (٢٧) لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ (٢٨) وَمَا تَشَاءُونَ إِلا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ (٢٩) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿إنْ﴾ هذا القرآن، وقوله: ﴿هُوَ﴾ من ذكر القرآن ﴿إِلا ذِكْرٌ لِلْعَالَمِينَ﴾ يقول: إلا تذكرة وعظة للعالمين من الجنّ والإنس ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ فجعل ذلك تعالى ذكره ذكرا لمن شاء من العالمين أن يستقيم، ولم يجعله ذكرا لجميعهم، فاللام في قوله: ﴿لِمَنْ شَاءَ مِنْكُمْ﴾ إبدال من اللام في للعالمين. وكان معنى الكلام: إن هو إلا ذكر لمن شاء منكم أن يستقيم على سبيل الحقّ فيتبعه، ويؤمن به.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ قال: يتبع الحقّ.\n\n* *\n\nوقوله: ﴿وَمَا تَشَاءُونَ إِلا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ﴾\n\nيقول تعالى ذكره: وما تشاءون أيها الناس الاستقامة على الحقّ، إلا أن يشاء الله ذلك.\n\nوذكر أن السبب الذي من أجله نزلت هذه الآية، ما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سعيد بن عبد العزيز، عن سليمان بن موسى لما نزلت ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ قال أبو جهل ذلك إلينا، إن شئنا استقمنا، فنزلت: ﴿وَمَا تَشَاءُونَ إِلا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ﴾ .\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن سعيد بن عبد العزيز، عن سليمان بن موسى، قال: لما نزلت هذه الآية ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ قال أبو جهل: الأمر إلينا، إن شئنا استقمنا، وإن شئنا لم نستقم، فأنزل الله: ﴿وَمَا تَشَاءُونَ إِلا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ﴾ .\n\n⁕ حدثني ابن البرقي، قال: ثنا عمرو بن أبي سلمة، عن سعيد، عن سليمان بن موسى، قال: لما نزلت هذه الآية: ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ قال أبو جهل: ذلك إلينا، إن شئنا استقمنا، وإن شئنا لم نستقم، فأنزل الله: ﴿وَمَا تَشَاءُونَ إِلا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ﴾ .\n\nآخر تفسير سورة ﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾","28":27,"29":27},"82":{"1":"القول في تأويل قوله تعالى: ﴿إِذَا السَّمَاءُ انْفَطَرَتْ (١) وَإِذَا الْكَوَاكِبُ انْتَثَرَتْ (٢) وَإِذَا الْبِحَارُ فُجِّرَتْ (٣) وَإِذَا الْقُبُورُ بُعْثِرَتْ (٤) عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ (٥) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿إِذَا السَّمَاءُ انْفَطَرَتْ﴾ انشقَّت، وإذا كواكبها انتثرت منها فتساقطت، ﴿وَإِذَا الْبِحَارُ فُجِّرَتْ﴾ يقول: فجَّر بعضها في بعض، فملأ جميعها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في بعض ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَإِذَا الْبِحَارُ فُجِّرَتْ﴾ يقول: بعضها في بعض.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَإِذَا الْبِحَارُ فُجِّرَتْ﴾ فُجِّر عذبها في مالحها، ومالحها في عذبها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَإِذَا الْبِحَارُ فُجِّرَتْ﴾ قال: فجِّر بعضها في بعض، فذهب ماؤها. وقال الكلبي: ملئت.\n\n* *\n\nوقوله: ﴿وَإِذَا الْقُبُورُ بُعْثِرَتْ﴾\n\nيقول: وإذا القبور أُثيرت فاستخرج من فيها من الموتى أحياء، يقال: بعثر فلان حوض فلان: إذا جعل أسفله أعلاه، يقال: بعثرة وبحثرة: لغتان.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَإِذَا الْقُبُورُ بُعْثِرَتْ﴾ يقول: بُحثت.\n\n* *\n\nوقوله: ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾\n\nيقول تعالى ذكره: علمت كلّ نفس ما قدّمت لذلك اليوم من عمل صالح ينفعه، وأخرت وراءه من شيء سنَّه فعمل به.\n\nواختلف أهل التأويل في تأويل ذلك، فقال بعضهم بنحو الذي قلنا في ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر بن سليمان، عن أبيه، قال: ثني عن القُرَظي، أنه قال في: ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: ما قدّمت مما عملت، وأما ما أخَّرت فالسنة يَسُنها الرجل يُعمل بها من بعده.\n\nوقال آخرون: عُني بذلك ما قدّمت من الفرائض التي أدتها، وما أخَّرت من الفرائض التي ضيعتها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبيه، عن سعيد بن مسروق، عن عكرِمة ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ﴾ قال: ما افترض عليها ﴿وَأَخَّرَتْ﴾ قال: مما افترض عليها.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: تعلم ما قدّمت من طاعة الله، وما أخرت مما أُمِرَت به من حقّ لله عليه لم تعمل به.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: ما قدّمت من خير، وأخَّرت من حق الله عليها لم تعمل به.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، ﴿مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: ما قدمت من طاعة الله وما أخرت من حق الله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: ما قدّمت: عملت، وما أخرت: تركت وضيَّعت، وأخرت من العمل الصالح الذي دعاها الله إليه.\n\nوقال آخرون: بل معنى ذلك: ما قدّمت من خير أو شرّ، وأخَّرت من خير أو شرّ.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا العوّام، عن إبراهيم التيمي، قال: ذكروا عنده هذه الآية ﴿عَلِمَتْ نَفْسٌ مَا قَدَّمَتْ وَأَخَّرَتْ﴾ قال: أنا مما أخَّرَ الحجاج.\n\nوإنما اخترنا القول الذي ذكرناه، لأن كلّ ما عمل العبد من خير أو شرّ فهو مما قدّمه، وأن ما ضيَّع من حقّ الله عليه وفرّط فيه فلم يعمله، فهو مما قد قدّم من شرّ، وليس ذلك مما أخَّر من العمل، لأن العمل هو ما عمله. فأما ما لم يعمله فإنما هو سيئة قدّمها، فلذلك قلنا: ما أخر: هو ما سنه من سنة حسنة وسيئة، مما إذا عمل به العامل، كان له مثل أجر العامل بها أو وزره.","2":1,"3":1,"4":1,"5":1,"6":"القول في تأويل قوله تعالى: ﴿يَا أَيُّهَا الإنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ (٦) الَّذِي خَلَقَكَ فَسَوَّاكَ فَعَدَلَكَ (٧) فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ (٨) ﴾\n\n.\n\nيقول تعالى ذكره: يا أيها الإنسان الكافر، أيّ شيء غرّك بربك الكريم، غرّ الإنسانَ به عدوُّه المسلَّط عليه.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ﴾ شيء ما غرّ ابن آدم هذا العدوّ الشيطان.\n\n* *\n\nوقوله: ﴿الَّذِي خَلَقَكَ فَسَوَّاكَ﴾\n\nيقول: الذي خلقك أيها الإنسان فسوّى خلقك ﴿فَعَدَلَكَ﴾ واختلفت القرَّاء في قراءة ذلك، فقرأته عامة قرَّاء المدينة ومكة والشام والبصرة ﴿فعدّلك﴾ بتشديد الدال، وقرأ ذلك عامة قرّاء الكوفة بتخفيفها، وكأن من قرأ ذلك بالتشديد وجَّه معنى الكلام إلى أنه جعلك معتدلا معدّل الخلق مقوَّما، وكأن الذين قرءوه بالتخفيف، وجَّهوا معنى الكلام إلى صرفك وأمالك إلى أيّ صورة شاء، إما إلى صورة حسنة، وإما إلى صورة قبيحة، أو إلى صورة بعض قراباته.\n\nوأولى الأقوال في ذلك عندي بالصواب أن يقال: إنهما قراءتان معروفتان في قراءة الأمصار صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب، غير أن أعجبهما إليّ أن أقرأ به قراءة من قَرَأ ذلك بالتشديد، لأن دخول\" في\" للتعديل أحسن في العربية من دخولها للعدل، ألا ترى أنك تقول: عدّلتك في كذا، وصرفتك إليه، ولا تكاد تقول: عدلتك إلى كذا وصرفتك فيه، فلذلك اخترت التشديد.\n\nوبنحو الذي قلنا في ذلك وذكرنا أن قارئي ذلك تأوّلوه، جاءت الرواية عن أهل التأويل أنهم قالوه.\n\nذكر الرواية بذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ﴾ قال: في أيّ شبه أب أو أم أو خال أو عمّ.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن إسماعيل، في قوله: ﴿مَا شَاءَ رَكَّبَكَ﴾ قال: إن شاء في صورة كلب، وإن شاء في صورة حمار.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل، عن أبي صالح ﴿فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ﴾ قال: خنزيرا أو حماوا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، عن عكرِمة، في قوله: ﴿فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ﴾ قال: إن شاء في صورة قرد، وإن شاء في صورة خنزير.\n\n⁕ حدثني محمد بن سنان القزّاز، قال: ثنا مطهر بن الهيثم، قال: ثنا موسى بن عليّ بن أبي رباح اللَّخمي، قال: ثني أبي، عن جدي، أن النبيّ ﷺ قال له: \" ما وُلِدَ لَك؟ \" قال: يا رسول الله ما عسَى أن يولد لي، إما غلام، وإما جارية، قال: \"فَمَن يُشْبِهُ؟ \" قال: يا رسول الله من عسى أن يشبه؟ إما أباه، وإما أمه؛ فقال النبيّ ﷺ عندها: \"مَهْ، لا تَقُولَنَّ هَكَذَا، إنَّ النُّطْفَةَ إذَا اسْتَقَرَّتْ فِي الرَّحِمِ أحْضَرَ اللهُ كُلَّ نَسَبٍ بَيْنَها وَبَينَ آدَمَ، أما قَرأْتَ هَذِهِ الآيَةَ فِي كتاب الله ﴿فِي أَيِّ صُورَةٍ مَا شَاءَ رَكَّبَكَ﴾ قال: سَلَكَكَ \".","7":6,"8":6,"9":"القول في تأويل قوله تعالى: ﴿كَلا بَلْ تُكَذِّبُونَ بِالدِّينِ (٩) وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ (١٠) كِرَامًا كَاتِبِينَ (١١) يَعْلَمُونَ مَا تَفْعَلُونَ (١٢) إِنَّ الأبْرَارَ لَفِي نَعِيمٍ (١٣) ﴾\n\n.\n\nيقول تعالى ذكره: ليس الأمر أيها الكافرون كما تقولون من أنكم على الحقّ في عبادتكم غير الله، ولكنكم تكذّبون بالثواب والعقاب، والجزاء والحساب.\n\nوبنحو الذي قلنا في معنى قوله: ﴿بَلْ تُكَذِّبُونَ بِالدِّينِ﴾ قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿بَلْ تُكَذِّبُونَ بِالدِّينِ﴾ قال: بالحساب.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد: ﴿تُكَذِّبُونَ بِالدِّينِ﴾ قال: بيوم الحساب.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قوله: ﴿بَلْ تُكَذِّبُونَ بِالدِّينِ﴾ قال: يوم شدّة، يوم يدين الله العباد بأعمالهم.\n\n* *\n\nوقوله: ﴿وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ﴾\n\nيقول: وإن عليكم رُقَباء حافظين يحفظون أعمالكم، ويُحْصونها عليكم ﴿كِرَامًا كَاتِبِينَ﴾ يقول: كراما على الله كاتبين يكتبون أعمالكم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: قال بعض أصحابنا، عن أيوب، في قوله: ﴿وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ كِرَامًا كَاتِبِينَ﴾ قال: يكتبون ما تقولون وما تَعْنُون.\n\n* *\n\nوقوله: ﴿يَعْلَمُونَ مَا تَفْعَلُونَ﴾\n\nيقول: يعلم هؤلاء الحافظون ما تفعلون من خير أو شرّ، يحصون ذلك عليكم.\n\n* *\n\nوقوله: ﴿إِنَّ الأبْرَارَ لَفِي نَعِيمٍ﴾\n\nيقول جل ثناؤه: إن الذين برّوا بأداء فرائض الله، واجتنابِ معاصيه لفي نعيم الجنان ينعمون فيها.","10":9,"11":9,"12":9,"13":9,"14":"القول في تأويل قوله تعالى: ﴿وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ (١٤) يَصْلَوْنَهَا يَوْمَ الدِّينِ (١٥) وَمَا هُمْ عَنْهَا بِغَائِبِينَ (١٦) وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ (١٧) ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ (١٨) يَوْمَ لا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا وَالأمْرُ يَوْمَئِذٍ لِلَّهِ (١٩) ﴾ .\n\nيقول تعالى ذكره: ﴿وَإِنَّ الْفُجَّارَ﴾ الذين كفروا بربهم ﴿لَفِي جَحِيمٍ﴾ .\n\n* *\n\nوقوله: ﴿يَصْلَوْنَهَا يَوْمَ الدِّينِ﴾\n\nيقول جلّ ثناؤه: يَصْلَى هؤلاء الفجار الجحيم يوم القيامة، يوم يُدان العباد بالأعمال، فيُجازَوْنَ بها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿يَوْمَ الدينِ﴾ من أسماء يوم القيامة، عظَّمه الله، وحذَّره عباده.\n\n* *\n\nوقوله: ﴿وَمَا هُمْ عَنْهَا بِغَائِبِينَ﴾\n\nيقول تعالى ذكره: وما هؤلاء الفجار من الجحيم بخارجين أبدا، فغائبين عنها، ولكنهم فيها مخلَّدون ماكثون، وكذلك الأبرار في النعيم، وذلك نحو قوله: ﴿وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ﴾ .\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: وما أدراك يا محمد، أيّ وما أشعرك ما يوم الدين؟ يقول: أيُّ شيء يوم الحساب والمجازاة، معظما شأنه جلّ ذكره، بقيله ذلك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ﴾ تعظيما ليوم القيامة، يوم تدان فيه الناس بأعمالهم.\n\n* *\n\nوقوله: ﴿ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ﴾\n\nيقول: ثم أيّ شيء أشعرك يوم المجازاة والحساب يا محمد، تعظيما لأمره، ثم فسَّر جلّ ثناؤه بعض شأنه فقال: ﴿يَوْمَ لا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا﴾ يقول: ذلك اليوم، ﴿يَوْمَ لا تَمْلِكُ نَفْسٌ﴾ يقول: يوم لا تُغني نفس عن نفس شيئا، فتدفع عنها بليَّة نزلت بها، ولا تنفعها بنافعة، وقد كانت في الدنيا تحميها، وتدفع عنها من بغاها سوءا، فبطل ذلك يومئذ، لأن الأمر صار لله الذي لا يغلبه غالب، ولا يقهره قاهر، واضمحلت هنالك الممالك، وذهبت الرياسات، وحصل الملك للملك الجبار، وذلك قوله: ﴿وَالأمْرُ يَوْمَئِذٍ لِلَّهِ﴾ يقول: والأمر كله يومئذ، يعني: الدين لله دون سائر خلقه، ليس لأحد من خلقه معه يومئذ أمر ولا نهي.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَالأمْرُ يَوْمَئِذٍ لِلَّهِ﴾ قال: ليس ثم أحد يومئذ يقضي شيئا، ولا يصنع شيئا إلا ربّ العالمين.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَوْمَ لا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا وَالأمْرُ يَوْمَئِذٍ لِلَّهِ﴾ والأمر والله اليوم لله، ولكنه يومئذ لا ينازعه أحد.\n\nواختلفت القرّاء في قراءة قوله: ﴿يَوْمَ لا تَمْلِكُ نَفْسٌ﴾ فقرأته عامة قرّاء الحجاز والكوفة بنصب ﴿يَوْمَ﴾ إذ كانت إضافته غير محضة. وقرأه بعض قرّاء البصرة بضم ﴿يَوْمُ﴾ ورفعه ردّا على اليوم الأوّل، والرفع فيه أفصح في كلام العرب، وذلك أن اليوم مضاف إلى يفعل، والعرب إذا أضافت اليوم إلى تفعل أو يفعل أو أفعل، رفعوه فقالوا: هذا يوم أفعل كذا، وإذا أضافته إلى فعل ماض نصبوه؛ ومنه قول الشاعر:\n\nعَلى حِينَ عاتَبْتُ المَشِيبَ عَلى الصِّبا ... وَقُلْتُ ألَمَّا تَصْحُ والشَّيْبُ وَازِعُ\n\nآخر تفسير سورة ﴿إذا السماء انفطرت﴾ .","15":14,"16":14,"17":14,"18":14,"19":14},"83":{"1":"القول في تأويل قوله تعالى: ﴿وَيْلٌ لِلْمُطَفِّفِينَ (١) الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ (٢) وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ (٣) أَلا يَظُنُّ أُولَئِكَ أَنَّهُمْ مَبْعُوثُونَ (٤) لِيَوْمٍ عَظِيمٍ (٥) يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ (٦) ﴾\n\n.\n\nيقول تعالى ذكره: الوادي الذي يسيل من صديد أهل جهنم في أسفلها للذين يُطَففون، يعني: للذين ينقصون الناس، ويبخسونهم حقوقهم في مكاييلهم إذا كالوهم، أو موازينهم إذا وزنوا لهم عن الواجب لهم من الوفاء، وأصل ذلك من الشيء الطفيف، وهو القليل النزر، والمطفِّف: المقلِّل حقّ صاحب الحقّ عما له من الوفاء والتمام في كيل أو وزن؛ ومنه قيل للقوم الذي يكونون سواء في حسبة أو عدد: هم سواء كطَفّ الصاع، يعني بذلك: كقرب الممتلئ منه ناقص عن الملء.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني أبو السائب، قال: ثنا ابن فضيل، عن ضِرار، عن عبد الله، قال: قال له رجل: يا أبا عبد الرحمن إن أهل المدينة ليوفون الكيل، قال: وما يمنعهم من أن يوفوا الكيل، وقد قال الله: ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ حتى بلغ: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين بن واقد، عن يزيد، عن عكرمة، عن ابن عباس قال: \" لما قَدِم النبيّ ﷺ المدينة، كانوا من أخبث الناس كيلا فأنزل الله: ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ فأحسنوا الكيل \".\n\n⁕ حدثني محمد بن خالد بن خداش، قال: ثنا سلم بن قتيبة، عن قسام الصيرفي، عن عكرمة قال: أشهد أن كلّ كيال ووزّان في النار، فقيل له في ذلك، فقال: إنه ليس منهم أحد يزن كما يتزن  ولا يكيل كما يكتال، وقد قال الله: ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ .\n\n* *\n\nوقوله: ﴿الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ﴾\n\nيقول تعالى ذكره: الذين إذا اكتالوا من الناس ما لهم قبلهم من حقّ، يستوفون لأنفسهم فيكتالونه منهم وافيا، و \"على\" و \"مِن\" في هذا الموضع يتعاقبان غير أنه إذا قيل: اكتلت منك، يراد: استوفيت منك.\n\n* *\n\nوقوله: ﴿وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ﴾\n\nيقول: وإذا هم كالوا للناس أو وزنوا لهم. ومن لغة أهل الحجاز أن يقولوا: وزنتك حقك، وكلتك طعامك، بمعنى: وزنت لك وكلت لك. ومن وجَّه الكلام إلى هذا المعنى جعل الوقف على \"هم\"، وجعل \"هم\" في موضع نصب. وكان عيسى بن عمر فيما ذُكر عنه يجعلهما حرفين، ويقف على كالوا، وعلى وزنوا، ثم يبتدئ هم يخسرون. فمن وجَّه الكلام إلى هذا المعنى جعل \"هم\" في موضع رفع، وجعل كالوا ووزنوا مكتفيين بأنفسهما.\n\nوالصواب في ذلك عندي الوقف على \"هم\"، لأن كالوا ووزنوا لو كانا مكتفيين، وكانت هم كلاما مستأنفا، كانت كتابة كالوا ووزنوا بألف فاصلة بينها وبين هم مع كل واحد منهما، إذ كان بذلك جرى الكتاب في نظائر ذلك إذا لم يكن متصلا به شيء من كنايات المفعول، فكتابهم ذلك في هذا الموضع بغير ألف أوضح الدليل على أن قوله: ﴿هُمْ﴾ إنما هو كناية أسماء المفعول بهم. فتأويل الكلام إذ كان الأمر على ما وصفنا على ما بيَّنا.\n\n* *\n\nوقوله: ﴿يُخْسِرُونَ﴾\n\nيقول: ينقصونهم.\n\n* *\n\nوقوله: ﴿أَلا يَظُنُّ أُولَئِكَ أَنَّهُمْ مَبْعُوثُونَ لِيَوْمٍ عَظِيمٍ﴾\n\nيقول تعالى ذكره: ألا يظنّ هؤلاء المطففون الناس في مكاييلهم وموازينهم أنهم مبعوثون من قبورهم بعد مماتهم ليوم عظيم شأنه: هائل أمره، فظيع هوله.\n\n* *\n\nوقوله: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾\n\nفيوم يقوم تفسير عن اليوم الأول المخفوض، ولكنه لما لم يعد عليه اللام ردّ إلى \"مبعوثون\"، فكأنه قال: ألا يظنّ أولئك أنهم مبعوثون يوم يقوم الناس وقد يجوز نصبه وهو بمعنى الخفض، لأنها إضافة غير محضة، ولو خفض ردّا على اليوم الأوّل لم يكن لحنا، ولو رفع جاز، كما قال الشاعر:\n\nوكُنتُ كَذي رِجْلَينِ: رِجلٍ صَحِيحةٍ ... وَرِجْلٍ رمَى فِيها الزَّمان فشُلَّتِ\n\nوذُكر أن الناس يقومون لربّ العالمين يوم القيامة حتى يلجمهم العرق، فبعض يقول: مقدار ثلثمائة عام، وبعض يقول: مقدار أربعين عاما.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ بن سعيد الكنديّ، قال: ثنا عيسى بن يونس، عن ابن عون، عن نافع، عن ابن عمر، عن النبيّ ﷺ، في قوله: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يقوم أحدكم في رشحه إلى أنصاف أذنيه.\n\n⁕ حدثنا ابن وكيع، قال: ثنا أبو خالد الأحمر، عن ابن عون، عن نافع، عن ابن عمر، عن النبيّ ﷺ \" ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يغيب أحدهم في رشحه إلى أنصاف أذنيه \".\n\n⁕ حدثنا حميد بن مسعدة، قال: ثنا يزيد بن زريع، قال: ثنا ابن عون، عن نافع، قال: قال ابن عمر: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ حتى يقوم أحدهم في رشحه إلى أنصاف أذنيه.\n\n⁕ حدثنا ابن وكيع، قال: ثنا جرير، عن محمد بن إسحاق، عن نافع، عن ابن عمر، قال: قال النبيّ ﷺ: \"إنَّ النَّاس يُوقَفُون يَوْمَ الْقِيامَةِ لِعَظَمَةِ اللهِ، حتى إنَّ الْعَرَقَ لَيُلْجِمُهُمْ إلى أنْصَافِ آذَانِهِمْ\".\n\n⁕ حدثنا ابن وكيع، قال: ثنا يونس بن بكير، عن محمد بن إسحاق، عن نافع، عن ابن عمر، قال: سمعت النبيّ ﷺ يقول: \" ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ يَوْم الْقِيامَةِ لِعَظَمَة الرَّحْمَنِ\"، ثم ذكر مثله.\n\n⁕ حدثني محمد بن خلف العسقلاني، قال: ثنا آدم، قال: ثنا حماد بن سلمة، عن أيوب، عن نافع عن ابن عمر قال: \" تلا رسول الله ﷺ هذه الآية ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يَقُومُونَ حتى يَبْلُغَ الرَّشْحُ إلى أنْصَاف آذانِهِمْ \".\n\n⁕ حدثنا أحمد بن محمد بن حبيب، قال: ثنا يعقوب بن إبراهيم، قال: ثنا أبي، عن صالح، قال: ثنا نافع، عن ابن عمر، قال: قال رسول الله ﷺ: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ يَوْمَ الْقِيامَةِ، حتى يَغِيبَ أحَدُهُمْ إلى أنصَافِ أذُنَيْهِ فِي رَشْحِهِ\".\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عنبسة بن سعيد، عن محارب بن دثار، عن ابن عمر، في قوله: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يقومون مئة سنة.\n\n⁕ حدثنا تميم بن المنتصر، قال: أخبرنا يزيد، قال: أخبرنا محمد بن إسحاق، عن نافع، عن ابن عمر، عن النبيّ ﷺ، قال: سمعت النبيّ ﷺ يقول: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ يَوْمَ الْقِيامَةِ، حتَّى إنَّ الْعَرَقَ لَيُلْجِمُ الرجل إلى أنْصَافِ أُذُنَيْهِ\".\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، عن محمد بن إسحاق، عن نافع، عن ابن عمر، عن النبيّ ﷺ، بنحوه.\n\n⁕ حدثنا ابن المثنى وابن وكيع، قالا ثنا يحيى، عن عبد الله، عن نافع، عن ابن عمر، عن النبيّ ﷺ قال: \"يَقُومُ النَّاسُ لِربّ الْعالمِين حتى يَقُومَ أحَدُهُمْ فِي رَشْحِهِ إلى أنْصَافِ أُذُنَيْهِ\".\n\n⁕ حدثني محمد بن إبراهيم السليمي المعروف بابن صدران، قال: ثنا يعقوب بن إسحاق قال: ثنا عبد السلام بن عجلان، قال: ثنا يزيد المدني، عن أبي هريرة، أن رسول الله ﷺ قال لبشير الغفاري: \"كَيْفَ أنْتَ صَانِعٌ فِي: يَوْمَ يَقُومُ النَّاسُ لِربّ الْعَالمِين مِقْدَارَ ثَلثِمائَةِ سَنَةٍ مِنْ أيَّامِ الدُّنْيا، لا يأتِيُهْم خَبرٌ مِنَ السَّماءِ، وَلا يُؤْمَرُ فِيهِمْ بأمْر\"، قال بشير: المستعان الله يا رسول الله، قال: \"إذَا أنْتَ أوَيْتَ إلى فِراشِكَ فَتَعَوَّذْ بالله مِنْ كُرَب يَوْمِ القِيامَة، وَسُوءِ الْحِساب\".\n\n⁕ حدثني يحيى بن طلحة اليربوعي، قال: ثنا شريك، عن الأعمش، عن المنهال بن عمرو، عن عبد الله بن مسعود، في قوله: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يمكثون أربعين عاما رافعي رءوسهم إلى السماء، لا يكلمهم أحد، قد ألجم العرق كلّ برّ وفاجر، قال: فينادي مناد: أليس عدلا من ربكم أن خلقكم ثم صوّركم، ثم رزقكم، ثم توليتم غيره أن يولي كلّ عبد منكم ما تولى في الدنيا؟ قالوا: بلى، ثم ذكر الحديث بطوله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا أبو بكر، عن الأعمش، عن المنهال بن عمرو، عن قيس بن سكن، قال: حدث عبد الله، وهو عند عمر ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: إذا كان يوم القيامة يقوم الناس بين يدي ربّ العالمين أربعين عاما، شاخصة أبصارهم إلى السماء حفاة عراة يلجمهم العرق، ولا يكلّمهم بشر أربعين عاما، ثم ذكر نحوه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: ذُكر لنا أن كعبا كان يقول: يقومون ثلثمائة سنة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران وسعيد، عن قتادة ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: كان كعب يقول: يقومون مقدار ثلثمائة سنة.\n\nقال: قتادة: وحدثنا العلاء بن زياد العدويّ، قال: بلغني أن يوم القيامة يقصر على المومن حتى يكون كإحدى صلاته المكتوبة.\n\n⁕ قال: ثنا مهران، قال: ثنا العمريّ، عن نافع، عن ابن عمر، قال: سمعت النبيّ ﷺ يقول: ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ قال: يَقُومُ الرَّجُلُ فِي رَشْحِهِ إلى أنْصَافِ أُذُنَيهِ\".\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن ابن عون، عن نافع، عن ابن عمر، قال: \" ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ حتى يقوم أحدهم في رشحه إلى أنصاف أذنيه.\n\nقال يعقوب، قال إسماعيل: قلت لابن عون: ذكر النبيّ ﷺ في هذا الحديث قال: \" نَعَمْ إنْ شاءَ اللهُ \".\n\n⁕ حدثنا أحمد بن عبد الرحمن، قال: ثني عمي، قال: أخبرني مالك بن أنس، عن نافع، عن ابن عمر، أن النبيّ ﷺ قال: \"يَقُومُ النَّاسُ لِربّ الْعَالمِين، حتى إنَّ أحَدَهُمْ لَيَغِيبُ فِي رَشْحِهِ إلى نِصْف أُذُنَيْهِ\".","2":1,"3":1,"4":1,"5":1,"6":1,"7":"القول في تأويل قوله تعالى: ﴿كَلا إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ (٧) وَمَا أَدْرَاكَ مَا سِجِّينٌ (٨) كِتَابٌ مَرْقُومٌ (٩) وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (١٠) الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ (١١) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿كَلا﴾ ، أي ليس الأمر كما يظنّ هؤلاء الكفار، أنهم غير مبعوثين ولا معذّبين، إن كتابهم الذي كتب فيه أعمالهم التي كانوا يعملونها في الدنيا ﴿لَفِي سِجِّينٍ﴾ وهي الأرض السابعة السفلى، وهو \"فعيل\" من السجن، كما قيل: رجل سِكِّير من السكر، وفِسيق من الفسق.\n\nوقد اختلف أهل التأويل في معنى ذلك، فقال بعضهم: مثل الذي قلنا في ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو أحمد، قال: ثنا سفيان، عن منصور، عن مجاهد، عن مغيث بن سميّ: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ قال: في الأرض السابعة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، عن مغيث بن سميّ، قال: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ قال: الأرض السفلى، قال: إبليس مُوثَق بالحديد والسلاسل في الأرض السفلى.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني جرير بن حازم، عن سليمان الأعمش، عن شمر بن عطية، عن هلال بن يساف، قال: كنا جلوسا إلى كعب أنا وربيع بن خيثم وخالد بن عُرْعرة، ورهط من أصحابنا، فأقبل ابن عباس، فجلس إلى جنب كعب، فقال: يا كعب أخبرني عن سِجِّين، فقال كعب: أما سجِّين: فإنها الأرض السابعة السفلى، وفيها أرواح الكفار تحت حدّ إبليس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ ذُكر أن عبد الله بن عمرو كان يقول: هي الأرض السفلى فيها أرواح الكفار، وأعمالهم أعمال السوء.\n\n⁕ حدثنا ابن عبد الأ٢٤-٢٨٣على، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فِي سِجِّينٍ﴾ قال: في أسفل الأرض السابعة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ يقول: أعمالهم في كتاب في الأرض السفلى.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿لَفِي سِجِّينٍ﴾ قال: عملهم في الأرض السابعة لا يصعد.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثني عمر بن إسماعيل بن مجالد، قال: ثنا مطرِّف بن مازن قاضي اليمن، عن معمر، عن قتادة قال: ﴿سِجِّينٍ﴾ الأرض السابعة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿لَفِي سِجِّينٍ﴾ يقول: في الأرض السفلى.\n\n⁕ حدثنا ابن بشار، قال: ثنا سليمان، قال: ثنا أبو هلال، قال: ثنا قتادة، في قوله: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ قال: الأرض السابعة السفلي.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كَلا إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ قال: يقال سجين: الأرض السافلة، وسجين: بالسماء الدنيا.\n\nوقال آخرون: بل ذلك حدّ إبليس.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القُمِّي، عن حفص بن حميد، عن شمر، قال: جاء ابن عباس إلى كعب الأحبار، فقال له ابن عباس: حدِّثني عن قول الله: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ ... ﴾ الآية، قال كعب: إن روح الفاجر يصعد بها إلى السماء، فتأبى السماء أن تقبلها، ويُهبط بها إلى الأرض فتأبى الأرض أن تقبلها، فتهبط فتد٢٤-٢٨٤خل تحت سبع أرضين، حتى ينتهي بها إلى سجين، وهو حدّ إبليس، فيخرج لها من سجين من تحت حدّ إبليس، رَقّ فيرقم ويختم ويوضع تحت حدّ إبليس بمعرفتها الهلاك إلى يوم القيامة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ قال: تحت حدّ إبليس.\n\nوقال آخرون: هو جبّ في جهنم مفتوح، ورووا في ذلك خبرا عن رسول الله ﷺ.\n\n⁕ حدثنا به إسحاق بن وهب الواسطي، قال: ثنا مسعود بن مسكان الواسطي، قال: ثنا نضر بن خُزيمة الواسطي، عن شعيب بن صفوان، عن محمد بن كعب القرظي، عن أبي هريرة، أن رسول الله ﷺ قال: \"الفَلَقُ جُبّ فِي جَهَنَّمَ مُغَطًّى، وأما سِجِّينٌ فمَفْتُوحٌ\".\n\nوقال بعض أهل العربية: ذكروا أن سجين: الصخرة التي تحت الأرض، قال: ويُرَى أن سجين صفة من صفاتها، لأنه لو كان لها اسما لم يجر، قال: وإن قلت: أجريته لأني ذهبت بالصخرة إلى أنها الحجر الذي فيه الكتاب كان وجها.\n\nوإنما اخترت القول الذي اخترت في معنى قوله: ﴿سِجِّينٍ﴾ لما:-\n\n⁕ حدثنا ابن وكيع، قال: ثنا ابن نمير، قال: ثنا الأعمش، قال: ثنا المنهال بن عمرو، عن زاذان أبي عمرو، عن البراء، قال: ﴿سِجِّينٍ﴾ الأرض السفلى.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا أبو بكر، عن الأعمش، عن المنهال، عن زاذان، عن البراء، أن رسول الله ﷺ، قال: وذكر نفس الفاجر، وأنَّهُ يُصعَدُ بها إلى السَّماء، قال: \" فَيَصْعَدُون بها فَلا يمُرُّونَ بِها عَلى مَلإ مِنَ المَلائِكَة إلا قالُوا: ما هَذَا الرُّوحُ الخَبِيثُ؟ قال: فَيَقُولُونَ: فُلانٌ بأقْبَحِ أسمَائِهِ التي كان يُسَمَّى بها في الدنيا حتى يَنْتَهوا بِهَا إلى السَّماء الدُّنْيا، فيَسْتَفْتِحُونَ لَهُ. فَلا يُفْتَحُ لَهُ، ثم قرأ رسول الله ﷺ: \" ﴿لا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ﴾ فَيَقُولُ اللهُ: اكْتُبُوا كِتَابَهُ فِي أسْفَلِ الأرْضِ فِي سجِّينٍ فِي الأرْضِ السُّفْلَى\".\n\n⁕ حدثنا نصر بن عليّ، قال: ثنا يحيى بن سليم، قال: ثنا ابن أبي نجيح، عن مجاهد، في قوله: (٢٤-٢٨٥ كَلا إِنَّ كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ) قال: سجين: صخرة في الأرض السابعة، فيجعل كتاب الفجار تحتها.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا سِجِّينٌ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: وأيّ شيء أدراك يا محمد، أيّ شيء ذلك الكتاب، ثم بين ذلك تعالى ذكره، فقال: هو ﴿كِتَابٌ مَرْقُومٌ﴾ وعنى بالمرقوم: المكتوب.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة فِي ﴿كِتَابٌ مَرْقُومٌ﴾ قال: كتاب مكتوب.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَمَا أَدْرَاكَ مَا سِجِّينٌ كِتَابٌ مَرْقُومٌ﴾ قال: رقم لهم بشرٍّ.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كِتَابٌ مَرْقُومٌ﴾ قال: المرقوم: المكتوب.\n\n* *\n\nوقوله: ﴿وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾\n\nيقول تعالى ذكره: ويل يومئذ للمكذبين بهذه الآيات، ﴿الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ﴾ ، يقول: الذين يكذبون بيوم الحساب والمجازاة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿الَّذِينَ يُكَذِّبُونَ بِيَوْمِ الدِّينِ﴾ قال: أهل الشرك يكذّبون بالدين، وقرأ: ﴿وَقَالَ الَّذِينَ كَفَرُوا هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ يُنَبِّئُكُمْ ... ﴾ إلى آخر الآية.","8":7,"9":7,"10":7,"11":7,"12":"القول في تأويل قوله تعالى: ﴿وَمَا يُكَذِّبُ بِهِ إِلا كُلُّ مُعْتَدٍ أَثِيمٍ (١٢) إِذَا تُتْلَى عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الأوَّلِينَ (١٣) كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ (١٤) ﴾\n\n.\n\nيقول تعالى ذكره: وما يُكذّبُ بيوم الدين ﴿إِلا كُلُّ مُعْتَدٍ﴾ اعتدى على الله في قوله، فخالف أمره ﴿أثِيمٍ﴾ بربه.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾ قال الله: ﴿وَمَا يُكَذِّبُ بِهِ إِلا كُلُّ مُعْتَدٍ أَثِيمٍ﴾ أي بيوم الدين، إلا كلّ معتد في قوله، أثيم بربه، ﴿إِذَا تُتْلَى عَلَيْهِ آيَاتُنَا﴾ يقول تعالى ذكره: إذا قُرئ عليه حججنا وأدلتنا التي بيَّنَاها في كتابنا الذي أنزلناه إلى محمد ﷺ ﴿قَالَ أَسَاطِيرُ الأوَّلِينَ﴾ يقول: قال: هذا ما سطَّره الأوّلون فكتبوه، من الأحاديث والأخبار.\n\n* *\n\nوقوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾\n\nيقول تعالى ذكره مكذّبا لهم في قيلهم ذلك: ﴿كَلا﴾ ، ما ذلك كذلك، ولكنه ﴿رَانَ عَلَى قُلُوبِهِمْ﴾ . يقول: غلب على قلوبهم وغَمَرها وأحاطت بها الذنوب فغطتها، يقال منه: رانت الخمر على عقله، فهي تَرِين عليه رَيْنا، وذلك إذا سكر، فغلبت على عقله؛ ومنه قول أبي زُبيد الطائي:\n\nثُمَّ لَمَّا رآهُ رَانَتْ بِهِ الخَم ... رُ وأن لا تَرِينَهُ باتِّقاء\n\nيعني: ترينه بمخافة، يقول: سكر فهو لا ينتبه؛ ومنه قول الراجز:\n\nلم نَروَ حتى هَجَّرَت وَرِينَ بي ... وَرِينَ بالسَّاقي الَّذي أمْسَى مَعِي\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل، وجاء الأثَر عن رسول الله ﷺ.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا أبو خالد، عن ابن عجلان، عن القَعْقاع بن حكيم، عن أبي صالح، عن أبي هُرَيرة، قال: قال رسول الله ﷺ: \"إذَا أذنَبَ العَبْدُ نُكِتَ فِي قَلْبِهِ نُكْتَة سَوْدَاءُ، فإنْ تابَ صُقِلَ مِنْها، فإنْ عادَ عادَتْ حتى تَعْظُمَ فِي قَلْبِهِ، فذلكَ الرَّانُ الَّذي قَالَ الله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ \".\n\n⁕ حدثنا محمد بن بشار، قال: ثنا صفوان بن عيسى، قال: ثنا ابن عَجلان، عن القَعقاع، عن أبي صالح، عن أبي هريرة، قال: قال رسول الله ﷺ: \"إنَّ المُؤْمَنَ إذَا أذْنَبَ ذَنْبًا كَانَتْ نُكْتَةٌ سَوْدَاءُ فِي قَلْبِهِ، فإن تابَ وَنزعَ وَاسْتَغْفَرَ صَقَلَتْ قَلْبَهُ، فإنْ زَادَ زَادَتْ حتى تَعْلُو قَلْبَهُ، فَذَلكَ الرَّانُ الَّذي قال الله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ \".\n\n⁕ حدثني عليّ بن سهيل، قال: ثنا الوليد بن مسلم، عن محمد بن عَجْلان، عن القَعقَاع بن حكيم، عن أبي صالح، عن أبي هريرة، عن النبيّ ﷺ قال: \"إنَّ الْعَبْدَ إذَا أذْنَبَ ذَنْبًا كَانَتْ نُكْتَةٌ سَوْدَاءُ فِي قَلْبِهِ، فإنْ تابَ مِنْهَا صُقِلَ قَلْبُهُ، فإنْ زَادَ زَادَتْ فَذلكَ قَوْلُ اللهِ: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ \".\n\n⁕ حدثني أبو صالح الضَّراري محمد بن إسماعيل، قال: أخبرني طارق بن عبد العزيز، عن ابن عجلان، عن القعقاع، عن أبي هريرة، قال: قال رسول إلله ﷺ: \"إنَّ الْعَبْدَ إذَا أخْطأَ خَطِيئَةً كَانَتْ نُكْتَةٌ فِي قَلْبِهِ، فإنْ تَاب واسْتَغْفَرَ وَنزعَ صَقَلَتْ قَلْبَهُ، وَذَلكَ الرَّانُ الَّذِي قَالَ اللهُ: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: أبو صالح: كذا قال: صقلت، وقال غيره: سَقَلت.\n\n⁕ حدثني عليّ بن سهيل الرمليّ، قال: ثنا الوليد، عن خُلَيد، عن الحسن، قال: وقرأ ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: الذنب على الذنب حتى يموت قلبه.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: الذنب على الذنب حتى يَعمى القلب فيموت.\n\n⁕ حدثني يحيى بن طلحة اليربوعي، قال: ثنا فضيل بن عياض، عن منصور، عن مجاهد ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: العبد يعمل بالذنوب فتحيط بالقلب، ثم ترتفع، حتى تغشى القلب.\n\n⁕ حدثني عيسى بن عثمان بن عيسى الرملي، قال: ثنا يحيى بن عيسى، عن الأعمش، قال: أرانا مجاهد بيده، قال: كانوا يرون القلب في مثل هذا يعني: الكفّ، فإذا أذنب العبد ذنبا ضم منه، وقال بأصبعه الخنصر هكذا فإذا أذنب ضمّ أصبعا أخرى، فإذا أذنب ضمّ أصبعا أخرى، حتى ضمّ أصابعه كلها، ثم يطبع عليه بطابع، قال مجاهد: وكانوا يرون أن ذلك الرَّيْن.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن الأعمش، عن مجاهد، قال: القلب مثل الكفّ، فإذا أذنب الذنب قبض أصبعا، حتى يقبض أصابعه كلها، وإن أصحابنا يرون أنه الران.\n\n⁕ حدثنا أبو كُرَيب مرة أخرى بإسناده عن مجاهد قال: القلب مثل الكفّ، وإذا أذنب انقبض وقبض أصبعه، فإذا أذنب انقبض حتى ينقبض كله، ثم يطبع عليه، فكانوا يرون أن ذلك هو الران ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ .\n\n⁕ حدثنا محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ قال: الخطايا حتى غمرته.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد: ﴿بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ انبثت على قلبه الخطايا حتى غمرته.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ يقول: يطبع.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: طبع على قلوبهم ما كسبوا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن طلحة، عن عطاء ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: غشيت على قلوبهم فهوت بها، فلا يفزعون، ولا يتحاشون.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الحسن ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: هو الذنب حتى يموت القلب.\n\n⁕ قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ قال: الران: الطبع يطبع القلب مثل الراحة، فيذنب الذنب فيصير هكذا، وعقد سفيان الخنصر، ثم يذنب الذنب فيصير هكذا، وقَبض سفيان كفه، فيطبع عليه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ أعمال السوء، أي والله ذنب على ذنب، وذنب على ذنب حتى مات قلبه واسودّ.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ قال: هذا الذنب على الذنب، حتى يَرِين على القلب فيسودّ.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ﴾ قال: غلب على قلوبهم ذُنُوبهم، فَلا يخْلُص إليها معها خير.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، في قوله: ﴿كَلا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ قال: الرجل يذنب الذنب، فيحيط الذنب بقلبه حتى تغشى الذنوب عليه. قال مجاهد: وهي مثل الآية التي في سورة البقرة ﴿بَلَى مَنْ كَسَبَ سَيِّئَةً وَأَحَاطَتْ بِهِ خَطِيئَتُهُ فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ﴾ .","13":12,"14":12,"15":"القول في تأويل قوله تعالى: ﴿كَلا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ (١٥) ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيمِ (١٦) ثُمَّ يُقَالُ هَذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ (١٧) ﴾\n\n.\n\nيقول تعالى ذكره: ما الأمر كما يقول هؤلاء المكذّبون بيوم الدين، من أن لهم عند الله زُلْفة، إنهم يومئذ عن ربهم لمحجوبون، فلا يرونه، ولا يرون شيئا من كرامته يصل إليهم.\n\nوقد اختلف أهل التأويل في معنى قوله: ﴿إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾ فقال بعضهم: معنى ذلك: إنهم محجوبون عن كرامته.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ بن سهل، قال: ثنا الوليد بن مسلم، عن خليد، عن قتادة ﴿كَلا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾ هو لا ينظر إليهم، ولا يزكيهم، ولهم عذاب أليم.\n\n⁕ حدثني سعيد بن عمرو السكوني، قال: ثنا بقية بن الوليد، قال: ثنا جرير، قال: ثني نمران أبو الحسن الذماري، عن ابن أبي مليكة أنه كان يقول في هذه الآية ﴿إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾ قال: المنان والمختال والذي يقتطع أموال الناس بيمينه بالباطل.\n\nوقال آخرون: بل معنى ذلك: إنهم محجوبون عن رؤية ربهم.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمار الرازي، قال: ثنا أبو معمر المنقري، قال: ثنا عبد الوارث بن سعيد، عن عمرو بن عبيد، عن الحسن في قوله: ﴿كَلا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾ قال: يكشف الحجاب فينظر إليه المؤمنون كلّ يوم غُدْوة وعشية، أو كلاما هذا معناه.\n\nوأولى الأقوال في ذلك بالصواب أن يقال: إن الله تعالى ذكره أخبر عن هؤلاء القوم أنهم عن رؤيته محجوبون. ويُحتمل أن يكون مرادًا به الحجاب عن كرامته، وأن يكون مرادًا به الحجاب عن ذلك كله، ولا دلالة في الآية تدلّ على أنه مراد بذلك الحجاب عن معنى منه دون معنى، ولا خبر به عن رسول الله ﷺ قامت حجته. فالصواب أن يقال: هم محجوبون عن رؤيته، وعن كرامته إذ كان الخبر عاما، لا دلالة على خصوصه.\n\n* *\n\nوقوله: ﴿إِنَّهُمْ لَصَالُو الْجَحِيمِ﴾\n\nيقول تعالى ذكره: ثم إنهم لوَارِدُو الجحيم، فمشويُّون فيها، ثم يقال: ﴿هَذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾ يقول جلّ ثناؤه: ثم يقال لهؤلاء المكذّبين بيوم الدين: هذا العذاب الذي أنتم فيه اليوم، هو العذاب الذي كنتم في الدنيا تخبرون أنكم ذائقوه، فتكذّبون به، وتنكرونه، فذوقوه الآن، فقد صَلَيْتُم به.","16":15,"17":15,"18":"القول في تأويل قوله تعالى: ﴿كَلا إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ (١٨) وَمَا أَدْرَاكَ مَا عِلِّيُّونَ (١٩) كِتَابٌ مَرْقُومٌ (٢٠) يَشْهَدُهُ الْمُقَرَّبُونَ (٢١) إِنَّ الأبْرَارَ لَفِي نَعِيمٍ (٢٢) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿كَلا إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ والأبرار: جمع برّ، وهم الذين برّوا الله بأداء فرائضه، واجتناب محارمه. وقد كان الحسن يقول: هم الذين لا يؤذون شيئًا حتى الذَّرّ.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا هشام، عن شيخ، عن الحسن، قال: سُئل عن الأبرار، قال: الذين لا يؤذون الذرّ.\n\n⁕ حدثنا إسحاق بن زيد الخطابي، قال: ثنا الفريابي، عن السري بن يحيى، عن الحسن، قال: الأبرار: هم الذين لا يؤذون الذرّ.\n\n* *\n\nوقوله: ﴿لَفِي عِلِّيِّينَ﴾\n\nاختلف أهل التأويل في معنى عليين، فقال بعضهم: هي السماء السابعة.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني جرير بن حازم، عن الأعمش، عن شمر بن عطية، عن هلال بن يساف، قال: سأل ابن عباس كعبًا وأنا حاضر عن العليين، فقال كعب: هي السماء السابعة، وفيها أرواح المؤمنين.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا عبيد الله - يعني: الْعَتَكي - عن قتادة، في قوله: ﴿إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ قال: في السماء العليا.\n\n⁕ حدثني عليّ بن الحسين الأزدي، قال: ثنا يحيى بن يمان، عن أُسامة بن زيد، عن أبيه، في قوله: ﴿إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ قال: في السماء السابعة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعًا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿عِلِّيِّينَ﴾ قال: السماء السابعة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿لَفِي عِلِّيِّينَ﴾ في السماء عند الله.\n\nوقال آخرون: بل العِليُّون: قائمة العرش اليمنى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿كَلا إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ ذُكر لنا أن كعبًا كان يقول: هي قائمة العرش اليمنى.\n\n⁕ حدثني عمر بن إسماعيل بن مجالد، قال: ثنا مُطَرِّف بن مازن، قاضي اليمن، عن معمر، عن قتادة، في قوله: ﴿إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ قال: عليون: قائمة العرش اليمنى.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فِي عِلِّيِّينَ﴾ قال: فوق السماء السابعة، عند قائمة العرش اليمنى.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القُمِّي، عن حفص، عن شمر بن عطية، قال: جاء ابن عباس إلى كعب الأحبار فسأله، فقال: حدثْنِي عن قول الله: (إِنَّ\n\nكِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ ... ) الآية، فقال كعب: إن الروح المؤمنة إذا قُبِضت، صُعد بها، فَفُتحت لها أبواب السماء، وتلقَّتها الملائكة بالبُشرَى، ثم عَرَجُوا معها حتى ينتهوا إلى العرش، فيخرج لها من عند العرش فيُرقَم رَقّ، ثم يختم بمعرفتها النجاة بحساب يوم القيامة، وتشهد الملائكة المقرّبون.\n\nوقال آخرون: بل عُنِي بالعليين: الجَنَّة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثنا معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ قال: الجنة.\n\nوقال آخرون: عند سِدْرَةِ المنتهى.\n\nذكر من قال ذلك:\n\n⁕ حدثني جعفر بن محمد البزوري من أهل الكوفة، قال: ثنا يعلى بن عبيد، عن الأجلح، عن الضحاك قال: إذا قبض روح العبد المؤمن عرج به إلى السماء، فتنطلق معه المقرّبون إلى السماء الثانية، قال الأجلح: قلت: وما المقرّبون؟ قال: أقربهم إلى السماء الثانية، فتنطلق معه المقرّبون إلى السماء الثالثة، ثم الرابعة، ثم الخامسة، ثم السادسة، ثم السابعة، حتى تنتهي به إلى سِدْرَة المنتهى. قال الأجلح: قلت للضحاك: لِمَ تُسمَّى سِدْرَة المنتهى؟ قال: لأنه يَنْتَهِي إليها كلّ شيء من أمر الله، لا يعدوها، فتقول: ربّ عبدك فلان، وهو أعلم به منهم، فيبعث الله إليهم بصَكّ مختوم يؤمِّنه من العذاب، فذلك قول الله: ﴿كَلا إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ وَمَا أَدْرَاكَ مَا عِلِّيُّونَ كِتَابٌ مَرْقُومٌ يَشْهَدُهُ الْمُقَرَّبُونَ﴾ .\n\nوقال آخرون: بل عُنِي بالعِلِّيِّينَ: في السماء عند الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿إِنَّ كِتَابَ الأبْرَارِ لَفِي عِلِّيِّينَ﴾ يقول: أعمالُهُم في كتاب عند الله في السماء.\n\nوالصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أخبر أن كتاب الأبرار في عليين؛ والعليون: جمع معناه: شيء فوق شيء، وعلوّ فوق علوّ، وارتفاع بعد ارتفاع، فلذلك جُمعت بالياء والنون، كجمع الرجال، إذا لم يكن له بناء من واحده واثنيه، كما حُكِيَ عن بعض العرب سماعًا أطْعَمَنَا مَرَقَةَ مَرَقَيْنِ: يعني اللحم المطبوخ  كما قال الشاعر:\n\nقَدْ رَوَيَتْ إلا الدُّهَيْدِهِينَا ... قَلَيُّصَاتٍ وَأُبَيْكِرِينَا\n\nفقال: وأبيكرينا، فجمعها بالنون إذ لم يقصد عددًا معلومًا من البكارة، بل أراد عددًا لا يحدّ آخره، وكما قال الآخر:\n\nفَأَصْبَحَتِ المَذَاهِبُ قَدْ أذَاعَتْ ... بِهَا الإعْصَارُ بَعْدَ الْوَابِلينَا\n\nيعني: مطرًا بعد مطر غير محدود العدد، وكذلك تفعل العرب في كلّ جمع لم يكن بناء له من واحده واثنيه، فجمعه في جميع الإناث والذكران بالنون على ما قد بيَّنا، ومن ذلك قولهم للرجال والنساء: عشرون وثلاثون. فإذا كان ذلك كالذي ذكرنا، فبين أنّ قوله: ﴿لَفِي عِلِّيِّينَ﴾ معناه: في علوّ وارتفاع في سماء فوق سماء، وعلوّ فوق علوّ وجائز أن يكون ذلك إلى السماء السابعة، وإلى سدرة المنتهى، وإلى قائمة العرش، ولا خبر يقطع العذر بأنه معنيّ به بعض ذلك دون بعض.\n\nوالصواب أن يقال في ذلك، كما قال جلّ ثناؤه: إن كتاب أعمال الأبرار لفي ارتفاع إلى حدّ قد علم الله جلّ وعزّ منتهاه، ولا علم عندنا بغايته، غير أن ذلك لا يقصر عن السماء السابعة، لإجماع الحجة من أهل التأويل على ذلك.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا عِلِّيُّونَ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ، مُعَجِّبه من عليين: وأيّ شيء أشعرك يا محمد ما عليون.\n\n* *\n\nوقوله: ﴿كِتَابٌ مَرْقُومٌ﴾\n\nيقول جلّ ثناؤه: إن كتاب الأبرار لفي عليين، ﴿كتاب مرقوم﴾ : أي مكتوب بأمان من الله إياه من النار يوم القيامة، والفوز بالجنة، كما قد ذكرناه قبل عن كعب الأحبار والضحاك بن مُزَاحم.\n\nوكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿كِتَابٌ مَرْقُومٌ﴾ رقم.\n\n* *\n\nوقوله: ﴿يَشْهَدُهُ الْمُقَرَّبُونَ﴾\n\nيقول: يشهد ذلك الكتاب المكتوب بأمان الله للبَرّ من عباده من النار، وفوزه بالجنة، المقرّبون من ملائكته من كلّ سماء من السموات السبع.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿يَشْهَدُهُ الْمُقَرَّبُونَ﴾ قال: كلّ أهل السماء.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَشْهَدُهُ الْمُقَرَّبُونَ﴾ من ملائكة الله.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يَشْهَدُهُ الْمُقَرَّبُونَ﴾ قال: يشهده مقرّبو أهل كلّ سماء.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يَشْهَدُهُ الْمُقَرَّبُونَ﴾ قال: الملائكة.\n\n* *\n\nوقوله: ﴿إِنَّ الأبْرَارَ لَفِي نَعِيمٍ﴾\n\nيقول تعالى ذكره: إن الأبرار الذين بَرّوا باتقاء الله وأداء فرائضه، لفي نعيم دائم، لا يزول يوم القيامة، وذلك نعيمهم في الجنان.","19":18,"20":18,"21":18,"22":18,"23":"القول في تأويل قوله تعالى: ﴿عَلَى الأرَائِكِ يَنْظُرُونَ (٢٣) تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ (٢٤) يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ (٢٥) خِتَامُهُ مِسْكٌ وَفِي ذَلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ (٢٦) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: ﴿عَلَى الأرَائِكِ يَنْظُرُونَ﴾ على السرر في الحجال من اللؤلؤ والياقوت ينظرون إلى ما أعطاهم الله من الكرامة والنعيم، والحَبْرة في الجنان.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿عَلَى الأرَائِكِ﴾ قال: من اللؤلؤ والياقوت.\n\n⁕ قال: ثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حصين، عن مجاهد، عن ابن عباس ﴿الأرَائِكِ﴾ السُّررُ في الحَجال.\n\n* *\n\nوقوله: ﴿تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ﴾\n\nيقول تعالى ذكره: تعرف في الأبرار الذين وصف الله صفتهم ﴿نضرة النعيم﴾ ، يعني: حُسنه وبريقه وتلألؤه.\n\nواختلفت القرّاء في قراءة قوله: ﴿تَعْرِفُ﴾ فقرأته عامة قرّاء الأمصار سوى أبي جعفر القارئ ﴿تَعْرِفُ فِي وُجُوهِهِمْ﴾ بفتح التاء من تعرف على وجه الخطاب ﴿نَضْرَةَ النَّعِيمِ﴾ بنصب نضرة. وقرأ ذلك أبو جعفر: ﴿تُعْرَفُ﴾ بضم التاء على وجه ما لم يسمّ فاعله ﴿فِي وُجُوهِهِمْ نَضْرَةُ النَّعِيمِ﴾ برفع نضرة.\n\nوالصواب من القراءة في ذلك عندنا: ما عليه قرّاء الأمصار، وذلك فتح التاء من ﴿تَعْرِفُ﴾ ونصب ﴿نَضْرَةَ﴾ .\n\n* *\n\nوقوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾\n\nيقول: يُسقى هؤلاء الأبرار من خمر صرف لا غشّ فيها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ قال: من الخمر.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ يعني بالرحيق: الخمر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ قال: خمر.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، قال: الرحيق: الخمر.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿رَحِيقٍ﴾ قال: هو الخمر.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ يقول: الخمر.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ الرحيق المختوم: الخمر، قال حسان:\n\nيَسْقُونَ مَنْ وَرَدَ البَرِيصَ عَلَيْهِمُ ... بَرَدَى يُصَفَّقُ بالرَّحِيقِ السَّلْسَلِ\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ﴾ قال: هو الخمر.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن الأعمش، عن عبد الله بن مرّة، عن مسروق، عن عبد الله قال: الرحيق: الخمر.\n\nوأما قوله: ﴿مَخْتُومٍ خِتَامُهُ مِسْكٌ﴾ فإن أهل التأويل اختلفوا في تأويله، فقال بعضهم: معنى ذلك: ممزوج مخلوط، مِزاجه وخِلطه مِسك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أشعث بن أبي الشعثاء، عن يزيد بن معاوية، وعلقمة عن عبد الله بن مسعود ﴿خِتَامُهُ مِسْكٌ﴾ قال: ليس بخاتم، ولكن خلط.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى بن سعيد وعبد الرحمن، قالا ثنا سفيان، عن أشعث بن سليم، عن يزيد بن معاوية، عن علقمة، عن عبد الله بن مسعود ﴿خِتَامُهُ مِسْكٌ﴾ قال: أما إنه ليس بالخاتم الذي يختم، أما سمعتم المرأة من نسائكم تقول: طيب كذا وكذا خلطه مسك.\n\n⁕ حدثني محمد بن عبيد المحاربيّ، قال: ثنا أيوب، عن أشعث بن أبي الشعثاء عمن ذكره عن علقمة، في قوله: ﴿خِتَامُهُ مِسْكٌ﴾ قال: خلطه مسك.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن الأعمش، عن عبد الله بن مرّة، عن مسروق، عن عبد الله ﴿مختوم﴾ قال: ممزوج ﴿خِتَامُهُ مِسْكٌ﴾ قال: طعمه وريحه.\n\n⁕ قال: ثنا وكيع، عن أبيه، عن أشعث بن أبي الشعثاء، عن يزيد بن معاوية، عن علقمة ﴿خِتَامُهُ مِسْكٌ﴾ قال: طعمه وريحه مسك.\n\nوقال آخرون: بل معنى ذلك: أن آخر شرابهم يُخْتم بمسك يجعل فيه.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿رَحِيقٍ مَخْتُومٍ خِتَامُهُ مِسْكٌ﴾ يقول: الخمر خُتِمَ بالمسك.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿خِتَامُهُ مِسْكٌ﴾ قال: طيَّب الله لهم الخمر، فكان آخر شيء جعل فيها حتى تختم المسك.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿خِتَامُهُ مِسْكٌ﴾ قال: عاقبته مسك قوم تُمزَج لهم بالكافور، وتختم بالمسك.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿خِتَامُهُ مِسْكٌ﴾ قال: عاقبته مِسك.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿خِتَامُهُ مِسْكٌ﴾ قال: طيَّب الله لهم الخمر، فوجدوا فيها في آخر شيء منها ريح المسك.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا حاتم بن وردان، قال: ثنا أبو حمزة، عن إبراهيم والحسن في هذه الآية: ﴿خِتَامُهُ مِسْكٌ﴾ قال: عاقبته مسك.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا أبو حمزة، عن جابر عن عبد الرحمن بن سابط، عن أبي الدرداء ﴿خِتَامُهُ مِسْكٌ﴾ فالشراب أبيض مثل الفضة يختمون به شرابهم، ولو أن رجلا من أهل الدنيا أدخل أصبعه فيه ثم أخرجها، لم يبق ذو روح إلا وجد طيبها.\n\nوقال آخرون: عُنِي بقوله: ﴿مَخْتُومٍ﴾ مُطَيَّن ﴿خِتَامُهُ مِسْكٌ﴾ طينه مسك.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح. عن مجاهد، قوله: ﴿مَخْتُومٍ خِتَامُهُ مِسْكٌ﴾ قال: طينه مسك.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿مَخْتُومٍ﴾ الخمر ﴿خِتَامُهُ مِسْكٌ﴾ : ختامه عند الله مسك، وختامها اليوم في الدنيا طين.\n\nوأولى الأقوال في ذلك عندنا بالصواب قول من قال: معنى ذلك: آخره وعاقبته مسك: أي هي طيبة الريح، إن ريحها في آخر شربهم يختم لها بريح المسك.\n\nوإنما قلنا: ذلك أولى الأقوال في ذلك بالصحة؛ لأنه لا وجه للختم في كلام العرب إلا الطبع والفراغ، كقولهم: ختم فلان القرآن: إذا أتى على آخره، فإذا كان لا وجه للطبع على شراب أهل الجنة، يفهم إذا كان شرابهم جاريًا، جري الماء في الأنهار، ولم يكن معتقًا في الدنان فيطين عليها وتختم، تعين أن الصحيح من ذلك الوجه الآخر وهو العاقبة والمشروب آخرًا، وهو الذي ختم به الشراب. وأما الختم بمعنى: المزج، فلا نعلمه مسموعًا من كلام العرب.\n\nوقد اختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الأمصار: ﴿خِتَامُهُ مِسْكٌ﴾ سوى الكسائيّ، فإنه كان يقرأه ﴿خاتَمَهُ مِسْكٌ﴾ .\n\nوالصواب من القول عندنا في ذلك ما عليه قرأة الأمصار، وهو ﴿خِتَامُهُ﴾ لإجماع الحجة من القرّاء عليه، والختام والخاتم وإن اختلفا في اللفظ، فإنهما متقاربان في المعنى غير أن الخاتم اسم، والختام مصدر؛ ومنه قول الفرزدق.\n\nفَبِتْنَ بِجَانبيَّ مُصَرَّعاتٍ ... وَبِتُّ أفُضُّ أغْلاقَ الخِتامِ\n\nونظير ذلك قولهم: هو كريم الطبائع والطباع.\n\n* *\n\nوقوله: ﴿وَفِي ذَلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ﴾\n\nيقول تعالى ذكره: وفي هذا النعيم الذي وصف جل ثناؤه أنه أعطى هؤلاء الأبرار في القيامة، فليتنافس المتنافسون. والتنافس: أن يَنفِس الرجل على الرجل بالشيء يكون له، ويتمنى أن يكون له دونه، وهو مأخوذ من الشيء النفيس، وهو الذي تحرص عليه نفوس الناس، وتطلبه وتشتهيه، وكان معناه في ذلك. فليجدّ الناس فيه، وإليه فليستبقوا في طلبه، ولتحرص عليه نفوسهم.","24":23,"25":23,"26":23,"27":"القول في تأويل قوله تعالى: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ (٢٧) عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ (٢٨) إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ (٢٩) ﴾\n\n.\n\nيقول تعالى ذكره: ومزاج هذا الرحيق من تسنيم؛ والتسنيم: التفعيل من قول القائل: سنَّمتهم العين تسنيمًا: إذا أجريتها عليهم من فوقهم، فكان معناه في هذا الموضع: ومزاجه من ماء ينزل عليهم من فوقهم فينحدر عليهم. وقد كان مجاهد والكلبيّ يقولان في ذلك كذلك.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿تَسْنِيمٍ﴾ قال: تسنيم: يعلو.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبيّ، في قوله: ﴿تَسْنِيمٍ﴾ قال: تسنيم ينصبّ عليهم من فوقهم، وهو شراب المقرّبين. وأما سائر أهل التأويل، فقالوا: هو عين يمزج بها الرحيق لأصحاب اليمين، وأما المقرّبون، فيشربونها صِرْفًا.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن الأعمش، عن عبد الله بن مرّة، عن مسروق، عن عبد الله في قوله: ﴿مِنْ تَسْنِيمٍ﴾ قال: عين في الجنة يشربها المقرّبون، وتمزج لأصحاب اليمين.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش، عن عبد الله بن مرّة، عن مسروق، عن عبد الله ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: يشربه المقرّبون صرفا، ويمزج لأصحاب اليمين.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مالك بن الحارث، عن مسروق ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: عين في الجنة يشربها المقرّبون صرفا، وتمزج لأصحاب اليمين.\n\n⁕ قال ثنا مهران، عن سفيان، عن الأعمش، عن عبد الله بن مرّة، عن مسروق ﴿عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴾ قال: يشرب بها المقرّبون صِرفًا، وتمزج لأصحاب اليمين.\n\n⁕ حدثني طلحة بن يحيى اليربوعي، قال: ثنا فضيل بن عياض، عن منصور، عن مالك بن الحارث، في قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: في الجنة عين يشرب منها المقرّبون صرفا، وتمزج لسائر أهل الجنة.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا أبو حمزة، عن عطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس، قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴾ صرفًا، ويمزج فيها لمن دونهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مالك بن الحارث، في قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: التسنيم: عين في الجنة يشربها المقرّبون صرفا، وتمزج لسائر أهل الجنة.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا أبو حمزة، عن عطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس، قوله ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: عين يشرب بها المقرّبون، ويمزج فيها لمن دونهم.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴾ عينًا من ماء الجنة تُمزج به الخمر.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: خفايا أخفاها الله لأهل الجنة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا عمران بن عيينة، عن إسماعيل، عن أبي صالح، في قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ قال: هو أشرف شراب في الجنة. هو للمقرّبين صرف، وهو لأهل الجنة مزاج.\n\n⁕ حدثني بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَمِزَاجُهُ مِنْ تَسْنِيمٍ﴾ شراب شريف، عين في الجنة يشربها المقرّبون صرفا، وتمزج لسائر أهل الجنة.\n\n⁕ حدثني يونس. قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿مِنْ تَسْنِيمٍ عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴾ قال: بلغنا أنها عين تخرج من تحت العرش، وهي مزاج هذه الخمر، يعني مزاج الرحيق.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿مِنْ تَسْنِيمٍ﴾ شراب اسمه تسنيم وهو من أشرف الشراب. فتأويل الكلام: ومزاج الرحيق من عين تُسَنَّم عليهم من فوقهم، فتنصبّ عليهم ﴿يَشْرَبُ بِهَا الْمُقَرَّبُونَ﴾ من الله صرفا، وتمزج لأهل الجنة.\n\nواختلفت أهل العربية في وجه نصب قوله: ﴿عَيْنًا﴾ قال بعض نحويي البصرة: إن شئت جعلت نصبه على يسقون عينا، وإن شئت جعلته مدحا، فيقطع من أوّل الكلام، فكأنك تقول: أعني: عينا.\n\nوقال بعض نحويي الكوفة: نصب العين على وجهين: أحدهما: أن ينوي من تسنيم عَيْن، فإذا نوَّنت نصبت، كما قال: ﴿أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ يَتِيمًا﴾ وكما قال: ﴿أَلَمْ نَجْعَلِ الأرْضَ كِفَاتًا أَحْيَاءً﴾ . والوجه الآخر: أن ينوي من ماء سُنِّم عينًا، كقولك: رفع عينا يشرب بها. قال: وإن لم يكن التسنيم اسما للماء فالعين نكرة، والتسنيم معرفة، وإن كان اسمًا للماء فالعين نكرة  فخرجت نصبا. وقال آخر من البصريين: ﴿مِنْ تَسْنِيمٍ﴾ معرفة، ثم قال: ﴿عَيْنا﴾ فجاءت نكرة، فنصبتها صفة لها. وقال آخر نُصبت بمعنى: من ماء يَتَسَنَّم عينا.\n\nوالصواب من القول في ذلك عندنا أن التسنيم اسم معرفة والعين نكرة، فنصبت لذلك إذ كانت صفة له.\n\nوإنما قلنا: ذلك هو الصواب لما قد قدّمنا من الرواية عن أهل التأويل، أن التسنيم هو العين، فكان معلومًا بذلك أن العين إذ كانت منصوبة وهي نكرة، وأن التسنيم معرفة.\n\n* *\n\nوقوله: ﴿إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ﴾\n\nيقول تعالى ذكره: إن الذين اكتسبوا المآثم، فكفروا بالله في الدنيا، كانوا فيها من الذين أقرّوا بوحدانية الله، وصدّقوا به ﴿يضحكون﴾ ، استهزاء منهم بهم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ﴾ في الدنيا، يقولون: والله إن هؤلاء لكذَبة وما هم على شيء استهزاء بهم.","28":27,"29":27,"30":"القول في تأويل قوله تعالى: ﴿وَإِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَ (٣٠) وَإِذَا انْقَلَبُوا إِلَى أَهْلِهِمُ انْقَلَبُوا فَكِهِينَ (٣١) وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَؤُلاءِ لَضَالُّونَ (٣٢) وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ (٣٣) ﴾\n\n.\n\nيقول تعالى ذكره: وكان هؤلاء الذين أجرموا إذا مرّ الذين آمنوا بهم يتغامزون؛ يقول: كان بعضهم يغمز بعضا بالمؤمن، استهزاء به وسخرية.\n\n* *\n\nوقوله: ﴿وَإِذَا انْقَلَبُوا إِلَى أَهْلِهِمُ انْقَلَبُوا فَاكِِهِينَ﴾\n\nيقول: وكان هؤلاء المجرمون إذا انصرفوا إلى أهلهم من مجالسهم انصرفوا ناعمين معجَبين.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿انْقَلَبُوا فَاكِِهِينَ﴾ قال: معجبين.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَإِذَا انْقَلَبُوا إِلَى أَهْلِهِمُ انْقَلَبُوا فَاكِِهِينَ﴾ قال: انقلب ناعما، قال: هذا في الدنيا، ثم أعقب النار في الآخرة.\n\nوقد كان بعض أهل العلم بكلام العرب يفرق بين معنى فاكهين وفكهين، فيقول: معنى فاكهين: ناعمين، وفكهين: مَرِحين. وكان غيره يقول: ذلك بمعنى واحد، وإنما هو بمنزلة طامع وطَمِع، وباخل وبخل.\n\n* *\n\nوقوله: ﴿وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَؤُلاءِ لَضَالُّونَ﴾\n\nيقول تعالى ذكره: وإذا رأى المجرمون المؤمنين قالوا لهم: إن هؤلاء لضالون عن محجة الحقّ، وسبيل القصد ﴿وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ﴾ يقول جل ثناؤه: وما بعث هؤلاء الكفار القائلون للمؤمنين ﴿إن هؤلاء لضالون﴾ حافظين عليهم أعمالهم. يقول: إنما كُلِّفوا الإيمان بالله، والعمل بطاعته، ولم يُجعلوا رُقباء على غيرهم يحفظون عليهم أعمالهم ويتفقدونها.","31":30,"32":30,"33":30,"34":"القول في تأويل قوله تعالى: ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ (٣٤) ﴾\n\n.","35":"القول في تأويل قوله تعالى: ﴿عَلَى الأرَائِكِ يَنْظُرُونَ (٣٥) هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ (٣٦) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿فَالْيَوْمَ﴾ وذلك يوم القيامة ﴿الَّذِينَ آمَنُوا﴾ بالله في الدنيا ﴿مِنَ الْكُفَّارِ﴾ فيها ﴿يَضْحَكُونَ عَلَى الأرَائِكِ يَنْظُرُونَ﴾ يقول: على سررهم التي في الحجال ينظرون إليهم وهم في الجنة، والكفار في النار يعذّبون.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ عَلَى الأرَائِكِ يَنْظُرُونَ﴾ قال: يعني: السُّرر المرفوعة عليها الحِجال. وكان ابن عباس يقول: إن السور الذي بين الجنة والنار يُفتح لهم فيه أبواب، فينظر المؤمنون إلى أهل النار، والمؤمنون على السرر ينظرون ٢٤-٣٠٥كيف يعذّبون، فيضحكون منهم، فيكون ذلك مما أقرّ الله به أعينهم، كيف ينتقم الله منهم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ﴾ ذُكر لنا أن كعبا كان يقول: إن بين الجنة والنار كوى، فإذا أراد المؤمن أن ينظر إلى عدّو كان له في الدنيا، اطلع من بعض الكوى، قال الله جل ثناؤه: ﴿فَاطَّلَعَ فَرَآهُ فِي سَوَاءِ الْجَحِيمِ﴾ أي في وسط النار، وذُكر لنا أنه رأى جماجم القوم تغلي.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال كعب: إن بين أهل الجنة وبين أهل النار كوى، لا يشاء رجل من أهل الجنة أن ينظر إلى غيره من أهل النار إلا فعل.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ عَلَى الأرَائِكِ يَنْظُرُونَ﴾ كان ابن عباس يقول: السور بين أهل الجنة والنار، فيفتح لأهل الجنة أبواب، فينظرون وهم على السُّرر إلى أهل النار كيف يعذّبون، فيضحكون منهم، ويكون ذلك مما أقرّ الله به أعينهم، كيف ينتقم الله منهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ﴾ قال: يُجاء بالكفار حتى ينظروا إلى أهل الجنة في الجنة، على سرر، فحين ينظرون إليهم تغلق دونهم الأبواب، ويضحك أهل الجنة منهم، فهو قوله: ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ عَلَى الأرَائِكِ يَنْظُرُونَ﴾ .\n\n* *\n\nوقوله: ﴿هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ﴾\n\nيقول تعالى ذكره: هل أثيب الكفار وجُزُوا ثواب ما كانوا في الدنيا يفعلون بالمؤمنين من سخريتهم منهم، وضحكهم بهم بضحك المؤمنين منهم في الآخرة، والمؤمنون على الأرائك ينظرون، وهم في النار يعذّبون.\n\nو ﴿ثُوِّبَ﴾ فعل من الثواب والجزاء، يقال منه: ثوّب فلان فلانًا على صنيعه، وأثابه منه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ﴾ قال: جزي.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان: ﴿هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ﴾ حين كانوا يسخرون.\n\nآخر تفسير سورة ويل للمطففين.","36":35},"84":{"1":"القول في تأويل قوله تعالى: ﴿إِذَا السَّمَاءُ انْشَقَّتْ (١) وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ (٢) وَإِذَا الأرْضُ مُدَّتْ (٣) وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ (٤) وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ (٥) ﴾\n\n.\n\nيقول تعالى ذكره: إذا السماء تصدّعت وتقطَّعت فكانت أبوابًا.\n\n* *\n\nوقوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾\n\nيقول: وَسَمِعَت السموات في تصدّعها وتشققها لربها وأطاعت له في أمره إياها، والعرب تقول: أذن لك في هذا الأمر أذنًا بمعنى: استمع لك، ومنه الخبر الذي رُوي عن النبيّ ﷺ: \"مَا أذِنَ اللهُ لِشَيءٍ كأَذَنِهِ لنَبِيّ يَتَغَنَّى بالقُرآنِ\" يعني بذلك: ما استمع الله لشيء كاستماعه لنبيّ يتغنى بالقرآن، ومنه قول الشاعر:\n\nصُمّ إذَا سَمِعُوا خَيْرًا ذُكِرْتُ بِهِ ... وَإنْ ذُكِرْتُ بِسُوءٍ عِنْدَهُمْ أَذِنُوا [[الخبر ١٦٨ - هذا الإسناد من أكثر الأسانيد دورانًا في تفسير الطبري، إن لم يكن أكثرها، فلا يكاد يخلو تفسير آية من رواية بهذا الإسناد. وقد عرض الطبري نفسه في (ص ١٢١ بولاق، سطر: ٢٨ وما بعده) ، فقال، وقد ذكر الخبر عن ابن مسعود وابن عباس بهذا الإسناد: \"فإن كان ذلك صحيحًا، ولست أعلمه صحيحًا، إذ كان بإسناده مرتابًا. . . . \". ولم يبين علة ارتيابه في إسناده، وهو مع ارتيابه قد أكثر من الرواية به. ولكنه لم يجعلها حجة قط.\n\nبيد أني أراه إسنادا يحتاج إلى بحث دقيق. ولأئمة الحديث كلام فيه وفي بعض رجاله. وقد تتبعت ما قالوا وما يدعو إليه بحثه، ما استطعت، وبدا لي فيه رأي، أرجو أن يكون صوابًا، إن شاء الله. وما توفيقي إلا بالله:\n\nأما شيخ الطبري، وهو \"موسى بن هارون الهمداني\": فما وجدت له ترجمة، ولا ذكرًا في شيء مما بين يدي من المراجع، إلا ما يرويه عنه الطبري أيضًا في تاريخه، وهو أكثر من خمسين موضعًا في الجزئين الأول والثاني منه. وما بنا حاجة إلى ترجمته من جهة الجرح والتعديل، فإن هذا التفسير الذي يرويه عن عمرو بن حماد، معروف عند أهل العلم بالحديث. وما هو إلا رواية كتاب، لا رواية حديث بعينه.\n\n\"وعمرو بن حماد\": هو عمرو بن حماد بن طلحة القناد، وقد ينسب إلى جده، فيقال عمرو بن طلحة، وهو ثقة، روى عنه مسلم في صحيحه، وترجمه ابن سعد في الطبقات ٦: ٢٨٥، وقال: \"وكان ثقة إن شاء الله\" مات سنة ٢٢٢. وترجمه ابن أبي حاتم في الجرح والتعديل ٣ / ١ / ٢٢٨، وروى عن أبيه ويحيى بن معين أنهما قالا فيه: \"صدوق\".\n\nأسباط بن نصر الهمداني: مختلف فيه، وضعفه أحمد، وذكره ابن حبان في الثقات: ٤١٠، ةترجمه البخاري في الكبير ١ / ٢ / ٥٣ فلم يذكر فيه جرحًا، وترجمه ابن أبي حاتم في الجرح والتعديل ١ / ١ / ٣٣٢، وروى عن يحيى بن معين قال: \"أسباط بن نصر ثقة\". وقد رجحنا توثيقه في شرح المسند، في الحديث ١٢٨٦.\n\nإسماعيل بن عبد الرحمن بن أبي كريمة السدي: هو السدي الكبير، قرشي بالولاء، مولى زينب بنت قيس بن مخرمة، من بني عبد مناف، كما نص على ذلك البخاري في تاريخيه: الصغير: ١٤١ - ١٤٢، والكبير ١ / ١ / ٣٦١، وهو تابعي، سمع أنسًا، كما نص على ذلك البخاري أيضًا، وروى عن غيره من الصحابة، وعن كثير من التابعين. وهو ثقة. أخرج له مسلم في صحيحه، وثقه أحمد بن حنبل، فيما روى ابن أبي حاتم في الجرح والتعديل ١ / ١ / ١٨٤، وروى أيضًا عن أحمد، قال: \"قال لي يحيى بن معين يومًا عند عبد الرحمن بن مهدي: السدي ضعيف، فغضب عبد الرحمن، وكره ما قال\": وفي الميزان والتهذيب \"أن الشعبي قيل له: إن السدي قد أعطي حظًا من علم القرآن، فقال: قد أعطي حظًا من جهل بالقرآن! \". وعندي أن هذه الكلمة من الشعبي قد تكون أساسا لقول كل من تكلم في السدي بغير حق. ولذلك لم يعبأ البخاري بهذا القول من الشعبي، ولم يروه، بل روى في الكبير عن مسدد عن يحيى قال: \" سمعت ابن أبي خالد يقول: السدي أعلم بالقرآن من الشعبي\". وروى في تاريخيه عن ابن المديني عن يحيى، وهو القطان، قال: \"ما رأيت أحدًا يذكر السدي إلا بخير، وما تركه أحد\". وفي التهذيب: \"قال العجلي: ثقة عالم بالتفسير راوية له\". وقد رجحنا توثيقه في شرح المسند ٨٠٧. وتوفي السدي سنة ١٢٧.\n\nو\"السدي\": بضم السين وتشديد الدال المهملتين، نسبة إلى \"السدة\"، وهي الباب، لأنه كان يجلس إلى سدة الجامع بالكوفة، ويبيع بها المقانع.\n\nأبو مالك: هو الغفاري، واسمه غزوان. وهو تابعي كوفي ثقة. ترجمه البخاري في الكبير ٤ / ١ / ١٠٨، وابن سعد في الطبقات ٦: ٢٠٦، وابن أبي حاتم في الجرح والتعديل ٣ / ٢ / ٥٥، وروى توثيقه يحيى بن معين.\n\nأبو صالح: هو مولى أم هانئ بنت أبي طالب، واسمه باذام، ويقال باذان. وهو تابعي ثقة، رجحنا توثيقه في شرح المسند ٢٠٣٠، وترجمه البخاري في الكبير ١ / ٢ / ١٤٤، وروى عن محمد بن بشار، قال: \"ترك ابن مهدي حديث أبي صالح\". وكذلك روى ابن أبي حاتم في ترجمته في الجرح والتعديل ١ / ١ / ٤٣١ - ٤٣٢ عن أحمد بن حنبل عن ابن مهدي. ولكنه أيضًا عن يحيى بن سعيد القطان، قال: \" لم أرَ أحدًا من أصحابنا ترك أبا صالح مولى أم هانئ، وما سمعت أحدًا من الناس يقول فيه شيئًا، ولم يتركه شعبة ولا زائدة ولا عبد الله بن عثمان\". وروى أيضًا عن يحيى بن معين، قال: \" أبو صالح مولى أم هانئ ليس به بأس، فإذا روى عنه الكلبي فليس بشيء، وإذا روى عنه غير الكلبي فليس به بأس، لأن الكلبي يحدث به مرة من رأيه، ومرة عن أبي صالح، ومرة عن أبي صالح عن ابن عباس\". يعني بهذا أن الطعن فيما يروي عنه هو في رواية الكلبي، كما هو ظاهر.\n\nهذا عن القسم الأول من هذا الإسناد. فإنه في حقيقته إسنادان أو ثلاثة. أولهما هذا المتصل بابن عباس.\n\nوالقسم الثاني، أو الإسناد الثاني: \"وعن مرة الهمداني عن ابن مسعود\". والذي يروي عن مرة الهمداني: هو السدي نفسه.\n\nومرة: هو ابن شراحيل الهمداني الكوفي، وهو تابعي ثقة، من كبار التابعين، ليس فيه خلاف بينهم.\n\nوالقسم الثالث، أو الإسناد الثالث: \"وعن ناس من أصحاب النبي ﷺ\".\n\nوهذا أيضًا من رواية السدي نفسه عن ناس من الصحابة.\n\nفالسدي يروي هذه التفاسير لآيات من القرآن: عن اثنين من التابعين عن ابن عباس، وعن تابعي واحد عن ابن مسعود، ومن رواية نفسه عن ناس من الصحابة.\n\nوللعلماء الأئمة الأقدمين كلام في هذا التفسير، بهذه الأسانيد، قد يوهم أنه من تأليف من دون السدي من الرواة عنه، إلا أني استيقنت بعدُ، أنه كتاب ألفه السدي.\n\nفمن ذلك قول ابن سعد في ترجمة \"عمرو بن حماد القناد\" ٦: ٢٨٥: \"صاحب تفسير أسباط بن نصر عن السدي\". وقال في ترجمة \"أسباط بن نصر\" ٦: ٢٦١: \"وكان راوية السدي، روى عنه التفسير\". وقال قبل ذلك في ترجمة \"السدي\" ٦: ٢٢٥: \"إسماعيل بن عبد الرحمن السدي، صاحب التفسير\". وقال قبل ذلك أيضًا، في ترجمة \"أبي مالك الغفاري\" ٦: ٢٠٦: \"أبو مالك الغفاري صاحب التفسير، وكان قليل الحديث\".\n\nولكن الذي يرجح أنه كتاب ألفه السدي، جمع فيه التفسير، بهذه الطرق الثلاث، قول أحمد بن حنبل في التهذيب ١: ٣١٤، في ترجمة السدي: \"إنه ليحسن الحديث، إلا أن هذا التفسير الذي يجئ به، قد جعل له إسنادًا، واستكلفه\". وقول الحافظ في التهذيب أيضًا ١: ٣١٥: \"قد أخرج الطبري وابن أبي حاتم وغيرهما، في تفاسيرهم، تفسير السدي، مفرقًا في السور، من طريق أسباط بن نصر عنه\".\n\nوقول السيوطي في الإتقان ٢: ٢٢٤ فيما نقل عن الخليل في الإرشاد: \"وتفسير إسماعيل السدي، يورده بأسانيد إلى ابن مسعود وابن عباس. وروى عن السدي الأئمة، مثل الثوري وشعبة. ولكن التفسير الذي جمعه، رواه أسباط بن نصر. وأسباط لم يتفقوا عليه. غير أن أمثل التفاسير تفسير السدي\". ثم قال السيوطي: \"وتفسير السدي، [الذي] أشار إليه، يورد منه ابن جرير كثيرًا، من طريق السدي عن أبي مالك وعن أبي صالح عن ابن عباس، وعن مرة عن ابن مسعود، و [عن] ناس من الصحابة. هكذا. ولم يورد منه ابن أبي حاتم شيئًا، لأنه التزم أن يخرج أصح ما ورد. والحاكم يخرج منه في مستدركه أشياء، ويصححه، لكن من طريق مرة عن ابن مسعود وناس، فقط، دون الطريق الأول، وقد قال ابن كثير: إن هذا الإسناد يروي به السدي أشياء فيها غرابة\".\n\nوأول ما نشير إليه في هذه الأقوال: التناقض بين قولي الحافظ ابن حجر والسيوطي، في أن ابن أبي حاتم أخرج تفسير السدي مفرقًا في تفسيره، كما صنع الطبري، في نقل الحافظ، وأنه أعرض عنه، في نقل السيوطي. ولست أستطيع الجزم في ذلك بشيء، إذ لم أرَ تفسير ابن أبي حاتم. ولكني أميل إلى ترجيح نقل ابن حجر، بأنه أكثر تثبتًا ودقة في النقل من السيوطي.\n\nثم قد صدق السيوطي فيما نقل عن الحاكم. فإنه يروي بعض هذا التفسير في المستدرك، بإسناده، إلى أحمد بن نصر: \"حدثنا عمرو بن طلحة القناد حدثنا أسباط بن نصر، عن إسماعيل بن عبد الرحمن السدي، عن مرة الهمداني، عن عبد الله بن مسعود، وعن أناس من أصحاب النبي ﷺ\". ثم يصححه على شرط مسلم، ويوافقه الذهبي في تلخيصه. من ذلك في المستدرك ٢: ٢٥٨، ٢٦٠، ٢٧٣، ٣٢١.\n\nوالحاكم في ذلك على صواب، فإن مسلمًا أخرج لجميع رجال هذا الإسناد. من عمرو بن حماد بن طلحة القناد إلى مرة الهمداني. ولم يخرج لأبي صالح باذام ولا لأبي مالك الغفاري، في القسم الأول من الإسناد الذي روى به السدي تفاسيره.\n\nأما كلمة الإمام أحمد بن حنبل في السدي \"إلا أن هذا التفسير الذي يجيء به، قد جعل له إسنادًا واستكلفه\" فإنه لا يريد ما قد يفهم من ظاهرها: أنه اصطنع إسنادا لا أصل له؛ إذ لو كان ذلك، لكان -عنده- كذابًا وضاعًا للرواية. ولكنه يريد -فيما أرى، والله أعلم- أنه جمع هذه التفاسير، من روايته عن هؤلاء الناس: عن أبي مالك وأبي صالح عن ابن عباس، وعن مرة عن ابن مسعود، وعن ناس من الصحابة، ثم ساقها كلها مفصلة، على الآيات التي ورد فيها شيء من التفسير، عن هذا أو ذاك أو أولئك، وجعل لها كلها هذا الإسناد، وتكلف أن يسوقها به مساقًا واحدًا.\n\nأعني: أنه جمع مفرق هذه التفاسير في كتاب واحد، جعل له في أوله هذه الأسانيد. يريد بها أن ما رواه من التفاسير في هذا الكتاب، لا يخرج عن هذه الأسانيد. ولا أكاد أعقل أنه يروي كل حرف من هذه التفاسير عنهم جميعا. فهو كتاب مؤلف في التفسير، مرجع فيه إلى الرواية عن هؤلاء، في الجملة، لا في التفصيل.\n\nإنما الذي أوقع الناس في هذه الشبهة، تفريق هذه التفاسير في مواضعها، مثل صنيع الطبري بين أيدينا، ومثل صنيع ابن أبي حاتم، فيما نقل الحافظ ابن حجر، ومثل صنيع الحاكم في المستدرك. فأنا أكاد أجزم أن هذا التفريق خطأ منهم، لأنه يوهم القارئ أن كل حرف من هذه التفاسير مروي بهذه الأسانيد كلها، لأنهم يسوقونها كاملة عند كل إسناد، والحاكم يختار منها إسنادًا واحدًا يذكره عند كل تفسير منها يريد روايته. وقد يكون ما رواه الحاكم -مثلا- بالإسناد إلى ابن مسعود، ليس مما روى السدي عن ابن مسعود نصًا. بل لعله مما رواه من تفسير ابن عباس، او مما رواه ناس من الصحابة، روى عن كل واحد منهم شيئًا، فأسند الجملة، ولم يسند التفاصيل.\n\nولم يكن السدي ببدع في ذلك، ولا يكون هذا جرحًا فيه ولا قدحًا. إنما يريد إسناد هذه التفاسير إلى الصحابة، بعضها عن ابن عباس، وبعضها عن ابن مسعود، وبعضها ع]]\n\nوأصل قولهم في الطاعة سمع له من الاستماع، يقال منه: سمعت لك، بمعنى سمعت قولك، وأطعت فيما قلتَ وأمرت.\n\nوبنحو الذي قلنا في معنى قوله: ﴿وَأَذِنَتْ لِرَبِّهَا﴾ قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ قال: سمعت لربها.\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ قال: سمعت وأطاعت.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ قال: سمعت.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ قال: سمعت وأطاعت.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ : أي سمعت وأطاعت.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ قال: سمعت وأطاعت.\n\n* *\n\nوقوله: ﴿وَحُقَّتْ﴾\n\nيقول: وحقق الله عليها الاستماع بالانشقاق والانتهاء إلى طاعته في ذلك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿وَحُقَّتْ﴾ قال: حُقِّقَت لطاعة ربها.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن أشعث بن إسحاق، عن جعفر، عن سعيد بن جُبير ﴿وَحُقَّتْ﴾ وحُقّ لها.\n\n* *\n\nوقوله: ﴿وَإِذَا الأرْضُ مُدَّتْ﴾\n\nيقول تعالى ذكره: وإذا الأرض بُسِطَتْ، فزيدت في سعتها.\n\nكالذي:-\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الزهريّ، عن عليّ بن حسين، أن النبي ﷺ قال: \"إذَا كَانَ يَوْمُ الْقِيَامَةِ مَدَّ اللهُ الأرْضَ حَتّى لا يَكُونَ لِبَشَرٍ مِنَ النَّاسِ إلا مَوْضِعُ قَدَمَيْهِ، فَأَكُونَ أوَّلَ مَنْ يُدْعَي، وَجِبْرِيلُ عَنْ يَمِينِ الرَّحْمَنِ، وَاللهِ ما رآهُ قَبْلَهَا، فأقُولُ يَا رَبّ إنَّ هَذَا أخْبَرَنِي أنَّكَ أرْسَلْتَهُ إليَّ، فَيَقُولُ: صَدَقَ، ثُمَّ أشْفَعُ فَأَقُولُ: يَا رَبّ عِبَادُكَ عَبَدُوكَ فِي أطْرَافِ الأرْضِ. - قال-: وَهُوَ المَقَامُ الْمَحْمُودُ\".\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿مُدَّتْ﴾ قال: يوم القيامة.\n\n* *\n\nوقوله: ﴿وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ﴾\n\nيقول جلّ ثناؤه: وألقت الأرض ما في بطنها من الموتى إلى ظهرها وتخلَّتْ منهم إلى الله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ﴾ قال: أخرجت ما فيها من الموتى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ﴾ قال: أخرجت أثقالها وما فيها.\n\n* *\n\nوقوله: ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾\n\nيقول: وسمعت الأرض في إلقائها ما في بطنها من الموتى إلى ظهرها أحياء، أمر ربها وأطاعت ﴿وَحُقَّتْ﴾ يقول: وحقَّقها الله للاستماع لأمره في ذلك، والانتهاء إلى طاعته.\n\nواختلف أهل العربية في موقع جواب قوله: ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ ، وقوله: ﴿وَإِذَا الأرْضُ مُدَّتْ﴾ فقال بعض نحويي البصرة: ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ على معنى قوله: ﴿يَاأَيُّهَا الإنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلاقِيهِ﴾ إذا السماء انشقت، على التقديم والتأخير.\n\nوقال بعض نحويي الكوفة: قال بعض المفسرين: جواب ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ قوله: ﴿وَأَذِنَتْ﴾ قال: ونرى أنه رأي ارتآه المفسر، وشبَّهه بقول الله تعالى: ﴿حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا﴾ لأنا لم نسمع جوابًا بالواو في إذا مبتدأة، ولا كلام قبلها، ولا في إذا، إذا ابتدئت. قال: وإنما تجيب العرب بالواو في قوله: حتى إذا كان، وفلما أن كان، لم يجاوزوا ذلك؛ قال: والجواب في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ وفي ﴿إِذَا الأرْضُ مُدَّتْ﴾ كالمتروك؛ لأن المعنى معروف قد تردّد في القرآن معناه، فعرف وإن شئت كان جوابه: يأيُّها الإنسان، كقول القائل: إذا كان كذا وكذا، فيأيها الناس ترون ما عملتم من خير أو شرّ، تجعل ﴿يأيُّهَا الإنسان﴾ هو الجواب، وتضمر فيه الفاء، وقد فُسَّر جواب ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ فيما يلقى الإنسان من ثواب وعقاب، فكأن المعنى: ترى الثواب والعقاب إذا السماء انشقَّتْ.\n\nوالصواب من القول في ذلك عندنا: أن جوابه محذوف ترك استغناء بمعرفة المخاطبين به بمعناه. ومعنى الكلام: ﴿إذا السماء انشقت﴾ رأى الإنسان ما قدّم من خير أو شرّ، وقد بين ذلك قوله: ﴿يَاأَيُّهَا الإنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلاقِيهِ﴾ والآياتُ بعدها.","2":1,"3":1,"4":1,"5":1,"6":"القول في تأويل قوله تعالى: ﴿يَا أَيُّهَا الإنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلاقِيهِ (٦) فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ (٧) فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا (٨) وَيَنْقَلِبُ إِلَى أَهْلِهِ مَسْرُورًا (٩) ﴾\n\n.\n\nيقول تعالى ذكره: يأيُّها الإنسان إنك عامل إلى ربك عملا فملاقيه به خيرًا كان عملك ذلك أو شرًا، يقول: فليكن عملك مما يُنجيك من سُخْطه، ويوجب لك رضاه، ولا يكن مما يُسخطه عليك فتهلك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثنى أبي، عن أبيه، عن ابن عباس ﴿يَاأَيُّهَا الإنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلاقِيهِ﴾ يقول: تعمل عملا تلقى الله به خيرًا كان أو شرًّا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَاأَيُّهَا الإنْسَانُ إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلاقِيهِ﴾ إن كدحك يا ابن آدم لضعيف، فمن استطاع أن يكون كدحه في طاعة الله فليفعل، ولا قوّة إلا بالله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا﴾ قال: عامل له عملا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد: وسمعته يقول في ذلك: ﴿إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا﴾ قال: عامل إلى ربك عملا قال: كدحا: العمل.\n\n* *\n\nوقوله: ﴿فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ﴾\n\nيقول تعالى ذكره: فأما من أعطي كتاب أعماله بيمينه ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ بأن ينظر في أعماله، فيغفر له سيئها، ويُجازى على حُسنها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل وجاء الخبر عن رسول الله ﷺ.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن وكيع، قال: ثنا جرير، عن محمد بن إسحاق، عن عبد الواحد بن حمزة، عن عباد بن عبد الله بن الزُّبير، عن عائشة، قالت: سمعت النبيّ ﷺ يقول: \"اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا\" قلت: يا رسول الله ما الحساب اليسير؟ قال: \"أن يُنْظَرَ فِي سَيِّئاتِهِ فَيُتَجَاوَزُ عَنْهُ، إنَّهُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَئِذٍ هَلَكَ\".\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن محمد بن إسحاق، قال: ثني عبد الواحد بن حمزة بن عبد الله بن الزبير، عن عباد بن عبد الله بن الزيير، عن عائشة، قالت: سمعت رسول الله ﷺ يقول في بعض صلاته: \"اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا\"، فلما انصرف قلت: يا رسول الله ما الحساب اليسير؟ قال: \"يُنْظَرُ فِي كِتَابِهِ، وَيُتَجَاوَزُ عَنْهُ، إنَّهُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَئِذٍ يا عَائِشَةُ هَلَكَ\".\n\n⁕ حدثنا نصر بن عليّ الجَهْضَمِيّ، قال: ثنا مسلم، عن الحريش بن الخرّيت أخي الزبير، عن ابن أبي مليكة، عن عائشة، قالت: من نُوقش الحساب، أو من حوسب عذّب، قال: ثم قالت: إنما الحساب اليسير: عَرْض على الله وهو يراهم.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الوهاب، قال: ثنا أيوب، وحدثني يعقوب، قال: ثنا ابن علية، قال: أخبرنا أيوب، عن ابن أبي مليكة، عن عائشة أن رسول الله ﷺ، قال: \"مَنْ حُوسِبَ يَوْمَ الْقِيَامَةِ عُذَّبَ\"، فقلت: أليس الله يقول: ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ قال: \"لَيْسَ ذَلِكَ الْحِسَابُ إنَّمَا ذلكَ العَرْضُ، وَلَكِنْ مَنْ نُوقِشَ الْحِسَابَ يَوْمَ الْقِيَامَةِ عُذِبَ\".\n\n⁕ حدثنا ابن وكيع، قال: ثنا روح بن عبادة، قال: ثنا أبو عامر الخزاز، عن ابن أبي مليكة، عن عائشة قالت: قال رسول الله ﷺ: \"إنَّهُ لَيْسَ أحَدٌ يُحَاسَبُ يَوْمَ القِيَامَةِ إلا مُعَذَّبًا\"، فقلت: أليس يقول الله: ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ ؟ قال: \"ذَلِكَ الْعَرضُ، إنَّهُ مَنْ نُوقِشَ الْحِسَابَ عُذّبَ\"، وقال بيده على أصبعه كأنه ينكته.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ قال: الحساب اليسير: الذي يغفر ذنوبه، ويتقبَّل حسناته، ويسير الحساب الذي يعفى عنه، وقرأ: ﴿وَيَخَافُونَ سُوءَ الْحِسَابِ﴾ ، وقرأ: ﴿أُولَئِكَ الَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا وَنَتَجاوَزُ عَنْ سَيِّئَاتِهِمْ فِي أَصْحَابِ الْجَنَّةِ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن عثمان بن الأسود، قال: ثني ابن أبي مليكة، عن عائشة، قالت: يا رسول الله ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ قال: \"ذَلِكَ الْعَرْضُ يَا عَائِشَةُ، مَنْ نُوقِشَ الْحِسَابَ هَلَكَ\".\n\n⁕ حدثنا ابن بشار، قال: ثنا عثمان بن عمرو وأبو داود، قالا ثنا أبو عامر الخزاز، عن ابن أبي مليكة، عن عائشة، قالت: قال رسول الله ﷺ: \" مَنْ حُوسِبَ عُذّبَ \"، قَالَتْ: فقلت: أليس الله يقول: ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ قال: \"ذَلِكَ الْعَرْضُ يَا عَائِشَةُ، وَمَنْ نُوقِشَ الحِسَابَ عُذّبَ\".\n\nإن قال قائل: وكيف قيل: ﴿فَسَوْفَ يُحَاسَبُ﴾ ، والمحاسبة لا تكون إلا من اثنين، والله القائم بأعمالهم ولا أحد له قِبَل ربه طَلِبة فيحاسبه؟ قيل: إن ذلك تقرير من الله للعبد بذنوبه، وإقرار من العبد بها وبما أحصاه كتاب عمله، فذلك المحاسبة على ما وصفنا، ولذلك قيل: يحاسب.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا ابن أبي عديّ، عن أبي يونس القشيري، عن ابن أبي مليكة، عن القاسم بن محمد، عن عائشة قالت: قال رسول الله ﷺ: \"لَيْسَ أحَدٌ يُحَاسَبُ يَوْمَ الْقِيَامَةِ إلا هَلَكَ\" قالت: فقلت: يا رسول الله ﴿فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ فقال: \"ذَلِكَ الْعَرْضُ، لَيْس أحَدٌ يُحَاسَبُ يَوْمَ الْقِيَامَةِ إلا هَلَكَ\".\n\n* *\n\nوقوله: ﴿وَيَنْقَلِبُ إِلَى أَهْلِهِ مَسْرُورًا﴾\n\nيقول: وينصرف هذا المحاسَبُ حسابًا يسيرًا إلى أهله في الجنة مسرورًا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَيَنْقَلِبُ إِلَى أَهْلِهِ مَسْرُورًا﴾ قال: إلى أهْلٍ أعدّ الله لهم الجنة.","7":6,"8":6,"9":6,"10":"القول في تأويل قوله تعالى: ﴿وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ (١٠) فَسَوْفَ يَدْعُو ثُبُورًا (١١) وَيَصْلَى سَعِيرًا (١٢) إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا (١٣) إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ (١٤) بَلَى إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا (١٥) ﴾\n\n.\n\nيقول تعالى ذكره: وأما من أعطي كتابه منكم أيها الناس يومئذ وراء ظهره، وذلك أن جعل يده اليمنى إلى عنقه وجعل الشمال من يديه وراء ظهره، فيتناول كتابه بشماله من وراء ظهره، ولذلك وصفهم جلَّ ثناؤه أحيانًا أنهم يؤتون كتبهم بشمائلهم، وأحيانًا أنهم يؤتونها من وراء ظهورهم.\n\nوبنحو الذي قلنا في ذلك أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ﴾ قال: يجعل يده من وراء ظهره.\n\n* *\n\nوقوله: ﴿فَسَوْفَ يَدْعُو ثُبُورًا﴾\n\nيقول: فسوف ينادي بالهلاك، وهو أن يقول: واثبوراه، واويلاه، وهو من قولهم: دعا فلان لهفه: إذا قال: والهفاه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nوقد ذكرنا معنى الثبور فيما مضى بشواهده، وما فيه من الرواية.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يَدْعُو ثُبُورًا﴾ قال: يدعو بالهلاك.\n\n* *\n\nوقوله: ﴿وَيَصْلَى سَعِيرًا﴾\n\nاختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء مكة والمدينة والشام: ﴿وَيُصَلَّى﴾ بضم الياء وتشديد اللام، بمعنى: أن الله يصليهم تصلية بعد تصلية، وإنضاجة بعد إنضاجة، كما قال تعالى: ﴿كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا﴾ ، واستشهدوا لتصحيح قراءتهم ذلك كذلك، بقوله: ﴿ثُمَّ الْجَحِيمَ صَلُّوهُ﴾ وقرأ ذلك بعض المدنيين وعامة قرّاء الكوفة والبصرة: ﴿وَيَصْلَى﴾ بفتح الياء وتخفيف اللام، بمعنى: أنهم يَصْلونها ويَرِدونها، فيحترقون فيها، واستشهدوا لتصحيح قراءتهم ذلك كذلك بقول الله: ﴿يَصْلَوْنَهَا﴾ و ﴿إِلا مَنْ هُوَ صَالِ الْجَحِيمِ﴾ .\n\nوالصواب من القول في ذلك عندي أنهما قراءتان معروفتان صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا﴾\n\nيقول تعالى ذكره: إنه كان في أهله في الدنيا مسرورا لما فيه من خلافه أمرَ الله، وركوبه معاصيه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا﴾ : أي في الدنيا.\n\n* *\n\nوقوله: ﴿إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ بَلَى﴾\n\nيقول تعالى ذكره: إنّ هذا الذي أُوتي كتابه وراء ظهره يوم القيامة، ظنّ في الدنيا أن لن يرجع إلينا، ولن يُبعث بعد مماته، فلم يكن يبالي ما ركب من المآثم؛ لأنه لم يكن يرجو ثوابًا، ولم يكن يخشى عقابًا، يقال منه: حار فلان عن هذا الأمر: إذا رجع عنه، ومنه الخبر الذي رُوي عن رسول الله ﷺ أنه كان يقول في دعائه: \"اللَّهُمَّ إنّي أعُوذُ بِكَ مِنَ الحَوْرِ بَعْدَ الكَوْرِ\" يعني بذلك: من الرجُوع إلى الكفر، بعد الإيمان.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ﴾ يقول: يُبعث.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ بَلَى﴾ قال: أن لا يرجع إلينا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ﴾ : أن لا مَعَادَ له ولا رجعة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿أَنْ لَنْ يَحُورَ﴾ قال: أن لن ينقلب: يقول: أن لن يبعث.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، ﴿ظَنَّ أَنْ لَنْ يَحُورَ﴾ قال: يرجع.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿أَنْ لَنْ يَحُورَ﴾ قال: أن لن ينقلب.\n\n* *\n\nوقوله: ﴿بَلَى﴾\n\nيقول تعالى ذكره: بلى لَيَحُورَنَّ وَلَيَرْجِعَنّ إلى ربه حيا كما كان قبل مماته.\n\n* *\n\nوقوله: ﴿إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا﴾\n\nيقول جلّ ثناؤه: إن ربّ هذا الذي ظن أن لن يحور، كان به بصيرا، إذ هو في الدنيا بما كان يعمل فيها من المعاصي، وما إليه يصير أمره في الآخرة، عالم بذلك كلِّه.","11":10,"12":10,"13":10,"14":10,"15":10,"16":"القول في تأويل قوله تعالى: ﴿فَلا أُقْسِمُ بِالشَّفَقِ (١٦) وَاللَّيْلِ وَمَا وَسَقَ (١٧) وَالْقَمَرِ إِذَا اتَّسَقَ (١٨) لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ (١٩) فَمَا لَهُمْ لا يُؤْمِنُونَ (٢٠) وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لا يَسْجُدُونَ (٢١) ﴾ .\n\nوهذا قَسَمٌ أقسم ربنا بالشفق، والشفق: الحمرة في الأفق من ناحية المغرب من الشمس في قول بعضهم.\n\nواختلف أهل التأويل في ذلك، فقال بعضهم: هو الحمرة كما قلنا، وممن قال ذلك جماعة من أهل العراق.\n\nوقال آخرون: هو النهار.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن إسماعيل الأحمسيّ، قال: ثنا محمد بن عبيد، قال: ثنا العوّام بن حوشب، قال: قلت لمجاهد: الشفق، قال: لا تقل الشفق، إن الشفق من الشمس، ولكن قل: حمرة الأفق.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد قوله: الشفق، قال: النهار كله.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿فَلا أُقْسِمُ بِالشَّفَقِ﴾ قال: النهار.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، مثله.\n\nوقال آخرون: الشفق: هو اسم للحمرة والبياض، وقالوا: هو من الأضداد.\n\nوالصواب من القول في ذلك عندي أن يقال: إن الله أقسم بالنهار مدبرا، والليل مقبلا. وأما الشفق الذي تَحُلّ به صلاة العشاء، فإنه للحمرة عندنا للعلة التي قد بيَّنَّاها في كتابنا كتاب الصلاة.\n\n* *\n\nوقوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾\n\nيقول: والليل وما جمع مما سكن وهدأ فيه من ذي روح كان يطير، أو يَدِب نهارًا، يقال منه: وسَقْتُه أسِقُه وَسْقا، ومنه طعام موسُوق، وهو المجموع في غرائر أو وعاء، ومنه الوَسْق، وهو الطعام المجتمع الكثير مما يُكال أو يوزن، يقال: هو ستون صاعًا، وبه جاء الخبر عن رسول الله ﷺ.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَمَا وَسَقَ﴾ يقول: وما جمع.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، عن مجاهد، عن ابن عباس في هذه الآية ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما جمع. وقال ابن عباس:\n\nمُسْتَوْسِقَاتٍ لَوْ يَجِدْنَ سَائِقَا\n\n⁕ حدثني يعقوب قال: ثنا ابن علية، عن أبي رجاء، قال: سأل حفص الحسن عن قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما جمع.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما جمع، يقول: ما آوى فيه من دابة.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ : وما لفّ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما أظلم عليه، وما أدخل فيه. وقال ابن عباس:\n\nمُسْتَوْسِقَاتٍ لَوْ يَجِدْنَ حَادِيا *\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ يقول: وما جمع من نجم أو دابة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَمَا وَسَقَ﴾ قال: وما جمع.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما جمع مجتمع فيه الأشياء التي يجمعها الله التي تأوي إليه، وأشياء تكون في الليل لا تكون في النهار ما جمع مما فيه ما يأوي إليه، فهو مما جمع.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، قال: ثنا عمرو، عن منصور، عن مجاهد: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ يقول: ما لُفّ عليه.\n\n⁕ قال: ثنا جرير، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: وما دخل فيه.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن إسرائيل، عن أبي الهيثم، عن سعيد بن جبير ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ : وما جمع.\n\n⁕ قال: ثنا وكيع، عن نافع، عن ابن عمر، عن ابن أبي مليكة، عن ابن عباس ﴿وَمَا وَسَقَ﴾ : وما جمع، ألم تسمع قول الشاعر:\n\nمُسْتَوْسِقَاتٍ لَوْ يَجِدْنَ سَائِقَا *\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة، في قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: ما حاز إذا جاء الليل.\n\nوقال آخرون: معنى ذلك: وما ساق.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عبد الله بن أحمد المَرْوَزيّ، قال: ثنا عليّ بن الحسن، قال: ثنا حسين، قال: سمعت عكرمة وسئل ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: ما ساق من ظلمة، فإذَا كان الليل، ذهب كلّ شيء إلى مأواه.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسن، عن عكرمة ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ يقول: ما ساق من ظلمة إذا جاء الليل ساق كل شيء إلى مأواه.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ قال: ما ساق معه من ظلمة إذا أقبل.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَاللَّيْلِ وَمَا وَسَقَ﴾ يعني: وما ساق الليل من شيء جمعه النجوم، ويقال: والليل وما جمع.\n\n* *\n\nوقوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾\n\nيقول: وبالقمر إذا تمّ واستوى.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ يقول: إذا استوى.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: إذا اجتمع واستوى.\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: إذا استوى.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُليّة، عن أبي رجاء، قال: سأل حفص الحسن، عن قوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: إذا اجتمع، إذا امتلأ.\n\n⁕ حدثني أبو كدينة، قال: ثنا ابن يمان، عن أشعث، عن جعفر بن أبي المغيرة، عن سعيد، في قوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: لثلاث عَشْرة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، قال: ثنا عمرو، عن منصور، عن مجاهد، مثله.\n\n⁕ قال ثنا جرير، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله ﴿إِذَا اتَّسَقَ﴾ قال: إذا استوى.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن إسرائيل، عن أبي الهيثم، عن سعيد بن جبير ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ : إذا استوى.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِذَا اتَّسَقَ﴾ : إذا استدار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ : إذا استوى.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: إذا اجتمع فاستوى.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَالْقَمَرِ إِذَا اتَّسَقَ﴾ قال: إذا استوى.\n\n* *\n\nوقوله: ﴿لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ﴾\n\nاختلفت القرّاء في قراءته، فقرأه عمر بن الخطاب وابن مسعود وأصحابه وابن عباس وعامة قرّاء مكة والكوفة ﴿لَتَرْكَبَنَّ﴾ بفتح التاء والباء. واختلف قارئو ذلك كذلك في معناه، فقال بعضهم: لَتَرْكَبنَ يا محمد أنت حالا بعد حال، وأمرًا بعد أمر من الشدائد.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا أبو بشر، عن مجاهد، أن ابن عباس كان يقرأ: ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ يعني نبيكم ﷺ حالا بعد حال.\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن عُلَيَة، قال: ثنا إسرائيل، عن أبي إسحاق، عن رجل حدّثه، عن ابن عباس في ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: منزلا بعد منزل.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ يقول: حالا بعد حال.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ﴾ يعني: منزلا بعد منزل، ويقال: أمرًا بعد أمر، وحالا بعد حال.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، قال: سمعت مجاهدًا، عن ابن عباس ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: محمد ﷺ.\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة في قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: حالا بعد حال.\n\n⁕ حدثنا ابن بشار، قال: ثنا هَوْذة، قال: ثنا عوف، عن الحسن، في قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: حالا بعد حال.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، قال: سأل حفص الحسن عن قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: منزلا عن منزل، وحالا بعد حال.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا شريك، عن موسى بن أبي عائشة، قال: سألت مرّة عن قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: حالا بعد حال.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن سعيد ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: حالا بعد حال.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: حالا بعد حال.\n\n⁕ قال ثنا وكيع، عن نصر، عن عكرِمة، قال: حالا بعد حال.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: لَتَرْكَبُنَّ الأمور حالا بعد حال.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله (لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ) يقول: حالا بعد حال، ومنزلا عن منزل.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ منزلا بعد منزل، وحالا بعد حال.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، قال: ثنا عمرو، عن منصور، عن مجاهد ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: أمرًا بعد أمر.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، في قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: أمرًا بعد أمر.\n\nوقال آخرون ممن قرأ هذه المقالة، وقرأ هذه القراءة عُنِي بذلك: لتركبنّ أنت يا محمد سماء بعد سماء.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: قال الحسن وأبو العالية ﴿لَتَرْكَبَنَّ﴾ يعني محمدًا ﷺ ﴿طَبَقًا عَنْ طَبَقٍ﴾ السموات.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن جابر، عن أبي الضحى، عن مسروق ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: أنت يا محمد سماء عن سماء.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن إسماعيل، عن الشعبيّ، قال: سماء بعد سماء.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن إسرائيل، عن جابر، عن عامر، عن علقمة، عن عبد الله، قال: سماء فوق سماء.\n\nوقال آخرون: بل معنى ذلك: لتركَبَنّ الآخرة بعد الأولى.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: الآخرة بعد الأولى.\n\nوقال آخرون ممن قرأ هذه القراءة: إنما عُنِي بذلك أنها تتغير ضروبًا من التغيير، وتُشَقَّقُ بالغمام مرّة وتحمرّ أخرى، فتصير وردة كالدهان، وتكون أخرى كالمهل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن قيس بن وهب، عن مرّة، عن ابن مسعود ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: السماء مرّة كالدِّهان، ومرّة تَشَقَّق.\n\n⁕ حدثنا ابن المثني، قال: ثنا محمد بن جعفر، قال: سمعت أبا الزرقاء الهَمْداني، وليس بأبي الزرقاء الذي يحدث في المسح على الجوربين، قال: سمعت مُرّة الهمداني، قال: سمعت عبد الله يقول في هذه الآية ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: السماء.\n\n⁕ حدثني عليّ بن سعيد الكنديّ، قال: ثنا عليّ بن غراب، عن الأعمش، عن إبراهيم، عن عبد الله في قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: هي السماء تغبرّ وتحمرّ وتَشَقَّق.\n\n⁕ حدثنا أبو السائب، قال: ثني أبو معاوية، عن الأعمش، عن إبراهيم، عن عبد الله، في قوله: ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: هي السماء تَشَقَّق، ثم تحمرّ، ثم تنفطر؛ قال: وقال ابن عباس: حالا بعد حال.\n\n⁕ حدثني يحيى بن إبراهيم المسعوديّ، قال: ثني أبي، عن أبيه، عن جدّه، عن الأعمش، عن إبراهيم قال: قرأ عبد الله هذا الحرف ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: السماء حالا بعد حال، ومنزلة بعد منزلة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن إبراهيم، عن عبد الله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ قال: هي السماء.\n\n⁕ حدثنا مهران، عن سفيان، عن أبي فروة، عن مرّة، عن ابن مسعود أنه قرأها نصبًا، قال: هي السماء.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن الأعمش، عن إبراهيم، عن عبد الله، قال: هي السماء تغير لونًا بعد لون.\n\nوقرأ ذلك عامة قرّاء المدينة وبعض الكوفيين ﴿لَتَرْكَبُنَّ﴾ بالتاء، وبضم الباء على وجه الخطاب للناس كافة أنهم يركبون أحوال الشدّة حالا بعد حال. وقد ذكر بعضهم أنه قرأ ذلك بالياء وبضم الباء، على وجه الخبر عن الناس كافة، أنهم يفعلون ذلك.\n\nوأولى القراءات في ذلك عندي بالصواب: قراءة من قرأ بالتاء وبفتح الباء، لأن تأويل أهل التأويل من جميعهم بذلك ورد وإن كان للقراءات الأخَر وجوه مفهومة. وإذا كان الصواب من القراءة في ذلك ما ذكرنا فالصواب من التأويل قول من قال ﴿لَتَرْكَبَنَّ﴾ أنت يا محمد حالا بعد حال، وأمرًا بعد أمر من الشدائد. والمراد بذلك -وإن كان الخطاب إلى رسول الله ﷺ موجهًا- جميع الناس، أنهم يلقون من شدائد يوم القيامة وأهواله أحوالا.\n\nوإنما قلنا: عُنِي بذلك ما ذكرنا أن الكلام قبل قوله ﴿لَتَرْكَبَنَّ طَبَقًا عَنْ طَبَقٍ﴾ جرى بخطاب الجميع، وكذلك بعده، فكان أشبه أن يكون ذلك نظير ما قبله وما بعده.\n\n* *\n\nوقوله: ﴿طَبَقًا عَنْ طَبَقٍ﴾\n\nمن قول العرب: وقع فلان في بنات طبق: إذا وقع في أمر شديد.\n\n* *\n\nوقوله: ﴿فَمَا لَهُمْ لا يُؤْمِنُونَ﴾\n\nيقول تعالى ذكره: فما لهؤلاء المشركين لا يصدّقون بتوحيد الله، ولا يقرّون بالبعث بعد الموت، وقد أقسم لهم ربهم بأنهم راكبون طبقًا عن طبق مع ما قد عاينوا من حججه بحقيقة توحيده.\n\n⁕ وقد حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَمَا لَهُمْ لا يُؤْمِنُونَ﴾ قال: بهذا الحديث، وبهذا الأمر.\n\n* *\n\nوقوله: ﴿وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لا يَسْجُدُونَ﴾\n\nيقول تعالى ذكره: وإذا قُرئ عليهم كتاب ربهم لا يخضعون ولا يستكينون، وقد بيَّنا معنى السجود قبلُ بشواهده، فأغنى ذلك عن إعادته.","17":16,"18":16,"19":16,"20":16,"21":16,"22":"القول في تأويل قوله تعالى: ﴿بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ (٢٢) وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ (٢٣) فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ (٢٤) إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ (٢٥) ﴾\n\n.\n\n* *\n\nقوله: ﴿بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ﴾\n\nيقول تعالى ذكره: بل الذين كفروا يكذبون بآيات الله وتنزيله.\n\n* *\n\nوقوله: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ﴾\n\nيقول تعالى ذكره: والله أعلم بما تُوعيه صدور هؤلاء المشركين من التكذيب بكتاب الله ورسوله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿يُوعُونَ﴾ قال: يكتمون.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ﴾ قال: المرءُ يُوعِي متاعه وماله هذا في هذا، وهذا في هذا، هكذا يعرف الله ما يوعون من الأعمال، والأعمال السيئة مما تُوعيه قلوبهم، ويجتمع فيها من هذه الأعمال الخير والشر، فالقلوب وعاء هذه الأعمال كلها، الخير والشرّ، يعلم ما يسرّون وما يعلنون، ولقد وَعَى لكم ما لا يدري أحد ما هو من القرآن وغير ذلك، فاتقوا الله وإياكم أن تدخلوا على مكارم هذه الأعمال بعض هذه الخبث ما يفسدها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿يُوعُونَ﴾ قال في صدورهم.\n\n* *\n\nوقوله: ﴿فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾\n\nيقول جلّ ثناؤه: فبشر يا محمد هؤلاء المكذّبين بآيات الله بعذاب أليم لهم عند الله موجع ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ يقول: إلا الذين تابوا منهم وصدّقوا، وأقرّوا بتوحيده، ونبوّة نبيه محمد ﷺ، وبالبعث بعد الممات. ﴿وعملوا الصالحات﴾ : يقول: وأدَّوا فرائض الله، واجتنبوا ركوب ما حرّم الله عليهم ركوبه.\n\n* *\n\nوقوله: ﴿لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾\n\nيقول تعالى ذكره لهؤلاء الذين آمنوا وعملوا الصالحات: ثواب غير محسوب ولا منقوص.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس قوله: ﴿لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ يقول: غير منقوص.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان عن ابن جريج، عن مجاهد، قوله: ﴿أَجْرٌ غَيْرُ مَمْنُونٍ﴾ يعني: غير محسوب.\n\nآخر تفسير سورة ﴿إذا السماء انشقَّت﴾","23":22,"24":22,"25":22},"85":{"1":"القول في تأويل قوله تعالى جل ثناؤه وتقدست أسماؤه: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ (١) وَالْيَوْمِ الْمَوْعُودِ (٢) وَشَاهِدٍ وَمَشْهُودٍ (٣) قُتِلَ أَصْحَابُ الأخْدُودِ (٤) النَّارِ ذَاتِ الْوَقُودِ (٥) ﴾ .\n\nقال أبو جعفر رحمه الله: قوله: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ أقسم الله جلّ ثناؤه بالسماء ذات البروج.\n\nواختلف أهل التأويل في معنى البروج في هذا الموضع، فقال بعضهم: عُنِي بذلك: والسماء ذات القصور. قالوا: والبروج: القصور.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثنى أبي، عن أبيه، عن ابن عباس ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ قال ابن عباس: قصور في السماء، قال غيره: بل هي الكواكب.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿الْبُرُوجِ﴾ يزعمون أنها قصور في السماء، ويقال: هي الكواكب.\n\nوقال آخرون: عُنِي بذلك: والسماء ذات النجوم، وقالوا: نجومها: بروجها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعًا، عن ابن أبي نجيح، عن مجاهد في قول الله: ﴿ذَاتِ الْبُرُوجِ﴾ قال: البروج: النجوم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ قال: النجوم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ وبروجها: نجومها.\n\nوقال آخرون: بل معنى ذلك: والسماء ذات الرمل والماء.\n\nذكر من قال ذلك:\n\n⁕ حدثني الحسن بن قزعة، قال: ثنا حصين بن نمير، عن سفيان بن حسين، في قوله: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ قال: ذات الرمل والماء.\n\nوأولى الأقوال في ذلك بالصواب أن يقال: معنى ذلك: والسماء ذات منازل الشمس والقمر، وذلك أن البروج جمع برج، وهي منازل تتخذ عالية عن الأرض مرتفعة، ومن ذلك قول الله: ﴿وَلَوْ كُنْتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ﴾ هي منازل مرتفعة عالية في السماء، وهي اثنا عشر برجًا، فمسير القمر في كلّ برج منها يومان وثلث، فذلك ثمانية وعشرون منزلا ثم يستسرّ ليلتين، ومسير الشمس في كلّ برج منها شهر.\n\n* *\n\nوقوله: ﴿وَالْيَوْمِ الْمَوْعُودِ﴾\n\nيقول تعالى ذكره: وأقسم باليوم الذي وعدته عبادي لفصل القضاء بينهم، وذلك يوم القيامة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل، وجاء الخبر عن رسول الله ﷺ.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن نمير وإسحاق الرازي، عن موسى بن عبيدة، عن أيوب بن خالد، عن عبد الله بن رافع، عن أبي هريرة، قال: قال رسول الله ﷺ: \"الْيَوْمُ الْمَوْعُودُ: يَوْمُ الْقِيَامَةِ\".\n\n⁕ قال: ثنا وكيع، عن موسى بن عبيدة، عن أيوب بن خالد، عن عبد الله بن رافع، عن أبي هريرة، عن النبيّ ﷺ، مثله.\n\n⁕ حدثنا يعقوب، قال: ثنا ابن علية، قال: ثنا يونس، قال: أنبأني عمار، قال: قال أبو هريرة: \"الْيَوْمُ الْمَوْعُودُ: يَوْمُ الْقِيَامَةِ\". قال يونس، وكذلك الحسن.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالْيَوْمِ الْمَوْعُودِ﴾ يعني: يوم القيامة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالْيَوْمِ الْمَوْعُودِ﴾ قال: القيامة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد: ﴿الْيَوْمِ الْمَوْعُودِ﴾ يوم القيامة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن يونس بن عبيد، عن عمار بن أبي عمار، مولى بني هاشم، عن أبي هريرة ﴿وَالْيَوْمِ الْمَوْعُودِ﴾ يوم القيامة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن موسى بن عبيدة، عن أيوب بن خالد، عن عبد الله بن رافع، عن أبي هريرة، عن النبيّ ﷺ: \"الْيَوْمُ الْمَوْعُودُ: يَوْمُ الْقِيَامَةِ\".\n\n⁕ حدثنا محمد بن عوف، قال: ثنا محمد بن إسماعيل بن عياش، قال: ثني أبي، قال: ثني ضمضم بن زرعة، عن شريح بن عبيد، عن أبي مالك الأشعريّ، قال: قال رسول الله ﷺ: \" ﴿الْيَوْمُ الْمَوْعُودُ﴾ يوم القيامة\".\n\n* *\n\nوقوله: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معنى ذلك: وأقسم بشاهد، قالوا: وهو يوم الجمعة، ومشهود قالوا: وهو يوم عرفة.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب قال: أخبرنا ابن علية، قال: أخبرنا يونس، قال: أنبأني عمار، قال: قال أبو هريرة: الشاهد: يوم الجمعة، والمشهود: يوم عرفة؛ قال يونس، وكذلك قال الحسن.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي إسحاق، قال: سمعت حارثة بن مضرِّب، يحدّث عن عليّ رضى الله عنه أنه قال في هذه الآية ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: يوم الجمعة، ويوم عرفة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد يوم الجمعة، والمشهود: يوم عرفة؛ ويقال: الشاهد: الإنسان، والمشهود: يوم القيامة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ : يومان عظيمان من أيام الدنيا، كنا نحدّث أن الشاهد يوم الجمعة، والمشهود يوم عرفة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد: يوم الجمعة، والمشهود: يوم عرفة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي إسحاق، عن الحارث، عن عليّ رضي الله عنه: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد يوم الجمعة، والمشهود: يوم عرفة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَشَاهِدٍ﴾ يوم الجمعة، ﴿وَمَشْهُودٍ﴾ : يوم عرفة.\n\n⁕ حدثنا أبو كريب، قال ثنا وكيع، عن موسى بن عبيدة، عن أيوب بن خالد، عن عبد الله بن رافع، عن أبي هريرة، قال: قال رسول الله ﷺ:\" وَشاَهِدٍ: يَوْمُ الْجُمُعَةِ، وَمَشْهُودٍ: يَوْمُ عَرَفَةَ\".\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن نمير وإسحاق الرازي، عن موسى بن عبيدة، عن أيوب بن خالد، عن عبد الله بن رافع، عن أبي هريرة، قال: قال رسول الله ﷺ: \" الْمَشْهُودُ: يَوْمُ عَرَفَةَ، وَالشَّاهِدُ: يَوْمُ الْجُمُعَةِ\".\n\n⁕ حدثنا سهل بن موسى، قال: ثنا ابن أبي فديك، عن ابن حرملة، عن سعيد أنه قال: قال رسول الله ﷺ: \"إنَّ سَيدَ الأيَّامِ يَوْمُ الْجُمُعَةِ، وَهُوَ الْشَّاهِدُ، وَالْمَشْهُودُ: يَوْمُ عَرَفَةَ\".\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن موسى بن عبيد، عن أيوب بن خالد، عن عبد الله بن رافع عن أبي هريرة، عن النبي ﷺ قال: \"الْمَشْهُودُ: يَوْمُ عَرَفَةَ، وَالْشَّاهِدُ: يَوْمُ الْجُمُعَةِ، فِيهِ سَاعَةٌ لا يُوَافِقُهَا مُؤْمِنٌ يَدْعُو اللهَ بِخَيْرٍ إلا اسْتَجَابَ لَهُ، وَلا يَسْتَعِيذُهُ مِنْ شَرٍّ إلا أعَاذَهُ\".\n\n⁕ حدثني محمد بن عوف، قال: ثنا محمد بن إسماعيل، قال: ثني أبي، قال: ثني ضمضم بن زرعة، عن شريح بن عبيد، عن أبي مالك الأشعري، قال: قال رسول الله ﷺ: \"إنَّ الشَّاهِدَ يَوْمُ الْجُمُعَةِ، وَإنَّ الْمَشْهُودَ يَوْمُ عَرَفَةَ، فَيَوْمُ الْجُمُعَةِ خِيَرةُ اللهِ لَنَا\".\n\n⁕ حدثني سعيد بن الربيع الرازي، قال: ثنا سفيان، عن عبد الرحمن بن حرملة، عن سعيد بن المسيب، قال: سيد الأيام يوم الجمعة، وهو شاهد.\n\nوقال آخرون: الشاهد: محمد، والمشهود: يوم القيامة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن شعبة، عن عليّ بن زيد، عن يوسف المكيّ، عن ابن عباس قال: الشاهد: محمد، والمشهود: يوم القيامة، ثم قرأ ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ وَذَلِكَ يَوْمٌ مَشْهُودٌ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن شباك، قال: سأل رجل الحسن بن عليّ، عن ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: سألتَ أحدًا قبلي؟ قال: نعم، سألت ابن عمر وابن الزبير، فقالا يوم الذبح ويوم الجمعة؛ قال: لا ولكن الشاهد: محمد، ثم قرأ: ﴿فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا﴾ والمشهود: يوم القيامة، ثم قرأ: ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ وَذَلِكَ يَوْمٌ مَشْهُودٌ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن جابر، عن أبي الضحى، عن الحسن بن عليّ، قال: الشاهد: محمد، والمشهود: يوم القيامة.\n\n⁕ حدثني سعيد بن الربيع، قال: ثنا سفيان، عن عبد الرحمن بن حَرْملة، عن سعيد بن المسيب: ﴿وَمَشْهُودٍ﴾ :يوم القيامة.\n\nوقال آخرون: الشاهد: الإنسان، والمشهود: يوم القيامة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عبيد المحاربيّ، قال: ثنا أسباط، عن عبد الملك، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد: ابن آدم، والمشهود يوم القيامة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وشاهد ومشهود﴾ قال: الإنسان، وقوله: ﴿ومشهود﴾ قال: يوم القيامة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، قال: الشاهد: الإنسان، والمشهود: يوم القيامة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن خالد الحذّاء، عن عكرِمة، في قوله: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: شاهد: ابن آدم، ومشهود: يوم القيامة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَشاَهِدٍ﴾ يعني الإنسان ﴿وَمَشْهُودٍ﴾ يوم القيامة، قال الله: ﴿وَذَلِكَ يَوْمٌ مَشْهُودٌ﴾ .\n\nوقال آخرون: الشاهد: محمد، والمشهود: يوم الجمعة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن يزيد، عن عكرِمة، في قوله: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد: محمد، والمشهود: يوم الجمعة، فذلك قوله: ﴿فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا﴾ .\n\nوقال آخرون: الشاهد: الله، والمشهود: يوم القيامة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَشَاهِدٍ﴾ يقول الله: ﴿وَمَشْهُودٍ﴾ يقول: يوم القيامة.\n\nوقال آخرون: الشاهد: يوم الأضحى، والمشهود: يوم الجمعة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن شباك، قال: سأل رجل الحسن بن عليّ، عن ﴿َشَاهِدٍ وَمَشْهُودٍ﴾ قال: سألت أحدًا قبلي؟ قال: نعم، سألت ابن عمر وابن الزبير، فقالا يوم الذبح، ويوم الجمعة.\n\nوقال آخرون: الشاهد: يوم الأضحى، والمشهود، يوم عَرَفة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، عن ابن عباس: ﴿وَشَاهِدٍ وَمَشْهُودٍ﴾ قال: الشاهد: يوم عرفة، والمشهود: يوم القيامة.\n\nوقال آخرون: المشهود: يوم الجمعة، وَرَوَوْا ذلك عن رسول الله ﷺ.\n\nذكر الرواية بذلك:\n\n⁕ حدثنا أحمد بن عبد الرحمن، قال: ثني عمي عبد الله بن وهب، قال: أخبرني عمرو بن الحارث، عن سعيد بن أبي هلال، عن زيد بن أيمن، عن عبادة بن نسيّ، عن أبي الدرداء، قال: قال رسول الله ﷺ: \"أَكْثِرُوا عَليَّ الصَّلاةَ يَوْمَ الْجُمُعَةِ، فَإِنَّهُ يَوْمٌ مَشْهُودٌ تَشْهَدُهُ الْمَلائِكَةُ\".\n\nوالصواب من القول في ذلك عندنا: أن يقال: إن الله أقسم بشاهد شهد، ومشهود شهد، ولم يخبرنا مع إقسامه بذلك أيّ شاهد وأيّ مشهود أراد، وكلّ الذي ذكرنا أن العلماء قالوا: هو المعنيّ مما يستحقّ أن يُقال له: ﴿َشَاهِدٍ وَمَشْهُودٍ﴾ .\n\n* *\n\nوقوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾\n\nيقول: لعن أصحاب الأخدود. وكان بعضهم يقول: معنى قوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ خبر من الله عن النار أنها قتلتهم.\n\nوقد اختلف أهل العلم في أصحاب الأخدود؛ من هم؟ فقال بعضهم: قوم كانوا أهل كتاب من بقايا المجوس.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القمي، عن جعفر عن ابن أبزي، قال: لما رجع المهاجرون من بعض غزواتهم، بلغهم نعي عمر بن الخطاب رضي الله عنه، فقال بعضهم لبعض: أيّ الأحكام تجري في المجوس، وإنهم ليسوا بأهل كتاب، وليسوا من مشركي العرب، فقال عليّ بن أبي طالب رضى الله عنه: قد كانوا أهل كتاب، وقد كانت الخمر أُحلَّت لهم، فشربها ملك من ملوكهم حتى ثمل منها، فتناول أخته فوقع عليها، فلما ذهب عنه السكر قال لها: ويحك، فما المخرج مما ابتليتُ به؟ فقالت: اخطب الناس، فقل: يأُّيها الناس إن الله قد أحلّ نكاح الأخوات، فقام خطيبًا، فقال: يأيُّها الناس إن الله قد أحلّ نكاح الأخوات، فقال الناس: إنا نبرأ إلى الله من هذا القول، ما أتانا به نبيٌّ، ولا وجدناه في كتاب الله، فرجع إليها نادمًا، فقال لها: ويحك، إن الناس قد أبوا عليّ أن يقرّوا بذلك، فقالت: ابسط عليهم السِّياط، ففعل، فبسط عليهم السياط، فأبَوا أن يقرّوا، فرجع إليها نادمًا، فقال: إنهم أبوا أن يقرّوا، فقالت: اخطبهم، فإن أبوا فجرّد فيهم السيف، ففعل، فأبى عليه الناس، فقال لها: قد أبى عليّ الناس، فقالت: خدّ لهم الأخدود، ثم اعرض عليها أهل مملكتك، فمن أقرّ، وإلا فاقذفه في النار، ففعل، ثم عرض عليها أهل مملكته، فمن لم يقرّ منهم قذفه في النار، فأنزل الله فيهم: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ النَّارِ ذَاتِ الْوَقُودِ﴾ إلى ﴿أَنْ يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالأرْضِ وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ حرّقوهم ﴿ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ فلم يزالوا منذ ذلك يستحلون نكاح الأخوات والبنات والأمهات.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ قال: حُدِّثنا أنّ عليّ بن أبي طالب رضي الله عنه كان يقول: هم ناس بمذارع اليمن، اقتتل مؤمنوها وكفارها، فظهر مؤمنوها على كفارها، ثم اقتتلوا الثانية، فظهر مؤمنوها على كفارها ثم أخذ بعضهم على بعض عهدًا ومواثيق أن لا يغدر بعضهم ببعض، فغدر بهم الكفار فأخذوهم أخذًا، ثم إن رجلا من المؤمنين قال لهم: هل لكم إلى خير، توقدون نارًا ثم تعرضوننا عليها، فمن تابعكم على دينكم فذلك الذي تشتهون، ومن لا اقتحم النار، فاسترحتم منه، قال: فأجَّجوا نارًا وعُرِضوا عليها، فجعلوا يقتحمونها صناديدهم، ثم بقيت منهم عجوز كأنها نكصت، فقال لها طفل في حجرها: يا أماه امضي ولا تنافقي. قصّ الله عليكم نبأهم وحديثهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ قال: يعني القاتلين الذين قتلوهم يوم قتلوا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ النَّارِ ذَاتِ الْوَقُودِ﴾ قال: هم ناس من بني إسرائيل خدّوا أخدودًا في الأرض، ثم أوقدوا فيها نارًا، ثم أقاموا على ذلك الأخدود رجالا ونساء، فعُرِضوا عليها، وزعموا أنه دانيال وأصحابه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء جميعًا، عن ابن أبي نجيح، عن مجاهد، قوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ قال: كان شقوق في الأرض بنَجْرَان كانوا يعذّبون فيها الناس.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ يزعمون أن أصحاب الأخدود من بني إسرائيل، أخذوا رجالا ونساء، فخدّوا لهم أخدودًا، ثم أوقدوا فيها النيران، فأقاموا المؤمنين عليها، فقالوا: تكفرون أو نقذفكم في النار.\n\n⁕ حدثني محمد بن معمر، قال: ثني حرمي بن عمارة، قال: ثنا حماد بن سلمة، قال: ثنا ثابت البُنانيّ، عن عبد الرحمن بن أبي ليلى، عن صهيب، قال: قال رسول الله ﷺ: \"كان فِيمَنْ كَانَ قَبْلَكُمْ مَلِكٌ، وَكَانَ لَهُ ساحِرٌ، فَأَتَى السَّاحِرُ الْمَلِكَ فَقَالَ: قَدْ كَبِرَتْ سِنِّي، وَدَنَا أجَلِي، فَادْفَعْ لِي غُلامًا أُعَلِّمْهُ السِّحْرَ \"، قال: \" فَدَفَعَ إلَيْهِ غُلامًا يُعَلِّمُهُ السِّحْرَ \"، قَالَ: \" فَكَانَ الغُلامُ يَخْتَلِفُ إلى السَّاحِرِ، وكَانَ بَيْنَ السَّاحِرِ وَبَيْنَ المَلِكِ رَاهِبٌ \"، قال: \" فَكَانَ الغُلامُ إذَا مَرَّ بالرَّاهِبِ قَعَدَ إلَيْهِ فَسَمِعَ مِنْ كَلامِهِ، فَأُعْجِبَ بِكَلامِهِ، فَكَانَ الغُلامُ إذَا أَتَى السَّاحِرَ ضَرَبَهُ وَقَالَ: مَا حَبَسَكَ؟ وَإذَا أَتَى أَهْلَهُ قَعَدَ عِنْدَ الرَّاهِبِ يَسْمَعُ كَلامَهُ، فَإذَا رَجَعَ إلى أَهْلِهِ ضَرَبُوهُ وَقَالُوا: مَا حَبَسَكَ؟ فَشَكَا ذَلِكَ إلَى الرَّاهِبِ فَقَالَ لَهُ الرَّاهِبُ: إذَا قَالَ لَكَ السَّاحِرُ: مَا حَبَسَكَ؟ قُلْ حَبَسَنِي أَهْلِي، وَإذَا قَالَ أَهْلُكَ: مَا حَبَسَكَ؟ فَقُلْ حَبَسَنِي السَّاحِرُ. فَبَيْنَمَا هُوَ كَذَلِكَ إذْ مَرَّ في طَرِيقٍ وَإذَا دَابَّةٌ عَظِيمَةٌ فِي الطَّرِيقِ قَدْ حَبَسَتِ النَّاسَ لا تَدَعُهُمْ يَجُوزُونَ، فَقَالَ الْغُلامُ: الآنَ أَعْلَمُ: أَمْرُ السَّاحِرِ أَرْضَى عِنْدَ اللهِ أَمْ أَمْرُ الرَّاهِبِ؟ قَالَ: فَأَخَذَ حَجَرًا \"، قَالَ: فَقَالَ: \" اللَّهُمْ إنْ كَانَ أمْرُ الرَّاهِبِ أحَبَّ إلَيْكَ مِنْ أَمْرِ السَّاحِرِ، فَإنِّي أَرْمِي بِحَجَرِي هَذَا فَيَقْتُلَهُ وَيَمُرُّ النَّاسُ، قَالَ: فَرَمَاهَا فَقَتَلَهَا، وَجَازَ النَّاسُ؛ فَبَلَغَ ذَلِكَ الرَّاهِبَ \"، قَالَ: وَأَتَاهُ الْغُلامُ فَقَالَ الرَّاهِبُ لِلْغُلامِ: إنَّكَ خَيْرٌ مِنِّي، وَإنِ ابْتُلِيتَ فَلا تَدُلَّنَّ عَلَيَّ \"؛ قَالَ: \" وَكَانَ الْغُلامُ يُبْرِئُ الأكْمَهَ وَالأبْرَصَ وَسَائِرَ الأدوَاءِ، وَكَانَ لِلْمَلِكِ جَلِيسٌ، قَالَ: فَعَمِيَ، قَالَ: فَقِيلَ لَهُ: إنَّ هَاهُنَا غُلامًا يُبْرِئُ الأكْمَهَ وَالأبْرَصَ وَسَائِرَ الأدْوَاءِ فَلَوْ أَتَيْتَهُ؟ قَالَ: \" فَاتَّخَذَ لَهُ هَدَايا \"؛ قَالَ: \" ثُمَّ أَتَاهُ فَقَالَ: يَا غُلامُ، إنْ أَبْرَأْتَنِي فَهَذِهِ الهَدَايَا كُلُّهَا لَكَ، فَقَالَ: مَا أَنَا بِطَبِيبٍ يشْفِيكَ، وَلَكِنَّ اللهَ يَشْفِي، فَإذَا آمَنْتَ دَعَوْتُ اللهَ أَنْ يَشْفِيَكَ \"، قَالَ: \" فَآمَنَ الأعْمَى، فَدَعَا اللهَ فَشَفَاهُ، فَقَعَدَ الأعْمَى إلى الْمَلِكِ كَمَا كَانَ يَقْعُدُ، فَقَالَ لَهُ المَلِكُ: أَلَيْسَ كُنْتَ أَعْمَى؟ قَالَ: نَعَمْ، قَالَ: فَمَنْ شَفَاكَ؟ قَالَ: رَبِّي، قَالَ: وَلَكَ رَبٌّ غَيرِي؟ قَالَ: نَعَمْ رَبِّي وَرَبُّكَ اللهُ \"، قَالَ: \" فَأَخَدَهُ بِالْعَذَابِ فَقَالَ: لَتَدُلَّنِي عَلَى مَنْ عَلَّمَكَ هَذَا \"، قَالَ: \" فَدَلَّ عَلَى الغلامِ، فَدَعَا الغُلامَ فَقَالَ: ارْجِعْ عَنْ دِينِكَ \"، قَالَ: \" فَأَبَى الْغُلامُ \"؛ قَالَ: فَأَخَذَهُ بِالْعَذَابِ \"، قَالَ: \" فَدَلَّ عَلَى الرَّاهِبِ، فَأَخَذَ الرَّاهِبَ فَقَالَ: ارْجِعْ عَنْ دِينِكِ فَأَبَى \"، قَالَ: \" فَوَضَعَ المِنْشَارَ عَلَى هَامَتِهِ فَشَقَّهُ حَتّى بَلَغَ الأرْضَ \"، قَالَ: \" وَأَخَذَ الأعْمَى فَقَالَ: لَتَرْجِعَنَّ أوْ لأقْتُلَنَّكَ \"، قَالَ: \" فَأَبَى الأعْمَى، فَوَضَعَ المِنْشَارَ عَلَى هَامَتِهِ فَشَقَّهُ حَتّى بَلَغَ الأرْضَ، ثُمَّ قَالَ لِلْغُلامِ: لَتَرْجِعَنَّ أوْ لأقْتُلَنَّكَ \"، قال: \" فَأَبَى \"، قَالَ: \" فَقَالَ: اذْهَبُوا بِهِ حَتَّى تَبْلُغُوا بِهِ ذِرْوَةَ الْجَبَلِ، فَإنْ رَجَعَ عَنْ دِينِهِ، وَإلا فَدَهْدِهُوهُ، فَلَمَّا بَلَغُوا بِه ذِرْوَةَ الْجَبَلِ فَوَقَعُوا فَمَاتُوا كُلُّهُمْ. وَجَاءَ الغُلامُ يَتَلَمَّسُ حَتّى دَخَلَ عَلَى الْمَلِكِ، فَقَالَ: أَيْنَ أصْحَابُكَ؟ قَالَ: كَفَانِيهمُ اللهُ. قَالَ: فَاذْهَبُوا بِهِ فَاحْمِلُوهُ فِي قُرْقُورٍ فَتَوَسَّطُوا بِهِ البَحْرَ، فَإنْ رَجَعَ عَنْ دِينِهِ وَإلا فَغَرِّقُوهُ \" قال: \" فَذَهَبُوا بِهِ، فَلَمَّا تَوَسَّطُوا بِهِ الْبَحْرَ قَالَ الْغُلامُ: اللَّهُمَّ اكْفِنِيهِمْ، فَانْكَفَأَتْ بِهِمُ السَّفِينَةُ. وَجَاءَ الغُلامُ يَتَلَمَّسُ حَتّى دَخَلَ عَلَى الْمَلِكِ، فَقَالَ المَلِكُ: أَيْنَ أصْحَابُكَ؟ قَالَ: دَعَوْتُ اللهَ فَكَفَانِِيهمْ، قَالَ: لأقْتُلَنَّكَ، قَالَ: مَا أَنْتَ بِقَاتِلِي حَتّى تَصْنَعَ مَا آمُرُكَ \"، قَالَ: \" فَقَالَ الْغُلامُ لِلْمَلِكِ: اجْمَعِ النَّاسَ فِي صَعِيدٍ وَاحِدٍ، ثُمَّ اصْلُبْنِي، ثُمَّ خُذْ سَهْمًا مِنْ كِنَانَتِي فَارْمِنِي وَقُلْ: باسْمِ رَبِّ الْغُلامِ فَإِنَّكَ سَتَقْتُلُنِي \"، قَالَ: \" فَجَمَعَ النَّاسَ فِي صَعِيدٍ وَاحِدٍ \"، قَالَ: \" وَصَلَبَهُ وَأَخَذَ سَهْمًا مِنْ كِنَانَتِهِ فَوَضَعَهُ فِي كَبِدِ الْقَوْسِ ثُمَّ رَمَى، فَقَالَ: باسْمِ رَبِّ الغُلامِ، فَوَقَعَ السَّهْمُ فِي صُدْغِ الْغُلامِ، فَوَضَعَ يَدَهُ هَكَذَا عَلَى صُدْغِهِ وَمَاتَ الْغُلامُ، فَقَالَ النَّاسُ: آمَنَّا بِرَبِّ الْغُلامِ، فَقَالُوا للْمَلِكِ: مَا صَنَعْتَ، الَّذي كُنْتَ تَحْذَرُ قَدْ وَقَعَ، قَدْ آمَنَ النَّاسُ، فَأَمَرَ بِأَفْوَاهِ السِّكَكِ فَأُخِذَتْ، وَخَدَّ الأخْدُودَ وضَرَّمَ فِيهِ النِّيرَانَ، وَأَخَذَهُمْ وَقَالَ: إنْ رَجَعُوا وَإلا فَأَلْقُوهُمْ فِي النَّارِ \"، قَالَ: \" فَكَانُوا يُلْقُونَهُمْ فِي النَّارِ \"، قَالَ: \" فَجَاءتِ امْرأةٌ مَعَها صَبِيٌّ لَهَا \"، قَالَ: \" فَلَمَّا ذَهَبَتْ تَقْتَحِمُ وَجَدَتْ حَرَّ النَّارِ، فَنَكَصَتْ \"، قَالَ: \" فَقَالَ لَهَا صَبِيُّهَا يا أُمَّاهُ امْضِي فَإنَّكِ عَلَى الْحَقِّ، فَاقْتَحَمَتْ فِي النَّارِ\".\n\nوقال آخرون: بل الذين أحرقتهم النار هم الكفار الذين فتنوا المؤمنين.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن عمار، عن عبد الله بن أبي جعفر، عن أبيه، عن الربيع بن أنس، قال: كان أصحاب الأخدود قومًا مؤمنين اعتزلوا الناس في الفترة، وإن جبارًا من عَبَدَة الأوثان أرسل إليهم، فعرض عليهم الدخول في دينه، فأبوا، فخدّ أخدودًا، وأوقد فيه نارًا، ثم خيرهم بين الدخول في دينه، وبين إلقائهم في النار، فاختاروا إلقاءهم في النار، على الرجوع عن دينهم، فألقوا في النار، فنجَّى الله المؤمنين الذين ألقوا في النار من الحريق، بأن قبض أرواحهم قبل أن تمسهم النار، وخرجت النار إلى من على شفير الأخدود من الكفار فأحرقتهم، فذلك قول الله: ﴿فَلَهُمْ عَذَابُ جَهَنَّمَ﴾ في الآخرة ﴿وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ في الدنيا.\n\nواختُلف في موضع جواب القسم بقوله: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ فقال بعضهم: جوابه: ﴿إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ﴾\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: وقع القسم هاهنا ﴿إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ﴾ . وقال بعض نحويي البصرة: موضع قسمها - والله أعلم - على ﴿قتل أصحاب الأخدود﴾ ، أضمر اللام كما قال: ﴿وَالشَّمْسِ وَضُحَاهَا ... قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ يريد: إن شاء الله لقد أفلح من زكَّاها، فألقى اللام، وإن شئت قلت على التقديم، كأنه قال: قتل أصحاب الأخدود، والسماء ذات البروج.\n\nوقال بعض نحويي الكوفة: يقال في التفسير: إن جواب القسم في قوله: ﴿قُتِلَ﴾ كما كان قسم ﴿وَالشَّمْسِ وَضُحَاهَا﴾ في قوله: ﴿قَدْ أَفْلَحَ﴾ هذا في التفسير، قالوا: ولم نجد العرب تدع القسم بغير لام يستقبل بها أو \"لا\" أو \"إن\" أو \"ما\"، فإن يكن ذلك كذلك، فكأنه مما ترك فيه الجواب، ثم استؤنف موضع الجواب بالخبر، كما قيل: \" يأَيُّهَا الإنسان \" في كثير من الكلام.\n\nوأولى الأقوال في ذلك عندي بالصواب قول من قال: جواب القسم في ذلك متروك، والخبر مستأنف؛ لأن علامة جواب القسم لا تحذفها العرب من الكلام إذا أجابته.\n\nوأولي التأويلين بقوله: ﴿قُتِلَ أَصْحَابُ الأخْدُودِ﴾ : لُعِنَ أصحاب الأخدود الذين ألقوا المؤمنين والمؤمنات في الأخدود.\n\nوإنما قلت: ذلك أولى التأويلين بالصواب؛ للذي ذكرنا عن الربيع من العلة، وهو أن الله أخبر أن لهم عذاب الحريق مع عذاب جهنم، ولو لم يكونوا أحرقوا في الدنيا، لم يكن لقوله: ﴿وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ معنى مفهوم، مع إخباره أن لهم عذاب جهنم؛ لأن عذاب جهنم هو عذاب الحريق مع سائر أنواع عذابها في الآخرة، والأخدود: الحفرة تحفر في الأرض.\n\n* *\n\nوقوله: ﴿النَّارِ ذَاتِ الْوَقُودِ﴾\n\nفقوله ﴿النار﴾ : ردّ على الأخدود، ولذلك خفضت، وإنما جاز ردّها عليه وهي غيره، لأنها كانت فيه، فكأنها إذ كانت فيه هو، فجرى الكلام عليه لمعرفة المخاطبين به بمعناه، وكأنه قيل: قتل أصحاب النار ذَاتِ الْوَقُودِ، ويعني بقوله: ﴿ذَاتِ الْوَقُودِ﴾ ذات الحطب الجزل، وذلك إذا فتحت الواو، فأما الوقود بضم الواو، فهو الاتقاد.","2":1,"3":1,"4":1,"5":1,"6":"القول في تأويل قوله تعالى: ﴿إِذْ هُمْ عَلَيْهَا قُعُودٌ (٦) وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ (٧) وَمَا نَقَمُوا مِنْهُمْ إِلا أَنْ يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ (٨) ﴾\n\n.\n\nيقول تعالى ذكره: النار ذات الوقود، إذ هؤلاء الكفار من أصحاب الأخدود عليها، يعني على النار، فقال عليها، والمعنى أنهم قعود على حافة الأخدود، فقيل: على النار، والمعنى: لشفير الأخدود، لمعرفة السامعين معناه.\n\nوكان قتادة يقول في ذلك ما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿النَّارِ ذَاتِ الْوَقُودِ إِذْ هُمْ عَلَيْهَا قُعُودٌ﴾ يعني بذلك المؤمنين، وهذا التأويل الذي تأوّله قتادة على مذهب من قال: قُتل أصحاب الأخدود من أهل الأيمان.\n\nوقد دلَّلْنا على أن الصواب من تأويل ذلك غير هذا القول الذي وجَّه تأويله قتادةُ قبله.\n\n* *\n\nوقوله: ﴿وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ﴾\n\nيعني: حضور.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَهُمْ عَلَى مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ﴾ يعني بذلك الكفار.\n\n* *\n\nوقوله: ﴿وَمَا نَقَمُوا مِنْهُمْ إِلا أَنْ يُؤْمِنُوا بِاللَّهِ﴾\n\nيقول تعالى ذكره: وما وجد هؤلاء الكفار الذين فتنوا المؤمنين على المؤمنين والمؤمنات بالنار في شيء، ولا فعلوا بهم ما فعلوا بسبب، إلا من أجل أنهم آمنوا بالله، وقال: ﴿إلا أن يؤمنوا بالله﴾ لأن المعنى إلا إيمانهم بالله، فلذلك حَسُنَ في موضعه ﴿يؤمنوا﴾ ، إذ كان الإيمان لهم صفة ﴿الْعَزِيزِ﴾ يقول: الشديد في انتقامه ممن انتقم منه ﴿الْحَمِيدِ﴾ يقول: المحمود بإحسانه إلى خلقه.","7":6,"8":6,"9":"القول في تأويل قوله تعالى: ﴿الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالأرْضِ وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ (٩) إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ (١٠) ﴾\n\n.\n\nيقول تعالى ذكره: الذي له سلطان السموات السبع والأرضين وما فيهنّ ﴿وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ﴾ يقول تعالى ذكره: والله على فِعْل هؤلاء الكفار من أصحاب الأخدود بالمؤمنين الذين فتنوهم شاهد، وعلى غير ذلك من أفعالهم وأفعال جميع خلقه، وهو مجازيهم جزاءهم.\n\n* *\n\nوقوله: ﴿إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾\n\nيقول: إن الذين ابْتَلَوُا المؤمنين والمؤمنات بالله بتعذيبهم، وإحراقهم بالنار.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثنى أبي، عن أبيه، عن ابن عباس ﴿إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ حرّقوا المؤمنين والمؤمنات.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿إِنَّ الَّذِينَ فَتَنُوا﴾ قَالَ: عَذَّبُوا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ قال: حرّقوهم بالنار.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ يقول: حرّقوهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن ابن أبزى ﴿إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ حرّقوهم.\n\n* *\n\nوقوله: ﴿ثُمَّ لَمْ يَتُوبُوا﴾\n\nيقول: ثم لم يتوبوا من كفرهم وفعلهم الذي فعلوا بالمؤمنين والمؤمنات من أجل إيمانهم بالله ﴿فَلَهُمْ عَذَابُ جَهَنَّمَ﴾ في الآخرة ﴿وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ في الدنيا.\n\nكما:-\n\n⁕ حُدثت عن عمار، قال: ثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع ﴿فَلَهُمْ عَذَابُ جَهَنَّمَ﴾ في الآخرة ﴿وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ في الدنيا.","10":9,"11":"القول في تأويل قوله تعالى: ﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأنْهَارُ ذَلِكَ الْفَوْزُ الْكَبِيرُ (١١) إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ (١٢) ﴾\n\n.\n\nيقول تعالى ذكره: إن الذين أقرّوا بتوحيد الله، وهم هؤلاء القوم الذين حرّقهم أصحاب الأخدود وغيرهم من سائر أهل التوحيد ﴿وَعَمِلُوا الصَّالِحَاتِ﴾ يقول: وعملوا بطاعة الله، وأْتَمروا لأمره، وانتهَوْا عما نهاهم عنه ﴿لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأنْهَارُ﴾ يقول: لهم في الآخرة عند الله بساتين تجري من تحتها الأنهار والخمر واللبن والعسل ﴿ذَلِكَ الْفَوْزُ الْكَبِيرُ﴾ يقول: هذا الذي هو لهؤلاء المؤمنين في الآخرة، هو الظفر الكبير بما طلبوا والتمسوا بإيمانهم بالله في الدنيا، وعملهم بما أمرهم الله به فيها ورضيه منهم.\n\n* *\n\nوقوله: ﴿إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: إن بطش ربك يا محمد لمن بطش به من خلقه، وهو انتقامه ممن انتقم منه لشديد، وهو تحذير من الله لقوم رسوله محمد ﷺ، أن يُحلّ بهم من عذابه ونقمته، نظير الذي حلّ بأصحاب الأخدود على كفرهم به، وتكذيبهم رسوله، وفتنتهم المؤمنين والمؤمنات منهم.","12":11,"13":"القول في تأويل قوله تعالى: ﴿إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ (١٣) وَهُوَ الْغَفُورُ الْوَدُودُ (١٤) ذُو الْعَرْشِ الْمَجِيدُ (١٥) فَعَّالٌ لِمَا يُرِيدُ (١٦) هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ (١٧) فِرْعَوْنَ وَثَمُودَ (١٨) ﴾\n\n.\n\nاختلف أهل التأويل في معنى قوله: ﴿إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ﴾ فقال بعضهم: معنى ذلك: إن الله أبدى خلقه، فهو يبتدئ، بمعنى: يحدث خلقه ابتداء، ثم يميتهم، ثم يعيدهم أحياء بعد مماتهم، كهيئتهم قبل مماتهم.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يُبْدِئُ وَيُعِيدُ﴾ يعني: الخلق.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يُبْدِئُ وَيُعِيدُ﴾ قال: يُبْدِئُ الخلق حين خلقه، ويعيده يوم القيامة.\n\nوقال آخرون: بل معنى ذلك: إنه هو يُبْدِئُ العذاب ويعيده.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ﴾ قال: يُبْدِئُ العذاب ويعيده.\n\nوأولى التأويلين في ذلك عندي بالصواب، وأشبههما بظاهر ما دلّ عليه التنزيل القولُ الذي ذكرناه عن ابن عباس، وهو أنه يُبْدِئُ العذاب لأهل الكفر به ويعيد، كما قال جلّ ثناؤه: ﴿فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ﴾ في الدنيا، فأبدأ ذلك لهم في الدنيا، وهو يعيده لهم في الآخرة.\n\nوإنما قلت: هذا أولى التأويلين بالصواب؛ لأن الله أتبع ذلك قوله: ﴿إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ﴾ فكان للبيان عن معنى شدّة بطشه الذي قد ذكره قبله، أشبه به بالبيان عما لم يَجْرِ له ذكر، ومما يؤيد ما قلنا من ذلك وضوحًا وصحة قوله: ﴿وَهُوَ الْغَفُورُ الْوَدُودُ﴾ فبيَّن ذلك عن أن الذي قبله من ذكر خبره عن عذابه وشدّة عقابه.\n\n* *\n\nوقوله: ﴿وَهُوَ الْغَفُورُ الْوَدُودُ﴾\n\nيقول تعالى ذكره: وهو ذو المغفرة لمن تاب إليه من ذنوبه، وذو المحبة له.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿الْغَفُورُ الْوَدُودُ﴾ يقول: الحبيب.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿الْغَفُورُ الْوَدُودُ﴾ قال: الرحيم.\n\n* *\n\nوقوله: ﴿ذُو الْعَرْشِ الْمَجِيدُ﴾\n\nيقول تعالى ذكره: ذو العرش الكريم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿ذُو الْعَرْشِ الْمَجِيدُ﴾ يقول: الكريم.\n\nواختلفت القرّاء في قراءة قوله: ﴿الْمَجِيدُ﴾ فقرأته عامة قرّاء المدينة ومكة والبصرة وبعض الكوفيين رفعًا، ردًّا على قوله: ﴿ذُو الْعَرْشِ﴾ على أنه من صفة الله تعالى ذكره. وقرأ ذلك عامه قرّاء الكوفة خفضًا، على أنه من صفة العرش.\n\nوالصواب من القول في ذلك عندنا أنهما قراءتان معروفتان، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿فَعَّالٌ لِمَا يُرِيدُ﴾\n\nيقول: هو غفار لذنوب من شاء من عباده إذا تاب وأناب منها، معاقب من أصرّ عليها وأقام، لا يمنعه مانع، مِنْ فِعْل أراد أن يفعله، ولا يحول بينه وبين ذلك حائل، لأن له مُلك السموات والأرض، وهو العزيز الحكيم.\n\n* *\n\nوقوله: ﴿هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: هل جاءك يا محمد حديث الجنود الذين تجندوا على الله ورسوله بأذاهم ومكروههم؛ يقول: قد أتاك ذلك وعلمته، فاصبر لأذى قومك إياك لما نالوك به من مكروه كما صبر الذين تجند هؤلاء الجنود عليهم من رسلي، ولا يثنيك عن تبليغهم رسالتي، كما لم يُثْن الذين أرسلوا إلى هؤلاء، فإن عاقبة من لم يصدقك ويؤمن بك منهم إلى عطب وهلاك، كالذي كان من هؤلاء الجنود، ثم بين جلّ ثناؤه عن الجنود من هم، فقال: ﴿فِرْعَوْنَ وَثَمُودَ﴾ يقول: ﴿فرعون﴾ ، فاجتزى بذكره، إذ كان رئيس جنده من ذكر جنده وأتباعه. وإنما معنى الكلام: هل أتاك حديث الجنود، فرعون وقومه وثمود، وخفض فرعون ردًّا على الجنود، على الترجمة عنهم، وإنما فتح لأنه لا يجرى وثمود.","14":13,"15":13,"16":13,"17":13,"18":13,"19":"القول في تأويل قوله تعالى: ﴿بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ (١٩) وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ (٢٠) بَلْ هُوَ قُرْآنٌ مَجِيدٌ (٢١) فِي لَوْحٍ مَحْفُوظٍ (٢٢) ﴾\n\n.\n\nيقول تعالى ذكره: ما بهؤلاء القوم الذين يكذّبون بوعيد الله أنهم لم يأتهم أنباء من قبلهم من الأمم المكذّبة رسل الله كفرعون وقومه، وثمود وأشكالهم، وما أحلّ الله بهم من النقم بتكذيبهم الرسل، ولكنهم في تكذيبهم بوحي الله وتنزيله، إيثارًا منهم لأهوائهم، واتِّباعًا منهم لسنن آبائهم ﴿وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ﴾ بأعمالهم مُحْصٍ لها، لا يخفى عليه منها شيءٌ، وهو مجازيهم على جميعها.\n\n* *\n\nوقوله: ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ﴾\n\nيقول - تكذيبا منه جلّ ثناؤه للقائلين للقرآن هو شعر وسجع -: ما ذلك كذلك، بل هو قرآن كريم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ﴾ يقول: قرآن كريم.\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن يمان، عن أشعث بن إسحاق، عن جعفر، عن سعيد، في قوله: ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ﴾ قال: كريم.\n\n* *\n\nوقوله: ﴿فِي لَوْحٍ مَحْفُوظٍ﴾\n\nيقول تعالى ذكره: هو قرآن كريم مُثْبَت في لوح محفوظ.\n\nواختلفت القرّاء في قراءة قوله: ﴿مَحْفُوظٍ﴾ فقرأ ذلك مَن قرأه مِن أهل الحجاز أبو جعفر القارئ وابن كثير، ومن قرأه من قرّاء الكوفة عاصم والأعمش وحمزة والكسائي، ومن البصريين أبو عمرو ﴿محفوظٍ﴾ خفضًا على معنى أن اللوح هو المنعوت بالحفظ. وإذا كان ذلك كذلك كان التأويل: في لوح محفوظ من الزيادة فيه والنقصان منه عما أثبته الله فيه. وقرأ ذلك من المكِّيين ابن مُحَيْصِن، ومن المدنيين نافع ﴿مَحْفُوظٌ﴾ رفعًا، ردًّا على القرآن، على أنه من نعته وصفته. وكان معنى ذلك على قراءتهما: ﴿بل هو قرآن مجيد﴾ محفوظ من التغيير والتبديل في لوح.\n\nوالصواب من القول في ذلك عندنا أنهما قراءتان معروفتان في قرأة الأمصار، صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب. وإذا كان ذلك كذلك، فبأيّ القراءتين قرأ القارئ، فتأويل القراءة التي يقرؤها على ما بيَّنا.\n\n⁕ وقد حدثنا محمد بن بشار، قال: ثنا يحيى، قال: ثنا سفيان عن منصور، عن مجاهد ﴿فِي لَوْحٍ﴾ قال: في أمّ الكتاب.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فِي لَوْحٍ مَحْفُوظٍ﴾ عند الله.\n\nوقال آخرون: إنما قيل محفوظ لأنه في جبهة إسرافيل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عمرو بن عليّ، قال: سمعت قرة بن سليمان، قال: ثنا حرب بن سريج، قال: ثنا عبد العزيز بن صهيب، عن أنس بن مالك، في قوله: ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ فِي لَوْحٍ مَحْفُوظٍ﴾ قال: إن اللوح المحفوظ الذي ذكر الله، ﴿بَلْ هُوَ قُرْآنٌ مَجِيدٌ فِي لَوْحٍ مَحْفُوظٍ﴾ في جَبْهَة إسرافيل.\n\nآخر تفسير سورة البروج","20":19,"21":19,"22":19},"86":{"1":"القول في تأويل قوله تعالى: ﴿وَالسَّمَاءِ وَالطَّارِقِ (١) وَمَا أَدْرَاكَ مَا الطَّارِقُ (٢) النَّجْمُ الثَّاقِبُ (٣) إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ (٤) فَلْيَنْظُرِ الإنْسَانُ مِمَّ خُلِقَ (٥) خُلِقَ مِنْ مَاءٍ دَافِقٍ (٦) يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ (٧) إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ (٨) يَوْمَ تُبْلَى السَّرَائِرُ (٩) فَمَا لَهُ مِنْ قُوَّةٍ وَلا نَاصِرٍ (١٠) ﴾\n\n.\n\nأقسم ربنا بالسماء وبالطارق الذي يطرق ليلا من النجوم المضيئة، ويخفى نهارًا، وكل ما جاء ليلا فقد طرق.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَالسَّمَاءِ وَالطَّارِقِ﴾ قال: السماء وما يطرق فيها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالسَّمَاءِ وَالطَّارِقِ وَمَا أَدْرَاكَ مَا الطَّارِقُ﴾ قال: طارق يطرق بليل، ويخفى بالنهار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالطَّارِقِ﴾ قال: ظهور النجوم، يقول: يطرقك ليلا.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿الطَّارِقِ﴾ النجم.\n\n﴿وَمَا أَدْرَاكَ مَا الطَّارِقُ﴾ يقول تعالى ذكره لنبيه محمد ﷺ: وما أشعرك يا محمد ما الطارق الذي أقسمتُ به، ثم بين ذلك جلّ ثناؤه، فقال: هو النجم الثاقب، يعني: يتوقد ضياؤه ويتوهَّج.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿النَّجْمُ الثَّاقِبُ﴾ يعني: المضيء.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿النَّجْمُ الثَّاقِبُ﴾ قال: هي الكواكب المضيئة، وثقوبه: إذا أضاء.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن يزيد، عن عكرِمة، في قوله: ﴿النَّجْمُ الثَّاقِبُ﴾ قال: الذي يثقب.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿الثَّاقِبُ﴾ قال: الذي يتوهَّج.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة: ثقوبه: ضوءه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿النَّجْمُ الثَّاقِبُ﴾ : المضيء.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿النَّجْمُ الثَّاقِبُ﴾ قال: كانت العرب تسمِّي الثُّريا النجم، ويقال: إن الثاقبَ النجمُ الذي يقال له زُحَلْ. والثاقب أيضًا: الذي قد ارتفع على النجوم، والعرب تقول للطائر - إذا هو لحق ببطن السماء ارتفاعًا -: قد ثَقَبَ، والعرب تقول: أثقِب نارك: أي أضئها.\n\n* *\n\nوقوله: ﴿إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ﴾\n\nاختلفت القرّاء في قراءة ذلك، فقرأه من قرّاء المدينة أبو جعفر، ومن قرّاء الكوفة حمزة ﴿لَمَّا عَلَيْهَا﴾ بتشديد الميم. وذُكِر عن الحسن أنه قرأ ذلك كذلك.\n\n⁕ حدثني أحمد بن يوسف، قال: ثنا أبو عبيد، قال: ثنا حجاج، عن هارون، عن الحسن أنه كان يقرؤها ﴿إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ﴾ مشدّدة، ويقول: إلا ليها حافظ، وهكذا كلّ شيءٍ في القرآن بالتثقيل. وقرأ ذلك من أهل المدينة نافع، ومن أهل البصرة أبو عمرو: ﴿لَمَا﴾ بالتخفيف، بمعنى: إن كلّ نفس لعليها حافظ، وعلى أن اللام جواب\" إن\" و\" ما\" التي بعدها صلة. وإذا كان ذلك كذلك لم يكن فيه تشديد.\n\nوالقراءة التي لا أختار غيرَها في ذلك التخفيف، لأن ذلك هو الكلام المعروف من كلام العرب، وقد أنكر التشديد جماعةٌ من أهل المعرفة بكلام العرب؛ أن يكون معروفًا من كلام العرب، غير أن الفرّاء كان يقول: لا نعرف جهة التثقيل في ذلك، ونرى أنها لغةٌ في هذيلٍ، يجعلون \" إلا \" مع \" إن المخففة \": لَمَّا، ولا يجاوزون ذلك، كأنه قال: ما كلّ نفس إلا عليها حافظ، فإن كان صحيحًا ما ذكر الفرّاء من أنها لغة هُذَيلٍ، فالقراءة بها جائزةٌ صحيحةٌ، وإن كان الاختيار أيضًا - إذا صحّ ذلك عندنا - القراءة الأخرى وهي التخفيف؛ لأن ذلك هو المعروف من كلام العرب، ولا ينبغي أن يُترك الأعرف إلى الأنكر.\n\n⁕ وقد حدثني أحمد بن يوسف، قال: ثنا أبو عبيد، قال: ثنا معاذ، عن ابن عون، قال: قرأت عند ابن سيرين: ﴿إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ﴾ فأنكره، وقال: سبحان الله، سبحان الله.\n\nفتأويل الكلام إذن: إن كلّ نفس لعليها حافظ من ربها، يحفظ عملها، ويُحصي عليها ما تكسب من خير أو شرّ.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿إنْ كُلُّ نَفْسٍ لَمَا عَلَيْهَا حَافِظٌ﴾ قال: كلّ نفس عليها حفظة من الملائكة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إنْ كُلُّ نَفْسٍ لَمَا عَلَيْهَا حَافِظٌ﴾ : حفظة يحفظون عملك ورزقك وأجلك، إذا توفيته يا ابن آدم قُبِضت إلى ربك.\n\n* *\n\nوقوله: ﴿فَلْيَنْظُرِ الإنْسَانُ مِمَّ خُلِقَ﴾\n\nيقول تعالى ذكره: فلينظر الإنسان المكذّب بالبعث بعد الممات، المُنكر قُدرة الله على إحيائه بعد مماته، ﴿مِمَّ خُلِقَ﴾ يقول: من أيّ شيءٍ خلقه ربه، ثم أخبر جلّ ثناؤه عما خلقه منه، فقال: (خُلِقَ مِنْ مَاءٍ دَافِقٍ) يعني: من ماء مدفوق، وهو مما أخرجته العرب بلفظ فاعل، وهو بمعنى المفعول، ويقال: إن أكثر من يستعمل ذلك من أحياء العرب سكان الحجاز إذا كان في مذهب النعت، كقولهم: هذا سرٌّ كاتم وهمٌّ ناصب، ونحو ذلك.\n\n* *\n\nوقوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾\n\nيقول: يخرج من بين ذلك، ومعنى الكلام: منهما، كما يقال: سيخرج من بين هذين الشيئين خير كثير، بمعنى: يخرج منهما.\n\nواختلف أهل التأويل في معنى الترائب وموضعها، فقال بعضهم: الترائب: موضع القلادة من صدر المرأة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عبد الرحمن بن الأسود الطفاويّ، قال: ثنا محمد بن ربيعة، عن سَلَمَة بن سابور، عن عطية العَوْفِيّ، عن ابن عباس ﴿الصُّلْبِ وَالتَّرَائِبِ﴾ قال: الترائب: موضع القِلادة.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ يقول: من بين ثدي المرأة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، قال: سُئل عكرِمة عن الترائب، فقال: هذه، ووضع يده على صدره بين ثدييه.\n\n⁕ حدثني ابن المثنى، قال: ثني سلم بن قتيبة، قال: ثني عبد الله بن النُّعمان الحُدَانيّ، أنه سمع عكرِمة يقول: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: صُلْب الرجل، وترائب المرأة.\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن يمان، عن شريك، عن عطاء، عن سعيد بن جبير، قال: الترائب الصدر.\n\n⁕ قال: ثنا ابن يمان، عن مِسْعَر، عن الحكم، عن أبي عياض، قال: ﴿التَّرَائِبِ﴾ : الصدر.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: الترائب: الصدر. وهذا الصلب وأشار إلى ظهره.\n\nوقال آخرون: الترائب: ما بين المنكبين والصدر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن يمان، عن إسرائيل، عن ثُوَير، عن مجاهد، قال: ﴿الترائِبِ﴾ ما بين المنكبين والصدر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿التَّرَائِبِ﴾ قال: أسفل من التراقي.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: الصُّلْب للرجل، والترائب للمرأة، والترائب فوق الثديين.\n\nوقال آخرون: هو اليدان والرجلان والعينان.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: فالترائب أطراف الرجل واليدان والرجلان والعينان، فتلك الترائب.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي رَوْق، عن الضحاك ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: الترائب: اليدان والرجلان.\n\n⁕ قال: ثنا مهران، عن سفيان، قال: قال غيره: الترائب: ماء المرأة وصلب الرجل.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ : عيناه ويداه ورجلاه.\n\nوقال آخرون: معنى ذلك، أنه يخرج من بين صلب الرجل ونحره.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ يقول: يخرج من بين صلب الرجل ونحره.\n\nوقال آخرون: هي الأضلاع التي أسفل الصلب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، في قوله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: الترائب: الأضلاع التي أسفل الصلب.\n\nوقال آخرون: هي عصارة القلب.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن إسحاق، قال: ثنا أبو صالح، قال: ثني الليث، أن معمر بن أبي حَبِيبة المَدِيني حدّثه، أنه بلغه في قول الله: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ قال: هو عُصَارة القلب، ومنه يكون الولد.\n\nوالصواب من القول في ذلك عندنا، قولُ من قال: هو موضع القِلادة من المرأة، حيث تقع عليه من صدرها؛ لأن ذلك هو المعروف في كلام العرب، وبه جاءت أشعارهم، قال المثقَّب العبدي:\n\nوَمِنْ ذَهَبٍ يُسَنُّ عَلَى تَرِيبٍ ... كَلَوْنِ العَاجِ لَيْسَ بِذِي غُضُونِ\n\nوقال آخر:\n\nوَالزَّعْفَرَانُ عَلَى تَرَائِبِهَا شَرِقا ... بِهِ اللَّبَّاُت والنَّحْرُ\n\n* *\n\nوقوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾\n\nيقول تعالى ذكره: إن هذا الذي خلقكم أيها الناس من هذا الماء الدافق، فجعلكم بشرًا سويًا، بعد أن كنتم ماء مدفوقًا، على رجعه لقادر.\n\nواختلف أهل التأويل في الهاء التي في قوله: ﴿عَلَى رَجْعِهِ﴾ على ما هي عائدةٌ، فقال بعضهم: هي عائدة على الماء. وقالوا: معنى الكلام: إن الله على ردّ النطفة في الموضع التي خرجت منه ﴿لَقَادِرٌ﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، عن عكرِمة، في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: إنه على رَدّه في صُلْبه لقادر.\n\n⁕ حدثنا ابن المثنى، قال: ثنا أبو النعمان الحكم بن عبد الله، قال: ثنا شعبة، عن أبي رجاء، عن عكرمة في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: لِلصُّلب.\n\n⁕ حدثني عبيد بن إسماعيل الهباري، قال: ثنا عبد الرحمن بن محمد المحاربيّ، عن ليث، عن مجاهد، في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: على أن يرد الماء في الإحليل.\n\n⁕ حدثني نصر بن عبد الرحمن الأوْدِيّ الوشاء، قال: ثنا أبو قَطَن عمرو بن الهيثم، عن ورقاء، عن عبد الله بن أبي نجيح، عن عبد الله بن أبي بكر، عن مجاهد، في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: على ردّ النطفة في الإحليل.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: في الإحليل.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ليث، عن مجاهد ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: ردّه في الإحليل.\n\nوقال آخرون: بل معنى ذلك: إنه على ردّ الإنسان ماءً كما كان قبل أن يخلقه منه.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ إن شئتُ رددتُه كما خلقته من ماءٍ.\n\nوقال آخرون: بل معنى ذلك: إنه على حبس ذلك الماء لقادرٌ.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ قال: على رجع ذلك الماء لقادرٌ، حتى لا يخرج، كما قدر على أن يخلق منه ما خلق قادر على أن يرجعه.\n\nوقال آخرون: بل معنى ذلك أنه قادر على رجع الإنسان من حال الكبر إلى حال الصغر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن مقاتل بن حيان، عن الضحاك قال: سمعته يقول في قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ يقول: إن شئتُ رددته من الكبر إلى الشباب، ومن الشباب إلى الصِّبا، ومن الصبا إلى النطفة. وعلى هذا التأويل تكون الهاء في قوله: ﴿عَلَى رَجْعِهِ﴾ من ذكر الإنسان.\n\nوقال آخرون، ممن زعم أن الهاء للإنسان: معنى ذلك أنه على إحيائه بعد مماته لقادر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ إن الله تعالى ذكره على بعثه وإعادته قادر.\n\nوأولى الأقوال في ذلك بالصواب قول من قال: معنى ذلك: إن الله على ردّ الإنسان المخلوق من ماء دافق من بعد مماته حيًّا، كهيئته قبل مماته لقادر.\n\nوإنما قلت: هذا أولى الأقوال في ذلك بالصواب؛ لقوله: ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾ فكان في إتباعه قوله: ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾ نبأ من أنباء القيامة، دلالة على أن السابق قبلها أيضًا منه، ومنه ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾ يقول تعالى ذكره: إنه على إحيائه بعد مماته لقادر يوم تُبلى السرائر، فاليوم من صفة الرجع، لأن المعنى: إنه على رجعه يوم تبلى السرائر لقادر.\n\nوَعُنِي بقوله: ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾\n\nيوم تُخْتَبَرُ سرائر العباد، فيظهر منها يومئذ ما كان في الدنيا مستخفيًا عن أعين العباد من الفرائض التي كان الله ألزمه إياها، وكلَّفه العمل بها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن عبد الله بن صالح، عن يحيى بن أيوب، عن ابن جريج، عن عطاء بن أبي رباح، في قوله: ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾ قال: ذلك الصوم والصلاة وغسل الجنابة، وهو السرائر، ولو شاء أن يقول: قد صُمْتُ، وليس بصائم، وقد صلَّيتُ، ولم يصلّ، وقد اغتسلت، ولم يغتسل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾ إن هذه السرائر مختبرة، فأسِرّوا خيرًا وأعلنوه إن استطعتم، ولا قوّة إلا بالله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾ قال: تُخْتَبَر.\n\n* *\n\nوقوله: ﴿فَمَا لَهُ مِنْ قُوَّةٍ وَلا نَاصِرٍ﴾\n\nيقول تعالى ذكره: فما للإنسان الكافر يومئذ من قوّة يمتنع بها من عذاب الله، وأليم نكاله، ولا ناصر ينصره فيستنقذه ممن ناله بمكروه، وقد كان في الدنيا يرجع إلى قوّةٍ من عشيرته، يمتنع بهم ممن أراده بسوءٍ، وناصرٍ من حليفٍ ينصره على من ظلمه واضطهده.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَمَا لَهُ مِنْ قُوَّةٍ وَلا نَاصِرٍ﴾ ينصره من الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَلا نَاصِرٍ﴾ قال: من قوّة يمتنع بها، ولا ناصر ينصره من الله.\n\n⁕ حدثني عليّ بن سهل، قال: ثنا ضَمْرة بن ربيعة، عن سفيان الثوري، في قوله: ﴿مِنْ قُوَّةٍ وَلا نَاصِرٍ﴾ قال: القوّة: العشيرة، والناصر: الحليف.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1,"10":1,"11":"القول في تأويل قوله تعالى: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ (١١) وَالأرْضِ ذَاتِ الصَّدْعِ (١٢) إِنَّهُ لَقَوْلٌ فَصْلٌ (١٣) وَمَا هُوَ بِالْهَزْلِ (١٤) إِنَّهُمْ يَكِيدُونَ كَيْدًا (١٥) وَأَكِيدُ كَيْدًا (١٦) فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا (١٧) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ ترْجع بالغيوم وأرزاق العباد كلّ عام؛ ومنه قول المتنخِّل في صفة سيف:\n\nأبْيَضُ كالرَّجْعِ رَسُوبٌ إذَا ... مَا ثَاخَ فِي مُحْتَفَلٍ يَخْتَلِي\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، قال: ثنا سفيان، عن خصيف، عن عكرِمة، عن ابن عباس: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: السحاب فيه المطر.\n\n⁕ حدثنا عليّ بن سهل، قال: ثنا مؤمل، قال: ثنا سفيان، عن خَصِيف، عن عكرِمة، عن ابن عباس في قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: ذات السحاب فيه المطر.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ يعني بالرجع: القطر والرزق كلّ عام.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، عن الحسن، في قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: ترجع بأرزاق الناس كلّ عام؛ قال أبو رجاء: سُئل عنها عكرِمة، فقال: رجعت بالمطر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ذَاتِ الرَّجْعِ﴾ قال: السحاب يمطر، ثم يَرجع بالمطر.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: ترجع بأرزاق العباد كلّ عام، لولا ذلك هلَكوا، وهلَكت مواشيهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: ترجع بالغيث كلّ عام.\n\n⁕ حُدثت عن الحسين: قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ يعني: المطر.\n\nوقال آخرون: يعني بذلك: أن شمسها وقمرها يغيب ويطلُع.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ قال: شمسها وقمرها ونجومها يأتين من هاهنا.\n\n* *\n\nوقوله: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾\n\nيقول تعالى ذكره: والأرض ذات الصدع بالنبات.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن خَصِيف، عن عكرِمة، عن ابن عباس ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ قال: ذات النبات.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ يقول: صدعها إخراج النبات في كلّ عام.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَيَة، عن أبي رجاء، عن الحسن ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ قال: هذه تصدع عما تحتها؛ قال أبو رجاء: وسُئل عنها عكرِمة، فقال: هذه تصدع عن الرزق.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، عن ابن أبي نجيح، قال مجاهد: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ مثل المأزم مأزم منى.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ قال: الصدع: مثل المأزم، غير الأودية وغير الجُرُف.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ تصدع عن الثمار وعن النبات كما رأيتم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ قال: تصدع عن النبات.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ وقرأ: ﴿ثُمَّ شَقَقْنَا الأرْضَ شَقًّا فَأَنْبَتْنَا فِيهَا حَبًّا وَعِنَبًا وَقَضْبًا﴾ إلى آخر الآية، قال: صدعها للحرث.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالأرْضِ ذَاتِ الصَّدْعِ﴾ :النبات.\n\n* *\n\nوقوله: ﴿إِنَّهُ لَقَوْلٌ فَصْلٌ﴾\n\nيقول تعالى ذكره: إن هذا القول وهذا الخبر لقول فصل: يقول: لقول يفصل بين الحقّ والباطل ببيانه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في العبارة عنه، فقال بعضهم: لقول حقّ. وقال بعضهم: لقول حكم.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّهُ لَقَوْلٌ فَصْلٌ﴾ يقول: حقّ.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّهُ لَقَوْلٌ فَصْلٌ﴾ :أي حُكْم.\n\n* *\n\nوقوله: ﴿وَمَا هُوَ بِالْهَزْلِ﴾\n\nيقول: وما هو باللعب ولا الباطل.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَمَا هُوَ بِالْهَزْلِ﴾ يقول: بالباطل.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَمَا هُوَ بِالْهَزْلِ﴾ قال: باللعب.\n\n* *\n\nوقوله: ﴿إِنَّهُمْ يَكِيدُونَ كَيْدًا﴾\n\nيقول تعالى ذكره: إن هؤلاء المكذّبين بالله ورسوله والوعد والوعيد يمكرون مكرًا.\n\n* *\n\nوقوله: ﴿وَأَكِيدُ كَيْدًا﴾\n\nيقول: وأمكر مكرًا؛ ومكره جلّ ثناؤه بهم: إملاؤه إياهم على معصيتهم وكفرهم به.\n\n* *\n\nوقوله: ﴿فَمَهِّلِ الْكَافِرِينَ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: فمهِّل يا محمد الكافرين ولا تعجل عليهم ﴿أَمْهِلْهُمْ رُوَيْدًا﴾ يقول: أمهلهم آنًا قليلا وأنظرهم للموعد الذي هو وقت حلول النقمة بهم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثنا معاوية، عن عليّ، عن ابن عباس، قوله: ﴿أَمْهِلْهُمْ رُوَيْدًا﴾ يقول: قريبًا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَمْهِلْهُمْ رُوَيْدًا﴾ الرويد: القليل.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا﴾ قال: مَهِّلْهم، فلا تعجل عليهم تَرْكَهُمْ، حتى لمَّا أراد الانتصار منهم أمره بجهادهم وقتالهم، والغلظة عليهم.\n\nآخر تفسير سورة والسماء والطارق.","12":11,"13":11,"14":11,"15":11,"16":11,"17":11},"87":{"1":"القول في تأويل قوله تعالى: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى (١) الَّذِي خَلَقَ فَسَوَّى (٢) وَالَّذِي قَدَّرَ فَهَدَى (٣) وَالَّذِي أَخْرَجَ الْمَرْعَى (٤) فَجَعَلَهُ غُثَاءً أَحْوَى (٥) سَنُقْرِئُكَ فَلا تَنْسَى (٦) إِلا مَا شَاءَ اللَّهُ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى (٧) ﴾\n\n.\n\nاختلف أهل التأويل في تأويل قوله: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ فقال بعضهم: معناه: عظم ربك الأعلى، لا ربّ أعلى منه وأعظم، وكان بعضهم إذا قرأ ذلك قال: سبحان ربي الأعلى.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا هشيم، قال: أخبرنا أبو بشر، عن سعيد بن جُبير، عن ابن عمر أنه كان يقرأ: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ سبحان ربي الأعلى ﴿الَّذِي خَلَقَ فَسَوَّى﴾ قال: وهي في قراءة أُبيّ بن كعب كذلك.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: سفيان، عن السدي، عن عبد خير، قال: سمعت عليًا رضي الله عنه قرأ: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ فقال: سبحان ربي الأعلى.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عنبسة، عن أبي إسحاق الهمداني، أن ابن عباس، كان إذا قرأ ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ يقول: سبحان ربي الأعلى، وإذا قرأ ﴿لا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ﴾ فأتى على آخرها ﴿أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى﴾ ؟ يقول: سبحانك اللهمّ وبَلَى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ ذُكر لنا أن نبيّ الله ﷺ كان إذا قرأها قال: سبحان ربي الأعلَى.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن خارجة، عن داود، عن زياد بن عبد الله، قال: سمعت ابن عباس يقرأ في صلاة المغرب: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ سبحان ربي الأعلَى.\n\nوقال آخرون: بل معنى ذلك: نزه يا محمد اسم ربك الأعلى، أن تسمي به شيئًا سواه، ينهاه بذلك أن يفعل ما فعل من ذلك المشركون من تسميتهم آلهتهم بعضها اللات وبعضها العزّى.\n\nوقال غيرهم: بل معنى ذلك: نزه الله عما يقول فيه المشركون كما قال: ﴿وَلا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ﴾ وقالوا: معنى ذلك: سبح ربك الأعلى؛ قالوا: وليس الاسم معنيًا.\n\nوقال آخرون: نزه تسميتك يا محمد ربك الأعلى وذكرك إياه أن تذكره إلا وأنت له خاشع متذلل؛ قالوا: وإنما عُنِي بالاسم: التسمية، ولكن وُضع الاسم مكان المصدر.\n\nوقال آخرون: معنى قوله: ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ : صلّ بذكر ربك يا محمد، يعني بذلك: صلّ وأنت له ذاكر، ومنه وجل خائف.\n\nوأولى الأقوال في ذلك عندنا بالصواب قول من قال: معناه: نزه اسم ربك أن تدعو به الآلهة والأوثان، لما ذكرت من الأخبار، عن رسول الله ﷺ، وعن الصحابة أنهم كانوا إذا قرءوا ذلك قالوا: سبحان ربي الأعلى، فَبَيَّن بذلك أن معناه كان عندهم معلوما: عظم اسم ربك ونزهه.\n\n* *\n\nوقوله: ﴿الَّذِي خَلَقَ فَسَوَّى﴾\n\nيقول: الذي خلق الأشياء فسوىّ خلقها، وعدّلها، والتسوية التعديل.\n\n* *\n\nوقوله: ﴿وَالَّذِي قَدَّرَ فَهَدَى﴾\n\nيقول تعالى ذكره: والذي قدّر خلقه فهدى.\n\nواختلف أهل التأويل في المعنى الذي عُنِي بقوله: ﴿فَهَدَى﴾ ، فقال بعضهم: هدى الإنسان لسبيل الخير والشرّ، والبهائم للمراتع.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿قَدَّرَ فَهَدَى﴾ قال: هدى الإنسان للشِّقوة والسعادة، وهَدى الأنعام لمراتعها.\n\nوقال آخرون: بل معنى ذلك، هدى الذكور لمأتى الإناث. وقد ذكرنا الرواية بذلك فيما مضى.\n\nوالصواب من القول في ذلك عندنا، أن الله عمّ بقوله: ﴿فَهَدَى﴾ الخبر عن هدايته خلقه، ولم يخصص من ذلك معنى دون معنى، وقد هداهم لسبيل الخير والشرّ، وهدى الذكور لمأتى الإناث، فالخبر على عمومه حتى يأتي خبر تقوم به الحجة، دالّ على خصوصه. واجتمعت قرّاء الأمصار على تشديد الدال من قدّر، غير الكسائي فإنه خفَّفها.\n\nوالصواب في ذلك التشديد، لإجماع الحجة عليه.\n\n* *\n\nوقوله: ﴿وَالَّذِي أَخْرَجَ الْمَرْعَى﴾\n\nيقول: والذي أخرج من الأرض مرعى الأنعام من صنوف النبات وأنواع الحشيش.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن مكرم، قال ثنا الحفري، قال ثنا سفيان، عن منصور، عن أبي رزين ﴿أَخْرَجَ الْمَرْعَى﴾ قال النبات.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالَّذِي أَخْرَجَ الْمَرْعَى ... ﴾ الآية، نبت كما رأيتم بين أصفر وأحمر وأبيض.\n\n* *\n\nوقوله: ﴿فَجَعَلَهُ غُثَاءً أَحْوَى﴾\n\nيقول تعالى ذكره: فجعل ذلك المرعى غُثاء، وهو ما جفّ من النبات ويبس، فطارت به الريح؛ وإنما عُني به هاهنا أنه جعله هشيمًا يابسًا متغيرًا إلى الحُوَّة، وهي السواد من بعد البياض أو الخضْرة، من شدّة اليبس.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿غُثَاءً أَحْوَى﴾ يقول: هشيمًا متغيرًا\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿غُثَاءً أَحْوَى﴾ قال: غثاء السيل أحوى، قال: أسود.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال ثنا سعيد، عن قتادة، في قوله: ﴿غُثَاءً أَحْوَى﴾ قال: يعود يبسًا بعد خُضرة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَجَعَلَهُ غُثَاءً أَحْوَى﴾ قال: كان بقلا ونباتًا أخضر، ثم هاج فيبُس، فصار غُثاء أحوى تذهب به الرياح والسيول. وكان بعض أهل العلم بكلام العرب يرى أن ذلك من المؤخَّر الذي معناه التقديم، وأن معنى الكلام: والذي أخرج المرعى أحوى: أي أخضر إلى السواد، فجعله غثاء بعد ذلك، ويعتلّ لقوله ذلك بقول ذي الرُّمة:\n\nحَوَّاءُ قَرْحاءُ أشْراطِيَّةٌ وَكَفَتْ ... فِيهَا الذِّهَابُ وَحَفَّتْهَا الْبَرَاعِيمُ\n\nوهذا القول وإن كان غير مدفوع أن يكون ما اشتدّت خضرته من النبات، قد تسميه العرب أسود، غير صواب عندي بخلافه تأويل أهل التأويل في أن الحرف إنما يحتال لمعناه المخرج بالتقديم والتأخير إذا لم يكن له وجه مفهوم إلا بتقديمه عن موضعه، أو تأخيره، فأما وله في موضعه وجه صحيح فلا وجه لطلب الاحتيال لمعناه بالتقديم والتأخير.\n\n* *\n\nوقوله: ﴿سَنُقْرِئُكَ فَلا تَنْسَى إِلا مَا شَاءَ اللَّهُ﴾\n\nيقول تعالى ذكره: سنقرئك يا محمد هذا القرآن فلا تنساه، إلا ما شاء الله.\n\nثم اختلف أهل التأويل في معنى قوله: ﴿فَلا تَنْسَى إِلا مَا شَاءَ اللَّهُ﴾ فقال بعضهم: هذا إخبار من الله نبيه عليه الصلاة والسلام أنه يعلمه هذا القرآن ويحفظه عليه، ونهي منه أن يعجل بقراءته كما قال جلّ ثناؤه: ﴿لا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن؛ قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿سَنُقْرِئُكَ فَلا تَنْسَى﴾ قال: كان يتذكر القرآن في نفسه مخافة أن ينسى، فقال قائلو هذه المقالة: معنى الاستثناء في هذا الموضع على النسيان، ومعنى الكلام: فلا تنسى، إلا ما شاء الله أن تنساه، ولا تذكُرَه، قالوا: ذلك هو ما نسخه الله من القرآن، فرفع حكمه وتلاوته.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿سَنُقْرِئُكَ فَلا تَنْسَى﴾ كان ﷺ لا ينسى شيئًا ﴿إِلا مَا شَاءَ اللَّهُ﴾ .\n\nوقال آخرون: معنى النسيان في هذا الموضع: الترك؛ وقالوا: معنى الكلام: سنقرئك يا محمد فلا تترك العمل بشيء منه، إلا ما شاء الله أن تترك العمل به، مما ننسخه.\n\nوكان بعض أهل العربية يقول في ذلك: لم يشأ الله أن تنسى شيئًا، وهو كقوله: ﴿خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالأرْضُ إِلا مَا شَاءَ رَبُّكَ﴾ ولا يشاء. قال: وأنت قائل في الكلام: لأعطينك كلّ ما سألت إلا ما شئت، وإلا أن أشاء أن أمنعك، والنية أن لا تمنعه، ولا تشاء شيئًا. قال: وعلى هذا مجاري الأيمان، يستثنى فيها، ونية الحالف: اللمام.\n\nوالقول الذي هو أولى بالصواب عندي قول من قال: معنى ذلك: فلا تنسى إلا أن نشاء نحن أن نُنسيكه بنسخه ورفعه.\n\nوإنما قلنا ذلك أولى بالصواب، لأن ذلك أظهر معانيه.\n\n* *\n\nوقوله: ﴿إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى﴾\n\nيقول تعالى ذكره: إن الله يعلم الجهر يا محمد من عملك ما أظهرته وأعلنته ﴿وَمَا يَخْفَى﴾ يقول: وما يخفى منه فلم تظهره مما كتمته، يقول: هو يعلم جميع أعمالك سرّها وعلانيتها؛ يقول: فاحذره أن يطلع عليك وأنت عامل في حال من أحوالك بغير الذي أذن لك به.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":"القول في تأويل قوله تعالى: ﴿وَنُيَسِّرُكَ لِلْيُسْرَى (٨) فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى (٩) سَيَذَّكَّرُ مَنْ يَخْشَى (١٠) وَيَتَجَنَّبُهَا الأشْقَى (١١) الَّذِي يَصْلَى النَّارَ الْكُبْرَى (١٢) ثُمَّ لا يَمُوتُ فِيهَا وَلا يَحْيَا (١٣) ﴾\n\n.\n\nيقول تعالى ذكره: ونسهلك يا محمد لعمل الخير وهو اليُسرَى، واليُسرَى: هو الفُعلى من اليسر.\n\n* *\n\nوقوله: ﴿فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى﴾\n\nيقول تعالى ذكره: فذكِّر عباد الله يا محمد عظمته، وعِظْهم، وحذّرهم عقوبته ﴿إِنْ نَفَعَتِ الذِّكْرَى﴾ يقول: إن نفعت الذكرى الذين قد آيستُك من إيمانهم، فلا تنفعهم الذكرى.\n\n* *\n\nوقوله: ﴿فَذَكِّرْ﴾\n\nأمر من الله لنبيه ﷺ بتذكير جميع الناس، ثم قال: إن نفعت الذكرى هؤلاء الذين قد آيستك من إيمانهم.\n\n* *\n\nوقوله: ﴿سَيَذَّكَّرُ مَنْ يَخْشَى﴾\n\nيقول جلّ ثناؤه: سَيَذَّكَّرُ يا محمد إذا ذكرت الذين أمرتك بتذكيرهم من يخشى الله، ويخاف عقابه ﴿وَيَتَجَنَّبُهَا﴾ يقول: ويتجنَّب الذكرى ﴿الأشْقَى﴾ يعني: أشقى الفريقين ﴿الَّذِي يَصْلَى النَّارَ الْكُبْرَى﴾ وهم الذين لم تنفعهم الذكرى.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى سَيَذَّكَّرُ مَنْ يَخْشَى﴾ فاتقوا الله، ما خشي الله عبد قطّ إلا ذكره ﴿وَيَتَجَنَّبُهَا الأشْقَى﴾ فلا والله لا يتنكَّب عبد هذا الذكر زهدًا فيه وبُغضًا لأهله، إلا شَقِيٌّ بَيِّن الشقاء.\n\n* *\n\nوقوله: ﴿الَّذِي يَصْلَى النَّارَ الْكُبْرَى﴾\n\nيقول: الذي يَرِد نار جهنم، وهي النار الكبرى، ويعني بالكبرى لشدّة الحرّ والألم.\n\n* *\n\nوقوله: ﴿ثُمَّ لا يَمُوتُ فِيهَا وَلا يَحْيَا﴾\n\nيقول: ثم لا يموت في النار الكبرى ولا يحيا، وذلك أن نفس أحدهم تصير فيها في حلقه، فلا تخرج فتفارقه فيموت، ولا ترجع إلى موضعها من الجسم فيحيا. وقيل: لا يموت فيها فيستريح، ولا يحيا حياة تنفعه.\n\nوقال آخرون: قيل ذلك؛ لأن العرب كانت إذا وصفت الرجل بوقوع في شدة شديدة، قالوا: لا هو حيّ، ولا هو ميت، فخاطبهم الله بالذي جرى به ذلك من كلامهم.","9":8,"10":8,"11":8,"12":8,"13":8,"14":"القول في تأويل قوله تعالى: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى (١٤) وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى (١٥) ﴾\n\n.","15":14,"16":"القول في تأويل قوله تعالى: ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا (١٦) وَالآخِرَةُ خَيْرٌ وَأَبْقَى (١٧) إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى (١٨) صُحُفِ إِبْرَاهِيمَ وَمُوسَى (١٩) ﴾\n\n.\n\nيقول تعالى ذكره: قد نجح وأدرك طلبته من تطهَّر من الكفر ومعاصي الله، وعمل بما أمره الله به، فأدّى فرائضه.\n\nوبنحو الذي قلنا في ذلك قال جماعة من أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ يقول: مَنْ تَزَكَّى من الشرك.\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا محمد بن عبد الله الأنصاري، قال: ثنا هشام، عن الحسن، في قوله: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ قال: من كان عمله زاكيًا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ قال: يعمل وَرِعًا.\n\n⁕ حدثني سعد بن عبد الله بن عبد الحكم، قال: ثنا حفص بن عُمر العَدَنيّ، عن الحكم، عن عكرِمة، في قوله: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ من قال: لا إله إلا الله.\n\nوقال آخرون: بل معنى ذلك: قد أفلح من أدّى زكاة ماله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عليّ بن الأقمر، عن أبي الأحوص ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ قال: من استطاع أن يرضَخَ فليفعل، ثم ليقم فليصلّ.\n\n⁕ حدثنا محمد بن عمارة الرازي، قال: ثنا أبو نعيم، قال: ثنا سفيان، عن علي بن الأقمر، عن أبي الأحوص ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ قال: من رَضَخَ  .\n\n⁕ حدثنا محمد بن عمارة، قال: ثنا عثمان بن سعيد بن مرَّة، قال: ثنا زهير، عن أبي إسحاق، عن أبي الأحوص، قال: إذا أتى أحدكم سائل وهو يريد الصلاة، فليقدّم بين يدي صلاته زكاته، فإن الله يقول: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾ فمن استطاع أن يقدّم بين يدي صلاته زكاةً فليفعل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى﴾ تزكى رجل من ماله، وأرضى خالقه.\n\nوقال آخرون: بل عُنِي بذلك زكاة الفطر.\n\nذكر من قال ذلك:\n\n⁕ حدثني عمرو بن عبد الحميد الآملي، قال: ثنا مروان بن معاوية، عن أبي خلدة، قال: دخلت على أبي العالية، فقال لي: إذا غَدَوت غدًا إلى العيد فمرّ بي، قال: فمررت به، فقال: هل طَعِمت شيئا؟ قلت: نعم، قال: أَفَضْت على نفسك من الماء؟ قلت: نعم، قال: فأخبرني ما فعلت بزكاتك؟ قلت: قد وجَّهتها، قال: إنما أردتك لهذا، ثم قرأ: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾ وقال: إن أهل المدينة لا يَرَونَ صدقة أفضل منها ومن سِقَاية الماء.\n\n* *\n\nوقوله: ﴿وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾\n\nاختلف أهل التأويل في تأويل قوله: ﴿وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾ فقال بعضهم: معنى ذلك: وحَّد الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال ثني معاوية، عن عليّ، عن ابن عباس ﴿وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾ يقول: وحَّد الله سبحانه وتعالى.\n\nوقال آخرون: بل معنى ذلك: وذكر الله ودعاه ورغب إليه.\n\nوالصواب من القول في ذلك أن يقال: وذكر الله فوحَّده، ودعاه ورغب إليه؛ لأن كلّ ذلك من ذكر الله، ولم يُخصص الله تعالى من ذكره نوعًا دون نوع.\n\n* *\n\nوقوله: ﴿فَصَلَّى﴾\n\nاختلف أهل التأويل في تأويل ذلك. فقال بعضهم: عُنِي به: فصلى الصلوات الخمس.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿فَصَلَّى﴾ يقول: صلَّى الصلوات الخمس.\n\nوقال آخرون: عُنِيَ به: صلاة العيد يوم الفطر.\n\nوقال آخرون: بل عُنِيَ به: وذكر اسم ربه فدعا، وقالوا: الصلاة هاهنا: الدعاء.\n\nوالصواب من القول أن يقال: عُنِيَ بقوله: ﴿فَصَلَّى﴾ : الصلوات، وذكر الله فيها بالتحميد والتمجيد والدعاء.\n\n* *\n\nوقوله: ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾\n\nيقول للناس: بل تؤثرون أيها الناس زينة الحياة الدنيا على الآخرة ﴿وَالآخِرَةُ خَيْرٌ﴾ لكم ﴿وَأَبْقَى﴾ يقول: وزينة الآخرة خير لكم أيها الناس وأبقى، لأن الحياة الدنيا فانية، والآخرة باقية، لا تنفَدُ ولا تفنى.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾ فاختار الناس العاجلة إلا من عصم الله.\n\n* *\n\nوقوله: ﴿وَالآخِرَةُ خَيْرٌ﴾\n\nفي الخير ﴿وَأَبْقَى﴾ في البقاء.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا أبو حمزة، عن عطاء، عن عَرْفَجَة الثقفي، قال: استقرأت ابن مسعود ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ ، فلما بلغ: ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾ ترك القراءة وأقبل على أصحابه، وقال: آثرنا الدنيا على الآخرة، فسكت القوم، فقال: آثرنا الدنيا؛ لأنا رأينا زينتها ونساءها وطعامها وشرابها، وزُوِيت عنا الآخرة، فاخترنا هذا العاجل، وتركنا الآجل.\n\nواختلفت القرّاء في قراءة قوله: ﴿بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا﴾ فقرأ ذلك عامَّة قرّاء الأمصار: ﴿بَلْ تُؤْثِرُونَ﴾ بالتاء، إلا أبا عمرو فإنه قرأه بالياء، وقال: يعني الأشقياء.\n\nوالذي لا أوثر عليه في قراءة ذلك التاء، لإجماع الحجة من القرّاء عليه. وذُكر أن ذلك في قراءة أُبي: ﴿بَلْ أَنْتُمْ تُؤْثِرُونَ﴾ فذلك أيضًا شاهد لصحة القراءة بالتاء.\n\n* *\n\nوقوله: ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى﴾\n\nاختلف أهل التأويل في الذي أشير إليه بقوله هذا، فقال بعضهم: أُشير به إلى الآيات التي في ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبيه، عن عكرِمة ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى صُحُفِ إِبْرَاهِيمَ وَمُوسَى﴾ يقول: الآيات التي في ﴿سَبِّحِ اسْمَ رَبِّكَ الأعْلَى﴾ .\n\nوقال آخرون: قصة هذه السورة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى صُحُفِ إِبْرَاهِيمَ وَمُوسَى﴾ قال: قصة هذه السورة لفي الصحف الأولى.\n\nوقال آخرون: بل معنى ذلك: إن هذا الذي قصّ الله تعالى في هذه السورة ﴿لَفِي الصُّحُفِ الأولَى﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى﴾ قال: إن هذا الذي قصّ الله في هذه السورة، لفي الصحف الأولى ﴿صُحُفِ إِبْرَاهِيمَ وَمُوسَى﴾ .\n\nوقال آخرون: بل عُنِي بذلك أن قوله: ﴿وَالآخِرَةُ خَيْرٌ وَأَبْقَى﴾ في الصحف الأولى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى﴾ قال: تتابعت كتب الله كما تسمعون أن الآخرة خير وأبقى.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّ هَذَا لَفِي الصُّحُفِ الأولَى صُحُفِ إِبْرَاهِيمَ وَمُوسَى﴾ قال: في الصحف التي أنزلها الله على إبراهيم وموسى أن الآخرة خير من الأولى.\n\nوأولى الأقوال في ذلك بالصواب، قول من قال: إن قوله: ﴿قَدْ أَفْلَحَ مَنْ تَزَكَّى وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا وَالآخِرَةُ خَيْرٌ وَأَبْقَى﴾ لفي الصحف الأولى، صحف إبراهيم خليل الرحمن، وصحف موسى بن عمران.\n\nوإنما قلت: ذلك أولى بالصحة من غيره؛ لأن هذا إشارة إلى حاضر، فلأن يكون إشارة إلى ما قرب منها أولى من أن يكون إشارة إلى غيره. وأما الصحف: فإنها جمع صحيفة، وإنما عُنِي بها: كتب إبراهيم وموسى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن أبي الخلد، قال: نزلت صحف إبراهيم في أوّل ليلة من رمضان، وأنزلت التوراة لستّ ليال خلون من رمضان، وأنزل الزبور لاثنتي عشرة ليلة، وأنزل الإنجيل لثماني عشرة، وأنزل الفرقان لأربع وعشرين.\n\nآخر تفسير سورة سبح اسم ربك الأعلى","17":16,"18":16,"19":16},"88":{"1":"القول في تأويل قوله تعالى: ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ (١) وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ (٢) عَامِلَةٌ نَاصِبَةٌ (٣) تَصْلَى نَارًا حَامِيَةً (٤) تُسْقَى مِنْ عَيْنٍ آنِيَةٍ (٥) لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ (٦) لا يُسْمِنُ وَلا يُغْنِي مِنْ جُوعٍ (٧) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: ﴿هَلْ أَتَاكَ﴾ يا محمد ﴿حَدِيثُ الْغَاشِيَةِ﴾ يعني: قصتها وخبرها.\n\nواختلف أهل التأويل في معنى الغاشية، فقال بعضهم: هي القيامة تغشي الناس بالأهوال.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿الْغَاشِيَةِ﴾ من أسماء يوم القيامة، عظَّمه الله، وحذّره عباده.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ قال: الغاشية: الساعة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ قال: الساعة.\n\nوقال آخرون: بل الغاشية: النار تغشَى وجوه الكَفَرة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن سعيد، في قوله: ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ قال: غاشية النار.\n\nوالصواب من القول في ذلك أن يقال: إن الله قال لنبيه ﷺ: ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ لم يخبرنا أنه عنى غاشية القيامة، ولا أنه عنى غاشية النار. وكلتاهما غاشية، هذه تغشى الناس بالبلاء والأهوال والكروب، وهذه تغشي الكفار باللفح في الوجوه، والشُّواظ والنحاس، فلا قول في ذلك أصحّ من أن يقال كما قال جلّ ثناؤه، ويعمّ الخبر بذلك كما عمه.\n\n* *\n\nوقوله: ﴿وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ﴾\n\nيقول تعالى ذكره: وجوه يومئذ، وهي وجوه أهل الكفر به\n\nخاشعة، يقول: ذليلة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ﴾ : أي ذليلة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿خَاشِعَةٌ﴾ قال: خاشعة في النار.\n\n* *\n\nوقوله: ﴿عَامِلَةٌ﴾\n\nيعني: عاملة في النار.\n\n* *\n\nوقوله: ﴿ناصِبَةٌ﴾\n\nيقول: ناصبة فيها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿عَامِلَةٌ نَاصِبَةٌ﴾ فإنها تعمل وَتَنْصَب من النار.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء، قال: سمعت الحسن، قرأ: ﴿عَامِلَةٌ نَاصِبَةٌ﴾ قال: لم تعمل لله في الدنيا، فأعملها في النار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿عَامِلَةٌ نَاصِبَةٌ﴾ تكبرت في الدنيا عن طاعة الله، فأعملها وأنصبها في النار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿عَامِلَةٌ نَاصِبَةٌ﴾ قال: عاملة ناصبة في النار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿عَامِلَةٌ نَاصِبَةٌ﴾ قال: لا أحد أنصَبُ ولا أشدّ من أهل النار.\n\n* *\n\nوقوله: ﴿تَصْلَى نَارًا حَامِيَةً﴾\n\nيقول تعالى ذكره: ترد هذه الوجوه نارًا حامية قد حميت واشتد حرها.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الكوفة ﴿تَصْلَى﴾ بفتح التاء، بمعنى: تصلى الوجوه. وقرأ ذلك أبو عمرو ﴿تُصْلَى﴾ بضم التاء اعتبارًا بقوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾ ، والقول في ذلك أنهما قراءتان صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾\n\nيقول: تسقى أصحاب هذه الوجوه من شَرَاب عين قد أنى حرّها، فبلغ غايته في شدة الحرّ.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾ قال: هي التي قد أطال أنينها.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَيَة، عن أبي رجاء، عن الحسن، في قوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾ قال: أنَى طبخها منذ يوم خلق الله الدنيا.\n\n⁕ حدثني به يعقوب مرّة أخرى، فقال: منذ يوم خلق الله السموات والأرض.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد في قول الله: ﴿مِنْ عَيْنٍ آنِيَةٍ﴾ قال: قد بلغت إناها، وحان شربها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾ يقول: قد أنَى طبخها منذ خلق الله السموات والأرض.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، في قوله: ﴿مِنْ عَيْنٍ آنِيَةٍ﴾ قال: من عين أنَى حرّها: يقول: قد بلغ حرّها.\n\nوقال بعضهم: عُنِيَ بقوله: ﴿مِنْ عَيْنٍ آنِيَةٍ﴾ من عين حاضرة.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿تُسْقَى مِنْ عَيْنٍ آنِيَةٍ﴾ قال: آنية: حاضرة.\n\n* *\n\nوقوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾\n\nيقول: ليس لهؤلاء الذين هم أصحاب الخاشعة العاملة الناصبة يوم القيامة طعام، إلا ما يطعمونه من ضَرِيع. والضريع عند العرب: نبت يُقال له الشِّبْرِق، وتسميه أهل الحجاز الضَّريع إذا يبس، ويسميه غيرهم: الشِّبْرق، وهو سمّ.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: الضريع: الشِّبْرق.\n\n⁕ حدثني محمد بن عُبيد المحاربيّ، قال: ثنا عباد بن يعقوب الأسديّ، قال محمد: ثنا، وقال عباد: أخبرنا محمد بن سليمان، عن عبد الرحمن الأصبهانيّ، عن عكرِمة في قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: الشِّبرق.\n\n⁕ حدثني يعقوب، قال: ثنا إسماعيل بن عُلَية، عن أبي رجاء، قال: ثني نجدة، رجل من عبد القيس عن عكرمة، في قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: هي شجرة ذات شوك، لاطئة بالأرض، فإذا كان الربيع سمَّتها قريش الشِّبرق، فإذا هاج العود سمتها الضَّريع.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ليث، عن مجاهد ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: الشبرق.\n\n⁕ حدثنا ابن حُميد، قال: ثنا مِهران، عن سفيان، عن ليث، عن مجاهد، مثله.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن؛ قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ضَرِيعٍ﴾ قال: الشِّبرق اليابس.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِلا مِنْ ضَرِيعٍ﴾ قال: هو الشبرق إذا يبس يسمى الضريع.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ يقول: من شرّ الطعام، وأبشعه وأخبثه.\n\n⁕ حدثني محمد بن عبيد، قال: ثنا شريك بن عبد الله، في قوله: (لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ) قال: الشبرق.\n\nوقال آخرون: الضَّرِيع: الحجارة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن جعفر، عن سعيد، في قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: الحجارة.\n\nوقال آخرون: الضَّرِيع: شجر من نار.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ يقول: شجر من نار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿لَيْسَ لَهُمْ طَعَامٌ إِلا مِنْ ضَرِيعٍ﴾ قال: الضريع: الشَّوك من النار. قال: وأما في الدنيا فإنَّ الضريع: الشوك اليابس الذي ليس له ورق، تدعوه العرب الضريع، وهو في الآخرة شوك من نار\n\n* *\n\nوقوله: ﴿لا يُسْمِنُ وَلا يُغْنِي مِنْ جُوعٍ﴾\n\nيقول: لا يُسمن هذا الضريع يوم القيامة أكلته من أهل النار، ﴿ولا يُغني من جوع﴾ يقول: ولا يُشْبعهم من جوع يصيبهم.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":"القول في تأويل قوله تعالى: ﴿وُجُوهٌ يَوْمَئِذٍ نَاعِمَةٌ (٨) لِسَعْيِهَا رَاضِيَةٌ (٩) فِي جَنَّةٍ عَالِيَةٍ (١٠) لا تَسْمَعُ فِيهَا لاغِيَةً (١١) فِيهَا عَيْنٌ جَارِيَةٌ (١٢) فِيهَا سُرُرٌ مَرْفُوعَةٌ (١٣) وَأَكْوَابٌ مَوْضُوعَةٌ (١٤) وَنَمَارِقُ مَصْفُوفَةٌ (١٥) وَزَرَابِيُّ مَبْثُوثَةٌ (١٦) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿وُجُوهٌ يَوْمَئِذٍ﴾ يعني: يوم القيامة ﴿نَاعِمَةٌ﴾ يقول: هي ناعمة بتنعيم الله أهلها في جناته، وهم أهل الإيمان بالله.\n\n* *\n\nوقوله: ﴿لِسَعْيِهَا رَاضِيَةٌ﴾\n\nيقول: لعملها الذي عملت في الدنيا من طاعة ربها راضية، وقيل: ﴿لِسَعْيِهَا رَاضِيَةٌ﴾ والمعنى: لثواب سعيها في الآخرة راضية.\n\n* *\n\nوقوله: ﴿فِي جَنَّةٍ عَالِيَةٍ﴾\n\nوهي بستان، عالية يعني: رفيعة.\n\n* *\n\nوقوله: ﴿لا تَسْمَعُ فِيهَا لاغِيَةً﴾\n\nيقول: لا تسمع هذه الوجوه - المعنى: لأهلها فيها في الجنة العالية - لاغية. يعني باللاغية: كلمة لغو واللَّغو: الباطل، فقيل للكلمة التي هي لغو لاغية، كما قيل لصاحب الدرع: دارع، ولصاحب الفرس: فارس، ولقائل الشعر شاعر، وكما قال الحُطيئة:\n\nأغَرَرْتَنِي وَزَعَمْتَ أنَّ ... كَ لابِنٌ بِالصَّيْفِ تَامِرْ\n\nيعني: صاحب لبن، وصاحب تمر. وزعم بعض الكوفيين أن معنى ذلك: لا تسمع فيها حالفة على الكذب ولذلك قيل: لاغية؛ ولهذا الذي قاله مذهب ووجه، لولا أن أهل التأويل من الصحابة والتابعين على خلافه، وغير جائز لأحد خلافهم فيما كانوا عليه مجمعين.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿لا تَسْمَعُ فِيهَا لاغِيَةً﴾ يقول: لا تسمع أذًى ولا باطلا.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿لا تَسْمَعُ فِيهَا لاغِيَةً﴾ قال: شتمًا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿لا تَسْمَعُ فِيهَا لاغِيَةً﴾ : لا تسمع فيها باطلا ولا شاتمًا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن مَعْمَر، عن قتادة، مثله.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الكوفة وبعض قرّاء المدينة وهو أبو جعفر ﴿لا تَسْمَعُ﴾ بفتح التاء، بمعنى: لا تسمع الوجوه. وقرأ ذلك ابن كثير ونافع وأبو عمرو ﴿لا تُسْمَعُ﴾ بضم التاء، بمعنى ما لم يسمّ فاعله ويؤنَّث تسمع لتأنيث لاغية. وقرأ ابن محيصن بالضم أيضًا، غير أنه كان يقرؤها بالياء على وجه التذكير.\n\nوالصواب من القول في ذلك عندي، أن كلّ ذلك قراءات معروفات صحيحات المعاني، فبأيّ ذلك قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿فِيهَا عَيْنٌ جَارِيَةٌ﴾\n\nيقول: في الجنة العالية عين جارية في غير أخدود.\n\n* *\n\nوقوله: ﴿فِيهَا سُرُرٌ مَرْفُوعَةٌ﴾\n\nوالسرر: جمع سرير، مرفوعة ليرى المؤمن إذا جلس عليها جميع ما خوّله ربه من النعيم والملك فيها، ويلحق جميع ذلك بصره.\n\nوقيل: عُنِي بقول مرفوعة: موضونة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فِيهَا سُرُرٌ مَرْفُوعَةٌ﴾ يعني: موضونة، كقوله: سُرر مصفوفة، بعضها فوق بعض.\n\n* *\n\nوقوله: ﴿وَأَكْوَابٌ مَوْضُوعَةٌ﴾\n\nوهي جمع كوب، وهي الأباريق التي لا آذان لها. وقد بيَّنا ذلك فيما مضى، وذكرنا ما فيه من الرواية بما أغنى عن إعادته.\n\nوَعُنِي بقوله: ﴿مَوْضُوعَةٌ﴾ : أنها موضوعة على حافة العين الجارية، كلما أرادوا الشرب وجدوها ملأى من الشراب.\n\n* *\n\nوقوله: ﴿وَنَمَارِقُ مَصْفُوفَةٌ﴾\n\nيعني بالنمارق: الوسائد والمرافق؛ والنمارق: واحدها نُمْرُقة، بضم النون. وقد حُكي عن بعض كلب سماعًا نِمْرِقة، بكسر النون والراء. وقيل: مصفوفة؛ لأن بعضها بجنب بعض.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَنَمَارِقُ مَصْفُوفَةٌ﴾ يقول: المرافق.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَنَمَارِقُ مَصْفُوفَةٌ﴾ يعني بالنمارق: المجالس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَنَمَارِقُ مَصْفُوفَةٌ﴾ والنمارق: الوسائد.\n\n* *\n\nوقوله: ﴿وَزَرَابِيُّ مَبْثُوثَةٌ﴾\n\nيقول تعالى ذكره: وفيها طنافس وبُسُط كثيرة مبثوثة مفروشة، والواحدة: زِرْبية، وهي الطِّنفسة التي لها خمل رقيق.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أحمد بن منصور، قال: ثنا يزيد، قال: ثنا سعيد، عن سفيان، قال: ثنا توبة العنبريّ، عن عكرِمة بن خالد، عن عبد الله بن عمار، قال: رأيت عمر بن الخطاب رضي الله عنه يصلي على عبقريّ، وهو الزرابيّ.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَزَرَابِيُّ مَبْثُوثَةٌ﴾ : المبسوطة.","9":8,"10":8,"11":8,"12":8,"13":8,"14":8,"15":8,"16":8,"17":"القول في تأويل قوله تعالى: ﴿أَفَلا يَنْظُرُونَ إِلَى الإبِلِ كَيْفَ خُلِقَتْ (١٧) وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ (١٨) وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ (١٩) وَإِلَى الأرْضِ كَيْفَ سُطِحَتْ (٢٠) ﴾\n\n.\n\nيقول تعالى ذكره لمُنكري قدرته على ما وصف في هذه السورة من العقاب والنكال الذي أعدّه لأهل عداوته، والنعيم والكرامة التي أعدّها لأهل ولايته: أفلا ينظر هؤلاء المنكرون قُدرة الله على هذه الأمور، إلى الإبل كيف خلقها وسخرها لهم وذَلَّلها وجعلها تحمل حملها باركة، ثم تنهض به، والذي خلق ذلك غير عزيز عليه أن يخلق ما وصف من هذه الأمور في الجنة والنار، يقول جلّ ثناؤه: أفلا ينظرون إلى الإبل فيعتبرون بها، ويعلمون أن القُدرة التي قدر بها على خلقها، لن يُعجزه خلق ما شابهها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: لما نعت الله ما في الجنة، عجب من ذلك أهل الضلالة، فأنزل الله: ﴿أَفَلا يَنْظُرُونَ إِلَى الإبِلِ كَيْفَ خُلِقَتْ﴾ فكانت الإبل من عيش العرب ومن خوَلهم.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي إسحاق عمن سمع شريحا يقول: اخرجوا بنا ننظر إلى الإبل كيف خُلقت.\n\n* *\n\nوقوله: ﴿وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ﴾\n\nيقول جلّ ثناؤه: أفلا ينظرون أيضا إلى السماء كيف رفعها الذي أخبركم أنه معِدّ لأوليائه ما وصف، ولأعدائه ما ذكر، فيعلموا أن قُدرته القدرة التي لا يُعجزه فعل شيء أراد فعله.\n\n* *\n\nوقوله: ﴿وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ﴾\n\nيقول: وإلى الجبال كيف أقيمت منتصبة لا تسقط، فتنبسط في الأرض، ولكنها جعلها بقدرته منتصبة جامدة، لا تبرح مكانها، ولا تزول عن موضعها.\n\n⁕ وقد حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ﴾ تصاعد إلى الجبل الصَّيخود عامة يومك، فإذا أفضيت إلى أعلاه، أفضيت إلى عيون متفجرة، وثمار متهدلة ثم لم تحرثه الأيدي ولم تعمله، نعمة من الله، وبُلغة الأجل.\n\n* *\n\nوقوله: ﴿وَإِلَى الأرْضِ كَيْفَ سُطِحَتْ﴾\n\nيقول: وإلى الأرض كيف بُسطت، يقال: جبل مُسَطَّح: إذا كان في أعلاه استواء.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِلَى الأرْضِ كَيْفَ سُطِحَتْ﴾ : أي بُسطت، يقول: أليس الذي خلق هذا بقادر على أن يخلق ما أراد في الجنة.","18":17,"19":17,"20":17,"21":"القول في تأويل قوله تعالى: ﴿فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ (٢١) لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ (٢٢) إِلا مَنْ تَوَلَّى وَكَفَرَ (٢٣) فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الأكْبَرَ (٢٤) إِنَّ إِلَيْنَا إِيَابَهُمْ (٢٥) ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ (٢٦) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: ﴿فَذَكِّرْ﴾ يا محمد عبادي بآياتي، وعظهم بحججي وبلِّغهم رسالتي ﴿إِنَّمَا أَنْتَ مُذَكِّرٌ﴾ يقول: إنما أرسلتك إليهم مذكرا لتذكرهم نعمتي عندهم، وتعرّفهم اللازم لهم، وتعظهم.\n\n* *\n\nوقوله: ﴿لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾\n\nيقول: لست عليهم بمسلَّط، ولا أنت بجبار تحملهم على ما تريد. يقول: كِلهم إليّ، ودعهم وحكمي فيهم؛ يقال: قد تسيطر فلان على قومه: إذا تسلط عليهم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ يقول: لست عليهم بجبار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ : أي كِلْ إليّ عبادي.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿بِمُسَيْطِرٍ﴾ قال: جبار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّمَا أَنْتَ مُذَكِّرٌ لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ قال: لست عليهم بمسلط أن تكرههم على الإيمان، قال: ثم جاء بعد هذا: ﴿جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ﴾ وقال ﴿اقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ﴾ وارصدوهم لا يخْرُجُوا فِي البِلاد ﴿فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾ قال: فنسخت ﴿لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ قال: جاء اقتله أو يُسْلِم؛ قال: والتذكرة كما هي لم تنسخ وقرأ: ﴿وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنْفَعُ الْمُؤْمِنِينَ﴾ .\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن أبي الزبير، عن جابر بن عبد الله، قال: قال رسول الله ﷺ: \"أُمِرْتُ أنْ أُقَاتِلَ النَّاسَ حتى يَقُولُوا: لا إلَهَ إلا اللهُ، فإذَا قالُوا: لا إلَهَ إلا اللهُ، عَصَمُوا مِنِّي دِماءَهُمْ وأمْوَالَهُمْ إلا بِحَقِّها، وحِسابُهُمْ على اللهِ\" ثم قرأ: ﴿إِنَّمَا أَنْتَ مُذَكِّرٌ لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي الزبير محمد بن مسلم، قال: سمعت جابر بن عبد الله، يقول: سمعت النبيّ ﷺ يقول، فذكر مثله، إلا أنه قال: قال أبو الزّبير: ثم قرأ: ﴿إِنَّمَا أَنْتَ مُذَكِّرٌ لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ﴾ .\n\n⁕ حدثنا يوسف بن موسى القطان، قال: ثنا وكيع، عن سفيان، عن أبي الزّبير، عن جابر، عن رسول الله ﷺ، مثله.\n\n* *\n\nوقوله: ﴿إِلا مَنْ تَوَلَّى وَكَفَرَ﴾\n\nيتوجَّه لوجهين: أحدهما: فذكر قومك يا محمد، إلا من تولى منهم عنك، وأعرض عن آيات الله فكفر، فيكون قوله \"إلا\" استثناء من الذين كان التذكير عليهم، وإن لم يذكروا، كما يقال: مضى فلان، فدعا إلا من لا تُرْجَى إجابته، بمعنى: فدعا الناس إلا من لا ترجى إجابته. والوجه الثاني: أن يجعل قوله: ﴿إِلا مَنْ تَوَلَّى وَكَفَرَ﴾ منقطعا عما قبله، فيكون معنى الكلام حينئذ لست عليهم بمسيطر، إلا من تولى وكفر، يعذّبه الله، وكذلك الاستثناء المنقطع يمتحن بأن يحسن معه إنّ، فإذا حسنت معه كان منقطعا، وإذا لم تحسن كان استثناء متصلا صحيحا، كقول القائل: سار القوم إلا زيدا، ولا يصلح دخول إن هاهنا لأنه استثناء صحيح.\n\n* *\n\nوقوله: ﴿فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الأكْبَرَ﴾\n\n: هو عذاب جهنم، يقول: فيعذبه الله العذاب الأكبر على كفره في الدنيا، وعذاب جهنم في الآخرة.\n\n* *\n\nوقوله: ﴿إِنَّ إِلَيْنَا إِيَابَهُمْ﴾\n\nيقول: إن إلينا رجوع من كفر ومعادهم ﴿ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ﴾ يقول: ثم إن على الله حسابه، وهو يجازيه بما سلف منه من معصية ربه، يُعْلِمُ بذلك نبيه محمدًا ﷺ أنه المتولي عقوبته دونه، وهو المجازي والمعاقب، وأنه الذي إليه التذكير وتبليغ الرسالة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إِلا مَنْ تَوَلَّى وَكَفَرَ﴾ قال: حسابه على الله.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِنَّ إِلَيْنَا إِيَابَهُمْ ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ﴾ يقول: إن إلى الله الإياب وعليه الحساب.\n\nآخر تفسير سورة الغاشية","22":21,"23":21,"24":21,"25":21,"26":21},"89":{"1":"القول في تأويل قوله تعالى: ﴿وَالْفَجْرِ (١) وَلَيَالٍ عَشْرٍ (٢) وَالشَّفْعِ وَالْوَتْرِ (٣) وَاللَّيْلِ إِذَا يَسْرِي (٤) هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ (٥) ﴾\n\n.\n\nهذا قسم، أقسم ربنا جلّ ثناؤه بالفجر، وهو فجر الصبح.\n\nواختلف أهل التأويل في الذي عُنِي بذلك، فقال بعضهم: عُنِي به النهار.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأغرّ المِنقريّ، عن خليفة بن الحصين، عن أبي نصر، عن ابن عباس، قوله: ﴿وَالْفَجْرِ﴾ قال: النهار.\n\nوقال آخرون: عُنِيَ به صلاة الصبح.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَالْفَجْرِ﴾ يعني: صلاة الفجر.\n\nوقال آخرون: هو فجر الصبح.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا عاصم الأحول، عن عكرِمة، في قوله: ﴿وَالْفَجْرِ﴾ قول: الفجر: فجر الصبح.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني عمر بن قيس، عن محمد بن المرتفع، عن عبد الله بن الزبير أنه قال: ﴿وَالْفَجْرِ﴾ قال: الفجر: قسم أقسم الله به.\n\n* *\n\nوقوله: ﴿وَلَيَالٍ عَشْرٍ﴾\n\nاختلف أهل التأويل في هذه الليالي العشر أيّ ليال هي، فقال بعضهم: هي ليالي عشر ذي الحجة.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، وعبد الوهاب ومحمد بن جعفر، عن عوف، عن زرارة، عن ابن عباس، قال: إن الليالي العشر التي أقسم الله بها، هي ليالي العشر الأول من ذي الحجة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَلَيَالٍ عَشْرٍ﴾ : عشر الأضحى؛ قال: ويقال: العشر: أولَ السنة من المحرم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وَهب، قال: أخبرني عمر بن قيس، عن محمد بن المرتفع، عن عبد الله بن الزبير ﴿وَلَيَالٍ عَشْرٍ﴾ أوّل ذي الحجة إلى يوم النحر.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا عوف، قال: ثنا زرارة بن أوفى، قال: قال ابن عباس: إن الليالي العشر اللاتي أقسم الله بهنّ: هن الليالي الأوَل من ذي الحجة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا إسرائيل، عن أبي إسحاق، عن مسروق ﴿وَلَيَالٍ عَشْرٍ﴾ قال: عشر ذي الحجة، وهي التي وعد الله موسى ﷺ.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا عاصم الأحول، عن عكرِمة ﴿وَلَيَالٍ عَشْرٍ﴾ قال: عشر ذي الحجة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأغرّ المنقريّ، عن خليفة بن حصين، عن أبي نصر، عن ابن عباس ﴿وَلَيَالٍ عَشْرٍ﴾ قال: عشر الأضحى.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَلَيَالٍ عَشْرٍ﴾ قال: عشر ذي الحجة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَلَيَالٍ عَشْرٍ﴾ قال: كنا نحدَّث أنها عشر الأضحى.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثَور، عن معمر، عن يزيد بن أبي زياد، عن مجاهد، قال: ليس عمل في ليال من ليالي السنة أفضل منه في ليالي العشر، وهي عشر موسى التي أتمَّها الله له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن أبى إسحاق، عن مسروق، قال: ليال العشر، قال: هي أفضل أيام السنة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ، يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَلَيَالٍ عَشْرٍ﴾ يعني: عشر الأضحى.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَلَيَالٍ عَشْرٍ﴾ قال: أوّل ذي الحجة؛ وقال: هي عشر المحرّم من أوّله.\n\nوالصواب من القول في ذلك عندنا: أنها عشر الأضحى لإجماع الحجة من أهل التأويل عليه، وأن عبد الله بن أبي زياد القَطْوانيّ، حدثني قال: ثني زيد بن حباب، قال: أخبرني عياش بن عقبة، قال: ثني جُبير بن نعيم، عن أبي الزبير، عن جابر، أن رسول الله ﷺ قال: \" ﴿وَالْفَجْرِ وَلَيَالٍ عَشْرٍ﴾ قال: عَشْرُ الأضْحَى\".\n\n* *\n\nوقوله: ﴿وَالشَّفْعِ وَالْوَتْرِ وَاللَّيْلِ إِذَا يَسْرِي هَلْ فِي ذَلِكَ قَسَمٌ﴾\n\nاختلف أهل التأويل في الذي عُنِيَ به من الوتر بقوله: ﴿والْوَتْرِ﴾ فقال بعضهم: الشفع: يوم النحر، والوتر: يوم عرفة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ وعبد الوهاب ومحمد بن جعفر، عن عوف، عن زرارة بن أوفى، عن ابن عباس، قال: الوتر: يوم عرفة، والشفع: يوم الذبح.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا عوف، قال: ثنا زرارة بن أوفى، قال: قال ابن عباس: الشفع: يوم النحر، والوَتر: يوم عرفة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عفان بن مسلم، قال: ثنا همام، عن قتادة، قال: قال عكرِمة، عن ابن عباس: الشفع: يوم النحر، والوَتر: يوم عرفة.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا عبيد الله، عن عكرِمة ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الشفع: يوم النحر، والوتر: يوم عرفة.\n\n⁕ وحدثنا به مرّة أخرى، فقال: الشفع: أيام النحر، وسائر الحديث مثله.\n\n⁕ حدثني يعقوب: قال: ثنا ابن عُلَية، قال: أخبرنا عاصم الأحول، عن عكرِمة في قوله: ﴿والشَّفْعِ﴾ قال: يوم النحر ﴿والْوَتْرِ﴾ قال: يوم عرفة.\n\n⁕ حدثنا ابن حُمَيد، قال: ثنا مهران، عن سفيان، عن أبيه، عن عكرِمة، قال: الشفع: يوم النحر، والوتر: يوم عرفة.\n\n⁕ قال: ثنا مهران، عن أبي سنان، عن الضحاك ﴿وَلَيَالٍ عَشْرٍ وَالشَّفْعِ وَالْوَتْرِ﴾ قال: أقسم الله بهنّ لما يعلم من فضلهنّ على سائر الأيام، وخير هذين اليومين لما يُعلَم من فضلهما على سائر هذه الليالي ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الشفع: يوم النحر، والوَتر: يوم عرفة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: كان عكرِمة يقول: الشفع: يوم الأضحى، والوتر: يوم عرفة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: قال عكرِمة: عرفة وَتْر، والنحر شفع، عرفة يوم التاسع، والنحر يوم العاشر.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿والشَّفْعِ﴾ يوم النحر ﴿والْوَتْرِ﴾ يوم عرفة.\n\nوقال آخرون: الشفع: اليومان بعد يوم النحر، والوَتر: اليوم الثالث.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد: في قوله: ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الشفع: يومان بعد يوم النحر، والوتر: يوم النَّفْر الآخرِ، يقول الله: ﴿فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ﴾ .\n\nوقال آخرون: الشفع: الخلق كله، والوتر: الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الله وتر، وأنتم شفع، ويقال: الشفع: صلاة الغداة، والوتر صلاة المغرب.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: كلّ خلق الله شفع، السماء والأرض والبرّ والبحر والجنّ والإنس والشمس والقمر، والله الوَتر وحده.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا ابن جُريج، قال: قال مجاهد، في قوله: ﴿وَمِنْ كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ﴾ قال: الكفر والإيمان، والسعادة والشقاوة، والهدى والضلالة، والليل والنهار، والسماء والأرض، والجنّ والإنس، والوَتْر: الله؛ قال: وقال في الشفع والوتر مثل ذلك.\n\n⁕ حدثني عبد الأعلى بن واصل، قال: ثنا محمد بن عبيد، قال: ثنا إسماعيل بن أبي خالد، عن أبي صالح، في قوله: ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: خلق الله من كل شيء زوجين، والله وَتْر واحد صَمَد.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الشفع: الزوج، والوتر: الله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن جابر، عن مجاهد ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الوتر: الله، وما خلق الله من شيء فهو شفع.\n\nوقال آخرون: عُنِيَ بذلك الخلق، وذلك أن الخلق كله شفع ووتر.\n\n⁕ قال: ثنا ابن ثور، عن مَعْمر، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: الخلق كله شفع ووتر، وأقسم بالخلق.\n\n⁕ قال: ثنا ابن ثور، عن معمر، قال: قال الحسن في ذلك: الخلق كله شفع ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: كان أبي يقول: كلّ شيء خلق الله شفع ووتر، فأقسم بما خلق، وأقسم بما تبصرون وبما لا تبصرون.\n\nوقال آخرون: بل ذلك: الصلاة المكتوبة، منها الشفع كصلاة الفجر والظهر، ومنها الوتر كصلاة المغرب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قال: كان عمران بن حصين يقول: ﴿الشَّفْعِ والْوَتْرِ﴾ : الصلاة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال عمران: هي الصلاة المكتوبة فيها الشفع والوتر.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع بن أنس ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: ذلك صلاة المغرب، الشفع: الركعتان، والوتر: الركعة الثالثة، وقد رفع حديث عمران بن حصين بعضهم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا نصر بن عليّ، قال: ثني أبي، قال: ثني خالد بن قيس، عن قتادة، عن عمران بن عصام، عن عمران بن حصين، عن النبيّ ﷺ - في الشفع والوتر - قال: \"هيَ الصَّلاةُ مِنْها شَفْعٌ، وَمِنْها وَتْرٌ\".\n\n⁕ حدثنا ابن بشار، قال: ثنا عفان بن مسلم قال: ثنا همام، عن قتادة، أنه سُئل عن الشفع والوتر، فقال: أخبرني عمران بن عصام الضُّبعي، عن شيخ من أهل البصرة، عن عمران بن حصين، عن النبيّ ﷺ، قال: \"هيَ الصَّلاةُ مِنْها شَفْعٌ، وَمنها وَتْرٌ\".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عبيد الله بن موسى، قال: أخبرنا همام بن يحيى، عن عمران بن عصام، عن شيخ من أهل البصرة، عن عمران بن حصين أن رسول الله ﷺ قال في هذه الآية ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ قال: \"هيَ الصَّلاةُ مِنْها شَفْعٌ، وَمِنْها وَتْرٌ\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالشَّفْعِ وَالْوَتْرِ﴾ إن من الصلاة شفعا، وإن منها وترا.\n\n⁕ حدثنا ابن بشار، قال: ثنا عفان بن مسلم، قال: ثنا همام، عن قتادة، أنه سُئل عن الشفع والوتر، فقال: قال الحسن: هو العدد. ورُوي عن النبيّ ﷺ خبر يؤيد القول الذي ذكرنا عن أبي الزُّبير.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عبد الله بن أبي زياد القَطْوَانيّ، قال: ثنا زيد بن حُباب، قال: أخبرني عَياش بن عقبة، قال: ثني جبير بن نعيم، عن أبي الزبير، عن جابر أن رسول الله ﷺ قال: \"الشَّفْع: الْيَوْمَانِ وَالْوَتْرُ: الْيَوْمُ الْوَاحِدُ\".\n\nوالصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أقسم بالشفع والوتر، ولم يخصص نوعا من الشفع ولا من الوتر دون نوع بخبر ولا عقل، وكلّ شفع ووتر فهو مما أقسم به مما قال أهل التأويل إنه داخل في قسمه هذا لعموم قسَمه بذلك.\n\nواختلفت القرّاء في قراءة قوله: ﴿وَالْوَتْرِ﴾ فقرأته عامة قرّاء المدينة ومكة والبصرة وبعض قرّاء الكوفة بكسر الواو.\n\nوالصواب من القول في ذلك أنهما قراءتان مستفيضتان معروفتان في قَرَأةِ الأمصار، ولغتان مشهورتان في العرب، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾\n\nيقول: والليل إذا سار فذهب، يقال منه: سرى فلان ليلا يَسْرِي: إذا سار.\n\nوقال بعضهم: عُنِيَ بقوله: ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾ ليلة جَمْع، وهي ليلة المزدلفة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني عمر بن قيس، عن محمد بن المرتفع، عن عبد الله بن الزبير ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾ حتى يُذهِب بعضه بعضا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَاللَّيْلِ إِذَا يَسْر﴾ يقول: إذا ذهب.\n\n⁕ حدثني محمد بن عُمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبى يحيى، عن مجاهد: ﴿وَاللَّيْلِ إِذَا يَسْر﴾ قال: إذا سار.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العاليه ﴿وَاللَّيْلِ إِذَا يَسْر﴾ قال: والليل إذا سار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَاللَّيْلِ إِذَا يَسْر﴾ يقول: إذا سار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَاللَّيْلِ إِذَا يَسْر﴾ قال: إذا سار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَاللَّيْلِ إِذَا يَسْر﴾ قال: الليل إذا يسير.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن جابر، عن عكرِمة ﴿وَاللَّيْلِ إِذَا يَسْر﴾ قال: ليلة جمع.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الشام والعراق ﴿يَسْرِ﴾ بغير ياء. وقرأ ذلك جماعة من القرّاء بإثبات الياء، وحذف الياء في ذلك أعجب إلينا، ليوفق بين رءوس الآي إذ كانت بالراء. والعرب ربما أسقطت الياء في موضع الرفع مثل هذا، اكتفاء بكسرة ما قبلها منها، من ذلك قول الشاعر:\n\nلَيْسَ تخْفى يَسارَتِي قَدْرَ يَوْمٍ ... وَلَقَدْ تُخْفِ شِيمَتِي إعْسَارِي\n\n* *\n\nوقوله: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾\n\nيقول تعالى ذكره: هل فيما أقسمت به من هذه الأمور مقنع لذي حجر، وإنما عُنِيَ بذلك: إن في هذا القسم مكتفى لمن عقل عن ربه مما هو أغلظ منه في الإقسام. فأما معنى قوله: ﴿لِذِي حِجْرٍ﴾ : فإنه لِذِي حِجًي وذِي عقل؛ يقال للرجل إذا كان مالكا نفسه قاهرًا لها ضابطا: إنه لذو حِجْر، ومنه قولهم: حَجَر الحاكم على فلان.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب وأبو السائب، قالا ثنا ابن إدريس، قال: أخبرنا قابوس بن أبي ظبيان، عن أبيه، عن ابن عباس، في قوله: ﴿لِذِي حِجْرٍ﴾ قال: لذي النُّهَى والعقل.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿لِذِي حِجْرٍ﴾ قال: لأولي النُّهى.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ قال: ذو الحِجْر والنُّهى والعقل.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن قابوس بن أبي ظبيان، عن أبيه، عن ابن عباس: ﴿قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي عقل، لذي نُهَي.\n\n⁕ قال: ثنا مهران، عن سفيان، عن الأغرّ المِنقريّ، عن خليفة بن الحصين، عن أبي نصر، عن ابن عباس ﴿قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي لُبّ، لذي حِجَى.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد قوله: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي عقل.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد: لذي عقل، لذي رأي.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي لبّ، أو نُهى.\n\n⁕ حدثنا الحسن بن عرفة، قال: ثنا خلف بن خليفة، عن هلال بن خباب، عن مجاهد، في قوله: ﴿قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي عقل.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، عن الحسن ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي حلم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿لِذِي حِجْرٍ﴾ قال: لذي حجى؛ وقال الحسن: لذي لُبّ.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، في قوله: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ لذي حِجى، لذي عقل ولُبّ.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾ قال: لذي عقل، وقرأ: ﴿لِقَوْمٍ يَعْقِلُونَ﴾ و ﴿لأولِي الألْبابِ﴾ وهم الذين عاتبهم الله وقال: العقل واللُّبّ واحد، إلا أنه يفترق في كلام العرب.","2":1,"3":1,"4":1,"5":1,"6":"القول في تأويل قوله تعالى: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ (٦) إِرَمَ ذَاتِ الْعِمَادِ (٧) الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلادِ (٨) وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِي (٩) وَفِرْعَوْنَ ذِي الأوْتَادِ (١٠) الَّذِينَ طَغَوْا فِي الْبِلادِ (١١) ﴾\n\n.\n\n* *\n\nوقوله: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ إِرَمَ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: ألم تنظر يا محمد بعين قلبك، فترى كيف فعل ربك بعاد؟\n\nواختلف أهل التأويل في تأويل قوله: ﴿إرَمَ﴾ فقال بعضهم: هي اسم بلدة، ثم اختلف الذين قالوا ذلك في البلدة التي عُنِيت بذلك، فقال بعضهم: عُنِيت به الإسكندرية.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني يعقوب بن عبد الرحمن الزهريّ، عن أبي صخر، عن القُرَظي، أنه سمعه يقول: ﴿إِرَمَ ذَاتِ الْعِمَادِ﴾ الإسكندرية.\n\nقال أبو جعفر، وقال آخرون: هي دِمَشق.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عبد الله الهلالي من أهل البصرة، قال: ثنا عبيد الله بن عبد المجيد، قال: ثنا ابن أبي ذئب، عن المقْبري ﴿بِعَادٍ إِرَمَ ذَاتِ الْعِمَادِ﴾ قال: دمشق.\n\nوقال آخرون: عُنِي بقوله: ﴿إرَمَ﴾ : أمة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد قوله: ﴿إرَمَ﴾ قال: أمة.\n\nوقال آخرون: معنى ذلك: القديمة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إرَمَ﴾ قال: القديمة.\n\nوقال آخرون: تلك قبيلة من عاد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ إِرَمَ ذَاتِ الْعِمَادِ﴾ قال: كنا نحدّث أن إرم قبيلة من عاد، بيت مملكة عاد.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿إرَمَ﴾ قال: قبيلة من عاد كان يقال لهم: إرم، جدّ عاد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، عن ابن إسحاق ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ إِرَمَ﴾ يقول الله: بعاد إرم، إن عاد بن إرم بن عوص بن سام بن نوح.\n\nوقال آخرون: ﴿إرَمَ﴾ : الهالك.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ إِرَمَ﴾ يعني بالإرم: الهالك؛ ألا ترى أنك تقول: أرم بنو فلان؟\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿بِعَادٍ إِرَمَ﴾ الهلاك؛ ألا ترى أنك تقول أُرِمَ  بنو فلان: أي هَلَكوا.\n\nوالصواب من القول في ذلك أن يُقال: إن إرم إما بلدة كانت عاد تسكنها، فلذلك ردّت على عاد للإتباع لها، ولم يجر من أجل ذلك، وإما اسم قبيلة فلم يُجر أيضا، كما لا يُجْرى أسماء القبائل، كتميم وبكر، وما أشبه ذلك إذا أرادوا به القبيلة، وأما اسم عاد فلم يجر، إذ كان اسما أعجميا.\n\nفأما ما ذُكر عن مجاهد أنه قال: عُنِيَ بذلك القديمة، فقول لا معنى له، لأن ذلك لو كان معناه لكان محفوظا بالتنوين، وفي ترك الإجراء الدليل على أنه ليس بنعت ولا صفة.\n\nوأشبه الأقوال فيه بالصواب عندي أنها اسم قبيلة من عاد، ولذلك جاءت القراءة بترك إضافة عاد إليها، وترك إجرائها، كما يقال: ألم تر ما فعل ربك بتميم نهشل؟ فيترك إجراء نهشل، وهي قبيلة، فترك إجراؤها لذلك، وهي في موضع خفض بالردّ على تميم، ولو كانت إرم اسم بلدة، أو اسم جدّ لعاد لجاءت القراءة بإضافة عاد إليها، كما يقال: هذا عمروُ زبيدٍ وحاتمُ طيئ، وأعشى هَمْدانَ، ولكنها اسم قبيلة منها فيما أرى، كما قال قتادة، والله أعلم، فلذلك أجمعت القرّاء فيها على ترك الإضافة وترك الإجراء.\n\n* *\n\nوقوله: ﴿ذَاتِ الْعِمَادِ﴾\n\nاختلف أهل التأويل في معنى قوله: ﴿ذَاتِ الْعِمَادِ﴾ في هذا الموضع، فقال بعضهم: معناه: ذات الطول، وذهبوا في ذلك إلى قول العرب للرجل الطويل: رجل مُعَمَّد، وقالوا: كانوا طوال الأجسام.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿ذَاتِ الْعِمَادِ﴾ يعني: طولهم مثل العماد.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد قوله: ﴿ذَاتِ الْعِمَادِ﴾ قال: كان لهم جسم في السماء.\n\nوقال بعضهم: بل قيل لهم: ﴿ذَاتِ الْعِمَادِ﴾ لأنهم كانوا أهل عَمَد، ينتجِعون الغيوث، وينتقلون إلى الكلأ حيث كان، ثم يرجعون إلى منازلهم.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿الْعِمَادِ﴾ قال: أهل عَمُود لا يقيمون.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿ذَاتِ الْعِمَادِ﴾ قال: ذُكر لنا أنهم كانوا أهل عَمُود لا يقيمون، سيارة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿ذَاتِ الْعِمَادِ﴾ قال: كانوا أهلَ عمود.\n\nوقال آخرون: بل قيل ذلك لهم لبناء بناه بعضهم، فشيَّد عَمَده، ورفع بناءه.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِرَمَ ذَاتِ الْعِمَادِ﴾ قال: عاد قوم هود بنَوها وعملوها حين كانوا في الأحقاف، قال: ﴿لَمْ يُخْلَقْ مِثْلُهَا﴾ مثل تلك الأعمال في البلاد، قال: وكذلك في الأحقاف في حضرموت، ثم كانت عاد، قال: وثم أحقاف الرمل، كما قال الله: بالأحقاف من الرمل، رمال أمثال الجبال تكون مظلة مجوّفة.\n\nوقال آخرون: قيل ذلك لهم لشدّة أبدانهم وقواهم.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿ذَاتِ الْعِمَادِ﴾ يعني: الشدّة والقوّة.\n\nوأشبه الأقوال في ذلك بما دلّ عليه ظاهر التنزيل قول من قال: عُنِيَ بذلك أنهم كانوا أهل عمود، سيارة لأن المعروف في كلام العرب من العماد، ما عمل به الخيام من الخشب والسواري التي يحمل عليها البناء، ولا يعلم بناء كان لهم بالعماد بخبر صحيح، بل وجه أهل التأويل قوله: ﴿ذَاتِ الْعِمَادِ﴾ إلى أنه عُنِيَ به طول أجسامهم، وبعضهم إلى أنه عُنِيَ به عماد خيامهم، فأما عماد البنيان، فلا يعلم كثير أحد من أهل التأويل وجهه إليه، وتأويل القرآن إنما يوجه إلى الأغلب الأشهر من معانيه ما وجد إلى ذلك سبيلا دون الأنكر.\n\n* *\n\nوقوله: ﴿الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلادِ﴾\n\nيقول جلّ ثناؤه: ألم تر كيف فعل ربك بعاد، إرم التي لم يخلق مثلها في البلاد، يعني: مثل عاد، والهاء عائدة على عاد. وجائز أن تكون عائدة على إرم لما قد بينا قبل أنها قبيلة. وإنما عُنِيَ بقوله: لم يُخْلق مثلها في العِظَم والبطش والأيد.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلادِ﴾ ذكر أنهم كانوا اثني عشر ذراعا طولا في السماء.\n\nوقال آخرون: بل معنى ذلك: ذات العماد التي لم يُخلق مثلها في البلاد، لم يخلق مثل الأعمدة في البلاد، وقالوا: التي لم يخلق مثلها من صفة ذات العماد، والهاء التي في مثلها إنما هي من ذكر ذات العماد.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: فذكر نحوه. وهذا قول لا وجه له، لأن العماد واحد مذكر، والتي للأنثى، ولا يوصف المذكر بالتي، ولو كان ذلك من صفة العماد لقيل: الذي لم يخلق مثله في البلاد، وإن جعلت التي لإرم، وجعلت الهاء عائدة في قوله: ﴿مِثْلُهَا﴾ عليها، وقيل: هي دمشق أو إسكندرية، فإن بلاد عاد هي التي وصفها الله في كتابه فقال: ﴿وَاذْكُرْ أَخَا عَادٍ إِذْ أَنْذَرَ قَوْمَهُ بِالأحْقَافِف﴾ والأحقاف: هي جمع حِقْف، وهو ما انعطف من الرمل وانحنى، وليست الإسكندرية ولا دمشق من بلاد الرمال، بل ذلك الشِّحْرَ من بلاد حضرموت، وما والاها.\n\n* *\n\nوقوله: ﴿وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِي﴾\n\nيقول: وبثمود الذين خرقوا الصخر ودخلوه فاتخذوه بيوتا، كما قال جلّ ثناؤه: ﴿وَكَانُوا يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا آمِنِينَ﴾ والعرب تقول: جاب فلان الفلاة يجوبها جوبا: إذا دخلها وقطعها، ومنه قول نابغة:\n\nأتاكَ أبُو لَيْلَى يَجُوبُ بِهِ الدُّجَى ... دُجَى اللَّيلِ جَوّابُ الفَلاةِ عَمِيمُ\n\nيعني بقوله: يجوب يدخل ويقطع.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ﴾ يقول: فخرقوها.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ﴾ يعني: ثمود قوم صالح، كانوا ينحتون من الجبال بيوتا.\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي يحيى، عن مجاهد في قوله: ﴿الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ﴾ قال: جابوا الجبال، فجعلوها بيوتا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ﴾ : جابوها ونحتوها بيوتا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: ﴿جَابُوا الصَّخْرَ﴾ قال: نَقبوا الصخر.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿جَابُوا الصَّخْرَ بِالْوَادِ﴾ يقول: قَدُّوا الحجارة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ﴾ : ضربوا البيوت والمساكن في الصخر في الجبال، حتى جعلوا فيها مساكن. جابوا: جوّبوها تجوّبوا البيوت في الجبال، قال قائل:\n\nألا كُلُّ شَيْءٍ ما خَلا اللهَ بائِدٌ ... كمَا بادَ حَيٌّ مِنْ شَنِيقٍ وَمارِدِ\n\nهُمُ ضَرَبُوا فِي كُلّ صَلاءَ صَعْدَةٍ ... بأيْدٍ شِدَادٍ أيِّدَاتِ السَّوَاعِدِ\n\n* *\n\nوقوله: ﴿وَفِرْعَوْنَ ذِي الأوْتَادِ﴾\n\nيقول جلّ ثناؤه: ألم تر كيف فعل ربك أيضا بفرعون صاحب الأوتاد.\n\nواختلف أهل التأويل في معنى قوله: ﴿ذِي الأوْتَادِ﴾ ولم قيل له ذلك، فقال بعضهم: معنى ذلك: ذي الجنود الذي يقوّون له أمره، وقالوا: الأوتاد في هذا الموضع: الجنود.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَفِرْعَوْنَ ذِي الأوْتَادِ﴾ قال: الأوتاد: الجنود الذين يشدّون له أمره، ويقال: كان فرعون يُوتِد في أيديهم وأرجلهم أوتادًا من حديد، يعلقهم بها.\n\nوقال آخرون: بل قيل له ذلك لأنه كان يُوتِد الناس بالأوتاد.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ذِي الأوْتَادِ﴾ قال: كان يوتد الناس بالأوتاد.\n\nوقال آخرون: كانت مظالّ وملاعب يلعب له تحتها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَفِرْعَوْنَ ذِي الأوْتَادِ﴾ ذُكر لنا أنها كانت مظال وملاعب يلعب له تحتها من أوتاد وحبال.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿ذِي الأوْتَادِ﴾ قال: ذي البناء كانت مظال يلعب له تحتها، وأوتادا تضرب له.\n\n⁕ قال: ثنا ابن ثور، عن معمر، عن ثابت البناني، عن أبي رافع، قال: أوتد فرعون لامرأته أربعة أوتاد، ثم جعل على ظهرها رحا عظيمة حتى ماتت.\n\nوقال آخرون: بل ذلك لأنه كان يعذّب الناس بالأوتاد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل، عن محمود، عن سعيد بن جُبير ﴿وَفِرْعَوْنَ ذِي الأوْتَادِ﴾ قال: كان يجعل رجلا هاهنا ورجلا هاهنا، ويدا هاهنا ويدا هاهنا بالأوتاد.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ذِي الأوْتَادِ﴾ قال: كان يوتد الناس بالأوتاد.\n\nوقال آخرون: إنما قيل ذلك لأنه كان له بنيان يعذّب الناس عليه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل، عن رجل، عن سعيد بن جُبير ﴿وَفِرْعَوْنَ ذِي الأوْتَادِ﴾ قال: كان له منَارات يعذّبهم عليها.\n\nوأولى هذه الأقوال عندي بالصواب قول من قال: عُنِيَ بذلك: الأوتاد التي تُوتَد، من خشب كانت أو حديد، لأن ذلك هو المعروف من معاني الأوتاد، ووصف بذلك لأنه إما أن يكون كان يعذّب الناس بها، كما قال أبو رافع وسعيد بن جُبير، وإما أن يكون كان يُلعب له بها.\n\n* *\n\nوقوله: ﴿الَّذِينَ طَغَوْا فِي الْبِلادِ﴾\n\nيعني بقوله جلّ ثناؤه ﴿الذين﴾ : عادًا وثمود وفرعون وجنده، ويعني بقوله ﴿طَغَوْا﴾ : تجاوزوا ما أباحه لهم ربهم، وعتوا على ربهم إلى ما حظره عليهم من الكفر به.\n\n* *\n\nوقوله: ﴿فِي الْبِلادِ﴾\n\n: التي كانوا فيها.","7":6,"8":6,"9":6,"10":6,"11":6,"12":"القول في تأويل قوله تعالى: ﴿فَأَكْثَرُوا فِيهَا الْفَسَادَ (١٢) فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ (١٣) إِنَّ رَبَّكَ لَبِالْمِرْصَادِ (١٤) فَأَمَّا الإنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ (١٥) ﴾\n\n.\n\nيقول تعالى ذكره: فأكثروا في البلاد المعاصي، وركوب ما حرّم الله عليهم ﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ﴾ يقول تعالى ذكره: فأنزل بهم يا محمد ربك عذابه، وأحلّ بهم نقمته، بما أفسدوا في البلاد، وطغَوْا على الله فيها. وقيل: فصبّ عليهم ربك سَوط عذاب. وإنما كانت نِقَما تنزل بهم، إما ريحا تُدَمرهم، وإما رَجفا يُدَمدم عليهم، وإما غَرَقا يُهلكهم من غير ضرب بسوط ولا عصا؛ لأنه كان من أليم عذاب القوم الذين خوطبوا بهذا القرآن، الجلد بالسياط، فكثر استعمال القوم الخبر عن شدّة العذاب الذي يعذّب به الرجل منهم أن يقولوا: ضُرب فلان حتى بالسياط، إلى أن صار ذلك مثلا فاستعملوه في كلّ معذَّب بنوع من العذاب شديد، وقالوا: صَبّ عليه سَوْط عذاب.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿سَوْطَ عَذَابٍ﴾ قال: ما عذّبوا به.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ﴾ قال: العذاب الذي عذّبهم به سماه: سوط عذاب.\n\n* *\n\nوقوله: ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: إن ربك يا محمد لهؤلاء الذين قصصت عليك قَصَصَهم، ولِضُرَبائهم من أهل الكفر، لبالمِرصاد يرصدهم بأعمالهم في الدنيا وفي الآخرة، على قناطر جهنم، ليكردسهم فيها إذا وردوها يوم القيامة.\n\nواختلف أهل التأويل في تأويله، فقال بعضهم: معنى قوله: ﴿لَبِالْمِرْصَادِ﴾ بحيث يرى ويسمع.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾ يقول: يَرى ويسمع.\n\nوقال آخرون: يعني بذلك أنه بمَرصد لأهل الظلم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن المبارك بن مجاهد، عن جُويْبِر، عن الضحاك في هذه الآية، قال: إذا كان يوم القيامة، يأمر الربّ بكرسيه، فيوضع على النار، فيستوي عليه، ثم يقول: وعزّتي وجلالي، لا يتجاوزني اليوم ذو مَظلِمة، فذلك قوله: ﴿لَبِالْمِرْصَادِ﴾ .\n\n⁕ قال: ثنا الحكم بن بشير، قال: ثنا عمرو بن قيس، قال: بلغني أن على جهنم ثلاث قناطر: قنطرة عليها الأمانة، إذا مرّوا بها تقول: يا ربّ هذا أمين، يا ربّ هذا خائن، وقنطرة عليها الرحِم، إذا مرّوا بها تقول: يا ربّ هذا واصل، يا ربّ هذا قاطع؛ وقنطرة عليها الربّ ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾ .\n\n⁕ قال: حدثنا مهران، عن سفيان ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾ يعني: جهنم عليها ثلاث قناطر: قنطرة فيها الرحمة، وقنطرة فيها الأمانة، وقنطرة فيها الربّ تبارك وتعالى.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾ قال: مِرْصاد عمل بني آدم.\n\n* *\n\nوقوله: ﴿فَأَمَّا الإنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ﴾\n\nيقول تعالى ذكره: فأما الإنسان إذا ما امتحنه ربه بالنعم والغنى ﴿فأكْرَمَهُ﴾ بالمال، وأفضل عليه، ﴿وَنَعَّمَهُ﴾ بما أوسع عليه من فضله ﴿فَيَقُولُ رَبِّي أَكْرَمَنِ﴾ فيفرح بذلك ويسرّ به ويقول: ربي أكرمني بهذه الكرامة.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَأَمَّا الإنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ﴾ وحقّ له.","13":12,"14":12,"15":12,"16":"القول في تأويل قوله تعالى: ﴿وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ (١٦) كَلا بَل لا تُكْرِمُونَ الْيَتِيمَ (١٧) وَلا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ (١٨) وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا (١٩) ﴾\n\n.\n\n* *\n\nوقوله: ﴿وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾\n\nيقول: وأما إذا ما امتحنه ربه بالفقر ﴿فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾ يقول: فضيَّق عليه رزقه وقَتَّره، فلم يكثر ماله، ولم يوسع عليه ﴿فَيَقُولُ رَبِّي أَهَانَنِ﴾ يقول: فيقول ذلك الإنسان: ربي أهانني، يقول: أذلني بالفقر، ولم يشكر الله على ما وهب له من سلامة جوارحه، ورزقه من العافية في جسمه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ﴾ ما أسرع كفر ابن آدم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، قوله: ﴿فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾ قال: ضَيَّقه.\n\nواختلفت القرّاء في قراءة قوله: ﴿فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾ فقرأت عامة قرّاء الأمصار ذلك بالتخفيف، فقَدَر: بمعنى فقتر، خلا أبي جعفر القارئ، فإنه قرأ ذلك بالتشديد ﴿فَقَدَّرَ﴾ . وذُكر عن أبي عمرو بن العلاء أنه كان يقول: قدّر، بمعنى يعطيه ما يكفيه، ويقول: لو فعل ذلك به ما قال ربي أهانني.\n\nوالصواب من قراءة ذلك عندنا بالتخفيف، لإجماع الحجة من القرّاء عليه.\n\n* *\n\nوقوله: ﴿كَلا بَل لا تُكْرِمُونَ الْيَتِيمَ﴾\n\nاختلف أهل التأويل في المعنيّ بقوله: ﴿كَلا﴾ في هذا الموضع، وما الذي أنكر بذلك، فقال بعضهم: أنكر جلّ ثناؤه أن يكون سبب كرامته من أكرم كثرة ماله، وسبب إهانته من أهان قلة ماله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ﴾ ما أسرع ما كفر ابن آدم، يقول الله جلّ ثناؤه: كلا إني لا أكرم من أكرمت بكثرة الدنيا، ولا أهين من أهنت بقلتها، ولكن إنما أكرم من أكرمت بطاعتي، وأُهينُ من أهنت بمعصيتي.\n\nوقال آخرون: بل أنكر جلّ ثناؤه حمد الإنسان ربه على نِعمه دون فقره، وشكواه الفاقة، وقالوا: معنى الكلام، كلا أي: لم يكن ينبغي أن يكون هكذا، ولكن كان ينبغي أن يحمده على الأمرين جميعا، على الغنى والفقر.\n\nوأولى القولين في ذلك بالصواب القول الذي ذكرناه عن قتادة لدلالة قوله: ﴿بَل لا تُكْرِمُونَ الْيَتِيمَ﴾ والآيات التي بعدها، على أنه إنما أهان من أهان بأنه لا يكرم اليتيم، ولا يَحُضّ على طعام المسكين، وسائر المعاني التي عدّد، وفي إبانته عن السبب الذي من أجله أهان من أهان، الدلالة الواضحة على سبب تكريمه من أكرم، وفي تبيينه ذلك عَقيب قوله: ﴿فَأَمَّا الإنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ﴾ بيان واضح عن الذي أنكر من قوله ما وصفنا.\n\n* *\n\nوقوله: ﴿بَل لا تُكْرِمُونَ الْيَتِيمَ﴾\n\nيقول تعالى ذكره: بل إنما أهنت من أهَنت من أجل أنه لا يكرم اليتيم، فأخرج الكلام على الخطاب، فقال: بل لستم تكرمون اليتيم، فلذلك أهنتكم ﴿وَلا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ﴾ .\n\nواختلفت القرّاء في قراءة ذلك، فقرأه من أهل المدينة أبو جعفر وعامة قرّاء الكوفة ﴿بَل لا تُكْرِمُونَ الْيَتِيمَ وَلا تَحَاضُّونَ﴾ بالتاء أيضا وفتحها وإثبات الألف فيها، بمعنى: ولا يحضّ بعضكم بعضًا على طعام المسكين. وقرأ ذلك بعض قرّاء مكة وعامة قرّاء المدينة بالتاء وفتحها وحذف الألف ﴿وَلا تَحُضُّون﴾ بمعنى: ولا تأمرون بإطعام المسكين. وقرأ ذلك عامة قرّاء البصرة ﴿يَحُضُّون﴾ بالياء وحذف الألف بمعنى: ولا يكرم القائلون إذا ما ابتلاه ربه فأكرمه ونعمه ربي أكرمني، وإذا قدر عليه رزقه ربي أهانني - اليتيم - ﴿ولا يحضون على طعام المسكين﴾ وكذلك يقرأ الذين ذكرنا من أهل البصرة ﴿يُكْرِمُونَ﴾ وسائر الحروف معها بالياء على وجه الخبر عن الذين ذكرت. وقد ذُكر عن بعضهم أنه قرأ ﴿تُحاضُّونَ﴾ بالتاء وضمها وإثبات الألف، بمعنى: ولا تحافظون.\n\nوالصواب من القول في ذلك عندي أن هذه قراءات معروفات في قَرَأة الأمصار، أعني: القراءات الثلاث صحيحات المعاني، فبأيّ ذلك قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾\n\nيقول تعالى ذكره: وتأكلون أيها الناس الميراث أكلا لمًّا، يعني: أكلا شديدًا لا تتركون منه شيئا، وهو من قولهم: لممت ما على الخِوان أجمع، فأنا ألمه لمًّا: إذا أكلت ما عليه فأتيت على جميعه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عمرو بن سعيد بن يسار القرشي، قال: ثنا الأنصاري، عن أشعث، عن الحسن ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ قال: الميراث.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَتَأْكُلُونَ التُّرَاثَ﴾ أي الميراث، وكذلك في قوله: ﴿أَكْلا لَمًّا﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ يقول: تأكلون أكلا شديدا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلية، عن يونس، عن الحسن، في قوله: ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ قال: نصيبه ونصيب صاحبه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد قوله: ﴿أَكْلا لَمًّا﴾ قال: اللمّ السفّ، لفّ كل شيء.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَكْلا لَمًّا﴾ أي: شديدا.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿أَكْلا لَمًّا﴾ يقول: أكلا شديدا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قول الله: ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ قال: الأكل اللمّ: الذي يأكل كلّ شيء يجده ولا يسأل، فأكل الذي له والذي لصاحبه، كانوا لا يُوَرِّثون النساء، ولا يورّثون الصغار، وقرأ: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ فِي يَتَامَى النِّسَاءِ اللاتِي لا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ وَالْمُسْتَضْعَفِينَ مِنَ الْوِلْدَانِ﴾ أي: لا تورِّثونهنّ أيضا ﴿أَكْلا لَمًّا﴾ يأكل ميراثه، وكلّ شيء لا يسأل عنه، ولا يدري أحلال أو حرام.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ . يقول: سَفًّا.\n\n⁕ حدثني ابن عبد الرحيم البرقيّ، قال: ثنا عمرو بن أبي سلمة البستيّ، عن زُهير، عن سالم، قال: قد سمعتُ بكر بن عبد الله يقول في هذه الآية: ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلا لَمًّا﴾ قال اللمّ: الاعتداء في المِيراث، يأكل ميراثه وميراث غيره.","17":16,"18":16,"19":16,"20":"القول في تأويل قوله تعالى: ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا (٢٠) كَلا إِذَا دُكَّتِ الأرْضُ دَكًّا دَكًّا (٢١) وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا (٢٢) وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الإنْسَانُ وَأَنَّى لَهُ الذِّكْرَى (٢٣) ﴾\n\n.\n\nيعني تعالى ذكره بقوله: ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ وتحبون جمع المال أيها الناس واقتناءه حبا كثيرا شديدا، من قولهم: قد جمّ الماء في الحوض: إذا اجتمع، ومنه قول زُهير بن أبي سلمى:\n\nفَلَمَّا ورَدْنَ المَاءَ زُرْقًا جِمامُهُ ... وَضَعْنَ عِصِيَّ الْحاضِرِ المُتَخَيَّمِ\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ يقول: شديدا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ فيحبون كثرة المال.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿حُبًّا جَمًّا﴾ قال: الجمّ: الكثير.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ : أي حبا شديدا.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿حُبًّا جَمًّا﴾ : يحبون كثرة المال.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ قال: الجمّ: الشديد.\n\nويعني جلّ ثناؤه بقوله: ﴿كَلا﴾ : ما هكذا ينبغي أن يكون الأمر. ثم أخبر جلّ ثناؤه عن ندمهم على أفعالهم السِّيئة في الدنيا، وتلهُّفهم على ما سلف منهم حين لا ينفعهم الندم، فقالّ جل ثناؤه: ﴿إِذَا دُكَّتِ الأرْضُ دَكًّا دَكًّا﴾ يعني: إذا رجت وزُلزلت زلزلة، وحرّكت تحريكا بعد تحريك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿إِذَا دُكَّتِ الأرْضُ دَكًّا دَكًّا﴾ يقول: تحريكها.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني حرملة بن عمران، أنه سمع عمر مولى غُفْرة يقول: إذا سمعت الله يقول: كلا فإنما يقول: كذبت.\n\n* *\n\nوقوله: ﴿وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا﴾\n\nيقول تعالى ذكره: وإذا جاء ربك يا محمد وأملاكه صفوفا صفا بعد صفّ.\n\nكما:-\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر وعبد الوهاب، قالا ثنا عوف، عن أبي المنهال، عن شهر بن حوشب، عن ابن عباس رضي الله عنهما أنه قال: إذا كان يوم القيامة مدّت الأرض مدّ الأديم، وزيد في سعتها كذا وكذا، وجمع الخلائق بصعيد واحد، جنهم وإنسهم، فإذا كان ذلك اليوم قيضت  هذه السماء الدنيا عن أهلها على وجه الأرض، وَلأهل السماء وحدهم أكثر من أهل الأرض جنهم وإنسهم بضعف فإذا نثروا على وجه الأرض فزِعوا منهم، فيقولون: أفيكم ربنا: فيفزعون من قولهم ويقولون: سبحان ربنا ليس فينا، وهو آت، ثم تقاض السماء الثانية، وَلأهل السماء الثانية وحدهم أكثر من أهل السماء الدنيا ومن جميع أهل الأرض بضعف جنهم وإنسهم، فإذا نثروا على وجه الأرض فزع إليهم أهل الأرض، فيقولون: أفيكم ربنا؟ فيفزعون من قولهم ويقولون: سبحان ربنا، ليس فينا، وهو آت، ثم تقاضُ السموات سماء سماء، كلما قيضت سماء عن أهلها كانت أكثر من أهل السموات التي تحتها ومن جميع أهل الأرض بضعف، فإذا نثروا على وجه الأرض، فزِع إليهم أهل الأرض، فيقولون لهم مثل ذلك، ويرجعون إليهم مثل ذلك، حتى تقاض السماء السابعة، فلأهل السماء السابعة أكثر من أهل ستِّ سموات، ومن جميع أهل الأرض بضعف، فيجيء الله فيهم والأمم جِثيّ صفوف، وينادي مناد: ستعلمون اليوم من أصحاب الكرم، ليقم الحمادون لله على كل حال؛ قال: فيقومون فيسرحون إلى الجنة، ثم ينادي الثانية: ستعلمون اليوم من أصحاب الكرم، أين الذين كانت تتجافى جنوبهم عن المضاجع، يدعون ربهم خوفا وطمعًا، ومما رزقناهم ينفقون؟ فيسرحون إلى الجنة؛ ثم ينادي الثانية: ستعلمون اليوم من أصحاب الكرم: أين الذين لا تلهيهم تجارة ولا بيع عن ذكر الله، وإقام الصلاة وإيتاء الزكاة، يخافون يوما تتقلَّب فيه القلوب والأبصار فيقومون فيسرحون إلى الجنة؛ فإذا أخذ من هؤلاء ثلاثة خرج عُنُق من النار، فأشرف على الخلائق، له عينان تبصران، ولسان فصيح، فيقول: إني وكلت منكم بثلاثة: بكلّ جبار عنيد، فيلقُطهم من الصفوف لقط الطير حبّ السمسم، فيحبس بهم في جهنم، ثم يخرج ثانية فيقول: إني وكلت منكم بمن آذى الله ورسوله فيلقطهم لقط الطير حبّ السمسم، فيحبس بهم في جهنم، ثم يخرج ثالثة، قال عوف: قال أبو المنهال: حسبت أنه يقول: وكلت بأصحاب التصاوير، فيلتقطهم من الصفوف لقط الطير حبّ السمسم، فيحبس بهم في جهنم، فإذا أخذ من هؤلاء ثلاثة، ومن هؤلاء ثلاثة، نُشرت الصحف، ووُضعت الموازين، ودُعي الخلائق للحساب.\n\n⁕ حدثني موسى بن عبد الرحمن قال: ثنا أبو أُسامة، عن الأجلح، قال: سمعت الضحاك بن مزاحم يقول: إذا كان يوم القيامة، أمر الله السماء الدنيا بأهلها، ونزل من فيها من الملائكة، وأحاطوا بالأرض ومن عليها، ثم الثانية، ثم الثالثة، ثم الرابعة، ثم الخامسة، ثم السادسة، ثم السابعة، فصَفُّوا صفًا دون صفّ، ثم ينزل الملك الأعلى على مجنبته اليسرى جهنم، فإذا رآها أهل الأرض ندّوا، فلا يأتون قطرا من أقطار الأرض إلا وجدوا سبعة صفوف من الملائكة، فيرجعون إلى المكان الذي كانوا فيه فذلك قول الله: ﴿إِنِّي أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُمْ مِنَ اللَّهِ مِنْ عَاصِم﴾ ، وذلك قوله: ﴿وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ وقوله: ﴿يَا مَعْشَرَ الْجِنِّ وَالإنْسِ إِنِ اسْتَطَعْتُمْ أَنْ تَنْفُذُوا مِنْ أَقْطَارِ السَّمَاوَاتِ وَالأرْضِ فَانْفُذُوا لا تَنْفُذُونَ إِلا بِسُلْطَانٍ﴾ وذلك قول الله: ﴿وَانْشَقَّتِ السَّمَاءُ فَهِيَ يَوْمَئِذٍ وَاهِيَةٌ وَالْمَلَكُ عَلَى أَرْجَائِهَا﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عبد الرحمن بن محمد المحاربيّ، عن إسماعيل بن رافع المدني، عن يزيد بن أبي زياد، عن محمد بن كعب القُرَظيّ، عن رجل من الأنصار، عن أبي هريرة، قال: قال رسول الله ﷺ: \"تُوقفُونَ مَوْقِفا وَاحِدًا يَوْمَ الْقِيامَةِ مِقْدَارَ سَبْعِينَ عاما، لا يُنْظُر إلَيْكُمْ وَلا يُقْضَى بَيْنَكُمْ، قَدْ حُصِرَ عَلَيْكُمْ، فَتَبْكُونَ حتى يَنْقطِعَ الدَّمْعُ، ثُمَّ تَدْمعُون دما وَتَبْكُون حتى يَبْلُغَ ذلكَ مِنْكُمْ الأذْقَانَ، أوْ يُلْجِمَكُمْ فَتَضُجُّونَ، ثُمَّ تَقُولُونَ مَنْ يَشْفَعُ لَنا إلى رَبِّنا، فَيَقْضِي بَيْنَنا، فَيَقُولُونَ مَنْ أحَقُّ بِذلكَ مِنْ أبِيكُمْ، جَعَلَ اللهُ تُرْبَتَهُ وَخَلْقَهُ بِيَدِهِ، وَنَفَخَ فِيهِ مِنْ رُوحِهِ، وكَلَّمَهُ قُبُلا فَيُؤْتَى آدَمُ ﷺ فَيُطْلَبُ ذلكَ إلَيْهِ فَيأْبَى، ثُمَّ يَسْتَقْرُونَ الأنبِياءَ نَبِيًّا نَبِيًّا، كُلَّما جاءُوا نَبِيًّا أبى \"قال رسولُ الله ﷺ: \"حتى يَأْتونِي، فإذَا جاءُونِي خَرَجْتُ حتى آتِي الفَحْص \"، قال أبو هريرة: يا رسول الله، ما الفحصُ؟ قال: \"قُدَّامَ العَرْشِ، فأخِرُّ ساجِدًا، فَلا أزَالُ ساجِدًا حتى يَبْعَثَ اللهُ إليَّ مَلَكًا، فَيأخُذَ بعَضُدِي، فَيرْفَعَنِي ثُمَّ يَقُولُ اللهُ لِي: مُحَمَّدٌ، وَهُوَ أعْلَمُ، فأقُولُ: نَعْم، فَيَقُولُ: ما شأنُكَ؟ فأقول: يا رَبِّ وَعَدْتَنِي الشَّفاعَةَ، شَفِّعْنِي فِي خَلْقِكَ فاقْضِ بَيْنَهُمْ، فَيَقُولُ: قَدْ شَفَّعْتُكَ، أنا آتِيكُمْ فأقْضِي بَيْنَكُمْ\". قال رسولُ الله ﷺ: \"فأنصَرِفُ حتى أقِفَ مَعَ النَّاسِ، فَبَيْنا نَحْنُ وَقُوفٌ، سَمِعْنا حِسًّا مِنَ السَّماءِ شَدِيدًا، فَهالَنا، فَنزلَ أهْلُ السَّماءِ الدُّنْيا بِمِثْلَيْ مَنْ فِي الأرْضِ مِنَ الجِنّ والإنسِ، حتى إذَا دنوْا مِنَ الأرْضِ، أشْرَقَتِ الأرْضُ، بِنُورِهِمْ، وأخَذُوا مَصَافَّهُمْ، وَقُلْنَا لَهُمْ: أفِيكُمْ رَبُّنا؟ قالوا: لا وَهُوَ آتٍ، ثُمَّ يَنزلُ أهْلُ السَّماءِ الثَّانِيَةِ بِمِثْلَيْ مَنْ نزلَ مِنَ المَلائِكَةِ، وَبِمِثْلَيْ مَنْ فِيها مِنَ الجِنّ وَالإنْسِ، حتى إذَا دَنَوْا مِنَ الأرْضِ أشْرَقَتِ الأرضُ بِنُورِهِمْ، وأخَذُوا مَصَافَّهُمْ، وَقُلْنَا لَهُمْ: أفِيكُمْ رَبُّنا؟ قالوا: لا وَهُوَ آتٍ. ثُمَّ نزلَ أهْلُ السَّمَوَاتِ عَلى قَدْرِ ذلكَ مِنَ الضِّعْفِ حتى نزلَ الجَبَّارُ فِي ظُلَلٍ مِنَ الغَمامِ وَالمَلائِكَةِ، وَلَهُمْ زَجَلٌ مِنْ تَسْبِيحِهِمْ، يَقُولُونَ: سُبْحانَ ذِي المُلْكِ وَالمَلَكُوتِ، سُبْحانَ رَبِّ العَرْشِ ذِي الجَبَرُوتِ، سُبْحَانَ الْحَيِّ الَّذِي لا يَمُوتُ سُبْحانَ الَّذِي يميت الخلائق ولا يَمُوتُ، سُبُّوحٌ قُدُّوسٌ رَبُّ المَلائِكَةِ والرُّوحِ، قُدُّوسٌ قُدُّوسٌ، سُبْحانَ رَبِّنا الأعْلَى سُبْحان ذِي الجَبرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِياءِ والسُّلْطانِ والعَظَمَةِ سُبْحانَهُ أبَدًا أبَدًا، يَحْمِلُ عَرْشَهُ يَوْمَئِذٍ ثمَانِيَةٌ، وَهمُ اليَوْمَ أرْبَعَةٌ، أقْدَامُهُم على تُخُومِ الأرْضِ السُّفْلَى، والسَّمَوَاتُ إلى حُجَزِهِمْ، وَالعَرْشُ عَلى مَناكِبِهمْ، فَوَضَعَ الله عَرْشَهُ حَيْثُ شَاء مِنَ الأرْض، ثُمَّ يُنادِي بِنِدَاءٍ يُسْمِعُ الخَلائِقَ فَيَقُولُ يا مَعْشَرَ الجِنِّ والإنْسِ، إنِّي قَدْ أنْصَتُّ مُنْذُ يَوْمِ خَلَقْتُكُمْ إلى يَوْمِكُمْ هَذَا، أسمَعُ كَلامَكُمْ، وأُبْصِرُ أعمالَكمْ، فَأنْصِتُوا إليَّ، فإنَّمَا هِيَ صُحُفُكُمْ وأعمالكُمْ تُقْرأُ علَيْكُمْ فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ، وَمَنْ وَجَدَ غَيرَ ذلكَ فَلا يَلُومَنَّ إلا نَفْسَهُ، ثُمَّ يأْمُرُ اللهُ جَهَنَّمَ فَتُخْرِجُ مِنْها عُنُقا ساطِعا مُظْلِما، ثُمَّ يَقُولُ اللهُ: ﴿أَلَمْ أَعْهَدْ إِلَيْكُمْ يَابَنِي آدَمَ أَنْ لا تَعْبُدُوا الشَّيْطَانَ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾ إلى قوله: ﴿هَذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ﴾ ، ﴿وَامْتَازُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ﴾ فيتميز الناس ويَجْثُونَ، وَهِيَ التي يَقُولُ اللهُ: ﴿وَتَرَى كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَى إِلَى كِتَابِهَا الْيَوْمَ ... ﴾ الآية، فَيَقْضِي اللهُ بَينَ خَلْقِهِ الجِنِّ والإنْسِ وَالْبَهائمِ، فإنَّهُ لَيَقِيدُ يَوْمَئِذٍ لِلْجَمَّاءِ مِنْ ذَاتِ القُرُونِ، حتى إذَا لَمْ يَبْقَ تَبِعَةٌ عِنْدَ وَاحِدةٍ لأخْرَى قال اللهُ: كُونُوا تُرَابًا، فَعِنْدَ ذلكَ يَقُولُ الكافِرُ يا لَيْتَني كُنْتُ تُرَابًا، ثُمَّ يَقْضِي اللهُ سُبْحانَهُ بَينَ الجِنِّ والإنْسِ\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا﴾ صفوف الملائكة.\n\n* *\n\nوقوله: ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾\n\nيقول تعالى ذكره: وجاء الله يومئذ بجهنم.\n\nكما:-\n\n⁕ حدثنا الحسن بن عرفة قال: ثنا مروان الفزاريّ، عن العلاء بن خالد الأسديّ، عن شقيق بن سلمة، قال: قال عبد الله بن مسعود، في قوله: ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ قال: جيء بها تُقاد بسبعين ألف زمام، مع كلّ زمام سبعون ألف ملك يقودونها.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن عاصم بن بهدلة، عن أبي وائل ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ قال: يُجاء بها يوم القيامة تُقاد بسبعين ألف زمام، مع كلّ زمام سبعون ألف ملك.\n\n⁕ حدثنا ابن حميد، قال: ثنا الحكم بن بشير، قال: ثنا عمرو بن قيس، عن قتادة، قال: جَنْبتيه: الجنة والنار؛ قال: هذا حين ينزل من عرشه إلى كرسيه لحساب خلقه، وقرأ: ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ قال: جيء بها مزمومة.\n\n* *\n\nوقوله: ﴿يَوْمَئِذٍ يَتَذَكَّرُ الإنْسَانُ﴾\n\nيقول تعالى ذكره: يومئذ يتذكر الإنسان تفريطه في الدنيا في طاعة الله، وفيما يقرّب إليه من صالح الأعمال ﴿وَأَنَّى لَهُ الذِّكْرَى﴾ يقول: من أيّ وجه له التذكير.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَأَنَّى لَهُ الذِّكْرَى﴾ يقول: وكيف له","21":20,"22":20,"23":20,"24":"القول في تأويل قوله تعالى: ﴿يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي (٢٤) فَيَوْمَئِذٍ لا يُعَذِّبُ عَذَابَهُ أَحَدٌ (٢٥) وَلا يُوثِقُ وَثَاقَهُ أَحَدٌ (٢٦) يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ (٢٧) ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً (٢٨) فَادْخُلِي فِي عِبَادِي (٢٩) وَادْخُلِي جَنَّتِي (٣٠) ﴾\n\n.\n\n* *\n\nوقوله: ﴿يَالَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾\n\nيقول تعالى ذكره مخبرا عن تلهُّف ابن آدم يوم القيامة، وتندّمه على تفريطه في الصَّالِحات من الأعمال في الدنيا التي تورثه بقاء الأبد في نعيم لا انقطاع له، يا ليتني قدمت لحياتي في الدنيا من صالح الأعمال لحياتي هذه، التي لا موت بعدها، ما ينجيني من غضب الله، ويوجب لي رضوانه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا هَوذة، قال: ثنا عوف، عن الحسن، في قوله: ﴿يَوْمَئِذٍ يَتَذَكَّرُ الإنْسَانُ وَأَنَّى لَهُ الذِّكْرَى يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾ قال: علم الله أنه صادق، هناك حياة طويلة لا موت فيها آخر ما عليه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَالَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾ هُناكُم والله الحياة الطويلة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿يَالَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾ قال: الآخرة.\n\n* *\n\nوقوله: ﴿فَيَوْمَئِذٍ لا يُعَذِّبُ عَذَابَهُ أَحَدٌ وَلا يُوثِقُ وَثَاقَهُ أَحَدٌ﴾\n\nأجمعت القرّاء قرّاء الأمصار في قراءة ذلك على كسر الذال من يعذّب، والثاء من يوثق، خلا الكسائي، فإنه قرأ ذلك بفتح الذال والثاء اعتلالا منه بخبر - رُوي عن رسول الله ﷺ أنه قرأه كذلك - واهي الإسناد.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن خارجة، عن خالد الحذّاء، عن أبي قِلابة، قال: ثني من أقرأه النبيّ ﷺ ﴿فَيَوْمَئِذٍ لا يُعَذِّبُ عَذَابَهُ أَحَدٌ﴾ .\n\nوالصواب من القول في ذلك عندنا ما عليه قرّاء الأمصار، وذلك كسر الذال والثاء لإجماع الحجة من القرّاء عليه. فإذَا كان ذلك كذلك، فتأويل الكلام: فيومئذ لا يعذَّب بعذاب الله أحد في الدنيا، ولا يوثق كوثاقه يومئذ أحد في الدنيا. وكذلك تأوّله قارئو ذلك كذلك من أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَيَوْمَئِذٍ لا يُعَذِّبُ عَذَابَهُ أَحَدٌ﴾ ولا يوثِق كوثاق الله أحد.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿فَيَوْمَئِذٍ لا يُعَذِّبُ عَذَابَهُ أَحَدٌ وَلا يُوثِقُ وَثَاقَهُ أَحَدٌ﴾ قال: قد علم الله أن في الدنيا عذابا وَوَثاقا، فقال: فيومئذ لا يعذّب عذابه أحد في الدنيا، ولا يُوثِق وثاقه أحد في الدنيا.\n\nوأما الذي قرأ ذلك بالفتح، فإنه وجَّه تأويله إلى: فيومئذ لا يعذَّب أحد في الدنيا كعذاب الله يومئذ ولا يوثق أحد في الدنيا كوثاقه يومئذ. وقد تأوّل ذلك بعض من قرأ ذلك كذلك بالفتح من المتأخرين، فيومئذ لا يعذَّب عذاب الكافر أحَد ولا يُوثَق وثاق الكافر أحد. وقال: كيف يجوز الكسر، ولا معذّب يومئذ سوى الله وهذا من التأويل غلط؛ لأن أهل التأويل تأوّلوه بخلاف ذلك، مع إجماع الحجة من القرّاء على قراءته بالمعنى الذي جاء به تأويل أهل التأويل، وما أحسبه دعاه إلى قراءة ذلك كذلك، إلا ذهابه عن وجه صحته في التأويل.\n\n* *\n\nوقوله: ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾\n\nيقول تعالى ذكره مخبرا عن قيل الملائكة لأوليائه يوم القيامة: يا أيتها النفس المطمئنة، يعني بالمطمئنة: التي اطمأنت إلى وعد الله الذي وعد أهل الإيمان به في الدنيا من الكرامة في الآخرة، فصدّقت بذلك.\n\nوقد اختلف أهل التأويل في تأويل ذلك فقال بعضهم نحو الذي قلنا فيه.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ يقول: المصدّقة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ هو المؤمن اطمأنت نفسه إلى ما وعد الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة والحسن، في قوله: ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: المطمئنة إلى ما قال الله، والمصدّقة بما قال.\n\nوقال آخرون: بل معنى ذلك: المصدّقة الموقِنة بأن الله ربها، المسلمة لأمره فيما هو فاعل بها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، في قوله: ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: النفس التي أيقنت أن الله ربها، وضربت جأشا لأمره وطاعته.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: أيقنت بأن الله ربها، وضربت لأمره جأشا.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن سفيان، عن منصور، عن مجاهد ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: المنيبة المخبتة التي قد أيقنت أن الله ربها، وضربت لأمره جأشا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: أيقنت بأن الله ربها، وضربت لأمره جأشا.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿المُطْمَئِنَّةُ﴾ قال: المُخبِتة والمطمئنة إلى الله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: التي قد أيقنت بأن الله ربها، وضربت لأمره جأشا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُليَّة، قال: ثنا ابن أبي نجيح، عن مجاهد، في قوله: ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: المخبِتة.\n\n⁕ حدثني سعيد بن الرييع الرازيّ، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: التي أيقنت بلقاء الله، وضربت له جأشا.\n\nوُذكر أن ذلك في قراءة أُبيّ ﴿يا أيَّتُها النَّفْسُ الآمِنَةُ﴾ .\n\nذكر الرواية بذلك:\n\n⁕ حدثنا خلاد بن أسلم قال: أخبرنا النضر، عن هارون القاري قال: ثني هلال، عن أبي شيخ الهنائي في قراءة أُبيّ ﴿يا أيَّتُها النَّفْسُ الآمِنَةُ المُطْمَئِنَّةُ﴾ وقال الكلبي: إن الآمنة في هذا الموضع، يعني به: المؤمنة.\n\nوقيل: إن ذلك قول الملك للعبد عند خروج نفسه مبشرة برضا ربه عنه، وإعداده ما أعدّ له من الكرامة عنده.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن جعفر، عن سعيد، قال: قُرئت: ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾ عند النبيّ ﷺ فقال أبو بكر: إن هذا لحسن، فقال رسول الله ﷺ: \"أما إنَّ المَلَكَ سَيَقُولُهَا لَكَ عِنْدَ المَوتِ\".\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل بن أبي خالد، عن أبي صالح ﴿ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾ قال هذا عند الموت ﴿فَادْخُلِي فِي عِبَادِي﴾ قال هذا يوم القيامة.\n\nوقال آخرون في ذلك بما:-\n\n⁕ حدثنا به أبو كريب، قال: ثنا ابن يمان، عن أُسامة بن زيد، عن أبيه في قوله: ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ قال: بُشِّرت بالجنة عند الموت، ويوم الجمع، وعند البعث.\n\n* *\n\nوقوله: ﴿ارْجِعِي إِلَى رَبِّكِ﴾\n\nاختلف أهل التأويل في تأويله، فقال بعضهم: هذا خبر من الله جلّ ثناؤه عن قيل الملائكة لنفس المؤمن عند البعث، تأمرها أن ترجع في جسد صاحبها؛ قالوا: وعُنِيَ بالردّ هاهنا صاحبها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾ قال: تردّ الأرواح المطمئنة يوم القيامة في الأجساد.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَادْخُلِي فِي عِبَادِي وَادْخُلِي جَنَّتِي﴾ يأمر الله الأرواح يوم القيامة أن ترجع إلى الأجساد، فيأتون الله كما خلقهم أول مرّة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر، عن أبيه، عن عكرِمة في هذه الآية ﴿ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾ إلى الجسد.\n\nوقال آخرون: بل يقال ذلك لها عند الموت.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل بن أبي خالد، عن أبي صالح ﴿ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾ قال: هذا عند الموت ﴿فَادْخُلِي فِي عِبَادِي﴾ قال: هذا يوم القيامة.\n\nوأولى القولين في ذلك بالصواب القول الذي ذكرناه عن ابن عباس والضحاك، أن ذلك إنما يقال لهم عند ردّ الأرواح في الأجساد يوم البعث لدلالة قوله: ﴿فَادْخُلِي فِي عِبَادِي وَادْخُلِي جَنَّتِي﴾ .\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معنى ذلك: فادخلي في عبادي الصالحين، وادخلي جنتي.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَادْخُلِي فِي عِبَادِي﴾ قال: ادخلي في عبادي الصالحين ﴿وَادْخُلِي جَنَّتِي﴾ .\n\nوقال آخرون: معنى ذلك: فادْخُلِي فِي طاعَتِي وادْخُلِي جَنَّتِي.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن نعيم بن ضمضم، عن محمد بن مزاحم أخي الضحاك بن مُزاحم ﴿فَادْخُلِي فِي عِبَادِي﴾ قال: في طاعتي ﴿وَادْخُلِي جَنَّتِي﴾ قال: في رحمتي.\n\nوكان بعض أهل العربية من أهل البصرة يوجِّه معنى قوله: ﴿فَادْخُلِي فِي عِبَادِي﴾ إلى: فادخلي في حزبي.\n\nوكان بعض أهل العربية من أهل الكوفة يتأوّل ذلك ﴿يَاأَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾ بالإيمان والمصدقة بالثواب والبعث ارجعي، تقول لهم الملائكة: إذا أُعطوا كتبهم بأيمانهم ﴿ارْجِعِي إِلَى رَبِّكِ﴾ إلى ما أعدّ الله لك من الثواب؛ قال: وقد يكون أن تقول لهم: شِبْه هذا القول ينوون ارجعوا من الدنيا إلى هذا المرجع؛ قال: وأنت تقول للرجل ممن أنت؟ فيقول: مُضَريّ، فتقول: كن تميميا أو قيسيا، أي: أنت من أحد هذين، فتكون كن صلة، كذلك الرجوع يكون صلة، لأنه قد صار إلى يوم القيامة، فكان الأمر بمعنى الخبر، كأنه قال: أيتها النفس أنت راضية مرضية.\n\nوقد رُوي عن بعض السلف أنه كان يقرأ ذلك: ﴿فادْخُلِي فِي عبدِي وَادْخُلِي جَنَّتِي﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني أحمد بن يوسف، قال: ثنا القاسم بن سلام، قال: ثنا حجاج، عن هارون، عن أبان بن أبي عياش، عن سليمان بن قَتَّةَ عن ابن عباس، أنه قرأها ﴿فادْخُلِي فِي عَبْدي﴾ على التوحيد.\n\n⁕ حدثني خلاد بن أسلم، قال: أخبرنا النضر بن شميل، عن هارون القاري، قال: ثني هلال، عن أبي الشيخ الهنائي ﴿فادْخُلِي فِي عَبْدِي﴾ . وفي قول الكلبي ﴿فادْخُلِي فِي عَبْدِي وَادْخُلِي فِي جَنَّتِي﴾ يعني: الروح ترجع في الجسد.\n\nوالصواب من القراءة في ذلك ﴿فَادْخُلِي فِي عِبَادِي﴾ بمعنى: فادخلي في عبادي الصالحين. لإجماع الحجة من القرّاء عليه.\n\nآخر تفسير سورة والفجر","25":24,"26":24,"27":24,"28":24,"29":24,"30":24},"90":{"1":"القول في تأويل قوله تعالى جل ثناؤه وتقدست أسماؤه: ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ (١) وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ (٢) وَوَالِدٍ وَمَا وَلَدَ (٣) لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ (٤) أَيَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ (٥) يَقُولُ أَهْلَكْتُ مَالا لُبَدًا (٦) أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ (٧) ﴾ .\n\nيقول تعالى ذكره: أقسم يا محمد بهذا البلد الحرام، وهو مكة، وكذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ يعني: مكة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ قال: مكة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ قال: الحرام.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ قال: مكة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن قتادة ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ قال: البلد مكة.\n\n⁕ حدثنا سوار بن عبد الله، قال: ثنا يحيى بن سعيد، عن عبد الملك، عن عطاء، في قوله: ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ يعني مكة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿لا أُقْسِمُ بِهَذَا الْبَلَدِ﴾ قال: مكة.\n\n* *\n\nوقوله: ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾\n\nيعني: بمكة؛ يقول جلّ ثناؤه لنبيه محمد ﷺ: وأنت يا محمد حِلٌّ بهذا البلد، يعني بمكة؛ يقول: أنت به حلال تصنع فيه من قَتْلِ من أردت قتلَه، وأَسْرِ من أردت أسره، مُطْلَقٌ ذلك لك؛ يقال منه: هو حِلّ، وهو حلال، وهو حِرْم، وهو حرام، وهو محلّ، وهو محرم، وأحللنا، وأحرمنا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ يعني بذلك: نبيّ الله ﷺ، أحلّ الله له يوم دخل مكة أن يقتل من شاء، ويستحْيِي من شاء؛ فقتل يومئذ ابن خَطَل صَبْرا وهو آخذ بأستار الكعبة، فلم تحِل لأحد من الناس بعد رسول الله ﷺ أن يقتل فيها حراما حرّمه الله، فأحلّ الله له ما صنع بأهل مكة، ألم تسمع أن الله قال في تحريم الحرم: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلا﴾ يعني بالناس أهل القبلة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: ما صنعت فأنت في حلّ من أمر القتال.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: أحلّ لرسول الله ﷺ ما صنع فيه ساعة.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: أحل له أن يصنع فيه ما شاء.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: أُحِلَّت للنبي ﷺ، قال: اصنع فيها ما شئت.\n\n⁕ حدثني موسى بن عبد الرحمن، قال: ثنا حسين الجُعْفِيّ، عن زائدة، عن منصور، عن مجاهد، في قول الله ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: أنت حِلّ مما صنعت فيه.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عمرو، عن منصور، عن مجاهد ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: أحلّ الله لك يا محمد ما صنعت في هذا البلد من شيء، يعني مكة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: لا تؤاخَذ بما عملت فيه، وليس عليك فيه ما على الناس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ يقول: بريء عن الحرج والإثم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ يقول: أنت به حلّ لست بآثم.\n\n⁕ حدثنا يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: لم يكن بها أحد حلا غير النبيّ ﷺ، كلّ من كان بها حراما، لم يحلّ لهم أن يقاتلوا فيها، ولا يستحلوا حرمه، فأحله الله لرسوله، فقاتل المشركين فيه.\n\n⁕ حدثنا سوار بن عبد الله، قال حدثنا يحيى بن سعيد، عن عبد الملك، عن عطاء ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ قال: إن الله حرّم مكة، لم تحلّ لنبيّ إلا نبيكم ساعة من نهار.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ يعني محمدا، يقول: أنت حلّ بالحرم، فاقتل إن شئت، أو دع.\n\n* *\n\nوقوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾\n\nيقول تعالى ذكره: فأقسم بوالد وبولده الذي وَلَد.\n\nثم اختلف أهل التأويل في المعنّي بذلك من الوالد وما ولد، فقال بعضهم: عُنِي بالوالد: كلّ والد، وما ولد: كلّ عاقر لم يلد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن عطية، عن شريك، عن خصيف، عن عكرمة، عن ابن عباس في: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: الوالد: الذي يلد، وما ولد: العاقر الذي لا يولد له.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن خصيف، عن عكرمة، عن ابن عباس ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: العاقر، والتي تلد.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن النضر بن عربي، عن عكرِمة ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: العاقر، والتي تلد.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: هو الوالد وولده.\n\nوقال آخرون: عُنِي بذلك: آدم وولده.\n\nذكر من قال ذلك:\n\n⁕ حدثني زكريا بن يحيى بن أبي زائدة، قال: ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: الوالد: آدم، وما ولد: ولده.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: ولده.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: آدم وما ولد.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: آدم وما ولد.\n\n⁕ حدثنا أبو كريب، قال: ثنا ابن أبي زائدة، عن ابن أبي خالد، عن أبي صالح في قول الله ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: آدم وما ولد.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: الوالد: آدم، وما ولد: ولده.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: آدم وما ولد.\n\n⁕ حدثني يونس بن عبد الأعلى، قال: ثنا محمد بن عبيد، عن إسماعيل بن أبي خالد، عن أبي صالح، في قوله: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: آدم وما ولد.\n\nوقال آخرون: عُنِي بذلك: إبراهيم وما ولد.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن موسى الحَرَشيّ، قال: ثنا جعفر بن سليمان، قال: سمعت أبا عمران الجَوْنِيّ يقرأ: ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ قال: إبراهيم وما ولد.\n\nوالصواب من القول في ذلك: ما قاله الذي قالوا: إن الله أقسم بكلّ والد وولده، لأن الله عم كلّ والد وما ولد. وغير جائز أن يخصّ ذلك إلا بحجة يجب التسليم لها من خبر، أو عقل، ولا خبر بخصوص ذلك، ولا برهان يجب التسليم له بخصوصه، فهو على عمومه كما عمه.\n\n* *\n\nوقوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾\n\nوهذا هو جواب القسم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: وقع ها هنا القسم ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ .\n\nواختلف أهل التأويل في تأويل ذلك، فقال بعضهم: معناه: لقد خلقنا ابن آدم في شدّة وعناء ونصب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ يقول: في نَصَب.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا سعيد، عن منصور بن زاذان، عن الحسن، أنه قال في هذه الآية: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ يقول: في شدّة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ حين خُلِق في مشقة لا يُلَقى ابن آدم إلا مكابد أمر الدنيا والآخرة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿فِي كَبَدٍ﴾ قال: يكابد أمر الدنيا والآخرة.\n\nوقال بعضهم: خُلِق خَلْقا لم نَخْلق خلقه شيئا.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن عليّ بن رفاعة، قال: سمعت الحسن يقول: لم يخلق الله خلقا يكابد ما يُكابد ابن آدم.\n\n⁕ قال: ثنا وكيع، عن عليّ بن رفاعة، قال: سمعت سعيد بن أبي الحسن يقول: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: يكابد مصائب الدنيا، وشدائد الآخرة.\n\n⁕ قال: ثنا وكيع، عن النضر، عن عكرِمة قال: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في شدّة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عطاء، عن سعيد بن جبير، عن ابن عباس ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في شدّة.\n\n⁕ قال: ثنا مهران، عن سفيان، عن ابن جريج، عن عطاء، عن ابن عباس، قال: في شدّة معيشته، وحمله وحياته، ونبات أسنانه.\n\n⁕ قال: ثنا مهران، عن سفيان، قال: قال مجاهد ﴿الإنْسَانَ فِي كَبَدٍ﴾ قال: شدة خروج أسنانه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿الإنْسَانَ فِي كَبَدٍ﴾ قال: شدّة.\n\nوقال آخرون: معنى ذلك أنه خُلِق منتصبا معتدل القامة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في انتصاب، ويقال: في شدّة.\n\n⁕ حدثنا ابن المثنى، قال: ثنا حرمى بن عمارة، قال: ثنا شعبة، قال: أخبرني عمارة، عن عكرِمة، في قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في انتصاب، يعني القامة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن إبراهيم ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: منتصبا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران؛ وحدثنا أبو كُرَيب، قال: ثنا وكيع، جميعا عن سفيان، عن منصور، عن إبراهيم، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن أبي زائدة، عن إسماعيل بن أبي خالد، عن عبد الله بن شَدَّاد، في قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: معتدلا بالقامة، قال أبو صالح: معتدلا في القامة.\n\n⁕ حدثنا يحيى بن داود الواسطي، قال: ثنا يحيى بن سعيد القطان، عن إسماعيل، عن أبي صالح ﴿خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: قائما.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿فِي كَبَدٍ﴾ خُلِق منتصبا على رجلين، لم تخلق دابة على خلقه\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مُغيرة، عن مجاهد ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في صَعَد.\n\nوقال آخرون: بل معنى ذلك: أنه خُلق في السماء.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي كَبَدٍ﴾ قال: في السماء، يسمى ذلك الكَبَد.\n\nوأولى الأقوال في ذلك بالصواب: قول من قال: معنى ذلك أنه خلق يُكابد الأمور ويُعالجها، فقوله: ﴿فِي كَبَدٍ﴾ معناه: في شدّة.\n\nوإنما قلنا: ذلك أولى بالصواب؛ لأن ذلك هو المعروف في كلام العرب من معاني الكَبَد، ومنه قول لبيد بن ربيعة:\n\nعَيْنِ هَلا بَكَيْتِ أرْبَدَ إذْ ... قُمْنا وَقَامَ الخُصُومِ فِي كَبَد\n\n* *\n\nوقوله: ﴿أَيَحْسَبُ أَنْ لَنْ يَقْدِرَ عَلَيْهِ أَحَدٌ﴾\n\nذُكر أن ذلك نزل في رجل بعينه من بني جُمح، كان يُدعى أبا الأشدّ، وكان شديدًا، فقال جلّ ثناؤه: أيحسب هذا القويّ بجَلَده وقوّته، أن لن يقهره أحد ويغلبه، فالله غالبه وقاهره.\n\n* *\n\nوقوله: ﴿يَقُولُ أَهْلَكْتُ مَالا لُبَدًا﴾\n\nيقول هذا الجليد الشديد: أهلكت مالا كثيرا، في عداوة محمد ﷺ، فأنفقت ذلك فيه، وهو كاذب في قوله ذلك، وهو فعل من التلبُّد، وهو الكثير، بعضه على بعض، يقال منه: لبد بالأرض يَلْبُد: إذا لصق بها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿مَالا لُبَدًا﴾ يعني باللبد: المال الكثير.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿مَالا لُبَدًا﴾ قال: كثيرا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني مسلم، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿أَهْلَكْتُ مَالا لُبَدًا﴾ . قال: مالا كثيرا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَهْلَكْتُ مَالا لُبَدًا﴾ : أي كثيرا.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿مَالا لُبَدًا﴾ قال: اللبد: الكثير.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الأمصار: ﴿مَالا لُبَدًا﴾ بتخفيف الباء. وقرأه أبو جعفر بتشديدها.\n\nوالصواب بتخفيفها، لإجماع الحجة عليه.\n\n* *\n\nوقوله: ﴿أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ﴾\n\nيقول تعالى ذكره: أيظن هذا القائل ﴿أَهْلَكْتُ مَالا لُبَدًا﴾ أن لم يره أحد في حال إنفاقه يزعم أنه أنفقه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَيَحْسَبُ أَنْ لَمْ يَرَهُ أَحَدٌ﴾ ابن آدم إنك مسئول عن هذا المال، من أين اكتسبته، وأين أنفقته.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":"القول في تأويل قوله تعالى: ﴿أَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِ (٨) وَلِسَانًا وَشَفَتَيْنِ (٩) وَهَدَيْنَاهُ النَّجْدَيْنِ (١٠) فَلا اقْتَحَمَ الْعَقَبَةَ (١١) وَمَا أَدْرَاكَ مَا الْعَقَبَةُ (١٢) فَكُّ رَقَبَةٍ (١٣) أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ (١٤) يَتِيمًا ذَا مَقْرَبَةٍ (١٥) أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ (١٦) ﴾\n\n.\n\nيقول تعالى ذكره: ألم نجعل لهذا القائل ﴿أَهْلَكْتُ مَالا لُبَدًا﴾ عينين يبصر بهما حجج الله عليه، ولسانا يعبر به عن نفسه ما أراد، وشفتين، نعمة منا بذلك عليه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَلَمْ نَجْعَلْ لَهُ عَيْنَيْنِ وَلِسَانًا وَشَفَتَيْنِ﴾ نِعَم من الله متظاهرة، يقررك بها كيما تشكره.\n\n* *\n\nوقوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾\n\nيقول تعالى ذكره: وهديناه الطريقين، ونجد: طريق في ارتفاع.\n\nواختلف أهل التأويل في معنى ذلك، فقال بعضهم: عُنِي بذلك: نَجْد الخير، ونَجْد الشرّ، كما قال: ﴿إِنَّا هَدَيْنَاهُ السَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عاصم، عن زرّ، عن عبد الله ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: الخير والشرّ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عاصم، عن زرّ، عن عبد الله، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن منذر، عن أبيه، عن الربيع بن خثيم، قال: ليسا بالثديين.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان؛ وحدثنا ابن حميد، قال: ثنا حكام، قال: ثنا عمران، جميعا عن عاصم، عن زرّ، عن عبد الله ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: نجد الخير، ونجد الشرّ.\n\n⁕ حدثنا ابن المثنى، قال: ثنا هشام بن عبد الملك، قال: ثنا شعبة، قال: أخبرني عاصم، قال: سمعت أبا وائل يقول: كان عبد الله يقول في: (وَهَدَيْنَاهُ النَّجْدَيْنِ) قال: نجد الخير، ونجد الشرّ.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ يقول: الهدي والضلالة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ يقول: سبيل الخير والشرّ.\n\n⁕ حدثنا هناد بن السريّ، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة، في قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: الخير والشرّ.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن عبد الله بن الربيع بن خثيم، عن أبي بُردة، قال: مرّ بنا الربيع بن خثيم، فسألناه عن هذه الآية: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ فقال: أما إنهما ليسا بالثديين.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد، قال: الخير والشرّ.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: سبيل الخير والشرّ.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ نجد الخير، ونجد الشرّ.\n\n⁕ حدثنا عمران بن موسى، قال: ثنا عبد الوارث، قال: ثنا يونس، عن الحسن، قال: قال رسول الله ﷺ: \" هُمَا نَجْدَانِ: نَجْدُ خَيْرٍ، وَنَجْدُ شَرّ، فَمَا جَعَلَ نَجْدَ الشَّرّ أحَبَّ إلَيْكُمْ مِنْ نَجْدِ الخَيْرِ\".\n\n⁕ حدثنا مجاهد بن موسى، قال: ثنا يزيد بن هارون، قال: أخبرنا عطية أبو وهب، قال: سمعت الحسن يقول: قال رسول الله ﷺ: \" ألا إنَّمَا هُمَا نَجْدَانِ: نَجْدُ الخَيْرِ، وَنَجْدُ الشَّرّ، فَمَا يَجَعَلُ نَجْدَ الشَّرِّ أحَبَّ إلَيْكُمْ مِنْ نَجْدِ الخَيْرِ\".\n\n⁕ حدثنا ابن المثنى، قال: ثنا هشام بن عبد الملك، قال: ثنا شعبة، عن حبيب، عن الحسن، عن النبيّ ﷺ، نحوه.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سمعت الحسن يقول ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: ذُكر لنا أن نبيّ الله ﷺ كان يقول: \" يا أيُّها النَّاسُ إنَّمَا هُمَا النَجْدَانِ: نَجْدُ الخَيْرِ، وَنَجْدُ الشَّرّ، فَمَا جَعَلَ نَجْدَ الشَّرّ أحَبَّ إلَيْكُمْ مِنْ نَجْدِ الخَيْرِ\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ : ذُكر لنا أن نبيّ الله ﷺ كان يقول: \"أيُّها النَّاسُ إنَّمَا هُمَا النَجْدَانِ: نَجْدُ الخَيْرِ، وَنَجْدُ الشَّرّ، فَمَا جَعَلَ نَجْدَ الشَّرّ أحَبَّ إلَيْكُمْ مِنْ نَجْدِ الخَيْرِ\".\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، في قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: قال النبيّ ﷺ: إنَّمَا هُمَا نَجْدَانِ، فَمَا جَعَلَ نَجْدَ الشَّرّ أحَبَّ إلَيْكُمْ مِنْ نَجْدِ الخَيْرِ\".\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قاطع طريق الخير والشرّ. وقرأ قول الله: ﴿إِنَّا هَدَيْنَاهُ السَّبِيلَ﴾ .\n\nوقال آخرون: بل معنى ذلك: وهديناه الثَّديين: سبيلي اللبن الذي يتغذّى به، وينبت عليه لحمه وجسمه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، قال: ثنا عيسى بن عقال، عن أبيه، عن ابن عباس ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ قال: هما الثديان.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن المبارك بن مجاهد، عن جُويبر، عن الضحاك، قال: الثديان.\n\nوأولى القولين بالصواب في ذلك عندنا: قول من قال: عُنِي بذلك طريق الخير والشرّ، وذلك أنه لا قول في ذلك نعلمه غير القولين اللذين ذكرنا، والثديان وإن كانا سبيلي اللبن، فإن الله تعالى ذكْره إذ عدّد على العبد نِعَمه بقوله: ﴿إِنَّا خَلَقْنَا الإنْسَانَ مِنْ نُطْفَةٍ أَمْشَاجٍ نَبْتَلِيهِ فَجَعَلْنَاهُ سَمِيعًا بَصِيرًا إِنَّا هَدَيْنَاهُ السَّبِيلَ﴾ إنما عدّد عليه هدايته إياه إلى سبيل الخير من نعمه، فكذلك قوله: ﴿وَهَدَيْنَاهُ النَّجْدَيْنِ﴾ .\n\n* *\n\nوقوله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾\n\nيقول تعالى ذكره: فلم يركب العقبة فيقطعها ويحوزها.\n\nوذُكر أن العقبة: جبل في جهنم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا يحيى بن كثير، قال: ثنا شعبة، عن أبي رجاء، عن الحسن، في قول الله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ قال: عَقَبةٌ في جهنم.\n\n⁕ حدثني عمر بن إسماعيل بن مجالد، قال: ثنا عبد الله بن إدريس، عن أبيه، عن عطية، عن ابن عمر، في قوله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ جبل من جهنم.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَيَّة، عن أبي رجاء، عن الحسن، في قوله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ قال: جهنم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ إنها قحمة شديدة، فاقتحموها بطاعة الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ قال: للنار عقبة دون الجسر.\n\n⁕ حدثنا ابن بشار، قال: ثنا وهب بن جرير، قال: ثنا أبي، قال: سمعت يحيى بن أيوب يحدّث عن يزيد بن أبى حبيب، عن شعيب بن زُرْعة، عن حنش، عن كعب، أنه قال: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ قال: هو سبعون درجة في جهنم.\n\nوأفرد قوله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ بذكر \" لا \" مرّة واحدة، والعرب لا تكاد تفردها في كلام في مثل هذا الموضع، حتى يكرّرها مع كلام آخر، كما قال: ﴿فَلا صَدَّقَ وَلا صَلَّى﴾ ﴿وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ﴾ وإنما فعل ذلك كذلك في هذا الموضع، استغناء بدلالة آخر الكلام على معناه، من إعادتها مرّة أخرى، وذلك قوله إذ فسَّر اقتحام العقبة، فقال: ﴿فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ يَتِيمًا ذَا مَقْرَبَةٍ أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا﴾ ، ففسر ذلك بأشياء ثلاثة، فكان كأنه في أوّل الكلام، قال: فلا فَعَل ذا وَلا ذا ولا ذا. وتأوّل ذلك ابن زيد، بمعنى: أفلا ومن تأوّله كذلك، لم يكن به حاجة إلى أن يزعم أن في الكلام متروكا. * ذكر الخبر بذلك عن ابن زيد:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، وقرأ قول الله: ﴿فَلا اقْتَحَمَ الْعَقَبَةَ﴾ قال: أفلا سلك الطريق التي منها النجاة والخير، ثم قال: ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾ .\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾\n\nيقول تعالى ذكره: وأيّ شيء أشعرك يا محمد ما العقبة.\n\nثم بين جلّ ثناؤه له، ما العقبة، وما النجاة منها، وما وجه اقتحامها؟ فقال: اقتحامها وقطعها فكّ رقبة من الرقّ، وأسر العبودة.\n\nكما:-\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُليَّة، عن أبي رجاء، عن الحسن ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ فَكُّ رَقَبَةٍ﴾ قال: ذُكر لنا أنه ليس مسلم يعتق رقبة مسلمة، إلا كانت فداءه من النار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ فَكُّ رَقَبَةٍ﴾ ذكر لنا أن نبيّ الله ﷺ سُئل عن الرقاب أيها أعظم أجرا؟ قال: \" أكثرها ثمنا \".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: ثنا سالم بن أبي الجعد، عن مَعْدانِ بن أبي طلحة، عن أبي نجيح، قال: سمعت رسول الله ﷺ يقول: \" أيُّمَا مُسْلِمٍ أَعْتَقَ رَجُلا مُسْلِمًا، فإنَّ اللهَ جَاعِلٌ وَفَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهِ، عَظْما مِنْ عِظامِ مُحَرّرِهِ مِنْ النَّار؛ وأيُّمَا امْرأةٍ مُسْلِمَةٍ أعْتَقَتِ امْرَأةً مُسْلِمَةً، فإنَّ اللهَ جَاعِلٌ وَفَاءَ كُلِّ عَظْمٍ مِنَ عِظَامِهَا، عَظْما مِنَ عِظامِ مُحَرّرِها مِنَ النَّار \".\n\n⁕ قال: ثنا سعيد، عن قتادة، عن قيس الجذاميّ، عن عقبة بن عامر الجهنيّ، أن رسول الله ﷺ قال: \" مَنْ أعْتَقَ رَقَبَةً مُؤْمِنَةً، فَهِيَ فِدَاؤُهُ مِنَ النَّارِ \".\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾ ثم أخبر عن اقتحامها فقال: ﴿فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ﴾ .\n\nواختلفت القرّاء في قراءة ذلك، فقرأه بعض قرّاء مكة وعامة قرّاء البصرة، عن ابن أبي إسحاق، ومن الكوفيين: الكسائي ﴿فَكُّ رَقَبَةٍ أوْ أطْعَمَ﴾ وكان أبو عمرو بن العلاء يحتجّ فيما بلغني فيه بقوله: ﴿ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا﴾ كأن معناه: كان عنده، فلا فكّ رقبة ولا أطعم، ثم كان من الذين آمنوا. وقرأ ذلك عامة قرّاء المدينة والكوفة والشام ﴿فَكُّ رَقَبَةٍ﴾ على الإضافة ﴿أَوْ إِطْعَامٌ﴾ على وجه المصدر.\n\nوالصواب من القول في ذلك: أنهما قراءتان معروفتان، قد قرأ بكل واحدة منهما علماء من القرّاء، وتأويل مفهوم، فبأيتهما قرأ القارئ فمصيب. فقراءته إذا قرئ على وجه الفعل تأويله: فلا اقتحم العقبة، لا فكّ رقبة، ولا أطعم، ثم كان من الذين آمنوا، ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾ على التعجب والتعظيم وهذه القراءة أحسن مخرجا في العربية، لأن الإطعام اسم، وقوله: ﴿ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا﴾ فعل، والعرب تُؤثِر ردّ الأسماء على الأسماء مثلها، والأفعال على الأفعال، ولو كان مجيء التَّنزيل ثم إن كان من الذين آمنوا، كان أحسن، وأشبه بالإطعام والفكّ من ثم كان، ولذلك قلت: ﴿فَكُّ رَقَبَةٍ أوْ أطْعَمَ﴾ أوجه في العربية من الآخر، وإن كان للآخر وجه معروف، ووجهه أنْ تضمر \" أنْ \" ثم تلقي، كما قال طرفة بن العبد:\n\nألا أيُّهَا ذَا الزَّاجِرِي أحْضُرَ الْوَغَى ... وأنْ أشْهَدَ اللَّذَّاتِ هلْ أنتَ مُخْلِدي\n\nبمعنى: ألا أيهاذا الزاجري أن أحضر الوغى. وفي قوله: \" أن أشهد \"الدلالة البينة على أنها معطوفة على أن أخرى مثلها، قد تقدّمت قبلها، فذلك وجه جوازه. وإذا وُجِّه الكلام إلى هذا الوجه كان قوله: ﴿فَكُّ رَقَبَةٍ أَوْ إِطْعَامٌ﴾ تفسيرًا لقوله: ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾ كأنه قيل: وما أدراك ما العقبة؟ هي فكّ رقبة ﴿أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ كما قال جلّ ثناؤه: ﴿وَمَا أَدْرَاكَ مَا هِيَهْ﴾ ، ثم قال: ﴿نَارٌ حَامِيَةٌ﴾ مفسرا لقوله: ﴿فَأُمُّهُ هَاوِيَةٌ﴾ ، ثم قال: وما أدراك ما الهاوية؟ هي نار حامية.\n\n* *\n\nوقوله: ﴿أَوْ أَطْعَمَ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾\n\nيقول: أو أطعم في يوم ذي مجاعة، والساغب: الجائع.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿أو أطْعَمَ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ يوم مجاعة.\n\n⁕ حدثنا الحسن بن عرفة، قال: ثني خالد بن حيان الرقي أبو يزيد، عن جعفر بن برقان، عن عكرِمة في قول الله ﴿أو أطْعَمَ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ قال: ذي مجاعة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ قال: الجوع.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿أو أطْعَمَ فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ يقول: يوم يُشْتَهَى فيه الطعام.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عثمان الثقفي، عن مجاهد، عن ابن عباس ﴿فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ قال: مجاعة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عثمان بن المُغيرة، عن مجاهد، عن ابن عباس، مثله.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول: في قوله: ﴿فِي يَوْمٍ ذِي مَسْغَبَةٍ﴾ قال: مجاعة.\n\n* *\n\nوقوله: ﴿يَتِيمًا ذَا مَقْرَبَةٍ﴾\n\nيقول: أو أطعم في يوم مجاعة صغيرًا لا أب له من قرابته، وهو اليتيم ذو المقرَبة؛ وعُنِي بذي المقربة: ذا القرابة.\n\nكما:-\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿يَتِيمًا ذَا مَقْرَبَةٍ﴾ قال: ذَا قرابة.\n\n* *\n\nوقوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾\n\nاختلف أهل التأويل في تأويل قوله: ﴿ذَا مَتْرَبَةٍ﴾ فقال بعضهم: عُنِيَ بذلك: ذو اللصوق بالتراب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن شعبة، قال: أخبرني المُغيرة، عن مجاهد، عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: الذي ليس له مأوى إلا التراب.\n\n⁕ حدثنا مطرِّف بن محمد الضبيّ، قال: ثنا أبو عاصم، قال: ثنا شعبة، عن المُغيرة، عن مجاهد، عن ابن عباس، مثله.\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن شعبة، عن حُصين، عن مجاهد، عن ابن عباس، في قول الله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: الذي لا يُواريه إلا التراب.\n\n⁕ حدثني زكريا بن يحيى بن أبي زائدة، قال: ثنا أبو عاصم، عن شعبة، عن المُغيرة، عن مجاهد، عن ابن عباس ﴿ذَا مَتْرَبَةٍ﴾ قال: الذي ليس له مَأوًى إلا التراب.\n\n⁕ حدثنا ابن حميد، قال: ثني جرير، عن مغيرة، عن مجاهد، عن ابن عباس ﴿مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: الذي ليس له مَأوًى إلا التراب.\n\n⁕ قال: ثنا جرير، عن منصور، عن مجاهد، عن ابن عباس، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: المسكين؛ المطروح في التراب.\n\n⁕ حدثني أبو حصين قال: ثنا عبد الله بن أحمد بن يونس، قال: ثنا عَبْثَرٌ، عن حصين، عن مجاهد، عن ابن عباس، قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: الذي لا يقيه من التراب شيء.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: ثنا حصين والمغيرة كلاهما، عن مجاهد، عن ابن عباس أنه قال في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: هو اللازق بالتراب من شدّة الفقر.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عمرو بن أبي قيس، عن منصور، عن مجاهد، عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: التراب الملقى على الطريق على الكُناسة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا طَلق بن غنام، عن زائدة، عن منصور، عن مجاهد، عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: هو المسكين الملقى بالطريق بالتراب.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الحصين، عن مجاهد ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: المطروح في الأرض، الذي لا يقيه شيء دون التراب.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حصين، عن مجاهد، عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: هو المُلزق بالأرض، لا يقيه شيء من التراب.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن حصين وعثمان بن المُغيرة، عن مجاهد عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال الذي ليس له شيء يقيه من التراب.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿ذَا مَتْرَبَةٍ﴾ قال: ساقط في التراب.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن جعفر بن برقان، قال: سمع عكرِمة ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: الملتزق بالأرض من الحاجة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن عكرِمة، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: التراب اللاصق بالأرض.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عثمان بن المُغيرة، عن سعيد بن جُبير، عن ابن عباس، قال: المُلقى في الطريق الذي ليس له بيت إلا التراب.\n\nوقال آخرون: بل هو المحتاج، كان لاصقا بالتراب، أو غير لاصق؛ وقالوا: إنما هو من قولهم: تَرِب الرجل: إذا افتقر.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ يقول: شديد الحاجة.\n\n⁕ حدثنا هناد بن السريّ، قال: ثنا أبو الأحوص، عن حصين، عن عكرِمة، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: هو المحارَف الذي لا مال له.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: ذا حاجة، الترب: المحتاج.\n\nوقال آخرون: بل هو ذو العيال الكثير الذين قد لصقوا بالتراب من الضرّ وشدّة الحاجة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ يقول: مسكين ذو بنين وعيال، ليس بينك وبينه قرابة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر بن أبي المُغيرة، عن سعيد بن جُبير، في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ قال: ذا عِيال.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ كنا نحدّث أن الترب هو ذو العيال الذي لا شيء له.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ﴾ ذا عيال لاصقين بالأرض، من المسكنة والجهد.\n\nوأولى الأقوال في ذلك بالصحة قول من قال: عُنِيَ به: أو مسكينا قد لصق بالتراب من الفقر والحاجة؛ لأن ذلك هو الظاهر من معانيه. وأن قوله: ﴿مَتْرَبَةٍ﴾ إنما هي \" مَفْعَلةٍ \" من ترب الرجل: إذا أصابه التراب.","9":8,"10":8,"11":8,"12":8,"13":8,"14":8,"15":8,"16":8,"17":"القول في تأويل قوله تعالى: ﴿ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ (١٧) أُولَئِكَ أَصْحَابُ الْمَيْمَنَةِ (١٨) وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ (١٩) عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ (٢٠) ﴾\n\n.\n\nيقول تعالى ذكره: ثم كان هذا الذي قال: ﴿أَهْلَكْتُ مَالا لُبَدًا﴾ من الذين آمنوا بالله ورسوله، فيؤمن معهم كما آمنوا ﴿وَتَوَاصَوْا بِالصَّبْرِ﴾ يقول: وممن أوصى بعضهم بعضا بالصبر على ما نابهم في ذات الله ﴿وَتَوَاصَوْا بِالْمَرْحَمَةِ﴾ يقول: وأوصى بعضهم بعضًا بالمرحمة.\n\nكما:-\n\n⁕ حدثنا محمد بن سنان والقزّاز، قال: ثنا أبو عاصم عن شبيب، عن عكرِمة، عن ابن عباس ﴿وَتَوَاصَوْا بِالْمَرْحَمَةِ﴾ قال: مَرْحَمة الناس.\n\n* *\n\nوقوله: ﴿أُولَئِكَ أَصْحَابُ الْمَيْمَنَةِ﴾\n\nيقول: الذين فعلوا هذه الأفعال التي ذكرتها، من فكّ الرقاب، وإطعام اليتيم، وغير ذلك، أصحاب اليمين، الذين يؤخذ بهم يوم القيامة ذات اليمين إلى الجنة.\n\n* *\n\nوقوله: ﴿وَالَّذِينَ كَفَرُوا بِآيَاتِنَا﴾\n\nيقول: والذين كفروا بأدلتنا وأعلامنا وحججنا من الكتب والرُّسل وغير ذلك ﴿هُمْ أَصْحَابُ الْمَشْأَمَةِ﴾ يقول: هم أصحاب الشمال يوم القيامة الذين يؤخذ بهم ذات الشمال. وقد بيَّنا معنى المشأمة، ولم قيل لليسار المشأمة فيما مضى، بما أغنى عن إعادته في هذا الموضع.\n\n* *\n\nوقوله: ﴿عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ﴾\n\nيقول تعالى ذكره: عليهم نار جهنم يوم القيامة مُطْبََقة؛ يقال منه: أوصدت وآصدت.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ﴾ قال: مُطْبَقة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، ﴿عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ﴾ قال: مُطْبَقة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿عَلَيْهِمْ نَارٌ مُؤْصَدَةٌ﴾ : أي مُطْبَقة، أطبقها الله عليهم، فلا ضوء فيها ولا فرج، ولا خروج منها آخر الأبد.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿مُؤْصَدَةٌ﴾ : مغلقة عليهم.\n\nآخر تفسير سورة لا أُقسم بهذا البلد.\n\n٢٤-٤٤٩","18":17,"19":17,"20":17},"91":{"1":"القول في تأويل قوله تعالى جل ثناؤه وتقدست أسماؤه: ﴿وَالشَّمْسِ وَضُحَاهَا (١) وَالْقَمَرِ إِذَا تَلاهَا (٢) وَالنَّهَارِ إِذَا جَلاهَا (٣) وَاللَّيْلِ إِذَا يَغْشَاهَا (٤) وَالسَّمَاءِ وَمَا بَنَاهَا (٥) وَالأرْضِ وَمَا طَحَاهَا (٦) وَنَفْسٍ وَمَا سَوَّاهَا (٧) فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا (٨) ﴾ .\n\n* *\n\nقوله: ﴿وَالشَّمْسِ وَضُحَاهَا﴾\n\nقسم أقسم ربنا تعالى ذكره بالشمس وضحاها؛ ومعنى الكلام: أقسم بالشمس، وبضحى الشمس.\n\nواختلف أهل التأويل في معنى قوله: ﴿وَضُحَاهَا﴾ فقال بعضهم: معنى ذلك: والشمس والنهار، وكان يقول: الضحى: هو النهار كله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالشَّمْسِ وَضُحَاهَا﴾ قال: هذا النهار.\n\nوقال آخرون: معنى ذلك: وضوئها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَالشَّمْسِ وَضُحَاهَا﴾ قال: ضوئها.\n\nوالصواب من القول في ذلك أن يقال: أقسم جلّ ثناؤه بالشمس ونهارها؛ لأن ضوء الشمس الظاهرة هو النهار.\n\n* *\n\nوقوله: ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾\n\nيقول تعالى ذكره: والقمر إذا تبع الشمس، وذلك في النصف الأوّل من الشهر، إذا غُربت الشمس، تلاها القمر طالعا.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ قال: يتلو النهار.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا عبد الملك، عن قيس بن سعد، عن مجاهد، قوله: ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ يعني: الشمس إذا تبعها القمر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ قال: تبعها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ يتلوها صبيحة الهلال فإذا سقطت الشمس رُؤي الهلال.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ قال: إذا تلاها ليلة الهلال.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿وَالشَّمْسِ وَضُحَاهَا وَالْقَمَرِ إِذَا تَلاهَا﴾ قال: هذا قسم، والقمر يتلو الشمس نصف الشهر الأوّل، وتتلوه النصف الآخر، فأما النصف الأوّل فهو يتلوها، وتكون أمامه وهو وراءها، فإذا كان النصف الآخر كان هو أمامها يقدمها، وتليه هي.\n\n* *\n\nوقوله: ﴿وَالنَّهَارِ إِذَا جَلاهَا﴾\n\nيقول: والنهار إذا جَلاهَا، قال: إذا أضاء.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالنَّهَارِ إِذَا جَلاهَا﴾ قال: إذا غشيها النهار. وكان بعض أهل العربية يتأوّل ذلك بمعنى: والنهار إذا جلا الظلمة، ويجعل الهاء والألف من جلاها كناية عن الظلمة، ويقول: إنما جاز الكناية عنها، ولم يجز لها ذكر قبل، لأن معناها معروف، كما يعرف معنى قول القائل: أصبحت باردة، وأمست باردة، وهبَّت شمالا فكني عن مؤنثات لم يجر لها ذكر، إذ كان معروفا معناهن.\n\nوالصواب عندنا في ذلك: ما قاله أهل العلم الذين حكينا قولهم، لأنهم أعلم بذلك، وإن كان للذي قاله من ذكرنا قوله من أهل العربية وَجْهٌ.\n\n* *\n\nوقوله: ﴿وَاللَّيْلِ إِذَا يَغْشَاهَا﴾\n\nيقول تعالى ذكره: والليل إذا يغشي الشمس، حتى تغيب فَتُظْلِمُ الآفَاقُ.\n\nوكان قتادة يقول في ذلك ما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَاللَّيْلِ إِذَا يَغْشَاهَا﴾ : إذا غَشَّاها الليل.\n\n* *\n\nوقوله: ﴿وَالسَّمَاءِ وَمَا بَنَاهَا﴾\n\nيقول جلّ ثناؤه: والسماء ومَنْ بناها، يعني: ومَنْ خَلَقها، وبناؤه إياها: تصييره إياها للأرض سقفا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالسَّمَاءِ وَمَا بَنَاهَا﴾ وبناؤها: خَلْقُها.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَالسَّمَاءِ وَمَا بَنَاهَا﴾ قال: الله بنى السماء.\n\nوقيل: ﴿وَمَا بَنَاهَا﴾ وهو جلّ ثناؤه بانيها، فوضع \"ما\" موضع \"مَنْ\" كما قال ﴿وَوَالِدٍ وَمَا وَلَدَ﴾ ، فوضع \"ما\" في موضع \"مَنْ\" ومعناه، ومَن ولد، لأنه قَسَمٌ أقسم بآدم وولده، وكذلك: ﴿وَلا تَنْكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ﴾ ، وقوله: ﴿فَانْكِحُوا مَا طَابَ لَكُمْ﴾ وإنما هو: فانكحوا مَنْ طاب لكم. وجائز توجيه ذلك إلى معنى المصدر، كأنه قال: والسماء وبنائها، ووالد وولادِته.\n\n* *\n\nوقوله: ﴿وَالأرْضِ وَمَا طَحَاهَا﴾\n\nوهذه أيضا نظير التي قبلها، ومعنى الكلام: والأرض ومَنْ طحاها.\n\nومعنى قوله: ﴿طَحَاهَا﴾ : بسطها يمينا وشمالا ومن كلّ جانب.\n\nوقد اختلف أهل التأويل في معنى قوله: ﴿طَحَاهَا﴾ فقال بعضهم: معنى ذلك: والأرض وما خلق فيها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَالأرْضِ وَمَا طَحَاهَا﴾ يقول: ما خلق فيها.\n\nوقال آخرون: يعني بذلك: وما بسطها.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمارة، قال: ثنا عبيد الله بن موسى، قال: ثنا عيسى؛ وحدتني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَالأرْضِ وَمَا طَحَاهَا﴾ قال: دحاها.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَمَا طَحَاهَا﴾ قال: بَسَطَها.\n\nوقال آخرون: بل معنى ذلك: وما قسمها.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَالأرْضِ وَمَا طَحَاهَا﴾ يقول: قسمها.\n\n* *\n\nوقوله: ﴿وَنَفْسٍ وَمَا سَوَّاهَا﴾\n\nيعني جلّ ثناؤه بقوله: ﴿وَمَا سَوَّاهَا﴾ نفسه؛ لأنه هو الذي سوّى النفس وخلقها، فعدّل خلقها، فوضع \"ما\" موضع \"مَنْ\" وقد يُحتمل أن يكون معنى ذلك أيضا المصدر، فيكون تأويله: ونفس وتسويَتها، فيكون القسم بالنفس وبتسويتها.\n\n* *\n\nوقوله: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾\n\nيقول تعالى ذكره: فبين لها ما ينبغي لها أن تأتي أو تذر من خير، أو شرّ أو طاعة، أو معصية.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ يقول: بَيَّنَ الخيرَ والشرَّ.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ يقول: بين الخيرَ والشرَّ.\n\nمحمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ قال: علَّمها الطاعة والمعصية.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ قال: عَرَّفَها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ : فبَيَّن لها فجورها وتقواها.\n\n⁕ وحُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ ، بين لها الطاعةَ والمعصيةَ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ قال: أعلمها المعصية والطاعة.\n\n⁕ قال: ثنا مِهْران، عن سفيان، عن الضحاك بن مزاحم ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ قال: الطاعةَ والمعصيةَ.\n\nوقال آخرون: بل معنى ذلك: أن الله جعل فيها ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ قال: جعل فيها فجورَها وتقواها.\n\n⁕ حدثنا ابن بشار، قال: ثنا صفوان بن عيسى وأبو عاصم النبيل، قالا ثنا عزرة بن ثابت، قال: ثني يحيى بن عقيل، عن يحيى بن يَعْمَر، عن أبي الأسود الدّيلي، قال: قال لي عمران بن حُصين: أرأيت ما يعمل الناس فيه ويتكادحون فيه أشيء قُضِيَ عليهم، ومضى عليهم من قَدَرٍ قد سبق، أو فيما يستقبلون مما أتاهم به نبيهم عليه الصلاة والسلام، وأكدت عليهم الحجة؟ قلت: بل شيء قُضِيَ عليهم، قال: فهل يكون ذلك ظلما؟ قال: ففزعت منه فزعا شديدا، قال: قلت له: ليس شيء إلا وهو خَلْقُه، ومِلْكُ يده، ﴿لا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾ قال: سددّك الله، إنما سألتك \"أظنه أنا\" لأخْبُرَ عقلك. إن رجلا من مُزَينة أو جهينة، أتى النبيّ ﷺ، فقال: يا رسول الله، أرأيت ما يعمل الناس فيه ويتكادحون أشيء قضي عليهم، ومضى عليهم من قدر سبق، أو فيما يستقبلون مما أتاهم به نبيهم عليه السلام وأكّدت به عليهم الحجة؟ قال: \"فِي شَيء قَدْ قُضِيَ عَلَيْهِمْ\"؛ قال: ففيم نعملُ؟ قال: \"مَنْ كانَ اللهُ خَلَقَهُ لإحْدَى المَنزلَتَينِ يُهَيِّئُهُ لَهَا، وَتَصْدِيقُ ذَلكَ فِي كِتَابِ اللهِ: ﴿وَنَفْسٍ وَمَا سَوَّاهَا فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ \".","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":"القول في تأويل قوله تعالى: ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا (٩) وَقَدْ خَابَ مَنْ دَسَّاهَا (١٠) كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا (١١) إِذِ انْبَعَثَ أَشْقَاهَا (١٢) فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا (١٣) فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاهَا (١٤) وَلا يَخَافُ عُقْبَاهَا (١٥) ﴾\n\n.\n\n* *\n\nقوله: ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾\n\nيقول: قد أفلح من زكَّى الله نفسه، فكثَّر تطهيرها من الكفر والمعاصي، وأصلحها بالصالحات من الأعمال.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ يقول: قد أفلح من زكَّى اللهُ نفسه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن خَصِيفٍ، عن مجاهد وسعيد بن جُبير وعكرِمة: ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ قالوا: من أصلحها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن خصيف، عن مجاهد وسعيد بن جُبير، ولم يذكر عكرِمة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ من عمل خيرا زكَّاها بطاعة الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ قال: قد أفلح من زكَّى نفسَه بعمل صالح.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ يقول: قد أفلح من زكى اللهُ نفسَه.\n\nوهذا هو موضع القسم؛\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: قد وقع القسم ها هنا ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ وقد ذكرتُ ما تقول أهل العربية في ذلك فيما مضى من نظائره قبل.\n\n* *\n\nوقوله: ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾\n\nيقول تعالى ذكره: وقد خاب في طِلبته، فلم يُدرك ما طلب والتمس لنفسه مِن الصلاح مَنْ دساها يعني: من دَسَّس الله نفسه فأَخْمَلها، ووضع منها، بخُذلانه إياها عن الهدى حتى ركب المعاصِيَ، وترك طاعة الله. وقيل: دسَّاها وهي دَسَّسها، فقُلبت إحدى سيناتها ياء، كما قال العجَّاج:\n\nتَقَضِّيَ الْبازِي إذا البازِي كَسَرْ\n\nيريد: تَقَضُّض. وتظنَّيت هذا الأمر، بمعنى: تظننت، والعرب تفعل ذلك كثيرا، فتبدل في الحرف المشدّدة بعض حروفه، ياء أحيانا، وواوا أحيانا؛ ومنه قول الآخر:\n\nيَذْهَبُ بِي فِي الشِّعْرِ كُلَّ فَنَّ ... حتى يَرُدَّ عَنِّي التَّظَنِّي\n\nيريد: التظنن.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾ يقول: وقد خاب من دَسَّى اللهُ نَفسَه فأضلَّه.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾ يعني: تكذيبها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن خصيف، عن مجاهد وسعيد بن جُبير ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾ قال أحدهما: أغواها، وقال الآخر: أضلَّها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن خَصيف، عن مجاهد ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾ قال: أضلَّها، وقال سعيد: مَنْ أغواها.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿مَنْ دَسَّاهَا﴾ قال: أغواها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَقَدْ خَابَ مَنْ دَسَّاهَا﴾ قال: أثّمها وأفجرها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، مثله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَقَدْ خَابَ﴾ يقول: وقد خاب من دَسَّى اللهُ نفسَه.\n\n* *\n\nوقوله: ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾\n\nيقول: كذَّبت ثمود بطغيانها، يعني: بعذابها الذي وعدهموه صالح عليه السلام، فكان ذلك العذاب طاغيا طغى عليهم، كما قال جلّ ثناؤه: ﴿فَأَمَّا ثَمُودُ فَأُهْلِكُوا بِالطَّاغِيَةِ﴾ .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل، وإن كان فيه اختلاف بين أهل التأويل.\n\nذكر من قال القول الذي قلنا في ذلك:\n\n⁕ حدثني سعيد بن عمرو السَّكونّي، قال: ثنا الوليد بن سَلَمة الفِلَسْطِينيّ، قال: ثني يزيد بن سمرة المَذحِجيّ عن عطاء الخُراسانيّ، عن ابن عباس، في قول الله: ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾ قال: اسم العذاب الذي جاءها، الطَّغْوَى، فقال: كذّبت ثمود بعذابها.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾ : أي الطغيان.\n\nوقال آخرون: كذّبت ثمود بمعصيتهم الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا عن ابن أبي نجيح، عن مجاهد ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾ قال: معصيتها.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾ قال: بغيانهم وبمعصيتهم.\n\nوقال آخرون: بل معنى ذلك بأجمعها.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني يحيى بن أيوب وابن لَهِيعة، عن عُمارة بن غزية، عن محمد ب رفاعة القُرَظِيّ، عن محمد بن كعب، أنه قال: ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا﴾ قال: بأجمعها.\n\n⁕ حدثني ابن عيد الرحيم الْبَرِقيّ، قال: ثنا ابن أبي مَرْيم، قال: أخبرني يحيى بن أيوب، قال: ثني عمارة بن غزية، عن محمد بن رفاعة القُرَظِيّ، عن محمد بن كعب، مثله.\n\nوقيل ﴿طَغْوَاهَا﴾ بمعنى: طغيانهم، وهما مصدران للتوفيق بين رءوس الآي، إذ كانت الطغْوَى أشبه بسائر رءوس الآيات في هذه السورة، وذلك نظير قوله: ﴿وَآخِرُ دَعْوَاهُمْ﴾ بمعنى: وآخر دعائهم.\n\n* *\n\nوقوله: ﴿إِذِ انْبَعَثَ أَشْقَاهَا﴾\n\nيقول: إذ ثار أشقى ثمود، وهو قُدَار بن سالف.\n\nكما:-\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا الطُّفاويّ، عن هشام، عن أبيه، عن عبد الله بن زَمْعة، قال: خطب رسول الله ﷺ، فذكر في خطبته الناقة، والذي عَقَرها، فقال: ﴿إذِ انْبَعَثَ أشْقَاهَا﴾ انْبَعَثَ لَهَا رَجُلٌ عَزِيزٌ عارِمٌ، مَنِيعٌ فِي رَهْطِهِ، مِثْلُ أبي زَمْعَةَ\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قالا ثنا سعيد، عن قتادة، في قوله. ﴿إِذِ انْبَعَثَ أَشْقَاهَا﴾ يعني أُحَيْمِرَ ثَمود.\n\n* *\n\nوقوله: ﴿فَقَالَ لَهُمْ رَسُولُ اللَّهِ﴾\n\nيعني بذلك جلّ ثناؤه: صالحا رسول الله ﷺ، فقال لثمود صالح: ﴿نَاقَةَ اللَّهِ وَسُقْيَاهَا﴾ احذروا ناقة الله وسُقياها، وإنما حذّرهم سُقيا الناقة، لأنه كان تقدّم إليهم عن أمر الله، أن للناقة شِربَ يوم، ولهم شِرْب يومٍ آخر، غير يوم الناقة، على ما قد بيَّنت فيما مضى قبل.\n\nوكما:-\n\n⁕ حدثني بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة (فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا) قسْم الله الذي قسم لها من هذا الماء.\n\n* *\n\nوقوله: ﴿فَكَذَّبُوهُ فَعَقَرُوهَا﴾\n\nيقول: فكذّبوا صالحا في خبره الذي أخبرهم به، من أن الله الذي جعل شِرْبَ الناقة يوما، ولهم شِرْبُ يوم معلوم، وأن الله يُحِلّ بهم نقمته، إن هم عقروها، كما وصفهم جلّ ثناؤه فقال: ﴿كَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ﴾ ، وقد يُحتمل أن يكون التكذيب بالعقْر. وإذا كان ذلك كذلك، جاز تقديم التكذيب قبل العقر، والعقر قبل التكذيب، وذلك أن كلّ فعل وقع عن سبب حَسُنَ ابتداؤه قبل السبب وبعده، كقول القائل: أعطيت فأحسنت، وأحسنت فأعطيت؛ لأن الإعطاء هو الإحسان، ومن الإحسان الإعطاء، وكذلك لو كان العقر هو سبب التكذيب، جاز تقديم أيّ ذلك شاء المتكلم. وقد زعم بعضهم أن قوله: ﴿فَكَذَّبُوهُ﴾ كلمة مكتفية بنفسها، وأن قوله: ﴿فَعَقَرُوهَا﴾ جواب لقوله: ﴿إِذِ انْبَعَثَ أَشْقَاهَا﴾ كأنه قيل: إذ انبعث أشقاها فعقرها، فقال: وكيف قيل ﴿فَكَذَّبُوهُ فَعَقَرُوهَا﴾ وقد كان القوم قبل قتل الناقة مُسَلِّمين، لها شرب يوم، ولهم شرب يوم آخر. قيل: جاء الخبر أنهم بعد تسليمهم ذلك أجمعوا على منعها الشرب، ورضوا بقتلها، وعن رضا جميعهم قَتَلها قاتِلُها، وعقَرَها من عقرها ولذلك نُسب التكذيب والعقر إلى جميعهم، فقال جلّ ثناؤه: ﴿فَكَذَّبُوهُ فَعَقَرُوهَا﴾ .\n\n* *\n\nوقوله: ﴿فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاهَا﴾\n\nيقول تعالى ذكره: فدمَّر عليهم ربهم بذنبهم ذلك، وكفرهم به، وتكذيبهم رسوله صالحا، وعقرهم ناقته ﴿فَسَوَّاهَا﴾ يقول: فسوّى الدمدمة عليهم جميعهم، فلم يُفْلِت منهم أحد.\n\nكما:-\n\n⁕ حدثني بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاهَا﴾ ذُكر لنا أن أحيمر ثَمود أبى أن يعقرها، حتى بايعه صغيرُهم وكبيرُهم، وذكرهم وأنثاهم، فلما اشترك القوم في عقرها دمدم الله عليهم بذنبهم فسوّاها.\n\n⁕ حدثني بشر بن آدم، قال: ثنا قُتيبة، قال: ثنا أبو هلال، قال: سمعت الحسن يقول: لما عقروا الناقة طلبوا فصيلها، فصار في قارة الجبل، فقطع الله قلوبهم.\n\n* *\n\nوقوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معناه: لا يخاف تبعة دمدمته عليهم.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: لا يخاف الله من أحد تبعة.\n\n⁕ حدثني إبراهيم بن المستمر، قال: ثنا عثمان بن عمرو، قال: ثنا عمر بن مرثد، عن الحسن، في قوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: ذاك ربنا تبارك وتعالى، لا يخاف تبعة مما صنع بهم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن عمرو بن منبه، هكذا هو في كتابي، سمعت الحسن قرأ: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: ذلك الربّ صنع ذلك بهم، ولم يخف تبعة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، عن الحسن، في قوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: لا يخاف تبعتهم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَلا يَخَافُ عُقْبَاهَا﴾ يقول: لا يخاف أن يتبع بشيء مما صنع بهم.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال محمد بن عمرو في حديثه، قال الله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ . وقال الحارث في حديثه: الله لا يخاف عقباها.\n\n⁕ حدثني محمد بن سنان، قال: ثنا يعقوب، قال: ثنا رزين بن إبراهيم، عن أبي سليمان، قال: سمعت بكر بن عبد الله المزنيّ يقول في قوله: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: لا يخاف الله التبعة.\n\nوقال آخرون: بل معنى ذلك: ولم يخف الذي عقرها عقباها: أي عُقبى فعلته التي فعل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا جابر بن نوح، قال: ثنا أبو روق، قال: ثنا الضحاك ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: لم يخف الذي عقرها عقباها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ: ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: لم يخف الذي عقرها عقباها.\n\n⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن السديّ ﴿وَلا يَخَافُ عُقْبَاهَا﴾ قال: الذي لا يخاف الذي صنع، عُقْبَى ما صنع.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الحجاز والشام ﴿فَلا يَخافُ عُقْبَاهَا﴾ بالفاء، وكذلك ذلك في مصاحفهم، وقرأته عامة قرّاء العراق في المِصْرين بالواو ﴿وَلا يَخَافُ عُقْبَاهَا﴾ وكذلك هو في مصاحفهم.\n\nوالصواب من القول في ذلك: أنهما قراءتان معروفتان، غير مختلفي المعنى، فبأيتهما قرأ القارئ فمصيب.\n\nواختلفت القرّاء في إمالة ما كان من ذوات الواو في هذه السورة وغيرها، كقوله: ﴿وَالْقَمَرِ إِذَا تَلاهَا﴾ ﴿وَمَا طَحَاهَا﴾ ونحو ذلك، فكان يفتح ذلك كلَّه عامة قرّاء الكوفة، ويُمِيلون ما كان من ذوات الياء، غير عاصم والكسائي، فإن عاصما كان يفتح جميعَ ذلك ما كان منه من ذوات الواو وذوات الياء، لا يُضْجِعُ منه شيئا.\n\nوكان الكسائي يكسر ذلك كلَّه. وكان أبو عمرو ينظر إلى اتساق رءوس الآي، فإن كانت متسقة على شيء واحد أمال جميعها، وأما عامة قرّاء المدينة فإنهم لا يميلون شيئا من ذلك الإمالة الشديدة، ولا يفتحونه الفتح الشديد، ولكن بين ذلك؛ وأفصح ذلك وأحسنه أن ينظر إلى ابتداء السورة، فإن كانت رءوسها بالياء أجري جميعها بالإمالة غير الفاحشة، وإن كانت رءوسها بالواو فتحت وجرى جميعها بالفتح غير الفاحش، وإذا انفرد نوع من ذلك في موضع أميل ذوات الياء الإمالة المعتدلة، وفتح ذوات الواو الفتح المتوسط، وإن أُميلت هذه، وفُتحت هذه لم يكن لحنا، غير أن الفصيح من الكلام هو الذي وصفنا صفته.\n\nآخر تفسير سورة والشمس وضحاها","10":9,"11":9,"12":9,"13":9,"14":9,"15":9},"92":{"1":"القول في تأويل قوله تعالى جل جلاله وتقدست أسماؤه: ﴿وَاللَّيْلِ إِذَا يَغْشَى (١) وَالنَّهَارِ إِذَا تَجَلَّى (٢) وَمَا خَلَقَ الذَّكَرَ وَالأنْثَى (٣) إِنَّ سَعْيَكُمْ لَشَتَّى (٤) فَأَمَّا مَنْ أَعْطَى وَاتَّقَى (٥) وَصَدَّقَ بِالْحُسْنَى (٦) فَسَنُيَسِّرُهُ لِلْيُسْرَى (٧) وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى (٨) وَكَذَّبَ بِالْحُسْنَى (٩) فَسَنُيَسِّرُهُ لِلْعُسْرَى (١٠) ﴾ .\n\nيقول تعالى ذكره مقسما بالليل إذا غشَّى النهار بظلمته، فأذهب ضوءه، وجاءت ظُلمته: ﴿وَاللَّيْلِ إِذَا يَغْشَى﴾ النهار ﴿وَالنَّهَارِ إِذَا تَجَلَّى﴾ وهذا أيضا قسم، أقسم بالنهار إذا هو أضاء فأنار، وظهر للأبصار. ما كانت ظلمة الليل قد حالت بينها وبين رؤيته وإتيانه إياها عِيانا، وكان قتادة يذهب فيما أقسم الله به من الأشياء أنه إنما أقسم به لعِظَم شأنه عنده.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿وَاللَّيْلِ إِذَا يَغْشَى وَالنَّهَارِ إِذَا تَجَلَّى﴾ قال: آيتان عظيمتان يكوّرهما الله على الخلائق.\n\n* *\n\nوقوله: ﴿وَمَا خَلَقَ الذَّكَرَ وَالأنْثَى﴾\n\nيحتمل الوجهين اللذين وصفت في قوله: ﴿وَالسَّمَاءِ وَمَا بَنَاهَا﴾ وفي ﴿وَالأرْضِ وَمَا طَحَاهَا﴾ وهو أن يجعل \"ما\" بمعنى \"مَنْ، فيكون ذلك قسما من الله جلّ ثناؤه بخالق الذّكر والأنثى، وهو ذلك الخالق، وأن تجعل \"ما\" مع ما بعدها بمعنى المصدر، ويكون قسما بخلقه الذكر والأنثى.\n\nوقد ذُكر عن عبد الله بن مسعود وأبي الدرداء: أنهما كانا يقرآن ذلك ﴿والذَّكَرِ والأنْثَى﴾ ويأثُرُه أبو الدرداء عن رسول الله ﷺ.\n\nذكر الخبر بذلك:\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي إسحاق قال: في قراءة عبد الله ﴿وَاللَّيْلِ إذَا يَغْشَى والنَّهارِ إذَا تَجَلَّى والذَّكَر والأنْثَى﴾ .\n\n⁕ حدثنا ابن المثني، قال: ثنا هشام بن عبد الملك  قال: ثنا شعبة، قال: أخبرني المُغيرة، قال: سمعت إبراهيم يقول: أتى علقمة الشام، فقعد إلى أبي الدرداء، فقال: ممن أنت؟ فقلت: من أهل الكوفة، فقال: كيف كان عبد الله يقرأ هذه الآية ﴿وَاللَّيْلِ إِذَا يَغْشَى وَالنَّهَارِ إِذَا تَجَلَّى﴾ فقلت: ﴿وَالذَّكَرِ والأنْثَى﴾ قال: فما زال هؤلاء حتى كادوا يستضلُّونني، وقد سمعتها من رسول الله ﷺ.\n\n⁕ حدثنا محمد بن عبد الأعلى، قال: ثنا حاتم بن وَرْدان، قال: ثنا أبو حمزة، عن إبراهيم، عن علقمة قال: أتينا الشام، فدخلت على أبي الدرداء، فسألني فقال: كيف سمعت ابن مسعود يقرأ هذه الآية: ﴿وَاللَّيْلِ إِذَا يَغْشَى وَالنَّهَارِ إِذَا تَجَلَّى﴾ قال: قلت: ﴿وَالذَّكَرِ والأنْثَى﴾ قال: كفاك، سمعتها من رسول الله ﷺ يقرؤها.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية؛ وحدثني إسحاق بن شاهين الواسطي، قال: ثنا خالد بن عبد الله عن داود، عن عامر، عن علقمة، قال: قَدِمت الشام، فلقيت أبا الدرداء، فقال: من أين أنت؟ فقلت من أهل العراق؟ قال: من أيَّها؟ قلت: من أهل الكوفة، قال: هل تقرأه قراءة ابن أمّ عبد؟ قلت: نعم، قال: اقرأ ﴿وَاللَّيْلِ إِذَا يَغْشَى﴾ قال: فقرأت: ﴿وَاللَّيْلِ إذَا يَغْشَى والنَّهارِ إذَا تَجَلَّى والذَّكَرِ والأنْثَى﴾ قال: فضحك، ثم قال: هكذا سمعت مِنْ رسول الله ﷺ.\n\n⁕ حدثنا ابن المثنى، قال: ثني عبد الأعلى، قال: ثني داود، عن عامر، عن علقمة، عن أبي الدَّرداء، عن النبيّ ﷺ، بنحوه.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن إبراهيم، عن علقمة، قال: قدمت الشام، فأتى أبو الدرداء، فقال: فيكم أحد يقرأ علي قراءة عبد الله؟ قال: فأشاروا إليّ، قال: قلت أنا، قال: فكيف سمعت عبد الله يقرأ هذه الآية: ﴿وَاللَّيْلِ إذَا يَغْشَى والنَّهارِ إذَا تَجَلَّى والذَّكَرِ والأنْثَى﴾ قال: وأنا هكذا سمعت رسول الله ﷺ يقول: فهؤلاء يريدوني على أن اقرأ ﴿وَمَا خَلَقَ الذَّكَرَ وَالأنْثَى﴾ فلا أنا أتابعهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَمَا خَلَقَ الذَّكَرَ وَالأنْثَى﴾ قال: في بعض الحروف ﴿والذَّكَرِ والأنْثَى﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، مثله.\n\n⁕ حدثني أحمد بن يوسف، قال: ثنا القاسم، قال: ثنا حجاج، عن هارون، عن إسماعيل، عن الحسن أنه كان يقرأها ﴿وَمَا خَلَقَ الذَّكَرَ وَالأنْثَى﴾ يقول: والذي خلق الذكر والأنثى؛ قال هارون قال أبو عمرو: وأهل مكة يقولون للرعد: سبحان ما سبَّحْتَ له.\n\n⁕ حدثنا ابن حُميد، قال: ثنا جرير، عن مُغيرة، عن مِقْسَمٍ الضَّبّي، عن إبراهيم بن يزيد بن أبي عمران، عن علقمة بن قيس أبي شبل: أنه أتى الشام، فدخل المسجد فصَّلى فيه، ثم قام إلى حَلْقة فجلس فيها؛ قال: فجاء رجل إليّ، فعرفت فيه تحوّش، القوم وهيبتهم له، فجلس إلى جنبي، فقلت: الحمد لله إني لأرجو أن يكون الله قد استجاب دعوتي، فإذا ذلك الرجل أبو الدرداء، قال: وما ذاك؟ فقال علقمة: دعوت الله أن يرزقني جليسا صالحا، فأرجو أن يكون أنت، قال: مِنْ أين أنت؟ قلت: من الكوفة، أو من أهل العراق من الكوفة. قال أبو الدرداء: ألم يكن فيكم صاحب النعلين والوساد والمِطْهَرة، يعني ابن مسعود، أو لم يكن فيكم من أُجير على لسان النبيّ ﷺ من الشيطان الرجيم، يعني عَمَّار بن ياسر، أو لم يكن فيكم صاحب السرّ الذي لا يعلمه غيره، أو أحد غيره، يعني حُذَيفة بن اليمان، ثم قال: أيكم يحفظ كما كان عبد الله يقرأ؟ قال: فقلت: أنا، قال: اقرأ: ﴿وَاللَّيْلِ إِذَا يَغْشَى وَالنَّهَارِ إِذَا تَجَلَّى﴾ قال علقمة: فقرأت: ﴿الذكر والأنثى﴾ ، فقال أبو الدرداء: والذي لا إله إلا هو، كذا أقرأنيها رسول الله ﷺ فوه إلى فيّ، فما زال هؤلاء حتى كادوا يردّونني عنها.\n\n* *\n\nوقوله: ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾\n\nيقول: إن عَمَلَكُمْ لمختلف أيها الناس، لأن منكم الكافر بربه، والعاصي له في أمره ونهيه، والمؤمن به، والمطيع له في أمره ونهيه.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: (إِنَّ سَعْيَكُمْ لَشَتَّى) يقول: لمختلف.\n\n* *\n\nوقوله: ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾\n\nجواب القسم، والكلام: والليل إذا يغشى إن سعيكم لشتى، وكذا قال أهل العلم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: وقع القسم ها هنا ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾ .\n\n* *\n\nوقوله: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى﴾\n\nيقول تعالى ذكره: فأما من أعطى واتقى منكم أيها الناس في سبيل الله، ومن أمَرَه الله بإعطائه من ماله، وما وهب له من فضله، واتقى الله واجتنب محارمه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا حميد بن مسعدة، قال: ثنا بشر بن المفضل، قال: ثنا داود، عن عامر، عن عكرِمة، عن ابن عباس، في قوله: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى﴾ قال: أعطى ما عنده واتقى، قال: اتقى ربه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن بن مهدي، قال: ثنا خالد بن عبد الله، عن داود بن أبي هند، عن عكرمة، عن ابن عباس ﴿فَأَمَّا مَنْ أَعْطَى﴾ من الفضل ﴿وَاتَّقَى﴾ : اتقى ربه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَأَمَّا مَنْ أَعْطَى﴾ حق الله ﴿وَاتَّقَى﴾ محارم الله التي نهى عنها.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول قي قوله: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى﴾ يقول: من ذكر الله، واتقى الله.\n\nواختلف أهل التأويل في تأويل قوله تعالى: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ فقال بعضهم: معنى ذلك: وصدّق بالخلَف من الله على إعطائه ما أعطى من ماله فيما أعْطَى فيه مما أمره الله بإعطائه فيه.\n\nذكر من قال ذلك:\n\n⁕ حدثني حميد بن مسعدة، قال: ثنا بشر بن المفضل، قال: ثنا دواد، عن عكرِمة، عن ابن عباس، في قوله: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: وصدّق بالخَلَف من الله.\n\n⁕ حدثني محمد بن المثنى، قال: ثني عبد الأعلى، قال: ثنا داود، عن عكرِمة، عن ابن عباس: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ يقول: وصدّق بالخلَف من الله.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن بن مهدي، قال: ثنا خالد بن عبد الله، عن داود بن أبي هند، عن عكرِمة، عن ابن عباس ﴿وَصَدَّقَ بِالْحُسْنَى﴾ بالخلف.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن داود، عن عكرِمة، عن ابن عباس، مثله.\n\n⁕ حدثنا إسماعيل بن موسى السديّ، قال: أخبرنا بشر بن الحكم الأحْمَسِيِّ، عن سعيد بن الصلت، عن إسماعيل بن أبي خالد، عن أبي صالح، عن ابن عباس ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: أيقن بالخلف.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن قيس بن مسلم، عن عكرِمة ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى﴾ قال: بالخلف.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن قيس بن مسلم، عن عكرِمة ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: بأن الله سيخلف له.\n\n⁕ قال ثنا مهران، عن سفيان، عن أبي هاشم المكي، عن مجاهد ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال بالخلف.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي بكر الهُذليّ، عن شهر بن حوشب، عن ابن عباس: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: بالخلف.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن نضر بن عربي، عن عكرمة، قال: بالخلف.\n\nوقال آخرون: بل معنى ذلك: وصدّق بأن الله واحد لا شريك له.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمر بن عليّ المُقَدَّمِيِّ، قال: ثنا أشعث السجستاني، قال: ثنا مِسْعَر؛ وحدثنا أبو كُرَيب قال: ثنا وكيع، عن مِسْعَر عن أبي حصين، عن أبي عبد الرحمن ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: بلا إله إلا الله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن أبي حصين، عن أبي عبد الرحمن مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهرإن، عن سفيان، عن أبي حصين، عن أبي عبد الرحمن، مثله.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ : بلا إله إلا الله.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَصَدَّقَ بِالْحُسْنَى﴾ : يقول: صدّقَ بلا إله إلا الله.\n\nوقال آخرون: بل معنى ذلك: وصدّق بالجنة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: بالجنة.\n\n⁕ حدثنا ابن بشار، قال: ثني محمد بن محبب، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن ابن أبي نجيح، عن مجاهد، مثله.\n\nوقال آخرون: بل معناه: وصدق بموعود الله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: بموعود الله على نفسه، فعمل بذلك الموعود الذي وعده الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله ﴿وَصَدَّقَ بِالْحُسْنَى﴾ قال: صدّق المؤمن بموعود الله الحسن.\n\nوأشبه هذه الأقوال بما دلّ عليه ظاهر التنزيل، وأولاها بالصواب عندي: قول من قال: عُنِي به التصديق بالخلف من الله على نفقته.\n\nوإنما قلت: ذلك أولى الأقوال بالصواب في ذلك، لأن الله ذكر قبله مُنفقا أنفق طالبا بنفقته الخلف منها، فكان أولى المعاني به أن يكون الذي عقيبه الخبر عن تصديقه بوعد الله إياه بالخلف إذ كانت نفقته على الوجه الذي يرضاه، مع أن الخبر عن رسول الله ﷺ بنحو الذي قلنا في ذلك ورد.\n\nذكر الخبر الوارد بذلك:\n\n⁕ حدثني الحسن بن سلمة بن أبي كبشة، قال: ثنا عبد الملك بن عمرو، قال: ثنا عباد بن راشد، عن قتادة قال: ثني خليد العصري، عن أبي الدرداء، قال: قال رسول الله ﷺ: \"ما مِنْ يَوْمٍ غَرَبَتْ فِيهِ شَمْسُهُ إلا وَبِجَنْبِيهَا مَلَكانِ يُنادِيانِ، يَسْمَعُهُ خَلْقُ اللهِ كُلُّهُم إلا الثَّقَلَينِ: اللَّهُمَّ أعْطِ مُنْفِقا خَلَفا، وأعْطِ مُمْسِكا تلَفا\" فأنزلَ الله في ذلك القرآنَ ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى﴾ ... إلى قوله ﴿لِلْعُسْرَى﴾ .\n\nوذُكر أن هذه الآية نزلت في أبي بكر الصدّيق رضى الله عنه.\n\nذكر الخبر بذلك:\n\n⁕ حدثني هارون بن إدريس الأصمّ، قال: ثنا عبد الرحمن بن محمد المحاربيّ، قال: ثنا محمد بن إسحاق، عن محمد بن عبيد الله بن عبد الرحمن بن أبي بكر الصدّيق، عن عامر بن عبد الله بن الزّبير، قال: كان أبو بكر الصدّيق يُعتق على الإسلام بمكة، فكان يعتق عجائز ونساء إذا أسلمن، فقال له أبوه: أي بنيّ، أراك تعتق أناسا ضعفاء، فلو أنك أعتقت رجالا جَلْدا يقومون معك، ويمنعونك، ويدفعون عنك، فقال: أي أبت، إنما أريد \"أظنه قال\": ما عند الله، قال: فحدثني بعض أهل بيتي، أن هذه الآية أنزلت فيه: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾ .\n\n* *\n\nوقوله: ﴿فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾\n\nيقول: فسنهيئه للخلة اليسرى، وهي العمل بما يرضاه الله منه في الدنيا، ليوجب له به في الآخرة الجنة.\n\n* *\n\nوقوله: ﴿وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى﴾\n\nيقول تعالى ذكره: وأما من بخل بالنفقة في سبيل الله، ومنع ما وهب الله له من فضله، من صرفه في الوجوه التي أمر الله بصرفه فيها، واستغنى عن ربه، فلم يرغب إليه بالعمل له بطاعته بالزيادة فيما خوّله من ذلك.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا حميد بن مسعدة، قال: ثنا بشر بن المفضل، قال: ثنا داود، عن عكرِمة، عن ابن عباس، في قوله: ﴿وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى﴾ قال: بخل بما عنده، واستغنى في نفسه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن، قال: ثنا خالد بن عبد الله، عن داود بن أبي هند، عن عكرِمة عن ابن عباس ﴿وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى﴾ وأما من بخل بالفضل، واستغنى عن ربه.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى﴾ يقول: من أغناه الله، فبخل بالزكاة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى﴾ : وأما من بخل بحقّ الله عليه، واستغنى في نفسه عن ربه.\n\nوأما قوله: ﴿وَكَذَّبَ بِالْحُسْنَى﴾ فإن أهل التأويل اختلفوا في تأويله نحو اختلافهم في قوله: ﴿وَصَدَّقَ بِالْحُسْنَى﴾ وأما نحن فنقول: معناه: وكذّب بالخَلَف.\n\nكما:-\n\n⁕ حدثنا حميد بن مسعدة، قال: ثنا بشر بن المفضل، قال: ثنا داود، عن عكرِمة، عن ابن عباس: ﴿وَكَذَّبَ بِالْحُسْنَى﴾ : وكذّب بالخلف.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن، قال: ثنا خالد بن عبد الله، عن داود بن أبي هند، عن عكرِمة، عن ابن عباس ﴿وَكَذَّبَ بِالْحُسْنَى﴾ بالخلف من الله.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَكَذَّبَ بِالْحُسْنَى﴾ وكذّب بموعود الله الذي وعد، قال الله: ﴿فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَكَذَّبَ بِالْحُسْنَى﴾ وكذّب الكافر بموعود الله الحسن.\n\nوقال آخرون: معناه: وكذّب بتوحيد الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال ثني أبي، عن أبيه، عن ابن عباس ﴿وَكَذَّبَ بِالْحُسْنَى﴾ : وكذّب بلا إله إلا الله.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَكَذَّبَ بِالْحُسْنَى﴾ بلا إله إلا الله.\n\nوقال آخرون: بل معنى ذلك: وكذّب بالجنة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَكَذَّبَ بِالْحُسْنَى﴾ قال: بالجنة.\n\n* *\n\nوقوله: ﴿فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾\n\nيقول تعالى ذكره: فسنهيئه في الدنيا للخلة العُسرى، وهو من قولهم: قد يسرت غنم فلان: إذا ولدت وتهيأت للولادة، وكما قال الشاعر:\n\nهُمَا سَيِّدَنا يَزْعُمانِ وإنَّمَا ... يَسُودَانِنا أنْ يَسَّرَتْ غَنَماهُمَا\n\nوقيل: ﴿فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ ولا تيسر في العُسرى للذي تقدّم في أول الكلام من قوله: ﴿فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾ واذا جمع بين كلامين أحدهما ذكر الخير والآخر ذكر الشرّ، جاز ذلك بالتيسير فيهما جميعا؛ والعُسرى التي أخبر الله جلّ ثناؤه أنه ييسره لها: العمل بما يكرهه ولا يرضاه.\n\nوبنحو الذي قلنا في ذلك جاء الأثر عن رسول الله ﷺ.\n\nذكر الخبر بذلك:\n\n⁕ حدثني واصل بن عبد الأعلى وأبو كُرَيب، قالا ثنا وكيع، عن الأعمش، عن سعد بن عُبيدة، عن أبي عبد الرحمن السُّلَميّ، عن عليّ، قال: كُنَّا جلوسا عند النبيّ ﷺ، فنكَت الأرض، ثم رفع رأسه فقال: \"ما مِنكُمْ مِن أحَدٍ إلا وَقَدْ كُتِبَ مَقْعَدُهُ مِنَ الجَنِّةِ وَمَقَعَدُهُ مِنَ النَّارِ\". قلنا: يا رسول الله أفلا نتكل؟ قال: \"لا اعْمَلُوا فَكُلّ مُيَسَّر\"، ثم قرأ: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ .\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا زائدة بن قُدامة، عن منصور، عن سعد بن عُبيدة عن أبي عبد الرحمن السُّلَميّ، عن عليّ، قال: كنا في جنازة في البقيع، فأتانا رسول الله ﷺ فجلس وجلسنا معه، ومعه عود ينكت في الأرض، فرفع رأسه إلى السماء فقال: \"ما مِنْكُمْ مِنْ نَفْسٍ مَنْفُوسَةٍ إلا قَدْ كُتبَ مَدْخَلُها\"، فقال القوم: يا رسول الله ألا نتكل على كتابنا، فمن كان من أهل السعادة فإنَّهُ يعمل للسعادة، ومن كان من أهل الشقاء فإنه يعمل للشقاء، فقال: \"بَلِ اعْمَلُوا فَكُلٌ مُيَسَّر؛ فأمَّا مَنْ كانَ مِنْ أهْلِ السَّعادَةِ فإنَّهُ يُيَسَّرُ لِعَمَلَ السَعادَةِ وأمَّا مَنْ كَانَ مِنْ أهْلِ الشَّقاءِ فإنَّهُ يُيَسَّرُ للشَّقاءِ\"، ثم قرأ (فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى) .\n\n⁕ حدثنا أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن سعد بن عبيدة، عن أبي عبد الرحمن السلميّ، عن عليّ، عن النبيّ ﷺ بنحوه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن منصور والأعمش: أنهما سمعا سعد بن عُبيدة، عن أبي عبد الرحمن السلميّ، عن عليّ، عن النبيّ ﷺ أنه كان في جنازة، فأخذ عودا، فجعل ينكت في الأرض، فقال: \"ما منْ أحَدٍ إلا وَقَدْ كُتبَ مَقْعَدُهُ مِنَ النَّارِ أوْ مِنَ الجَنَّةِ\"، فقالوا: يا رسول الله أفلا نتكل؟ قال: \"اعْمَلُوا فَكُلّ مُيَسَّرٌ ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ \".\n\n⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن منصور والأعمش، عن سعد بن عُبيدة، عن أبي عبد الرحمن السلميّ، عن عليّ رضى الله عنه قال: كنا جلوسا مع النبيّ ﷺ، فتناول شيئا من الأرض بيده، فقال: \"ما مِنْكُمْ مِنْ أحَدٍ إلا وَقَدْ عَلِمَ مَقْعَدَهُ مِنَ الجَنَّةِ والنَّارِ \" قالوا: يا نبيّ الله، أفلا نتكل؟ قال: \"لا اعْمَلُوا فَكُلّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ\"، ثم قرأ: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى﴾ ... الآيتين.\n\n⁕ قال: ثنا مهران، عن أبي سنان، عن عبد الملك بن سَمُرة بن أبي زائدة، عن النزال بن سَبَرةَ، قال: قال النبيّ ﷺ: \"ما مِنْكُمْ مِنْ نَفْسٍ مَنْفُوسَةٍ إلا قَدْ كُتبَ اللهُ عَلَيْها ما هِيَ لاقِيَتُهُ\" وأعرابي عند النبيّ ﷺ مرتاد، فقال الأعرابيّ: فما جاء بي أضرب من وادي كذا وكذا، إن كان قد فرغ من الأمر.\n\nفنكت النبيّ ﷺ في الأرض، حتى ظنّ القوم أنه ود أنه لم يكن تكلم بشيء منه، فقال النبي ﷺ: \"كُلّ مُيَسرٌ لِمَا خُلِقَ لَهُ، فَمَنْ يُرِدِ اللهُ بِهِ خَيرًا يَسَّرَهُ لِسَبِيلِ الخَيرِ، وَمَنْ يُرِدْ بِهِ شَرًّا يَسَّرَهُ لِسَبِيلِ الشَّرِّ\"، فلقيت عمَرو بن مرّة، فعرضت عليه هذا الحديث، فقال: قال النبيّ ﷺ، وزاد فيه: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ .\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا هشيم، قال: ثنا حصين، عن سعد بن عبيدة، عن أبي عبد الرحمن السلميّ، قال: لما نزلت هذه الآية: (إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ) قال رجل: يا رسول الله، ففيم العمل؟ أفي شيء نستأنفه، أو في شيء قد فُرغ منه؟ فقال رسول الله ﷺ: \"اعْمَلُوا فَكُلٌّ مُيَسَّرٌ: سَنُيَسِّرُهُ لِلْيُسْرَى، وَسَنُيَسِّّرُهُ لِلْعُسْرَى\".\n\n⁕ حدثني عمرو بن عبد الملك الطائي، قال: ثنا محمد بن عبيدة، قال: ثنا الجراح، عن إبراهيم بن عبد الحميد، عن الحجاج بن أرطاة، عن أبي إسحاق الهمداني، عن سليمان الأعمش، رفع الحديث إلى عليّ بن أبي طالب رضى الله عنه أنه قال: كان رسول الله ﷺ ذات يوم جالسا وبيده عود ينكت به في الأرض، فرفع رأسه فقال: \"ما مِنْكُمْ مِنْ أحَدٍ إلا وَقَدْ عُلِمَ مِقْعَدُهُ مِنَ الجَنَّةِ أو النَّار\" قلنا: يا رسول الله أفلا نتوكل؟ قال لهم: \" اعْمَلُوا فَكُلّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ\" ثم قال: \"أمَا سَمِعْتم اللهَ فِي كِتابِهِ يَقُولُ: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ \".\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن بن مهديّ، قال: ثنا خالد بن عبد الله، عن داود بن أبي هند، عن عكرِمة، عن ابن عباس ﴿فَسَنُيَسِّرُهُ لِلْعُسْرَى﴾ : للشرّ من الله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني عمرو بن الحارث، عن أبي الزبير، عن جابر بن عبد الله أنه قال: يا رسول الله، أنعمل لأمر قد فُرغ منه، أو لأمر نأتنفه؟ فقال ﷺ: \"كُلّ عَامِلٍ مُيَسَّرٌ لِعَملِهِ\".\n\n⁕ حدثني يونس، قال: ثنا سفيان، عن عمرو بن دينار، عن طلق بن حبيب، عن بشير بن كعب، قال: سأل غلامان شابان النبيّ ﷺ، فقالا يا رسول الله، أنعمل فيما جفَّت به الأقلام، وجرَت به المقادير، أو في شيء يستأنف؟ فقال: \"بَلْ فِيما جَفَّتْ بِهِ الأقْلامُ وَجَرَتْ به المقادِيُر\" قالا ففيم العمل إذن؟ قال: \"اعمَلُوا، فَكُلُّ عامِلٍ مُيَسَّرٌ لَعَمَلِهِ الَّذِي خلِقَ لَهُ\"، قالا فالآن نجدّ ونعمل.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1,"10":1,"11":"القول في تأويل قوله تعالى: ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى (١١) إِنَّ عَلَيْنَا لَلْهُدَى (١٢) وَإِنَّ لَنَا لَلآخِرَةَ وَالأولَى (١٣) فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى (١٤) ﴾\n\n.","12":11,"13":11,"14":11,"15":"القول في تأويل قوله تعالى: ﴿لا يَصْلاهَا إِلا الأشْقَى (١٥) الَّذِي كَذَّبَ وَتَوَلَّى (١٦) وَسَيُجَنَّبُهَا الأتْقَى (١٧) الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّى (١٨) ﴾ .\n\nيعني جلّ ثناؤه بقوله: ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ﴾ : أي شيء يدفع عن هذا الذي بخل بماله، واستغنى عن ربه، ماله يوم القيامة ﴿إِذًا﴾ هو ﴿تَرَدَّى﴾ .\n\nثم اختلف أهل التأويل في تأويل قوله: ﴿إِذَا تَرَدَّى﴾ فقال بعضهم: تأويله: إذا تردّى في جهنم: أي سقط فيها فَهَوى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا الأشجعيّ، عن ابن أبي خالد، عن أبي صالح ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى﴾ قال: في جهنم. قال أبو كُرَيب: قد سمع الأشجعيّ من إسماعيل ذلك.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قوله: ﴿إِذَا تَرَدَّى﴾ قال: إذا تردّى في النار.\n\nوقال آخرون: بل معنى ذلك: إذا مات.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ليث، عن مجاهد ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى﴾ قال: إذا مات.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إِذَا تَرَدَّى﴾ قال: إذا مات\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا الأشجعيّ، عن سفيان، عن ليث، عن مجاهد، قال: إذا مات.\n\nوأولى القولين في ذلك بالصواب قول من قال: معناه: إذا تردّى في جهنم، لأن ذلك هو المعروف من التردّي، فأما إذا أُريد معنى الموت، فإنه يقال: رَدِيَ فلان، وقلما يقال: تردّى.\n\n* *\n\nوقوله: ﴿إِنَّ عَلَيْنَا لَلْهُدَى﴾\n\nيقول تعالى ذكره: إن علينا لبيانَ الحقّ من الباطل، والطاعة من المعصية.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿إِنَّ عَلَيْنَا لَلْهُدَى﴾ يقول: على الله البيان، بيانُ حلاله وحرامه، وطاعته ومعصيته.\n\nوكان بعض أهل العربية يتأوّله بمعنى: أنه من سلك الهدى فعلى الله سبيله، ويقول وهو مثل قوله: ﴿وَعَلَى اللَّهِ قَصْدُ السَّبِيلِ﴾ ويقول: معنى ذلك: من أراد الله فهو على السبيل القاصد، وقال: يقال معناه: إن علينا للهدى والإضلال، كما قال: ﴿سَرَابِيلَ تَقِيكُمُ الْحَرَّ﴾ وهي تقي الحرّ والبرد.\n\n* *\n\nوقوله: ﴿وَإِنَّ لَنَا لَلآخِرَةَ وَالأولَى﴾\n\nيقول: وإن لنا ملك ما في الدنيا والآخرة، نعطي منهما من أردنا من خلقنا، ونحرمه من شئنا.\n\nوإنما عَنَى بذلك جلّ ثناؤه أنه يوفق لطاعته من أحبّ من خلقه، فيكرمه بها في الدنيا، ويهيئ له الكرامة والثواب في الآخرة، ويخذُل من يشاء خذلانه من خلقه عن طاعته، فيهينه بمعصيته في الدنيا، ويخزيه بعقوبته عليها في الآخرة.\n\nثم قال جل ثناؤه: ﴿فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى﴾ يقول تعالى ذكره: فأنذرتكم أيها الناس نارا تتوهَّج، وهي نار جهنم، يقول: احذروا أن تعصوا ربكم في الدنيا، وتكفروا به، فَتصْلَونها في الآخرة. وقيل: تلظَّى، وإنما هي تتلظَّى، وهي في موضع رفع، لأنه فعل مستقبل، ولو كان فعلا ماضيا لقيل: فأنذرتكم نارًا تلظَّت.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿نَارًا تَلَظَّى﴾ قال: تَوَهَّج.\n\n* *\n\nوقوله: ﴿لا يَصْلاهَا إِلا الأشْقَى﴾\n\nيقول جلّ ثناؤه: لا يدخلها فيصلى بسعيرها إلا الأشقى، ﴿الَّذِي كَذَّبَ وَتَوَلَّى﴾ يقول: الذي كذّب بآيات ربه، وأعرض عنها، ولم يصدق بها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، قال: ثنا هشام بن الغاز، عن مكحول، عن أبي هريرة، قال: لتدخلن الجنة إلا من يأبى، قالوا: يا أبا هريرة: ومن يأبى أن يدخل الجنة؟ قال: فقرأ: ﴿الَّذِي كَذَّبَ وَتَوَلَّى﴾ .\n\n⁕ حدثني الحسن بن ناصح، قال: ثنا الحسن بن حبيب ومعاذ بن معاذ، قالا ثنا الأشعث، عن الحسن في قوله: ﴿لا يَصْلاهَا إِلا الأشْقَى﴾ قال معاذ: الذي كذّب وتولى، ولم يقله الحسن، قال: المشرك.\n\nوكان بعض أهل العربية يقول: لم يكن كذب بردّ ظاهر، ولكن قصر عما أمر به من الطاعة، فجُعِل تكذيبا، كما تقول: لقي فلان العدوّ، فكذب إذا نكل ورجع، وذُكر أنه سمع بعض العرب يقول: ليس لحدّهم مكذوبة، بمعنى: أنهم إذا لقوا صدقوا القتال، ولم يرجعوا؛ قال: وكذلك قول الله: ﴿لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ﴾ .\n\n* *\n\nوقوله: ﴿وَسَيَتَجَنَّبُهَا الأشْقَى﴾\n\nيقول: وسيوقَّى صِلِيَّ النار التي تلظَّى التقيُّ، ووضع أفعل موضع فعيل، كما قال طرَفة:\n\nتَمَنَّى رِجالٌ أنْ أمُوتَ وَإنْ أَمُتْ ... فَتِلكَ سَبيلٌ لَسْتُ فيها بأَوْحَدِ\n\n* *\n\nوقوله: ﴿الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّى﴾\n\nيقول: الذي يعطي ماله في الدنيا في حقوق الله التي ألزمه إياها، ﴿يَتَزَكَّى﴾ : يعني: يتطهر بإعطائه ذلك من ذنوبه.","16":15,"17":15,"18":15,"19":"القول في تأويل قوله تعالى: ﴿وَمَا لأحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى (١٩) إِلا ابْتِغَاءَ وَجْهِ رَبِّهِ الأعْلَى (٢٠) وَلَسَوْفَ يَرْضَى (٢١) ﴾\n\n.\n\nكان بعض أهل العربية يوجه تأويل ذلك إلى: وما لأحد من خلق الله عند هذا الذي يؤتي ماله في سبيل الله يتزكى ﴿مِنْ نِعْمَةٍ تُجْزَى﴾ يعني: من يد يكافئه عليها، يقول: ليس ينفق ما ينفق من ذلك، ويعطي ما يعطي، مجازاة إنسان يجازيه على يد له عنده، ولا مكافأة له على نعمة سلفت منه إليه، أنعمها عليه، ولكن يؤتيه في حقوق الله ابتغاء وجه الله. قال: وإلا في هذا الموضع بمعنى لكن، وقال: يجوز أن يكون يفعل في المكافأة مستقبلا فيكون معناه: ولم يرد بما أنفق مكافأة من أحد، ويكون موقع اللام التي في أحد في الهاء التي خفضتها عنده، فكأنك قلت: وما له عند أحد فيما أنفق من نعمة يلتمس ثوابها، قال: وقد تضع العرب الحرف في غير موضعه إذا كان معروفا، واستشهدوا لذلك ببيت النابغة:\n\nوَقَدْ خِفْتُ حتى ما تَزِيدُ مخافَتِي ... على وَعِلٍ فِي ذِي الَمطَارَةِ عاقِلِ\n\nوالمعنى: حتى ما تزيد مخافة وعل على مخافتي وهذا الذي قاله الذي حكينا قوله من أهل العربية، وزَعْمُ أنه مما يجوز هو الصحيح الذي جاءت به الآثار عن أهل التأويل وقالوا: نزلت في أبي بكر بعِتْقه من أعتق.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، فال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَمَا لأحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى إِلا ابْتِغَاءَ وَجْهِ رَبِّهِ الأعْلَى وَلَسَوْفَ يَرْضَى﴾ يقول: ليس به مثابة الناس ولا مجازاتهم، إنما عطيته لله.\n\n⁕ حدثني محمد بن إبراهيم الأنماطي، قال: ثنا هارون بن معروف. قال: ثنا بشر بن السَّريّ، قال: ثنا مصعب بن ثابت، عن عامر بن عبد الله عن أبيه، قال: نزلت هذه الآية في أبي بكر الصدّيق: ﴿وَمَا لأحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى إِلا ابْتِغَاءَ وَجْهِ رَبِّهِ الأعْلَى وَلَسَوْفَ يَرْضَى﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: أخبرني سعيد، عن قتادة، في قوله ﴿وَمَا لأحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى﴾ قال: نزلت في أبي بكر، أعتق ناسا لم يلتمس منهم جزاء ولا شكورا، ستة أو سبعة، منهم بلال، وعامر بن فُهَيرة.\n\nوعلى هذا التأويل الذي ذكرناه عن هؤلاء، ينبغي أن يكون قوله: ﴿إِلا ابْتِغَاءَ وَجْهِ رَبِّهِ الأعْلَى﴾ نصبا على الاستثناء من معنى قوله: ﴿وَمَا لأحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى﴾ لأن معنى الكلام: وما يؤتي الذي يؤتي من ماله ملتمسا من أحد ثوابه، إلا ابتغاء وجه ربه. وجائز أن يكون نصبه على مخالفة ما بعد إلا ما قبلها، كما قال النابغة:\n\n... ... ... ... ... ... ... ... ... .. ... .... وَما بالرَّبْعِ مِنْ أحَدِ\n\nإلا أَوَارِيَّ لأيًا ما أُبَيِّنُها ... ... ... ... ... ... ... ... ... ...\n\n* *\n\nوقوله: ﴿وَلَسَوْفَ يَرْضَى﴾\n\nيقول: ولسوف يرضى هذا المؤتي ماله في حقوق الله عزّ وجلّ، يتزكى بما يثيبه الله في الآخرة عوضًا مما أتى في الدنيا في سبيله، إذا لقي ربه تبارك وتعالى.\n\nآخر تفسير سورة والليل إذا يغشى","20":19,"21":19},"93":{"1":"القول في تأويل قوله جل جلاله وتقدست أسماؤه ﴿وَالضُّحَى (١) وَاللَّيْلِ إِذَا سَجَى (٢) مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى (٣) وَلَلآخِرَةُ خَيْرٌ لَكَ مِنَ الأولَى (٤) وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى (٥) أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى (٦) وَوَجَدَكَ ضَالا فَهَدَى (٧) وَوَجَدَكَ عَائِلا فَأَغْنَى (٨) ﴾ .\n\nأقسم ربنا جلّ ثناؤه بالضحى، وهو النهار كله، وأحسب أنه من قولهم: ضَحِيَ فلان للشمس: إذا ظهر منه؛ ومنه قوله: ﴿وَأَنَّكَ لا تَظْمَأُ فِيهَا وَلا تَضْحَى﴾ : أي لا يصيبك فيها الشمس.\n\nوقد ذكرت اختلاف أهل العلم في معناه في قوله: ﴿وَالشَّمْسِ وَضُحَاهَا﴾ مع ذكري اختيارنا فيه. وقيل: عُنِي به وقت الضحى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَالضُّحَى﴾ ساعة من ساعات النهار.\n\n* *\n\nوقوله: ﴿وَاللَّيْلِ إِذَا سَجَى﴾\n\nاختلف أهل التأويل في تأويله، فقال بعضهم: معناه: والليل إذا أقبل بظلامه.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَاللَّيْلِ إِذَا سَجَى﴾ يقول: والليل إذا أقبل.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، في قول الله: ﴿وَاللَّيْلِ إِذَا سَجَى﴾ قال: إذا لَبِسَ الناس، إذَا جاء.\n\nوقال آخرون: بل معنى ذلك: إذا ذهب.\n\nذكر من قال ذلك:\n\n⁕ حدثني علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس ﴿وَاللَّيْلِ إِذَا سَجَى﴾ يقول: إذا ذهب.\n\nوقال آخرون: معناه: إذا استوى وسكن.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حُميد، قال: ثنا مِهْران؛ وحدثنا أبو كُرَيب، قال: ثنا وكيع، جميعا عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَاللَّيْلِ إِذَا سَجَى﴾ قال: إذا استوى.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَاللَّيْلِ إِذَا سَجَى﴾ قال: إذا استوى\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَاللَّيْلِ إِذَا سَجَى﴾ سكن بالخلق.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿وَاللَّيْلِ إِذَا سَجَى﴾ يعني: استقراره وسكونه.\n\n⁕ حدثني يونس، قال: أخبرني ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَاللَّيْلِ إِذَا سَجَى﴾ قال: إذا سكن، قال: ذلك سجوه، كما يكون سكون البحر سجوه.\n\nوأولى هذه الأقوال بالصواب عندي في ذلك قول من قال معناه: والليل إذا سكن بأهله، وثبت بظلامه، كما يقال: بحر ساج: إذا كان ساكنا؛ ومنه قول أعشى بني ثعلبة:\n\nفَمَا ذَنْبُنا إنْ جاشَ بَحْرُ ابنِ عَمِّكم ... وَبحْرُكَ ساجٍ ما يُوَارِي الدَّعامِصَا\n\nوقول الراجز:\n\nيا حَبَّذَا القَمْرَاءُ وَاللَّيْلُ السَّاجْ\n\nوطُرُقٌ مِثْلُ مُلاءِ النَّسَّاجْ\n\n* *\n\nوقوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾\n\nوهذا جواب القسم، ومعناه: ما تركك يا محمد ربك وما أبغضك. وقيل: ﴿وَمَا قَلَى﴾ ومعناه. وما قلاك، اكتفاء بفهم السامع لمعناه، إذ كان قد تقدّم ذلك قوله: ﴿مَا وَدَّعَكَ﴾ فعرف بذلك أن المخاطب به نبيّ الله ﷺ.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ يقول: ما تركك ربك، وما أبغضك.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ قال: ما قلاك ربك وما أبغضك؛ قال: والقالي: المبغِض.\n\nوذُكر أن هذه السورة نزلت على رسول الله ﷺ تكذيبا من الله قريشا في قيلهم لرسول الله، لما أبطأ عليه الوحي: قد ودّع محمدًا ربه وقلاه.\n\nذكر الرواية بذلك:\n\n⁕ حدثني عليّ بن عبد الله الدهان، قال: ثنا مفضل بن صالح، عن الأسود بن قيس العبديّ، عن ابن عبد الله، قال: لما أبطأ جبريل على رسول الله ﷺ، فقالت امرأة من أهله، أو من قومه: ودّع الشيطان محمدا، فأنزل الله عليه: ﴿وَالضُّحَى﴾ ... إلى قوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\nقال أبو جعفر: ابن عبد الله: هو جندب بن عبد الله البجلي.\n\n⁕ حدثني محمد بن عيسى الدامغاني، ومحمد بن هارون القطان، قالا ثنا سفيان، عن الأسود بن قيس سمع جندبا البجليّ يقول: أبطأ جبريل على النبيّ ﷺ حتى قال المشركون: ودّع محمدا ربه، فأنزل الله: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن الأسود بن قيس، أنه سمع جندبا البجلي قال: قالت امرأة لرسول الله ﷺ: ما أرى صاحبك إلا قد أبطأ عنك، فنزلت هذه الآية: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأسود بن قيس، قال سمعت جندب بن عبد الله يقول: إن امرأة أتت النبيّ ﷺ فقالت: ما أرى شيطانك إلا قد تركك، فنزلت: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا ابن أبي الشوارب، قال: ثنا عبد الواحد بن زياد، قال: ثنا سليمان الشيباني، عن عبد الله بن شدّاد أن خديجة قالت للنبيّ ﷺ ما أرى ربك إلا قد قلاك، فأنزل الله: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ قال: إن جبريل عليه السلام أبطأ عليه بالوحي، فقال ناس من الناس، وهم يومئذ بمكة، ما نرى صاحبك إلا قد قلاك فودّعك، فأنزل الله ما تسمع: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ قال: أبطأ عليه جبريل، فقال المشركون: قد قلاه ربه وودّعه، فأنزل الله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ مكث جبريل عن محمد ﷺ، فقال المشركون: قد ودّعه ربه وقلاه، فأنزل الله هذه الآية.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ قال: لما نزل عليه القرآن، أبطأ عنه جبريل أياما، فعُيّر بذلك، فقال المشركون: ودّعه ربه وقلاه، فأنزل الله: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن هشام بن عروة، عن أبيه، قال أبطأ جبريل على النبيّ ﷺ، فجزع جزعا شديدا، وقالت خديجة: أرى ربك قد قلاك، مما نرى من جزعك، قال: فنزلت ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ ... إلى آخرها.\n\n* *\n\nوقوله: ﴿وَلَلآخِرَةُ خَيْرٌ لَكَ مِنَ الأولَى﴾\n\nيقول تعالى ذكره: وللدار الآخرة، وما أعد الله لك فيها، خير لك من الدار الدنيا وما فيها. يقول: فلا تحزن على ما فاتك منها، فإن الذي لك عند الله خير لك منها.\n\n* *\n\nوقوله: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾\n\nيقول تعالى ذكره: ولسوف يعطيك يا محمد ربك في الآخرة من فواضل نعمه، حتى ترضى.\n\nوقد اختلف أهل العلم في الذي وعده من العطاء، فقال بعضهم: هو ما\n\n⁕ حدثني به موسى بن سهل الرملي، قال: ثنا عمرو بن هاشم، قال: سمعت الأوزاعيّ يحدّث، عن إسماعيل بن عبيد الله بن أبي المهاجر المخزومي، عن عليّ بن عبد الله بن عباس، عن أبيه، قال: عرض على رسول الله ﷺ ما هو مفتوح على أمته من بعده كَفْرا كَفْرا، فسرّ بذلك، فأنزل الله ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾ فأعطاه في الجنة ألف قصر، في كلّ قصر، ما ينبغي من الأزواج والخدم.\n\n⁕ حدثني محمد بن خلف العسقلاني، قال: ثني روّاد بن الجراح، عن الأوزاعيّ، عن إسماعيل بن عبيد الله، عن عليّ بن عبد الله بن عباس، في قوله: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾ قال: ألف قصر من لؤلؤ، ترابهنّ المسك، وفيهنّ ما يصلحهنّ.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾ ، وذلك يوم القيامة.\n\nوقال آخرون في ذلك ما:-\n\n⁕ حدثني به عباد بن يعقوب، قال: ثنا الحكم بن ظهير، عن السديّ، عن ابن عباس، في قوله: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾ قال: من رضا محمد ﷺ ألا يدخل أحد من أهل بيته النار.\n\n* *\n\nوقوله: ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى﴾\n\nيقول تعالى ذكره معدّدا على نبيه محمد ﷺ نعمه عنده، ومذكِّره آلاءه قِبَله: ألم يجدك يا محمد ربك يتيمًا فآوى، يقول: فجعل لك مأوى تأوي إليه، ومنزلا تنزله ﴿وَوَجَدَكَ ضَالا فَهَدَى﴾ ووجدك على غير الذي أنت عليه اليوم.\n\nوقال السديّ في ذلك ما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن السديّ ﴿وَوَجَدَكَ ضَالا﴾ قال: كان على أمر قومه أربعين عاما. وقيل: عُنِيَ بذلك: ووجدك في قوم ضلال فهداك.\n\n* *\n\nوقوله: ﴿وَوَجَدَكَ عَائِلا فَأَغْنَى﴾\n\nيقول: ووجدك فقيرا فأغناك، يقال منه: عال فلان يَعيل عَيْلَة، وذلك إذا افتقر؛ ومنه قول الشاعر:\n\nفَمَا يَدْرِي الفَقِيرُ مَتى غناهُ ... وَما يَدْرِي الغَنِيُّ مَتى يَعِيلُ\n\nيعني: متى يفتقر.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَوَجَدَكَ عَائِلا﴾ فقيرا.\n\nوذُكر أنها في مصحف عبد الله ﴿وَوَجَدَكَ عَدِيما فآوَى﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى وَوَجَدَكَ ضَالا فَهَدَى وَوَجَدَكَ عَائِلا فَأَغْنَى﴾ قال: كانت هذه منازل رسول الله ﷺ، قبل أن يبعثه الله سبحانه وتعالى.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":"القول في تأويل قوله تعالى: ﴿فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ (٩) وَأَمَّا السَّائِلَ فَلا تَنْهَرْ (١٠) وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ (١١) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ: ﴿فَأَمَّا الْيَتِيمَ﴾ يا محمد ﴿فَلا تَقْهَرْ﴾ يقول: فلا تظلمه، فتذهب بحقه، استضعافًا منك له.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة (فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ) : أي لا تظلم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ﴾ قال: تُغْمِصْه وَتحْقِره. وذُكر أن ذلك في مصحف عبد الله ﴿فَلا تَكْهَرْ﴾ .\n\n* *\n\nوقوله: ﴿وَأَمَّا السَّائِلَ فَلا تَنْهَرْ﴾\n\nيقول: وأما من سألك من ذي حاجة فلا تنهره، ولكن أطعمه واقض له حاجته ﴿وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ﴾ : يقول: فاذكره.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا هشيم، عن أبي بشر، عن مجاهد، في قوله: ﴿وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ﴾ قال: بالنبوّة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا سعيد بن إياس الجريريّ، عن أبى نضرة، قال: كان المسلمون يرون أن من شُكْرِ النعم أن يحدّثَ بها.\n\nآخر تفسير سورة الضحى، ولله الحمد والشكر","10":9,"11":9},"94":{"1":"القول في تأويل قوله تعالى: ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ (١) وَوَضَعْنَا عَنْكَ وِزْرَكَ (٢) الَّذِي أَنْقَضَ ظَهْرَكَ (٣) وَرَفَعْنَا لَكَ ذِكْرَكَ (٤) فَإِنَّ مَعَ الْعُسْرِ يُسْرًا (٥) إِنَّ مَعَ الْعُسْرِ يُسْرًا (٦) فَإِذَا فَرَغْتَ فَانْصَبْ (٧) وَإِلَى رَبِّكَ فَارْغَبْ (٨) ﴾\n\n.\n\nيقول تعالى ذكره لنبيه محمد ﷺ، مذكِّره آلاءه عنده، وإحسانه إليه، حاضا له بذلك على شكره، على ما أنعم عليه، ليستوجب بذلك المزيد منه: ﴿أَلَمْ نَشْرَحْ لَكَ﴾ يا محمد، للهدى والإيمان بالله ومعرفة الحقّ ﴿صَدْرِكَ﴾ فنلِّين لك قلبك، ونجعله وعاء للحكمة: ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ يقول: وغفرنا لك ما سلف من ذنوبك، وحططنا عنك ثقل أيام الجاهلية التي كنت فيها، وهي في قراءة عبد الله فيما ذُكر: ﴿وَحَلَلْنا عَنْكَ وِقْرَكَ الَّذِي أَنْقَض ظَهْرَكَ﴾ يقول: الذي أثقل ظهرك فأوهنه، وهو من قولهم للبعير إذا كان رجيع سفر قد أوهنه السفر، وأذهب لحمه: هو نِقْضُ سَفَر.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد في قول الله: ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ قال: ذنبك.\n\n﴿الَّذِي أَنْقَضَ ظَهْرَكَ﴾ قال: أثقل ظهرك.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ وَوَضَعْنَا عَنْكَ وِزْرَكَ الَّذِي أَنْقَضَ ظَهْرَكَ﴾ : كانت للنبيّ ﷺ ذنوب قد أثقلته، فغفرها الله له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿أَنْقَضَ ظَهْرَكَ﴾ قال: كانت للنبي: ذنوب قد أثقلته، فغفرها الله له.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ يعني: الشرك الذي كان فيه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ قال: شرح له صدرَه، وغفر له ذنبَه الذي كان قبل أن يُنَبأ، فوضعه.\n\nوفي قوله: ﴿الَّذِي أَنْقَضَ ظَهْرَكَ﴾ قال: أثقله وجهده، كما يُنْقِضُ البعيرَ حِمْلُه الثقيل، حتى يصير نِقضا بعد أن كان سمينا ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ قال: ذنبك الذي أنقض ظهرَك، أثقل ظهرك، ووضعناه عنك، وخفَّفنا عنك ما أثقل ظهرَك.\n\n* *\n\nوقوله: ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾\n\nيقول: ورفعنا لك ذكرك، فلا أُذْكَرُ إلا ذُكِرْتَ معي، وذلك قول: لا إله إلا الله، محمد رسول الله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب وعمرو بن مالك، قالا ثنا سفيان بن عيينة، عن ابن أبي نجيح، عن مجاهد ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾ قال: لا أُذْكَرُ إلا ذُكْرِتَ معي: أشهد أن لا إله إلا الله، وأشهد أن محمدا رسول الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾ قال النبيّ ﷺ: \"ابْدَءُوا بالعُبُودَةِ، وَثَنُّوا بالرسالة\" فقلت لمعمر، قال: أشهد أن لا إله إلا الله، وأن محمدا عبده، فهو العبودة، ورسوله أن تقول: عبده ورسوله.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَرَفَعْنَا لَكَ ذِكْرَكَ﴾ رفع الله ذكره في الدنيا والآخرة، فليس خطيب، ولا متشهد، ولا صاحب صلاة، إلا ينادي بها: أشهد أن لا إله إلا الله، وأشهد أن محمدا رسول الله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرنا عمرو بن الحارث، عن درّاج، عن أبي الهيثم عن أبي سعيد الخدريّ، عن رسول الله ﷺ، أنه قال: \"أتانِي جِبْرِيلُ فَقالَ إنَّ رَبِّي وَرَبكَ يَقُولُ: كَيْفَ رَفَعْتُ لَكَ ذِكْرَكَ؟ قال: الله أعْلَمُ، قال: إذَا ذُكِرْتُ ذُكرتَ مَعِي\".\n\n* *\n\nوقوله: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: فإنّ مع الشدّة التي أنت فيها من جهاد هؤلاء المشركين، ومن أوّله ما أنت بسبيله رجاء وفرجا بأن يُظْفِرَكَ بهم، حتى ينقادوا للحقّ الذي جئتهم به طوعا وكَرها.\n\nورُوي عن النبيّ ﷺ أن هذه الآية لما نزلت، بَشَّر بها أصحابه وقال: \"لَنْ يَغْلِبَ عُسْرٌ يُسْرَيْنِ\".\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر بن سليمان، قال: سمعت يونس، قال: قال الحسن: لما نزلت هذه الآية ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ قال رسول الله ﷺ: \"أبْشِرُوا أتاكُمُ اليُسْرُ، لَنْ يَغْلِبَ عُسْرٌ يُسْرَيْنِ\".\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن يونس، عن الحسن، مثله، عن النبيّ ﷺ.\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا عوف، عن الحسن، عن النبي ﷺ، بنحوه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن، قال: خرج النبيّ ﷺ يوما مسرورا فَرِحا وهو يضحك، وهو يقول: \"لَنْ يَغْلِبَ عُسْرٌ يُسْرَيْنَ، لَنْ يَغْلِبَ عُسْرٌ يُسْرَيْنِ ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ \".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ ذُكر لنا أن رسول الله ﷺ بشَّر أصحابه بهذه الآية، فقال: \"لَنْ يَغْلِبَ عُسْرٌ يُسْرَيْنِ\".\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا سعيد، عن معاوية بن قرة أبي إياس، عن رجل، عن عبد الله بن مسعود، قال: لو دخل العسر في جُحْر، لجاء اليسر حتى يدخل عليه، لأن الله يقول: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن شعبة، عن رجل، عن عبد الله، بنحوه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم: قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ قال: يتبع اليسرُ العُسَر.\n\n* *\n\nوقوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾\n\nاختلف أهل التأويل في تأويل ذلك، فقال بعضهم: معناه: فإذا فَرعت من صلاتك، فانصب إلى ربك في الدعاء، وسله حاجاتك.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ يقول: في الدعاء.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ يقول: فإذا فرغت مما فُرض عليك من الصلاة فسل الله، وارغب إليه، وانصب له.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ قال: إذا قمت إلى الصلاة فانصب في حاجتك إلى ربك.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول: في قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ يقول: من الصلاة المكتوبة قبل أن تسلِّم، فانصَب.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ وَإِلَى رَبِّكَ فَارْغَبْ﴾ قال: أمره إذا فرغ من صلاته أن يبالغ في دعائه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿فَإِذَا فَرَغْتَ﴾ من صلاتك ﴿فَانْصَبْ﴾ في الدعاء.\n\nوقال آخرون: بل معنى ذلك: ﴿فَإِذَا فَرَغْتَ﴾ من جهاد عدوّك ﴿فَانْصَبْ﴾ في عبادة ربك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: قال الحسن في قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ قال: أمره إذا فرغ من غزوه، أن يجتهد في الدعاء والعبادة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ قال عن أبيه: فإذا فرغت من الجهاد، جهاد العرب، وانقطع جهادهم، فانصب لعبادة الله ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾ .\n\nوقال آخرون: بل معنى ذلك: فإذا فرغت من أمر دنياك، فانصب في عبادة ربك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ قال: إذا فرغت من أمر الدنيا فانصب، قال: فصّل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ قال: إذا فرغت من أمر دنياك فانصب، فصّل.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن مجاهد، في قوله: ﴿فَإِذَا فَرَغْتَ﴾ قال: إذا فرغت من أمر الدنيا، وقمت إلى الصلاة، فاجعل رغبتك ونيتك له.\n\nوأولى الأقوال في ذلك بالصواب، قول من قال: إن الله تعالى ذكره، أمر نبيه أن يجعل فراغه من كلّ ما كان به مشتغلا من أمر دنياه وآخرته، مما أدّى له الشغل به، وأمره بالشغل به إلى النصب في عبادته، والاشتغال فيما قرّبه إليه، ومسألته حاجاته، ولم يخصص بذلك حالا من أحوال فراغه دون حال، فسواء كلّ أحوال فراغه، من صلاة كان فراغه، أو جهاد، أو أمر دنيا كان به مشتغلا لعموم الشرط في ذلك، من غير خصوص حال فراغ، دون حال أخرى.\n\n* *\n\nوقوله: ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾\n\nيقول تعالى ذكره: وإلى ربك يا محمد فاجعل رغبتك، دون من سواه من خلقه، إذ كان هؤلاء المشركون من قومك قد جعلوا رغبتهم في حاجاتهم إلى الآلهة والأنداد.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾ قال: اجعل نيتك ورغبتك إلى الله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾ قال: اجعل رغبتك ونيتك إلى ربك.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾ قال: إذا قمت إلى الصلاة.\n\nآخر تفسير سورة ألم نشرح","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1},"95":{"1":"القول في تأويل قوله جل جلاله وتقدست أسماؤه: ﴿وَالتِّينِ وَالزَّيْتُونِ (١) وَطُورِ سِينِينَ (٢) وَهَذَا الْبَلَدِ الأمِينِ (٣) لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ (٤) ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ (٥) إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ (٦) ﴾ .\n\nاختلف أهل التأويل في تأويل قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ فقال بعضهم: عُنِي بالتين: التين الذي يؤكل، والزيتون: الزيتون الذي يُعْصر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا روح، قال: ثنا عوف، عن الحسن، في قول الله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: تينكم هذا الذي يؤكل، وزيتونكم هذا الذي يُعْصر.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا المعتمر بن سليمان، قال: سمعت الحكم يحدّث، عن عكرِمة، قال: التين: هو التين، والزيتون: الذي تأكلون.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن يزيد، عن عكرِمة ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: تينكم وزيتونكم.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَيَّة، عن أبي رجاء، قال: سُئِل عكرِمة عن قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: التين تينكم هذا، والزيتون: زيتونكم هذا.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: التين الذي يؤكل، والزيتون: الذي يعصر.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران؛ وحدثنا أبو كُرَيب، قال: ثنا وكيع، جميعا عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: الفاكهة التي تأكل الناس.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سلام بن سليم، عن خصيف، عن مجاهد ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: هو تينكم وزيتونكم.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن حماد، عن إبراهيم، في قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: التين الذي يؤكل، والزيتون الذي يُعصر.\n\n⁕ حدثنا بن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبيّ ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ هو الذي ترون.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قَتَادة، قال: قال الحسن، فى قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ : التين تينكم، والزيتون زيتونكم هذا.\n\nوقال آخرون: التين: مسجد دمشق، والزيتون: بيت المقدس.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا رَوْح، قال: ثنا عوف، عن يزيد أبي عبد الله، عن كعب أنه قال في قول الله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: التين: مسجد دمشق، والزيتون: بيت المقدس.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿وَالتِّينِ﴾ قال: الجبل الذي عليه دمشق ﴿وَالزَّيْتُونَ﴾ : الذي عليه بيت المقدس.\n\n⁕ حدثنا بشر، قال: ثنا يزد، قال: ثنا سعيد، عن قتادة ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ ذُكر لنا أن التين الجبل الذي عليه دمشق، والزيتون: الذي عليه بيت المقدس.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، وسألته عن قول الله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ قال: التين: مسجد دمشق، والزيتون، مسجد إيلياء.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي بكر، عن عكرِمة (وَالتِّينِ وَالزَّيْتُونِ) قال: هما جبلان.\n\nوقال آخرون: التين: مسجد نوح، والزيتون: مسجد بيت المقدس.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَالتِّينِ وَالزَّيْتُونِ﴾ يعني مسجد نوح الذي بني على الجوديّ، والزيتون: بيت المقدس؛ قال: ويقال: التين والزيتون وطور سينين: ثلاثة مساجد بالشام.\n\nوالصواب من القول في ذلك عندنا: قول من قال: التين: هو التين الذي يُؤكل، والزيتون: هو الزيتون الذي يُعصر منه الزيت، لأن ذلك هو المعروف عند العرب، ولا يُعرف جبل يسمى تينا، ولا جبل يقال له زيتون، إلا أن يقول قائل: أقسم ربنا جلّ ثناؤه بالتين والزيتون. والمراد من الكلام: القسم بمنابت التين، ومنابت الزيتون، فيكون ذلك مذهبا، وإن لم يكن على صحة ذلك أنه كذلك دلالة في ظاهر التنزيل، ولا من قول من لا يجوّز خلافه، لأن دمشق بها منابت التين، وبيت المقدس منابت الزيتون.\n\n* *\n\nوقوله: ﴿وَطُورِ سِينِينَ﴾\n\nاختلف أهل التأويل في تأويله، فقال بعضهم: هو جبل موسى بن عمران صلوات الله وسلامه عليه ومسجده.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا معاذ بن هشام، قال: ثني أبي، عن قتادة، عن قزعة، قال: قلت لابن عمر: إني أريد أن آتي بيت المقدس ﴿وَطُورِ سِينِينَ﴾ فقال: لا تأت طور سينين، ما تريدون أن تدعوا أثر نبيّ إلا وطئتموه. قال قتادة ﴿وَطُورِ سِينِينَ﴾ : مسجد موسى ﷺ.\n\n⁕ حدثنا ابن بشار، قال: ثنا روح، قال: ثنا عوف، عن الحسن، في قوله.\n\n﴿طُورِ سِينِينَ﴾ قال: جبل موسى.\n\n⁕ قال: ثنا عوف، عن يزيد أبي عبد الله، عن كعب، في قوله: ﴿وَطُورِ سِينِينَ﴾ قال: جبل موسى ﷺ.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَطُورِ سِينِينَ﴾ قال: هو الطُّور.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَطُورِ سِينِينَ﴾ قال: مسجد الطور.\n\nوقال آخرون: الطور: هو كلّ جبل يُنْبِتُ.\n\n* *\n\nوقوله ﴿سِينِينَ﴾\n\n: حسن.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عمران بن موسى القزاز، قال: ثنا عبد الوارث بن سعيد، قال: ثنا عمارة، عن عكرِمة، في قوله: ﴿وَطُورِ سِينِينَ﴾ قال: هو الحسن، وهي لغة الحبشة، يقولون للشيء الحسن: سِينا سِينا.\n\n⁕ حدثنا يعقوب بن إبراهيم، قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سُئل عكرِمة، عن قوله ﴿وَطُورِ سِينِينَ﴾ قال: طُور: جبل، وسِينين: حَسَنٌ بالحبشية.\n\n⁕ حدثنا ابن حميد، قال: ثنا الصباح بن محارب، عن سفيان، عن أبي إسحاق، عن عمرو بن ميمون، قال: صليت خلف عمر بن الخطاب رضى الله عنه المغرب، فقرأ في أوّل ركعة ﴿وَالتِّينِ وَالزَّيْتُونِ وَطُورِ سِينِينَ﴾ قال: هو جبل.\n\n⁕ حدثني يعقوب، قال: ثنا المعتمر، قال: سمعت الحكم يحدّث، عن عكرِمة ﴿وَطُورِ سِينِينَ﴾ قال: سواء علي نبات السهل والجبل.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَطُورِ سِينِينَ﴾ قال: الجبل.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَطُورِ سِينِينَ﴾ : جبل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَطُورِ سِينِينَ﴾ الجبل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن النضر، عن عكرِمة، قال: الطور: الجبل، والسينين: الحسن، كما ينبت في السهل، كذلك ينبت في الجبل.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبيّ، أما ﴿طُورِ سِينِينَ﴾ فهو الجبل ذو الشجر.\n\nوقال آخرون: هو الجبل، وقالوا: سينين: مبارك حسن.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿وَطُورِ﴾ : الجبل و ﴿سِينِينَ﴾ قال: المبارك.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَطُورِ سِينِينَ﴾ قال: جبل مبارك بالشام.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَطُورِ سِينِينَ﴾ قال: جبل بالشام، مُبارك حسن.\n\nوأولى الأقوال في ذلك بالصواب: قول من قال: طور سينين: جبل معروف، لأن الطور هو الجبل ذو النبات، فإضافته إلى سينين تعريف له، ولو كان نعتا للطور، كما قال من قال معناه حسن أو مبارك، لكان الطور منّونا، وذلك أن الشيء لا يُضاف إلى نعته، لغير علة تدعو إلى ذلك.\n\n* *\n\nوقوله: ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾\n\nيقول: وهذا البلد الآمن من أعدائه أن يحاربوا أهله، أو يغزوهم. وقيل: الأمين، ومعناه: الآمن، كما قال الشاعر:\n\nألمْ تَعْلَمي يا أسْمَ وَيحَكِ أنَّنِي ... حَلَفْتُ يمِينا لا أخُونُ أمِيني\n\nيريد: آمني، وهذا كما قال جلّ ثناؤه: ﴿أَوَلَمْ يَرَوْا أَنَّا جَعَلْنَا حَرَمًا آمِنًا وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ﴾ .\n\nوإنما عني بقوله: ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ : مكة.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال: مكة.\n\n⁕ حدثنا ابن بشار، قال: ثنا روح، قال: ثنا عوف، عن يزيد أبي عبد الله، عن كعب، في قول الله ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال: البلد الحرام.\n\n⁕ حدثنا ابن بشار، قال: ثنا روح، قال: ثنا عوف، عن الحسن، في قوله ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال: البلد الحرام.\n\n⁕ قال: ثنا عبد الرحمن، قال: ثنا سفيان؛ وحدثنا ابن حميد، قال: ثنا مهران، عن سفيان؛ وحدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال مكة.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سَلام بن سليم، عن خَصيف، عن مجاهد: ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ : مكة.\n\n⁕ حدثني يعقوب،، قال: ثنا المعتمر، قال: سمعت الحكم يحدّث عن عكرِمة ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ : قال: البلد الحرام.\n\n⁕ قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سُئل عكرِمة، عن قوله ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال: مكة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ يعني: مكة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ قال: المسجد الحرام.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن حماد، عن إبراهيم ﴿وَهَذَا الْبَلَدِ الأمِينِ﴾ : مكة.\n\n* *\n\nوقوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾\n\nوهذا جواب القسم، يقول تعالى ذكره: والتين والزيتون، لقد خلقنا الإنسان في أحسن تقويم.\n\nوبالذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: وقع القسم ها هنا ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ اختلف أهل التأويل في تأويل قوله (لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ) فقال بعضهم: معناه: في أعدل خلق، وأحسن صورة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عمرو، عن عاصم، عن أبي رَزِين، عن ابن عباس ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: في أعدل خلق.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن حماد، عن إبراهيم ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: في أحسن صورة.\n\n⁕ قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن حماد، عن إبراهيم، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن حماد، عن إبراهيم ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: خَلْقٍ.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حماد، عن إبراهيم ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: في أحسن صورة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ يقول: في أحسن صورة.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ : في أحسن صورة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: أحسن خَلْقٍ.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: في أحسن خلق.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ يقول: في أحسن صورة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، هو والكلبيّ ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾ قالا في أحسن صورة.\n\nوقال آخرون: بل معنى ذلك: لقد خلقنا الإنسان، فبلغنا به استواء شبابه وجلده وقوّته، وهو أحسن ما يكون، وأعدل ما يكون وأقومه.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا المعتمر، قال: سمعت الحكم يحدّث، عن عكرِمة، في قوله: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: الشاب القويّ الجَلْد.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: شبابه أوّل ما نشأ.\n\nوقال آخرون: قيل ذلك لأنه ليس شيء من الحيوان إلا وهو منكبّ على وجهه غير الإنسان.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن المثنى، قال: ثنا ابن أبي عديّ، عن داود، عن عكرِمة، عن ابن عباس ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ قال: خلق كلّ شيء منكبا على وجهه، إلا الإنسان.\n\nوأولى الأقوال في ذلك بالصواب: أن يقال: إن معنى ذلك: لقد خلقنا الإنسان في أحسن صورة وأعدلها؛ لأن قوله: ﴿أَحْسَنِ تَقْوِيمٍ﴾ إنما هو نعت لمحذوف، وهو في تقويم أحسن تقويم، فكأنه قيل: لقد خلقناه في تقويم أحسن تقويم.\n\n* *\n\nوقوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾\n\nاختلف أهل التأويل في تأويل ذلك، فقال بعضهم: معنى ذلك: ثم رددناه إلى أرذل العمر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن داود، عن عكرِمة، عن ابن عباس ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: إلى أرذل العمر.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام بن سلم، عن عمرو، عن عاصم، عن أبي رزين، عن ابن عباس ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: إلى أرذل العمر.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ يقول: يرّد إلى أرذل العمر، كبر حتى ذهب عقله، وهم نفر رُدّوا إلى أرذل العمر على عهد رسول الله ﷺ، فسُئل رسول الله ﷺ حين سفهت عقولهم، فأنزل الله عذرهم أن لهم أجرهم الذي عملوا قبل أن تذهب عقولهم.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سُئل عكرِمة، عن قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: ردّوا إلى أرذل العمر.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل وعبد الرحمن، قالا ثنا سفيان، عن حماد، عن إبراهيم، في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: إلى أرذل العمر.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن حماد، عن إبراهيم، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حماد، عن إبراهيم، مثله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: رددناه إلى الهِرَم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: الهِرَم.\n\n⁕ حدثني يعقوب، قال: ثنا المعتمر، قال: سمعت الحكم يحدّث، عن عكرِمة ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: الشيخ الهَرِم، لم يضرّه كبرُه إن ختم الله له بأحسن ما كان يعمل.\n\nوقال آخرون: بل معنى ذلك: ثم رددناه إلى النار في أقبح صورة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي جعفر الرازيّ، عن الربيع بن أنس، عن أبي العالية ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: في شرّ صورة في صورة خنزير.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: النار.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد، قال: إلى النار.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، قال: في النار.\n\n⁕ قال: ثنا مؤمل، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد قال: إلى النار.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: قال الحسن: جهنم مأواه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: قال الحسن، في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: في النار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: إلى النار.\n\nوأولى الأقوال في ذلك عندي بالصحة، وأشبهها بتأويل الآية، قول من قال: معناه: ثم رددناه إلى أرذل العمر، إلى عمر الخَرْفَى، الذين ذهبت عقولهم من الهِرَم والكِبر، فهو في أسفل من سفل في إدبار العمر وذهاب العقل.\n\nوإنما قلنا: هذا القول أولى بالصواب في ذلك؛ لأن الله تعالى ذكره، أخبر عن خلقه ابن آدم، وتصريفه في الأحوال، احتجاجا بذلك على مُنكري قُدرته على البعث بعد الموت، ألا ترى أنه يقول: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ يعني: بعد هذه الحُجَج.\n\nومحال أن يحتجّ على قوم كانوا مُنكرين معنى من المعاني بما كانوا له مُنكرين. وإنما الحجة على كلّ قوم بما لا يقدرون على دفعه، مما يعاينونه ويحسُّونه، أو يقرّون به، وإن لم يكونوا له مُحسين.\n\nوإذْ كان ذلك كذلك، وكان القوم للنار- التي كان الله يتوعدهم بها في الآخرة- مُنكرين، وكانوا لأهل الهِرَم والخَرَف من بعد الشباب والجَلَد شاهدين، علم أنه إنما احتجّ عليهم بما كانوا له مُعاينين، من تصريفه خلقه، ونقله إياهم من حال التقويم الحسن والشباب والجلد، إلى الهِرَم والضعف وفناء العمر، وحدوث الخَرَف.\n\n* *\n\nوقوله: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾\n\nاختلف أهل التأويل في معنى هذا الاستثناء، فقال بعضهم: هو استثناء صحيح من قوله ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قالوا: وإنما جاز استثناء الذين آمنوا وعملوا الصالحات، وهم جمع، من الهاء في قوله ﴿ثُمَّ رَدَدْنَاهُ﴾ وهي كناية الإنسان، والإنسان في لفظ واحد، لأن الإنسان وإن كان في لفظ واحد، فإنه في معنى الجمع، لأنه بمعنى الجنس، كما قيل: ﴿وَالْعَصْرِ إِنَّ الإنْسَانَ لَفِي خُسْرٍ﴾ قالوا: وكذلك جاز أن يقال: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ فيضاف أفعل إلى جماعة، وقالوا: ولو كان مقصودا به قصد واحد بعينه، لم يجز ذلك، كما لا يُقال: هذا أفضل قائمين، ولكن يقال: هذا أفضل قائم\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن سعيد بن سابق، عن عاصم الأحول، عن عكرِمة، قال: من قرأ القرآن لم يرد إلى أرذل العمر، ثم قرأ: ﴿لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال: لا يكون حتى لا يعلم من بعد علم شيئا، فعلى هذا التأويل قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ لخاصّ من الناس، غير داخل فيهم الذين آمنوا وعملوا الصالحات، لأنه مستثنى منهم.\n\nوقال آخرون: بل الذين آمنوا وعملوا الصالحات قد يدخلون في الذين ردّوا إلى أسفل سافلين، لأن أرذل العمر قد يردّ إليه المؤمن والكافر. قالوا: وإنما استثنى قوله: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ من معنى مضمر في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قالوا: ومعناه: ثم رددناه أسفل سافلين، فذهبت عقولهم وخرفوا، وانقطعت أعمالهم، فلم تثبت لهم بعد ذلك حسنة ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ فإن الذي كانوا يعملونه من الخير، في حال صحة عقولهم، وسلامة أبدانهم، جار لهم بعد هرمهم وخَرَفهَم.\n\nوقد يُحتمل أن يكون قوله: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ استثناء منقطعا، لأنه يحسن أن يقال: ثم رددناه أسفل سافلين، إلا الذين آمنوا وعملوا الصالحات، لهم أجر غير ممنون، بعد أن يردّ أسفل سافلين.\n\nذكر من قال معنى هذا القول:\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن داود، عن عكرِمة، عن ابن عباس ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ قال: فأيما رجل كان يعمل عملا صالحا وهو قوي شاب، فعجز عنه، جرى له أجر ذلك العمل حتى يموت.\n\n⁕ حدثني محمد بن سعد، قال: ثنى أبي، قال: ثني عمى، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ يقول: إذا كان يعمل بطاعة الله في شبيبته كلها، ثم كبر حتى ذهب عقله، كُتب له مثل عمله الصالح، الذي كان يعمل في شبيبته، ولم يُؤاخذ بشيء مما عمل في كبره، وذهاب عقله، من أجل أنه مؤمن، وكان يطيع الله في شبيبته.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن حماد، عن إبراهيم، في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ قال: إلى أرذل العمر، فإذا بلغ المؤمن إلى أرذل العمر، كُتِبَ له كأحسن ما كان يعمل في شبابه وصحته، فهو قوله: (فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) .\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن حماد، عن إبراهيم ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ فإنه يكتب له من الأجر، مثل ما كان يعمل في الصحة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن حماد بن أبي سليمان، عن إبراهيم، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن حماد، عن إبراهيم ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال: إذا بلغ من الكبر ما يعجز عن العمل، كُتِب له ما كان يعمل.\n\nوقال آخرون: بل معنى ذلك: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ فإنه يُكتب لهم حسناتهم ويُتجاوز لهم عن سيئاتهم.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عمرو، عن عاصم، عن أبي رَزين عن ابن عباس ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال: هم الذين أدركهم الكبر، لا يؤاخذون بعمل عملوه في كبرهم، وهم هَرْمَى لا يعقلون.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن أبي رجاء، قال: سُئل عكرمة، عن قوله: ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ قال: يوفيه الله أجره أو عمله، ولا يؤاخذه إذا رُدّ إلى أرذل العمر.\n\n⁕ حدثني يعقوب، قال: ثنا المعتمر بن سليمان، قال: سمعت الحكم يحدّث، عن عكرِمة ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال: الشيخ الهرم لم يضرّه كبره إن ختم الله له بأحسن ما كان يعمل.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال: من أدركه الهرم، وكان يعمل صالحا، كان له مثل أجره إذا كان يعمل.\n\nوقال آخرون: بل معنى ذلك: ثم رددناه أسفل سافلين في جهنم، إلا الذين آمنوا وعملوا الصالحات، فلهم أجر غير ممنون، فعلى هذا التأويل: إلا الذين آمنوا وعملوا الصالحات مستثنون من الهاء في قوله: ﴿ثُمَّ رَدَدْنَاهُ﴾ ، وجاز استثناؤهم منها إذ كانت كناية للإنسان، وهو بمعنى الجمع، كما قال: ﴿إِنَّ الإنْسَانَ لَفِي خُسْرٍ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ إِلا الَّذِينَ آمَنُوا﴾ : إلا من آمن.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: قال الحسن، في قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ : في النار ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ قال الحسن: هي كقوله: ﴿وَالْعَصْرِ إِنَّ الإنْسَانَ لَفِي خُسْرٍ إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ .\n\nوأولى الأقوال في ذلك عندنا بالصحة، قول من قال: معناه: ثم رددناه إلى أرذل العمر، إلا الذين آمنوا وعملوا الصالحات في حال صحتهم وشبابهم، فلهم أجر غير ممنون بعد هرمهم، كهيئة ما كان لهم من ذلك على أعمالهم، في حال ما كانوا يعملون وهم أقوياء على العمل.\n\nوإنما قلنا ذلك أولى بالصحة لما وصفنا من الدلالة على صحة القول بأن تأويل قوله: ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾ إلى أرذل العمر.\n\nاختلفوا في تأويل قوله: ﴿غَيْرُ مَمْنُونٍ﴾ فقال بعضهم: معناه: لهم أجر غير منقوص.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ يقول: غير منقوص.\n\nوقال آخرون: بل معناه: غير محسوب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن جُرَيج، عن مجاهد ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ : غير محسوب.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا مؤمل، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ قال: غير محسوب.\n\n⁕ قال: ثنا سفيان، عن حماد، عن إبراهيم ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ قال: غير محسوب.\n\nوقد قيل: إن معنى ذلك: فلهم أجر غير مقطوع.\n\nوأولى الأقوال في ذلك بالصواب: قول من قال: فلهم أجر غير منقوص، كما كان له أيام صحته وشبابه، وهو عندي من قولهم: جبل مَنِين: إذا كان ضعيفا؛ ومنه قول الشاعر:\n\nأعْطَوْا هُنَيْدَة يَحْدُوها ثَمَانِيَة ... ما فِي عَطائِهمُ مَنٌّ وَلا سَرَف\n\nيعني: أنه ليس فيه نقص، ولا خطأ.","2":1,"3":1,"4":1,"5":1,"6":1,"7":"القول في تأويل قوله تعالى: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ (٧) أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ (٨) ﴾\n\n.\n\nاختلف أهل التأويل في تأويل قوله: ﴿فَمَا يُكَذِّبُكَ بَعْدُ﴾ فقال بعضهم معناه: فمن يكذّبك يا محمد بعد هذه الحجج التي احتججنا بها، بالدين، يعني: بطاعة الله، وما بعثك به من الحقّ، وأن الله يبعث من في القبور؟ قالوا: \"ما\" في معنى \"مَنْ\"، لأنه عُنِيَ به ابن آدم، ومن بعث إليه النبيّ ﷺ.\n\nوقال آخرون: بل معنى ذلك: فما يكذّبك أيها الإنسان بعد هذه الحجج بالدين.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، قال: قلت لمجاهد: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ عني به النبيّ ﷺ؟ قال: معاذ الله! عُني به الإنسان.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عمن سمع مجاهدا يقول: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ قلت: يعني به: النبيّ ﷺ؟ قال: معاذ الله! إنما يعني به الإنسان.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ أعني به النبيّ ﷺ؟ قال: معاذ الله! إنما عُنِيَ به الإنسان.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبيّ ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ ؟ إنما يعني الإنسان، يقول: خلقتك في أحسن تقويم، فما يكذّبك أيها الإنسان بعد بالدين.\n\nوقال آخرون: إنما عني بذلك رسول الله ﷺ، وقيل له: استيقن مع ما جاءك من الله من البيان، أن الله أحكم الحاكمين.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ أي استيقن بعد ما جاءك من الله البيان ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾ .\n\nوأولى الأقوال في ذلك عندي بالصواب قول من قال: معنى \"ما\" معنى \"مَنْ\"، ووجه تأويل الكلام إلى: فمن يكذبك يا محمد بعد الذي جاءك من هذا البيان من الله بالدين؟ يعني: بطاعة الله، ومجازاته العباد على أعمالهم. وقد تأوّل ذلك بعض أهل العربية بمعنى: فما الذي يكذّبك بأن الناس يدانون بأعمالهم؟ وكأنه قال: فمن يقدر على تكذيبك بالثواب والعقاب، بعد ما تبين له خلقنا الإنسان على ما وصفنا.\n\nواختلفوا في معنى قوله: ﴿بِالدِّينِ﴾ فقال بعضهم: بالحساب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عبد الرحمن بن الأسود الطُّفاوي، قال: ثنا محمد بن ربيعة، عن النضر بن عربيّ، عن عكرِمة، في قوله: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ قال: الحساب.\n\nوقال آخرون: معناه: بحكم الله.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾ يقول: ما يكذّبك بحكم الله.\n\nوأولى القولين في ذلك بالصواب قول من قال: الدين في هذا الموضع: الجزاء والحساب، وذلك أن أحد معانى الدين في كلام العرب: الجزاء والحساب؛ ومنه قولهم: كما تدين تُدان. ولا أعرف من معاني الدين \"الحكم\" في كلامهم، إلا أن يكون مرادا بذلك: فما يكذّبك بعد بأمر الله الذي حكم به عليك أن تطيعه فيه؟ فيكون ذلك.\n\n* *\n\nوقوله: ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾\n\nيقول تعالى ذكره: أليس الله يا محمد بأحكم من حكم في أحكامه، وفصل قضائه بين عباده؟ وكان رسول الله ﷺ إذا قرأ ذلك فيما بلغنا قال: بَلى.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾ ذُكر لنا أن نبيّ الله ﷺ كان إذا قرأها قال: \"بلى، وأنا على ذلك من الشاهدين\".\n\n⁕ حدثنا أبو كُريب، قال: ثنا وكيع، عن أبيه، عن أبي إسحاق، عن سعيد بن جُبير، قال: كان ابن عباس إذا قرأ: ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾ قال: سبحانك اللهمّ، وبلى.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: كان قتادة إذا تلا ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾ قال: بلى، وأنا على ذلك من الشاهدين، أحسبه كان يرفع ذلك؛ وإذا قرأ: ﴿أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى﴾ ؟ قال: بلى، وإذا تلا ﴿فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ﴾ قال: آمنت بالله، وبما أنزل.\n\nآخر تفسير سورة والتين","8":7},"96":{"1":"القول في تأويل قوله جل جلاله وتقدست أسماؤه: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (١) خَلَقَ الإنْسَانَ مِنْ عَلَقٍ (٢) اقْرَأْ وَرَبُّكَ الأكْرَمُ (٣) الَّذِي عَلَّمَ بِالْقَلَمِ (٤) عَلَّمَ الإنْسَانَ مَا لَمْ يَعْلَمْ (٥) كَلا إِنَّ الإنْسَانَ لَيَطْغَى (٦) أَنْ رَآهُ اسْتَغْنَى (٧) إِنَّ إِلَى رَبِّكَ الرُّجْعَى (٨) ﴾ .\n\nيعني جل ثناؤه بقوله: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ محمدا ﷺ يقول: اقرأ يا محمد بذكر ربك ﴿الَّذِي خَلَقَ﴾ ثم بين الذي خلق فقال: ﴿خَلَقَ الإنْسَانَ مِنْ عَلَقٍ﴾ يعني: من الدم، وقال: من علق؛ والمراد به من علقة، لأنه ذهب إلى الجمع، كما يقال: شجرة وشجر، وقصَبة وَقصَب، وكذلك علقة وعَلَق. وإنما قال: من علق والإنسان في لفظ واحد، لأنه في معنى جمع، وإن كان في لفظ واحد، فلذلك قيل: من عَلَق.\n\n* *\n\nوقوله: ﴿اقْرَأْ وَرَبُّكَ الأكْرَمُ﴾\n\nيقول: اقرأ يا محمد وربك الأكرم ﴿الَّذِي عَلَّمَ بِالْقَلَمِ﴾ خَلْقَهُ للكتابة والخط.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ قرأ حتى بلغ ﴿عَلَّمَ بِالْقَلَمِ﴾ قال: القلم: نعمة من الله عظيمة، لولا ذلك لم يقم، ولم يصلح عيش. وقيل: إن هذه أوّل سورة نزلت في القرآن على رسول الله ﷺ.\n\nذكر من قال ذلك:\n\n⁕ حدثني أحمد بن عثمان البصري، قال: ثنا وهب بن جرير، قال: ثنا أبي، قال: سمعت النعمان بن راشد يقول عن الزهريّ، عن عروة، عن عائشة أنها قالت كان أوّل ما ابتدئ به رسول الله ﷺ من الوحي الرؤيا الصادقة؛ كانت تجيء مثل فلق الصبح، ثم حُبِّب إليه الخلاء، فكان بغار حراء يتحنَّث فيه الليالي ذوات العدد، قبل أن يرجع إلى أهله، ثم يرجع إلى أهله فيتزوّد لمثلها، حتى فجأه الحق، فأتاه، فقال: يا محمد أنت رسول الله، قال رسول الله: \"فَجَثَوْتُ لِرُكْبَتيَّ وأنا قائِمٌ، ثُمَّ رَجَعْتُ تَرْجُفُ بَوَادِرِي، ثُمَّ دَخَلْتُ عَلى خَدِيجَةَ، فَقُلْتُ: زَمِّلُونِي زَمِّلُونِي، حتى ذَهَبَ عنِّي الرَّوْعُ، ثُمَّ أتانِي فَقالَ: يا مُحَمَّدُ، أنا جِبْرِيُل وأنْتَ رَسُولُ اللهِ، قال: فَلَقَدْ هَمَمْت أنْ أطْرَحَ نَفسِي مِنْ حالِقٍ [مِنْ جَبَلٍ] ، فَتَمَثَّل إليَّ حِينَ هَمَمْتُ بذلكَ، فَقالَ: يا مُحَمَّدُ، أنا جِبْرِيلُ، وأنْتَ رَسُولُ اللهِ، ثُمَّ قالَ: اقْرأ، قُلْتُ: ما أقْرأ؟ قال: فأخَذَنِي فَغطَّنِي ثَلاثَ مَرَّاتٍ، حتى بَلَغَ مِنِّي الجَهْدُ، ثُمَّ قالَ: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ فَقَرأتُ، فأتَيْتُ خَدِيجَةَ، فَقَلْتُ: لَقَدْ أشْفَقْتُ عَلى نَفْسِي، فأخْبَرْتُها خَبرِي، فَقالَتْ: أبْشِرْ، فَوَاللهِ لا يُخْزِيكَ الله أبدًا، وَوَاللهِ إنَّكَ لَتَصِلُ الرَّحِمَ، وَتَصْدُقُ الحَدِيثَ، وَتُؤَدِّي الأمانَةَ، وَتحْمِلُ الكَلَّ، وَتَقْرِي الضَّيْفَ، وتُعِينُ عَلى نَوَائِبِ الْحَقّ، ثُمَّ انْطَلَقَتْ بِي إلى وَرَقَةَ بنِ نَوْفَل بنِ أسَدٍ، قالَتْ: اسْمَعْ مِنِ ابْنِ أخِيكَ، فَسأَلنِي، فأخْبَرْتُهُ خَبَرِي، فَقالَ: هَذا النَّامُوسُ الَّذِي أُنزلَ عَلَى مُوسَى ﷺ، لَيْتَنِي فِيها جَذَعٌ، لَيْتَنِي أكُونُ حَيًّا حِينَ يُخْرِجُكَ قَوْمُكَ، قُلْتُ: أوَ مُخْرِجيَّ هُمْ؟ قال: نَعَمْ، إنَّهُ لَمْ يَجِئ رَجُلٌ قَطّ بِمَا جِئْتَ بِهِ، إلا عُودِيَ، وَلَئِنْ أدْرَكَنِي يَوْمُك أنْصُرْكَ نَصْرًا مُؤَزَّرًا، ثُمَّ كانَ أوَّل ما نزلَ عَليَّ مِنَ القُرْآنِ بَعْدَ ﴿اقرأ﴾ : ﴿ن وَالْقَلَمِ وَمَا يَسْطُرُونَ مَا أَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ وَإِنَّ لَكَ لأجْرًا غَيْرَ مَمْنُونٍ وَإِنَّكَ لَعَلى خُلُقٍ عَظِيمٍ فَسَتُبْصِرُ وَيُبْصِرُونَ﴾ و ﴿يَا أَيُّهَا الْمُدَّثِّرُ قُمْ فَأَنْذِرْ﴾ ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى﴾ .\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني يونس، عن ابن شهاب، قال: ثني عروة أن عائشة أخبرته، وذكر نحوه، غير أنه لم يقل:\" ثم كان أوّل ما أنزل عليّ من القرآن ... الكلام إلى آخره.\n\n⁕ حدثنا ابن أبي الشوارب، قال: ثنا عبد الواحد، قال: ثنا سليمان الشيباني، قال: ثنا عبد الله بن شدّاد، قال: أتى جبريل محمدا، فقال: يا محمد اقرأ، فقال: \"وما أقرا؟ \" قال: فضمه، ثم قال: يا محمد اقرأ، قال: \"وما اقرأ؟ \" قال: ﴿بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ حتى بلغ ﴿عَلَّمَ الإنْسَانَ مَا لَمْ يَعْلَمْ﴾ . قال: فجاء إلى خديجة، فقال: \"يا خديجة ما أراه إلا قد عرض لي\"، قالت: كلا والله ما كان ربك يفعل ذلك بك، وما أتيت فاحشة قطّ؛ قال: فأتت خديجة ورقة فأخبرته الخبر، قال: لئن كنت صادقة إن زوجك لنبيّ، ولَيَلْقَينّ من أمته شدة، ولئن أدركته لأومننّ به، قال: ثم أبطأ عليه جبريل، فقالت له خديجة: ما أرى ربك إلا قد قلاك، فأنزل الله: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n⁕ حدثنا إبراهيم بن سعيد الجوهريّ، قال: ثنا سفيان، عن الزهريّ، عن عروة، عن عائشة- قال إبراهيم: قال سفيان: حفظه لنا ابن إسحاق- إن أوّل شيء أُنزل من القرآن: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ .\n\n⁕ حدثنا عبد الرحمن بن بشر بن الحكم النيسابوري، قال: ثنا سفيان، عن محمد بن إسحاق، عن الزهريّ عن عروة، عن عائشة، أن أوّل سورة أُنزلت من القرآن ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ .\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن شعبة، عن عمرو بن دينار، عن عُبيد بن عُمير، قال: أوّل سورة نزلت على رسول الله ﷺ ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ .\n\n⁕ قال: ثنا عبد الرحمن بن مهدي، قال. ثنا شعبة، عن عمرو بن دينار، قال: سمعت عُبيد بن عُمير يقول، فذكر نحوه.\n\n⁕ حدثنا خلاد بن أسلم، قال. أخبرنا النضر بن شميل، قال: ثنا قرّة، قال: أخبرنا أبو رجاء العُطارديّ، قال: كنا في المسجد الجامع، ومقرئنا أبو موسى الأشعري، كأني أنظر إليه بين بُردين أبيضين؛ قال أبو رجاء: عنه أخذت هذه السورة: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ وكانت أوّل سورة نزلت على محمد.\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، قال: ثنا محمد بن إسحاق، عن بعض أصحابه، عن عطاء بن يسار، قال: أوّل سورة نزلت من القرآن ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ .\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى وعبد الرحمن بن مهدي، قالا ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، قال: أوّل ما نزل من القرآن: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ وزاد ابن مهدي: و ﴿ن وَالْقَلَمِ﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن شعبة، عن عمرو بن دينار، قال: سمعت عُبيد بن عُمير يقول: أوّل ما أنزل من القرآن ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ .\n\n⁕ قال ثنا وكيع، عن قُرّة بن خالد، عن أبي رجاء العُطارديّ، قال: إني لأنظر إلى أبي موسى وهو يقرأ القرآن في مسجد البصرة، وعليه بُردان أبيضان، فأنا أخذت منه ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ ، وهي أوّل سورة أنزلت على محمد ﷺ.\n\n⁕ قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد، قال: إن أوّل سورة أُنزلت: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ . ثم ﴿ن وَالْقَلَمِ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n* *\n\nوقوله: ﴿عَلَّمَ الإنْسَانَ مَا لَمْ يَعْلَمْ﴾\n\nيقول تعالى ذكره: علَّم الإنسان الخطّ بالقلم، ولم يكن يَعْلَمُهُ، مع أشياء غير ذلك، مما علمه ولم يكن يعلمه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿عَلَّمَ الإنْسَانَ مَا لَمْ يَعْلَمْ﴾ قال: علَّم الإنسان خطا بالقلم.\n\n* *\n\nوقوله: ﴿كَلا﴾\n\nيقول تعالى ذكره: ما هكذا ينبغي أن يكون الإنسان أن يُنْعِم عليه ربُّه بتسويته خَلقه، وتعليمه ما لم يكن يعلم، وإنعامه بما لا كُفءَ له، ثم يكفر بربه الذي فعل به ذلك، ويطغى عليه، أن رآه استغنى.\n\n* *\n\nوقوله: ﴿إِنَّ الإنْسَانَ لَيَطْغَى أَنْ رَآهُ اسْتَغْنَى﴾\n\nيقول: إن الإنسان ليتجاوز حدّه، ويستكبر على ربه، فيكفر به، لأن رأى نفسه استغنت. وقيل: إن رآه استغنى لحاجة \"رأى\" إلى اسم وخبر، وكذلك تفعل العرب في كل فعل اقتضى الاسم والفعل، إذا أوقعه المخبر عن نفسه على نفسه، مكنيا عنها فيقول: متى تراك خارجا؟ ومتى تحسبك سائرا؟ فإذا كان الفعل لا يقتضي إلا منصوبا واحدا، جعلوا موضع المكنى نفسه، فقالوا: قتلت نفسك، ولم يقولوا: قتلتك ولا قتلته.\n\n* *\n\nوقوله: ﴿إِنَّ إِلَى رَبِّكَ الرُّجْعَى﴾\n\n: يقول: إن إلى ربك يا محمد مَرْجِعَه، فذائق من أليم عقابه ما لا قبل له به.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":"القول في تأويل قوله تعالى: ﴿أَرَأَيْتَ الَّذِي يَنْهَى (٩) عَبْدًا إِذَا صَلَّى (١٠) ﴾\n\n.\n\nذُكر أن هذه الآية وما بعدها نزلت في أبي جهل بن هشام، وذلك أنه قال فيما بلغنا: لئن رأيت محمدا يصلي، لأطأنّ رقبته؛ وكان فيما ذُكر قد نهى رسول الله ﷺ أن يصلي، فقال الله لنبيه محمد ﷺ: أرأيت يا محمد أبا جهل الذي يَنْهاك أن تصلي عند المقام، وهو مُعرض عن الحقّ، مكذّب به. يُعجِّب جلّ ثناؤه نبيه والمؤمنين من جهل أبي جهل، وجراءته على ربه، في نهيه محمدا عن الصلاة لربه، وهو مع أياديه عنده مكذّب به.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن قال: ثنا ورقاء، جميعا عن ابن أبي نجيح. عن مجاهد. في قول الله: ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾ قال: أبو جهل، يَنْهي محمدا ﷺ إذا صلى.\n\n⁕ حدثنا بشر. قال: ثنا يزيد. قال: ثنا سعيد. عن قتادة ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾ نزلت في عدوّ الله أبي جهل، وذلك لأنه قال: لئن رأيت محمدا يصلي لأطأنّ على عنقه، فأنزل الله ما تسمعون.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قول الله: ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾ قال: قال أبو جهل: لئن رأيت محمدا ﷺ يصلي، لأطأنّ على عنقه؛ قال: وكان يقال: لكل أمة فرعون، وفرعون هذه الأمة أبو جهل.\n\n⁕ حدثنا إسحاق بن شاهين الواسطيّ، قال: ثنا خالد بن عبد الله، عن داود، عن عكرِمة، عن ابن عباس، قال: كان رسول ﷺ يصلي، فجاءه أبو جهل، فنهاه أن يصلي، فأنزل الله: ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾ ...\n\nإلى قوله: ﴿كَاذِبَةٍ خَاطِئَةٍ﴾ .","10":9,"11":"القول في تأويل قوله تعالى: ﴿أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى (١١) أَوْ أَمَرَ بِالتَّقْوَى (١٢) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿أَرَأَيْتَ إِنْ كَانَ﴾ محمد ﴿عَلَى الْهُدَى﴾ يعني: على استقامة وسَدَاد في صلاته لربه ﴿أَوْ أَمَرَ بِالتَّقْوَى﴾ أو أمر محمد هذا الذي ينهي عن الصلاة، باتقاء الله، وخوف عقابه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى أَوْ أَمَرَ بِالتَّقْوَى﴾ قال محمد: كان على الهدى، وأمر بالتقوى.\n\n* *\n\nالقول في تأويل قوله تعالى: ﴿أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى (١٣) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿أَرَأَيْتَ إِنْ كَذَّبَ﴾ أبو جهل بالحق الذي بعث به محمدًا ﴿وَتَوَلَّى﴾ يقول: وأدبر عنه، فلم يصدِّّق به.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى﴾ يعني: أبا جهل.\n\n* *\n\nالقول في تأويل قوله تعالى: ﴿أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى (١٤) كَلا لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ (١٥) نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ (١٦) فَلْيَدْعُ نَادِيَهُ (١٧) سَنَدْعُ الزَّبَانِيَةَ (١٨) كَلا لا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ (١٩) ﴾\n\n.\n\nيقول تعالى ذكره: ألم يعلم أبو جهل إذ ينهى محمدا عن عبادة ربه، والصلاة له، بأن الله يراه فيخاف سطوته وعقابه. وقيل: أرأيت الذي ينهى عبدا إذا صلى، أرأيت إن كان على الهدى، فكررت أرأيت مرات ثلاثًا على البدل. والمعنى: أرأيت الذي ينهى عبدا إذا صلى، وهو مكذب متول عن ربه، ألم يعلم بأن الله يراه.\n\n* *\n\nوقوله: ﴿كَلا لَئِنْ لَمْ يَنْتَهِ﴾\n\nيقول: ليس كما قال: إنه يطأ عنق محمد، يقول: لا يقدر على ذلك، ولا يصل إليه.\n\n* *\n\nقوله: ﴿لَئِنْ لَمْ يَنْتَهِ﴾\n\nيقول: لئن لم ينته أبو جهل عن محمد ﴿لَنَسْفَعَنْ بِالنَّاصِيَةِ﴾ يقول: لنأخذنّ بمقدم رأسه، فلنضمنه ولنُذلنه؛ يقال منه: سفعت بيده: إذا أخذت بيده. وقيل: إنما قيل ﴿لَنَسْفَعَنْ بِالنَّاصِيَةِ﴾ والمعنى: لنسوّدنّ وجهه، فاكتفى بذكر الناصية من الوجه كله، إذ كانت الناصية في مقدم الوجه. وقيل: معنى ذلك: لنأخذنّ بناصيته إلى النار، كما قال: ﴿فَيُؤْخَذُ بِالنَّوَاصِي وَالأقْدَامِ﴾ .\n\n* *\n\nوقوله: ﴿نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ﴾\n\nفخفض ناصية ردّا على الناصية الأولى بالتكرير، ووصف الناصية بالكذب والخطيئة، والمعنى لصاحبها.\n\n* *\n\nوقوله: ﴿فَلْيَدْعُ نَادِيَهُ﴾\n\nيقول تعالى ذكره: فليدع أبو جهل أهل مجلسه وأنصاره، من عشيرته وقومه، والنادي: هو المجلس.\n\nوإنما قيل ذلك فيما بلغنا، لأن أبا جهل لما نهى النبيّ ﷺ عن الصلاة عند المقام، انتهره رسول الله ﷺ، وأغلظ له، فقال أبو جهل: علام يتوعدني محمد وأنا أكثر أهل الوادي ناديا؟ فقال الله جلّ ثناؤه: ﴿لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعَنْ بِالنَّاصِيَةِ﴾ ، فليدع حينئذ ناديه، فإنه إن دعا ناديه، دعونا الزبانية.\n\nوبنحو الذي قلنا في ذلك جاءت الأخبار، وقال أهل التأويل.\n\nذكر الآثار المروية في ذلك:\n\n⁕ حدثنا ابن وكيع، قال: ثنا أبو خالد الأحمر؛ وحدثنا أبو كُرَيب، قال: ثنا الحكم بن جميع، قال: ثنا عليّ بن مُسْهِر، جميعا عن داود بن أبي هند، عن عكرِمة، عن ابن عباس قال: كان رسول الله ﷺ يصلي عند المقام، فمرّ به أبو جهل بن هشام، فقال: يا محمد، ألم أنهك عن هذا؟ وتوعَّده، فأغلظ له رسول الله ﷺ وانتهره، فقال: يا محمد بأيّ شيء تهددني؟ أما والله إني لأكثر هذا الوادي ناديا، فأنزل الله: ﴿فَلْيَدْعُ نَادِيَهُ سَنَدْعُ الزَّبَانِيَةَ﴾ قال ابن عباس: لو دعا ناديه، أخذته زبانية العذاب من ساعته.\n\n⁕ حدثني إسحاق بن شاهين، قال: ثنا خالد بن عبد الله، عن داود، عن عكرِمة، عن ابن عباس، قال: كان رسول الله ﷺ يصلي، فجاءه أبو جهل، فنهاه أن يصلي، فأنزل الله: ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾ ... إلى قوله: ﴿كَاذِبَةٍ خَاطِئَةٍ﴾ فقال: لقد علم أني أكثر هذا الوادي نَادِيا، فغضب النبيّ ﷺ، فتكلم بشيء، قال داود: ولم أحفظه، فأنزل الله: ﴿فَلْيَدْعُ نَادِيَهُ سَنَدْعُ الزَّبَانِيَةَ﴾ فقال ابن عباس: فوالله لو فعل لأخذته الملائكة من مكانه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن أبيه، قال: ثنا نعيم بن أبي هند، عن أبي حازم، عن أبي هريرة، قال: قال أبو جهل: هل يعفر محمد وجهه بين أظهركم؟ قال: فقيل نعم، قال: فقال: واللات والعزى لئن رأيته يصلي كذلك، لأطأنّ على رقبته، لأعفرنّ وجهه في التراب، قال: فأتى رسول الله ﷺ وهو يصلي ليطأ على رقبته، قال: فما فجأهم منه إلا وهو ينكص على عَقبيه، ويتقي بيديه؛ قال: فقيل له: مالك؟ قال: فقال: إن بيني وبينه خَنْدقا من نار، وهَوْلا وأجنحة؛ قال: فقال رسول الله ﷺ: \"لَوْ دَنا مِنِّي لاخْتَطَفَتْهُ المَلائِكَةُ عُضْوًا عُضْوًا\" قال: وأنزل الله، لا أدري في حديث أبي هريرة أم لا ﴿كَلا إِنَّ الإنْسَانَ لَيَطْغَى أَنْ رَآهُ اسْتَغْنَى إِنَّ إِلَى رَبِّكَ الرُّجْعَى أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى أَوْ أَمَرَ بِالتَّقْوَى أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى﴾ يعني أبا جهل ﴿أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى كَلا لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعَنْ بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ فَلْيَدْعُ نَادِيَهُ﴾ يدعو قومه ﴿سَنَدْعُ الزَّبَانِيَةَ﴾ الملائكة ﴿كَلا لا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: أخبرنا يونس بن أبي إسحاق، عن الوليد بن العَيْزار، عن ابن عباس، قال: قال أبو جهل: لئن عاد محمد يصلي عند المقام لأقتلنه، فأنزل الله: ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾ حتى بلغ هذه الآية: ﴿لَنَسْفَعَنْ بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ فَلْيَدْعُ نَادِيَهُ سَنَدْعُ الزَّبَانِيَةَ﴾ ، فجاء النبيّ ﷺ وهو يصلي، فقيل له: ما يمنعك؟ قال: \"قد اسودّ ما بيني وبينه من الكتائب\" ... قال ابن عباس: والله لو تحرّك لأخذته الملائكة والناس ينظرون إليه.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا زكريا بن عديّ، قال: ثنا عبيد الله بن عمرو، عن عبد الكريم، عن عكرِمة، عن ابن عباس، قال: قال أبو جهل: لئن رأيت رسول الله ﷺ يصلي عند الكعبة، لآتينه حتى أطأ على عنقه، فقال رسول الله ﷺ: \"لَوْ فَعَلَ لأخَذَتْهُ المَلائِكَةُ عِيانا\".\n\nوبالذي قلنا في معنى النادي قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن مسعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس في قوله: ﴿فَلْيَدْعُ نَادِيَهُ﴾ يقول: فليدع ناصره.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿سَنَدْعُ الزَّبَانِيَةَ﴾ قال: الملائكة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي سنان، عن عبد الله بن أبي الهذيل: الزبانية أرجلهم في الأرض، ورءوسهم في السماء.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر عن قتادة، في قوله: ﴿سَنَدْعُ الزَّبَانِيَةَ﴾ قال النبيّ ﷺ: \"لَوْ فَعَلَ أبُو جَهْلٍ لأخَذَتْهُ الزَّبانِيَةُ المَلائِكَةُ عِيانًا\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿سَنَدْعُ الزَّبَانِيَةَ﴾ قال: الملائكة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: الزبانية، قال: الملائكة.\n\n* *\n\nوقوله: ﴿كُلا﴾\n\nيقول تعالى ذكره: ليس الأمر كما يقول أبو جهل، إذ ينهي محمدًا عن عبادة ربه، والصلاة له ﴿لا تُطِعْهُ﴾ يقول جلّ ثناؤه لنبيه محمد ﷺ: لا تُطع أبا جهل فيما أمرك به من ترك الصلاة لربك ﴿وَاسْجُدْ﴾ لِرَبّكَ ﴿وَاقْتَرَبَ﴾ منه، بالتحبب إليه بطاعته، فإن أبا جهل لن يقدر على ضرّك، ونحن نمنعك منه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿كَلا لا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ﴾ ذكر لنا أنها نزلت في أبي جهل، قال: لئن رأيت محمدًا يصلي لأطأنّ عنقه، فأنزل الله: ﴿كَلا لا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ﴾ قال نبي الله ﷺ حين بلغه الذي قال أبو جهل، قال: \"لو فعل لاختطفته الزبانية\".\n\nآخر تفسير سورة اقرأ باسم ربك، والحمد لله وحده.","12":11,"13":11,"14":11,"15":11,"16":11,"17":11,"18":11,"19":11},"97":{"1":"القول في تأويل قوله تعالى: ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ (١) وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ (٢) لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ (٣) تَنزلُ الْمَلائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ (٤) سَلامٌ هِيَ حَتَّى مَطْلَعِ الْفَجْرِ (٥) ﴾\n\n.\n\nيقول تعالى ذكره: إنا أنزلنا هذا القرآن جملة واحدة إلى السماء الدنيا في ليلة القَدْر، وهي ليلة الحُكْم التي يقضي الله فيها قضاء السنة؛ وهو مصدر من قولهم: قَدَرَ الله عليّ هذا الأمر، فهو يَقْدُر قَدْرا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن المثنى، قال: ثني عبد الأعلى، قال: ثنا داود، عن عكرِمة، عن ابن عباس، قال: نزل القرآن كله مرة واحدة في ليلة القدر في رمضان إلى السماء الدنيا، فكان الله إذا أراد أن يحدث في الأرض شيئًا أنزله منه حتى جمعه.\n\n⁕ حدثنا ابن المثنى قال: ثنا عبد الوهاب، قال: ثنا داود، عن عكرمة، عن ابن عباس، قال: أنزل الله القرآن إلى السماء الدنيا في ليلة القدر، وكان الله إذا أراد أن يوحي منه شيئا أوحاه، فهو قوله: ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ .\n\n⁕ قال: ثنا ابن أبي عديّ، عن داود، عن عكرِمة، عن ابن عباس، فذكر نحوه، وزاد فيه. وكان بين أوّله وآخره عشرون سنة.\n\n⁕ قال ثنا عمرو بن عاصم الكلابي، قال: ثنا المعتمر بن سليمان التيميّ، قال: ثنا عمران أبو العوّام، قال: ثنا داود بن أبي هند، عن الشعبيّ، أنه قال في قول الله: ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ قال: نزل أول القرآن في ليلة القدر.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا حصين، عن حكيم بن جبير، عن ابن عباس، قال: نزل القرآن في ليلة من السماء العليا إلى السماء الدنيا جملة واحدة، ثم فُرِّق في السنين، وتلا ابن عباس هذه الآية: ﴿فَلا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ﴾ قال: نزل متفرّقا.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن داود، عن الشعبيّ، في قوله: ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ قال: بلغنا أن القرآن نزل جملة واحدة إلى السماء الدنيا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سلمة بن كهيل، عن مسلم، عن سعيد بن جُبير: أنزل القرآن جملة واحدة، ثم أنزل ربنا في ليلة القدر: ﴿فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ﴾ .\n\n⁕ قال: ثنا جرير، عن منصور، عن سعيد بن جُبير، عن ابن عباس، في قوله ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ قال: أنزل القرآن جملة واحدة في ليلة القدر، إلى السماء الدنيا، فكان بموقع النجوم، فكان الله ينزله على رسوله، بعضه في أثر بعض، ثم قرأ: ﴿وقالوا لَوْلا نزلَ عَلَيْهِ الْقُرْآنُ جُمْلَةً وَاحِدَةً كَذَلِكَ لِنُثَبِّتَ بِهِ فُؤَادَكَ وَرَتَّلْنَاهُ تَرْتِيلا﴾ .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿ليلة القدر﴾ : ليلة الحكم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ قال: ليلة الحكم.\n\nثنا وكيع. عن سفيان، عن محمد بن سوقة، عن سعيد بن جُبير: يؤذن للحجاج في ليلة القدر، فيكتبون بأسمائهم وأسماء آبائهم، فلا يغادر منهم أحد، ولا يُزاد فيهم، ولا ينقص منهم.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا ربيعة بن كلثوم، قال: قال رجل للحسن وأنا أسمع: رأيت ليلة القدر في كلّ رمضان هي؟ قال: نعم، والله الذي لا إله إلا هو إنها لفي كلّ رمضان، وإنها لليلة القدر، ﴿فيها يُفرق كلّ أمر حكيم﴾ فيها يقضي الله كلّ أجل وعمل ورزق، إلى مثلها.\n\n⁕ حدثنا أبو كُرَيب. قال: ثنا وكيع، عن سفيان، عن أبي إسحاق، عن سعيد بن جُبير، عن ابن عمر. قال: ليلة القدر في كلّ رمضان.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ﴾\n\nيقول: وما أشعرك يا محمد أيّ شيء ليلة القدر خير من ألف شهر.\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معنى ذلك: العمل في ليلة القدر بما يرضي الله، خير منَ العمل في غيرها ألف شهر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: بلغني عن مجاهد ﴿لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ قال: عملها وصيامها وقيامها خير من ألف شهر.\n\n⁕ قال: ثنا الحكم بن بشير، قال: ثنا عمرو بن قيس الملائي، قوله: ﴿خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ قال: عملٌ فيها خير من عمل ألف شهر.\n\nوقال آخرون: معنى ذلك أن ليلة القدر خير من ألف شهر، ليس فيها ليلة القدر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ ليس فيها ليلة القدر.\n\nوقال آخرون في ذلك ما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا حَكَّام بن سلم، عن المُثَنَّى بن الصَّبَّاح، عن مجاهد قال: كان في بني إسرائيل رجل يقوم الليل حتى يصبح، ثم يجاهد العدوّ بالنهار حتى يُمْسِيَ، ففعل ذلك ألف شهر، فأنزل الله هذه الآية: ﴿لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ قيام تلك الليلة خير من عمل ذلك الرجل.\n\nوقال آخرون في ذلك ما:-\n\n⁕ حدثني أبو الخطاب الجاروديّ سهيل، قال: ثنا سَلْم بن قُتيبة، قال: ثنا القاسم بن الفضل، عن عيسى بن مازن، قال: قلت للحسن بن عليّ رضى الله عنه: يا مسوّد وجوه المؤمنين، عمدت إلى هذا الرجل، فبايعت له، يعني معاوية بن أبي سفيان، فقال: إن رسول الله ﷺ أري في منامه بني أميَّة يعلون منبره حليفة خليفة، فشقّ ذلك عليه، فأنزل الله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ و ﴿إِنَّا أَنزلْنَاهُ فِي لَيْلَةِ الْقَدْرِ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ يعني ملك بني أمية؛ قال القاسم: فحسبنا مُلْكَ بني أمية، فإذا هو ألف شهر.\n\nوأشبه الأقوال في ذلك بظاهر التنزيل قول من قال: عملٌ في ليلة القدر خير من عمل ألف شهر، ليس فيها ليلة القدر. وأما الأقوال الأخر، فدعاوى معان باطلة، لا دلالة عليها من خبر ولا عقل، ولا هي موجودة في التنزيل.\n\n* *\n\nوقوله: ﴿تَنزلُ الْمَلائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾\n\nاختلف أهل التأويل في تأويل ذلك، فقال بعضهم: معنى ذلك: تنزل الملائكة وجبريل معهم، وهو الروح في ليلة القدر ﴿بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾ يعني بإذن ربهم، من كلّ أمر قضاه الله في تلك السنة، من رزق وأجل وغير ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله: ﴿مِنْ كُلِّ أَمْرٍ﴾ قال: يقضى فيها ما يكون في السنة إلى مثلها.\n\nفعلى هذا القول منتهى الخبر، وموضع الوقف من كلّ أمر.\n\nوقال آخرون: ﴿تَنزلُ الْمَلائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ﴾ لا يلقون مؤمنا ولا مؤمنة إلا سلَّموا عليه.\n\nذكر من قال ذلك:\n\n⁕ حُدثت عن يحيى بن زياد الفرّاء، قال: ثني أبو بكر بن عياش، عن الكلبيّ، عن أبي صالح، عن ابن عباس: أنه كان يقرأ: \"من كل امرئ سلام\" وهذه القراءة من قرأ بها وجَّه معنى من كلّ امرئ: من كلّ ملَك؛ كان معناه عنده: تنزل الملائكة والروح فيها بإذن ربهم من كلّ ملك يسلم على المؤمنين والمؤمنات؛ ولا أرى القراءة بها جائزة، لإجماع الحجة من القرّاء على خلافها، وأنها خلاف لما في مصاحف المسلمين، وذلك أنه ليس في مصحف من مصاحف المسلمين في قوله \"أمر\" ياء، وإذا قُرِئت: ﴿مِنْ كُلّ امْرِئ﴾ لحقتها همزة، تصير في الخطّ ياء.\n\nوالصواب من القول في ذلك: القول الأوّل الذي ذكرناه قبل، على ما تأوّله قتادة.\n\n* *\n\nوقوله: ﴿سَلامٌ هِيَ حَتَّى مَطْلَعِ الْفَجْرِ﴾\n\nسلام ليلة القدر من الشرّ كله من أوّلها إلى طلوع الفجر من ليلتها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿سَلامٌ هِيَ﴾ قال: خير ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿مِنْ كُلِّ أَمْرٍ سَلامٌ﴾ أي هي خير كلها إلى مطلع الفجر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن جابر، عن مجاهد ﴿سَلامٌ هِيَ حَتَّى مَطْلَعِ الْفَجْرِ﴾ قال: من كلّ أمر سلام.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿سَلامٌ هِيَ﴾ قال: ليس فيها شيء، هي خير كلها ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾ .\n\nموسى بن عبد الرحمن المسروقي، قال: ثنا عبد الحميد الحمانيّ، عن الأعمش، عن المنهال، عن عبد الرحمن بن أبي لَيلى، في قوله: ﴿مِنْ كُلِّ أَمْرٍ سَلامٌ هِيَ﴾ قال: لا يحدث فيها أمر.\n\nوعُنِي بقوله: ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾ : إلى مطلع الفجر.\n\nواختلفت القرّاء في قراءة قوله: ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾ فقرأت ذلك عامة قرّاء الأمصار، سوى يحيى بن وثاب والأعمش والكسائي ﴿مَطْلَعِ الْفَجْرِ﴾ بفتح اللام، بمعنى: حتى طلوع الفجر؛ تقول العرب: طلعت الشمس طلوعا ومطلعا. وقرأ ذلك يحيى بن وثاب والأعمش والكسائي: ﴿حتى مَطْلِعِ الْفَجْرِ﴾ بكسر اللام، توجيها منهم ذلك إلى الاكتفاء بالاسم من المصدر، وهم ينوون بذلك المصدر.\n\nوالصواب من القراءة في ذلك عندنا: فتح اللام لصحة معناه في العربية، وذلك أن المطلع بالفتح هو الطلوع، والمطلع بالكسر: هو الموضع الذي تطلع منه، ولا معنى للموضع الذي تطلع منه في هذا الموضع.\n\nآخر تفسير سورة القدر","2":1,"3":1,"4":1,"5":1},"98":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنْفَكِّينَ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ (١) رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً (٢) فِيهَا كُتُبٌ قَيِّمَةٌ (٣) وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلا مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ (٤) ﴾ .\n\nاختلف أهل التأويل في تأويل قوله: ﴿لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنْفَكِّينَ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ﴾ فقال بعضهم: معنى ذلك: لم يكن هؤلاء الكفار من أهل التوراة والإنجيل، والمشركون من عَبدة الأوثان ﴿مُنْفَكِّينَ﴾ يقول: منتهين حتى يأتيهم هذا القرآن.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد في قول الله: ﴿مُنْفَكِّينَ﴾ قال: لم يكونوا ليَنتهوا حتى يتبين لهم الحق.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله ﴿مُنْفَكِّينَ﴾ قال: منتهين عما هم فيه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿مُنْفَكِّينَ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ﴾ أي هذا القرآن.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قول الله: ﴿وَالْمُشْرِكِينَ مُنْفَكِّينَ﴾ قال: لم يكونوا منتهين حتى يأتيهم؛ ذلك المنفكّ.\n\nوقال آخرون: بل معنى ذلك أن أهل الكتاب وهم المشركون، لم يكونوا تاركين صفة محمد في كتابهم، حتى بُعث، فلما بُعث تفرّقوا فيه.\n\nوأولى الأقوال في ذلك بالصحة أن يقال: معنى ذلك: لم يكن الذين كفروا من أهل الكتاب والمشركين مفترقين في أمر محمد، حتى تأتيهم البيِّنة، وهي إرسال الله إياه رسولا إلى خلقه، رسول من الله. وقوله. ﴿مُنْفَكِّينَ﴾ في هذا الموضع عندي من انفكاك الشيئين أحدهما من الآخر، ولذلك صَلُح بغير خبر، ولو كان بمعنى ما زال، احتاج إلى خبر يكون تماما له، واستؤنف قوله ﴿رَسُولٌ مِنَ اللَّهِ﴾ هي نكرة على البيِّنة، وهي معرفة، كما قيل: ﴿ذُو الْعَرْشِ الْمَجِيدُ فَعَّالٌ﴾ فقال: حتى يأتيهم بيان أمر محمد أنه رسول الله، ببعثة الله إياه إليهم، ثم ترجم عن البيِّنة، فقال: تلك البينة\n\n﴿رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً﴾ يقول: يقرأ صحفا مطهرة من الباطل\n\n﴿فِيهَا كُتُبٌ قَيِّمَةٌ﴾ يقول: في الصحف المطهرة كتب من الله قيمة عادلة مستقيمة، ليس فيها خطأ، لأنها من عند الله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً﴾ يذكر القرآن بأحسن الذكر، ويثني عليه بأحسن الثناء.\n\n* *\n\nوقوله: ﴿وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلا مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ﴾\n\nيقول: وما تفرّق اليهود والنصارى في أمر محمد ﷺ، فكذّبوا به، إلا من بعد ما جاءتهم البينة، يعني: من بعد ما جاءت هؤلاء اليهود والنصارى البينة، يعني: أن بيان أمر محمد أنه رسول بإرسال الله إياه إلى خلقه، يقول: فلما بعثه الله تفرّقوا فيه، فكذّب به بعضهم، وآمن بعضهم، وقد كانوا قبل أن يُبعث غير مفترقين فيه أنه نبيّ.","2":1,"3":1,"4":1,"5":"القول في تأويل قوله تعالى: ﴿وَمَا أُمِرُوا إِلا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ (٥) ﴾\n\n.\n\nيقول تعالى ذكره: وما أمر الله هؤلاء اليهود والنصارى الذين هم أهل الكتاب إلا أن يعبدوا الله مخلصين له الدين؛ يقول: مفردين له الطاعة، لا يخلطون طاعتهم ربهم بشرك، فأشركت اليهود بربها بقولهم إن عُزَيرا ابن الله، والنصارى بقولهم في المسيح مثل ذلك، وجحودهم نبوة محمد ﷺ.\n\n* *\n\nوقوله: ﴿حُنَفَاءَ﴾\n\nقد مضى بياننا في معنى الحنيفية قبل بشواهده المُغنية عن إعادتها، غير أنا نذكر بعض ما لم نذكر قبل من الأخبار في ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ﴾ يقول: حجاجا مسلمين غير مشركين، يقول: ويقيموا الصلاة ويؤتوا الزكاة، ويحجوا وذلك دين القيمة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَمَا أُمِرُوا إِلا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ﴾ والحنيفية: الختان، وتحريم الأمهات والبنات والأخوات والعمات والخالات والمناسك.\n\n* *\n\nوقوله: ﴿وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ﴾\n\nيقول: وليقيموا الصلاة، وليؤتوا الزكاة.\n\n* *\n\nوقوله: ﴿وَذَلِكَ دِينُ الْقَيِّمَةِ﴾\n\nيعني أن هذا الذي ذكر أنه أمر به هؤلاء الذين كفروا من أهل الكتاب والمشركين، هو الدين القيمة، ويعني بالقيِّمة: المستقيمة العادلة، وأضيف الدين إلى القيِّمة، والدين هو القَيِّم، وهو من نعته لاختلاف لفظيهما. وهي في قراءة عبد الله فيما أرى فيما ذُكر لنا: ﴿وَذَلِكَ دِينُ الْقَيِّمَةِ﴾ وأُنِّثت القيمة، لأنها جعلت صفة للملة، كأنه قيل: وذلك الملة القيِّمة، دون اليهودية والنصرانية.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله ﴿وَذَلِكَ دِينُ الْقَيِّمَةِ﴾ هو الدين الذي بعث الله به رسوله، وشرع لنفسه، ورضي به.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿كُتُبٌ قَيِّمَةٌ﴾ ﴿وَذَلِكَ دِينُ الْقَيِّمَةِ﴾ قال: هو واحد؛ قيِّمة: مستقيمة معتدلة.","6":"القول في تأويل قوله تعالى: ﴿إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا أُولَئِكَ هُمْ شَرُّ الْبَرِيَّةِ (٦) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ (٧) ﴾ .\n\nيقول تعالى ذكره: إن الذين كفروا بالله ورسوله محمد ﷺ، فجحدوا نبوّته، من اليهود والنصارى والمشركين جميعهم ﴿فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا﴾ يقول: ماكثين لابثين فيها ﴿أَبَدًا﴾ لا يخرجون منها، ولا يموتون فيها ﴿أُولَئِكَ هُمْ شَرُّ الْبَرِيَّةِ﴾ يقول جل ثناؤه: هؤلاء الذين كفروا من أهل الكتاب والمشركين، هم شرّ من برأه الله وخلقه، والعرب لا تهمز البرية، وبترك الهمز فيها قرأتها قراء الأمصار، غير شيء يُذكر عن نافع بن أبي نعيم، فإنه حكى بعضهم عنه أنه كان يهمزها، وذهب بها إلى قول الله: ﴿مِنْ قَبْلِ أَنْ نَبْرَأَهَا﴾ [الحديد: ٢٢] وأنها فعيلة من ذلك. وأما الذين لم يهمزوها، فإن لتركهم الهمز في ذلك وجهين: أحدهما أن يكونوا تركوا الهمز فيها، كما تركوه من الملك، وهو مفعل من ألك أو لأك، ومِن يرى، وترى، ونرى، وهو يفعل من رأيت. والآخر: أن يكونوا وجَّهوها إلى أنها فعيلة من البري وهو التراب. حكي عن العرب سماعا: بفيك البري، يعني به: التراب.\n\n* *\n\nوقوله: ﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾\n\nيقول تعالى ذكره: إن الذين آمنوا بالله ورسوله محمد، وعبدوا الله مخلصين له الدين حنفاء، وأقاموا الصلاة، وآتوا الزكاة، وأطاعوا الله فيما أمر ونهى ﴿أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾ يقول: من فعل ذلك من الناس فهم خير البرية. وقد: حدثنا ابن حميد، قال: ثنا عيسى بن فرقد، عن أبي الجارود، عن محمد بن عليّ ﴿أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾ فقال النبي ﷺ: \"أنْتَ يا عَلي وَشِيعَتُكَ\".","7":6,"8":"القول في تأويل قوله تعالى جل جلاله وتقدست أسماؤه: ﴿جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الأنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ (٨) ﴾ .\n\nيقول تعالى ذكره: ثواب هؤلاء الذين آمنوا وعملوا الصالحات عند ربهم يوم القيامة ﴿جَنَّاتِ عَدْنٍ﴾ يعني بساتين إقامَة لا ظعن فيها، تجري من تحت أشجارها الأنهار ﴿خَالِدِينَ فِيهَا أَبَدًا﴾ يقول: ماكثين فيها أبدًا، لا يخرجون عنها، ولا يموتون فيها\n\n﴿رَضِيَ اللَّهُ عَنْهُمْ﴾ بما أطاعوه في الدنيا، وعملوا لخلاصهم من عقابه في ذلك\n\n﴿وَرَضُوا عَنْهُ﴾ بما أعطاهم من الثواب يومئذ، على طاعتهم ربهم في الدنيا، وجزاهم عليها من الكرامة.\n\n* *\n\nوقوله: ﴿ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ﴾\n\nيقول تعالى ذكره: هذا الخير الذي وصفته، ووعدته الذين آمنوا وعملوا الصالحات يوم القيامة، لمن خشي ربه؛ يقول: لمن خاف الله في الدنيا في سرّه وعلانيته، فاتقاه بأداء فرائضه، واجتناب معاصيه، وبالله التوفيق.\n\nآخر تفسير سورة لم يكن"},"99":{"1":"القول في تأويل قوله تعالى: ﴿إِذَا زُلْزِلَتِ الأرْضُ زِلْزَالَهَا (١) وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا (٢) وَقَالَ الإنْسَانُ مَا لَهَا (٣) يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا (٤) بِأَنَّ رَبَّكَ أَوْحَى لَهَا (٥) يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِيُرَوْا أَعْمَالَهُمْ (٦) فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ (٧) وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ (٨) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿إِذَا زُلْزِلَتِ الأرْضُ﴾ لقيام الساعة ﴿زِلْزَالَهَا﴾ فرُجَّت رجًّا؛ والزلزال: مصدر إذا كسرت الزاي، وإذا فتحت كان اسما؛ وأضيف الزلزال إلى الأرض وهو صفتها، كما يقال: لأكرمنك كرامتك، بمعنى: لأكرمنك كرامة. وحسن ذلك في زلزالها، لموافقتها رءوس الآيات التي بعدها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن يمان، عن أشعث، عن جعفر، عن سعيد، قال: ﴿زُلْزِلَتِ الأرْضُ﴾ على عهد عبد الله، فقال لها عبد الله: مالك، أما إنها لو تكلَّمت قامت الساعة.\n\n* *\n\nوقوله: ﴿وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا﴾\n\nيقول: وأخرجت الأرض ما في بطنها من الموتى أحياء، والميت في بطن الأرض ثقل لها، وهو فوق ظهرها حيا ثقل عليها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سنان القزّاز، قال: ثنا أبو عاصم، عن شبيب، عن عكرِمة، عن ابن عباس ﴿وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا﴾ قال: الموتى.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، ﴿وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا﴾ قال: يعني الموتى.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعا، عن ابن أبى نجيح، عن مجاهد ﴿وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا﴾ من في القبور.\n\n* *\n\nوقوله: ﴿وَقَالَ الإنْسَانُ مَا لَهَا﴾\n\nيقول تعالى ذكره: وقال الناس إذا زلزلت الأرض لقيام الساعة: ما للأرض وما قصتها ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾ .\n\nكان ابن عباس يقول في ذلك ما:-\n\n⁕ حدثني ابن سنان القزّاز، قال: ثنا أبو عاصم، عن شبيب، عن عكرِمة، عن ابن عباس، ﴿وَقَالَ الإنْسَانُ مَا لَهَا﴾ قال الكافر: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾\n\nيقول: يومئذ تحدث الأرض أخبارها، وتحديثها أخبارها، على القول الذي ذكرناه عن عبد الله بن مسعود، أن تتكلم فتقول: إن الله أمرني بهذا، وأوحى إليّ به، وأذن لي فيه.\n\nوأما سعيد بن جبير، فإنه كان يقول في ذلك ما:-\n\n⁕ حدثنا به أبو كُرَيب، قال: ثنا وكيع، عن إسماعيل بن عبد الملك، قال: سمعت سعيد بن جبير يقرأ في المغرب مرة: ﴿يَوْمَئِذٍ تُنَبِّئُ أَخْبَارَها﴾ ومرة: ﴿تُحَدِّثُ أَخْبَارَهَا﴾ .\n\nفكأن معنى تحدّث كان عند سعيد: تُنَبِّئُ، وتنبيئها أخبَارَهَا: إخراجها أثقالها من بطنها إلى ظهرها. وهذا القول قول عندي صحيح المعنى، وتأويل الكلام على هذا المعنى: يومئذ تبين الأرض أخبارها بالزلزلة والرجة، وإخراج الموتى من بطونها إلى ظهورها، بوحي الله إليها، وإذنه لها بذلك، وذلك معنى قوله: ﴿بِأَنَّ رَبَّكَ أَوْحَى لَهَا﴾ .\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن. قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَأَخْرَجَتِ الأرْضُ أَثْقَالَهَا وَقَالَ الإنْسَانُ مَا لَهَا يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا بِأَنَّ رَبَّكَ أَوْحَى لَهَا﴾ قال: أمرها، فألقَت ما فيها وتخلَّت.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿بِأَنَّ رَبَّكَ أَوْحَى لَهَا﴾ قال: أمرها.\n\nوقد ذُكر عن عبد الله أنه كان يقرأ ذلك: ﴿يَوْمَئِذٍ تُنْبِّئُ أَخْبَارَها﴾ وقيل: معنى ذلك أن الأرض تحدث أخبارها من كان على ظهرها من أهل الطاعة والمعاصي، وما عملوا عليها من خير أو شرّ.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾ قال: ما عمل عليها من خير أو شرّ، ﴿بِأَنَّ رَبَّكَ أَوْحَى لَهَا﴾ قال: أعلمها ذلك.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾ قال: ما كان فيها، وعلى ظهرها من أعمال العباد.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا﴾ قال: تخبر الناس بما عملوا عليها.\n\nوقيل: عنى بقوله: ﴿أَوْحَى لَهَا﴾ : أوحى إليها.\n\nذكر من قال ذلك:\n\n⁕ حدثني ابن سنان القزّاز، قال: ثنا أبو عاصم، عن شبيب، عن عكرِمة، عن ابن عباس ﴿أَوْحَى لَهَا﴾ قال: أوحى إليها.\n\n* *\n\nوقوله: ﴿يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا﴾\n\nقيل: إن معنى هذه الكلمة التأخير بعد ﴿لِيُرَوْا أَعْمَالَهُمْ﴾ قالوا: ووجه الكلام: يومئذ تحدث أخبارها بأن ربك أوحى لها، لِيُرَوْا أعمالهم، يومئذ يصدر الناس أشتاتا. قالوا: ولكنه اعترض بين ذلك بهذه الكلمة.\n\nومعنى قوله: ﴿يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا﴾ عن موقف الحساب فِرَقا متفرقين، فآخذ ذات اليمين إلى الجنة، وآخذ ذات الشمال إلى النار.\n\n* *\n\nوقوله: ﴿لِيُرَوْا أَعْمَالَهُمْ﴾\n\nيقول: يومئذ يصدر الناس أشتاتا متفرّقين، عن اليمين وعن الشمال، ليروا أعمالهم، فيرى المحسن في الدنيا، المطيع لله عمله وما أعد الله له يومئذ من الكرامة، على طاعته إياه كانت في الدنيا، ويرى المسيء العاصي لله عمله وجزاء عمله وما أعدّ الله له من الهوان والخزي في جهنم على معصيته إياه كانت في الدنيا، وكفره به.\n\n* *\n\nوقوله: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ﴾\n\nيقول: فمن عمل في الدنيا وزن ذرة من خير، يرى ثوابه هنالك ﴿وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ يقول: ومن كان عمل في الدنيا وزن ذرة من شر يرى جزاءه هنالك، وقيل: ومن يعمل والخبر عنها في الآخرة، لفهم السامع معنى ذلك، لما قد تقدم من الدليل قبل، على أن معناه: فمن عمل؛ ذلك دلالة قوله: ﴿يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِيُرَوْا أَعْمَالَهُمْ﴾ على ذلك. ولكن لما كان مفهوما معنى الكلام عند السامعين، وكان في قوله: ﴿يَعْمَلْ﴾ حث لأهل الدنيا على العمل بطاعة الله، والزجر عن معاصيه، مع الذي ذكرت من دلالة الكلام قبل ذلك، على أن ذلك مراد به الخبر عن ماضي فعله، وما لهم على ذلك، أخرج الخبر على وجه الخبر عن مستقبل الفعل.\n\nوبنحو الذي قلنا من أن جميعهم يرون أعمالهم، قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني على، قال: ثنا بو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، في قوله: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ﴾ قال: ليس مؤمن ولا كافر عمِل خيرا ولا شرا في الدنيا، إلا آتاه الله إياه. فأما المؤمن فيريه حسناته وسيئاته، فيغفر الله له سيئاته. وأما الكافر فيردّ حسناته، ويعذّبه بسيئاته. وقيل في ذلك غير هذا القول، فقال بعضهم: أما المؤمن، فيعجل له عقوبة سيئاته في الدنيا، ويؤخِّر له ثواب حسناته، والكافر يعجِّل له ثواب حسناته، ويؤخر له عقوبة سيئاته.\n\nذكر من قال ذلك:\n\n⁕ حدثني موسى بن عبد الرحمن المسروقي، قال: ثنا محمد بن بشر، قال: حدثنيه محمد بن مسلم الطائفي، عن عمرو بن قتادة، قال: سمعت محمد بن كعب القرظي، وهو يفسِّر هذه الآية: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ﴾ قال: من يعمل مثقال ذرَّة من خير من كافر ير ثوابه في الدنيا في نفسه وأهله وماله وولده، حتى يخرج من الدنيا، وليس له عنده خير ﴿وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ من مؤمن ير عقوبته في الدنيا في نفسه وأهله وماله وولده، حتى يخرج من الدنيا وليس عنده شيء.\n\n⁕ حدثني محمود بن خِداش، قال: ثنا محمد بن يزيد الواسطي، قال: ثنا محمد بن مسلم الطائفي، عن عمرو بن دينار، قال: سألت محمد بن كعب القرظي، عن هذه الآية: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ قال: من يعمل مثقال ذرَّة من خير من كافر، ير ثوابها في نفسه وأهله وماله، حتى يخرج من الدنيا وليس له خير؛ ومن يعمل مثقال ذرة من شر من مؤمن، ير عقوبتها في نفسه وأهله وماله، حتى يخرج وليس له شر.\n\n⁕ حدثني أبو الخطاب الحساني، قال: ثنا الهيثم بن الربيع، قال: ثنا سماك بن عطية، عن أيوب، عن أبي قِلابة، عن أنس، قال: كان أبو بكر رضى الله عنه يأكل مع النبي ﷺ، فنزلت هذه الآية: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ فرفع أبو بكر يده من الطعام، وقال: يا رسول الله إني أُجزَى بما عملت من مثقال ذرة من شرّ، فقال: \"يا أبا بَكر، ما رأيْتَ في الدنْيا ممَّا تكره فمثَاقيلُ ذَرّ الشَّرّ، وَيَدَّخِرُ لَكَ اللهُ مثَاقِيلَ الخير حتى تُوَفَّاه يَوْمَ الْقِيامَةِ\".\n\n⁕ حدثنا ابن بشار، قال: ثنا أيوب، قال: وجدنا في كتاب أبي قِلابة، عن أبي إدريس: أن أبا بكر كان يأكل مع النبيّ ﷺ، فأنزلت هذه الآية: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ فرفع أبو بكر يده من الطعام، وقال: إني لراء ما عملت، قال: لا أعلمه إلا قال: ما عملت من خير وشرّ، فقال النبيّ ﷺ: \"إنَّ ما تَرَى مِمَّا تَكْرَهُ فَهُوَ مثَاقِيلُ ذَرّ شَر كَثِيرٍ، وَيَدَّخِرُ اللهُ لَكَ مَثَاقِيلَ ذَرّ الخَيْرِ حتى تُعْطَاهُ يَوْمَ الْقِيَامَةِ\" وتصديق ذلك في كتاب الله: ﴿وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ﴾ .\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا أيوب، قال: قرأت في كتاب أبي قلابة قال: نزلت ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ وأبو بكر يأكل مع النبي ﷺ، فأمسك وقال: يا رسول الله، إني لراء ما عملت من خير وشر؟ فقال: \" أرأيْتَ ما رأيْتَ مِمَّا تَكْرَهُ، فَهُوَ مِنْ مثَاقِيلِ ذَرّ الشَّرِ، وَيَدَّخِرُ مثَاقِيلَ ذَرّ الخَيْرِ، حتى تُعْطَوْهُ يَوْمَ الْقِيامَةِ\" قال أبو إدريس: فأرى مصداقها في كتاب الله، قال: ﴿وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ﴾ .\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن عُليَة، عن داود، عن الشعبي، قال: قالت عائشة: يا رسول الله، إن عبد الله بن جُدْعان كان يصل الرحم، ويفعل ويفعل، هل ذاك نافعه؟ قال: \"لا إنه لم يقل يوما: \" رب اغفر لي خطيئتي يوم الدين \".\n\n⁕ حدثنا ابن وكيع، قال: ثنا حفص، عن داود، عن الشعبي، عن مسروق، عن عائشة، قالت: قلت: يا رسول الله، ابن جدعان كان في الجاهلية يصل الرحم، ويُطعم المسكين، فهل ذاك نافعه؟ قال: \"لا يَنْفَعُهُ، إنَّهُ لَمْ يَقُلْ يوما: \" رب اغفر لي خطيئتي يوم الدين \"\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عدي، عن داود، عن عامر الشعبي، أن عائشة أم المؤمنين قالت: يا رسول الله، إن عبد الله بن جدعان، كان يصل الرحم، ويَقْرِي الضيف، ويفكّ العاني، فهل ذلك نافعه شيئا؟ قال: \"لا إنَّهُ لَمْ يقل يوما: \" رب اغفر لي خطيئتي يوم الدين\".\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن أبي عديّ، عن داود، عن عامر، عن علقمة، أن سلمة بن يزيد الجعفي، قال: يا رسول الله، إن أمنا هلكت في الجاهلية، كانت تصل الرحم، وتَقْرِي الضيف، وتفعل وتفعل، فهل ذلك نافعها شيئا؟ قال: \"لا\".\n\n⁕ حدثنا ابن المثنى، قال: ثنا الحجاج بن المنهال، قال: ثنا المعتمر بن سليمان، قال: ثنا داود، عن الشعبيّ، عن علقمة بن قيس، عن سلمة بن يزيد الجعفي، قال: ذهبت أنا وأخي إلى رسول الله ﷺ، فقلت: يا رسول الله، إن أمنا كانت في الجاهلية تقري الضيف، وتصل الرحم، هل ينفعها عملها ذلك شيئا؟ قال: \"لا\".\n\n⁕ حدثني محمد بن إبراهيم بن صدران وابن عبد الأعلى، قالا ثنا المعتمر بن سليمان، قال: ثنا داود بن أبي هند، عن الشعبي، عن علقمة، عن سلمة بن يزيد، عن النبي ﷺ، بنحوه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، عن محمد بن كعب، أنه قال: أما المؤمن فيرى حسناته في الآخرة، وأما الكافر فيرى حسناته في الدنيا.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا أبو عاصم، قال: ثنا أبو نعامة، قال: ثنا عبد العزيز بن بشير الضبي جدّه سلمان بن عامر أن سلمان بن عامر جاء رسول الله ﷺ، فقال: إنّ أبي كان يصل الرحم، ويفي بالذمة، ويُكرم الضيف، قال: \"ماتَ قَبْلَ الإسْلامِ\"؟ قال: نعم، قال: \"لَنْ يَنْفَعَهُ ذَلكَ\"، فولى، فقال رسول الله ﷺ: \"عَليَّ بالشَّيْخِ\"، فجاءَ، فَقالَ رسولُ الله ﷺ: \"إنَّها لَنْ تَنْفَعَهُ، وَلَكِنَّهَا تَكُونُ فِي عَقِبِهِ، فَلَنْ تُخْزَوْا أبَدًا، وَلَنْ تَذِلُّوا أَبَدًا، وَلَنْ تَفْتَقِرُوا أَبدًا\".\n\n⁕ حدثنا ابن المثنى وابن بشار، قالا ثنا أبو داود، قال: ثنا عمران، عن قتادة، عن أنس، أن رسول الله ﷺ قال: \"إِنَّ اللهَ لا يَظْلِمُ المُؤْمِنُ حَسَنَةً يُثابُ عَلَيْها الرّزْقَ فِي الدنْيا، ويُجْزى بِها فِي الآخِرَةِ؛ وأمَّا الكافِرُ فَيُعْطِيهِ بِها فِي الدنْيا، فإذَا كَانَ يَوْمُ الْقِيامَةِ، لَمْ تَكُنْ لَهُ حَسَنةٌ\".\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن علية، قال: ثنا ليث، قال: ثني المعلى، عن محمد بن كعب الْقُرَظي، قال: قال رسول الله ﷺ: \"ما أحْسَنَ مِنْ مُحْسِنٍ، مُؤْمِنٍ أوْ كَافِرٍ إلا وَقَعَ ثَوَابُهُ عَلى الله فِي عاجِل دُنْيَاهُ، أَوْ آجِلِ آخِرَتِهِ\".\n\n⁕ حدثني يونس بن عبد الأعلى، قال: أخبرنا ابن وهب، قال: أخبرني يحيى بن عبد الله، عن أبي عبد الرحمن الحُبَليِّ، عن عبد الله بن عمرو بن العاص أنه قال: أنزلت: ﴿إِذَا زُلْزِلَتِ الأرْضُ زِلْزَالَهَا﴾ وأبو بكر الصدّيق قاعد، فبكى حين أنزلت، فقال له رسول الله ﷺ: \"ما يُبْكِيكَ يا أبا بَكْرٍ؟ \" قال: يُبكيني هذه السورة، فقال له رسول الله ﷺ: \"لَوْلا أنَّكُمْ تُخْطِئونَ وَتُذْنِبُونَ فَيَغْفِرُ اللهُ لَكُمْ لَخَلَقَ اللهُ أُمَّةً يُخْطِئُونَ وَيُذْنِبُونَ فَيَغْفرُ لَهُمْ\".\n\nفهذه الأخبار عن رسول الله ﷺ تُنبئ عن أن المؤمن إنما يرى عقوبة سيئاته في الدنيا، وثواب حسناته في الآخرة، وأن الكافر يرى ثواب حسناته في الدنيا، وعقوبة سيئاته في الآخرة، وأن الكافر لا ينفعه في الآخرة ما سلف له من إحسان في الدنيا مع كُفره.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن عليّ، عن الأعمش، عن إبراهيم التيمي، قال: أدركت سبعين من أصحاب عبد الله، أصغرهم الحارث بن سويد، فسمعته يقرأ: ﴿إِذَا زُلْزِلَتِ الأرْضُ زِلْزَالَهَا﴾ حتى بلغ إلى: ﴿وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ قال: إن هذا إحصاء شديد.\n\nوقيل: إن الذَّرَّة دُودة حمراء ليس لها وزن.\n\nذكر من قال ذلك:\n\n⁕ حدثني إسحاق بن وهب العلاف ومحمد بن سنان القزّاز، قالا ثنا أبو عاصم، قال: ثنا شبيب بن بشر، عن عكرمة، عن ابن عباس، في قوله: ﴿مِثْقَالَ ذَرَّةٍ﴾ قال ابن سنان في حديثه: مثقال ذرّة حمراء. وقال ابن وهب في حديثه: نملة حمراء. قال إسحاق، قال يزيد بن هارون: وزعموا أن هذه الدودة الحمراء ليس لها وزن.\n\nآخر تفسير سورة إذا زلزلت الأرض.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1},"100":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿وَالْعَادِيَاتِ ضَبْحًا (١) فَالْمُورِيَاتِ قَدْحًا (٢) فَالْمُغِيرَاتِ صُبْحًا (٣) فَأَثَرْنَ بِهِ نَقْعًا (٤) فَوَسَطْنَ بِهِ جَمْعًا (٥) إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ (٦) وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ (٧) وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ (٨) أَفَلا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ (٩) ﴾ .","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1,"10":"القول في تأويل قوله تعالى: ﴿وَحُصِّلَ مَا فِي الصُّدُورِ (١٠) إِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ (١١) ﴾\n\n.\n\nاختلف أهل التأويل في تأويل قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ فقال بعضهم: عُني بالعاديات ضبحا: الخيل التي تعدو، وهي تحمحم.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: الخيل، وزعم غير ابن عباس أنها الإبل.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال ابن عباس: هو في القتال.\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة في قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال الخيل.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: أخبرنا أبو رجاء، قال: سُئل عكرِمة، عن قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: ألم تر إلى الفرس إذا جرى كيف يضبح؟ حدثني إبراهيم بن سعيد الجوهري، قال: ثنا سفيان، عن ابن جُرَيج، عن عطاء، قال: ليس شيء من الدوابّ يضبح غير الكلب والفرس.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله الله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: الخيل تضبح.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الخيل، عدت حتى ضبحت.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، في قوله ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الخيل تعدو حتى تضبح.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سعيد، عن قتادة مثل حديث بشر، عن يزيد؛ حدثنا أبو كُرَيب، قال: ثنا وكيع، قال: ثنا سعيد، قال: سمعت سالما يقرأ: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الخيل عدت ضبحا.\n\n⁕ قال: ثنا وكيع، عن واصل، عن عطاء ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: الخيل.\n\n⁕ قال: ثنا وكيع، عن سفيان بن عيينة، عن عمرو، عن عطاء، عن ابن عباس، قال: ما ضبحت دابة قط إلا كلب أو فرس.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الخيل.\n\n⁕ حدثني سعيد بن الربيع الرازي. قال: ثنا سفيان بن عيينة، عن عَمْرو، عن عطاء، عن ابن عباس، قال: هي الخيل.\n\nوقال آخرون: هي الإبل.\n\nذكر من قال ذلك:\n\n⁕ حدثني أبو السائب. قال: ثنا أبو معاوية، عن الأعمش، عن إبراهيم، عن عبد الله ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الإبل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن الأعمش، عن إبراهيم، عن عبد الله، مثله.\n\n⁕ حدثني عيسى بن عثمان الرملي، قال: ثني عمي يحيى بن عيسى الرملي، عن الأعمش، عن إبراهيم، عن عبد الله، مثله.\n\n⁕ حدثنا ابن حُميد، قال: ثنا جرير، عن مُغيرة، عن إبراهيم، عن عبد الله ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: هي الإبل إذا ضبحت تنفست.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرنا أبو صخر، عن أبي معاوية البجلي، عن سعيد بن جبير، عن ابن عباس حدثه قال: بينما أنا في الحجر جالس، أتاني رجل يسأل عن ﴿الْعَادِيَاتِ ضَبْحًا﴾ فقلت له: الخيل حين تغير في سبيل الله، ثم تأوي إلى الليل، فيصنعون طعامهم، ويورون نارهم. فانفتل عني، فذهب إلى علي بن أبي طالب رضى الله عنه وهو تحت سقاية زمزم، فسأله عن ﴿الْعَادِيَاتِ ضَبْحًا﴾ فقال: سألتَ عنها أحدًا قبلي؟ قال: نعم، سألت عنها ابن عباس، فقال: الخيل حين تغير في سبيل الله، قال: اذهب فادعه لي؛ فلما وقفت على رأسه قال: تفتي الناس بما لا علم لك به، والله لكانت أول غزوة في الإسلام لبدر، وما كان معنا إلا فرسان: فرس للزبير، وفرس للمقداد فكيف تكون العاديات ضبحا! إنما العاديات ضبحا من عرفة إلى مزدلفة إلى منى ؛ قال ابن عباس: فنزعت عن قولي، ورجعت إلى الذي قال علي رضي الله عنه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن إبراهيم ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: الإبل.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: قال ابن مسعود: هو في الحج.\n\n⁕ حدثنا سعيد بن الربيع الرازي، قال: ثنا سفيان، عن عمرو بن دينار، عن عبيد بن عمير، قال: هي الإبل، يعني ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن إبراهيم ﴿وَالْعَادِيَاتِ ضَبْحًا﴾ قال: قال ابن مسعود: هي الإبل.\n\nوأولى القولين في ذلك عندي بالصواب: قول من قال: عني بالعاديات: الخيل، وذلك أن الإبل لا تضبح، وإنما تضبح الخيل، وقد أخبر الله تعالى أنها تعدو ضبحا، والضبح: هو ما قد ذكرنا قبل. وبما قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا إبراهيم بن سعيد الجوهري، قال: ثنا أبو معاوية، عن إسماعيل بن أبي خالد، عن أبي صالح، قال: قال علي رضى الله عنه: الضبح من الخيل: الحمحمة، ومن الإبل: النفس.\n\n⁕ قال: ثنا سفيان، عن ابن جُرَيج، عن عطاء، قال: سمعت ابن عباس يصف الضبح: أحْ أحْ.\n\n* *\n\nوقوله: ﴿فَالْمُورِيَاتِ قَدْحًا﴾\n\nاختلف أهل التأويل، في ذلك، فقال بعضهم: هي الخيل توري النار بحوافرها.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن علية، قال: ثنا أبو رجاء، قال: سئل عكرِمة، عن قوله: ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: أورت وقدحت.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: هي الخيل؛ وقال الكلبي: تقدح بحوافرها حتى يخرج منها النار.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل، عن عطاء ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: أورت النار بحوافرها.\n\n⁕ حدثت عن الحسين، قال: سمعت أبا معاذ، يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَالْمُورِيَاتِ قَدْحًا﴾ توري الحجارة بحوافرها.\n\nوقال آخرون: بل معنى ذلك أن الخيل هجن الحرب بين أصحابهن وركبانهن.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: هجن الحرب بينهم وبين عدوهم.\n\n⁕ حدثنا ابن حميد، فال: ثنا مهران، عن سعيد، عن قتادة ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: هجن الحرب بينهم وبين عدوهم.\n\nوقال آخرون: بل عني بذلك: الذين يورون النار بعد انصرافهم من الحرب.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني أبو صخر، عن أبي معاوية البجلي، عن سعيد بن جبير، عن ابن عباس، قال: سألني علي بن أبي طالب رضى الله عنه، عن ﴿وَالْعَادِيَاتِ ضَبْحًا فَالْمُورِيَاتِ قَدْحًا﴾ فقلت له: الخيل تغير في سبيل الله، ثم تأوي إلى الليل، فيصنعون طعامهم ويورون نارهم.\n\nوقال آخرون: بل معنى ذلك: مكر الرجال.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبى، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: المكر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح. عن مجاهد، في قول الله: ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: مكر الرجال.\n\nوقال آخرون: هي الألسنة\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسن بن عرفة، قال: ثنا يونس بن محمد، قال: ثنا حماد بن سلمة، عن سماك بن حرب، عن عكرِمة قال: يقال في هذه الآية ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: هي الألسنة.\n\nوقال آخرون: هي الإبل حين تسير تنسف بمناسمها الحصى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن إبراهيم، عن عبد الله: ﴿فَالْمُورِيَاتِ قَدْحًا﴾ قال: إذا نسفت الحصى بمناسمها، فضرب الحصى بعضه بعضا، فيخرج منه النار.\n\nوأولى الأقوال في ذلك بالصواب: أن يقال: إن الله تعالى ذكره أقسم بالموريات التي توري النيران قدحا؛ فالخيل توري بحوافرها، والناس يورونها بالزند، واللسان - مثلا - يوري بالمنطق، والرجال يورون بالمكر - مثلا -، وكذلك الخيل تهيج الحرب بين أهلها: إذا التقت في الحرب، ولم يضع الله دلالة على أن المراد من ذلك بعض دون بعض فكل ما أورت النار قدحا، فداخلة فيما أقسم به، لعموم ذلك بالظاهر.\n\n* *\n\nوقوله: ﴿فَالْمُغِيرَاتِ صُبْحًا﴾\n\nاختلف أهل التأويل في تأويل ذلك، فقال بعضهم: معنى ذلك: فالمغيرات صبحا على عدوّها علانية.\n\nذكر من قال ذلك:\n\n٢٩٢٥٩ - حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني أبو صخر، عن أبي معاوية البجلي، عن سعيد بن جبير، عن ابن عباس، قال: سألني رجل عن المغيرات صبحا، فقال: الخيل تغير في سبيل الله.\n\n٢٩٢٦٠ - حدثني يعقوب بن إبراهيم، قال: ثنا ابن علية، قال: أخبرنا أبو رجاء، قال: سألت عكرِمة، عن قوله ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: أغارت على العدو صبحا.\n\n٢٩٢٦١ - حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: هي الخيل.\n\n٢٩٢٦٢ - حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: هي الخيل.\n\n٢٩٢٦٣ - حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: أغار القوم بعد ما أصبحوا على عدوهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ثور، عن معمر، عن قتادة ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: أغارت حين أصبحوا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ قال: أغار القوم حين أصبحوا.\n\nوقال آخرون: عني بذلك الإبل حين تدفع بركبانها من \"جمع\" يوم النحر إلى \"منى\".\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن إبراهيم، عن عبد الله ﴿فَالْمُغِيرَاتِ صُبْحًا﴾ حين يفيضون من جمع.\n\nوأولى الأقوال في ذلك بالصواب: أن يقال: إن الله جل ثناؤه أقسم بالمغيرات صبحا، ولم يخصص^ من ذلك مغيرة دون مغيرة، فكل مغيرة صبحا، فداخلة فيما أقسم به ؛ وقد كان زيد بن أسلم يذكر تفسير هذه الأحرف ويأباها، ويقول: إنما هو قسم أقسم الله به.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَالْعَادِيَاتِ ضَبْحًا فَالْمُورِيَاتِ قَدْحًا﴾ قال: هذا قسم أقسم الله به. وفي قوله: ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: كل هذا قسم، قال: ولم يكن أبي ينظر فيه إذا سئل عنه، ولا يذكره، يريد به القسم.\n\n* *\n\nوقوله ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾\n\nيقول تعالى ذكره: فرفعن بالوادي غبارا؛ والنقع: الغبار، ويقال: إنه التراب. والهاء في قوله \"به\" كناية اسم الموضع، وكنى عنه، ولم يجر له ذكر، لأنه معلوم أن الغبار لا يثار إلا من موضع، فاستغنى بفهم السامعين بمعناه من ذكره.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: الخيل.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل، عن عطاء وابن زيد، قال: النقع: الغبار.\n\n⁕ حدثنا هناد، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: هي أثارت الغبار، يعني الخيل.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: ثنا أبو رجاء، قال: سئل عكرِمة، عن قوله ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: أثارت التراب بحوافرها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران عن سعيد، عن قتادة ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: أثرن بحوافرها نقع التراب.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، مثله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: أثرن به غبارا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني أبو صخر، عن أبي معاوية البجلي، عن سعيد بن جبير، عن ابن عباس قال: قال لي علي: إنما العاديات ضبحا من عرفة إلى المزدلفة، ومن المزدلفة إلى منى ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ : الأرض حين تطؤها بأخفافها وحوافرها.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن إبراهيم، عن عبد الله ﴿فَأَثَرْنَ بِهِ نَقْعًا﴾ قال: إذا سرن يثرن التراب.\n\n* *\n\nوقوله: ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾\n\nيقول تعالى ذكره: فوسطن بركبانهن جمع القوم، يقال: وسطت القوم بالتخفيف، ووسطته بالتشديد، وتوسطته: بمعنى واحد.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، قال: ثنا أبو رجاء، قال: سئل عكرِمة، عن قوله: ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: جمع الكفار.\n\n⁕ حدثنا هناد بن السري، قال: ثنا أبو الأحوص، عن سماك، عن عكرِمة ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال جمع القوم.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: هو جمع القوم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن واصل، عن عطاء ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: جمع العدو.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: جمع هؤلاء وهؤلاء.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ فوسطن جمع القوم.\n\n⁕ حدثنا ابن حميد قال: ثنا مهران، عن سعيد، عن قتادة ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ فوسطن بالقوم جمع العدو.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ قال: وسطن جمع القوم.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ الجمع: الكتيبة.\n\nوقال آخرون: بل عني بذلك ﴿فَوَسَطْنَ بِهِ﴾ مزدلفة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن مغيرة، عن إبراهيم، عن عبد الله ﴿فَوَسَطْنَ بِهِ جَمْعًا﴾ يعني: مزدلفة.\n\n* *\n\nوقوله: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾\n\nيقول: إن الإنسان لكفور لنعم ربه. والأرض الكنود: التي لا تنبت شيئا، قال الأعشى:\n\nأحْدِثْ لَهَا تُحْدِثْ لِوَصْلِكَ إنَّها ... كُنُدٌ لوَصْلِ الزَّائِرِ المُعْتادِ\n\nوقيل: إنما سميت كندة: لقطعها أباها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عبيد الله بن يوسف الجبيري، قال: ثنا محمد بن كثير، قال: ثنا مسلم، عن مجاهد، عن ابن عباس، قوله: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لكفور.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لربه لكفور.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لكفور.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مهدي بن ميمون، عن شعيب بن الحبحاب، عن الحسن البصري: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: هو الكفور الذي يعد المصائب، وينسى نعم ربه.\n\n⁕ حدثنا وكيع، عن أبي جعفر، عن الربيع، قال: الكنود: الكفور.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، قال: قال الحسن: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ يقول: لوام لربه يعد المصائب\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿لَكَنُودٌ﴾ قال: لكفور.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لكفور.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة، مثله.\n\n⁕ حدثنا يحيى بن حبيب بن عربي، قال: ثنا خالد بن الحارث، قال: ثنا شعبة، عن سماك أنه قال: إنما سميت كندة: أنها قطعت أباها ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لكفور.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عبيد الله، عن إسرائيل، عن جعفر بن الزبير، عن القاسم، عن أبي أمامة قال: قال رسول الله ﷺ: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: \" لَكَفُورٌ، الَّذِي يَأْكُلُ وَحْدَهُ وَيَضْرِبُ عَبْدَهُ، وَيَمْنَعُ رِفْدَهُ \".\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: الكنود: الكفور، وقرأ: ﴿إِنَّ الإنْسَانَ لَكَفُورٌ﴾ .\n\n⁕ حدثنا الحسن بن علي بن عياش، قال: ثنا أبو المغيرة عبد القدوس، قال: ثنا حريز بن عثمان، قال: ثني حمزة بن هانيء، عن أبي أمامة أنه كان يقول: الكنود: الذي ينزل وحده، ويضرب عبده، ويمنع رفده.\n\n⁕ حدثني محمد بن إسماعيل الصوارى، قال: ثنا محمد بن سوار، قال: أخبرنا أبو اليقظان، عن سفيان عن هشام، عن الحسن، في قوله ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ قال: لوام لربه، يعد المصائب، وينسى النعم.\n\n* *\n\nوقوله: ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾\n\nيقول تعالى ذكره: إن الله على كنوده ربه لشهيد: يعني لشاهد.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ قال: يقول: إن الله على ذلك لشهيد.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ في بعض القراءات \"إن الله على ذلك لشهيد\".\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ يقول: وإن الله عليه شهيد.\n\n* *\n\nوقوله: ﴿وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾\n\nيقول تعالى ذكره: وإن الإنسان لحب المال لشديد.\n\nواختلف أهل العربية في وجه وصفه بالشدة لحب المال، فقال بعض البصريين: معنى ذلك: وإنه من أجل حب الخير لشديد: أي لبخيل؛ قال: يقال للبخيل: شديد ومتشدد. واستشهدوا لقوله ذلك ببيت طرفة بن العبد البكري:\n\nأرَى المَوْتَ يَعْتامُ النُّفُوسَ ويَصْطَفِي ... عَقِيلَةَ مالِ الباخِلِ المُتَشَددِ\n\nوقال آخرون: معناه: وإنه لحب الخير لقوي.\n\nوقال بعض نحويي الكوفة: كان موضع ﴿لِحُبِّ﴾ أن يكون بعد شديد، وأن يضاف شديد إليه، فيكون الكلام: وإنه لشديد حب الخير؛ فلما تقدم الحب في الكلام، قيل: شديد، وحذف من آخره، لما جرى ذكره في أوله ولرءوس الآيات، قال: ومثله في سورة إبراهيم: ﴿كَرَمَادٍ اشْتَدَّتْ بِهِ الرِّيحُ فِي يَوْمٍ عَاصِفٍ﴾ والعصوف لا يكون لليوم، إنما يكون للريح؛ فلما جرى ذكر الريح قبل اليوم طرحت من آخره، كأنه قال: في يوم عاصف الريح، والله أعلم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾ قال: الخير: الدنيا؛ وقرأ: ﴿إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ﴾ قال: فقلت له: ﴿إن ترك خيرا﴾ : المال؟ قال: نعم، وأي شيء هو إلا المال؟ قال: وعسى أن يكون حراما، ولكن الناس يعدونه خيرا، فسماه الله خيرا، لأن الناس يسمونه خيرا في الدنيا، وعسى أن يكون خبيثا، وسمي القتال في سبيل الله سوءا، وقرأ قول الله: ﴿فَانْقَلَبُوا بِنِعْمَةٍ مِنَ اللَّهِ وَفَضْلٍ لَمْ يَمْسَسْهُمْ سُوءٌ﴾ قال: لم يمسسهم قتال؛ قال: وليس هو عند الله بسوء، ولكن يسمونه سوءا.\n\nوتأويل الكلام: إن الإنسان لربه لكنود، وإنه لحب الخير لشديد، وإن الله على ذلك من أمره لشاهد. ولكن قوله: ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ قدم، ومعناه التأخير، فجعل معترضا بين قوله: ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾ ، وبين قوله: ﴿وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة ﴿إِنَّ الإنْسَانَ لِرَبِّهِ لَكَنُودٌ وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ قال: هذا في مقاديم الكلام، قال: يقول: إن الله لشهيد أن الإنسان لحب الخير لشديد.\n\n* *\n\nوقوله: ﴿أَفَلا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ﴾\n\nيقول: أفلا يعلم هذا الإنسان الذي هذه صفته، إذا أثير ما في القبور، وأخرج ما فيها من الموتى وبحث.\n\nوذكر أنها في مصحف عبد الله: \"إذا بحث ما في القبور\"، وكذلك تأول ذلك أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، في قوله: ﴿بُعْثِرَ مَا فِي الْقُبُورِ﴾ بحث. وللعرب في ﴿بُعْثِرَ﴾ لغتان: تقول: بعثر، وبحثر، ومعناهما واحد.\n\n* *\n\nوقوله: ﴿وَحُصِّلَ مَا فِي الصُّدُورِ﴾\n\nيقول: وميز وبين، فأبرز ما في صدور الناس من خير وشر.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، قوله: ﴿وَحُصِّلَ مَا فِي الصُّدُورِ﴾ يقول: أبرز.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَحُصِّلَ مَا فِي الصُّدُورِ﴾ يقول: ميز.\n\n* *\n\nوقوله: ﴿إِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ﴾\n\nيقول: إن ربهم بأعمالهم، وما أسرّوا في صدورهم، وأضمروه فيها، وما أعلنوه بجوارحهم منها، عليم لا يخفى عليه منها شيء، وهو مجازيهم على جميع ذلك يومئذ.\n\nآخر تفسير سورة: والعاديات","11":10},"101":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿الْقَارِعَةُ (١) مَا الْقَارِعَةُ (٢) وَمَا أَدْرَاكَ مَا الْقَارِعَةُ (٣) يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ (٤) وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ (٥) فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ (٦) فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ (٧) وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ (٨) فَأُمُّهُ هَاوِيَةٌ (٩) وَمَا أَدْرَاكَ مَا هِيَهْ (١٠) نَارٌ حَامِيَةٌ (١١) ﴾ .\n\nيقول تعالى ذكره: ﴿الْقَارِعَةُ﴾ : الساعة التي يقرع قلوب الناس هولُها، وعظيم ما ينزل بهم من البلاء عندها، وذلك صبيحة لا ليل بعدها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿الْقَارِعَةُ﴾ من أسماء يوم القيامة، عظَّمه الله وحذّره عباده.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قي قوله ﴿الْقَارِعَةُ مَا الْقَارِعَةُ﴾ قال: هي الساعة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، ثنا سعيد، عن قتادة، قوله: ﴿الْقَارِعَةُ مَا الْقَارِعَةُ﴾ قال: هي الساعة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، قال: سمعت أن القارعة والواقعة والحاقة: القيامة.\n\n* *\n\nوقوله: ﴿مَا الْقَارِعَةُ﴾\n\nيقول تعالى ذكره معظما شأن القيامة والساعة التي يقرع العباد هولها: أيّ شيء القارعة، يعني بذلك: أيّ شيء الساعة التي يقرع الخلق هولها: أي ما أعظمها وأفظعها وأهولها.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا الْقَارِعَةُ﴾\n\nيقول تعالى ذكره لنبيه محمد ﷺ: وما أشعرك يا محمد أيّ شيء القارعة.\n\n* *\n\nوقوله: ﴿يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ﴾\n\nيقول تعالى ذكره: القارعة يوم يكون الناس كالفراش، وهو الذي يتساقط في النار والسراج، ليس ببعوض ولا ذباب، ويعني بالمبثوث: المفرّق.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ﴾ هذا الفراش الذي رأيتم يتهافت في النار.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ﴾ قال: هذا شَبَه شبهه الله، وكان بعض أهل العربية يقول: معنى ذلك: كغوغاء الجراد، يركب بعضه بعضا، كذلك الناس يومئذ، يجول بعضهم في بعض.\n\n* *\n\nوقوله: ﴿وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ﴾\n\nيقول تعالى ذكره: ويوم تكون الجبال كالصوف المنفوش؛ والعِهْن: هو الألوان من الصوف.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، في قوله: ﴿وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ﴾ قال: الصوف المنفوش.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: هو الصوف. وذُكر أن الجبال تسير على الأرض وهي في صورة الجبال كالهباء.\n\n* *\n\nوقوله: ﴿فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ﴾\n\nيقول: فأما من ثقُلَت موازين حسناته، يعني بالموازين: الوزن، والعرب تقول: لك عندي درهم بميزان درهمك، ووزن درهمك، ويقولون: داري بميزان دارك ووزن دارك، يراد: حذاء دارك. قال الشاعر:\n\nقدْ كُنْتُ قَبْلَ لِقائِكُمْ ذَا مِرَّة ... عِندِي لِكُلِّ مُخاصِمٍ مِيزَانُهُ\n\nيعني بقوله: لكلّ مخاصم ميزانه: كلامه، وما ينقض عليه حجته. وكان مجاهد يقول: ليس ميزان، إنما هو مثل ضرب.\n\n⁕ حدثنا بذلك أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ﴾ يقول: في عيشة قد رضيها في الجنة.\n\nكما:-\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ﴾ يعني: في الجنة.\n\n* *\n\nوقوله: ﴿وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ فَأُمُّهُ هَاوِيَةٌ﴾\n\nيقول: وأما من خفّ وزن حسناته، فمأواه ومسكنه الهاوية التي يهوي فيها على رأسه في جهنم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ فَأُمُّهُ هَاوِيَةٌ﴾ وهي النار هي مأواهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَأُمُّهُ هَاوِيَةٌ﴾ قال: مصيره إلى النار، هي الهاوية. قال قتادة: هي كلمة عربية، كان الرجل إذا وقع في أمر شديد، قال: هوت أمه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الأشعث بن عبد الله الأعمى، قال: إذا مات المؤمن ذُهب بروحه إلى أرواح المؤمنين، فيقولون: روّحوا أخاكم، فإنه كان في غمّ الدنيا؛ قال: ويسألونه ما فعل فلان؟ فيقول: مات، أو ما جاءكم؟ فيقولون: ذهبوا به إلى أمِّه الهاوية.\n\n⁕ حدثني إسماعيل بن سيف العجلي، قال: ثنا عليّ بن مُسْهِر، قال: ثنا إسماعيل، عن أبي صالح، في قوله ﴿فَأُمُّهُ هَاوِيَةٌ﴾ قال: يهوون في النار على رءوسهم.\n\n⁕ حدثنا ابن سيف، قال: ثنا محمد بن سَوَّار، عن سعيد، عن قتادة ﴿فَأُمُّهُ هَاوِيَةٌ﴾ قال: يهوي في النار على رأسه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَأُمُّهُ هَاوِيَةٌ﴾ قال: الهاوية: النار، هي أمُّه ومأواه التي يرجع إليها، ويأوي إليها، وقرأ: ﴿وَمَأْوَاهُمُ النَّارُ﴾ .\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿فَأُمُّهُ هَاوِيَةٌ﴾ وهو مثلها، وإنما جعل النار أمَّه، لأنها صارت مأواه، كما تؤوي المرأة ابنها، فجعلها إذ لم يكن له مأوى غيرها، بمنزلة أمّ له.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا هِيَهْ﴾\n\nيقول جلّ ثناؤه لنبيه محمد ﷺ: وما أشعرك يا محمد ما الهاوية، ثم بَيَّن ما هي، فقال: ﴿نَارٌ حَامِيَةٌ﴾ ، يعني بالحامية: التي قد حميت من الوقود عليها.","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1,"10":1,"11":1},"102":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿أَلْهَاكُمُ التَّكَاثُرُ (١) حَتَّى زُرْتُمُ الْمَقَابِرَ (٢) كَلا سَوْفَ تَعْلَمُونَ (٣) ثُمَّ كَلا سَوْفَ تَعْلَمُونَ (٤) كَلا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ (٥) لَتَرَوُنَّ الْجَحِيمَ (٦) ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ (٧) ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ (٨) ﴾ .\n\nيقول تعالى ذكره: ألهاكم أيها الناس المباهاة بكثرة المال والعدد عن طاعة ربكم، وعما ينجيكم من سخطه عليكم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿أَلْهَاكُمُ التَّكَاثُرُ حَتَّى زُرْتُمُ الْمَقَابِرَ﴾ قال: كانوا يقولون: نحن أكثر من بني فلان، ونحن أعدّ من بني فلان، وهم كلّ يوم يتساقطون إلى آخرهم، والله ما زالوا كذلك حتى صاروا من أهل القبور كلهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ قالوا: نحن أكثر من بني فلان، وبنو فلان أكثر من بني فلان، ألهاهم ذلك حتى ماتوا ضلالا.\n\nورُوي عن النبيّ ﷺ كلام يدلّ على أن معناه التكاثر بالمال.\n\nذكر الخبر بذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن هشام الدستوائي، عن قتادة، عن مطرِّف بن عبد الله بن الشِّخِّير، عن أبيه أنه انتهى إلى النبيّ ﷺ، وهو يقرأ: ﴿أَلْهَاكُمُ التَّكَاثُرُ حَتَّى زُرْتُمُ الْمَقَابِرَ﴾ قال: \"ابن آدم، ليس لك من مال إلا ما أكلت فأفنيت، أو لبِست فأبليت، أو تصدّقت فأمضيت\".\n\n⁕ حدثنا محمد بن خلف العسقلاني، قال: ثنا آدم، قال: ثنا حماد بن سلمة، عن ثابت البناني، عن أنس بن مالك، عن أُبيّ بن كعب، قال: كنا نرى أن هذا الحديث من القرآن: \"لو أن لابن آدم واديين من مال، لتمنى واديا ثالثا، ولا يملأ جوف ابن آدم إلا التراب، ثم يتوب الله على من تاب\" حتى نزلت هذه السورة: ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ إلى آخرها. وقوله ﷺ بعقب قراءته \"ألهاكم\" ليس لك من مالك إلا كذا وكذا، ينبئ أن معنى ذلك عنده: ألهاكم التكاثر: المال.\n\n* *\n\nوقوله: ﴿حَتَّى زُرْتُمُ الْمَقَابِرَ﴾\n\nيعني: حتى صرتم إلى المقابر فدفنتم فيها؛ وفي هذا دليل على صحة القول بعذاب القبر، لأن الله تعالى ذكره، أخبر عن هؤلاء القوم الذين ألهاهم التكاثر، أنهم سيعلمون ما يلقون إذا هم زاروا القبور وعيدا منه لهم وتهدّدا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن عطية، عن قيس، عن حجاج، عن المنهال، عن زِرّ، عن عليّ، قال: كنا نشكّ في عذاب القبر، حتى نزلت هذه الآية: ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ ... إلى: ﴿كَلا سَوْفَ تَعْلَمُونَ﴾ في عذاب القبر.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام بن سلم، عن عنبسة، عن ابن أبي ليلى، عن المنهال، عن زِرّ، عن عليّ، قال: نزلت ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ في عذاب القبر.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن عمرو، عن الحجاج، عن المنهال بن عمرو، عن زِرّ، عن عليّ، قال: ما زلنا نشكّ في عذاب القبر، حتى نزلت: ﴿أَلْهَاكُمُ التَّكَاثُرُ حَتَّى زُرْتُمُ الْمَقَابِرَ﴾ .\n\n* *\n\nوقوله: ﴿كَلا سَوْفَ تَعْلَمُونَ﴾\n\nيعني تعالى ذكره بقوله: كلا ما هكذا ينبغي أن تفعلوا، أن يُلْهِيَكُم التكاثر.\n\n* *\n\nوقوله: ﴿سَوْفَ تَعْلَمُونَ﴾\n\nيقول جلّ ثناؤه: سوف تعلمون إذا زرتم المقابر، أيها الذين ألهاهم التكاثر، غبّ فعلكم، واشتغالكم بالتكاثر في الدنيا عن طاعة الله ربكم.\n\n* *\n\nوقوله: ﴿ثُمَّ كَلا سَوْفَ تَعْلَمُونَ﴾\n\nيقول: ثم ما هكذا ينبغي أن تفعلوا أن يلهيكم التكاثر بالأموال، وكثرة العدد، سوف تعلمون إذا زرتم المقابر، ما تلقون إذا أنتم زرتموها، من مكروه اشتغالكم عن طاعة ربكم بالتكاثر. وكرّر قوله: ﴿كَلا سَوْفَ تَعْلَمُونَ﴾ مرتين، لأن العرب إذا أرادت التغليظ في التخويف والتهديد كرّروا الكلمة مرتين.\n\nورُوي عن الضحاك في ذلك ما:-\n\n⁕ حدثنا به ابن حميد، قال: ثنا مهران، عن أبي سنان، عن ثابت، عن الضحاك ﴿كَلا سَوْفَ تَعْلَمُونَ﴾ قال: الكفار ﴿ثُمَّ كَلا سَوْفَ تَعْلَمُونَ﴾ قال: المؤمنون. وكذلك كان يقرأها.\n\n* *\n\nوقوله: ﴿كَلا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ﴾\n\nيقول تعالى ذكره: ما هكذا ينبغي أن تفعلوا، أن يلهيكم التكاثر أيها الناس، لو تعلمون أيها الناس علما يقينا، أن الله باعثكم يوم القيامة من بعد مماتكم من قبوركم ما ألهاكم التكاثر عن طاعة الله ربكم، ولسارعتم إلى عبادته، والانتهاء إلى أمره ونهيه، ورفض الدنيا إشفاقا على أنفسكم من عقوبته.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿كَلا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ﴾ كنا نحدَّث أن علم اليقين: أن يعلم أنَّ الله باعثه بعد الموت.\n\n* *\n\nوقوله: ﴿لَتَرَوُنَّ الْجَحِيمَ﴾\n\nاختلفت القراء في قراءة ذلك؛ فقرأته قراء الأمصار: ﴿لَتَرَوُنَّ الْجَحِيمَ﴾ بفتح التاء من ﴿لَتَرَوُنَّ﴾ في الحرفين كليهما، وقرأ ذلك الكسائي بضم التاء من الأولى، وفتحها من الثانية.\n\nوالصواب عندنا في ذلك الفتح فيهما كليهما، لإجماع الحجة عليه. وإذا كان ذلك كذلك، فتأويل الكلام: لترونّ أيها المشركون جهنم يوم القيامة، ثم لترونها عيانا لا تغيبون عنها.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس قوله: ﴿ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ﴾ يعني: أهل الشرك.\n\n* *\n\nوقوله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾\n\nيقول: ثم ليسألنكم الله عزّ وجلّ عن النعيم الذي كنتم فيه في الدنيا: ماذا عملتم فيه، من أين وصلتم إليه، وفيم أصبتموه، وماذا عملتم به.\n\nواختلف أهل التأويل في ذلك النعيم ما هو؟ فقال بعضهم: هو الأمن والصحة.\n\nذكر من قال ذلك:\n\n⁕ حدثني عباد بن يعقوب، قال. ثنا محمد بن سليمان، عن ابن أبي ليلى، عن الشعبيّ، عن ابن مسعود، في قوله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: الأمن والصحة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا حفص، عن ابن أبي ليلى، عن الشعبيّ، عن عبد الله، مثله.\n\n⁕ حدثني علي بن سعيد الكنديّ، قال: ثنا محمد بن مروان، عن ليث، عن مجاهد ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: الأمن والصحة.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم. قال: ثنا سفيان، قال: بلغني في قوله: ﴿لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: الأمن والصحة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن إسماعيل بن عياش، عن عبد العزيز بن عبد الله، قال: سمعت الشعبيّ يقول: النعيم المسئول عنه يوم القيامة: الأمن والصحة.\n\n⁕ قال: ثنا مهران، عن خالد الزيات، عن ابن أبي ليلى، عن عامر الشعبيّ، عن ابن مسعود، مثله.\n\n⁕ قال: ثنا مهران، عن سفيان ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: الأمن والصحة.\n\nوقال آخرون: بل معنى ذلك: ثم لَيُسْئَلُنّ يومئذ عما أنعم الله به عليهم مما وهب لهم من السمع والبصر وصحة البدن.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: النعيم: صحة الأبدان والأسماع والأبصار، قال: يسأل الله العباد فيم استعملوها، وهو أعلم بذلك منهم، وهو قوله: ﴿إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولا﴾ .\n\n⁕ حدثني إسماعيل بن موسى الفَزاريُّ، قال: أخبرنا عمر بن شاكر، عن الحسن قال: كان يقول في قوله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: السمع والبصر، وصحة البدن.\n\nوقال آخرون: هو العافية.\n\nذكر من قال ذلك:\n\n⁕ حدثني عباد بن يعقوب، قال: ثنا نوح بن درّاج، عن سعد بن طريف، عن أبي جعفر ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: العافية.\n\nوقال آخرون: بل عُنِي بذلك: بعض ما يطعمه الإنسان، أو يشربه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال ثنا عبد الرحمن، قال: ثنا سفيان، عن بكير بن عتيق، قال: رأيت سعيد بن جُبَير أُبِيَ بشربة عسل، فشربها، وقال: هذا النعيم الذي تُسألون عنه.\n\n⁕ حدثني عليّ بن سهل الرملي، قال: ثنا الحسن بن بلال، قال: ثنا حماد بن سلمة، عن عَمَّار  بن أبي عمار، قال: سمعت جابر بن عبد الله يقول: أتانا النبيّ ﷺ وأبو بكر وعمرُ رضي الله عنهما، فأطعمناهم رطبا، وسقيناهم ماء، فقال رسول الله ﷺ: \"هَذَا مِنَ النَّعِيمِ الَّذِي تُسألون عَنْهُ\".\n\n⁕ حدثنا جابر بن الكرديّ، قال: ثنا يزيد بن هارون، قال: ثنا حماد بن سلمة، عن عمار بن أبي عمار، قال: سمعت جابر بن عبد الله يقول: أتانا النبيّ ﷺ، فذكر نحوه.\n\n⁕ حدثني الحسن بن عليّ الصُدائي، قال: ثنا الوليد بن القاسم، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، قال: بينما أبو بكر وعمر رضى الله عنهما جالسان، إذ جاء النبيّ ﷺ، فقال: \"ما أجْلَسَكُما ها هُنا؟ \" قالا الجوع، قال: \"وَالَّذِي بَعَثَنِي بالْحَقّ ما أخْرَجَنِي غَيرُهُ\"، فانطلقوا حتى أتوا بيت رجل من الأنصار، فاستقبلتهم المرأة، فقال لها النبيّ ﷺ: \"أيْنَ فُلانُ؟ \" فقالت: ذهب يستعذب لنا ماء، فجاء صاحبهم يحمل قربته، فقال: مرحبا، ما زار العباد شيء أفضل من شيء زارني اليوم، فعلق قربته بكَرَب نخلة، وانطلق فجاءهم بعِذْق، فقال النبي ﷺ: \"ألا كُنْتَ اجْتَنَيْتَ؟ \" فقال: أحببت أن تكونوا الذين تختارون على أعينكم، ثم أخذ الشفرة، فقال النبيّ ﷺ: \"إيَّاكَ والْحَلُوبَ\"، فذبح لهم يومئذ، فأكلوا، فقال النبيّ ﷺ: \"لَتُسْأَلُنَّ عَنْ هَذَا يَوْمَ القِيامَةِ، أخْرَجَكُمْ مِنْ بُيُوتِكُمُ الجُوعُ، فَلَمْ تَرْجِعُوا حتى أصَبْتُمْ هَذَا، فَهَذَا مِنَ النَّعِيمِ\".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا يحيى بن أبي بكير، قال ثنا شيبان بن عبد الرحمن، عن عبد الملك بن عُمَير، عن أبي سَلَمة، عن أبي هريرة، قال: قال النبيّ ﷺ لأبي بكر وعمر: \"انْطَلِقُوا بِنا إلى أبي الهَيْثَم بنِ التَّيَّهانِ الأنْصَارِيّ\"، فانطلق بهم إلى ظلّ حديقته، فبسط لهم بساطا، ثم انطلق إلى نخلة، فجاء بِقِنْوٍ، فقال رسول الله ﷺ: \"فَهَلا تَنَقَّيْتَ لَنا مِنْ رُطَبِهِ؟ \" فقال: أردت أن تَخَيَّرُوا من رطبه وبُسره، فأكلوا وشربول من الماء؛ فلما فرغ رسول الله ﷺ، قال: \"هَذَا وَالَّذِي نَفْسِي بِيدهِ مِنَ النَّعِيمِ، الَّذِي أنْتُمْ فِيهِ مَسْئُولُونَ عَنْهُ يَوْمَ القِيامَةِ، هَذَا الظِّلُّ البارِدُ، والرُّطَبُ البارِدُ، عَلَيْهِ الماءُ البارِدُ\".\n\n⁕ حدثني صالح بن مسمار المروزي، قال: ثنا آدم بن أبي إياس، قال: ثنا شيبان، قال: ثنا عبد الملك بن عمير، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة، عن رسول الله ﷺ بنحوه، إلا أنه قال في حديثه: \"ظِلٌّ بارِدٌ، ورُطَبٌ بارِدٌ، وَماءٌ بارِدٌ\".\n\n⁕ حدثنا عليّ بن عيسى البزاز، قال: ثنا سعيد بن سليمان، عن حشرج بن نباتة، قال: ثنا أبو بصيرة عن أبي عسيب، مولى رسول الله ﷺ، قال: مرّ النبيّ ﷺ حتى دخل حائطا لبعض الأنصار، فقال لصاحب الحائط: \"أطْعِمْنا بُسْرًا\"، فجاء بعذق فوضعه، فأكل رسول الله ﷺ وأصحابه، ثم دعا بماء بارد فشرب، فقال: \"لَتُسْأَلُنَّ عَنْ هَذَا يَوْمَ القِيامَةِ\"، فأخذ عمر العذق، فضرب به الأرض حتى تناثر البسر، ثم قال: يا رسول الله، إنا لمسئولون عن هذا؟ قال: \"نَعَمْ، إلا مِنْ كِسْرَةٍ يُسَدُّ بِها جَوْعَةٌ، أوْ حُجْرٌ يُدْخَلُ فِيه مِنَ الحَرِّ والقَرِّ\".\n\n⁕ حدثني سعيد بن عمرو السكونيّ، قال: ثنا بقية، عن حشرج بن نباتة، قال: حدثني أبو بصيرة، عن أبي عسيب مولى رسول الله ﷺ، قال: مرّ بي النبيّ ﷺ، فدعاني وخرجت ومعه أبو بكر وعمر رضى الله عنهما، فدخل حائطا لبعض الأنصار، فأُتِيَ بِبُسْرِ عِذْق منه، فوُضِع بين يديه، فأكل هو وأصحابه، ثم دعا بما بارد، فشرب، ثم قال: \"لَتُسْأَلُنَّ عَنْ هَذَا يَوْمَ القِيامَةِ\"، فقال عمر: عن هذا يوم القيامة؟ فقال: \"نَعَمْ، إلا مِنْ ثَلاثَةٍ: خِرْقَةٍ كَفَّ بِها عَوْرَتَهُ، أو كِسْرَةٍ سَدُّ بِها جَوْعَتَةُ، أوْ جُحْرٍ يَدْخُلُ فِيهِ مِنَ الحَرِّ والقَرّ\".\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلية، عن الجريريّ، عن أبي بصيرة، قال: أكل رسول الله ﷺ وناس من أصحابه أكلة من خبز شعير لم يُنْخَل، بلحم سمين، ثم شربوا من جدول، فقال: \"هذا كله من النعيم الذي تُسْأَلُونَ عنه يوم القيامة\".\n\n⁕ حدثنا مجاهد بن موسى، قال: ثنا يزيد، قال: ثنا محمد بن عمرو، عن صفوان بن سليم، عن محمد بن محمود بن لبيد، قال: \"لما نزلت ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ فقرأها حتى بلغ: ﴿لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قالوا: يا رسول الله، عن أيّ النعيم نسأل، وإنما هو الأسودان: الماء، والتمر، وسيوفنا على عواتقنا، والعدوّ حاضر! قال: \"إن ذلكَ سَيَكُونُ\".\n\n⁕ حدثني يعقوب بن إبراهيم والحسين بن عليّ الصدائي، قالا ثنا شبابة بن سوّار، قال: ثني عبد الله بن العلاء أبو رَزِين الشامي، قال: ثنا الضحاك بن عَرْزَم، قال: سمعت أبا هريرة يقول: قال: رسول الله ﷺ: \"إنَّ أولَ ما يُسْأَلُ عَنْهُ العَبْدُ يَوْمَ الْقِيَامَةِ مِنَ النَّعِيمِ أنْ يُقَالَ لَهُ: ألَم نُصِحَّ لَك جِسْمَكَ، وَتُروَ مِنَ الماءِ البارِدِ\"؟.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا ليث، عن مجاهد، قال: قال أبو معمر عبد الله بن سخبرة: ما أصبح أحد بالكوفة إلا ناعماً، إن أهونهم عيشا الذي يأكل خبز البرّ، ويشرب ماء الفرات، ويستظلّ من الظلّ، وذلك من النعيم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن إسماعيل بن عياش، عن عبد الرحمن بن الحارث التميميّ، عن ثابت البناني، عن النبيّ ﷺ قال: \"النَّعِيم: المَسْئُولُ عَنْهُ يَوْمَ القِيامَةِ: كِسْرَةٌ تُقَوّيهِ، وَماءٌ يُرْوِيهِ، وَثَوْبٌ يُوَارِيهِ\".\n\n⁕ قال: ثنا مهران، عن إسماعيل بن عياش، عن بشر بن عبد الله بن بشار، قال: سمعت بعض أهل يمن يقول: سمعت أبا أُمامة يقول: النعيم المسئول عنه يوم القيامة: خبز البرّ، والماء العذب.\n\n⁕ قال: ثنا مهران، عن سفيان، عن بكير بن عتيق العامري، قال: أُتِيَ سعيد بن جُبير بشَربة عسل، فقال: أما إن هذا النعيم الذي نسأل عنه يوم القيامة ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن بكير بن عتيق، عن سعيد بن جُبير، أنه أتي بشربة عسل، فقال: هذا من النعيم الذي تُسألون عنه.\n\nوقال آخرون: ذلك كلّ ما التذّه الإنسان في الدنيا من شيء.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: عن كل شيء من لذّة الدنيا.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ إن الله عزّ وجل سائل كلّ عبد عما استودعه من نِعَمه وحقه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ قال: إن الله تعالى ذكره سائل كلّ ذي نعمة فيما أنعم عليه.\n\nوكان الحسن وقتادة يقولان: ثلاث لا يُسأَل عنهنّ ابن آدم، وما خلاهنّ فيه المسألة والحساب إلا ما شاء الله: كسوة يواري بها سوْأته، وكسرة يشدّ بها صلبه، وبيت يظله.\n\nوالصواب من القول في ذلك: أن يقال: إن الله أخبر أنه سائل هؤلاء القوم عن النعيم، ولم يخصص في خبره أنه سائلهم عن نوع من النعيم دون نوع، بل عمّ بالخبر في ذلك عن الجميع، فهو سائلهم كما قال عن جميع النعيم، لا عن بعض دون بعض.\n\nآخر تفسير سورة ألهاكم","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1},"103":{"1":"القول في تأويل قوله جل جلاله وتقدست أسماؤه: ﴿وَالْعَصْرِ (١) إِنَّ الإنْسَانَ لَفِي خُسْرٍ (٢) إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ (٣) ﴾ .\n\nاختلف أهل التأويل في تأويل قوله: ﴿وَالْعَصْرِ﴾ فقال بعضهم: هو قسم أقسم ربنا تعالى ذكره بالدهر، فقال: العصر: هو الدهر.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿وَالْعَصْرِ﴾ قال: العصر: ساعة من ساعات النهار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَالْعَصْرِ﴾ قال: هو العشيّ.\n\nوالصواب من القول في ذلك: أن يقال: إن ربنا أقسم بالعصر ﴿وَالْعَصْرِ﴾ اسم للدهر، وهو العشيّ والليل والنهار، ولم يخصص مما شمله هذا الاسم معنى دون معنى، فكلّ ما لزِمه هذا الاسم، فداخل فيما أقسم به جلّ ثناؤه.\n\n* *\n\nوقوله: ﴿إِنَّ الإنْسَانَ لَفِي خُسْرٍ﴾\n\nيقول: إن ابن آدم لفي هلَكة ونقصان.\n\nوكان عليّ رضى الله عنه يقرأ ذلك: ﴿إنَّ الإنْسانَ لَفِي خُسْر وإنه فيه إلى آخر الدهر﴾ .\n\n⁕ حدثني ابن عبد الأعلى بن واصل، قال: ثنا أبو نعيم الفضل بن دكين، قال: أخبرنا إسرائيل، عن أبي إسحاق، عن عمرو ذي مرّ، قال: سمعت عليا رضى الله عنه يقرأ هذا الحرف ﴿وَالْعَصْرِ وَنَوَائِب الدَّهْرِ، إنَ الإنْسانَ لَفِي خُسْرٍ، وإنه فيه إلى آخر الدهر﴾ .\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة (إِنَّ الإنْسَانَ لَفِي خُسْر) ففي بعض القراءات ﴿وإنه فيه إلى آخر الدهر﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن أبي إسحاق، عن عمرو ذي مرّ، أن عليا رضى الله عنه قرأها ﴿وَالْعَصْرِ وَنَوَائِب الدَّهْرِ، إنَّ الإنْسانَ لَفِي خُسْر﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿إِنَّ الإنْسَانَ لَفِي خُسْرٍ﴾ إلا من آمن ﴿إِلا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ يقول: إلا الذين صدّقوا الله ووحَّدوه، وأقرّوا له بالوحدانية والطاعة، وعملوا الصالحات، وأدّوا ما لزمهم من فرائضه، واجتنبوا ما نهاهم عنه من معاصيه، واستثنى الذين آمنوا من الإنسان، لأن الإنسان بمعنى الجمع، لا بمعنى الواحد.\n\n* *\n\nوقوله: ﴿وَتَوَاصَوْا بِالْحَقِّ﴾\n\nيقول: وأوصى بعضهم بعضا بلزوم العمل بما أنزل الله في كتابه، من أمره، واجتناب ما نهى عنه فيه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَتَوَاصَوْا بِالْحَقِّ﴾ والحق: كتاب الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَتَوَاصَوْا بِالْحَقِّ﴾ قال: الحقّ كتاب الله.\n\n⁕ حدثني عمران بن بكار الكلاعي، قال: ثنا خطاب بن عثمان، قال: ثنا عبد الرحمن بن سنان أبو روح السكوني، حمصيّ لقيته بإرمينية، قال: سمعت الحسن يقول في ﴿وَتَوَاصَوْا بِالْحَقِّ﴾ قال: الحقّ: كتاب الله.\n\n* *\n\nوقوله: ﴿وَتَوَاصَوْا بِالصَّبْرِ﴾\n\nيقول: وأوصى بعضهم بعضا بالصبر على العمل بطاعة الله.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَتَوَاصَوْا بِالصَّبْرِ﴾ قال: الصبر: طاعة الله.\n\n⁕ حدثني عمران بن بكار الكُلاعي، قال: ثنا خطاب بن عثمان، قال: ثنا عبد الرحمن بن سنان أبو روح، قال: سمعت الحسن يقول في قوله: ﴿وَتَوَاصَوْا بِالصَّبْرِ﴾ قال: الصبر: طاعة الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَتَوَاصَوْا بِالصَّبْرِ﴾ قال: الصبر: طاعة الله.\n\nآخر تفسير سورة والعصر","2":1,"3":1},"104":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ (١) الَّذِي جَمَعَ مَالا وَعَدَّدَهُ (٢) يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ (٣) كَلا لَيُنْبَذَنَّ فِي الْحُطَمَةِ (٤) وَمَا أَدْرَاكَ مَا الْحُطَمَةُ (٥) نَارُ اللَّهِ الْمُوقَدَةُ (٦) الَّتِي تَطَّلِعُ عَلَى الأفْئِدَةِ (٧) إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ (٨) فِي عَمَدٍ مُمَدَّدَةٍ (٩) ﴾ .\n\nيعني تعالى ذكره بقوله:\n\n﴿وَيْلٌ لِكُلِّ هُمَزَةٍ﴾ الوادي يسيل من صديد أهل النار وقيحهم، ﴿لِكُلِّ هُمَزَةٍ﴾ : يقول: لكل مغتاب للناس، يغتابهم ويبغضهم، كما قال زياد الأعجم:\n\nتُدلِي بوُدِّي إذا لاقَيْتَنِي كَذِبا ... وَإنْ أُغَيَّبْ فأنتَ الهامِزُ اللُّمَزَهْ\n\nويعني باللمزة: الذي يعيب الناس، ويطعن فيهم.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا مسروق بن أبان، قال: ثنا وكيع، عن رجل لم يسمه، عن أبي الجوزاء، قال: قلت لابن عباس: من هؤلاء هم الذين بدأهم الله بالويل؟ قال: هم المشاءون بالنميمة، المفرقون بين الأحبة، الباغون أكبر العيب.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن أبيه، عن رجل من أهل البصرة، عن أبي الجوزاء، قال: قلت: لابن عباس: من هؤلاء الذين ندبهم الله إلى الويل؟ ثم ذكر نحو حديث مسروق بن أبان.\n\n⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: الهمزة يأكل لحوم الناس، واللمزة: الطعان.\n\nوقد رُوي عن مجاهد خلاف هذا القول، وهو ما:-\n\n⁕ حدثنا به أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ﴾ قال: الهمزة: الطعان، واللمزة: الذي يأكل لحوم الناس.\n\n⁕ حدثنا مسروق بن أبان الحطاب، قال: ثنا وكيع، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\nورُوي عنه أيضا خلاف هذين القولين، وهو ما:-\n\n⁕ حدثنا به ابن بشار، قال: ثنا يحيى، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: أحدهما الذي يأكل لحوم الناس، والآخر الطعان. وهذا يدلّ على أن الذي حدث بهذا الحديث قد كان أشكل عليه تأويل الكلمتين، فلذلك اختلف نقل الرواة عنه فيما رووا على ما ذكرت.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ أما الهمزة: فأكل لحوم الناس، وأما اللمزة: فالطعان عليهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد بن أبي عروبة، عن قتادة، قال: الهمزة: آكل لحوم الناس: واللمزة: الطعان عليهم.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن خثيم، عن سعيد بن جبير، عن ابن عباس: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: ويل لكلّ طعان مغتاب.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية، قال: الهمزة: يهمزه في وجهه، واللمزة: من خلفه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: يهمزه ويلمزه بلسانه وعينه، ويأكل لحوم الناس، ويطعن عليهم.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، قال: الهمزة باليد، واللمزة باللسان.\n\nوقال آخرون في ذلك ما:-\n\n⁕ حدثني به يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: الهمزة: الذي يهمز الناس بيده، ويضربهم بلسانه، واللمزة: الذي يلمزهم بلسانه ويعيبهم.\n\nواختلف في المعنى بقوله: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ﴾ فقال بعضهم: عني بذلك: رجل من أهل الشرك بعينه، فقال بعض من قال هذا القول: هو جميل بن عامر الجُمَحِيّ.\n\nوقال آخرون منهم: هو الأخنس بن شريق.\n\nذكر من قال: عُنِي به مشرك بعينه.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: مشرك كان يلمز الناس ويهمزهم.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن رجل من أهل الرقة قال: نزلت في جميل بن عامر الجمحي.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، في قوله ﴿هُمَزَةٍ لُمَزَةٍ﴾ قال: ليست بخاصة لأحد، نزلت في جميع بني عامر؛ قال ورقاء: زعم الرقاشي.\n\nوقال بعض أهل العربية: هذا من نوع ما تذكر العرب اسم الشيء العام، وهي تقصد به الواحد، كما يقال في الكلام، إذا قال رجل لأحد: لا أزورك أبدا: كل من لم يزرني، فلست بزائره، وقائل ذلك يقصد جواب صاحبه القائل له: لا أزورك أبدا.\n\nوقال آخرون: بل معنيّ به، كل من كانت هذه الصفة صفته، ولم يقصد به قصد آخر.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو. قال: ثنا أبو عاصم، قاله: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ قال: ليست بخاصة لأحد.\n\nوالصواب من القول في ذلك: أن يقال: إن الله عمّ بالقول كلّ همزة لمزة، كلّ من كان بالصفة التي وصف هذا الموصوف بها، سبيله سبيله كائنا من كان من الناس.\n\n* *\n\nوقوله: ﴿الَّذِي جَمَعَ مَالا وَعَدَّدَهُ﴾\n\nيقول: الذي جمع مالا وأحصى عدده، ولم ينفقه في سبيل الله، ولم يؤد حق الله فيه، ولكنه جمعه فأوعاه وحفظه.\n\nواختلفت القرّاء في قراءة ذلك، فقرأه من قرّاء أهل المدينة أبو جعفر، وعامة قرّاء الكوفة سوى عاصم: \"جَمَّعَ\" بالتشديد، وقرأ ذلك عامة قرّاء المدينة والحجاز، سوى أبي جعفر وعامة قرّاء البصرة، ومن الكوفة عاصم، \"جَمَعَ\" بالتخفيف، وكلهم مجمعون على تشديد الدال من ﴿وَعَدَّدَهُ﴾ على الوجه الذي ذكرت من تأويله. وقد ذكر عن بعض المتقدمين بإسناد غير ثابت، أنه قرأه: \"جَمَعَ مَالا وَعَدَدَهُ\" تخفيف الدال، بمعنى: جمع مالا وجمع عشيرته وعدده. هذه قراءة لا أستجيز القراءة بها، بخلافها قراءة الأمصار، وخروجها عما عليه الحجة مجمعة في ذلك.\n\nوأما قوله: ﴿جَمَعَ مَالا﴾ فإن التشديد والتخفيف فيهما صوابان، لأنهما قراءتان معروفتان في قراءة الأمصار، متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب.\n\n* *\n\nوقوله: ﴿يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ﴾\n\nيقول: يحسب أن ماله الذي جمعه وأحصاه، وبخل بإنفاقه، مخلده في الدنيا، فمزيل عنه الموت. وقيل: أخلده، والمعنى: يخلده، كما يقال للرجل الذي يأتي الأمر الذي يكون سببا لهلاكه: عطب والله فلان، هلك والله فلان، بمعنى: أنه يعطب من فعله ذلك، ولما يهلك بعد ولم يعطب؛ وكالرجل يأتي الموبقة من الذنوب: دخل والله فلان النار.\n\n* *\n\nوقوله: ﴿كَلا﴾\n\nيقول تعالى ذكره: ما ذلك كما ظنّ، ليس ماله مخلِّده،\n\nثم أخبر جلّ ثناؤه أنه هالك ومعذب على أفعاله ومعاصيه، التي كان يأتيها في الدنيا، فقال جل ثناؤه: ﴿لَيُنْبَذَنَّ فِي الْحُطَمَةِ﴾ يقول: ليُقذفنّ يوم القيامة في الحطمة، والحطمة: اسم من أسماء النار، كما قيل لها: جهنم وسقر ولظى، وأحسبها سميت بذلك لحطمها كلّ ما ألقي فيها، كما يقال للرجل الأكول: الحطمة. ذكر عن الحسن البصري أنه كان يقرأ ذلك: \"لَيُنْبَذَانِّ فِي الحُطَمَةِ\" يعني: هذا الهمزة اللمزة وماله، فثنَّاه لذلك.\n\n* *\n\nوقوله: ﴿وَمَا أَدْرَاكَ مَا الْحُطَمَةُ﴾\n\nيقول: وأيّ شيء أشعرك يا محمد ما الحطمة، ثم أخبره عنها ما هي، فقال جل ثناؤه: هي ﴿نَارُ اللَّهِ الْمُوقَدَةُ الَّتِي تَطَّلِعُ عَلَى الأفْئِدَةِ﴾ يقول: التي يطلع ألمها ووهجها القلوب؛ والاطلاع والبلوغ قد يكونان بمعنى، حُكي عن العرب سماعا: متى طلعت أرضنا؛ وطلعت أرضي: بلغت.\n\n* *\n\nوقوله: ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾\n\nيقول تعالى ذكره: إن الحطمة التي وصفت صفتها عليهم، يعني: على هؤلاء الهمازين اللمازين ﴿مُؤْصَدَةٌ﴾ : يعني: مطبقة؛ وهي تهمز ولا تهمز؛ وقد قُرئتا جميعا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا طلق، عن ابن ظهير، عن السديّ، عن أبي مالك، عن ابن عباس في ﴿مُؤْصَدَة﴾ : قال: مطبقة.\n\n⁕ حدثني عبيد بن أسباط، قال: ثني أبي، عن فضيل بن مرزوق، عن عطية، في قوله: ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ قال: مطبقة.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن سعيد، قال: في النار رجل في شعب من شعابها ينادي مقدار ألف عام: يا حنان يا حنان، فيقول رب العزة لجبريل: أخرج عبدي من النار، فيأتيها فيجدها مطبقة، فيرجع فيقول: يا ربّ ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ فيقول: يا حبريل فكها، وأخرج عبدي من النار، فيفكها، ويخرج مثل الخيال، فيطرح على ساحل الجنة حتي يُنبت الله له شعرا ولحما ودما.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن علية، عن أبي رجاء، عن الحسن، في قوله: ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ قال: مطبقة.\n\n⁕ حدثنا أبو كريب، قال: ثنا وكيع، عن مضرِّس بن عبد الله، قال: سمعت الضحاك ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ قال: مطبقة.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ قال: عليهم مغلقة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ : أي مطبقة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ﴾ قال: مطبقة، والعرب تقول: أوصد الباب: أغلق.\n\n* *\n\nوقوله: ﴿فِي عَمَدٍ مُمَدَّدَةٍ﴾\n\nاختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء المدينة والبصرة: ﴿فِي عَمَدٍ﴾ بفتح العين والميم. وقرأ ذلك عامة قرّاء الكوفة: \"فِي عُمُدٍ\" بضم العين والميم. والقول في ذلك عندنا أنهما قراءتان معروفتان، قد قرأ بكل واحدة منهما علماء من القرّاء، ولغتان صحيحتان. والعرب تجمع العمود: عُمُدا وعَمَدا، بضم الحرفين وفتحهما، وكذلك تفعل في جمع إهاب، تجمعه: أُهُبا، بضم الألف والهاء، وأَهَبا بفتحهما، وكذلك القضم، فبأيتهما قرأ القارئ فمصيب.\n\nواختلف أهل التأويل في معنى ذلك، فقال بعضهم: ﴿إنها عليهم مؤصدة بعمد ممددة﴾ أي مغلقة مطبقة عليهم، وكذلك هو في قراءة عبد الله فيما بلغنا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن قتادة، في قراءة عبد الله: \"إنها عَلَيْهِمْ مُؤْصَدَةٍ بِعَمَدٍ مُمَدَّدَةٍ\".\n\nوقال آخرون: بل معنى ذلك: إنما دخلوا في عمد، ثم مدت عليهم تلك العمد بعماد.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿فِي عَمَدٍ مُمَدَّدَةٍ﴾ قال: أدخلهم في عمد، فمدت عليهم بعماد، وفي أعناقهم السلاسل، فسدّت بها الأبواب.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد ﴿فِي عَمَدٍ﴾ من حديد مغلولين فيها، وتلك العمد من نار قد احترقت من النار، فهي من نار ﴿مُمَدَّدَةٍ﴾ لهم.\n\nوقال آخرون: هي عمد يعذّبون بها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فِي عَمَدٍ مُمَدَّدَةٍ﴾ كُنَّا نحدَّث أنها عمد يعذّبون بها في النار، قال بشر: قال يزيد: في قراءة قتادة: ﴿عَمَدٍ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد، عن قتادة ﴿فِي عَمَدٍ مُمَدَّدَةٍ﴾ قال: عمود يعذبون به في النار.\n\nوأولى الأقوال بالصواب في ذلك قول من قال: معناه: أنهم يعذّبون بعمد في النار، والله أعلم كيف تعذيبه إياهم بها، ولم يأتنا خبر تقوم به الحجة بصفة تعذيبهم بها، ولا وضع لنا عليها دليل، فندرك به صفة ذلك، فلا قول فيه، غير الذي قلنا يصحّ عندنا، والله أعلم.\n\nآخر تفسير سورة الهمزة","2":1,"3":1,"4":1,"5":1,"6":1,"7":1,"8":1,"9":1},"105":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ (١) أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ (٢) وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ (٣) تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ (٤) فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ (٥) ﴾ .\n\nيقول تعالى ذكره لنبيه محمد ﷺ: ألم تنظر يا محمد بعين قلبك، فترى بها ﴿كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ﴾ الذين قَدِموا من اليمن يريدون تخريب الكعبة من الحبشة ورئيسهم أبرهة الحبشيّ الأشرم ﴿أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ﴾\n\nيقول: ألم يجعل سعي الحبشة أصحاب الفيل في تخريب الكعبة ﴿فِي تَضْلِيلٍ﴾ يعني: في تضليلهم عما أرادوا وحاولوا من تخريبها.\n\n* *\n\nوقوله: ﴿وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ﴾\n\nيقول تعالى ذكره: وأرسل عليهم ربك طيرا متفرقة، يتبع بعضها بعضا من نواح شتي؛ وهي جماع لا واحد لها، مثل الشماطيط والعباديد ونحو ذلك. وزعم أبو عبيدة معمر بن المثنى، أنه لم ير أحدا يجعل لها واحدا. وقال الفرّاء: لم أسمع من العرب في توحيدها شيئا. قال: وزعم أبو جعفر الرُّؤاسِيّ، وكان ثقة، أنه سمع أن واحدها: إبالة. وكان الكسائي يقول: سمعت النحويين يقولون: إبول، مثل العجول. قال: وقد سمعت بعض النحويين يقول. واحدها: أبيل.\n\nوبنحو الذي قلنا في الأبابيل: قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا سوّار بن عبد الله، قال: ثنا يحيى بن سعيد، قال: ثنا حماد بن سلمة، عن عاصم بن بهدلة، عن زرّ، عن عبد الله، في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: فرق.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى وعبد الرحمن، قالا ثنا حماد بن سلمة، عن عاصم، عن زرّ، عن عبد الله، قال: الفِرَق.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: يتبع بعضُها بعضا.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ﴾ قال: هي التي يتبع بعضها بعضا.\n\n⁕ حدثنا ابن المثنى، قال: ثني عبد الأعلى، قال: ثنا داود، عن إسحاق بن عبد الله بن الحارث بن نوفل، أنه قال في: ﴿طَيْرًا أَبَابِيلَ﴾ قال: هي الأقاطيع، كالإبل المؤَبَّلة.\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القُمِّيّ، عن جعفر، عن سعيد بن عبد الرحمن بن أبزى ﴿طَيْرًا أَبَابِيلَ﴾ قال: متفرّقة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، قال: ثنا الفضل، عن الحسن ﴿طَيْرًا أَبَابِيلَ﴾ قال: الكثيرة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن جابر، عن ابن سابط، عن أبي سلمة، قالا الأبابيل: الزُّمَر.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد في قول الله: ﴿أَبَابِيلَ﴾ قال: هي شتى متتابعة مجتمعة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة قال: الأبابيل: الكثيرة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة قال: الأبابيل: الكثيرة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ يقول: متتابعة. بعضها على أثر بعض.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد؛ في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: الأبابيل: المختلفة، تأتي من ها هنا، وتأتي من ها هنا، أتتهم من كلّ مكان.\n\nوذُكر أنها كانت طيرا أُخرجت من البحر. وقال بعضهم: جاءت من قبل البحر.\n\nثم اختلفوا في صفتها، فقال بعضهم: كانت بيضاء.\n\nوقال آخرون: كانت سوداء.\n\nوقال آخرون: كانت خضراء، لها خراطيم كخراطيم الطير، وأكفّ كأكفّ الكلاب.\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن ابن عون، عن محمد بن سيرين، في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: قال ابن عباس: هي طير، وكانت طيرا لها خراطيم كخراطيم الطير، وأكفّ كأكفّ الكلاب.\n\n⁕ حدثني الحسن بن خلف الواسطي، قال: ثنا وكيع وروح بن عبادة، عن ابن عون، عن ابن سيرين عن ابن عباس، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن ابن عون، عن ابن عباس، نحوه.\n\n⁕ حدثنا يعقوب، قال: ثنا هشيم، قال: أخبرنا حسين، عن عكرمة، في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: كانت طيرا خرجت خضرا، خرجت من البحر، لها رءوس كرءوس السباع.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش، عن أبي سفيان، عن عبيد بن عمير ﴿طَيْرًا أَبَابِيلَ﴾ قال: هي طير سود بحرية، في مناقرها وأظفارها الحجارة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن أبي سفيان، عن عبيد بن عمير: ﴿طَيْرًا أَبَابِيلَ﴾ قال: سود بحرية، في أظافيرها ومناقيرها الحجارة.\n\n⁕ قال: ثنا مهران، عن خارجة، عن عبد الله بن عون، عن ابن سيرين، عن ابن عباس قال: لها خراطيم كخراطيم الطير، وأكفّ كأكفّ الكلاب.\n\n⁕ حدثنا يحيى بن طلحة اليربوعى، قال: ثنا فضيل بن عياض، عن عطاء بن السائب، عن سعيد بن جبير، في قوله: ﴿طَيْرًا أَبَابِيلَ﴾ قال: طير خُضْر، لها مناقير صُفْر، تختلف عليهم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن الأعمش، عن أبي سفيان، عن عبيد بن عمير، قال: طير سود تحمل الحجارة في أظافيرها ومناقيرها.\n\n* *\n\nوقوله: ﴿تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ﴾\n\nيقول تعالى ذكره: ترمي هذه الطير الأبابيل التي أرسلها الله على أصحاب الفيل، بحجارة من سجيل.\n\nوقد بيَّنا معنى سجيل في موضع غير هذا، غير أنا نذكر بعض ما قيل من ذلك في هذا الموضع، من أقوال مَنْ لم نذكره في ذلك الموضع.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ، عن عكرمة، عن ابن عباس ﴿حِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: طين في حجارة.\n\n⁕ حدثني الحسين بن محمد الذارع، قال: ثنا يزيد بن زُرَيع، قال: ثنا سعيد، عن قتادة، عن عكرمة، عن ابن عباس ﴿تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: من طين.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن السدي، عن عكرمة، عن ابن عباس ﴿حِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: سنك وكل.\n\n⁕ حدثني الحسين بن محمد الذارع، قال: ثنا يزيد بن زريع، عن عمارة بن أبي حفصة، عن عكرمة، في قوله: ﴿تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: من طين.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن شرقي، قال: سمعت عكرمة يقول: ﴿تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: سنك وكل.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا حصين، عن عكرمة، قال: كانت ترميهم بحجارة معها، قال: فإذا أصاب أحدهم خرج به الجُدَرِيّ، قال: كان أوّل يوم رُؤى فيه الجدريّ؛ قال: لم ير قبل ذلك اليوم، ولا بعده.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن موسى بن أبي عائشة، قال: ذكر أبو الكُنود، قال: دون الحِمَّصة وفوق العدسة.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو أحمد، قال: ثنا سفيان، عن موسى بن أبي عائشة، قال: كانت الحجارة التي رُمُوا بها أكبر من العدسة؛ وأصغر من الحِمَّصَةِ.\n\n⁕ قال: ثنا أبو أحمد الزُّبيريّ، قال: ثنا إسرائيل، عن موسى بن أبي عائشة، عن عمران، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن السديّ، عن عكرِمة، عن ابن عباس: سجِّيل بالفارسية: سنك وكل، حَجَر وطين.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن جابر بن سابط، قال: هي بالأعجمية: سنك وكل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: كانت مع كل طير ثلاثة أحجار: حجران في رجليه، وحجر في منقاره، فجعلت ترميهم بها.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿حِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: هي من طين.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: هي طير بيض، خرجت من قِبَل البحر، مع كلّ طير ثلاثة أحجار: حجران في رجليه، وحجر في منقاره، ولا يصيب شيئا إلا هشَمه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرنا عمرو بن الحارث بن يعقوب أن أباه أخبره أنه بلغه أن الطير التي رمت بالحجارة، كأنت تحملها بأفواهها، ثم إذا ألقتها نَفِط لها الجلد.\n\nوقال آخرون: معنى ذلك: ترميهم بحجارة من سماء الدنيا.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ﴾ قال: السماء الدنيا، قال: والسماء الدنيا اسمها سجيل، وهي التي أنزل الله جلّ وعزّ على قوم لوط.\n\nقال: أخبرنا ابن وهب، قال: أخبرنا عمرو بن الحارث، عن سعيد بن أبي هلال، أنه بلغه أن الطير التي رمت بالحجارة، أنها طير تخرج من البحر، وأن سجيل: السماء الدنيا. وهذا القول الذي قاله ابن زيد لا نعرف لصحته وجها في خبر ولا عقل، ولا لغة، وأسماء الأشياء لا تدرك إلا من لغة سائرة، أو خبر من الله تعالى ذكره.\n\nكان السبب الذي من أجله حلَّت عقوبة الله تعالى بأصحاب الفيل، مسير أبرهة الحبشيّ بجنده معه الفيل، إلى بيت الله الحرام لتخريبه.\n\nوكان الذي دعاه إلى ذلك فيما:-\n\n⁕ حدثنا به ابن حميد، قال: ثنا سلمة بن الفضل، قال: ثنا ابن إسحاق، أن أبرهة بنى كنيسة بصنعاء، وكان نصرانيا، فسماها القليس؛ لم يُر مثلها في زمانها بشيء من الأرض؛ وكتب إلى النجاشيّ ملك الحبشة: إني قد بنيت لك أيها الملك كنيسة، لم يبن مثلها لملك كان قبلك، ولستُ بمُنتهٍ حتى أصرف إليها حاجّ العرب  . فلما تحدثت العرب بكتاب أبرهة ذلك للنجاشي، غضب رجل من النَّسأة أحد بني فقيم، ثم أحد بني مالك، فخرج حتى أتى القُليس، فقعد فيها، ثم خرج فلحق بأرضه، فأخبر أبرهة بذلك، فقال: من صنع هذا؟ فقيل: صنعه رجل من أهل هذا البيت، الذي تحجّ العرب إليه بمكة، لما سمع من قولك: أصرف إليه حاجّ العرب، فغضب، فجاء فقعد فيها، أي أنها ليست لذلك بأهل؛ فغضب عند ذلك أبرهة، وحلف ليسيرنّ إلى البيت فيهدمه، وعند أبرهة رجال من العرب قد قَدِموا عليه يلتمسون فضله، منهم محمد بن خُزَاعي بن حِزَابة الذَّكواني، ثم السُّلَمي، في نفر من قومه، معه أخ له يقال له قيس بن خزاعي؛ فبينما هم عنده، غَشِيهم عبد لأبرهة، فبعث إليهم فيه بغذائه، وكان يأكل الخُصَى؛ فلما أتى القوم بغذائه، قالوا: والله لئن أكلنا هذا لا تزال تسبُّنا به العرب ما بقينا، فقام محمد بن خزاعي، فجاء أبرهة فقال: أيها الملك، إن هذا يوم عيد لنا، لا نأكل فيه إلا الجنُوب والأيدي، فقال له أبرهة: فسنبعث إليكم ما أحببتم، فإنما أكرمتكم بغذائي، لمنزلتكم عندي.\n\nثم إن ابرهة توج محمد بن خُزَاعِي، وأمَّره على مضر، وأمره أن يسير في الناس، يدعوهم إلى حج القُلَّيس، كنيسته التي بناها، فسار محمد بن خزاعي، حتى إذا نزل ببعض أرض بني كنانة، وقد بلغ أهل تهامة أمره، وما جاء له، بعثوا إليه رجلا من هذيل يقال له عُرْوة بن حياض الملاصي، فرماه بسهم فقتله؛ وكان مع محمد بن خزاعي أخوه قيس بن خزاعي، فهرب حين قُتل أخوه، فلحق بأبرهة فأخبره بقتله، فزاد ذلك أبرهة غضبا وحنقا، وحلف ليغزونّ بني كنانة، وليهدمنّ البيت.\n\nثم إن أبرهة حين أجمع السير إلى البيت، أمر الحُبْشان فتهيأت وتجهَّزت، وخرج معه بالفيل، وسمعت العرب بذلك، فأعظموه، وفُظِعوا به، ورأوا جهاده حقا عليهم، حين سمعوا أنه يريد هدم الكعبة، بيت الله الحرام، فخرج رجل كان من أشراف أهل اليمن وملوكهم، يقال له ذو نَفْر، فدعا قومه ومن أجابه من سائر العرب، إلى حرب أبرهة، وجهاده عن بيت الله، وما يريد من هدمه وإخرابه، فأجابه من أجابه إلى ذلك، وعَرَض له، وقاتله، فهزم وتفرق أصحابه، وأُخِذَ له ذو نفر أسيرا؛ فلما أراد قتله، قال ذو نفر: أيها الملك لا تقتلني، فإنه عسى أن يكون بقائي معك خيرا لك من قتلي؛ فتركه من القتل، وحبسه عنده في وثاق. وكان أبرهة رجلا حليما.\n\nثم مضى أبرهة على وجهه ذلك يريد ما خرج له، حتى إذا كان بأرض خثعم، عرض له نفيل بن حبيب الخثعميّ في قبيلتي خثعم: شهران، وناهس، ومن معه من قبائل العرب، فقاتله فهزمه أبرهة، وأُخِذ له أسيرا، فأتي به؛ فلما همّ بقتله، قال له نفيل: أيها الملك لا تقتلني، فإني دليلك بأرض العرب، وهاتان يداي لك على قبيلتي خثعم: شهران، وناهس، بالسمع والطاعة؛ فأعفاه وخلَّى سبيله، وخرج به معه، يدله على الطريق؛ حتى إذا مرّ بالطائف، خرج إليه مسعود بن معتب في رجال ثقيف، فقال: أيها الملك، إنما نحن عبيدك، سامعون لك مطيعون، ليس لك عندنا خلاف، وليس بيتنا هذا بالبيت الذي تريد - يعنون اللات - إنما تريد البيت الذي بمكة - يعنون الكعبة - ونحن نبعث معك من يدلك، فتجاوز عنهم، وبعثوا معهم أبا رغال؛ فخرج أبرهة ومعه أبو رغال حتى أنزله المغمِّس، فلما أنزله به مات أبو رغال هناك، فرَجَمت العرب قبره، فهو القبر الذي ترجم الناس بالمغمِّس.\n\nولما نزل أبرهة المغمس، بعث رجلا من الحبشة، يقال له الأسود بن مقصود، على خيل له حتى انتهى إلى مكة، فساق إليه أموال أهل مكة من قريش وغيرهم، وأصاب فيها مئتي بعير لعبد المطلب بن هاشم، وهو يومئذ كبير قريش وسيدها؛ وهمت قريش وكنانة وهذيل ومن كان معهم بالحرم من سائر الناس بقتاله، ثم عرفوا أنهم لا طاقة لهم به، فتركوا ذلك، وبعث أبرهة حناطة الحميري إلى مكة، وقال له: سل عن سيد هذا البلد وشريفهم، ثم قل له: إن الملك يقول لكم: إني لم آت لحربكم، إنما جئت لهدم البيت، فإن لم تعرضوا دونه بحرب فلا حاجة لي بدمائكم، فإن لم يُرِد حربي فأتني به.\n\nفلما دخل حناطة مكة، سأل عن سيد قريش وشريفها، فقيل: عبد المطلب بن هاشم بن عبد مناف بن قُصَيّ، فجاءه فقال له ما أمره به أبرهة، قال له عبد المطلب: والله ما نريد حربه، وما لنا بذلك من طاقة؛ هذا بيت الله الحرام، وبيت خليله إبراهيم عليه السلام - أو كما قال - فإن يمنعه فهو بيته وحرمه، وإن يُخْلِ بينه وبينه، فو الله ما عندنا له من دافع عنه، أو كما قال؛ فقال له حناطة: فانطلق إلى الملك، فإنه قد أمرني أن آتيه بك. فانطلق معه عبد المطلب، ومعه بعض بنيه، حتى أتى العسكر، فسأل عن ذي نفر، وكان له صديقا، فدل عليه، فجاءه وهو في محبسه، فقال: يا ذا نفر، هل عندك غَنَاء فيما نزل بنا؟ فقال له ذو نفر، وكان له صديقا: وما غناء رجل أسير في يدي ملك، ينتظر أن يقتله غدوا أو عشيا! ما عندي غناء في شيء مما نزل بك، إلا أن أنيسا سائق الفيل لي صديق، فسأرسل إليه، فأوصيه بك، وأعظم عليه حقك، وأساله أن يستأذن لك على الملك، فتكلمه بما تريد، ويشفع لك عنده بخير، إن قدر على ذلك. قال: حسبي، فبعث ذو نفر إلى أنيس، فجاء به، فقال: يا أنيس إن عبد المطلب سيد قريش، وصاحب عير مكة، يطعم الناس بالسهل، والوحوش في رءوس الجبال، وقد أصاب الملك له مئتي بعير، فاستأذن له عليه، وانفعه عنده بما استطعت، فقال: أفعل.\n\nفكلَّم أنيس أبرهة، فقال: أيها الملك، هذا سيِّد قريش ببابك، يستأذن عليك، وهو صاحب عير مكة، يُطعم الناس بالسهل، والوحوش في رءوس الجبال، فأْذَنْ له عليك، فليكلمك بحاجته، وأحسن إليه. قال: فأذن له أبرهة، وكان عبد المطلب رجلا عظيما وسيما جسيما؛ فلما رآه أبرهة أجلَّه وأكرمه أن يجلس تحته، وكره أن تراه الحبشة يجلسه معه على سرير ملكه، فنزل أبرهة عن سريره، فجلس على بساطه، فأجلسه معه عليه إلى جنبه، ثم قال لترجمانه: قل له ما حاجتك إلى الملك؟ فقال له ذلك الترجمان، فقال له عبد المطلب: حاجتي إلى الملك أن يردّ عليّ مئتي بعير أصابها لي؛ فلما قال له ذلك، قال أبرهة لترجمانه: قل له: قد كنت أعجبتني حين رأيتك، ثم زهدت فيك حين كلَّمتَني، أتكلمني في مئتي بعير أصبتها لك، وتترك بيتا هو دينك ودين آبائك، قد جئت لهدمه فلا تكلمني فيه؟ قال له عبد المطلب: إني أنا رب الإبل، وإن للبيت ربا سيمنعه، قال: ما كان ليمنع مني، قال: فأنت وذاك، أردد إليّ إبلي.\n\nوكان فيما زعم بعض أهل العلم قد ذهب مع عبد المطب إلى أبرهة، حين بعث إليه حناطة، يعمر بن نفاثة بن عديّ بن الديل بن بكر بن عبد مناف بن كنانة، وهو يومئذ سيِّد بني كنانة، وخويلد بن واثلة الهُذَليّ وهو يومئذ سيد هُذَيل، فعرضوا على أبرهة ثلث أموال تهامة، على أن يرجع عنهم، ولا يهدم البيت، فأبي عليهم، والله أعلم.\n\nوكان أبرهة، قد ردّ على عبد المطلب الإبل التي أصاب له، فلما انصرفوا عنه انصرف عبد المطلب إلى قريش، فأخبرهم الخبر، وأمرهم بالخروج من مكة، والتحرزّ في شعف الجبال والشعاب، تخوّفا عليهم من مَعَرّة الجيش؛ ثم قام عبد المطلب، فأخذ بحلقة الباب، باب الكعبة، وقام معه نفر من قريش يدعون الله، ويستنصرونه على أبرهة وجنده، فقال عبد المطلب، وهو آخذ حلقة باب الكعبة:\n\nيا رَبِّ لا أرْجُو لَهُمْ سِوَاكا ... يا رَبِّ فامْنَعْ مِنْهُم حِماكا\n\nإنَّ عَدُوَّ الْبَيْتِ مَنْ عادَاكا ... امْنَعْهُمُ أنْ يُخَربُوا قُرَاكا\n\nوقال أيضا:\n\nلا هُمَّ إنَّ العَبْدَ يَمْ ... نَعُ رَحْلَهُ فامْنَع حِلالكْ\n\nلا يَغْلِبَنَّ صَلِيبُهُمْ ... ومِحَالُهُمْ غَدْوا مِحَالكْ\n\nفَلَئِنْ فَعَلْتَ فَرُبَّمَا ... أوْلى فأمْرٌ ما بَدَا لَكْ\n\nوَلئِنْ فَعَلْتَ فإنَّهُ ... أمْرٌ تُتِمُّ بِهِ فِعَالكْ\n\nوقال أيضا:\n\nوكُنْتُ إذَا أتى باغٍ بِسَلْمٍ ... نُرَجِّي أن تَكُونَ لَنَا كَذلِكْ\n\nفَوَلَّوْا لَمْ يَنالُوا غَيْرَ خِزْيٍ ... وكانَ الحَيْنُ يُهْلِكُهُمْ هُنَالكْ\n\nوَلَمْ أسْمَعْ بأرْجَسَ مِنْ رِجالٍ ... أرَادُوا العِزَّ فانْتَهَكُوا حَرامَكْ\n\nجَرُّوا جُمُوعَ بِلادِهِمْ ... والْفِيلَ كَيْ يَسبُوا عِيَالكْ\n\nثم أرسل عبد المطلب حلقة باب الكعبة، وانطلق هو ومن معه من قريش إلى شَعَف الجبال، فتحرّزوا فيها، ينتظرون ما أبرهة فاعل بمكة إذا دخلها؛ فلما أصبح أبرهة تهيأ لدخول مكة، وهيأ فيله، وعبأ جيشه، وكان اسم الفيل محمودا، وأبرهة مُجْمِعٌ لهدم البيت، ثم الانصراف إلى اليمن. فلما وجَّهوا الفيل، أقبل نفيل بن حبيب الخثعميّ، حتى قام إلى حنبه، ثم أخذ بأذنه فقال: أبرك محمود، وارجع راشدا من حيث جئت، فإنك في بلد الله الحرام؛ ثم أرسل أذنه، فبَرَك الفيل، وخرج نُفَيل بن حبيب يشتدّ حتى أصعد في الجبل. وضربوا الفيل ليقوم فأبى، وضربوا في رأسه بالطبرزين ليقوم، فأبى، فأدخلوا محاجن لهم في مراقه، فبزغوه بها ليقوم، فأبى، فوجَّهوه راجعا إلى اليمن، فقام يهرول، ووجَّهوه إلى الشام، ففعل مثل ذلك، ووجهوه إلى المشرق، ففعل مثل ذلك، ووجهوه إلى مكة فبرك، وأرسل الله عليهم طيرا من البحر، أمثال الخطاطيف، مع كل طير ثلاثة أحجار يحملها: حجر في منقاره، وحجران في رجليه مثل الحمص والعدس، لا يصيب منهم أحدا إلا هلك، وليس كلهم أصابت، وخرجوا هاربين يبتدرون الطريق الذي منه جاءوا، ويسألون عن نفيل بن حبيب، ليدلهم على الطريق إلى اليمن، فقال نُفَيل بن حبيب حين رأى ما أنزل الله بهم من نقمته:\n\nأيْنَ المَفَرُّ والإلَهُ الطَّالِبْ ... والأشْرَمُ المَغْلُوبُ غَيْرُ الْغَالِبْ\n\nفخرجوا يتساقطون بكلّ طريق، ويهلكون على كلّ منهل، فأصيب أبرهة في جسده، وخرجوا به معهم، فسقطت أنامله أنملة أنملة، كلما سقطت أنملة أتبعتها مِدّة تَمُثُّ قيحا ودما، حتى قَدِموا به صنعاء، وهو مثل فرخ الطير، فما مات حتى انصدع صدره عن قلبه فيما يزعمون.\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، عن ابن إسحاق، عن يعقوب بن عتبة بن المُغيرة بن الأخنس، أنه حدّث، أن أوّل ما رُؤيت الحصبة والجدريّ بأرض العرب ذلك العام، وأنه أوّل ما رؤي بها مُرار الشجر: الحرملُ والحنظلُ والعُشرُ ذلك العام.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ﴾ أقبل أبرهة الأشرم من الحبشة يوما ومن معه من عداد أهل اليمن، إلى بيت الله ليهدمه من أجل بيعة لهم أصابها العرب بأرض اليمن، فأقبلوا بفيلهم، حتى إذا كانوا بالصَّفَّاح برك؛ فكانوا إذا وجَّهوه إلى بيت الله ألقى بجرانه على الأرض، وإذا وجهوه إلى بلدهم انطلق وله هرولة، حتى إذا كان بنخلة اليمانية بعث الله عليهم طيرا بيضا أبابيل. والأبابيل: الكثيرة، مع كلّ طير ثلاثة أحجار: حجران في رجليه، وحجر في منقاره، فجعلت ترميهم بها حتى جعلهم الله عزّ وجلّ كعصف مأكول؛ قال: فنجا أبو يكسوم وهو أبرهة، فجعل كلما قدم أرضا تساقط بعض لحمه، حتى أتى قومه، فأخبرهم الخبر ثم هلك.\n\n* *\n\nوقوله: ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾\n\nيعني تعالى ذكره: فجعل الله أصحاب الفيل كزرع أكلته الدواب فراثته، فيبس وتفرّقت أجزاؤه؛ شبَّه تقطُّع أوصالهم بالعقوبة التي نزلت بهم، وتفرّق آراب أبدانهم بها، بتفرّق أجزاء الروث، الذي حدث عن أكل الزرع.\n\nوقد كان بعضهم يقول: العصف: هو القشر الخارج الذي يكون على حبّ الحنطة من خارج، كهيئة الغلاف لها.\n\nذكر من قال: عُني بذلك ورق الزرع:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿كَعَصْفٍ مَأْكُولٍ﴾ قال: ورق الحنطة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿كَعَصْفٍ مَأْكُولٍ﴾ قال: هو التبن.\n\n⁕ وحُدثت عن الحسين، قال: سمعت أبا معاذ، قال: أخبرنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿كَعَصْفٍ مَأْكُولٍ﴾ : كزرع مأكول.\n\n⁕ حدثني محمد بن عمارة الأسدي، قال: ثنا زريق بن مرزوق، قال: ثنا هبيرة، عن سلمة بن نُبَيط، عن الضحاك، في قوله ﴿كَعَصْفٍ مَأْكُولٍ﴾ قال: هو الهبور بالنبطية، وفي رواية: المقهور.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾ قال: ورق الزرع وورق البقل، إذا أكلته البهائم فراثته، فصار رَوْثا.\n\nذكر من قال: عني به قشر الحبّ:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿كَعَصْفٍ مَأْكُولٍ﴾ قال: البرّ يؤكل ويُلقى عصفه الريح والعصف: الذي يكون فوق البرّ: هو لحاء البرّ.\n\nوقال آخرون في ذلك بما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي سنان، عن حبيب بن أبي ثابت: ﴿كَعَصْفٍ مَأْكُولٍ﴾ قال: كطعام مطعوم.\n\nآخر تفسير سورة الفيل","2":1,"3":1,"4":1,"5":1},"106":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿لإيلافِ قُرَيْشٍ (١) إِيلافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ (٢) فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ (٣) الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ (٤) ﴾ .\n\nاختلفت القرّاء في قراءة: ﴿لإيلافِ قُرَيْشٍ إِيلافِهِمْ﴾ ، فقرأ ذلك عامة قرّاء الأمصار بياء بعد همز لإيلاف وإيلافهم، سوى أبي جعفر، فإنه وافق غيره في قوله ﴿لإيلافِ﴾ فقرأه بياء بعد همزة، واختلف عنه في قوله ﴿إِيلافِهِمْ﴾ فروي عنه أنه كان يقرأه: \"إلْفِهِمْ\"  على أنه مصدر من ألف يألف إلفا، بغير ياء. وحَكى بعضهم عنه أنه كان يقرؤه: \"إلافِهِمْ\" بغير ياء مقصورة الألف.\n\nوالصواب من القراءة في ذلك عندي: من قرأه: ﴿لإيلافِ قُرَيْشٍ إِيلافِهِمْ﴾ بإثبات الياء فيهما بعد الهمزة، من آلفت الشيء أُولفه إيلافا، لإجماع الحجة من القرّاء عليه. وللعرب في ذلك لغتان: آلفت، وألفت؛ فمن قال: آلفت بمدّ الألف قال: فأنا أؤالف إيلافا؛ ومن قال: ألفت بقصر الألف قال: فأنا آلف إلفا، وهو رجل آلف إلفا. وحكي عن عكرمة أنه كان يقرأ ذلك: \"لتألف قريش إلفهم رحلة الشتاء والصيف\".\n\n⁕ حدثني بذلك أبو كُرَيب، قال: ثنا وكيع، عن أبي مكين، عن عكرِمة.\n\nوقد رُوي عن النبي ﷺ في ذلك، ما:-\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ليث، عن شهر بن حوشب، عن أسماء بنت يزيد، قالت: سمعت النبي ﷺ يقرأ: \"إلْفَهُمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ\".\n\nواختلف أهل العربية في المعنى الجالب هذه اللام في قوله: ﴿لإيلافِ قُرَيْشٍ﴾ ، فكان بعض نحويي البصرة يقول: الجالب لها قوله: ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾ فهي في قول هذا القائل صلة لقوله جعلهم، فالواجب على هذا القول، أن يكون معنى الكلام: ففعلنا بأصحاب الفيل هذا الفعل، نعمة منا على أهل هذا البيت، وإحسانا منا إليهم، إلى نعمتنا عليهم في رحلة الشتاء والصيف، فتكون اللام في قوله ﴿لإيلافِ﴾ بمعنى إلى، كأنه قيل: نعمة لنعمة وإلى نعمة، لأن إلى موضع اللام، واللام موضع إلى.\n\nوقد قال معنى هذا القول بعض أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى: وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿إيلافِهِم رِحْلَة الشتاءِ والصَّيْف﴾ قال: إيلافهم ذلك فلا يشقّ عليهم رحلة شتاء ولا صيف.\n\n⁕ حدثني إسماعيل بن موسى السديِّ، قال: أخبرنا شريك، عن إبراهيم بن المهاجر، عن مجاهد ﴿لإيلافِ قُريْشٍ﴾ قال: نعمتي على قريش.\n\n⁕ حدثني محمد بن عبد الله الهلالي، قال: ثنا فروة بن أبي المَغْراء الكندي، قال: ثنا شريك، عن إبراهيم بن المهاجر، عن مجاهد، مثله.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا عامر بن إبراهيم الأصبهاني، قال: ثنا خطاب ابن جعفر بن أبي المغيرة قال: ثني أبي، عن سعيد بن جُبير، عن ابن عباس، في قوله: ﴿لإيلافِ قُريْشٍ﴾ قال: نعمتي على قريش.\n\nوكان بعض نحويي الكوفة يقول: قد قيل هذا القول، ويقال: إنه تبارك وتعالى عجَّب نبيه ﷺ فقال: اعجب يا محمد لِنعَم الله على قريش، في إيلافهم رحلة الشتاء والصيف. ثم قال: فلا يتشاغلوا بذلك عن الإيمان واتباعك يستدل بقوله: ﴿فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ﴾ .\n\nوكان بعض أهل التأويل يوجِّه تأويل قوله: ﴿لإيلافِ قُريْشٍ﴾ إلى أُلفة بعضهم بعضا.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿لإيلافِ قُريْشٍ﴾ فقرأ: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ﴾ إلى آخر السورة، قال: هذا لإيلاف قريش، صنعتُ هذا بهم لألفة قريش، لئلا أفرّق أُلفتهم وجماعتهم، وإنما جاء صاحب الفيل ليستبيد حريمهم، فصنع الله ذلك.\n\nوالصواب من القول في ذلك عندنا أن يقال: إن هذه اللام بمعنى التعجب. وأن معنى الكلام: اعجبوا لإيلاف قريش رحلة الشتاء والصيف، وتركهم عبادة ربّ هذا البيت، الذي أطعهم من جوع، وآمنهم من خوف، فليعبدوا ربّ هذا البيت، الذي أطعمهم من جوع، وآمنهم من خوف. والعرب إذا جاءت بهذه اللام، فأدخلوها في الكلام للتعجب اكتفوا بها دليلا على التعجب من إظهار الفعل الذي يجلبها، كما قال الشاعر:\n\nأغَرَّكَ أنْ قَالُوا لِقُرَّةَ شاعِرًا ... فيالأباهُ مِنْ عَرِيفٍ وَشَاعِرِ\n\nفاكتفى باللام دليلا على التعجب من إظهار الفعل، وإنما الكلام: أغرّك أن قالوا: اعجبوا لقرّة شاعرا، فكذلك قوله:\n\n﴿لإيلافِ﴾ .\n\nوأما القول الذي قاله من حَكينا قوله، أنه من صلة قوله: ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾ فإن ذلك لو كان كذلك، لوجب أن يكون \"لإيلاف\" بعض \"ألم تر\"، وأن لا تكون سورة منفصلة من \"ألم تر\"، وفي إجماع جميع المسلمين على أنهما سورتان تامتان، كلّ واحدة منهما منصلة عن الأخرى ما يبين عن فساد القول الذي قاله من قال ذلك. ولو كان قوله: ﴿لإيلافِ قُرَيْشٍ﴾ من صلة قوله: ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾ لم تكن \"ألم تر\" تامَّة حتى توصل بقوله: ﴿لإيلافِ قُرَيْشٍ﴾ لأن الكلام لا يتمّ إلا بانقضاء الخبر الذي ذُكر.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿إلْفَهُمْ رِحْلَةَ الشتاءِ وَالصَّيْف﴾ يقول: لزومهم.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبى، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿لإيلافِ قُرَيْشٍ﴾ قال: نهاهم عن الرحلة، وأمرهم أن يعبدوا ربّ هذا البيت، وكفاهم المؤنة، وكانت رحلتهم في الشتاء والصيف، فلم يكن لهم راحة في شتاء ولا صيف، فأطعمهم بعد ذلك من جوع، وآمنهم من خوف، وألفوا الرحلة، فكانوا إذا شاءوا ارتحلوا، وإذا شاءوا أقاموا، فكان ذلك من نعمة الله عليهم.\n\n⁕ حدثني محمد بن المثنى، قال: ثني ابن عبد الأعلى، قال: ثنا داود، عن عكرمة قال: كانت قريش قد ألفوا بصرى واليمن يختلفون إلى هذه في الشتاء، وإلى هذه في الصيف ﴿فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ﴾ فأمرهم أن يقيموا بمكة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن إسماعيل، عن أبي صالح ﴿لإيلافِ قُرَيْشٍ إِيلافِهِمْ﴾ قال: كانوا تجارا، فعلم الله حبهم للشام.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿لإيلافِ قُرَيْشٍ﴾ قال: عادة قريش عادتهم رحلة الشتاء والصيف.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿لإيلافِ قُرَيْشٍ﴾ كانوا ألفوا الارتحال في القيظ والشتاء.\n\n* *\n\nوقوله: ﴿إِيلافِهِمْ﴾\n\nمخفوضة على الإبدال، كأنه قال: لإيلاف قريش لإيلافهم، رحلة الشتاء والصيف، وأما الرحلة فنُصبَت بقوله. ﴿إِيلافِهِمْ﴾ ، ووقوعه عليها.\n\n* *\n\nوقوله: ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾\n\nيقول: رحلة قريش الرحلتين: إحداهما إلى الشام في الصيف، والأخرى إلى اليمن في الشتاء.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ قال: كانت لهم رحلتان: الصيف إلى الشام، والشتاء إلى اليمن في التجارة، إذا كان الشتاء امتنع الشأم منهم لمكان البرد، وكانت رحلتهم في الشتاء إلى اليمن.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ قال: كانوا تُجَّارا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، ثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الكلبيّ ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ قال: كانت لهم رحلتان: رحلة في الشتاء إلى اليمن، ورحلة في الصيف إلى الشأم.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا عامر بن إبراهيم الأصبهاني، قال: ثنا خطاب بن جعفر بن أبي المغيرة قال: ثني أبي، عن سعيد بن جُبير، عن ابن عباس ﴿إِيلافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ قال: كانوا يشْتون بمكة، ويَصِيفون بالطائف.\n\n* *\n\nوقوله: ﴿فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ﴾\n\nيقول: فليقيموا بموضعهم ووطنهم من مكة، وليعبدوا ربّ هذا البيت، يعني بالبيت: الكعبة.\n\nكما:-\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا هشيم، قال: أخبرنا مُغيرة، عن إبراهيم، أن عمر بن الخطاب رضى الله عنه، صلى المغرب بمكة، فقرأ: ﴿لإيلافِ قُرَيْشٍ﴾ فلما انتهى إلى قوله: ﴿فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ﴾ أشار بيده إلى البيت.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا عامر بن إبراهيم الأصبهاني، قال: ثنا خطاب ابن جعفر بن أبي المغيرة، قال: ثني أبي، عن سعيد بن جُبير، عن ابن عباس، في قوله ﴿فَلْيَعْبُدُوا رَبَّ هَذَا الْبَيْتِ﴾ قال الكعبة.\n\nوقال بعضهم: أمروا أن يألفوا عبادة ربّ مكة كإلفهم الرحلتين.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عمرو بن عبد الحميد الآمُلِيّ، قال: ثنا مروان، عن عاصم الأحول، عن عكرِمة، عن ابن عباس، في قول الله: ﴿لإيلافِ قُرَيْشٍ﴾ قال: أُمروا أن يألفوا عبادة ربّ هذا البيت، كإلفهم رحلة الشتاء والصيف.\n\n* *\n\nوقوله: ﴿الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ﴾\n\nيقول: الذي أطعم قريشا من جوع.\n\nكما:-\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله: ﴿الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ﴾ يعني: قريشا أهل مكة بدعوة إبراهيم ﷺ حيث قال: ﴿وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ﴾ .\n\n﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ اختلف أهل التأويل في معنى قوله: ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ فقال بعضهم: معنى ذلك: أنه آمنهم مما يخاف منه من لم يكن من أهل الحرم من الغارات والحروب والقتال، والأمور التي كانت العرب يخاف بعضها من بعض.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ حيث قال إبراهيم عليه السلام: ﴿رَبِّ اجْعَلْ هَذَا الْبَلَدَ آمِنًا﴾ .\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: آمنهم من كلّ عدو في حرمهم.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قوله: ﴿لإيلافِ قُرَيْشٍ إِيلافِهِمْ﴾ قال: كان أهل مكة تجارا يتعاورون ذلك شتاء وصيفا، آمنين في العرب، وكانت العرب يغير بعضها على بعض، لا يقدرون على ذلك، ولا يستطيعونه من الخوف، حتى إن كان الرجل منهم ليُصاب في حيّ من أحياء العرب، وإذا قيل حِرْمِيٌّ خُليَ عنه وعن ماله، تعظيما لذلك فيما أعطاهم الله من الأمن.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: كانوا يقولون: نحن من حرم الله، فلا يعرض لهم أحد في الجاهلية، يأمنون بذلك، وكان غيرهم من قبائل العرب إذا خرج أغير عليه.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: كانت العرب يغير بعضها على بعض، ويسبي بعضها بعضا، فأمنوا من ذلك لمكان الحرم، وقرأ: ﴿أَوَلَمْ نُمَكِّنْ لَهُمْ حَرَمًا آمِنًا يُجْبَى إِلَيْهِ ثَمَرَاتُ كُلِّ شَيْءٍ﴾ .\n\nوقال آخرون: عُنِي بذلك: وآمنهم من الجذام.\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا قال: قال الضحاك: ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: من خوفهم من الجذام.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: من الجذام وغيره.\n\n⁕ حدثنا أبو كُريب، قال: قال وكيع: سمعت أطعمهم من جوع، قال: الجوع ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ الخوف: الجذام.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا عامر بن إبراهيم الأصبهاني، قال: ثنا خطاب بن جعفر بن أبي المُغيرة، قال: ثني أبي، عن سعيد بن جُبير، عن ابن عباس ﴿وَآمَنَهُمْ مِنْ خَوْفٍ﴾ قال: الخوف: الجذام.\n\nوالصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أخبر أنه ﴿آمَنَهُمْ مِنْ خَوْفٍ﴾ والعدو مخوف منه، والجذام مخوف منه، ولم يخصص الله الخبر عن أنه آمنهم من العدوّ دون الجذام، ولا من الجذام دون العدوّ، بل عمّ الخبر بذلك، فالصواب أن يعمّ كما عمّ جلّ ثناؤه، فيقال: آمنهم من المعنيين كليهما.\n\nآخر تفسير سورة قريش","2":1,"3":1,"4":1},"107":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ (١) فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ (٢) وَلا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ (٣) فَوَيْلٌ لِلْمُصَلِّينَ (٤) الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ (٥) الَّذِينَ هُمْ يُرَاءُونَ (٦) وَيَمْنَعُونَ الْمَاعُونَ (٧) ﴾ .\n\nيعني تعالى ذكره بقوله: ﴿أرأيت الذي يكذب بالدين﴾ أرأيت يا محمد الذي يكذّب بثواب الله وعقابه، فلا يطيعه في أمره ونهيه.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ﴾ قال: الذي يكذّب بحكم الله عز وجلّ.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن جُرَيج ﴿يُكَذِّبُ بِالدِّينِ﴾ قال: بالحساب.\n\nوذُكر أن ذلك في قراءة عبد الله: \"أرأيْتَ الَّذِي يُكَذِّبُ الدِّينَ\" فالباء في قراءته صلة، دخولها في الكلام وخروجها واحد.\n\n* *\n\nوقوله: ﴿فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ﴾\n\nيقول: فهذا الذي يكذِّب بالدين، هو الذي يدفع اليتيم عن حقه، ويظلمه. يقال منه: دععت فلانًا عن حقه، فأنا أدعه دعًا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، ﴿فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ﴾ قال: يدفع حقّ اليتيم.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿يَدُعُّ الْيَتِيمَ﴾ قال: يدفع اليتيم فلا يُطعمه.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَذَلِكَ الَّذِي يَدُعُّ الْيَتِيمَ﴾ : أي يقهره ويظلمه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿يَدُعُّ الْيَتِيمَ﴾ قال: يقهره ويظلمه.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿يَدُعُّ الْيَتِيمَ﴾ قال: يقهره.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان في قوله: ﴿يَدُعُّ الْيَتِيمَ﴾ قال: يدفعه.\n\n* *\n\nوقوله: ﴿وَلا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ﴾\n\nيقول تعالى ذكره: ولا يحثّ غيره على إطعام المحتاج من الطعام.\n\n* *\n\nوقوله: ﴿فَوَيْلٌ لِلْمُصَلِّينَ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾\n\nيقول تعالى ذكره: فالوادي الذي يسيل من صديد أهل جهنم للمنافقين الذين يصلون، لا يريدون الله عز وجل بصلاتهم، وهم في صلاتهم ساهون إذا صلوها.\n\nواختلف أهل التأويل في معنى قوله: ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ فقال بعضهم: عُنِيَ بذلك أنهم يؤخِّرونها عن وقتها، فلا يصلونها إلا بعد خروج وقتها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن المثنى، قال: ثنا سكن بن نافع الباهلي، قال: ثنا شعبة، عن خلف بن حوشب، عن طلحة بن مُصَرّف، عن مصعب بن سعد، قال: قلت لأبي، أرأيت قول الله عزّ وجلّ: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ : أهي تركها؟ قال: لا ولكن تأخيرها عن وقتها.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن عُلَية، عن هشام الدستوائي، قال: ثنا عاصم بن بهدلة، عن مصعب بن سعد، قال: قلت لسعد: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ : أهو ما يحدّث به أحدنا نفسه في صلاته؟ قال: لا ولكن السهو أن يؤخِّرها عن وقتها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عاصم، عن مصعب بن سعد ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: السهو: الترك عن الوقت.\n\n⁕ حدثنا عمرو بن عليّ، قال: ثنا عمران بن تمام البناني، قال: ثنا أبو جمرة الضبعي نصر بن عمران، عن ابن عباس، في قوله: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: الذين يؤخِّرونها عن وقتها.\n\n⁕ وحدثنا ابن حميد، قال: ثنا يعقوب، عن جعفر، عن ابن أبزي ﴿فَوَيْلٌ لِلْمُصَلِّينَ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: الذين يؤخِّرون الصلاة المكتوبة، حتى تخرج من الوقت أو عن وقتها.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش، عن أبي الضحى عن مسروق ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: الترك لوقتها.\n\n⁕ حدثني أبو السائب، قال: ثني أبو معاوية، عن الأعمش، عن مسلم، عن مسروق، في قوله: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: تضييع ميقاتها.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن أبي الضحى ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: ترك المكتوبة لوقتها.\n\n⁕ حدثنا ابن البرقي، قال: ثنا ابن أبي مريم، قال: ثنا يحيى بن أيوب، قال: أخبرني ابن زحر، عن الأعمش، عن مسلم بن صبيح ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ الذين يضيعونها عن وقتها.\n\nوقال آخرون: بل عني بذلك أنهم يتركونها فلا يصلونها.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿فَوَيْلٌ لِلْمُصَلِّينَ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ فهم المنافقون كانوا يراءون الناس بصلاتهم إذا حضروا، ويتركونها إذا غابوا، ويمنعونهم العارية بغضا لهم، وهو الماعون.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: هم المنافقون يتركون الصلاة في السرّ، ويصلون في العلانية.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: الترك لها.\n\nوقال آخرون: بل عُنِيَ بذلك أنهم يتهاونون بها، ويتغافلون عنها ويلهون.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: لاهون.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ : غافلون.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: ساهٍ عنها، لا يبالي صلى أم لم يصلّ.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ يصلون، وليست الصلاة من شأنهم.\n\n⁕ حدثني أبو السائب، قال: ثنا ابن فضيل، عن ليث، عن مجاهد، في قوله: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: يتهاونون.\n\nوأولى الأقوال في ذلك عندي بالصواب بقوله: ﴿ساهُونَ﴾ : لاهون يتغافلون عنها، وفي اللهو عنها والتشاغل بغيرها، تضييعها أحيانا، وتضييع وقتها أخرى، وإذا كان ذلك كذلك صح بذلك قول من قال: عُنِيَ بذلك ترك وقتها، وقول من قال: عُنِيَ به تركها لما ذكرتُ من أن في السهو عنها المعاني التي ذكرت.\n\nوقد رُوي عن رسول الله ﷺ بذلك خبران يؤيدان صحة ما قلنا في ذلك:\n\nأحدهما: ما:-\n\n⁕ حدثني به زكريا بن أبان المصري، قال: ثنا عمرو بن طارق، قال: ثنا عكرمة بن إبراهيم، قال: ثنا عبد الملك بن عمير، عن مصعب بن سعد، عن سعد بن أبي وقاص، قال: سألت النبيّ ﷺ، عن (الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ) قال: هم الذين يؤخِّرون الصلاة عن وقتها.\n\nوالآخر منهما: ما:-\n\n⁕ حدثني به أبو كُرَيب، قال: ثنا معاوية بن هشام، عن شيبان النحوي، عن جابر الجعفي، قال: ثني رجل، عن أبي برزة الأسلميّ، قال: قال رسول الله ﷺ: \"لما نزلت هذه الآية: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ : الله أكبر هذه خير لكم من أن لو أعطي كلّ رجل منكم مثل جميع الدنيا هو الذي إن صلى لم يرج خير صلاته، وإن تركها لم يخف ربه\".\n\n⁕ حدثني أبو عبد الرحيم البرقي، قال: ثنا عمرو بن أبي سلمة، قال: سمعت عمر بن سليمان يحدّث عن عطاء بن دينار أنه قال: الحمد لله الذي قال: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ وكلا المعنيين اللذين ذكرت في الخبرين اللذين روينا عن رسول الله ﷺ محتمل عن معنى السهو عن الصلاة.\n\n* *\n\nوقوله: ﴿الَّذِينَ هُمْ يُرَاءُونَ﴾\n\nيقول: الذين هم يراءون الناس بصلاتهم إذا صلوا، لأنهم لا يصلون رغبة في ثواب، ولا رهبة من عقاب، وإنما يصلونها ليراهم المؤمنون فيظنونهم منهم، فيكفون عن سفك دمائهم، وسبي ذراريهم، وهم المنافقون الذين كانوا على عهد رسول الله ﷺ، يستبطنون الكفر، ويُظهرون الإسلام، كذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عامر ومؤمل، قالا ثنا سفيان، عن ابن أبي نجيح، عن مجاهد: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ﴾ قال: هم المنافقون.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثني يونس، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، عن عليّ بن أبي طالب عليه السلام في قوله: ﴿يُرَاءُونَ وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: يراءون بصلاتهم.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ الَّذِينَ هُمْ يُرَاءُونَ﴾ يعني المنافقين.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قال: هم المنافقون، كانوا يراءون الناس بصلاتهم إذا حضروا، ويتركونها إذا غابوا.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني ابن زيد: ويصلون- وليس الصلاة من شأنهم- رياءً.\n\n* *\n\nوقوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾\n\nيقول: ويمنعون الناس منافع ما عندهم، وأصل الماعون من كلّ شيء منفعته، يقال للماء الذي ينزل من السحاب ماعون، ومنه قول أعشى بني ثعلبة:\n\nبِأَجْوَدَ مِنْه بِمَاعُونِهِ ... إذا ما سَماؤُهُمُ لَمْ تَغِمْ\n\nوقال آخر يصف سحابا:\n\nيَمُجُّ صّبيرُهُ المَاعُونَ صَبًا  وقال عبيد الراعي:\n\nقَوْمٌ عَلى الإسْلامِ لَمَّا يَمْنَعُوا ... ماعُونَهُمْ وَيُضَيِّعُوا التَّهْلِيلا\n\nيعني بالماعون: الطاعة والزكاة.\n\nواختلف أهل التأويل في الذي عُنِيَ به من معاني الماعون في هذا الموضع، فقال بعضهم: عُنِيَ به الزكاة المفروضة.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن أبي نجيح، عن مجاهد، قال: قال عليّ رضى الله عنه في قوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: الزكاة.\n\n⁕ حدثني ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن عبد الله بن أبي نجيح، عن مجاهد، قال: قال عليّ رضى الله عنه: ﴿المَاعُون﴾ : الزكاة.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم، قال: ثنا سفيان، وحدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ، عن أبي صالح، عن عليّ رضى الله عنه قال: ﴿المَاعُون﴾ : الزكاة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرنا سفيان، عن ابن أبي نجيح، عن مجاهد، عن عليّ رضى الله عنه ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: يمنعون زكاة أموالهم.\n\n⁕ حدثني محمد بن عمارة وأحمد بن هشام قالا ثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن السديّ عن أبي صالح، عن عليّ رضى الله عنه ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: الزكاة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿المَاعُون﴾ قال: الزكاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، عن عليّ، مثله.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى، وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، أن عليا رضى الله عنه كان يقول ﴿المَاعُون﴾ : الصدقة المفروضة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن ابن أبي نجيح، عن مجاهد ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ أن عليا رضى الله عنه قال: هي الزكاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن رجل، عن مجاهد، عن ابن عمر، قال: ﴿المَاعُونَ﴾ : الزكاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سلمة بن كهيل، عن أبي المُغيرة، قال: سأل رجل ابن عمر، عن الماعون قال: هو المال الذي لا يؤدى حقه، قال: قلت: إن ابن أمّ عبد يقول: هو المتاع الذي يتعاطاه الناس بينهم، قال: هو ما أقول لك.\n\n⁕ حدثنا ابن المثنى، قال: ثنا وهب بن جرير، قال: ثنا شعبة، عن سلمة، قال: سمعت أبا المُغيرة قال: سألت ابن عمر، عن الماعون، فقال: هو منع الحقّ.\n\n⁕ حدثنا عبد الحميد بن بيان، قال: أخبرنا محمد بن يزيد، عن إسماعيل، عن سلمة بن كهيل، قال: سُئل ابن عمر عن الماعون، فقال: هو الذي يسأل حق ماله ويمنعه، فقال: إن ابن مسعود يقول: هو القدر والدلو والفأس، قال: هو ما أقول لكم.\n\n⁕ حدثني هارون بن إدريس الأصمّ، قال: ثنا عبد الرحمن بن محمد المحاربي، عن إسماعيل بن أبي خالد، عن سلمة بن كهيل، أن ابن عمر سُئل عن قول الله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: الذي يُسأل مال الله فيمنعه، فقال الذي سأله، فإن ابن مسعود يقول: هو الفأس والقدر، قال ابن عمر: هو ما أقول لك.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن إسماعيل بن أبي خالد، عن سلمة بن كهيل، قال: سأل رجل ابن عمر عن الماعون، فذكر مثله.\n\n⁕ حدثني سليمان بن محمد بن معدي كرب الرعيني، قال: ثنا بقية بن الوليد، قال: ثنا شعبة، قال: ثني سلمة بن كهيل، قال: سمعت أبا المغيرة: رجلا من بني أسد، قال: سألت عبد الله بن عمر، عن الماعون، قال: هو منع الحقّ، قلت: إن ابن مسعود قال: هو منع الفأس والدلو قال: هو منع الحقّ.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن سلمة بن كهيل، عن أبي المغيرة، عن ابن عمر قال: هي الزكاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ، عن أبي صالح، عن عليّ، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا جابر بن زيد بن رفاعة، عن حسان بن مخارق، عن سعيد بن جُبير، قال: ﴿المَاعُونَ﴾ : الزكاة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة والحسن: الماعون: الزكاة المفروضة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسماعيل، عن أبي عمر، عن ابن الحنفية رضى الله عنه قال: هي الزكاة.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: الزكاة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: هم المنافقون يمنعون زكاة أموالهم.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن عبد الأعلى، قال: ثنا سعيد، عن قتادة، قال: ﴿المَاعُونَ﴾ : الزكاة المفروضة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سعيد، عن قتادة، مثله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا محمد بن عقبة، قال: سمعت الحسن يقول: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: منعوا صدقات أموالهم، فعاب الله عليهم.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مبارك، عن الحسن ﴿الَّذِينَ هُمْ يُرَاءُونَ وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: هو المنافق الذي يمنع زكاة ماله، فإن صلى راءى، وإن فاتته لم يأس عليها.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سلمة، عن الضحاك، قال: هي الزكاة.\n\nوقال آخرون: هو ما يتعاوره الناس بينهم من مثل الدلو والقدر ونحو ذلك.\n\nذكر من قال ذلك:\n\n⁕ حدثني زكريا بن يحيى بن أبي زائدة، قال: ثنا ابن أبي إدريس، عن الأعمش، عن الحكم بن يحيى بن الجزار، عن أبي العبيدين، أنه قال لعبد الله: أخبرني عن الماعون؟ قال: هو ما يتعاوره الناس بينهم.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن الحكم، قال: سمعت يحيى بن الجزار يحدّث عن أبي العبيدين: رجل من بني تميم ضرير البصر، وكان يسأل عبد الله بن مسعود، وكان ابن مسعود يعرف له ذلك، فسأل عبد الله عن الماعون، فقال عبد الله: إن من الماعون منع الفأس والقدر والدلو، خصلتان من هؤلاء الثلاث؛ قال شعبة: الفأس ليس فيه شكّ.\n\n⁕ حدثنا ابن المثنى، قال: ثنا الوليد، قال: ثنا شعبة، عن الحكم بن عتيبة، عن يحيى بن الجزار، عن أبي العبيدين، عن عبد الله، مثله.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن عُلَيه، قال: ثنا شعبة، عن الحكم بن عتيبة، عن يحيى بن الجزار، أن أبا العبيدين: رجلا من بني تميم، كان ضرير البصر، سأل ابن مسعود عن الماعون، فقال: هو منع الفأس والدلو، أو قال: منع الفأس والقدر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن الأعمش، عن الحكم، عن يحيى بن الجزار، أن أبا العبيدين سأل ابن مسعود، عن الماعون، قال: هو ما يتعاوره الناس بينهم، الفأس والقدر والدلو.\n\n⁕ حدثنا أحمد بن منصور الرمادي، قال: ثنا أبو الجوّاب، عن عمار بن رزيق، عن أبي إسحاق، عن حارثة بن مضرِّب، عن أبي العبيدين، عن عبد الله، قال: كنا أصحاب محمد نحدّث أن الماعون: القدر والفأس والدلو. قال أبو بكر: قال أبو الجوّاب، وخالفه زُهير بن معاوية فيما:-\n\n⁕ حدثنا به الحسن الأشيب، قال: ثنا زُهَير، قال: ثنا أبو إسحاق، عن حارثة، عن أبي العبيدين، حدثني محمد بن عبيد، قال: ثنا أبو الأحوص، عن أبي إسحاق، عن حارثة، عن أبي العبيدين وسعيد بن عياض، عن عبد الله، قال: كنا أصحاب محمد ﷺ نتحدّث أن الماعون: الدلو والفأس والقدر، لا يستغنى عنهنّ.\n\n⁕ حدثنا ابن المثنى، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن ابن أبي إسحاق، عن سعيد بن عياض -قال أبو موسى: هكذا قال غندر- عن أصحاب النبيّ ﷺ، قالوا: إن من الماعون: الفأس والدلو والقدر.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الرحمن، قال: ثنا سفيان، وحدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبى إسحاق، عن سعيد بن عياض، يحدّث عن أصحاب النبيّ ﷺ بمثله.\n\n⁕ قال: ثنا أبو داود، قال: ثنا شعبة، عن أبي إسحاق، قال: سمعت سعيد بن عياض، يحدّث عن أصحاب النبيّ ﷺ، مثله.\n\n⁕ حدثنا خلاد، قال: أخبرنا النضر، قال: أخبرنا إسرائيل، قال: أخبرنا أبو إسحاق، عن حارثة بن مضرب، عن أبى العبيدين، قال: قال عبد الله: الماعون: القدر والفأس والدلو.\n\n⁕ حدثنا خلاد، قال: أخبرنا النضر، قال: أخبرنا المسعودي، قال: أخبرنا سلمة بن كُهَيْلٍ، عن أبي العبيدين، وكانت به زمانة، وكان عبد الله يعرف له ذلك، فقال: يا أبا عبد الرحمن ما الماعون؟ قال: ما يتعاطى الناس بينهم من الفأس والقدر والدلو وأشباه ذلك.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن سلمة بن كهيل، عن مسلم، عن أبي العبيدين، أنه سأل ابن مسعود، عن الماعون، فقال: ما يتعاطاه الناس بينهم.\n\n⁕ قال: ثنا مهران، عن الحسن وسلمة بن كهيل، عن أبي العبيدين، عن ابن مسعود، قال: الفأس والدلو والقدر وأشباهه.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عبد الرحمن بن محمد المحاربيّ، عن المسعوديّ، عن سلمة بن كهيل، عن أبي العبيدين، أنه سأل ابن مسعود، عن قوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ فذكر نحوه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن إبراهيم التيمي، عن الحارث بن سويد، عن ابن مسعود، قال: الفأس والقدر والدلو.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن الأعمش، عن إبراهيم التيميّ، عن الحارث بن سويد، عن عبد الله قال: ﴿المَاعُونَ﴾ منع الفأس والقدر والدلو.\n\n⁕ حدثنا أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن إبراهيم، عن الحارث بن سويد، عن عبد الله، أنه سُئل عن الماعون، قال: ما يتعاوره الناس بينهم: الفأس والدلو وشبهه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن مالك بن الحارث، عن ابن مسعود، قال: الدلو والفأس والقدر.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن أبي إسحاق، عن سعيد بن عياض، عن أصحاب النبيّ ﷺ: قال: الماعون: الفأس والقدر والدلو.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن إبراهيم، قال: سُئل عبد الله عن الماعون، قال: ما يتعاوره الناس بينهم، الفأس والقدر والدلو وشبهه.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا مغيرة، عن إبراهيم أنه قال هو عارية الناس: الفأس والقدر والدلو ونحو ذلك، يعني الماعون.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن الأعمش، عن إبراهيم، عن عبد الله، بمثله.\n\n⁕ قال: ثنا وكيع، عن الأعمش، عن سعيد بن جُبير، عن ابن عباس مثله، قال: الفأس والدلو.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن حبيب بن أبي ثابت الأسدّي، عن سعيد بن جُبير، عن ابن عباس قال: ﴿المَاعُونَ﴾ : العارية.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع؛ وحدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، عن ابن عباس، قال: هو العارية.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد، نحوه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن ابن أبي نجيح، عن مجاهد، عن ابن عباس، مثله.\n\n⁕ حدثنا محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، عن ابن عباس، في قوله: ﴿المَاعُونَ﴾ قال: متاع البيت.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا إسماعيل، عن ابن أبي نجيح، عن مجاهد، أراه عن ابن عباس -\"شك أبو كريب\"- ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: المتاع.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا ابن أبي نجيح، عن مجاهد، قال: قال ابن عباس هو متاع البيت.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قال: يمنعونهم العارية، وهو الماعون.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: اختلف الناس في ذلك، فمنهم من قال: يمنعون الزكاة، ومنهم من قال: يمنعون الطاعة، ومنهم من قال: يمنعون العارية.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن ليث، عن مجاهد، عن ابن عباس، في قوله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: لم يجيء أهلها بعد.\n\n⁕ حدثني ابن المثنى، قال: ثنا محمد، قال: ثنا شعبة، عن ابن أبي نجيح، عن مجاهد، قال: قال ابن عباس: ﴿المَاعُونَ﴾ ما يتعاطى الناس بينهم.\n\n⁕ حدثنا يعقوب بن إبراهيم، قال: أخبرنا ابن عُلَية، قال: ثنا ليث، عن أبي إسحاق، عن الحارث، قال: قال عليّ رضى الله عنه: ﴿المَاعُونَ﴾ : منع الزكاة والفأس والدلو والقدر.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم النبيل، قال: ثنا سفيان، عن حبيب بن أبي ثابت، عن سعيد بن جُبير قال: الماعون: العارية.\n\n⁕ حدثني أبو حصين عبد الله بن أحمد بن يونس، قال: ثنا عبثر، قال: ثنا حصين، عن أبي مالك، في قول الله: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ قال: الدلو والقدر والفأس.\n\n⁕ حدثنا عمرو بن علي، قال: ثنا أبو داود، قال: ثنا أبو عوانة، عن عاصم بن بهدلة، عن أبي وائل، عن عبد الله، قال: كنا مع نبينا ﷺ ونحن نقول: الماعون: منع الدلو وأشباه ذلك.\n\nوقال آخرون: الماعون: المعروف.\n\nذكر من قال ذلك:\n\n⁕ حدثنا محمد بن إبراهيم السلمي، قال: ثنا أبو عاصم، قال: ثنا محمد بن رفاعة، قال: سمعت محمد بن كعب يقول: الماعون: المعروف.\n\nوقال آخرون: الماعون: هو المال.\n\nذكر من قال ذلك:\n\n⁕ حدثني أحمد بن حرب، قال: ثنا موسى بن إسماعيل، قال: ثنا إبراهيم بن سعد، عن ابن شهاب، عن سعيد بن المسيب، قال: الماعون، بلسان قريش: المال.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن ابن أبى ذئب، عن الزهريّ، قال: الماعون: بلسان قريش: المال.\n\nوأولى الأقوال في ذلك عندنا بالصواب، إذ كان الماعون هو ما وصفنا قبل، وكان الله قد أخبر عن هؤلاء القوم، وأنهم يمنعونه الناس، خبرًا عاما، من غير أن يخص من ذلك شيئا أن يقال: إن الله وصفهم بأنهم يمنعون الناس ما يتعاونونه بينهم، ويمنعون أهل الحاجة والمسكنة ما أوجب الله لهم في أموالهم من الحقوق؛ لأن كل ذلك من المنافع التي ينتفع بها الناس بعضهم من بعض.\n\nآخر تفسير سورة أرأيت","2":1,"3":1,"4":1,"5":1,"6":1,"7":1},"108":{"1":"القول في تأويل قوله تعالى: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ (١) فَصَلِّ لِرَبِّكَ وَانْحَرْ (٢) إِنَّ شَانِئَكَ هُوَ الأبْتَرُ (٣) ﴾\n\n.\n\nيقول تعالى ذكره: ﴿إِنَّا أَعْطَيْنَاكَ﴾ يا محمد ﴿الْكَوْثَرَ﴾ واختلف أهل التأويل في معنى الكوثر، فقال بعضهم: هو نهر في الجنة أعطاه الله نبيه محمدا ﷺ.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا عطاء بن السائب، عن محارب بن دثار، عن ابن عمر: أنه قال: \"الكوثر: نهر في الجنة، حافتاه من ذهب وفضة، يجري على الدرّ والياقوت، ماؤه أشدّ بياضا من اللبن، وأحلى من العسل\".\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن عطاء، عن محارب بن دثار الباهلي، عن ابن عمر، في قوله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: \"نهر في الجنة حافتاه الذهب، ومجراه على الدرّ والياقوت، وماؤه اشدّ بياضا من الثلج، وأشدّ حلاوة من العسل، وتربته أطيب من ريح المسك\".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا عمر بن عبيد، عن عطاء، عن سعيد بن جُبير، عن ابن عباس، قال: \"الكوثر: نهر في الجنة حافتاه من ذهب وفضة، يجري على الياقوت والدرّ، ماؤه أبيض من الثلج، وأحلى من العسل\".\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القُمِّي، عن حفص بن حميد، عن شمر بن عطية، عن شقيق أو مسروق، قال: قلت لعائشة: يا أمّ المؤمنين، وما بُطْنان الجنة؟ قالت: \"وسط الجنة: حافتاه قصور اللؤلؤ والياقوت، ترابه المسك، وحصباؤه اللؤلؤ والياقوت\".\n\n⁕ حدثنا أحمد بن أبي سريج الرازيّ، قال: ثنا أبو النضر وشبابة، قالا ثنا أبو جعفر الرازيّ، عن ابن أبي نجيح، عن مجاهد، عن رجل، عن عائشة قالت: الكوثر: نهر في الجنة ليس أحد يدخل أصبعيه في أذنيه إلا سمع خرير ذلك النهر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي جعفر؛ وحدثنا ابن أبي سريج، قال: ثنا أبو نعيم، قال: أخبرنا أبو جعفر الرازيّ، عن ابن أبي نجيح، عن أنس، قال: الكوثر: نهر في الجنة.\n\n⁕ قال: ثنا وكيع، عن سفيان، عن أبي إسحاق، عن أبي عبيدة، عن عائشة قالت: الكوثر نهر في الجنة، درّ مجوّف.\n\n⁕ حدثنا وكيع، عن إسرائيل، عن أبي إسحاق، عن أبي عبيدة، عن عائشة: \"الكوثر: نهر في الجنة، عليه من الآنية عدد نجوم السماء\".\n\n⁕ قال ثنا وكيع، عن أبي جعفر الرازيّ، عن ابن أبي نجيح، عن عائشة قالت: من أحبّ أن يسمع خرير الكوثر، فليجعل أصبعيه في أُذنيه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي إسحاق، عن أبي عبيدة، عن عائشة، قالت: نهر في الجنة، شاطئاه الدرّ المجوّف.\n\n⁕ قال: ثنا مهران، عن أبي معاذ عيسى بن يزيد، عن أبي إسحاق، عن أبي عبيدة، عن عائشة قالت: \"الكوثر: نهر في بطنان الجنة وسط الجنة، فيه نهر شاطئاه در مجوف، فيه من الآنية لأهل الجنة، مثل عدد نجوم السماء\".\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: نهر أعطاه الله محمدا ﷺ في الجنة.\n\n⁕ حدثنا أحمد بن أبي سريج، قال: ثنا مسعدة، عن عبد الوهاب، عن مجاهد، قال: \"الكَوْثر: نهر في الجنة، ترابه مسك أذفر، وماؤه الخمر\".\n\n⁕ حدثنا ابن أبي سريج، قال: ثنا عبيد الله، قال: أخبرنا أبو جعفر، عن الربيع، عن أبي العالية، في قوله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: نهر في الجنة.\n\n⁕ حدثنا الربيع، قال: أخبرنا ابن وهب، عن سليمان بن بلال، عن شريك بن أبي نمر، قال: سمعت أنس بن مالك يحدثنا، قال: لما أسري برسول الله ﷺ، مضى به جبريل في السماء الدنيا، فإذا هو بنهر، عليه قصر من لؤلؤ وزبرجد، فذهب يَشَمّ ترابه، فإذا هو مسك، فقال: \"يا جبريل ما هذا النهر؟ \" قال: هو الكوثر الذي خبأ لك ربُّك.\n\nوقال آخرون: عُنِي بالكوثر: الخير الكثير.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثني هشيم، قال: أخبرنا أبو بشر وعطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس أنه قال في الكوثر: هو الخير الكثير الذي أعطاه الله إياه. قال أبو بشر: فقلت لسعيد بن جبير: فإن ناسا يزعمون أنه نهر في الجنة، قال: فقال سعيد: النهر الذي في الجنة من الخير الذي أعطاه الله إياه.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا إسماعيل بن إبراهيم، عن عطاء بن السائب، قال: قال محارب بن دثار: ما قال سعيد بن جُبير في الكوثر؟ قال: قلت: قال: قال ابن عباس: هو الخير الكثير، فقال: صدق والله.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن عطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس، قال: الكوثر: الخير الكثير.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، قال: سألت سعيد بن جبير، عن الكوثر، فقال: هو الخير الكثير الذي آتاه الله، فقلت لسعيد: إنا كنا نسمع أنه نهر في الجنة، فقال: هو الخير الذي أعطاه الله إياه.\n\n⁕ حدثنا ابن المثنى، قال: ثني عبد الصمد، قال: ثنا شعبة، عن أبي بشر، عن سعيد بن جبير: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: الخير الكثير.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد، قال: ثنا شعبة، عن عمارة بن أبى حفصة، عن عكرمة، قال: هو النبوّة، والخير الذي أعطاه الله إياه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا حرمي بن عمارة، قال: ثنا شعبة، قال: أخبرني عمارة، عن عكرمة في قول الله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: الخير الكثير، والقرآن والحكمة.\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، قال: ثنا عمارة بن أبي حفصة، عن عكرمة أنه قال: الكوثر: الخير الكثير.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن عطاء بن السائب، عن سعيد بن جُبير، عن ابن عباس: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: الخير الكثير.\n\n⁕ قال: ثنا مهران، عن سفيان، عن هلال، قال: سألت سعيد بن جُبير ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: أكثر الله له من الخير، قلت: نهر في الجنة؟ قال: نهر وغيره.\n\n⁕ حدثنا زكريا بن يحيى بن أبي زائدة، قال: ثنا أبو عاصم، عن عيسى بن ميمون، عن ابن أبي نجيح، عن مجاهد، قال: الكوثر: الخير الكثير.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قال: الكوثر: الخير الكثير.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن مجاهد: الكوثر: قال: الخير كله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، قال: خير الدنيا والآخرة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة في الكوثر، قال: هو الخير الكثير.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عطاء بن السائب، عن سعيد بن جُبير، قال: الكوثر: الخير الكثير.\n\n⁕ قال: ثنا وكيع، عن بدر بن عثمان، سمع عكرمة يقول في الكوثر: قال: ما أُعطي النبّي من الخير والنبوّة والقرآن.\n\n⁕ حدثنا أحمد بن أبي سريج الرازيّ، قال: ثنا أبو داود، عن بدر، عن عكرمة، قوله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: الخير الذي أعطاه الله النبوّة والإسلام.\n\nوقال آخرون: هو حوض أُعطيه رسول الله ﷺ في الجنة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن مطر، عن عطاء ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: حوض في الجنة أُعطيه رسول الله ﷺ.\n\n⁕ حدثنا أحمد بن أبي سريج، قال: ثنا أبو نعيم، قال: ثنا مطر، قال: سألت عطاء ونحن نطوف بالبيت عن قوله: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال: حوض أُعطيه رسول الله ﷺ.\n\nوأولى هذه الأقوال بالصواب عندي، قول من قال: هو اسم النهر الذي أُعطيه رسول الله ﷺ في الجنة، وصفه الله بالكثرة، لعِظَم قدره.\n\nوإنما قلنا ذلك أولى الأقوال في ذلك، لتتابع الأخبار عن رسول الله ﷺ بأن ذلك كذلك.\n\nذكر الأخبار الواردة بذلك:\n\n⁕ حدثنا أحمد بن المقدام العجلي، قال: ثنا المعتمر، قال: سمعت أبي يحدّث عن قتادة، عن أنس قال: لما عُرج بنبيّ الله ﷺ في الجنة، أو كما قال، عرض له نهر حافتاه الياقوت المجوف، أو قال: المجوب، فضرب الملك الذي معه بيده فيه، فاستخرج مسكا، فقال محمد للملك الذي معه: \"ما هَذَا؟ \" قال: هذا الكوثر الذي أعطاك الله؛ قال: ورفعت له سدرة المنتهى، فأبصر عندها أثرا عظيما\" أو كما قال.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن أنس، أن رسول الله ﷺ، قال: \"بَيْنَما أنا أسِيرُ في الجَنَّةِ، إذْ عَرَض ليَ نَهْرٌ، حافَتاهُ قِبابُ اللُّؤْلُؤِ المُجَوَّفِ، فقالَ المَلَكُ الَّذِي مَعَهُ: أتَدْرِي ما هَذَا؟ هَذَا الكَوْثَرُ الَّذِي أعْطاكَ اللهُ إيَّاهُ، وَضَرَبَ بِيَدِهِ إلى أرْضِه، فأخْرَجَ مِنْ طِينِه المِسْكَ\".\n\n⁕ حدثني ابن عوف، قال: ثنا آدم، قال: ثنا شيبان، عن قتادة، عن أنس قال: قال رسول الله ﷺ: \"لمَّا عُرِجَ بِي إلى السَّماء، أَتَيْتُ على نَهْرٍ حافَتاهُ قِبابُ اللُّؤْلُؤِ المُجَوَّف، قُلتُ: ما هَذَا يا جِبْرِيلُ؟ قال: هَذَا الكَوْثَرُ الَّذِي أعْطَاكَ رَبُّكَ، فأهْوَى المَلكُ بِيَدِهِ، فاسْتَخْرَجَ طِينَه مِسْكًا أذفَرَ\".\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، عن حميد، عن أنس بن مالك، قال: قال رسول الله ﷺ: \"دَخَلْتُ الجَنَّة، فإذَا أنا بِنَهْرٍ حافَتاهُ خِيامُ اللُّؤْلُؤِ، فَضَرَبْتُ بِيَدِي إلى ما يَجْرِي فِيهِ، فإذَا مِسْكٌ أذْفَرُ؛ قال: قُلْتُ: ما هَذَا يا جِبْرِيلُ؟ قال: هَذَا الكَوْثَرُ الَّذِي أعْطاكَهُ اللهُ\".\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الصمد، قال: ثنا همام، قال: ثنا قتادة، عن أنس، قال: قال رسول الله ﷺ، فذكر نحو حديث يزيد، عن سعيد.\n\n⁕ حدثنا بشر، قال: ثنا أحمد بن أبي سريج، قال: ثنا أبو أيوب العباس، قال: ثنا إبراهيم بن مسعدة، قال: ثنا محمد بن عبد الله بن مسلم ابن أخي ابن شهاب، عن أبيه، عن أنس، قال: سئل رسول الله ﷺ عن الكوثر، فقال: \"هُوَ نَهْرٌ أعْطانِيهِ اللهُ في الجَنَّةِ، تُرَابُهُ مِسْكٌ أبْيَضُ مِنَ اللَّبَنِ، وأحْلَى مِنَ العَسَلِ، تَرِدُهُ طَيْرٌ أعنَاقُهَا مِثْلُ أعناقِ الجُزُرِ\"، قال أبو بكر: يا رسول الله، إنها لناعمة؟ قال: \"آكِلُها أنْعَمُ مِنْها\".\n\n⁕ حدثنا خلاد بن أسلم، قال: أخبرنا محمد بن عمرو بن علقمة بن أبي وقاص الليثي، عن كثير، عن أنس بن مالك، قال: قال رسول الله ﷺ: \"دَخَلْتُ الجَنَّةَ حِينَ عُرِجَ بِيَ، فَأُعْطِيتُ الْكَوْثَرَ، فإذَا هُوَ نَهْرٌ فِي الجَنَّةِ، عُضَادَتاهُ بُيُوتٌ مُجَوَّفَةٌ مِنْ لُؤْلُؤٍ\".\n\n⁕ حدثني محمد بن عبد الله بن عبد الحكم، قال: ثنا أبي وشعيب بن الليث، عن الليث، عن يزيد بن الهاد، عن عبد الله بن مسلم بن شهاب، عن أنس: أن رجلا جاء إلى النبيّ ﷺ فقال: يا رسول الله، ما الكوثر؟ قال: \"نَهْرٌ أعْطانِيهِ اللهُ فِي الجَنَّةِ، لَهُوَ أشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وأحْلَى مِنَ العَسَلِ، فِيهِ طُيُورٌ أعْناقُهَا كأعْناقِ الجُزُرِ\". قال عمر: يا رسول الله إنها لناعمة، قال: \"آكِلُها أنْعَمُ مِنْها\".\n\n⁕ حدثنا يونس، قال: ثنا يحيى بن عبد الله، قال: ثني الليث، عن ابن الهاد، عن عبد الوهاب عن عبد الله بن مسلم بن شهاب، عن أنس، أن رجلا جاء إلى النبي ﷺ، فذكر مثله.\n\n⁕ حدثنا عمر بن عثمان بن عبد الرحمن الزهري، أن أخاه عبد الله، أخبره أن أنس بن مالك صاحب النبي ﷺ أخبره: أن رجلا سأل النبي ﷺ، فقال: ما الكوثر؟ فقال رسول الله ﷺ: \" نَهْرٌ أعْطانِيهِ اللهُ فِي الجَنَّةِ، مَاؤهُ أبْيَضُ مِنَ اللَّبَنِ، وأحْلَى مِنَ العَسَلِ، فِيهِ طُيُورٌ أعْناقُهَا كأعْناقِ الجُزُرِ\"، فقال عمر: إنها لناعمة يا رسول الله، فقال: \"آكِلُها أنْعَمُ مِنْهَا\".\n\nفقال: عمر بن عثمان: قال ابن أبي أُوَيس؛ وحدثني أبي، عن ابن أخي الزهريّ، عن أبيه، عن أنس، عن النبي ﷺ في الكوثر، مثله.\n\n⁕ حدثنا ابن المثنى، قال: ثنا ابن فضيل، قال: ثنا عطاء، عن محارب بن دثار، عن ابن عمر، قال: قال رسول الله ﷺ: \"الكَوْثَرُ نَهْرٌ فِي الجَنَّةِ، حَافَتاهُ مِنْ ذَهَبٍ، وَمجْرَاهُ عَلى الْياقُوتِ والدُّرِّ، تُرْبَتُهُ أطْيَبُ مِنَ المِسْكِ، ماؤُهُ أحْلَى مِنَ العَسَلِ، وأشَدُّ بَياضًا مِنَ الثَّلْجِ\".\n\n⁕ حدثنا يعقوب، قال: ثنا ابن عُلَية، قال: أخبرنا عطاء بن السائب، قال: قال لي محارب بن دثار: ما قال سعيد بن جُبير في الكوثر؟ قلت: حدثنا عن ابن عباس، أنه قال: هو الخير الكثير، فقال: صدق والله، إنه للخير الكثير، ولكن حدثنا ابن عمر، قال: لما نزلت: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ قال رسول الله ﷺ: \"الكَوْثَرُ نَهْرٌ فِي الجَنَّةِ، حافَتاهُ مِنْ ذَهَبٍ، يَجْرِي على الدُّرِّ واليَاقُوتِ\".\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، عن أنس بن مالك، أن النبي ﷺ قال: \"الكَوْثَرُ نَهْرٌ فِي الجَنَّةِ\"، قال النبيّ ﷺ: \"رَأَيْتُ نَهَرًا حَافَتاهُ اللُّؤْلُؤ، فَقُلْتُ: يا جِبْرِيلُ ما هَذَا؟ قالَ: هَذَا الكَوْثَرُ الَّذِي أعْطَاكَهُ اللهُ\".\n\n⁕ حدثنا ابن البرقي، قال: ثنا ابن أبي مريم، قال: ثنا محمد بن جعفر بن أبي كثير، قال: أخبرنا حزام بن عثمان، عن عبد الرحمن الأعرج، عن أُسامة بن زيد أن رسول الله ﷺ أتى حمزة بن عبد المطلب يوما، فلم يجده، فسأل امرأته عنه، وكانت من بني النجار، فقالت: خرج، بأبي أنت آنفا عامدا نحوك، فأظنه أخطأك في بعض أزقة بني النجار، أو لا تدخل يا رسول الله؟ فدخل، فقدمت إليه حيسا، فأكل منه، فقالت: يا رسول الله، هنيئا لك ومريئا، لقد جئت وإني لأريد أن آتيك فأهنيك وأمريك  أخبرني أبو عمارة أنك أُعطيت نهرا في الجنة يُدعى الكوثر، فقال: \"أَجَلْ، وَعَرْضُهُ - يعني أرضه - يَاقُوتٌ وَمَرْجَانٌ وزَبَرْجَدٌ ولُؤْلُؤٌ\".\n\n* *\n\nوقوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾\n\nاختلف أهل التأويل في الصلاة التي أمر الله نبيه ﷺ أن يصليها بهذا الخطاب، ومعنى قوله: ﴿وَانْحَرْ﴾ فقال بعضهم: حضه على المواظبة على الصلاة المكتوبة، وعلى الحفظ عليها في أوقاتها بقوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ .\n\nذكر من قال ذلك:\n\n⁕ حدثني عبد الرحمن بن الأسود الطفاوي، قال: ثنا محمد بن ربيعة، قال: ثني يزيد بن أبي زياد بن أبي الجعد، عن عاصم الجحدري، عن عقبة بن ظهير، عن علي رضى الله عنه في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع اليمين على الشمال في الصلاة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا حماد بن سلمة، عن عاصم الجحدري، عن عقبة بن ظبيان عن أبيه، عن علي رضى الله عنه ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع اليد على اليد في الصلاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن حماد بن سلمة، عن عاصم الجحدري، عن عقبة بن ظهير، عن أبيه، عن علي رضى الله عنه ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع يده اليمنى على وسط ساعده اليسرى، ثم وضعهما على صدره.\n\n⁕ قال: ثنا مهران، عن حماد بن سلمة، عن عاصم الأحول، عن الشعبي مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن يزيد بن أبي زياد، عن عاصم الجحدري، عن عقبة بن ظهير، عن علي رضى الله عنه: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع اليمين على الشمال في الصلاة.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم، يقال: ثنا عوف، عن أبي القُموص، في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع اليد على اليد في الصلاة.\n\n⁕ حدثنا ابن حميد، قال: ثنا أبو صالح الخراساني، قال: ثنا حماد، عن عاصم الجحدري، عن أبيه، عن عقبة بن ظبيان، أن علي بن أبي طالب رضى الله عنه قال في قول الله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: وضع يده اليمنى على وسط ساعده الأيسر، ثم وضعهما على صدره.\n\nوقال آخرون: بل عُنِيَ بقوله ﴿فَصَلِّ لِرَبِّكَ﴾ : الصلاة المكتوبة، وبقوله ﴿وَانْحَرْ﴾ أن يرفع يديه إلى النحر عند افتتاح الصلاة والدخول فيها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن جابر، عن أبي جعفر ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ الصلاة، وانحر: برفع يديه أول ما يكبر في الافتتاح.\n\nوقال آخرون: عني بقوله: ﴿فَصَلِّ لِرَبِّكَ﴾ المكتوبة، وبقوله ﴿وَانْحَرْ﴾ : نحر البُدن.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام بن سلم وهارون بن المغيرة، عن عنبسة، عن ابن أبي نجيح، عن مجاهد ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: الصلاة المكتوبة، ونحر البُدن.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، عن عطاء بن السائب، عن سعيد بن جُبير وحجاج أنهما قالا في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: صلاة الغداة بجمع، ونحر البُدن بمنًى.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن قطر، عن عطاء: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: صلاة الفجر، وانحر البدن. حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: الصلاة المكتوبة، والنحر: النسك والذبح يوم الأضحى.\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن الحكم، في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: صلاة الفجر.\n\nوقال آخرون: بل عُنِيَ بذلك: صل يوم النحر صلاة العيد، وانحر نسكك.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا هارون بن المغيرة، عن عنبسة، عن جابر، عن أنس بن مالك، قال: كان النبي ﷺ ينحر قبل أن يصلي، فأمر أن يصلي ثم ينحر.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن جابر، عن عكرِمة: فصلّ الصلاة، وانحر النُّسُك.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن ثابت بن أبي صفية، عن أبي جعفر ﴿فَصَلِّ لِرَبِّكَ﴾ قال: الصلاة؛ وقال عكرِمة: الصلاة ونحر النُّسُك.\n\n⁕ حدثنا ابن حميد، قال: ثنا حكام، عن أبي جعفر، عن الربيع ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: إذا صليت يوم الأضحى فانحر.\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا قطر، قال: سألت عطاء، عن قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: تصلي وتنحر.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو عاصم، قال: ثنا عوف، عن الحسن ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: اذبح\n\n⁕ قال: ثنا عبد الرحمن، قال: ثنا أبان بن خالد، قال: سمعت الحسن يقول ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: الذبح.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: نحر البُدن، والصلاة يوم النحر.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: صلاة الأضحى، والنحر: نحر البُدن.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن ابن أبي نجيح، عن مجاهد ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: مناحر البُدن بِمِنًى.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن رجل، عن عكرمة ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: نحر النسك.\n\n⁕ حدثني علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ يقول: اذبح يوم النحر.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: نحر البُدن.\n\nوقال آخرون: قيل ذلك للنبي ﷺ، لأن قوما كانوا يصلون لغير الله، وينحرون لغيره فقيل له. اجعل صلاتك ونحرك لله، إذ كان من يكفر بالله يجعله لغيره.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثني أبو صخر، عن محمد بن كعب القرظي، أنه كان يقول في هذه الآية: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ يقول: إن ناسا كانوا يصلون لغير الله، وينحرون لغير الله، فإذا أعطيناك الكوثر يا محمد، فلا تكن صلاتك ونحرك إلا لي.\n\nوقال آخرون: بل أنزلت هذه الآية يوم الحديبية، حين حصر النبيّ ﷺ وأصحابه، وصُدّوا عن البيت، فأمره الله أن يصلي، وينحر البُدن، وينصرف، ففعل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: أخبرني أبو صخر، قال: ثني أبو معاوية البجلي، عن سعيد بن جُبير أنه قال: كانت هذه الآية، يعني قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ يوم الحديبية، أتاه جبريل عليه السلام فقال: انحر وارجع، فقام رسول الله ﷺ، فخطب خطبة الفطر والنحر  ثم ركع ركعتين، ثم انصرف إلى البُدن فنحرها، فذلك حين يقول: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ .\n\nوقال آخرون: بل معنى ذلك: فصل وادع ربك وسله.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن أبي سنان، عن ثابت، عن الضحاك ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ قال: صلّ لربك وسل.\n\nوكان بعض أهل العربية يتأوّل قوله: ﴿وَانْحَرْ﴾ واستقبل القبلة بنحرك. وذُكر أنه سمع بعض العرب يقول: منازلهم تتناحر: أي هذا بنحر هذا: أي قبالته. وذكر أن بعض بني أسد أنشده:\n\nأبا حَكَمٍ هَلْ أنْتَ عَمُّ مُجَالِدٍ ... وَسَيِّدُ أهْلِ الأبْطَحِ المُتَنَاحِرِ\n\nأي ينحر بعضه بعضا.\n\nوأولى هذه الأقوال عندي بالصواب: قول من قال: معنى ذلك: فاجعل صلاتك كلها لربك خالصا دون ما سواه من الأنداد والآلهة، وكذلك نحرك اجعله له دون الأوثان، شكرا له على ما أعطاك من الكرامة والخير الذي لا كفء له، وخصك به، من إعطائه إياك الكوثر.\n\nوإنما قلت: ذلك أولى الأقوال بالصواب في ذلك، لأن الله جلّ ثناؤه أخبر نبيه ﷺ بما أكرمه به من عطيته وكرامته، وإنعامه عليه بالكوثر، ثم أتبع ذلك قوله: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ، فكان معلوما بذلك أنه خصه بالصلاة له، والنحر على الشكر له، على ما أعلمه من النعمة التي أنعمها عليه، بإعطائه إياه الكوثر، فلم يكن لخصوص بعض الصلاة بذلك دون بعض، وبعض النحر دون بعض وجه، إذ كان حثا على الشكر على النِّعَم.\n\nفتأويل الكلام إذن: إنا أعطيناك يا محمد الكوثر، إنعاما منا عليك به، وتكرمة منا لك، فأخلص لربك العبادة، وأفرد له صلاتك ونسكك، خلافا لما يفعله من كفر به، وعبد غيره، ونحر للأوثان.\n\nوقوله: (إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾\n\nيعني بقوله جل ثناؤه: ﴿إِنَّ شَانِئَكَ﴾ إن مبغضك يا محمد وعدوك ﴿هُوَ الأبْتَرُ﴾ يعني بالأبتر: الأقلّ والأذلّ المنقطع دابره، الذي لا عقب له.\n\nواختلف أهل التأويل في المعنيّ بذلك، فقال بعضهم: عني به العاص بن وائل السهميّ.\n\nذكر من قال ذلك:\n\n⁕ حدثني علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، قوله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ يقول: عدوّك.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، قوله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: هو العاص بن وائل.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن هلال بن خباب، قال: سمعت سعيد بن جُبير يقول: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: هو العاص بن وائل.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن هلال، قال: سألت سعيد بن جُبير، عن قوله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: عدوّك العاص بن وائل انبتر من قومه.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: العاص بن وائل، قال: أنا شانئٌ محمدا، ومن شنأه الناس فهو الأبتر.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: هو العاص بن وائل، قال: أنا شانئٌ محمدا، وهو أبتر، ليس له عقب، قال الله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال قتادة: الأبتر: الحقير الدقيق الذليل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ هذا العاص بن وائل، بلغنا أنه قال: أنا شانئُ محمد.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: الرجل يقول: إنما محمد أبتر، ليس له كما ترون عقب، قال الله: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ .\n\nوقال آخرون: بل عني بذلك: عقبة بن أبي معيط.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا يعقوب القُمِّي، عن حفص بن حميد، عن شمر بن عطية، قال: كان عقبة بن أبي معيط يقول: إنه لا يبقى للنبيّ ﷺ ولد، وهو أبتر، فأنزل الله فيه هؤلاء الآيات: ﴿إِنَّ شَانِئَكَ﴾ عقبة بن أبي معيط ﴿هُوَ الأبْتَرُ﴾ .\n\nوقال آخرون: بل عني بذلك جماعة من قريش.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الوهاب، قال: ثنا داود، عن عكرمة، في هذه الآية: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا هَؤُلاءِ أَهْدَى مِنَ الَّذِينَ آمَنُوا سَبِيلا﴾ قال: نزلت في كعب بن الأشرف، أتى مكة فقال لها أهلها: نحن خير أم هذا الصنبور  المنبتر من قومه، ونحن أهل الحجيج، وعندنا منحر البدن، قال: أنتم خير. فأنزل الله فيه هذه الآية، وأنزل في الذين قالوا للنبي ﷺ ما قالوا: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ .\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن بدر بن عثمان، عن عكرمة ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ . قال: لما أوحي إلى النبي ﷺ قالت قريش: بَتِرَ محمد منا، فنزلت: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: الذي رماك بالبتر هو الأبتر.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبى عديّ، قال: أنبأنا داود بن أبي هند، عن عكرمة، عن ابن عباس قال: لما قَدِم كعب بن الأشرف مكة أتَوْه، فقالوا له: نحن أهل السقاية والسدانة، وأنت سيد أهل المدينة، فنحن خير أم هذا الصنبور المنبتر من قومه، يزعم أنه خير منا؟ قال: بل أنتم خير منه، فنزلت عليه: ﴿إِنَّ شَانِئَكَ هُوَ الأبْتَرُ﴾ قال: وأنزلت عليه: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِنَ الْكِتَابِ﴾ ... إلى قوله ﴿نَصِيرًا﴾ .\n\nوأولى الأقوال في ذلك عندي بالصواب أن يقال: إن الله تعالى ذكره أخبر أن مُبغض رسول الله ﷺ هو الأقلّ الأذلّ، المنقطع عقبه، فذلك صفة كل من أبغضه من الناس، وإن كانت الآية نزلت في شخص بعينه.\n\nآخر تفسير سورة الكوثر","2":1,"3":1},"109":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ (١) لا أَعْبُدُ مَا تَعْبُدُونَ (٢) وَلا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ (٣) وَلا أَنَا عَابِدٌ مَا عَبَدْتُمْ (٤) وَلا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ (٥) لَكُمْ دِينُكُمْ وَلِيَ دِينِ (٦) ﴾ .\n\nيقول تعالى ذكره لنبيه محمد ﷺ، وكان المشركون من قومه فيما ذكر عرضوا عليه أن يعبدوا الله سنة، على أن يعبد نبيّ الله ﷺ آلهتهم سنة، فأنزل الله معرفه جوابهم في ذلك: ﴿قُلْ﴾ يا محمد لهؤلاء المشركين الذين سألوك عبادة آلهتهم سنة، على أن يعبدوا إلهك سنة ﴿يَاأَيُّهَا الْكَافِرُونَ﴾ بالله ﴿لا أَعْبُدُ مَا تَعْبُدُونَ﴾ من الآلهة والأوثان الآن ﴿وَلا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ﴾ الآن\n\n﴿وَلا أَنَا عَابِدٌ﴾ فيما أستقبل\n\n﴿مَا عَبَدْتُمْ﴾ فيما مضى ﴿وَلا أَنْتُمْ عَابِدُونَ﴾ فيما تستقبلون أبدا ﴿مَا أَعْبُدُ﴾ أنا الآن، وفيما أستقبل. وإنما قيل ذلك كذلك، لأن الخطاب من الله كان لرسول الله ﷺ في أشخاص بأعيانهم من المشركين، قد علم أنهم لا يؤمنون أبدا، وسبق لهم ذلك في السابق من علمه، فأمر نبيه ﷺ أن يؤيسهم من الذي طمعوا فيه، وحدّثوا به أنفسهم، وأن ذلك غير كائن منه ولا منهم، في وقت من الأوقات، وآيس نبي الله ﷺ من الطمع في إيمانهم، ومن أن يفلحوا أبدا، فكانوا كذلك لم يفلحوا ولم ينجحوا، إلى أن قتل بعضهم يوم بدر بالسيف، وهلك بعض قبل ذلك كافرا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل، وجاءت به الآثار.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن موسى الحَرشي، قال: ثنا أبو خلف، قال: ثنا داود، عن عكرِمة، عن ابن عباس: أن قريشا وعدوا رسول الله ﷺ أن يعطوه مالا فيكون أغنى رجل بمكة، ويزّوجوه ما أراد من النساء، ويطئوا عقبه، فقالوا له: هذا لك عندنا يا محمد، وكفّ عن شتم آلهتنا، فلا تذكرها بسوء، فإن لم تفعل، فإنا نعرض عليك خصلة واحدة، فهي لك ولنا فيها صلاح. قال: \"ما هي؟ \" قالوا: تعبد آلهتنا سنة: اللات والعزي، ونعبد إلهك سنة، قال: \"حتى أنْظُرَ ما يأْتي مِنْ عِنْدِ رَبّي\"، فجاء الوحي من اللوح المحفوظ: ﴿قُلْ يَاأَيُّهَا الْكَافِرُونَ﴾ السورة، وأنزل الله: ﴿قُلْ أَفَغَيْرَ اللَّهِ تَأْمُرُونِّي أَعْبُدُ أَيُّهَا الْجَاهِلُونَ﴾ ... إلى قوله: ﴿فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ﴾ .\n\n⁕ حدثني يعقوب، قال: ثنا ابن عُلَية، عن محمد بن إسحاق، قال: ثني سعيد بن مينا مولى البَختري  قال: لقي الوليد بن المُغيرة والعاص بن وائل، والأسود بن المطلب، وأميَّة بن خلف، رسول الله، فقالوا: يا محمد، هلمّ فلنعبد ما تعبد، وتعبدْ ما نعبد، ونُشركك في أمرنا كله، فإن كان الذي جئت به خيرا مما بأيدينا، كنا قد شَرِكناك فيه، وأخذنا بحظنا منه؛ وإن كان الذي بأيدينا خيرا مما في يديك، كنت قد شَرِكتنا في أمرنا، وأخذت منه بحظك، فأنزل الله: ﴿قُلْ يَاأَيُّهَا الْكَافِرُونَ﴾ حتى انقضت السورة.\n\n* *\n\nوقوله: ﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾\n\nيقول تعالى ذكره: لكم دينكم فلا تتركونه أبدا، لأنه قد ختم عليكم، وقضي أن لا تنفكوا عنه، وأنكم تموتون عليه، ولي دين الذي أنا عليه، لا أتركه أبدا، لأنه قد مضى في سابق علم الله أني لا أنتقل عنه إلى غيره.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قول الله: ﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾ قال: للمشركين؛ قال: واليهود لا يعبدون إلا الله ولا يشركون، إلا أنهم يكفرون ببعض الأنبياء، وبما جاءوا به من عند الله، ويكفرون برسول الله، وبما جاء به من عند الله، وقتلوا طوائف الأنبياء ظلما وعدوانا، قال: إلا العصابة التي بقوا، حتى خرج بختنصر، فقالوا: عُزَير ابن الله، دعا الله ولم يعبدوه ولم يفعلوا كما فعلت النصارى، قالوا: المسيح ابن الله وعبدوه.\n\nوكان بعض أهل العربية يقول: كرّر قوله: ﴿لا أَعْبُدُ مَا تَعْبُدُونَ﴾ وما بعده على وجه التوكيد، كما قال: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ ، وكقوله: ﴿لَتَرَوُنَّ الْجَحِيمَ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ﴾ .\n\nآخر تفسير سورة الكافرون","2":1,"3":1,"4":1,"5":1,"6":1},"110":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ (١) وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا (٢) فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا (٣) ﴾ .\n\nيقول تعالى ذكره لنبيه محمد ﷺ: إذا جاءك نصر الله يا محمد على قومك من قريش، والفتح: فتح مكة ﴿وَرَأَيْتَ النَّاسَ﴾ من صنوف العرب وقبائلها أهل اليمن منهم، وقبائل نزار ﴿يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا﴾ يقول: في دين الله الذي ابتعثك به، وطاعتك التي دعاهم إليها أفواجًا، يعني: زُمَرًا، فوجًا فوجًا.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ما قلنا في قوله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ :\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ : فتح مكة.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ النصر حين فتح الله عليه ونصره.\n\n⁕ حدثني إسماعيل بن موسى، قال: أخبرنا الحسين بن عيسى الحنفي، عن معمر، عن الزهري، عن أبي حازم، عن ابن عباس، قال: بينا رسول الله ﷺ بالمدينة، إذ قال: \"اللهُ أكْبَرُ، اللهُ أكْبَرُ، جاءَ نَصْرُ الله والفَتْحُ، جاءَ أهْلُ اليَمَنِ\"، قيل: يا رسول الله، وما أهل اليمن؟ قال: \"قَوْمٌ رَقِيقَةٌ قُلُوبُهُمْ، لَيِّنةٌ طِبَاعُهُمْ، الإيمَانُ يَمَانٍ، والفِقْهُ يَمَانٍ، والحِكْمَةُ يَمَانِيَةٌ\".\n\n⁕ حدثنا ابن المثنى، قال: ثني عبد الأعلى، قال: ثنا داود، عن عامر، عن مسروق، عن عائشة، قالت: كان رسول الله ﷺ يكثر من قول: سبحان الله وبحمده، وأستغفر الله وأتوب إليه؛ قالت: فقلت: يا رسول الله أراك تُكثر قول: سبحان الله وبحمده، وأستغفر الله وأتوب إليه، فقال: \"خَبَّرَنِي رَبِّي أنّي سأرَى عَلامَةً فِي أمَّتِي، فإذَا رَأَيْتُهَا أكْثَرْتُ مِنْ قَوْل سُبْحَانَ الله وبحَمْدِهِ، وأسْتَغْفِرُهُ وأتُوبُ إلَيْهِ، فَقَدْ رَأَيْتُها ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ فتح مكة ﴿وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا﴾ \".\n\n⁕ حدثنا ابن وكيع، قال: ثنا عبد الأعلى، قال: ثنا داود عن الشعبي، عن مسروق، عن عائشة، عن النبي ﷺ، بنحوه.\n\n⁕ حدثنا ابن المثنى، قال: ثنا عبد الوهاب، قال: ثنا داود، عن عامر، عن عائشة، قالت: كان نبي الله ﷺ يكثر قبل موته من قول سبحان الله وبحمده ثم ذكر نحوه.\n\n⁕ حدثني إسحاق بن شاهين، قال: ثنا خالد، عن داود، عن عامر، عن مسروق، عن عائشة، عن النبي ﷺ، بنحوه.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن عكرمة قال: لما نزلت: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قال النبيّ ﷺ: \"جَاءَ نَصْرُ الله والفَتْحُ، وَجَاءَ أهْلُ اليَمَنِ\"، قالوا: يا نبيّ الله، وما أهل اليمن؟ قال: \"رَقِيقَةٌ قُلُوبُهُمْ، لَيِّنَةٌ طِبَاعُهُمْ، الإيمَانُ يَمَانٍ، والْحِكْمَةُ يَمَانِيَةٌ\". وأما قوله؛ ﴿أَفْوَاجًا﴾ فقد تقدّم ذكره في معنى أقوال أهل التأويل.\n\n⁕ وقد حدثني الحارث، قال: ثنا بشر، قال: ثنا يزيد، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد ﴿فِي دِينِ اللَّهِ أَفْوَاجًا﴾ قال: زُمرًا زُمرًا.\n\n* *\n\nوقوله: ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ﴾\n\nيقول: فسبح ربك وعظمه بحمده وشكره، على ما أنجز لك من وعده. فإنك حينئذ لاحق به، وذائق ما ذاق مَنْ قبلك من رُسله من الموت.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن حبيب، عن سعيد بن جبير، عن ابن عباس، أن عمر بن الخطاب رضي الله عنه سألهم عن قول الله تعالى: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قالوا: فتح المدائن والقصور، قال: فأنت يا بن عباس ما تقول: قلت: مَثَلٌ ضُرب لمحمد ﷺ نعيت إليه نفسه.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي بشر، عن سعيد بن جُبير، عن ابن عباس، أن عمر بن الخطاب رضي الله عنه كان يُدنيه، فقال له عبد الرحمن: إن لنا أبناءً مثلَهُ، فقال عمر: إنه من حيث تعلم، قال: فسأله عمر عن قول الله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ السورة، فقال ابن عباس: أجله، أعلمه الله إياه، فقال عمر: ما أعلم منها إلا مثل ما تعلم.\n\n⁕ حدثنا ابن حُميد، قال: ثنا مهران، عن سفيان، عن عاصم، عن أبي رزين، عن ابن عباس، قال: قال عمر رضي الله عنه: ما هي؟ يعني ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قال ابن عباس، ﴿إِذَا جَاءَ نَصْرُ اللَّهِ﴾ حتى بلغ: ﴿وَاسْتَغْفِرْهُ﴾ إنك ميت ﴿إِنَّهُ كَانَ تَوَّابًا﴾ فقال عمر: ما نعلم منها إلا ما قلت.\n\n⁕ قال: ثنا مهران، عن سفيان عن عاصم، عن أبي رزين، عن ابن عباس قال: لما نزلت ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ علم النبيّ أنه نعيت إليه نفسه، فقيل له: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ... ﴾ إلى آخر السورة.\n\n⁕ حدثنا أبو كُرَيب وابن وكيع، قالا ثنا ابن فضيل، عن عطاء بن السائب، عن سعيد بن جبير، عن ابن عباس، قال: لما نزلت ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قال رسول الله ﷺ: \"نُعِيَتْ إليَّ نَفْسِي، كأنّي مَقْبُوضٌ فِي تِلكَ السَّنَةِ\".\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قال: ذاك حين نَعَى لَه نفسه يقول: إذا ﴿وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا﴾ يعني إسلام الناس، يقول: فذاك حين حضر أجلك ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا﴾ .\n\n⁕ حدثني أبو السائب وسعيد بن يحيى الأموي، قالا ثنا أبو معاوية، عن الأعمش، عن مسلم، عن مسروق، عن عائشة قالت كان رسول الله ﷺ يُكثر أن يقول قبل أن يموت: \"سبحانك اللهم وبحمدك، أستغفرك وأتوب إليك \"؛ قالت: فقلت: يا رسول الله ما هذه الكلمات التي أراك قد أحدثتها تقولها؟ قال: \"قد جعلت لي علامة في أمتي إذا رأيتها قلتها ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ إلى آخر السورة\".\n\n⁕ حدثني يحيى بن إبراهيم المسعودي، قال: ثني أبي، عن أبيه، عن جده، عن الأعمش، عن مسلم، عن مسروق، قال: قالت عائشة: ما سمعت رسول الله ﷺ منذ أنزلت عليه هذه السورة ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ لا يقول قبلها: سبحانك ربنا وبحمدك، اللهمّ اغفر لي\".\n\n⁕ حدثنا ابن وكيع، قال: ثنا ابن نمير، عن الأعمش، عن مسلم، عن مسروق، عن عائشة، عن النبيّ ﷺ، مثله.\n\n⁕ حدثنا ابن وكيع، قال: ثنا جرير، عن منصور، عن أبي الضحى، عن مسروق، عن عائشة قالت: كان رسول الله ﷺ يُكثر أن يقول في ركوعه وسجوده: \" سبحانك اللهم وبحمدك، اللهمّ اغفر لي\"، يتأول القرآن.\n\n⁕ حدثني يعقوب بن إبراهيم، قال: ثنا ابن عُلَية، عن داود، عن الشعبي، قال داود: لا أعلمه إلا عن مسروق، وربما قال عن مسروق، عن عائشة قالت: كان رسول الله ﷺ يُكثر أن يقول: \"سبحان الله وبحمده، أستغفر الله وأتوب إليه\"، فقلت: إنك تُكثر من هذا، فقال: \"إنَّ رَبي قَدْ أخْبَرَنِي أنِّي سأرَى عَلامةً في أُمَّتِي، وأَمَرَنِي إذَا رأَيْتُ تِلكَ الْعَلامَةَ أنْ أُسَبِّحَ بِحَمْدِهِ، وأسْتَغْفِرَهُ إنَّهُ كَانَ تَوَّابا، فَقَدْ رأَيْتُها ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ \".\n\n⁕ حدثنا أبو السائب، قال: ثنا حفص، قال: ثنا عاصم، عن الشعبي، عن أم سلمة، قالت: كان رسول الله ﷺ في آخر أمره لا يقوم ولا يقعد، ولا يذهب ولا يجيء إلا قال: \"سبحان الله وبحمده\"، فقلت: يا رسول الله، إنك تكثر من سبحان الله وبحمده، لا تذهب ولا تجيء، ولا تقوم ولا تقعد إلا قلت: سبحان الله وبحمده، قال: \"إني أمرت بها\"، فقال: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ إلى آخر السورة.\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، قال: ثنا ابن إسحاق، عن بعض أصحابه، عن عطاء بن يسار، قال: نزلت سورة ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ كلها بالمدينة بعد فتح مكة، ودخولها الناس في الدين، ينعي إليه نفسه.\n\n⁕ قال: ثنا جرير، عن مُغيرة، عن زياد بن الحصين، عن أبي العالية، قال: لما نزلت: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ ونعيت إلى النبيّ ﷺ نفسه، كان لا يقوم من مجلس يجلس فيه حتى يقول: \"سبحانك اللهمّ وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك\".\n\n⁕ قال: ثنا الحكم بن بشير، قال: ثنا عمرو، قال: لما نزلت: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ كان النبيّ ﷺ مما يكثر أن يقول: \"سبحانك اللهم وبحمدك، رب اغفر لي وتب عليّ، إنك أنت التوّاب الرحيم\".\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ قرأها كلها. قال ابن عباس: هذه السورة عَلَمٌ وحَدٌّ حدّه الله لنبيه ﷺ، ونعى له نفسه. إي إنك لن تعيش بعدها إلا قليلا. قال قتادة: والله ما عاش، بعد ذلك إلا قليلا سنتين، ثم توفي ﷺ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي معاذ عيسى بن أبي يزيد، عن أبي إسحاق، عن أبي عبيدة، عن ابن مسعود، قال: لما نزلت: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ كان يكثر أن يقول: \"سبحانك اللهمّ وبحمدك، اللهمّ اغفر لي، سبحانك ربنا وبحمدك، اللهمّ اغفر لي، إنك أنت التواب الغفور\".\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قول الله: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾ : كانت هذه السورة آية لموت رسول الله ﷺ.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا﴾ قال: اعلم أنك ستموت عند ذلك.\n\n* *\n\nوقوله: ﴿وَاسْتَغْفِرْهُ﴾\n\nيقول: وسله أن يغفر ذنوبك.\n\nيقول: إنه كان ذا رجوع لعبده، المطيع إلى ما يحب. والهاء من قوله \"إنه\" من ذكر الله عز وجلّ.\n\nآخر تفسير سورة النصر","2":1,"3":1},"111":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ (١) مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ (٢) سَيَصْلَى نَارًا ذَاتَ لَهَبٍ (٣) وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ (٤) فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ (٥) ﴾ .\n\nيقول تعالى ذكره: خسرت يدا أبي لهب، وخسر هو. وإنما عُنِي بقوله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ تبّ عمله. وكان بعض أهل العربية يقول: قوله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ : دعاء عليه من الله.\n\nوأما قوله: ﴿وَتَبَّ﴾ فإنه خبر. ويُذكر أن ذلك في قراءة عبد الله: \"تَبَّتْ يَدَا أبِي لَهَبٍ وَقَدْ تَبَّ\". وفي دخول \"قد\" فيه دلالة على أنه خبر، ويمثِّل ذلك بقول القائل، لآخر: أهلكك الله، وقد أهلكك، وجعلك صالحا وقد جعلك.\n\nوبنحو الذي قلنا في معنى قوله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ : أي خسرت وتب.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾ قال: التبّ: الخسران، قال: قال أبو لهب للنبيّ ﷺ: ماذا أُعطَى يا محمد إن آمنت بك؟ قال؟ \"كمَا يُعْطَى المُسْلِمُون\"، فقال: مالي عليهم فضل؟ قال: \"وأيّ شَيْءٍ تَبْتَغِي؟ \" قال: تبا لهذا من دين تبا، أن أكون أنا وهؤلاء سواء، فأنزل الله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ يقول: بما عملت أيديهم.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة (تَبَّتْ يَدَا أَبِي لَهَبٍ) قال: خسرت يدا أبي لهب وخسر.\n\nوقيل: إن هذه السورة نزلت في أبي لهب، لأن النبي ﷺ لما خص بالدعوة عشيرته، إذ نزل عليه: ﴿وَأَنْذِرْ عَشِيرَتَكَ الأقْرَبِينَ﴾ وجمعهم للدعاء، قال له أبو لهب: تبا لك سائر اليوم، ألهذا دعوتنا؟\n\nذكر الأخبار الواردة بذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا أبو معاوية، عن الأعمش، عن عمرو، عن سعيد بن جبير، عن ابن عباس قال: صعد رسول الله ﷺ ذات يوم الصفا، فقال: \"يا صَباحاهُ! \" فاجتمعت إليه قريش، فقالوا: مالك؟ قال: \"أرأيْتُكُمْ إنْ أخْبَرْتُكُمْ أنَّ العَدُوَّ مُصَبِّحُكُمْ أوْ مُمَسِّيكُمْ، أما كُنْتُمْ تُصَدقُونَنِي؟ \" قالوا: بلى، قال: \"فإني نَذِيرٌ لَكُمْ بَينَ يَدَيْ عَذَابٍ شَدِيدٍ\"، فقال أبو لهب: تبا لك، ألهذا دعوتنا وجمعتنا؟! فأنزل الله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ إلى آخرها.\n\n⁕ حدثني أبو السائب، قال: ثنا أبو معاوية، عن الأعمش، عن عمرو، عن سعيد بن جبير، عن ابن عباس، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن نمير، عن الأعمش، عن عمرو بن مرة، عن سعيد بن جبير، عن ابن عباس، قال: لما نزلت ﴿وَأَنْذِرْ عَشِيرَتَكَ الأقْرَبِينَ﴾ قام رسول الله ﷺ على الصَّفا ثم نادَى: \"يا صَبحاهُ\" فاجتمع الناس إليه، فبين رجل يجيء، وبين آخر يبعث رسوله، فقال: \"يا بَنِي هاشِمٍ، يا بَنِي عَبْدِ المُطَّلِبِ، يا بَنِي فِهْرٍ، يا بَنِي ... يا بَنِي أرَأَيْتُكُمْ لَوْ أخْبَرْتُكُمْ أنَّ خَيْلا بِسَفْحِ هَذَا الجَبَلِ\" -يريد تغير عليكم- صَدَّقْتُمُونِي؟ \" قالوا: نعم، قال: \"فإني نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ\"، فقال أبو لهب: تبا لك سائر اليوم، ألهذا دعوتنا؟ فنزلت: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾ \".\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا أبو أسامة، عن الأعمش، عن عمرو بن مرة، عن سعيد بن جبير، عن ابن عباس قال: لما نزلت هذه الآية: ﴿وَأَنْذِرْ عَشِيرَتَكَ الأقْرَبِينَ﴾ ورهطك منهم المخلصين، خرج رسول الله ﷺ، حتى صعد الصفا، فهتف: \"يا صَباحاهُ\". فقالوا: من هذا الذي يهتف؟ فقالوا: محمد، فاجتمعوا إليه، فقال: \"يا بَنِي فُلانٍ، يا بَنِي فُلانٍ، يا بَنِي عَبْدِ المُطَّلِبِ، يا بَنِي عَبْدِ مَنَافٍ\"، فاجتمعوا إليه، فقال: \"أرَأَيْتُكُمْ لَوْ أَخْبَرْتُكُمْ أنَّ خَيْلا تَخْرُجُ بِسَفْحِ هَذَا الجَبَلِ أكُنْتُمْ مُصَدِّقِيَّ؟ \" قالوا: ما جربنا عليك كذبا، قال \"فإنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ\"، فقال أبو لهب: تبا لك ما جمعتنا إلا لهذا؟ ثم قام فنزلت هذه السورة: \"تَبَّتْ يَدَا أبِي لَهَبٍ وَقَدْ تَبَّ\" كذا قرا الأعمش إلى آخر السورة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، في قوله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ قال: حين أرسل النبي ﷺ إليه وإلى غيره، وكان أبو لهب عمّ النبيّ ﷺ، وكان اسمه عبد العزى، فذكرهم، فقال أبو لهب: تبا لك، في هذا أرسلت إلينا؟ فأنزل الله: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ .\n\n* *\n\nوقوله: ﴿مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ﴾\n\nيقول تعالى ذكره: أيّ شيء أغنى عنه ماله، ودفع من سخط الله عليه ﴿وَمَا كَسَبَ﴾ وهم ولده. وبالذي قلنا في ذلك قال أهل التأويل\n\nذكر من قال ذلك:\n\n⁕ حدثنا الحسن بن داود بن محمد بن المنكدر، قال: ثنا عبد الرزاق، عن معمر، عن ابن خيثم، عن أبي الطفيل، قال: جاء بنو أبي لهب إلى ابن عباس، فقاموا يختصمون في البيت، فقام ابن عباس، فحجز بينهم، وقد كُفّ بصره، فدفعه بعضهم حتى وقع على الفراش، فغضب وقال: أخرجوا عني الكسب الخبيث.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي بكر الهذلي، عن محمد بن سفيان، عن رجل من بني مخزوم، عن ابن عباس أنه رأى يوما ولد أبي لهب يقتتلون، فجعل يحجز بينهم ويقول: هؤلاء مما كسب.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ليث، عن مجاهد ﴿مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ﴾ قال: ما كسب ولده.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قول الله: ﴿وَمَا كَسَبَ﴾ قال: ولده هم من كسبه.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبي نجيح، عن مجاهد، في قول الله ﴿وَمَا كَسَبَ﴾ قال: ولده.\n\n* *\n\nوقوله: ﴿سَيَصْلَى نَارًا ذَاتَ لَهَبٍ﴾\n\nيقول: سيصلى أبو لهب نارا ذات لهب.\n\n* *\n\nوقوله: ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾\n\nيقول: سيصلى أبو لهب وامرأته حمالة الحطب، نارا ذات لهب. واختلفت القرّاء في قراءة ﴿حَمَّالَةَ الْحَطَبِ﴾ فقرأ ذلك عامة قرّاء المدينة والكوفة والبصرة: \"حَمَّالَةُ الحَطَبِ\" بالرفع، غير عبد الله بن أبي إسحاق، فإنه قرأ ذلك نصبا فيما ذكر لنا عنه.\n\nواختلف فيه عن عاصم، فحكي عنه الرفع فيها والنصب، وكأن من رفع ذلك جعله من نعت المرأة، وجعل الرفع للمرأة ما تقدم من الخبر، وهو \"سَيَصْلَى\"، وقد يجوز أن يكون رافعها الصفة، وذلك قوله: ﴿فِي جِيدِهَا﴾ وتكون \"حَمَّالَة\" نعتا للمرأة. وأما النصب فيه فعلى الذم، وقد يحتمل أن يكون نصبها على القطع من المرأة، لأن المرأة معرفة، وحمالة الحطب نكرة  .\n\nوالصواب من القراءة في ذلك عندنا: الرفع، لأنه أفصح الكلامين فيه، ولإجماع الحجة من القرّاء عليه.\n\nواختلف أهل التأويل، في معنى قوله: ﴿حَمَّالَةَ الْحَطَبِ﴾ فقال بعضهم: كانت تجيء بالشوك فتطرحه في طريق رسول الله ﷺ، ليدخل في قدمه إذا خرج إلى الصلاة.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله: ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تحمل الشوك، فتطرحه على طريق النبي ﷺ، ليعقره وأصحابه، ويقال: ﴿حَمَّالَةَ الْحَطَبِ﴾ : نقالة للحديث.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن إسرائيل، عن أبي إسحاق، عن رجل من همدان يقال له يزيد بن زيد، أن امرأة أبي لهب كانت تلقي في طريق النبيّ ﷺ الشوك، فنزلت: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ ... وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ .\n\n⁕ حدثني أبو هريرة الضبعي، محمد بن فراس، قال: ثنا أبو عامر، عن قرة بن خالد، عن عطية الجدلِّي. في قوله: ﴿حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تضع العضاه على طريق رسول الله ﷺ، فكأنما يطأ به كثيبا.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول، في قوله: ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ كانت تحمل الشوك، فتلقيه على طريق نبي الله ﷺ ليعقِره.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تأتي بأغصان الشوك، فتطرحها بالليل في طريق رسول الله ﷺ.\n\nوقال آخرون: قيل لها ذلك: حمالة الحطب، لأنها كانت تحطب الكلام، وتمشي بالنميمة، وتعير رسول الله ﷺ بالفقر.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا المعتمر بن سليمان، قال: قال أبو المعتمر: زعم محمد أن عكرمة قال ﴿حَمَّالَةَ الْحَطَبِ﴾ : كانت تمشي بالنميمة.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن ابن أبي نجيح، عن مجاهد: ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تمشي بالنميمة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا الأشجعي، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد، مثله.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿حَمَّالَةَ الْحَطَبِ﴾ قال: النميمة.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ : أي كانت تنقل الأحاديث من بعض الناس إلى بعض.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تحطب الكلام، وتمشي بالنميمة.\n\nوقال بعضهم: كانت تعير رسول الله ﷺ بالفقر، وكانت تحطب فعُيِّرتْ بأنها كانت تحطب.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ قال: كانت تمشي بالنميمة.\n\nوأولى القولين في ذلك بالصواب عندي، قول من قال: كانت تحمل الشوك، فتطرحه في طريق رسول الله ﷺ، لأن ذلك هو أظهر معنى ذلك.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن عيسى بن يزيد، عن ابن إسحاق، عن يزيد بن زيد، وكان ألزم شيءٍ لمسروق، قال: لما نزلت: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ﴾ بلغ امرأة أبي لهب أن النبي ﷺ يهجوك، قالت: علام يهجوني؟ هل رأيتموني كما قال محمد أحمل حطبا؟ \" ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ \"؟ فمكثت، ثم أتته، فقالت: إن ربك قلاك وودعك، فأنزل الله: ﴿وَالضُّحَى وَاللَّيْلِ إِذَا سَجَى مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ .\n\n* *\n\nوقوله ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾\n\nيقول في عنقها؛ والعرب تسمي العنق جيدا ؛ ومنه قول ذي الرمة:\n\nفعَيْنَاكِ عَيْناها وَلَوْنُكِ لَوْنُها ... وجِيدُكِ إلا أنَّهَا غَيْرُ عَاطِلِ\n\nوبالذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿فِي جِيدِهَا حَبْلٌ﴾ قال: في رقبتها.\n\n* *\n\nوقوله: ﴿حَبْلٌ مِنْ مَسَدٍ﴾\n\nاختلف أهل التأويل في ذلك، فقال بعضهم: هي حبال تكون بمكة.\n\nذكر من قال ذلك:\n\n⁕ حدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: حبل من شجر، وهو الحبل الذي كانت تحتطب به.\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس ﴿حَبْلٌ مِنْ مَسَدٍ﴾ قال: هي حبال تكون بمكة؛ ويقال: المَسَد: العصا التي تكون في البكرة، ويقال المَسَد: قلادة من وَدَع.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد: في قوله: ﴿حَبْلٌ مِنْ مَسَدٍ﴾ قال: حبال من شجر تنبت في اليمن لها مسد، وكانت تفتل؛ وقال ﴿حَبْلٌ مِنْ مَسَدٍ﴾ : حبل من نار في رقبتها.\n\nوقال آخرون: المسد: الليف.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن السدي، عن يزيد، عن عروة ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: سلسلة من حديد، ذرعها سبعون ذراعا.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السدي، عن رجل يقال له يزيد، عن عروة بن الزبير ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: سلسلة ذرعها سبعون ذراعا.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن يزيد، عن عروة بن الزبير ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: سلسلة ذرعها سبعون ذراعا.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبيه، عن الأعمش، عن مجاهد ﴿مِنْ مَسَدٍ﴾ قال: من حديد.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: حبل في عنقها في النار مثل طوق طوله سبعون ذراعا.\n\nوقال آخرون: المَسَد: الحديد الذي يكون في البَكرة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن منصور، عن مجاهد ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: الحديدة تكون في البكرة.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد ﴿حَبْلٌ مِنْ مَسَدٍ﴾ قال: عود البكرة من حديد.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد ﴿حَبْلٌ مِنْ مَسَدٍ﴾ قال: الحديدة للبكرة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: ثنا المعمر بن سليمان، قال: قال أبو المعتمر: زعم محمد أن عكرمة قال: ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ إنه الحديدة التي في وسط البكرة.\n\nوقال آخرون: هو قلادة من ودع في عنقها.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ﴾ قال: قلادة من ودع.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿حَبْلٌ مِنْ مَسَدٍ﴾ قال: قلادة من ودع.\n\nوأولى الأقوال في ذلك عندي بالصواب، قول من قال: هو حبل جُمع من أنواع مختلفة، ولذلك اختلف أهل التأويل في تأويله على النحو الذي ذكرنا، ومما يدلّ على صحة ما قلنا في ذلك قول الراجز:\n\nوَمَسَدٍ أُمِرَّ مِنْ أيانِقِ ... صُهْبٍ عِتاقٍ ذاتِ مُخ زَاهِق\n\nفجعل إمراره من شتى، وكذلك المسد الذي في جيد امرأة أبي لهب، أمِرَّ من أشياء شتى، من ليف وحديد ولحاء، وجعل في عنقها طوقا كالقلادة من ودع؛ ومنه قول الأعشى:\n\nتُمْسِي فَيَصْرِفُ بَابَها مِنْ دُونِنَا ... غَلْقًا صَرِيفَ مَحَالَةَ الأمْسَادِ\n\nيعني بالأمساد: جمع مَسَد، وهي الجبال.\n\nآخر تفسير سورة تبت","2":1,"3":1,"4":1,"5":1},"112":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ (١) اللَّهُ الصَّمَدُ (٢) لَمْ يَلِدْ وَلَمْ يُولَدْ (٣) وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ (٤) ﴾ .\n\nذُكر أن المشركين سألوا رسول الله ﷺ عن نسب ربّ العزّة، فأنزل الله هذه السورة جوابا لهم. وقال بعضهم: بل نزلت من أجل أن اليهود سألوه، فقالوا له: هذا الله خلق الخلق، فمن خلق الله؟ فأُنزلت جوابا لهم.\n\nذكر من قال: أنزلت جوابا للمشركين الذين سألوه أن ينسب لهم الربّ تبارك وتعالى.\n\n⁕ حدثنا أحمد بن منيع المَرْوَزِي ومحمود بن خداش الطالَقاني، قالا ثنا أبو سعيد الصنعاني، قال: ثنا أبو جعفر الرازي، عن الربيع بن أنس، عن أبي العالية، عن أبي بن كعب، قال: قال المشركون للنبيّ ﷺ: انسُب لنا ربك، فأنزل الله: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا يحيى بن واضح، قال: ثنا الحسين، عن يزيد، عن عكرمة، قال: إن المشركين قالوا: يا رسول الله أخبرنا عن ربك، صف لنا ربك ما هو، ومن أي شيء هو؟ فأنزل الله: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ إلى آخر السورة.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ﴾ قال: قال ذلك قتادة الأحزاب: انسُب لنا ربك، فأتاه جبريل بهذه.\n\n⁕ حدثني محمد بن عوف، قال: ثنا شريح، قال: ثنا إسماعيل بن مجالد، عن مجالد، عن الشعبي، عن جابر قال: قال المشركون: انسُب لنا ربك، فأنزل الله ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ .\n\nذكر من قال: نزل ذلك من أجل مسألة اليهود:\n\n⁕ حدثنا ابن حميد، قال: ثنا سلمة، قال: ثني ابن إسحاق، عن محمد، عن سعيد، قال: أتى رهط من اليهود النبي ﷺ، فقالوا: يا محمد هذا الله خلق الخلق، فمن خلقه؟ فغضب النبيّ ﷺ حتى انتُقِع لونه، ثم ساورهم غضبا لربه، فجاءه جبريل عليه السلام فسكنه، وقال: اخفض عليك جناحك يا محمد، وجاءه من الله جواب ما سألوه عنه. قال: \" يقول الله: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ \" فلما تلا عليهم النبي ﷺ، قالوا: صف لنا ربك كيف خلقه، وكيف عضده، وكيف ذراعه، فغضب النبيّ ﷺ أشدّ من غضبه الأول، وساورهم غضبا، فأتاه جبريل فقال له مثل مقالته، وأتاه بجواب ما سألوه عنه: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالأرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّماوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سعيد بن أبي عروبة، عن قتادة، قال: جاء ناس من اليهود إلى النبي ﷺ، فقالوا: أنسب لنا ربك، فنزلت: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ حتى ختم السورة.\n\nفتأويل الكلام إذا كان الأمر على ما وصفنا: قل يا محمد لهؤلاء السائليك عن نسب ربك وصفته، ومَن خَلقه: الربّ الذي سألتموني عنه، هو الله الذي له عبادة كل شيء، لا تنبغي العبادة إلا له، ولا تصلح لشيء سواه.\n\nواختلف أهل العربية في الرافع ﴿أَحَدٌ﴾ فقال بعضهم: الرافع له \" الله\"، وهو عماد  بمنزلة الهاء في قوله: ﴿إِنَّهُ أَنَا اللَّهُ الْعَزِيزُ الْحَكِيمُ﴾ . وقال آخر منهم: بل هو مرفوع، وإن كان نكرة بالاستئناف، كقوله: هذا بعلي شيخ، وقال: هو الله جواب لكلام قوم قالوا له: ما الذي تعبد؟ فقال: \"هو الله\"، ثم قيل له: فما هو؟ قال: هو أحد.\n\nوقال آخرون ﴿أَحَدٌ﴾ بمعنى: واحد، وأنكر أن يكون العماد مستأنفا به، حتى يكون قبله حرف من حروف الشكّ، كظنّ وأخواتها، وكان وذواتها، أو إنّ وما أشبهها، وهذا القول الثاني هو أشبه بمذاهب العربية.\n\nواختلفت القرّاء في قراءة ذلك، فقرأته عامة قرّاء الأمصار ﴿أَحَدٌ اللَّهُ الصَّمَدُ﴾ بتنوين \" أحدٌ \"، سوى نصر بن عاصم، وعبد الله بن أبي إسحاق، فإنه رُوي عنهما ترك التنوين: \" أحَدُ اللهُ \"؛ وكأن من قرأ ذلك كذلك، قال: نون الإعراب إذا استقبلتها الألف واللام أو ساكن من الحروف حذفت أحيانا، كما قال الشاعر:\n\nكَيْفَ نَوْمي على الفِرَاشِ وَلَمَّا ... تَشْمَلِ الشَّامَ غَارَةٌ شَعْوَاءُ\n\nتُذْهِلُ الشَّيْخَ عَنْ بَنِيهِ وَتُبْدِي ... عَنْ خِدَامِ العَقِيلَةِ العَذْراءُ\n\nيريد: عن خدام العقيلة.\n\nوالصواب في ذلك عندنا: التنوين، لمعنيين: أحدهما أفصح اللغتين، وأشهر الكلامين، وأجودهما عند العرب. والثاني: إجماع الحجة من قرّاء الأمصار على اختيار التنوين فيه، ففي ذلك مُكْتَفًى عن الاستشهاد على صحته بغيره. وقد بيَّنا معنى قوله \" أحد \" فيما مضى، بما أغنى عن إعادته في هذا الموضع.\n\n* *\n\nوقوله: ﴿اللَّهُ الصَّمَدُ﴾\n\nيقول تعالى ذكره: المعبود الذي لا تصلح العبادة إلا له الصمد.\n\nواختلف أهل التأويل في معنى الصمد، فقال بعضهم: هو الذي ليس بأجوف، ولا يأكل ولا يشرب.\n\nذكر من قال ذلك:\n\n⁕ حدثنا عبد الرحمن بن الأسود، قال: ثنا محمد بن ربيعة، عن سلمة بن سابور، عن عطية، عن ابن عباس، قال: ﴿الصمد﴾ : الذي ليس بأجوف.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن منصور، عن مجاهد، قال: ﴿الصمد﴾ : المُصْمَت الذي لا جوف له.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن منصور، عن مجاهد، مثلَه سواء.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، قال: ﴿الصمد﴾ : المصمت الذي ليس له جوف.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن ووكيع، قالا ثنا سفيان، عن ابن أبي نجيح، عن مجاهد، قال ﴿: الصَّمَد﴾ : الذي لا جوف له.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع؛ وحدثنا ابن حميد، قال: ثنا مهران جميعا، عن سفيان، عن ابن أبي نجيح، عن مجاهد، مثلَه.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا الربيع بن مسلم، عن الحسن، قال: ﴿الصمد﴾ : الذي لا جوف له.\n\n⁕ قال: ثنا الربيع بن مسلم، عن إبراهيم بن ميسرة، قال: أرسلني مجاهد إلى سعيد بن جبير أساله عن ﴿الصمد﴾ ، فقال: الذي لا جوف له.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى، قال: ثنا إسماعيل بن أبي خالد، عن الشعبي، قال: ﴿الصمد﴾ الذي لا يطعم الطعام.\n\n⁕ حدثنا يعقوب، قال: ثنا هشيم، عن إسماعيل بن أبي خالد، عن الشعبي أنه قال: ﴿الصمد﴾ : الذي لا يأكل الطعام، ولا يشرب الشراب.\n\n⁕ حدثنا أبو كُرَيب وابن بشار، قالا ثنا وكيع، عن سلمة بن نبيط، عن الضحاك، قال: ﴿الصمد﴾ : الذي لا جوف له.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن أبي زائدة، عن إسماعيل، عن عامر، قال: ﴿الصمد﴾ : الذي لا يأكل الطعام.\n\n⁕ حدثنا ابن بشار وزيد بن أخزم، قالا ثنا ابن داود، عن المستقيم بن عبد الملك، عن سعيد بن المسيب قال: ﴿الصمد﴾ : الذي لا حِشوة له.\n\n⁕ حُدثت عن الحسين، قال: سمعت أبا معاذ يقول: ثنا عبيد، قال: سمعت الضحاك يقول في قوله: ﴿الصمدُ﴾ : الذي لا جوف له.\n\n⁕ حدثني العباس بن أبي طالب، قال: ثنا محمد بن عمر بن رومي، عن عبيد الله بن سعيد قائد الأعمش، قال: ثني صالح بن حيان، عن عبد الله بن بريدة، عن أبيه، قال: لا أعلمه إلا قد رفعه، قال: ﴿الصَّمَد﴾ الذي لا جوف له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا بشر بن المفضل، عن الربيع بن مسلم، قال: سمعت الحسن يقول: ﴿الصَّمَد﴾ : الذي لا جوف له.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن عكرمة، قال: ﴿الصمد﴾ : الذي لا جوف له.\n\nوقال آخرون: هو الذي لا يخرج منه شيء.\n\nذكر من قال ذلك:\n\n⁕ حدثني يعقوب، قال: ثنا ابن علية، عن أبي رجاء قال: سمعت عكرمة، قال في قوله: ﴿الصمد﴾ : الذي لم يخرج منه شيء، ولم يلد، ولم يولد.\n\n⁕ حدثنا ابن بشار، قال: ثنا محمد بن جعفر، قال: ثنا شعبة، عن أبي رجاء محمد بن يوسف، عن عكرمة قال: ﴿الصمد﴾ : الذي لا يخرج منه شيء.\n\nوقال آخرون: هو الذي لم يَلِد ولم يُولَد.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية، قال: ﴿الصمد﴾ : الذي لم يلد ولم يولد، لأنه ليس شيء يلد إلا سيورث، ولا شيء يولد إلا سيموت، فأخبرهم تعالى ذكره أنه لا يورث ولا يموت.\n\n⁕ حدثنا أحمد بن منيع ومحمود بن خداش قالا ثنا أبو سعيد الصنعاني، قال: قال المشركون للنبي ﷺ أنسب لنا ربك فأنزل الله: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ لأنه ليس شيء يولد إلا سيموت، وليس شيء يموت إلا سيورث، وإن الله جلّ ثناؤه لا يموت ولا يورث ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ : ولم يكن لَه شبيه ولا عِدل، وليس كمثله شيء.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن أبي معشر، عن محمد بن كعب: الصمد: الذي لم يلد ولم يولد، ولم يكن له كفوا أحد.\n\nوقال آخرون: قدانتهى سُؤدده.\n\nذكر من قال ذلك:\n\n⁕ حدثني أبو السائب، قال: ثني أبو معاوية، عن الأعمش، عن شقيق، قال: الصمد: هو السيد الذي قد انتهى سؤدده.\n\n⁕ حدثنا أبو كُرَيب وابن بشار وابن عبد الأعلى، قالوا: ثنا وكيع، عن الأعمش، عن أبي وائل، قال: ﴿الصَّمَد﴾ : السيد الذي قد انتهى سؤدده؛ ولم يقل أبو كُرَيب وابن عبد الأعلى سؤدده.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن الأعمش، عن أبي وائل مثله.\n\n⁕ حدثنا علي، قال: ثنا أبو صالح، قال: ثني معاوية، عن علي، عن ابن عباس، في قوله: ﴿الصَّمَدُ﴾ يقول: السيد الذي قد كمُل في سُؤدَده، والشريف الذي قد كمل في شرفه، والعظيم الذي قد عظم في عظمته، والحليم الذي قد كمل في حلمه، والغني الذي قد كمل في غناه، والجبَّار الذي قد كمل في جبروته، والعالم الذي قد كمل في علمه، والحكيم الذي قد كمل في حكمته، وهو الذي قد كمل في أنواع الشرف والسؤدد، وهو الله سبحانه هذه صفته، لا تنبغي إلا له.\n\nوقال آخرون: بل هو الباقي الذي لا يفنَى.\n\nذكر من قال ذلك:\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، في قوله: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ﴾ قال: كان الحسن وقتادة يقولان: الباقي بعد خلقه، قال: هذه سورة خالصة، ليس فيها ذكر شيء من أمر الدنيا والآخرة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: ﴿الصمد﴾ : الدائم.\n\nقال أبو جعفر: الصمد عند العرب: هو السيد الذي يُصمد إليه، الذي لا أحد فوقه، وكذلك تسمى أشرافها؛ ومنه قول الشاعر:\n\nألا بَكَرَ النَّاعي بِخَيْرَيْ بَنِي أسَدْ ... بِعَمْرِو بْنِ مَسْعُودٍ وبالسَّيِّدِ الصَّمَدْ\n\nوقال الزبرقان:\n\nوَلا رَهِينَةً إلا سَيِّدٌ صَمَدُ\n\nفإذا كان ذلك كذلك، فالذي هو أولى بتأويل الكلمة، المعنى المعروف من كلام من نزل القرآن بلسانه؛ ولو كان حديث ابن بُريدة، عن أبيه صحيحا، كان أولى الأقوال بالصحة، لأن رسول الله ﷺ أعلم بما عنى الله جل ثناؤه، وبما أنزل عليه.\n\n* *\n\nوقوله: ﴿لَمْ يَلِدْ﴾\n\nيقول: ليس بفانٍ، لأنه لا شيء يلد إلا هو فانٍ بائد\n\n﴿وَلَمْ يُولَدْ﴾ يقول: وليس بمحدث لم يكن فكان، لأن كل مولود فإنما وجد بعد أن لم يكن، وحدث بعد أن كان غير موجود، ولكنه تعالى ذكره قديم لم يزل، ودائم لم يبد، ولا يزول ولا يفنى.\n\n* *\n\nوقوله: ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾\n\nاختلف أهل التأويل في معنى ذلك، فقال بعضهم: معنى ذلك: ولم يكن له شبيه ولا مِثْل.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن أبي جعفر، عن الربيع، عن أبي العالية قوله: ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ : لم يكن له شبيه، ولا عِدْل، وليس كمثله شيء.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن عمرو بن غيلان الثقفي، وكان أميرَ البصرة  عن كعب، قال: إن الله تعالى ذكره أسس السموات السبع، والأرضين السبع، على هذه السورة ﴿لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ وإن الله لم يكافئه أحد من خلقه.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ قال: ليس كمثله شيء، فسبحان الله الواحد القهار.\n\n⁕ حدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، عن ابن جريج ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا﴾ : مثل.\n\nوقال آخرون: معنى ذلك، أنه لم يكن له صاحبة.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن عبد الملك بن أبجر، عن طلحة، عن مجاهد، قوله: ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ قال: صاحبة.\n\n⁕ حدثنا ابن بشار، قال: ثنا يحيى، عن سفيان، عن ابن أيجر، عن طلحة، عن مجاهد، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا ابن إدريس، عن عبد الملك، عن طلحة، عن مجاهد، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن ابن أبجر، عن رجل عن مجاهد ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ قال: صاحبة.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن سفيان، عن عبد الملك بن أبجر، عن طلحة بن مصرف، عن مجاهد ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾ قال: صاحبة.\n\n⁕ حدثنا أبو السائب، قال: ثنا ابن إدريس، عن عبد الملك، عن طلحة، عن مجاهد مثله.\n\nوالكُفُؤُ والكُفَى والكِفَاء في كلام العرب واحد، وهو المِثْل والشِّبْه؛ ومنه قول نابغة بني ذُبيان:\n\nلا تَقْذِفَنِّي بِرُكْن لا كِفَاء لَهُ ... وَلَوْ تَأَثَّفَكَ الأعْدَاءُ بالرِّفَدِ\n\nيعني: لا كِفَاء له: لا مثل له.\n\nواختلف القرّاء في قراءة قوله: ﴿كُفُوا﴾ . فقرأ ذلك عامة قرّاء البصرة: ﴿كُفُوا﴾ بضم الكاف والفاء. وقرأه بعض قرّاء الكوفة بتسكين الفاء وهمزها \" كُفْئًا \".\n\nوالصواب من القول في ذلك: أن يقال: إنهما قراءتان معروفتان، ولغتان مشهورتان، فبأيَّتِهِما قرأ القارئ فمصيب.\n\nآخر تفسير سورة الإخلاص","2":1,"3":1,"4":1},"113":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ (١) مِنْ شَرِّ مَا خَلَقَ (٢) وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ (٣) وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ (٤) وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ (٥) ﴾ .\n\nيقول تعالى ذكره لنبيه محمد ﷺ: قل يا محمد، أستجير بربّ الفلق من شرّ ما خلق من الخلق.\n\nواختلف أهل التأويل في معنى ﴿الفلق﴾ فقال بعضهم: هو سجن في جهنم يسمى هذا الاسم.\n\nذكر من قال ذلك:\n\n⁕ حدثني الحسين بن يزيد الطحان، قال: ثنا عبد السلام بن حرب، عن إسحاق بن عبد الله، عمن حدثه عن ابن عباس قال: ﴿الفلق﴾ : سجن في جهنم.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو أحمد الزبيري، قال: ثنا عبد السلام بن حرب، عن إسحاق بن عبد الله بن أبي فروة، عن رجل، عن ابن عباس، في قوله: ﴿الفَلَقِ﴾ : سجن في جهنم.\n\n⁕ حدثني يعقوب، قال: ثنا هشيم، قال: أخبرنا العوّام بن عبد الجبار الجولاني، قال: قَدم رجل من أصحاب رسول الله ﷺ الشأم، قال: فنظر إلى دور أهل الذمة، وما هم فيه من العيش والنضارة، وما وُسِّع عليهم في دنياهم، قال: فقال: لا أبا لك أليس من ورائهم الفلق؟ قال: قيل: وما الفلق؟ قال: بيت في جهنم إذ فُتح هَرّ أهْلُ النار.\n\n⁕ حدثنا ابن بشار، قال: ثنا عبد الرحمن، قال: ثنا سفيان، قال: سمعت السديّ يقول: ﴿الفَلَق﴾ : جُب في جهنم.\n\n⁕ حدثني عليّ بن حسن الأزدي، قال: ثنا الأشجعيّ، عن سفيان، عن السديّ، مثله.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن السديّ، مثله.\n\n⁕ حدثني إسحاق بن وهب الواسطيُّ، قال: ثنا مسعود بن موسى بن مشكان الواسطيُّ، قال: ثنا نصر بن خُزَيمة الخراساني، عن شعيب بن صفوان، عن محمد بن كعب القُرَظِيِّ، عن أبي هُريرة، عن النبيّ ﷺ قال: \"الفَلَق: جبّ في جهنم مغطًّى\".\n\n⁕ حدثنا ابن البرقي، قال: ثنا ابن أبي مريم، قال: ثنا نافع بن يزيد، قال: ثنا يحيى بن أبي أسيد عن ابن عجلان، عن أبي عبيد، عن كعب، أنه دخل كنيسة فأعجبه حُسنها، فقال: أحسن عمل وأضلّ قوم، رضيت لكم الفلق، قيل: وما الفلق؟ قال: بيت في جهنم إذا فُتح صاح جميع أهل النار من شدّة حرّه.\n\nوقال آخرون: هو اسم من أسماء جهنم.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: سمعت خيثم بن عبد الله يقول: سألت أبا عبد الرحمن الحبلي، عن ﴿الفلق﴾ ، قال: هي جهنم.\n\nوقال آخرون: الفلق: الصبح.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿أَعُوذُ بِرَبِّ الْفَلَقِ﴾ قال: ﴿الفلق﴾ : الصبح.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، قال: أنبأنا عوف، عن الحسن، في هذه الآية ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ قال: ﴿الفلق﴾ : الصبح.\n\n⁕ قال: ثنا عبد الرحمن، قال: ثنا سفيان، عن سالم الأفطس، عن سعيد بن جُبير، قال: ﴿الفلق﴾ : الصبح.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع؛ وحدثنا ابن حميد، قال: ثنا مهران جميعا، عن سفيان، عن سالم الأفطس، عن سعيد بن جُبير، مثله.\n\n⁕ حدثني عليّ بن الحسن الأزدي، قال: ثنا الأشجعيّ، عن سفيان، عن سالم، عن سعيد بن جُبير، مثله.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع، عن الحسن بن صالح، عن عبد الله بن محمد بن عقيل، عن جابر، قال: ﴿الفَلَق﴾ : الصبح.\n\n⁕ حدثنا ابن بشار، قال: ثنا أبو أحمد، قال: ثنا الحسن بن صالح، عن عبد الله بن محمد بن عقيل، عن جابر بن عبد الله، مثله.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، أخبرنا أبو صخر، عن القُرَظِيّ أنه كان يقول في هذه الآية: ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ يقول: فالق الحبّ والنوى، قال: فالق الإصباح.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا، عن ابن أبي نجيح، عن مجاهد، في قوله: ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ قال: الصبح.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ قال: ﴿الفَلَق﴾ : فَلق النهار.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة، قال: ﴿الفلق﴾ : فلق الصبح.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قول الله: ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ قيل له: فلق الصبح؟ قال: نعم، وقرأ: ﴿فَالِقُ الإصْبَاحِ وَجَعَلَ اللَّيْلَ سَكَنًا﴾ .\n\nوقال آخرون: ﴿الفلَق﴾ : الخلق، ومعنى الكلام: قل أعوذ بربّ الخلق.\n\nذكر من قال ذلك:\n\n⁕ حدثني عليّ، قال: لنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، في قوله: ﴿الفلق﴾ : يعني: الخلق.\n\nوالصواب من القول في ذلك أن يقال: إن الله جلّ ثناؤه أمر نبيه محمدًا ﷺ أن يقول: ﴿أَعُوذُ بِرَبِّ الْفَلَقِ﴾ والفلق في كلام العرب: فلق الصبح، تقول العرب: هو أبين من فَلَق الصُّبح، ومن فرق الصبح. وجائز أن يكون في جهنم سجن اسمه فَلَق. وإذا كان ذلك كذلك، ولم يكن جلّ ثناؤه وضعَ دلالة على أنه عُنِي بقوله: ﴿بِرَبِّ الْفَلَقِ﴾ بعض ما يُدْعَى الفلق دون بعض، وكان الله تعالى ذكره ربّ كل ما خلق من شيء، وجب أن يكون معنيا به كل ما اسمه الفَلَق، إذ كان ربّ جميع ذلك.\n\nوقال جلّ ثناؤه: ﴿مِنْ شَرِّ مَا خَلَقَ﴾ لأنه أمر نبيه أن يستعيذ ﴿من شرّ كل شيء﴾ ، إذ كان كلّ ما سواه، فهو ما خَلَق.\n\n* *\n\nوقوله: ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾\n\nيقول: ومن شرّ مظلم إذا دخل، وهجم علينا بظلامه.\n\nثم اختلف أهل التأويل في المظلم الذي عُنِي في هذه الآية، وأمر رسول الله ﷺ بالاستعاذة منه، فقال بعضهم: هو الليل إذا أظلم.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس: ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: الليل.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، قال: أنبأنا عوف، عن الحسن، في قوله: ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: أوّل الليل إذا أظلم.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: ثنا أبو صخر، عن القرظي أنه كان يقول في: ﴿غَاسِقٍ إِذَا وَقَبَ﴾ يقول: النهار إذا دخل في الليل.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن رجل من أهل المدينة، عن محمد بن كعب ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: هو غروب الشمس إذا جاء الليل، إذا وقب.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، قوله: ﴿غَاسِقٍ﴾ قال: الليل ﴿إِذَا وَقَبَ﴾ قال: إذا دخل.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن الحسن ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: الليل إذا أقبل.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، عن الحسن ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: إذا جاء.\n\n⁕ حدثني عليّ، قال: ثنا أبو صالح، قال: ثني معاوية، عن عليّ، عن ابن عباس، قوله ﴿إِذَا وَقَبَ﴾ يقول: إذا أقبل. وقال بعضهم: هو النهار إذا دخل في الليل، وقد ذكرناه قبلُ.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن رجل من أهل المدينة، عن محمد بن كعب القُرَظِيّ ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: هو غروب الشمس إذا جاء الليل، إذا وجب.\n\nوقال آخرون: هو كوكب. وكان بعضهم يقول: ذلك الكوكب هو الثُّريا.\n\nذكر من قال ذلك:\n\n⁕ حدثنا مجاهد بن موسى، قال: ثنا يزيد، قال: أخبرنا سليمان بن حِبان، عن أبي المُهَزِّم، عن أبي هريرة في قوله: ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: كوكب.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: كانت العرب تقول: الغاسق: سقوط الثريا، وكانت الأسقام والطواعين تكثر عند وقوعها وترتفع عند طلوعها.\n\nولقائلي هذا القول عِلة من أثر عن النبيّ ﷺ. وهو ما:-\n\n⁕ حدثنا به نصر بن عليّ، قال: ثنا بكار بن عبد الله بن أخي همام، قال: ثنا محمد بن عبد العزيز بن عمر بن عبد الرحمن بن عوف، عن أبيه، عن أبي سلمة، عن أبي هريرة، عن النبيّ ﷺ ﴿وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ﴾ قال: \" النجم الغاسق \".\n\nوقال آخرون: بل الغاسق إذا وقب: القمر، ورووا بذلك عن النبيّ ﷺ خبرا.\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا وكيع؛ وحدثنا ابن سفيان، قال: ثنا أبي ويزيد بن هارون، به.\n\n⁕ وحدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن محمد بن عبد الرحمن بن أبي ذئب، عن خاله الحارث بن عبد الرحمن، عن أبي سلمة بن عبد الرحمن، عن عائشة قالت: أخذ النبيّ ﷺ بيدي، ثم نظر إلى القمر، ثم قال: \"يا عائِشَةُ تَعَوَّذِي باللهِ مِنْ شَرِّ غَاسِقٍ إذَا وَقَب، وَهَذَا غاسِقٌ إذَا وَقَبَ\"، وهذا لفظ حديث أبي كُرَيب، وابن وكيع. وأما ابن حُمَيد، فإنه قال في حديثه: قالت: أخَذَ النبيّ ﷺ بيدي، فقال: \" أتَدْرِينَ أيَّ شَيءٍ هَذَا؟ تَعَوَّذِي باللهِ مِنْ شَرِّ هَذَا؛ فإنَّ هَذَا الْغاسِقُ إذَا وَقَبَ\".\n\n⁕ حدثنا محمد بن سنان، قال: ثنا أبو عامر، قال: ثنا ابن أبي ذئب، عن الحارث بن عبد الرحمن، عن عائشة، عن النبيّ ﷺ نظر إلى القمر. فقال: \"يا عائِشَةُ اسْتَعِيذِي باللهِ مِنْ شَرِّ هَذَا، فإنَّ هَذَا الْغاسِقُ إذَا وَقَبَ\".\n\nوأولى الأقوال في ذلك عندي بالصواب، أن يقال: إن الله أمر نبيه ﷺ أن يستعيذ ﴿وَمِنْ شَرِّ غَاسِقٍ﴾ وهو الذي يُظْلم، يقال: قد غَسَق الليل يَغُسْق غسوقا: إذا أظلم ﴿إِذَا وَقَبَ﴾ يعني: إذا دخل في ظلامه؛ والليل إذا دخل في ظلامه غاسق، والنجم إذا أفل غاسق، والقمر غاسق إذا وقب، ولم يخصص بعض ذلك بل عمّ الأمر بذلك، فكلّ غاسق، فإنه ﷺ كان يُؤمر بالاستعاذة من شره إذا وقب. وكان يقول في معنى وقب: ذهب.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿غَاسِقٍ إِذَا وَقَبَ﴾ قال: إذا ذهب، ولست أعرف ما قال قتادة في ذلك في كلام العرب، بل المعروف من كلامها من معنى وقب: دخل.\n\n* *\n\nوقوله: ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ﴾\n\nيقول: ومن شرّ السواحر الّلاتي ينفُثن في عُقَد الخيط، حين يَرْقِين عليها.\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس  ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ﴾ قال: ما خالط السِّحر من الرُّقَي.\n\n⁕ حدثنا ابن بشار، قال: ثنا ابن أبي عديّ، عن عوف، عن الحسن ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ﴾ قال: السواحر والسَّحرَة.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، قال: تلا قتادة: (وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ) قال: إياكم وما خالط السِّحر من هذه الرُّقَى.\n\n⁕ قال: ثنا ابن ثور، عن معمر، عن ابن طاوس، عن أبيه، قال: ما من شيء أقرب إلى الشرك من رُقْية المجانين.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة، قال: كان الحسن يقول إذا جاز ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ﴾ قال: إياكم وما خالط السحر.\n\n⁕ حدثنا ابن حميد، قال: ثنا مهران، عن سفيان، عن جابر، عن مجاهد وعكرِمة ﴿النَّفَّاثَاتِ فِي الْعُقَدِ﴾ قال: قال مجاهد: الرُّقَى في عقد الخيط، وقال عكرِمة: الأخذ في عقد الخيط.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ﴾ قال: النفاثات: السواحر في العقد.\n\n* *\n\nوقوله: ﴿وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾\n\nاختلف أهل التأويل في الحاسد الذي أمر النبيّ ﷺ أن يستعيذ من شرّ حسده به، فقال بعضهم: ذلك كلّ حاسد أمر النبيّ ﷺ أن يستعيذ من شرّ عينه ونفسه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ قال: من شرّ عينه ونفسه، وعن عطاء الخراساني مثل ذلك. قال معمر: وسمعت ابن طاوس يحدّث عن أبيه، قال: العَينُ حَقٌّ، وَلَو كانَ شَيءٌ سابق القَدرِ، سَبَقَتْهُ العَينُ، وإذا اسْتُغْسِل  أحدكم فَلْيَغْتَسِل.\n\nوقال آخرون: بل أمر النبيّ ﷺ بهذه الآية أن يستعيذ من شرّ اليهود الذين حسدوه.\n\nذكر من قال ذلك:\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ قال: يهود، لم يمنعهم أن يؤمنوا به إلا حسدهم.\n\nوأولى القولين بالصواب في ذلك، قول من قال: أمر النبيّ ﷺ أن يستعيذ من شرّ كلّ حاسد إذا حسد، فعابه أو سحره، أو بغاه سوءًا.\n\nوإنما قلنا: ذلك أولى بالصواب؛ لأن الله عزّ وجلّ لم يخصص من قوله ﴿وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ حاسدا دون حاسد، بل عمّ أمره إياه بالاستعاذة من شرّ كلّ حاسد، فذلك على عمومه.\n\nآخر تفسير سورة الفلق","2":1,"3":1,"4":1,"5":1},"114":{"1":"القول في تأويل قوله جل ثناؤه وتقدست أسماؤه: ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ (١) مَلِكِ النَّاسِ (٢) إِلَهِ النَّاسِ (٣) مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ (٤) الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ (٥) مِنَ الْجِنَّةِ وَالنَّاسِ (٦) ﴾ .\n\nيقول تعالى ذكره لنبيه محمد ﷺ: قل يا محمد أستجير ﴿بِرَبِّ النَّاسِ مَلِكِ النَّاسِ﴾ وهو ملك جميع الخلق: إنسهم وجنهم، وغير ذلك، إعلاما منه بذلك من كان يعظم الناس تعظيم المؤمنين ربهم أنه ملك من يعظمه، وأن ذلك في مُلكه وسلطانه، تجري عليه قُدرته، وأنه أولى بالتعظيم، وأحقّ بالتعبد له ممن يعظمه، ويُتعبد له، من غيره من الناس.\n\n* *\n\nوقوله: ﴿إِلَهِ النَّاسِ﴾\n\nيقول: معبود الناس، الذي له العبادة دون كل شيء سواه.\n\n* *\n\nوقوله: ﴿مِنْ شَرِّ الْوَسْوَاسِ﴾\n\nيعني: من شرّ الشيطان ﴿الْخَنَّاسِ﴾ الذي يخنِس مرّة ويوسوس أخرى، وإنما يخنِس فيما ذُكر عند ذكر العبد ربه.\n\nذكر من قال ذلك:\n\n⁕ حدثنا أبو كُرَيب، قال: ثنا يحيى بن عيسى، عن سفيان، عن حكيم بن جُبير، عن سعيد بن جبير، عن ابن عباس، قال: ما من مولود إلا على قلبه الوَسواس، فإذا عقل فذكر الله خَنَس، وإذا غَفَل وسوس، قال: فذلك قوله: ﴿الْوَسْوَاسِ الْخَنَّاسِ﴾ .\n\n⁕ حدثنا ابن حميد، قال: ثنا جرير، عن منصور، عن سفيان، عن ابن عباس، في قوله ﴿الْوَسْوَاسِ الْخَنَّاسِ﴾ قال: الشيطان جاثم على قلب ابن آدم، فإذا سها وغفل وسوس، وإذا ذكر الله خنس.\n\n⁕ قال: ثنا مهران، عن عثمان بن الأسود، عن مجاهد ﴿الْوَسْوَاسِ الْخَنَّاسِ﴾ قال: ينبسط فإذا ذكر الله خَنَس وانقبض، فإذا غفل انبسط.\n\n⁕ حدثني محمد بن عمرو، قال: ثنا أبو عاصم، قال: ثنا عيسى؛ وحدثني الحارث، قال: ثنا الحسن، قال ثنا ورقاء، جميعا عن ابن أبي نجيح، عن مجاهد، في قوله ﴿الْوَسْوَاسِ الْخَنَّاسِ﴾ قال: الشيطان يكون على قلب الإنسان، فإذا ذكر الله خَنَس.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن معمر، عن قتادة ﴿الْوَسْوَاسِ﴾ قال: قال هو الشيطان، وهو الخَنَّاس أيضا، إذا ذكر العبد ربه خنس، وهو يوسوس وَيخْنِس.\n\n⁕ حدثنا بشر، قال: ثنا يزيد، قال: ثنا سعيد، عن قتادة ﴿مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ﴾ يعني: الشيطان، يوسوس في صدر ابن آدم، ويخنس إذا ذُكر الله.\n\n⁕ حدثنا ابن عبد الأعلى، قال: ثنا ابن ثور، عن أبيه، قال: ذُكر لي أن الشيطان، أو قال الوسواس، ينفث في قلب الإنسان عند الحزن وعند الفرح، وإذا ذُكر الله خنس.\n\n⁕ حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد، في قوله: ﴿الْخَنَّاسِ﴾ قال: الخناس الذي يوسوس مرّة، ويخنس مرّة من الجنّ والإنس، وكان يقال: شيطان الإنس أشدّ على الناس من شيطان الجنّ، شيطان الجنّ يوسوس ولا تراه، وهذا يُعاينك معاينة.\n\nورُوي عن ابن عباس رضى الله عنه أنه كان يقول في ذلك ﴿مِنْ شَرِّ الْوَسْوَاسِ﴾ الذي يوسوس بالدعاء إلى طاعته في صدور الناس، حتى يُستجاب له إلى ما دعا إليه من طاعته، فإذا استجيب له إلى ذلك خَنَس.\n\nذكر من قال ذلك:\n\n⁕ حدثني محمد بن سعد، قال: ثني أبي، قال: ثني عمي، قال: ثني أبي، عن أبيه، عن ابن عباس، في قوله ﴿الْوَسْوَاسِ﴾ قال: هو الشيطان يأمره، فإذا أطيع خنس.\n\nوالصواب من القول في ذلك عندي أن يقال: إن الله أمر نبيه محمدا ﷺ أن يستعيذ به من شرّ شيطان يوسوس مرّة ويخنس أخرى، ولم يخصَّ وسوسته على نوع من أنواعها، ولا خنوسه على وجه دون وجه، وقد يوسوس بالدعاء إلى معصية الله، فإذا أطيع فيها خَنَس، وقد يوسوس بالنَّهْي عن طاعة الله فإذا ذكر العبدُ أمر ربه فأطاعه فيه، وعصى الشيطان خنس، فهو في كلّ حالتيه وَسْواس خَناس، وهذه الصفة صفته.\n\n* *\n\nوقوله: ﴿الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ﴾\n\nيعني بذلك: الشيطان الوسواس، الذي يوسوس في صدور الناس: جنهم وإنسهم.\n\nفإن قال قائل: فالجنّ ناس، فيقال: الذي يوسوس في صدور الناس من الجنة والناس. قيل: قد سماهم الله في هذا الموضع ناسا، كما سماهم في موضع آخر رجالا فقال: ﴿وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ﴾ فجعل الجنّ رجالا وكذلك جعل منهم ناسا.\n\nوقد ذُكر عن بعض العرب أنه قال وهو يحدّث، إذ جاء قوم من الجنّ فوقفوا، فقيل: من أنتم؟ فقالوا: ناس من الجنّ، فجعل منهم ناسا، فكذلك ما في التنزيل من ذلك.\n\nآخر كتاب التفسير، والحمد لله العلي الكبير.","2":1,"3":1,"4":1,"5":1,"6":1}};
